var EXPLAIN = {
"1": {"point": "「踏切」は訓読みで「ふみきり」。動詞「踏み切る」の連用形が名詞になった語で、「踏」は連用形の「ふみ」、「切」は連濁せず「きり」と読む。", "meaning": "鉄道の線路と道路が同じ高さで交差している所。", "kr": "건널목", "opts": ["ふむきり：「踏む」の終止形の形。名詞は連用形「ふみ」から作るので誤り", "", "ふむぎり：「ふむ」も「ぎり」も誤り", "ふみぎり：「切」は連濁せず「きり」"], "ex": "電車が近づいて、<b>踏切</b>の警報機が鳴り始めた。"},
"2": {"point": "「緩い」は「ゆるい」。締め方が足りず、すき間やゆとりがある様子。「緩む（ゆるむ）」「緩める（ゆるめる）」と同じ読み。音読みは「カン」（緩和）。", "meaning": "締まり方が足りず、ゆとりがありすぎる様子。", "kr": "느슨하다, 헐겁다", "opts": ["もろい＝脆い（壊れやすい）。「緩」の読みではない", "かたい＝固い・硬い。「緩」の読みではない", "きつい：締まりすぎている様子で、「緩い」とは反対の意味", ""], "ex": "ベルトが<b>緩く</b>なったので、穴を一つずらした。"},
"3": {"point": "「姿勢」は音読みで「しせい」。「姿（シ）」「勢（セイ）」とも清音。「せー」と長く発音される音も、仮名では「せい」と書く（先生＝せんせい）。", "meaning": "体の構え。また、物事に取り組む態度・心構え。", "kr": "자세", "opts": ["", "しぜい：「勢」は濁らない（「大勢＝おおぜい」のように濁る語もあるが、「姿勢」は「せい」）", "しせえ：発音は「せー」と聞こえるが、仮名で書くと「しせい」", "しぜえ：濁音も表記も誤り"], "ex": "長時間パソコンを使うときは、<b>姿勢</b>に気をつけたほうがいい。"},
"4": {"point": "「慎重」は「しんちょう」。「慎（シン）」は「慎む（つつしむ）」の音読み。「重」はここでは「チョウ」と読む（貴重・尊重と同じ）。", "meaning": "注意深く、軽々しく行動しないこと。", "kr": "신중", "opts": ["ちんちょう：「慎」はチンと読まない（「珍重＝珍しいものとして大切にする」は別の語）", "", "ちんじゅう：「慎」も「重」も読みが違う（「珍獣＝珍しい動物」は別の語）", "しんじゅう：「重」をジュウと読む誤り（「心中」は別の語）"], "ex": "大切な契約なので、<b>慎重</b>に検討してから決めたい。"},
"5": {"point": "「懐く」は訓読みで「なつく」。動物や子どもが人に慣れて親しむこと。「懐かしい（なつかしい）」と同じ「なつ」。音読みは「カイ」（懐中）、ほかの訓読みに「ふところ」がある。", "meaning": "人に慣れて、親しみを持ってそばに寄ってくる。", "kr": "따르다, 길들다", "opts": ["まごついて＝まごつく（どうしてよいかわからず迷う）。ふつう仮名で書く語", "なげいて＝嘆いて（悲しんで、ため息をつく）", "そむいて＝背いて（逆らう・従わない）。意味はほぼ反対", ""], "ex": "引っ越してきた子猫が、ようやく家族に<b>懐いて</b>きた。"},
"6": {"point": "「既に」は「すでに」。「もう・それより前に」という意味の副詞。音読みは「キ」（既婚・既存）。", "meaning": "もう。その時より前に。", "kr": "이미, 벌써", "opts": ["さらに＝更に（その上、もっと）", "いかに＝如何に（どれほど・どのように）", "", "いやに（妙に、ひどく）。「既」の読みではない"], "ex": "駅に着いたときには、最終電車は<b>既に</b>出てしまっていた。"},
"7": {"point": "「思惑が外れる」は、前もって考えていた見込みや期待のとおりにならないこと。「〜が外れて残念そう」とあるので、見込み・期待の意味の「思惑」が合う。", "meaning": "前もって考えていた見込み・期待。", "kr": "생각, 예상, 의도", "opts": ["魂胆＝心の中に隠したたくらみ（「何か魂胆がある」）。悪い意味が強く、「外れる」とは結びつかない", "下心＝表に出さない、よくないたくらみ。「下心が外れる」とは言わない", "本音＝本当の気持ち。「外れる」ものではない", ""], "ex": "雨で客が来ず、店の<b>思惑</b>は大きく外れた。"},
"8": {"point": "「てっきり〜と思っていた」は、確かにそうだと思い込んでいたが実際は違った、という言い方。後ろに「思っていた」があるので「てっきり」。", "meaning": "（後に「〜と思った」が続いて）きっとそうだと思い込んでいた様子。", "kr": "당연히 ~인 줄 (알았다)", "opts": ["めっきり＝変化がはっきり感じられる様子（「めっきり寒くなった」）", "", "こってり＝味や色が濃い様子（「こってりしたラーメン」）", "きっかり＝数量や時間がちょうど（「きっかり3時」）"], "ex": "<b>てっきり</b>休みだと思っていたら、店は開いていた。"},
"9": {"point": "「目標に向かって突き進む」は、困難をものともせず、まっすぐ勢いよく進むこと。努力を続ける様子をよい意味で表す。", "meaning": "勢いよく、まっすぐに進んでいく。", "kr": "돌진하다, 매진하다", "opts": ["", "突き飛ばして＝突き飛ばす（人などを強く突いて倒す）。対象が必要で、ここでは使えない", "突き落として＝突き落とす（突いて高い所から落とす）。対象が必要", "突っ走って＝突っ走る（勢いよく走る）。比喩では「周りを見ずに強引に進める」という響きがあり、目標に向かって努力する様子には「突き進む」が自然"], "ex": "彼女は夢に向かってひたすら<b>突き進んで</b>いる。"},
"10": {"point": "「〜に抗議する」は、相手の行為や決定に反対の意見を強く申し立てること。住民が建設に反対し工事が止まったので「抗議」。", "meaning": "相手の言動や決定に対して、反対の意見を強く申し立てること。", "kr": "항의", "opts": ["反論＝相手の意見や主張に、反対の論を述べること。意見に対して使い、「建設」のような行為には使いにくい", "", "口論＝言い争い。「〜に口論する」とは言わない", "反逆＝国や権力に背いて逆らうこと。住民の反対には大げさ"], "ex": "選手たちは審判の判定に強く<b>抗議</b>した。"},
"11": {"point": "「体力が衰える」は、年齢などで力が弱くなること。「衰えてきた」で、少しずつ弱くなってきた変化を表す。", "meaning": "勢いや力が弱くなる。", "kr": "쇠약해지다, 약해지다", "opts": ["さびて＝錆びる（金属がさびる）。体力には使わない", "やつれて＝やつれる（病気や心配で、顔や体が痩せ衰える）。見た目の変化で、「体力が」には合わない", "", "にぶって＝鈍る（「腕・勘・決心が鈍る」）。「体力が鈍る」とは普通言わない"], "ex": "年をとって、記憶力が<b>衰えて</b>きた。"},
"12": {"point": "「壮大な計画・プロジェクト」は、規模が大きく立派な様子。新社長が大規模な計画を発表する文脈に合う。", "meaning": "規模が大きく立派な様子。", "kr": "웅장한, 장대한", "opts": ["", "豪壮な＝建物などが大きく堂々としている様子（「豪壮な邸宅」）。計画には使わない", "広壮な＝建物が広く立派な様子（「広壮な屋敷」）。計画には使わない", "壮厳な：正しくは「荘厳（そうごん）」と書き、重々しく尊い様子。計画には使わない"], "ex": "宇宙の歴史を描いた<b>壮大な</b>物語に心を打たれた。"},
"13": {"point": "「ローテーションを組む」は、何人かが順番に交代して仕事をする計画を作ること。5人の医師が交代で24時間対応している。", "meaning": "順番に交代すること。交代の順番。", "kr": "교대, 로테이션", "opts": ["セクション＝部門・区分", "ロケーション＝場所・立地。撮影の現地", "ポジション＝地位・持ち場", ""], "ex": "店員は週ごとの<b>ローテーション</b>で休みを取っている。"},
"14": {"point": "「濁る」は訓読みで「にごる」。水などが透き通らなくなること。音読みは「ダク」（濁音・濁流）。", "meaning": "液体や空気に混ざり物があって、透明でなくなる。", "kr": "탁해지다, 흐려지다", "opts": ["", "くもって＝曇って（空が雲で覆われる・ガラスがぼんやりする）。水には「濁る」を使う", "どもって＝吃って（言葉がつかえて、すらすら出ない）", "たまって＝溜まって（水などが一か所に集まる）"], "ex": "雨の後は、川の水が茶色く<b>濁る</b>。"},
"15": {"point": "「怪しい」は「あやしい」。正体がわからず疑わしい様子。音読みは「カイ」（怪物・怪談）。", "meaning": "正体がわからず疑わしい。普通と違っていて気味が悪い。", "kr": "수상하다", "opts": ["めずらしい＝珍しい（めったにない）", "いやしい＝卑しい（品がない・下品だ）", "", "たくましい＝逞しい（体や心が強い）"], "ex": "夜中に家の前を<b>怪しい</b>人がうろうろしていた。"},
"16": {"point": "「納得」は「なっとく」。「納」は普通「ノウ」（納入）だが、この語では「ナッ」と読み、「得（トク）」が続く。", "meaning": "他人の考えや物事の理由をよく理解して、受け入れること。", "kr": "납득", "opts": ["のうどく：「納」も「得」も読みが違う", "のうとく：「納」を「ノウ」と読む誤り。この語では「なっ」", "なっどく：「得」は濁らず「とく」", ""], "ex": "説明を聞いて、ようやく<b>納得</b>がいった。"},
"17": {"point": "「厳か」は訓読みで「おごそか」。重々しく、近寄りがたい雰囲気。音読みは「ゲン・ゴン」（厳重・荘厳）、ほかの訓読みに「きびしい」がある。", "meaning": "重々しく、身が引き締まるような様子。", "kr": "엄숙하다", "opts": ["", "はなやか＝華やか（明るく派手で美しい）", "おろそか＝疎か（いいかげんにする様子）。「おごそか」と音が似ているので注意", "しとやか＝淑やか（動作や話し方が上品で落ち着いている）"], "ex": "神社では新年の儀式が<b>厳か</b>に行われた。"},
"18": {"point": "「解除」は「かいじょ」。「解（カイ）」＋「除（ジョ）」。「除」は「削除（さくじょ）・掃除（そうじ）」のように「ジョ・ジ」と読み、「ショ」とは読まない。", "meaning": "制限・禁止・契約などを取りやめて、元の状態に戻すこと。", "kr": "해제", "opts": ["かいしょ：「除」を清音で読む誤り。正しくは「じょ」", "", "げしょ：「解」をゲと読むのは「解熱（げねつ）・解毒（げどく）」など一部の語だけ。「除」も清音で誤り", "げじょ：「解」をゲと読む誤り。この語は「かい」"], "ex": "台風が過ぎ去り、大雨警報が<b>解除</b>された。"},
"19": {"point": "「設ける」は訓読みで「もうける」。機会・場所・規則などを新しく作って用意すること。音読みは「セツ」（設置・設備）。「儲ける（もうける＝利益を得る）」とは同じ読みの別の語。", "meaning": "物事を行うための場所・機会・制度などを新たに用意する。", "kr": "마련하다, 설치하다", "opts": ["しつける＝躾ける（礼儀作法を教え込む）", "", "しかける＝仕掛ける（相手に働きかける・装置を取り付ける）", "さずける＝授ける（目上の者が与える）"], "ex": "会社は社員の意見を聞く場を<b>設けた</b>。"},
"20": {"point": "「大人になるために必要なプロセス」は、成長の途中で通る過程という意味。反抗期を成長の一段階として受け止める文脈に合う。", "meaning": "物事が進む道筋。過程。", "kr": "과정, 프로세스", "opts": ["アレンジ＝配置・手配。曲の編曲", "", "タイミング＝ちょうどよい時機", "セクション＝部門・区分"], "ex": "結果だけでなく、そこに至る<b>プロセス</b>も大切だ。"},
"21": {"point": "動詞の連用形＋「込む」で、その動作に熱中して長く続ける意味になる（話し込む・考え込む・眠り込む）。友人と思わず1時間も話した、という文脈に合う。", "meaning": "（動詞の連用形について）熱中して長く〜する。", "kr": "(오래) 열중해서 ~하다", "opts": ["通して＝〜通す（最後まで続けてやり抜く。「歩き通す」）。「つい〜てしまった」という無意識の様子に合わない", "詰めて＝〜詰める（「思い詰める・問い詰める」）。「話し詰める」とは普通言わない", "かけて＝話しかける（相手に声をかける）。1時間続いた様子は表せない", ""], "ex": "難しい問題に、彼はじっと考え<b>込んで</b>いる。"},
"22": {"point": "「利益を社会へ還元する」は、得た利益を、それを生んだ社会や客に返して役立てること。決まった言い方。", "meaning": "得た利益などを、元の所（社会・客など）に返すこと。", "kr": "환원", "opts": ["", "返還＝借りた物・取り上げた物を元の持ち主に返すこと（「領土の返還」）。寄付や支援の意味はない", "募金＝寄付金を集めること（または募金に応じて寄付すること）。利益を社会に返す意味はない", "譲渡＝権利や財産を他人に譲り渡すこと。法律的な語で文脈に合わない"], "ex": "売り上げの一部は、地域の子どもたちに<b>還元</b>されている。"},
"23": {"point": "「養う」は、生活に必要なものを与えて世話をし、生活させること。兄が進学をあきらめて弟や妹の生活を支えた、という文脈に合う。", "meaning": "生活の面倒を見る。扶養する。", "kr": "부양하다, 먹여 살리다", "opts": ["", "稼いで＝稼ぐ（働いてお金を得る）。対象はお金で、「私たちを稼ぐ」とは言わない", "施して＝施す（恵みとして与える）。「人を施す」とは言わない", "労わって＝労わる（いたわる：弱い者を大切に扱う）。気づかいの意味で、生活を支える意味はない"], "ex": "彼は一人で働いて、家族四人を<b>養って</b>いる。"},
"24": {"point": "「あっけない」は、予想よりも簡単に終わってしまい、物足りない様子。振り返りもしない短い別れの様子に合う。", "meaning": "予想外に簡単で、物足りない。", "kr": "허무하다, 싱겁다", "opts": ["だらしない＝きちんとしていない・しまりがない。服装や生活の様子に使い、別れの様子には合わない", "なにげない＝特別な考えや意図がない様子（「なにげない一言」）。すぐに終わってしまった別れの物足りなさは表せない", "", "きりがない＝終わりがない・限りがない。すぐに終わった別れとは意味が反対"], "ex": "優勝候補のチームが一回戦で<b>あっけなく</b>負けた。"},
"25": {"point": "「守備が手薄だ」は、守る人数や備えが足りない様子。後ろの「攻撃すればすぐに点が奪える」と合う。", "meaning": "人手や備えが少なくて、十分でないこと。", "kr": "허술함, 손이 부족함", "opts": ["軽薄＝考えや言動が軽々しく、誠実さがないこと。人の性格に使う", "", "強固＝しっかりしていて揺るがない。点が取りやすいという文脈と反対", "頑丈＝作りがしっかりしていて壊れにくい。文脈と反対"], "ex": "夜間は警備が<b>手薄</b>になるので注意が必要だ。"},
"26": {"point": "「心配りができる」は、相手のことを考えてあれこれ気を配れること。人の長所としてほめる言い方。", "meaning": "相手のために、あれこれと気を配ること。", "kr": "배려, 마음 씀씀이", "opts": ["心当たり＝思い当たること（「心当たりがある」）", "気負い＝張り切りすぎる気持ち。「気負いができる」とは言わない", "", "気心＝その人の性質や考え方（「気心が知れた仲」）"], "ex": "客一人ひとりへの細やかな<b>心配り</b>が、この旅館の魅力だ。"},
"27": {"point": "「慌てる」は「あわてる」。急なことに落ち着きを失い、急いで行動すること。音読みは「コウ」（恐慌）。", "meaning": "驚いたり急いだりして、落ち着きを失う。", "kr": "당황하다, 허둥대다", "opts": ["あれてて：「慌」は「あわ」と読み、「あれ」とは読まない", "", "かれてて：「慌」の読みではない", "かわてて：「慌」の読みではない（「か」ではなく「あ」）"], "ex": "地震のときは<b>慌てず</b>、まず身の安全を確保しよう。"},
"28": {"point": "「道端」は訓読み＋訓読みで「みちばた」。「端（はた）」が連濁して「ばた」になる（井戸端＝いどばた、川端＝かわばた）。", "meaning": "道のすぐそば。道のへり。", "kr": "길가", "opts": ["", "みちはじ：「端」は「はし・はた」と読むが、「はじ」とは読まない", "どうたん：「道端」を音読みで読むことはない", "どうてん：「端」をテンとは読まない（「動転」は別の語）"], "ex": "<b>道端</b>に自転車を止めないでください。"},
"29": {"point": "「破裂」は「はれつ」。「破（ハ）」＋「裂（レツ）」。「裂」は「裂ける（さける）」の音読み（分裂・決裂）。内側からの圧力で勢いよく破れること。", "meaning": "内側からの力で、勢いよく裂けて破れること。", "kr": "파열", "opts": ["はかい＝破壊（壊すこと）。「裂」はカイと読まない", "", "ほうかい＝崩壊（崩れ落ちること）。別の語", "ほうれつ：「破」をホウと読む誤り"], "ex": "寒さで水道管が<b>破裂</b>した。"},
"30": {"point": "「柔軟」は「じゅうなん」。「柔（ジュウ）」は「柔道」の「じゅう」。「軟（ナン）」は「軟らかい（やわらかい）」の音読みで、「ネン」とは読まない。", "meaning": "やわらかく、しなやかなこと。考え方が一つにこだわらず、状況に合わせられること。", "kr": "유연", "opts": ["じゅうねん：「軟」をネンと読む誤り", "ゆうねん：「柔」も「軟」も読みが違う", "", "ゆうなん：「柔」をユウと読む誤り"], "ex": "予定が変わっても、<b>柔軟</b>に対応できる人は頼りになる。"},
"31": {"point": "「名残」は「なごり」と読む特別な読み方。物事が過ぎ去った後に残る気配や、別れるときの心残り。「名残惜しい」は、別れがつらく離れがたいという意味。", "meaning": "物事が過ぎた後に残る気配・影響。別れを惜しむ気持ち。", "kr": "아쉬움, 자취", "opts": ["", "のこり：「残」だけの読み（残り）。「名」が読まれていない", "めいざん：音読みを当てはめた誤り。「名残」はこう読まない", "みょうざん：音読みを当てはめた誤り"], "ex": "夏の<b>名残</b>を感じさせる暑い日が続いている。"},
"32": {"point": "「淡い」は「あわい」。色・味などが薄く軽い様子。音読みは「タン」（淡水・冷淡）。", "meaning": "色・味・香りなどが薄くて軽い。感情がかすかである。", "kr": "연하다, 옅다", "opts": ["しぶい＝渋い（地味で落ち着いている・渋い味）", "もろい＝脆い（壊れやすい）", "やわい（柔らかい・弱いの意の、くだけた言い方）。「淡」の読みではない", ""], "ex": "春らしい<b>淡い</b>ピンクのセーターを買った。"},
"33": {"point": "「発覚」は、隠れていた悪事や問題が表に出ること。「エラーが発覚する」のように、問題そのものを主語にして使える。", "meaning": "隠されていた悪事・秘密・問題などが明らかになること。", "kr": "발각, 드러남", "opts": ["開示＝情報などを明らかにして示すこと。人や組織が行う行為で、「エラーが開示する」とは言わない", "暴露＝秘密や悪事をあばいて公にすること（また、それが明るみに出ること）。隠された秘密・悪事に使い、プログラムのエラーには合わない", "摘発＝悪事をあばいて公にすること。主に警察などが行う", ""], "ex": "会社の不正が、内部の告発によって<b>発覚</b>した。"},
"34": {"point": "「番組を見逃す」は、見るつもりだったものを見る機会を失うこと。帰宅が遅く見られなかった、という文脈に合う。", "meaning": "見る機会を失う。見落とす。", "kr": "놓치다", "opts": ["", "見過ごして＝見過ごす（見ていながら気づかない・知っていて黙って許す）。番組を見られなかった意味ではない", "見通して＝見通す（先のことを予測する・遠くまで見る）", "見越して＝見越す（将来を予測して、それに備える）"], "ex": "楽しみにしていた試合の中継を<b>見逃して</b>しまった。"},
"35": {"point": "「ほほえましい」は、見ていて思わずほほえみたくなるような、心温まる様子。幼い娘が妹にお菓子を分ける姿に合う。", "meaning": "見ていて、思わずほほえみたくなる様子。", "kr": "흐뭇하다", "opts": ["ねづよくて＝根強い（なかなか変わらない・しっかり根を張っている）", "めざましくて＝目覚ましい（驚くほどすばらしい）。成長や活躍に使い、この場面には合わない", "", "おっかなくて＝おっかない（怖い。話し言葉）"], "ex": "公園で遊ぶ親子の姿が<b>ほほえましい</b>。"},
"36": {"point": "「目途（めど）が立つ」は、物事の見通しがつくこと。仕事が一段落する見通しがついたら連絡する、という文脈に合う。", "meaning": "目途（めど）：目標。物事の見通し。", "kr": "목표, 전망", "opts": ["", "展望＝広く見渡すこと・将来の見通し（「展望が開ける」）。「展望が立つ」とは言わない", "意図＝何かをしようとする考え・ねらい", "設計＝建物や機械などの計画を立てること"], "ex": "資金の<b>目途</b>が立ったので、工事を始めることにした。"},
"37": {"point": "「ねだる」は、甘えたり無理に頼んだりして、物を買ってもらうこと。子どもが父に時計を買ってもらった場面に合う。", "meaning": "甘えたり無理を言ったりして、ほしい物を求める。", "kr": "조르다", "opts": ["つつしんで＝慎んで・謹んで（控えめにして・うやうやしく）", "", "おもねて：「おもねる（気に入られようとこびる）」のことだが、て形は「おもねって」。意味も合わない", "へりくだって＝へりくだる（相手を敬い、自分を低くする）"], "ex": "子どもにおもちゃを<b>ねだられて</b>、つい買ってしまった。"},
"38": {"point": "「高度な文明」は、程度・水準が高い文明。技術や文化の発達の程度を表すには「高度な」を使う。", "meaning": "程度や水準が高いこと。", "kr": "고도의", "opts": ["上等な＝品質がよい（「上等な服」）。主に物に使う", "高尚な＝程度が高く上品な（「高尚な趣味」）。文明の発達の度合いには使わない", "上級な：「上級」は等級や学年が上のこと（「上級クラス」）。「上級な」という言い方はしない", ""], "ex": "この手術には<b>高度な</b>技術が必要だ。"},
"39": {"point": "「ドライ」は、感情に流されず、物事を割り切って考える性格のこと。「泣かないと思う」と合う。", "meaning": "感情に流されず、割り切っている様子。", "kr": "냉정하다, 감정에 휘둘리지 않다", "opts": ["インテリ＝知識人。泣く・泣かないとは関係がない", "", "ロマンチック＝夢や情緒を大切にする様子。泣きそうな性格で、文脈と反対", "タイト＝きつい・余裕がない（「タイトなスケジュール」）。性格には使わない"], "ex": "彼は仕事の人間関係を<b>ドライ</b>に割り切っている。"},
"40": {"point": "「厳重」は「げんじゅう」。「厳（ゲン）」＋「重（ジュウ）」。「重」は「慎重（しんちょう）」のようにチョウとも読むが、この語はジュウ。", "meaning": "少しの手落ちもないよう、きびしく行う様子。", "kr": "엄중", "opts": ["げんちょう：「重」をチョウと読む誤り。この語は「じゅう」", "がんじゅう：「厳」をガンと読む誤り", "", "がんじょう＝頑丈（作りが丈夫で壊れにくい）。別の語"], "ex": "重要な書類は金庫に<b>厳重</b>に保管されている。"},
"41": {"point": "「勝る」は「まさる」。他と比べて上である、優れているという意味。「これに勝る喜びはない」は「これ以上の喜びはない」という決まった言い方。「勝つ（かつ）」と同じ字だが読みが違う。", "meaning": "他と比べて、程度や価値が上である。", "kr": "낫다, 뛰어나다", "opts": ["", "たえる＝耐える・堪える（我慢する）", "かつる：「勝つ」と混同した形で、こういう語はない", "こえる＝超える・越える（ある程度より上になる）。意味は近いが「勝」の読みではない"], "ex": "健康に<b>勝る</b>宝はない。"},
"42": {"point": "「愚か」は「おろか」。考えが足りず、ばかげている様子。音読みは「グ」（愚問・愚痴）。", "meaning": "知恵や判断力が足りない様子。ばかげている。", "kr": "어리석다", "opts": ["おろそかな＝疎かな（いいかげんにする）。一字違いに注意", "おおらかな＝大らかな（心が広く、細かいことにこだわらない）", "おごそかな＝厳かな（重々しい）", ""], "ex": "同じ失敗を何度も繰り返すのは<b>愚かな</b>ことだ。"},
"43": {"point": "「催促」は「さいそく」。「催（サイ）」は「催す（もよおす）」、「促（ソク）」は「促す（うながす）」の音読み。早くするよう相手に求めること。", "meaning": "早くするように相手をせきたてること。", "kr": "재촉", "opts": ["そくせい：「催促」の読みではない（「催」はサイ）。「促成・速成」は別の語", "", "ようせい＝要請（必要なことを願い求める）。「催促」の読みではない", "とくそく＝督促（期限までに行うよう強く求める）。意味は近いが「催」はトクと読まない"], "ex": "家賃の支払いが遅れて、大家さんから<b>催促</b>された。"},
"44": {"point": "「枠」は訓読みで「わく」。周りを囲む縁取り、また決められた範囲。「採用の枠」は採用する人数の範囲。「枠」は日本で作られた字（国字）で、音読みはない。", "meaning": "周りを囲むもの。物事の決められた範囲・制限。", "kr": "틀, 테두리", "opts": ["", "いき＝域（ある範囲・段階。「名人の域」）。「枠」の読みではない", "みぞ＝溝（地面を細長く掘った所）", "ふち＝縁（物のへり）"], "ex": "予算の<b>枠</b>の中で計画を立てる。"},
"45": {"point": "「煩わしい」は「わずらわしい」。面倒で気が重い様子。動詞「煩う（わずらう）」から。音読みは「ハン・ボン」（煩雑・煩悩）。", "meaning": "面倒で、関わるのが嫌だと感じる様子。", "kr": "번거롭다, 귀찮다", "opts": ["いまわしい＝忌まわしい（不吉で嫌な感じがする）", "うるわしい＝麗しい（美しい・心温まる）", "", "そぐわしい：こういう語はない（「そぐわない＝似合わない」と混同しない）"], "ex": "毎日届くメールの整理が<b>煩わしい</b>。"},
"46": {"point": "「消費者のニーズに合わせる」は、消費者が求めていることに合わせること。売れる商品づくりの文脈に合う。", "meaning": "必要・要求。需要。", "kr": "니즈, 수요", "opts": ["", "ルーズ＝だらしない（「時間にルーズ」）", "ニュアンス＝言葉などの微妙な意味合い", "ケア＝世話・手入れ（「肌のケア」）"], "ex": "高齢者の<b>ニーズ</b>に応えるサービスが増えている。"},
"47": {"point": "「処方」は、医者が病気に合わせて薬の種類や量を決めること。「薬を処方してもらう」は決まった言い方。", "meaning": "医者が病状に合わせて薬の種類や量を指示すること。", "kr": "처방", "opts": ["処分＝不要な物を捨てる・違反を罰すること", "処遇＝人をどのように扱うか。待遇", "処理＝物事を片付けること（「データ処理」）", ""], "ex": "医者に<b>処方</b>された薬を、毎食後に飲んでいる。"},
"48": {"point": "「雄大」は、景色などが大きく堂々としている様子。山頂からの景色を見て自分の小ささを感じる、という文脈に合う。", "meaning": "規模が大きく、堂々としている様子。", "kr": "웅대하다, 웅장하다", "opts": ["過大＝大きすぎること（「過大評価」）", "盛大＝大規模で盛んなこと（「盛大なパーティー」）。景色には使わない", "", "大胆＝度胸があり、思い切ったことをする様子"], "ex": "飛行機の窓から、<b>雄大</b>な富士山が見えた。"},
"49": {"point": "「由緒ある」は、古くから続く立派な歴史や来歴がある、という意味の決まった言い方。江戸時代から続く店に合う。", "meaning": "物事の起こりと、今までの歴史。「由緒ある」で、古くからの立派な歴史があること。", "kr": "유서", "opts": ["", "継承＝地位・財産・伝統などを受け継ぐこと。「継承ある」とは言わない", "経歴＝その人のこれまでの学業・仕事の歴史。主に人に使う", "因縁＝前から決まっている関係・宿命。言いがかりの意味もある（「因縁をつける」）"], "ex": "京都には<b>由緒</b>ある寺がたくさんある。"},
"50": {"point": "「変化に乏しい」は、変化が少ない、という意味。「〜に乏しい」の形で使う。同じことの繰り返しの毎日に合う。", "meaning": "少ない。十分でない。", "kr": "부족하다, 빈약하다", "opts": ["はかない＝儚い（すぐに消えてしまいそうで、むなしい）。「〜にはかない」とは言わない", "あさましい＝浅ましい（品がなく、心が卑しい）", "", "たわいない（取るに足りない・張り合いがない）。「〜にたわいない」とは言わない"], "ex": "この地域は天然資源に<b>乏しい</b>。"},
"51": {"point": "「言い張る」は、周りが何と言おうと自分の主張を曲げずに言い続けること。容疑者が犯行を否定し続けている文脈に合う。", "meaning": "自分の主張を強く言い続けて、曲げない。", "kr": "우기다, 끝까지 주장하다", "opts": ["言い付けて＝言い付ける（命令する・告げ口する）", "言い寄って＝言い寄る（好きな相手に近づいて口説く）", "言い聞かせて＝言い聞かせる（よくわかるように話して教える）", ""], "ex": "弟は自分は悪くないと<b>言い張って</b>、謝ろうとしない。"},
"52": {"point": "「そばをすする」は、音を立てて口に吸い込みながら食べること。勢いよく食べて汁がはねた、という文脈に合う。", "meaning": "汁や麺などを、音を立てて吸い込むように飲食する。", "kr": "후루룩 마시다(먹다)", "opts": ["つった＝釣る・吊る（魚を釣る・物を吊り下げる）", "", "あせった＝焦る（思うようにならず、いらいらする）", "うなった＝唸る（苦しそうな声や低い声を出す）"], "ex": "熱いスープをゆっくり<b>すすった</b>。"},
"53": {"point": "「控える」は「ひかえる」。ここでは、量や回数を少なめにする・やめておくという意味。音読みは「コウ」（控除）。", "meaning": "度を越さないように、量や回数を少なくする。", "kr": "삼가다, 자제하다", "opts": ["おさえて＝抑えて・押さえて（勢いを止める）。意味は近いが「控」の読みではない", "きたえて＝鍛えて（練習を重ねて強くする）", "そなえて＝備えて（前もって準備する）", ""], "ex": "医者に言われて、塩分を<b>控える</b>ようにしている。"},
"54": {"point": "「快く」は「こころよく」。気持ちよく、嫌な顔をせずに。「快い（こころよい）」の連用形。音読みは「カイ」（快適・愉快）。", "meaning": "気持ちよく。嫌がらずに喜んで。", "kr": "흔쾌히", "opts": ["", "いさぎよく＝潔く（未練を残さず、思い切りよく）", "ここちよく＝心地よく（気持ちがいい）。意味は近いが「快」一字ではこう読まない", "かっこよく＝格好よく（見た目や態度がすてきに）"], "ex": "先輩は急な頼みも<b>快く</b>聞いてくれた。"},
"55": {"point": "「織物」は「おりもの」。「織る（おる）」の連用形「おり」＋「物（もの）」。「織」の音読みは「ショク・シキ」（組織＝そしき）。", "meaning": "糸を縦横に組み合わせて作った布。", "kr": "직물", "opts": ["しきもつ：「織」をシキ、「物」をモツと読む誤り", "しきもの＝敷物（床に敷くもの）。別の語", "おりもつ：「物」はここでは「もの」と読む", ""], "ex": "京都の西陣は、高級な<b>織物</b>で知られている。"},
"56": {"point": "「検討」は「けんとう」。「検（ケン）」＋「討（トウ）」とも清音。よく調べて、良いか悪いかを考えること。同じ読みの「見当」と文脈で区別する。", "meaning": "よく調べて考えること。", "kr": "검토", "opts": ["", "げんとう：「検」は濁らない（「幻灯」は別の語）", "けんどう：「討」は濁らない（「剣道」は別の語）", "げんどう：どちらも濁らない（「言動」は別の語）"], "ex": "ご提案については、来週の会議で<b>検討</b>します。"},
"57": {"point": "「有無」は「うむ」。「有」は普通「ユウ」だが、この語では「ウ」と読む（有頂天＝うちょうてん）。「無」は「ム」。あるかないか、という意味。", "meaning": "あることとないこと。あるかないか。", "kr": "유무", "opts": ["ゆうむ：「有」をユウと読む誤り。この語は「う」", "ゆうぶ：「有」も「無」も読みが違う（「無」をブと読むのは「無事（ぶじ）」など）", "", "うぶ：「無」をブと読む誤り（「うぶ＝世慣れていない」は別の語）"], "ex": "経験の<b>有無</b>は問いません。"},
"58": {"point": "「田舎」は「いなか」と読む熟字訓。一字ずつの読みを当てはめても読めない特別な読み方。都会から離れた所、また故郷のこと。", "meaning": "都会から離れた、田畑や自然の多い地方。故郷。", "kr": "시골", "opts": ["でんしゃ：音読みを当てはめた誤り（「電車」とは別）", "", "たしゃ：「田」の訓「た」と「舎」の音「シャ」を当てはめた誤り", "いなが：濁らず「いなか」"], "ex": "夏休みに<b>田舎</b>の祖父母の家へ帰った。"},
"59": {"point": "「アクセスがいい」は、目的地への交通の便がいいこと。通勤が長くて嫌になったので会社に行きやすい家に引っ越した、という文脈に合う。", "meaning": "目的地までの交通の便。", "kr": "접근성, 교통편", "opts": ["リーチ＝手の届く範囲。主にボクシングなどで使う", "ロード＝道路", "", "ターミナル＝鉄道やバスの終点・発着所"], "ex": "このホテルは空港への<b>アクセス</b>がよい。"},
"60": {"point": "「打ち解ける」は、遠慮や警戒がなくなって親しくなること。「初対面の人ともすぐに」と合う。", "meaning": "遠慮がなくなって、心を開いて親しくなる。", "kr": "마음을 터놓다, 허물없이 지내다", "opts": ["打ち込む（熱中する・強く打って入れる）", "", "打ち合わせる＝前もって相談する", "打ち消す＝否定する"], "ex": "合宿で一緒に過ごすうちに、新しい仲間とも<b>打ち解けた</b>。"},
"61": {"point": "「赴任」は、仕事のために任地へ行くこと。「海外に赴任する」は決まった言い方。", "meaning": "命じられた任地へ行くこと。", "kr": "부임", "opts": ["転換＝方向・方針などを別のものに変えること", "", "任命＝ある役職につくよう命じること。「〜を…に任命する」の形で、「海外に任命する」とは言わない", "採用＝人を雇うこと・意見などを取り上げて使うこと"], "ex": "父は単身でシンガポールに<b>赴任</b>している。"},
"62": {"point": "「目覚ましい活躍」は、目が覚めるほどすばらしい活躍。年に5本の映画に出る、という後の文に合う。", "meaning": "目覚ましい（めざましい）：驚くほどすばらしい。", "kr": "눈부시다", "opts": ["相応しい（ふさわしい）＝よく似合う・釣り合っている。活躍の程度を表さない", "", "儚い（はかない）＝すぐに消えてしまいそうでむなしい。文脈と反対", "甚だしい（はなはだしい）＝程度がひどい。「甚だしい誤解」のように悪い意味で使う"], "ex": "この町は近年、<b>目覚ましい</b>発展を遂げた。"},
"63": {"point": "「温和な性格」は、穏やかで優しい性格。そういう人が怒っているから「余程のことがあった」と推測できる。", "meaning": "性格が穏やかで優しい様子。", "kr": "온화한", "opts": ["円滑な＝物事がすらすらと進む様子（「円滑な運営」）。性格には使わない", "良質な＝品質がよい。物に使う", "濃厚な＝味などが濃い・可能性が高い（「濃厚な味」）", ""], "ex": "祖父は<b>温和な</b>人で、怒った顔を見たことがない。"},
"64": {"point": "「手入れがしやすい髪型」は、自分で整えたり世話をしたりしやすい髪型。「手入れ」は、よい状態を保つために世話をすること。", "meaning": "よい状態を保つために、整えたり直したりすること。", "kr": "손질", "opts": ["", "手際＝物事を処理する腕前（「手際がいい」）。「手際がしやすい」とは言わない", "手触り＝手で触ったときの感じ", "手間＝ある事にかかる時間や労力（「手間がかかる」）"], "ex": "庭の木の<b>手入れ</b>を植木屋さんに頼んだ。"},
"65": {"point": "「声援」は、声を出して応援すること。「聞こえてきた」とあるので、耳に聞こえる応援の声。", "meaning": "声をかけて励まし、応援すること。", "kr": "성원, 응원", "opts": ["共鳴＝他人の考えに深く共感すること・音が響き合うこと。応援して励ます声という意味はない", "期待＝よい結果を望んで待つこと。耳に「聞こえてくる」ものではない", "名声＝世間のよい評判", ""], "ex": "観客の<b>声援</b>を受けて、選手たちは最後まで走り抜いた。"},
"66": {"point": "「ことごとく」は「一つ残らず全部」という意味の副詞。案が一つ残らず却下された、ということなので「残らず全て」が最も近い。", "meaning": "残らず全部。すべて。", "kr": "모조리, 남김없이", "opts": ["", "次々と＝続けて、一つの後にまた一つ。数の多さではなく、続く様子", "即座に＝その場ですぐに。時間の早さで、量の意味はない", "容赦なく＝手加減せずに、厳しく"], "ex": "台風で、畑の野菜は<b>ことごとく</b>だめになった。"},
"67": {"point": "「気兼ね」は、相手の気持ちを気にして遠慮すること。「気兼ねする」≒「遠慮する」。", "meaning": "他人に気をつかって、遠慮すること。", "kr": "어려워함, 눈치 봄", "opts": ["考えすぎて＝必要以上に考えて。遠慮の意味はない", "悩んで＝どうしたらよいか苦しんで", "", "落ち込んで＝気分が沈んで"], "ex": "ここは自分の家だと思って、<b>気兼ね</b>なく過ごしてください。"},
"68": {"point": "「あやふや」は、はっきりせず、確かでない様子。「曖昧」も、はっきりしない様子を表すので最も近い。", "meaning": "はっきりせず、確かでない様子。", "kr": "애매함, 불확실함", "opts": ["簡潔＝短くて、要点がまとまっている様子", "", "無難＝欠点や危険がなく、特に問題がない様子", "無邪気＝素直で悪気がない様子"], "ex": "記憶が<b>あやふや</b>で、正確な日付が思い出せない。"},
"69": {"point": "「せわしい」は「忙しい・落ち着かない」という意味。引っ越しで忙しい日々なので「いそがしい」が最も近い。", "meaning": "用事が多くて落ち着かない。忙しい。", "kr": "바쁘다, 분주하다", "opts": ["むなしい＝空しい（中身がない・かいがない）", "", "わずらわしい＝煩わしい（面倒で嫌だ）。忙しさそのものではない", "おもいがけない＝思いがけない（予想していなかった）"], "ex": "年末は何かと<b>せわしい</b>。"},
"70": {"point": "「過ち」は、やりそこなうこと・間違い。「過ちを恐れず」は「失敗を恐れず」と言い換えられる。", "meaning": "やりそこない。間違い。", "kr": "잘못, 실수", "opts": ["非難＝相手の欠点や間違いを責めること", "指摘＝問題点などを具体的に示すこと", "危険＝危ないこと", ""], "ex": "若い頃の<b>過ち</b>を、今も後悔している。"},
"71": {"point": "「憤慨」は、ひどく腹を立てること。「激怒した」が最も近い。", "meaning": "不正や理不尽なことに、ひどく腹を立てること。", "kr": "분개", "opts": ["恐縮した＝相手に申し訳なく思って身が縮む思いをした", "共感した＝相手と同じ気持ちになった。反対に近い", "", "困惑した＝どうしてよいかわからず困った"], "ex": "不公平な判定に、観客は<b>憤慨</b>した。"},
"72": {"point": "「気さく」は、気取らず親しみやすい人の性格・態度を表す。「気さくな人」「気さくに話す」のように人について使う。④は森田さんの話しぶりなので正しい。", "meaning": "気取らず、親しみやすい様子。", "kr": "싹싹하다, 허물없다", "opts": ["「気さく」は人の性格に使い、会社には使わない → 自由な雰囲気の会社", "共感の仕方を表す語ではない → 素直に（すんなり）共感できる", "「無警戒に・簡単に」の意味はない → 気軽に（すぐに）ついて行ってしまう", ""], "ex": "社長は<b>気さくな</b>人で、新入社員にもよく話しかけてくれる。"},
"73": {"point": "「ほつれる」は、縫い目や編み目、束ねた髪などの糸がほどけて乱れること。②のタオルの糸が当てはまる。", "meaning": "縫い目・編み目・束ねた髪などがほどけて乱れる。", "kr": "올이 풀리다, 흐트러지다", "opts": ["結んだものがゆるむのは「ほどける」 → 帯がほどけないように", "", "気持ちがゆるむのは「ほぐれる」 → 緊張がほぐれた", "糸の乱れではない → 花束が崩れて（乱れて）"], "ex": "セーターの袖口が<b>ほつれて</b>きた。"},
"74": {"point": "「見込む」は、将来のことを予想して、それを計算に入れること。「〜を見込んで…する」の形で使う。④は観光客の増加を予想して施設を建てたので正しい。", "meaning": "将来どうなるかを予想して、計算に入れる。", "kr": "예상하다, 전망하다", "opts": ["頼りにする意味は「当てにする」 → 親の収入を当てにして", "根拠なく信じるのは「思い込む」 → いないと信じている（思い込んでいる）", "試験問題を推し量るのは「予想する」 → 出る問題を予想して（ヤマをかけて）", ""], "ex": "来年度は売り上げの増加が<b>見込まれて</b>いる。"},
"75": {"point": "「とっさに」は、考える時間もないほど急な場面で、反射的に何かをする様子。①は責められた瞬間に思わず嘘をついたので正しい。", "meaning": "考える間もなく、その瞬間に。", "kr": "순간적으로, 엉겁결에", "opts": ["", "指示を受けて行う仕事は反射的な動作ではない → すぐに（ただちに）報告書を仕上げた", "気づかないうちに寝るのは「いつの間にか」 → いつの間にか寝てしまった", "用が済んで急いで帰る様子は「さっさと」 → さっさと帰って行った"], "ex": "ボールが飛んできて、<b>とっさに</b>顔を手で覆った。"},
"76": {"point": "「手回し」は、前もって準備や手配をしておくこと。「手回しがいい」の形でよく使う。③は加藤さんの準備がよかったので正しい。", "meaning": "前もって準備・手配をしておくこと。", "kr": "사전 준비, 채비", "opts": ["物を配る意味はない → プリントを回して（配って）", "品物を用意する意味では使わない → 袋の用意（手配）をお願いした", "", "料理の準備は「下ごしらえ」 → 野菜を切って下ごしらえしておいた"], "ex": "彼女は<b>手回し</b>がよく、出発前にすべての予約を済ませていた。"},
"77": {"point": "「雑談」は、特に目的のない、気楽なおしゃべり。①は上司との気楽な話について述べているので正しい。", "meaning": "特に目的のない、気楽な話。", "kr": "잡담", "opts": ["", "雑談は書いて載せるものではない → アニメの感想（レビュー）を掲載している", "世間の騒ぎの意味はない → 大きな騒ぎ（話題）になってしまう", "人を笑わせる言葉は「冗談」。「雑談を言う」とは言わない → 冗談を言って"], "ex": "会議の前に少し<b>雑談</b>をして、場を和ませた。"},
"78": {"point": "「いくぶん」は「少し・いくらか」という意味。「やや」が最も近い。", "meaning": "少し。いくらか。", "kr": "다소, 약간", "opts": ["はなはだ＝非常に。程度が大きい", "", "きわめて＝この上なく。程度が大きい", "おおいに＝大いに、たくさん。程度が大きい"], "ex": "薬を飲んで、痛みは<b>いくぶん</b>和らいだ。"},
"79": {"point": "「復旧する」は、壊れたり止まったりしたものが元の状態に戻ること。「元通りになる」が最も近い。", "meaning": "壊れたものや止まったものが、元の状態に戻ること。", "kr": "복구되다", "opts": ["再起動する＝コンピューターなどをもう一度起動する。元に戻ることの一つの手段で、同じ意味ではない", "", "老朽化する＝古くなって役に立たなくなる", "廃れる（すたれる）＝使われなくなって衰える"], "ex": "地震で止まっていた電車が、夕方にようやく<b>復旧した</b>。"},
"80": {"point": "「おびえる」は、怖がってびくびくすること。「こわがっている」が最も近い。", "meaning": "怖がって、びくびくする。", "kr": "겁먹다, 무서워하다", "opts": ["", "うなっている＝唸る（低い声を出す）", "こごえている＝凍える（寒さで体が冷えて動かない）。寒い場面だが、気持ちの意味ではない", "うずくまっている＝体を丸めてしゃがみこむ。姿勢のことで、気持ちの意味ではない"], "ex": "雷の音に<b>おびえて</b>、犬がベッドの下に隠れた。"},
"81": {"point": "「窮屈だ」は、狭かったり小さかったりして、自由に動けない様子。首回りが窮屈なシャツは「きつい」シャツ。", "meaning": "狭くて自由に動けない。きつい。", "kr": "갑갑하다, 비좁다", "opts": ["心地よい＝気持ちがいい。反対の意味", "不快だ＝気分が悪い。窮屈だと不快かもしれないが、大きさが合わない意味はない", "", "ゆるい＝締まりがない。反対の意味"], "ex": "太ったせいで、去年のズボンが<b>窮屈</b>になった。"},
"82": {"point": "「ぞんざい」は、物事を丁寧にせず、いい加減に扱う様子。「いい加減に」が最も近い。", "meaning": "やり方が雑で、いい加減な様子。", "kr": "소홀히, 날림으로", "opts": ["", "気まぐれに＝その時の気分で、変わりやすく", "効率的に＝むだなく", "入念に＝細かいところまで念入りに。反対の意味"], "ex": "お客様の荷物を<b>ぞんざいに</b>扱ってはいけない。"},
"83": {"point": "「麓（ふもと）」は、山の下の方の、平地に続くあたり。「下の方」が最も近い。", "meaning": "山の下の方。山のすそ。", "kr": "기슭", "opts": ["頂上＝山のいちばん高い所。反対の意味", "中腹＝山の頂上と麓の中ほど", "", "上の方＝反対の意味"], "ex": "山の<b>麓</b>に小さな温泉宿がある。"},
"84": {"point": "「使い果たす」は、お金や力などを残らず全部使ってしまうこと。①はエネルギーを全部使って疲れ切ったので正しい。", "meaning": "残らず全部使ってしまう。", "kr": "다 써 버리다", "opts": ["", "使用が終わったという意味ではない → 使い終わったら", "物を最後まで使うのは「使い切る」 → きちんと使い切ってから", "「使い果たす」は残らず全部使うことなので「大半」と合わない。時間を何かに使うのは「費やす」 → 部活動に費やしてしまった"], "ex": "旅行でお金を<b>使い果たして</b>しまった。"},
"85": {"point": "「かすむ」は、霧や涙などのために物がぼんやりして、はっきり見えなくなること。④は霧で目の前さえぼんやりしているので正しい。", "meaning": "霧・もや・涙などで、物がぼんやりして見えにくくなる。", "kr": "흐릿해지다, 뿌옇게 보이다", "opts": ["湯気でレンズが白くなるのは「曇る」 → 眼鏡が曇ってしまった", "朝日が昇るのは見えやすくなること。かすむのは見えにくくなること → 景色が明るくなってきた", "すれすれに触れて通るのは「かすめる」 → ボールが頭をかすめて", ""], "ex": "春の遠い山が<b>かすんで</b>見える。"},
"86": {"point": "「円満」は、争いや不満がなく、穏やかにうまくいっている様子。「円満な家庭」「円満に解決する」のように人間関係に使う。②が正しい。", "meaning": "争いや不満がなく、穏やかでうまくいっている様子。", "kr": "원만함", "opts": ["物事がとどこおりなく進むのは「円滑」 → 円滑な物資の輸送", "", "気持ちが満たされるのは「満足」 → ご満足のご様子（ご満悦）", "仕事の評価には使わない → 仕事ぶりは立派だ（申し分ない）"], "ex": "話し合いの結果、問題は<b>円満</b>に解決した。"},
"87": {"point": "「格差」は、収入・地位などの、上下の水準の差。①は都市部と農村部の収入の差なので正しい。", "meaning": "収入・地位・資格などの、程度や水準の差。", "kr": "격차", "opts": ["", "人を不当に区別する意味は「差別」。「格差的」とは言わない → 差別的な発言", "見た目の違いは上下の差ではない → 違いがわからない", "時間の長さの違いは単に「差」 → 所要時間に差はない"], "ex": "地域による医療の<b>格差</b>が問題になっている。"},
"88": {"point": "「延々と」は、終わりが見えないほど長く続く様子。③は友人と長く話し続けたので正しい。", "meaning": "終わりが見えないほど長く続く様子。", "kr": "끝없이, 장황하게", "opts": ["人の様子を表す語ではない → 生き生きとしている", "人が次々に来るのは「続々と」 → 乗客が続々と降りてきた", "", "髪の美しさは表さない → 髪の毛はつややか（さらさら）で"], "ex": "会議は結論が出ないまま<b>延々と</b>続いた。"},
"89": {"point": "「補足する」は、足りない部分を付け加えて補うこと。主に説明や情報について使う。④は資料にない部分を口で付け加えるので正しい。", "meaning": "足りないところを付け加えて補う。", "kr": "보충하다", "opts": ["物を強くするのは「補強」 → 窓が割れないように補強しておこう", "水分や栄養を取り入れるのは「補給」 → 水分を補給しないと", "欠けた人数を埋めるのは「補充」 → 欠員を補充する", ""], "ex": "先ほどの説明に、一点<b>補足</b>させてください。"},
"90": {"point": "「手分けする」は、一つの仕事を何人かで分けて受け持つこと。「何人かで協力して」が最も近い。", "meaning": "一つの仕事を、何人かで分担すること。", "kr": "분담하다, 나누어 맡다", "opts": ["あきらめないで＝最後まで続けて", "計画を練って＝よく考えて計画を作って", "手を抜かず＝いい加減にせず", ""], "ex": "家族で<b>手分けして</b>、部屋の掃除をした。"},
"91": {"point": "「いかにも」は、本当にそれらしい様子を表す。「いかにも兄がやりそうなこと」＝「まさに兄らしいこと」。", "meaning": "本当にそれらしく。まさに。", "kr": "정말로, 과연, 그야말로", "opts": ["なおさら＝いっそう、ますます", "", "わざわざ＝特別に手間をかけて", "かろうじて＝やっとのことで"], "ex": "<b>いかにも</b>高そうな時計をしている。"},
"92": {"point": "「すこやか」は、体も心も元気で丈夫な様子。「健康に」が最も近い。", "meaning": "体も心も元気で丈夫な様子。", "kr": "건강하게, 튼튼하게", "opts": ["おおらかに＝心が広く、細かいことにこだわらない様子で", "いさましく＝勇ましく（勇気があって力強く）", "優秀に：「優秀」は能力が優れていること。体の丈夫さの意味はない", ""], "ex": "子どもたちが<b>すこやかに</b>育つことを願っている。"},
"93": {"point": "「弁解」は、自分の失敗などについて事情を説明して、許してもらおうとすること。「言い訳」が最も近い。", "meaning": "言い訳。自分の立場を説明して、正当化しようとすること。", "kr": "변명", "opts": ["", "訂正＝誤りを直すこと", "知らんふり＝知っているのに知らないふりをすること", "後悔＝してしまったことを後で悔やむこと"], "ex": "遅刻の理由をいくら<b>弁解</b>しても、信じてもらえなかった。"},
"94": {"point": "「おだてる」は、ほめて相手をいい気分（得意）にさせること。「得意にさせないで」が最も近い。", "meaning": "ほめて、相手をいい気にさせる。", "kr": "추켜세우다, 치켜올리다", "opts": ["怒らせないで＝腹を立てさせないで", "馬鹿にしないで＝見下さないで。ほめる「おだてる」とは反対の方向", "誘惑しないで＝悪いことに誘い込まないで", ""], "ex": "<b>おだてられて</b>、つい高い服を買ってしまった。"},
"95": {"point": "「見苦しい」は、見ていて不快で、体裁が悪い様子。「みっともない」が最も近い。", "meaning": "見ていて不快である。体裁が悪い。", "kr": "꼴사납다, 보기 흉하다", "opts": ["あらっぽい＝荒っぽい（乱暴だ・大ざっぱだ）", "せわしない＝落ち着かない、忙しい", "", "めんどうくさい＝手間がかかって嫌だ"], "ex": "負けてから言い訳をするのは<b>見苦しい</b>。"},
"96": {"point": "「緩和する」は、厳しさや激しさの程度をやわらげること。「痛み・規制・混雑を緩和する」のように使う。④が正しい。", "meaning": "厳しさや激しさの程度をやわらげる。", "kr": "완화하다", "opts": ["雪が水になるのは「解ける」 → 雪が解けて流れ出す", "景気がよくなるのは「回復する」 → 景気が回復して", "締め付けのない服は「ゆったりした」 → ゆったりした服", ""], "ex": "政府は輸入の規制を<b>緩和する</b>方針だ。"},
"97": {"point": "「いきさつ」は、物事がそうなるまでの事情・経緯。②は急に引っ越すことになった事情なので正しい。", "meaning": "物事がそうなるまでの事情。経緯。", "kr": "경위, 자초지종", "opts": ["研究結果の裏付けには使わない → 根拠（過程）がはっきりしていない", "", "道の進み方は「道順」 → 駅までの道順", "作業の流れは「手順」 → 納品までの手順（流れ）"], "ex": "二人が結婚するまでの<b>いきさつ</b>を聞いた。"},
"98": {"point": "「めくる」は、紙など重なった薄いものの端を持ち上げて裏返すこと。「ページ・カレンダー・トランプをめくる」。①が正しい。", "meaning": "重なった紙などの端を持ち上げて、裏返す。", "kr": "넘기다, 젖히다", "opts": ["", "貼ってあるものを取るのは「はがす」 → 古い絆創膏をはがして", "食べ物の上下を返すのは「裏返す」 → ステーキを裏返して", "袖を上へ折り上げるのは「まくる」 → 袖をまくって"], "ex": "本のページを<b>めくる</b>音だけが、図書館に響いていた。"},
"99": {"point": "「いたずらに」は、むだに、意味もなく、という意味。「いたずらに時間が過ぎる」は決まった言い方。②が正しい。", "meaning": "むだに。意味もなく。", "kr": "헛되이, 쓸데없이", "opts": ["勝手な行動の意味はない → 生徒たちが勝手に（こっそり）", "", "訪問の口実には使わない → ついでにお邪魔しても", "量の多さは表さない → 宝石がふんだんに使われていて"], "ex": "<b>いたずらに</b>不安をあおるような報道は控えるべきだ。"},
"100": {"point": "「突き止める」は、調べて、わからなかったことを明らかにすること。「原因・正体・居場所を突き止める」。④が正しい。", "meaning": "調べて、わからなかったことを明らかにする。", "kr": "밝혀내다, 알아내다", "opts": ["見つかる意味は「発見される」 → ジャングルの奥地で発見された", "自分の行動を確認するのは「確かめる」 → 消したか確かめたほうがいい", "人を選ぶのは「見極める」 → 適切な人材を見極める（選び出す）", ""], "ex": "警察はついに犯人の居場所を<b>突き止めた</b>。"},
"101": {"point": "「大ざっぱ」は、細かい点にこだわらず、全体をおおまかにとらえる様子。「大ざっぱに見積もる」が正しい。", "meaning": "細かいところにこだわらず、おおまかな様子。", "kr": "대략적임, 대충", "opts": ["部屋の状態には使わない → 部屋が散らかっている", "物の形には使わない → リンゴは形が不ぞろい（不格好）だが", "", "服装には使わない → ラフな（気軽な）服装で"], "ex": "細かい予定は決めず、<b>大ざっぱ</b>な計画だけ立てた。"},
"102": {"point": "「いっそ」は、中途半端より思い切って別の極端なほうを選ぶ気持ちを表す。「どうせ遅れるなら、むしろ休もう」と言い換えられる。", "meaning": "思い切って。むしろ。", "kr": "차라리, 아예", "opts": ["やけに＝妙に、ひどく（「今日はやけに寒い」）", "すでに＝もう、以前に", "とかく＝ともすれば、あれこれと（「とかく人は他人を気にする」）", ""], "ex": "こんなに古いなら、修理するより<b>いっそ</b>買い替えたほうがいい。"},
"103": {"point": "「そっけない」は、相手への思いやりや関心が感じられず、冷たい様子。「つれない」も、相手に冷淡な様子を表すので最も近い。", "meaning": "思いやりや関心が感じられず、冷たい。", "kr": "쌀쌀맞다, 무뚝뚝하다", "opts": ["", "あどけない＝子どもらしく無邪気でかわいい", "ぎこちない＝動作や言葉が不自然で、なめらかでない", "ふがいない＝情けない、だらしない"], "ex": "声をかけたが、<b>そっけない</b>返事しか返ってこなかった。"},
"104": {"point": "「うやむや」は、物事がはっきりしないまま、決着がつかない様子。「あいまいな」が最も近い。", "meaning": "はっきりしないまま、ぼかされている様子。", "kr": "흐지부지함", "opts": ["ややこしい＝複雑で、わかりにくい", "", "さえない＝ぱっとしない・元気がない", "いい加減な＝無責任な・でたらめな。はっきりしないという中心の意味とは違う"], "ex": "事故の原因は<b>うやむや</b>のまま、調査が打ち切られた。"},
"105": {"point": "「領土」は、その国が治めている土地。「国土」が最も近い。", "meaning": "一つの国が治めている土地。", "kr": "영토", "opts": ["地域＝ある範囲の土地。国のものという意味はない", "一帯＝そのあたり全体", "範囲＝ある限られた広がり", ""], "ex": "島の<b>領土</b>をめぐって、両国は長く対立している。"},
"106": {"point": "「きしむ」は、物がこすれ合ってギシギシと音を立てること。「音が鳴る」が最も近い。", "meaning": "物と物がこすれ合って、ギシギシと音を立てる。", "kr": "삐걱거리다", "opts": ["水漏れする＝水がもれる", "", "腐っている＝木などが腐ってだめになっている", "壊れている＝使えない状態になっている。きしむのは壊れる前の状態"], "ex": "古いドアは開けるたびに<b>きしむ</b>。"},
"107": {"point": "「誇張する」は、実際より大げさに表現すること。「オーバーに」が最も近い。", "meaning": "実際より大げさに表すこと。", "kr": "과장하다", "opts": ["", "タフに＝たくましく、粘り強く", "シンプルに＝簡単に、飾らずに", "ユニークに＝独特に、個性的に"], "ex": "その記事は、事故の被害を<b>誇張して</b>伝えていた。"},
"108": {"point": "「行き詰まる」は、物事がそれ以上うまく進められなくなること。「経営・研究・交渉に行き詰まる」。②が正しい。", "meaning": "物事がそれ以上進められなくなる。", "kr": "막히다, 난관에 부딪치다", "opts": ["自然に終わる意味ではない → 20歳くらいで止まる", "", "反対の意味になってしまう → 最後までやり遂げる（やり抜く）", "管の中で物が詰まるのは「詰まる」 → ゴミが詰まって"], "ex": "研究に<b>行き詰まった</b>ときは、少し休むのもいい。"},
"109": {"point": "「かろうじて」は、やっとのことで、ぎりぎりのところで、という意味。よい結果がどうにか得られたときに使う。④が正しい。", "meaning": "やっとのことで。ぎりぎりのところで。", "kr": "간신히, 가까스로", "opts": ["よくない結果には使わない → 惜しくも不合格になってしまった", "依頼や期限には使わない → 遅くとも終電までには", "これからの意志には使わない → 何とかして（無理をして）車を買う", ""], "ex": "最後の問題が解けて、<b>かろうじて</b>合格点に届いた。"},
"110": {"point": "「うろたえる」は、思いがけないことに慌てて、どうしてよいかわからなくなること。②は浮気を問い詰められて慌てたので正しい。", "meaning": "思いがけないことに慌てて、取り乱す。", "kr": "당황하다, 허둥대다", "opts": ["体の疲れには使わない → 少し運動しただけで息切れする（ばてる）", "", "うろうろ歩き回る意味ではない（「うろつく」と混同しない） → 不審な人がうろついていた", "喜びには使わない → 思いがけないプレゼントに驚いて"], "ex": "突然名前を呼ばれて、彼は<b>うろたえた</b>。"},
"111": {"point": "「〜た拍子に」は、ある動作をしたはずみで、思いがけないことが起こる様子。③は自転車をよけた動作のはずみでスマホを落としたので正しい。", "meaning": "（「〜た拍子に」の形で）その動作のはずみ。その瞬間。", "kr": "~한 순간, ~하는 바람에", "opts": ["帰宅の動作がきっかけで電話が来たわけではない → 帰宅したとたんに（と同時に）", "予定した時期のきっかけは「機に」 → 来年の3月を機に", "", "前に動作がないと使えない → 暗い道で不意に背後から"], "ex": "立ち上がった<b>拍子</b>に、テーブルのコップを倒してしまった。"},
"112": {"point": "「精巧」は、細かいところまで巧みに作られている様子。主に物の作りに使う。④は偽物の作りが細かく巧みなので正しい。", "meaning": "細かいところまで巧みにできている様子。", "kr": "정교함", "opts": ["助言には使わない → 的確に（丁寧に）アドバイスを", "話し方には使わない → 詳細に話してください", "確認の仕方には使わない → 入念に（綿密に）確認する", ""], "ex": "この時計は<b>精巧</b>な技術で作られている。"},
"113": {"point": "「ねばる」は、あきらめずに根気よく続けること。①は最後まであきらめなかったので正しい。", "meaning": "あきらめずに、根気よく続ける。", "kr": "끈질기게 버티다", "opts": ["", "話が盛り上がるのは「弾む」 → 話が弾んで", "効果が続くのは「続く・持続する」 → 効果が続きます（持続します）", "疲れが消えないのは「残る」 → 昨日の疲れが残り"], "ex": "最後まで<b>ねばった</b>が、結局一点差で負けた。"},
"114": {"point": "「再三」は、二度も三度も、何度も繰り返す様子。「たびたび」が最も近い。", "meaning": "何度も。たびたび。", "kr": "재삼, 여러 번", "opts": ["", "せっかく＝わざわざ努力したのに（むだになった）", "とっくに＝ずっと前に", "ふたたび＝もう一度。一回だけ繰り返す意味で、「何度も」とは違う"], "ex": "<b>再三</b>注意したのに、彼はまた同じミスをした。"},
"115": {"point": "「ありふれた」は、どこにでもあって珍しくない様子。「平凡な」が最も近い。", "meaning": "どこにでもあって、珍しくない。", "kr": "흔해 빠진, 평범한", "opts": ["質素な＝ぜいたくをせず、つつましい", "孤独な＝ひとりぼっちの", "", "半端な＝中途半端な、そろっていない"], "ex": "<b>ありふれた</b>材料でも、工夫すればおいしい料理になる。"},
"116": {"point": "「すみやか」は、時間をかけずにすばやく行う様子。「迅速に」が最も近い。", "meaning": "時間をかけずに、すばやく。", "kr": "신속하게", "opts": ["未然に＝まだ起こらないうちに", "着々と＝順調に一歩ずつ。速さの意味は弱い", "丁寧に＝注意深く、細かいところまで", ""], "ex": "地震の際は、<b>すみやかに</b>避難してください。"},
"117": {"point": "「思い返す」は、過去のことをもう一度思い出して考えること。「回顧する」が最も近い。", "meaning": "過去のことを、もう一度思い出して考える。", "kr": "돌이켜 보다, 회고하다", "opts": ["憶測する＝根拠もなく、いいかげんに推し量る", "推測する＝わかっていることから、わからないことを推し量る", "予期する＝前もって予想して待つ。未来のことに使う", ""], "ex": "子どもの頃を<b>思い返す</b>と、懐かしい気持ちになる。"},
"118": {"point": "「うっとうしい」は、じゃまに感じて気分がすっきりしない様子。何度もかかってくる電話を嫌がっているので「煩わしい」が最も近い。", "meaning": "じゃまで不快に感じる。気分が晴れない。", "kr": "성가시다, 짜증스럽다", "opts": ["腹立たしい＝腹が立つ。怒りが中心で、じゃまに感じる意味とは違う", "", "手ごわい＝相手が強くて、簡単には勝てない", "悩ましい＝悩みが多くて苦しい"], "ex": "前髪が伸びて目にかかり、<b>うっとうしい</b>。"},
"119": {"point": "「糸口」は、問題を解決するためのきっかけ・手がかり。「ヒント」が最も近い。", "meaning": "物事を解決するきっかけ。手がかり。", "kr": "실마리", "opts": ["", "サポート＝支援、手助け", "メリット＝利点、長所", "プラス＝利益になること、有利な点"], "ex": "彼の一言が、問題を解決する<b>糸口</b>になった。"},
"120": {"point": "「投げ出す」は、責任を持つべきことを途中で放棄してやめること。①は腹を立てて仕事を放り出したので正しい。", "meaning": "途中で放棄して、やめてしまう。", "kr": "내팽개치다, 포기하다", "opts": ["", "遊びを一時やめるだけなら「やめる」 → ゲームはやめて（切り上げて）", "不要な物を処分するのは「捨てる」 → 古くなったから捨ててしまおう", "店の判断でやめるのは「取りやめる」 → サラダの提供を取りやめて（中止して）"], "ex": "彼は困難な仕事を途中で<b>投げ出す</b>ような人ではない。"},
"121": {"point": "「禁物」は、悪い結果を招くので、してはいけないこと。「無理は禁物」「油断は禁物」のように使う。②が正しい。", "meaning": "悪い結果を招くので、避けるべきこと。", "kr": "금물", "opts": ["規則で禁じるのは「禁止」 → 持ち込みは禁止となっております", "", "取ってはいけない物の意味ではない → 許可なく他人の松茸を採ってはいけない", "法を破る行為は「罪」 → 若いころに罪を犯し"], "ex": "試験前の夜ふかしは<b>禁物</b>だ。"},
"122": {"point": "「忠実」には「誠実に務めを果たす」と「元のものをそのまま正確に再現する」の意味がある。①は映画の世界をそのまま再現しているので正しい（後者の意味）。", "meaning": "務めを誠実に果たす様子。元のものを正確に再現する様子。", "kr": "충실함", "opts": ["", "移動手段の確かさは「確実」 → 電車のほうが確実だ", "疑いがないことは「明らか」 → 飲みすぎたことであるのは明らかだ（事実だ）", "願いの強さは「切に」 → 成功することを切に（心から）願う"], "ex": "この映画は原作に<b>忠実</b>に作られている。"},
"123": {"point": "「にぎわう」は、人が大勢集まって活気があること。「〜でにぎわう」の形で場所を主語にして使う。④が正しい。", "meaning": "人が大勢集まって、活気がある。", "kr": "붐비다, 활기차다", "opts": ["人の集まり以外には使わない → 多様な生物が群れて（すんで）", "悩みが消えるのは「吹き飛ぶ」 → 悩みも一瞬で吹き飛んだ", "人を元気にする意味はない → 落ち込んでいる私を励ます（元気づける）ために", ""], "ex": "週末の商店街は、買い物客で<b>にぎわって</b>いる。"},
"124": {"point": "「動向」は、社会・人・物事が動いていく方向や、その様子。「景気・世論・台風の動向」。③が正しい。", "meaning": "物事や人が動いていく方向。その様子。", "kr": "동향", "opts": ["個人の行いは「行動」 → 思いつきで行動を起こしてしまう", "人の様子は「態度」 → 彼の真剣な態度（表情）", "", "これからの計画は「予定」 → リニューアルオープンする予定だ"], "ex": "投資家は為替の<b>動向</b>に注目している。"},
"125": {"point": "「漏れる」は、液体・気体・光・秘密などが、すき間から外に出ること。①は水筒のお茶が外に出たので正しい。", "meaning": "液体・気体・光・情報などが、すき間から外に出る。", "kr": "새다", "opts": ["", "味が中まで入るのは「染みる」 → 中まで味が染みた大根", "土に水分が行き渡るのは「潤う」 → 畑が十分に潤った", "氷が水になるのは「溶ける」 → 南極の氷が全て溶けると"], "ex": "会議の内容が外部に<b>漏れて</b>しまった。"},
"126": {"point": "「〜てでも」は、ある犠牲を払ってまで実現させるという強い意志を表す。前の「恩師の頼みとあれば（恩師の頼みという理由なら）」と合い、「仕事を休むという犠牲を払ってでも駆けつける」となる。", "opts": ["休まなくても＝休まない場合でも。「休まなくても駆けつける」では、犠牲を払う強い意志が表せない", "", "休まないまでも＝休むところまではしなくても（〜ないまでも：〜ほどではないが）。意志の強さと合わない", "休まなくとも＝「休まなくても」の書き言葉。①と同じ理由で合わない"], "ex": "徹夜し<b>てでも</b>、明日までにこの報告書を仕上げます。"},
"127": {"point": "「AであれBであれ」は「AであってもBであっても、例外なく」という意味。鳥も犬も含め、どんなペットも禁止という規約の厳しさを表す。", "opts": ["", "とて/とて：「とて」は「〜であっても（私とて人間だ）」の意で、「AとてBとて」と二つ並べる形は普通使わない", "なり/なり：「AなりBなり」は「どちらでもいいから選んで」という提案・命令に使い、禁止の文には合わない", "とやら/とやら：「とやら」は「〜とかいう」という不確かな伝聞で、意味が合わない"], "ex": "大人<b>であれ</b>子ども<b>であれ</b>、ルールは守らなければならない。"},
"128": {"point": "「〜といったところだ」は「だいたい〜くらいだ（多くはない）」と程度を軽く示す言い方。「せいぜい」と一緒に使われることが多く、参加者が多くても50人程度だったという意味になる。", "opts": ["までのことだった：「〜までのことだ」は「〜するだけのことだ（だめならあきらめるまでのことだ）」の意。数量には使わない", "", "に限ったことだった：普通「〜に限ったことではない（〜だけではない）」と否定の形で使う", "には至らないことだった：「〜に至らない」は「そこまでにならない」の意で、「せいぜい」と合わない"], "ex": "毎日の勉強時間は、せいぜい1時間<b>といったところ</b>だ。"},
"129": {"point": "前の文「食生活と運動を心がけることは大事だ」と、後の文「毎日実行するのは容易ではない」は反対の内容なので、逆接の接続詞「しかしながら」が入る。", "opts": ["それゆえ＝それだから（順接）。後の内容が前の結果になっていない", "ならびに＝および（並列）。名詞を並べるのに使う", "したがって＝だから（順接）。逆の内容をつなげない", ""], "ex": "計画は順調に進んでいる。<b>しかしながら</b>、予算の問題はまだ残っている。"},
"130": {"point": "「社長は金曜日にお戻りになると〜」の話し手は安田さんで、言ったのは社長。社長の行為「言う」を高める尊敬語「おっしゃる」を使い、「とおっしゃっていました」とするのが最も自然。", "opts": ["伺って：「聞く」の謙譲語で、聞いた自分（安田さん）の行為になる。社長が言った内容を伝える文では「おっしゃる」が自然", "お伝えして：自分が伝える謙譲表現。社長が言ったことにならない", "拝聴して：講演などを謹んで聞くという謙譲語で、予定を聞いた場面には大げさ", ""], "ex": "先生は、明日は休講だと<b>おっしゃって</b>いました。"},
"131": {"point": "「〜きらいがある」は、よくない傾向がある、という意味（動詞の辞書形・名詞＋の に接続）。「考えすぎる」という短所を控えめに指摘する文に合う。", "opts": ["ものと思われる：「〜と推測される」という書き言葉の推量。会話で人の短所を言う文に合わない", "", "極まりない：「失礼極まりない」のように、な形容詞・名詞について「この上なく〜だ」を表す。動詞には付かない", "にしのびない：「〜するのはつらくてできない（捨てるにしのびない）」の意で、意味が合わない"], "ex": "彼は何でも一人で抱え込む<b>きらいがある</b>。"},
"132": {"point": "「〜ことなく」は「〜しないで」という意味の書き言葉的な表現。ミスをした時も責めないで支えてくれた人たちに感謝する、という流れになる。", "opts": ["責めんがために戦った：「〜んがため（に）」は「〜するために」という目的。仲間に感謝する内容と合わない", "", "責めるに至った：「〜に至る」は「ついに〜するまでになる」。感謝の理由にならない", "責めるかのごとく戦った：「〜かのごとく」は「まるで〜かのように」。意味が通らない"], "ex": "彼は一度も休む<b>ことなく</b>、三年間働き続けた。"},
"133": {"point": "「〜ないものだろうか」は、実現が難しいことを何とかして実現させたいという強い願いを表す。後の「強く願う」と合う。", "opts": ["", "なくならないことだろうか：「〜ことだろう」は「どんなに〜ことだろう」のような感慨を表し、願望にならない", "なくなるものだろうか：「なくなるはずがない」という反語の意味になり、願いと合わない", "なくなることだろうか：疑問・感慨の形で、願望を表さない"], "ex": "もう少し安く海外旅行ができない<b>ものだろうか</b>。"},
"134": {"point": "「〜をもって」は「〜で・〜によって」という手段・方法を表す改まった言い方。「書面をもってお知らせします」は、採用の通知などに使われる決まった表現。", "opts": ["もとに：「〜をもとに」は「〜を材料・根拠にして」の意。知らせる手段は表さない", "おいて：「〜において」は「に」に付いて場所・時・分野を表す。「〜をおいて」は「〜以外に（〜をおいてほかにない）」の意で後に否定が来る。どちらも手段は表さない", "", "ふまえて：「〜をふまえて」は「〜を前提・判断の基礎にして」。手段は表さない"], "ex": "合否の結果は、後日メール<b>をもって</b>お知らせします。"},
"135": {"point": "「〜ずにはおかない」は「必ず〜する・自然に〜させてしまう」という意味。動詞のない形の「ない」を取って「ず」を付ける（及ぼさない→及ぼさず）。価格高騰が生活に必ず影響を与える、という意味になる。", "opts": ["及ぶ：自動詞で「影響が及ぶ」と使う。「影響を」と合わず、形も「ずにはおかない」に接続しない", "及ぼす：辞書形は「ずにはおかない」に接続しない", "及ぼさない：「〜ないにはおかない」という形はない", ""], "ex": "彼の熱のこもった演説は、聞く人の心を動かさ<b>ずにはおかない</b>。"},
"136": {"point": "「〜たら〜たで」は、同じ動詞を繰り返して「もしそうなった場合でも、それはそれで（別の問題がある）」という意味を表す。", "steps": "「多忙な生活を送っていると」の後には、その結果の「仕事を辞めたくなるが」が来る。逆接の「が」の後に反対の状況「暇になったらなったで」を置く。「今までとは違う」は名詞「悩み」を修飾するので「悩みが出てくる」の前に置き、「出てくる」が文末の「だろう」につながる。", "ex": "お金がないと困るが、あったら<b>あったで</b>使い道に悩むものだ。"},
"137": {"point": "「AくらいならB（ほうがいい）」は「Aのような望ましくないことをするよりは、Bのほうがましだ」という意味。", "steps": "「くらい」は動詞の辞書形に付き、「なら」はその後に付く（食べないでやせる→くらい→なら）。後半の「思い切って食べて」は、文末の「その分走ったほうがいい」に直接つながる。", "ex": "途中でやめる<b>くらいなら</b>、初めからやらないほうがいい。"},
"138": {"point": "「〜とあって」は「〜という特別な事情なので（当然こうなる）」、「〜とみえる」は「様子から判断すると〜らしい」という意味。", "steps": "「ついに」は「おじいちゃんになった」を修飾し、その後に理由の「とあって」が付く。その結果が「喜びを隠せない」で、話し手の推測「とみえる」が最後に来る。", "ex": "人気歌手が来る<b>とあって</b>、会場には朝から長い列ができた。"},
"139": {"point": "「〜にかまけて」は「〜に気を取られて、ほかの大切なことをおろそかにする」という意味。不満や非難を込めて使う。", "steps": "「仕事や」と「付き合いに」が並んで「仕事や付き合いに」となり、その後に「かまけて」が来る。おろそかにしている内容「家事に協力的ではない」が、文末の「と愚痴っている」につながる。", "ex": "忙しさ<b>にかまけて</b>、家族と過ごす時間を作れずにいる。"},
"140": {"point": "「AはおろかBすら（〜ない）」は「Aは言うまでもなく、もっと簡単なBさえ〜ない」という意味。Bには程度の低いものが来る。", "steps": "目的だった「手に入れること」に「はおろか」を付け、より簡単な「予約券をもらうこと」に「すら」を付けて、文末の「できなかった」につなげる。", "ex": "忙しくて、旅行<b>はおろか</b>週末に休むこと<b>すら</b>できない。"},
"141": {"point": "「すなわち」は、前の語を別の言葉で言い換えるときに使う。「西洋史」＝「ヨーロッパの歴史」なので「すなわち」。", "opts": ["ないしは＝または。どちらか一方を選ぶ意味で、言い換えにならない", "", "ただし＝前の内容に条件や例外を付け加える", "それだけに＝それだからなおさら"], "ex": "日本の首都、<b>すなわち</b>東京には多くの人が集まる。"},
"142": {"point": "「お召しになる」は「着る」の尊敬語。社長の奥様が着物を着ていた、という意味になる。", "opts": ["お越しになっていました：「来る・行く」の尊敬語。「着物をお越しになる」とは言わない", "うけたまわっておりました：「聞く・引き受ける」の謙譲語。着物とは結びつかない", "", "おあがりになっていました：「食べる・（家に）上がる」の尊敬語。着物とは結びつかない"], "ex": "奥様は、すてきなドレスを<b>お召しになって</b>いた。"},
"143": {"point": "「〜にたえる」は「〜するだけの価値がある」という意味（見るにたえる・鑑賞にたえる）。「子ども向けとはいえ」と逆接でつながり、大人が見ても十分価値がある、と勧めている。", "opts": ["", "大人が見るまでもないものだけどね：「〜までもない」は「〜する必要がない」。見に行くことを勧める前の文と合わない", "大人には見かねるものだよ：「見かねる」は「見ていられない（見かねて手伝う）」の意で、勧める文と合わない", "大人が見ようにも見られないものだったよ：「〜ようにも〜ない」は「〜したくてもできない」。意味が通らない"], "ex": "素人の作品だが、十分鑑賞<b>にたえる</b>出来だ。"},
"144": {"point": "「数量＋からある」は「〜もある、〜以上の」と数量の多さを強調する（主に重さ・長さ・大きさ）。きゃしゃな体なのに20キロもの荷物を持ち上げた驚きを表す。", "opts": ["からいる：数量を強調する言い方としては使わない", "だけする：こういう言い方はしない", "", "だけある：「〜だけ（のこと）はある」は「さすが〜にふさわしい」という評価の意味で、数量の強調ではない"], "ex": "彼は30キロ<b>からある</b>米袋を一人で運んだ。"},
"145": {"point": "「AもさることながらB」は「Aはもちろんのこと、Bも」という意味で、AもBもよいと評価するときに使う。デザインも機能性も優れている家具に合う。", "opts": ["をよそに＝〜を無視して（周囲の心配をよそに）。評価の文に合わない", "に至るまで＝範囲の端まで（細部に至るまで）。「機能性にも」とつながらない", "はおろか＝「Aは言うまでもなく、Bも（〜ない）」。「漢字はおろかひらがなも書けない」のように後に否定・マイナスの内容が来ることが多い", ""], "ex": "この店は料理の味<b>もさることながら</b>、サービスも素晴らしい。"},
"146": {"point": "「〜ものを」は「〜のに」という意味で、そうしなかったことへの残念な気持ち・不満を表す。言ってくれれば手伝いに行ったのに、という気持ち。", "opts": ["ものの＝「〜けれども」という逆接。後に文が続く必要がある", "ものか＝「絶対に〜しない」という強い否定・反語（行くものか）", "", "ものだ＝当然・回想・感慨を表す。残念な気持ちは表せない"], "ex": "一言相談してくれればよかった<b>ものを</b>。"},
"147": {"point": "「動詞のた形＋までだ」は「特別な理由ではなく、ただ〜しただけだ」と、すでにした行為を控えめに説明する言い方。ほめられた佐藤くんの返事に合う。", "opts": ["", "する：「辞書形＋までだ」は「〜するしかない（だめなら別の方法を探すまでだ）」という決意で、すでにした行為には使わない", "させた：使役形で、誰かにさせたことになり文脈に合わない", "させる：使役形。③と同じく誰かにさせたことになり、また辞書形は②と同じく既にした行為に使えない"], "ex": "私は思ったことを正直に言った<b>までです</b>。"},
"148": {"point": "「〜ともなると」は「〜という特別な時期・立場になると、当然…」という意味。紅葉の名所で、10月の週末という特別な時期になると渋滞する、という流れ。", "opts": ["と相まって＝「〜と一緒になって（効果が高まる）」。「好天と相まって」のように使う", "", "ならでは＝「〜だけが持つ（名詞＋ならではの）」。後に「の」＋名詞が必要", "たるもの＝「〜という立場にある者は（教師たるもの…べきだ）」。時期には使わない"], "ex": "年末<b>ともなると</b>、街は買い物客でいっそうにぎわう。"},
"149": {"point": "「泣くに泣けない」は、泣きたいほどつらいのに、自分のせいなどで泣くこともできない、という気持ち。自分の不注意でスマホを落とした場面に合う。", "opts": ["泣くだけ泣いた＝思う存分泣いた。「なんとも言われぬ気持ち」とつながりにくい", "泣くともなく泣いた：「〜ともなく」は「はっきりした意図なく」の意（見るともなく見る）。意味が合わない", "泣きに泣いた＝ひたすら泣き続けた。自分のせいで泣けないつらさは表せない", ""], "ex": "旅行の当日に寝坊して飛行機に乗り遅れ、<b>泣くに泣けない</b>思いをした。"},
"150": {"point": "「〜を禁じ得ない」は「〜という気持ちを抑えることができない」という書き言葉。「と同時に」で後の「嫌悪を感じた」と並び、失望も嫌悪も感じたという意味になる。", "opts": ["失望するのに反して：「〜に反して」は「〜とは反対に」。後の嫌悪と並ばない", "", "失望には当たらないばかりか：「〜には当たらない」は「〜する必要はない」。発言を批判する文と合わない", "失望しないまでも：「〜ないまでも」は「〜ほどではないが」。強い嫌悪と合わない"], "ex": "被害者の話を聞いて、涙<b>を禁じ得なかった</b>。"},
"151": {"point": "「〜がてら」は「〜を兼ねて・〜のついでに」という意味。名詞や動詞のます形に付く。", "steps": "「退職」には「した今」が付いて「退職した今」になる。「暇つぶし」に「がてら」が付く。実際にする動作「見返す」は、「には（〜するのには）」の前に来る。", "ex": "散歩<b>がてら</b>、駅前の本屋に寄った。"},
"152": {"point": "「〜かたわら」は「本業の〜をする一方で、別のこともする」という意味。動詞の辞書形・名詞＋の に付く。", "steps": "「主役を務める」がひとまとまりになり、その後に「かたわら」が来る。もう一つの活動「劇団を」は、後の「立ち上げ」の目的語になる。", "ex": "彼は会社に勤める<b>かたわら</b>、小説を書いている。"},
"153": {"point": "「生まれながらにして」は「生まれた時から・生まれつき」という意味の書き言葉。", "steps": "「チェンバロという」の後には、その楽器を説明する「形がピアノに似た楽器を弾き」が来る。続いて「5歳で作曲をしたと言われており」と経歴を述べ、「生まれながらにして」が「音楽の才能を備えていた」を修飾して「と言える」につながる。", "ex": "人は<b>生まれながらにして</b>自由であり、平等である。"},
"154": {"point": "「名詞＋まみれ」は、汚いものが一面についている様子（ほこりまみれ・泥まみれ・汗まみれ）。", "steps": "「掃除」には「したら」が付く。その結果として「全身」「ほこり」「まみれ」が並び、「になった」につながる。「ほこりまみれ」で一語になる。", "ex": "雨の中で試合をして、選手たちは泥<b>まみれ</b>になった。"},
"155": {"point": "「AあってのB」は「Aがあるからこそ、Bが成り立つ」、「今回ほど〜ことはない」は「今回がいちばん〜だ」という意味。", "steps": "文末の「実感したことはありません」と呼応する「今回ほど」を最初に置く。「お客様」に「あっての」が付いて名詞「仕事」を修飾し、「仕事なのだ」となる。", "ex": "ファン<b>あっての</b>プロ野球だということを忘れてはいけない。"},
"156": {"point": "「〜（よ）うとも」は「たとえ〜ても」という逆接の仮定。「どんなに」と呼応して、どんなにつらいことが起こっても、という意味になる。", "opts": ["起こるにたえて：「〜にたえる」は「〜する価値がある・我慢できる」の意で、意味が通らない", "", "起こるにひきかえ：「〜にひきかえ」は「〜とは反対に（比べて）」。仮定を表さない", "起こらんがために：「〜んがため」は「〜するために」という目的。意味が合わない"], "ex": "誰に何と言われ<b>ようとも</b>、私はこの道を進む。"},
"157": {"point": "「〜ではあるまいし」は「〜ではないのだから（当然〜だ）」という意味で、相手の言葉への反論や不満に使う話し言葉。初心者ではないのだから、そんなミスはしない、という意味。", "opts": ["", "ともなれば＝「〜という立場になれば」。「初心者ともなれば」では意味が通らない", "ときたら＝「〜は（不満を込めて）」と話題を取り上げる。反論の文にならない", "はおろか＝「〜は言うまでもなく」。後に「も」の文が必要"], "ex": "子ども<b>ではあるまいし</b>、一人で帰れるよ。"},
"158": {"point": "「もしくは」は「または」という意味で、二つのうちどちらか一方を選ぶことを表す。郵送か電子メールのどちらかで送る、という意味。", "opts": ["いわゆる＝世間でよく言われる（いわゆる天才）", "いわば＝たとえて言えば", "", "はじめ＝「〜をはじめ（として）」で代表例を挙げる"], "ex": "黒<b>もしくは</b>青のペンで記入してください。"},
"159": {"point": "「〜と言わんばかりに」は、実際には言わないが、今にもそう言いそうな態度で、という意味。自分には関係ないという態度で行ってしまった様子を表す。", "opts": ["", "言うが早いか：「〜が早いか」は「〜するとすぐに」。実際に言ったことになり、「とでも」と合わない", "言ってこのかた：「〜てこのかた」は「〜して以来」。意味が通らない", "言うべからず：「〜べからず」は「〜してはならない」という禁止"], "ex": "彼は「早く帰れ」と<b>言わんばかりに</b>時計を見た。"},
"160": {"point": "「〜には当たらない」は「〜するほどのことではない・〜する必要はない」という意味。前輪が曲がっただけでけがもないので、心配する必要はない、と答えている。", "opts": ["心配したかいがありました：「かいがある」は努力が報われること。相手を安心させる文に合わない", "", "心配極まりないです：「極まりない」は「この上なく〜だ」。前の「けがもない」と矛盾する", "心配を禁じ得ません：「〜を禁じ得ない」は「〜という気持ちを抑えられない」。前の内容と矛盾する"], "ex": "少し遅れたくらいで、謝る<b>には当たらない</b>よ。"},
"161": {"point": "「可能形＋ものなら」は「もし〜できるなら（実際は難しいが）」という仮定で、後に願望が来る。帰ることはできないが、帰れるなら今すぐ帰りたい、という気持ち。", "opts": ["帰ろう：「意向形＋ものなら」は「もし〜したら（大変なことになる）」の意で、後に悪い結果が来る。願望の文と合わない", "帰せる：「帰す（帰らせる）」の可能形で、自分が帰る意味にならない", "帰った：た形は「ものなら」に接続しない", ""], "ex": "やり直せる<b>ものなら</b>、高校時代からやり直したい。"},
"162": {"point": "「名詞＋ならでは（の）」は「〜だけが持っている、〜でなければ得られない」という意味。この土地でしか食べられない食材、という意味になる。", "opts": ["ずくめ＝「〜ばかり（黒ずくめ・いいことずくめ）」。土地には使わない", "の極み＝最高の程度（贅沢の極み）。「土地の極み」では意味が通らない", "を踏まえて＝「〜を前提にして」。食材の特徴を表さない", ""], "ex": "これは職人<b>ならでは</b>の技だ。"},
"163": {"point": "「何のお構いもせず（しませんで）」は、客を十分にもてなせなかったことをわびる決まり文句。帰る客に主人側が言う。", "opts": ["", "ご奉仕もせず：「奉仕」は報酬を求めずに尽くすこと。もてなしのあいさつには使わない", "お世話もせず：決まった言い方ではなく、客に対するあいさつとして不自然", "ご遠慮もせず：自分が遠慮しなかったという意味になり、もてなした側のあいさつにならない"], "ex": "遠いところをお越しいただいたのに、何の<b>お構いもできず</b>申し訳ありません。"},
"164": {"point": "「〜に則って（のっとって）」は、規則・法律・基準などに従って、という意味。法律に従って裁かれる権利、となる。", "opts": ["を兼ねて＝一つで二つの役目を果たす（散歩を兼ねて）", "を境に＝〜を区切りにして（それを境に変わった）", "", "にかまけて＝〜に気を取られて、他のことをおろそかにする"], "ex": "試合は国際ルール<b>に則って</b>行われる。"},
"165": {"point": "「〜をものともせず」は、困難や障害を問題にせず、立ち向かって何かを成し遂げる様子。夢を叶えた鈴木君への評価に合う。", "opts": ["", "障害もさることながら：「〜もさることながら」は「〜はもちろん（…も）」。後に並べる内容がない", "障害をはばからず：「〜をはばからず」は「遠慮しないで（人目をはばからず）」。障害には使わない", "障害のいかんによらず：「〜のいかんによらず」は「〜がどうであっても」。困難に立ち向かう意味は弱い"], "ex": "彼は足のけが<b>をものともせず</b>、最後まで走り抜いた。"},
"166": {"point": "「Aとは言わないまでも（B）」は「Aというほどではないが、せめてBくらいは」という意味。", "steps": "「せっかくの」の後には名詞の「夏休みなので」が来る。「人気のリゾート地」に「とは言わない」「まで」が続き、文中の「も」と合わせて「とは言わないまでも」となる。", "ex": "毎日<b>とは言わないまでも</b>、週に一度は運動したい。"},
"167": {"point": "「AなくしてはB（ない）」は「AがなければBはできない」という意味の書き言葉。感謝を述べるときによく使う。", "steps": "「山口教授の」は名詞「的確なご指導」を修飾し、その後に「なくしては」が来る。後半は「この論文を書き上げること」が、文末の「は不可能だった」の主語になる。", "ex": "皆様のご協力<b>なくしては</b>、この大会の成功はありませんでした。"},
"168": {"point": "「Aを契機に（して）B」は「Aをきっかけにして、Bをする・Bが変わる」という意味。", "steps": "「母親の再婚」に「を」「契機」「に」が続いて「を契機に」となる。そのあとに新しく始めたこと「一人暮らし」が来て、「を始めた」につながる。", "ex": "入院<b>を契機に</b>、たばこをやめた。"},
"169": {"point": "「AにとどまらずB」は「Aだけでなく、Bにまで範囲が広がる」という意味。", "steps": "「日本国内に」に「とどまらず」が付き、範囲が広がった先の「海外からも」が続く。「注文が入って」が文末の「くる」につながる。", "ex": "この問題は一つの地域<b>にとどまらず</b>、国全体に広がっている。"},
"170": {"point": "「Aならいざ知らずB」は「Aならともかく、Bは（〜だ）」という意味で、Bについて驚きや批判を述べるときに使う。", "steps": "「普段から」の後に「運動している人」が来て、「なら」「いざ知らず」が続く。対比される「君のように」は、後の「家にこもってばかりいる人」につながる。", "ex": "子ども<b>ならいざ知らず</b>、大人がそんなことを言うなんて。"},
"171": {"point": "「ちなみに」は、前の話に関連することを付け加えるときに使う。物件の話のついでにスーパーの有無を尋ねている。", "opts": ["", "おまけに＝その上（さらに〜だ）。事実を付け加えるときに使い、質問の前には不自然", "あるいは＝または。二つのうちのどちらかを表す", "さりとて＝そうかといって（逆接）。意味がつながらない"], "ex": "明日は創立記念日で休みです。<b>ちなみに</b>、来週の月曜日も休みです。"},
"172": {"point": "「想像にかたくない」は「簡単に想像できる」という意味の決まった言い方。あざだらけの体から、虐待されていたことが容易に想像できる。", "opts": ["たえない：「聞くにたえない（聞いていられない）」「感謝にたえない」のように使い、「想像にたえない」とは言わない", "たりない：「〜にたりない」は「〜する価値がない（恐れるにたりない）」。意味が合わない", "", "しのびない：「見るにしのびない」のように「つらくて〜できない」。「想像に」とは結びつかない"], "ex": "彼女がどれほど悲しんだかは、想像<b>にかたくない</b>。"},
"173": {"point": "「〜のいかんによらず」は「〜がどうであるかに関係なく」という意味。人種や性別に関係なく、すべての人に権利がある、となる。", "opts": ["いかんで＝「〜次第で（決まる）」。後の内容と合わない", "いかんでは＝「〜次第では（そうなることもある）」。「すべての人に」と合わない", "", "いかんによっては＝「〜によっては」。一部の場合を表し、「すべての人」と矛盾する"], "ex": "理由の<b>いかんによらず</b>、無断欠席は認めません。"},
"174": {"point": "「〜に恥じない」は「〜の名や評判を汚さない、〜にふさわしい」という意味。先代の社長の名にふさわしい経営をしたい、という意気込みになる。", "opts": ["加えて＝「〜に加えて（その上に）」。意味が通らない", "", "ひきかえ＝「〜にひきかえ（〜と比べて反対に）」。意味が通らない", "もまして＝「〜にもまして（〜以上に）」。名に「もまして」では意味が通らない"], "ex": "優勝チームの名<b>に恥じない</b>試合をしたい。"},
"175": {"point": "「辞書形＋べくして＋同じ動詞」は「そうなるのが当然で、実際にそうなった」という意味。出会うのが運命だった、という意味になる。", "opts": ["出会い：「べくして」はます形の語幹に接続しない", "出会って：て形は「べくして」に接続しない", "", "出会おう：意向形は「べくして」に接続しない"], "ex": "準備不足だったのだから、この失敗は起こる<b>べくして</b>起こったと言える。"},
"176": {"point": "「〜のをいいことに」は「〜という状況を都合のいい機会にして（よくないことをする）」という意味。先生が来ないのをチャンスに騒いでいる様子を表す。", "opts": ["入るか入るまいか：「入ろうかどうしようか迷う」の意で、先生の行為として意味が通らない", "", "入ってきたのをさかい：「〜を境に」は「〜を区切りに」だが、形が不完全で、騒ぐ理由にならない", "入らずとも：「入らなくても」の意で、後の内容とつながらない"], "ex": "親が留守な<b>のをいいことに</b>、弟は一日中ゲームをしていた。"},
"177": {"point": "「〜をぬきにして」は「〜を除いて・〜なしで」という意味。飲み会の場なので、堅い仕事の話はやめて楽しもう、という意味になる。", "opts": ["もとより＝「もちろん」。「堅い話はもとより」では後の文とつながらない", "おろか：「〜はおろか」の形で使い、「〜は言うまでもなく」の意。意味も形も合わない", "", "ものともせず＝「〜を問題にせず」。困難に立ち向かうときに使う"], "ex": "冗談は<b>ぬきにして</b>、そろそろ本題に入りましょう。"},
"178": {"point": "「AにせよBにせよ」は「AでもBでも、どちらの場合でも」という意味。進学しても就職しても資格は役に立つから取っておいたほうがいい、という意味になる。", "opts": ["とか/とか：例を並べる話し言葉で、「どちらの場合でも」の意味は出ない", "やら/やら：「AやらBやらで大変だ」のように、いろいろなものを並べる", "なり/なり：「AなりBなりしなさい」と、どちらかを選ぶよう提案するときに使う。後の文と合わない", ""], "ex": "行く<b>にせよ</b>行かない<b>にせよ</b>、早めに連絡してください。"},
"179": {"point": "「〜てなるものか」は「絶対に〜しない」という強い決意を表す。一度負けた相手なので「今度こそ負けたくない」とがんばった、という意味になる。", "opts": ["負けようがない＝「負ける可能性がない」。決意の表現ではない", "", "負けるよりほかない＝「負けるしかない」。意味が反対", "負けるものではない：「〜ものではない」は「〜するべきではない（一般的な忠告）」「普通は〜しない」の意。自分の強い決意は表さない"], "ex": "こんなところで、あきらめ<b>てなるものか</b>。"},
"180": {"point": "「賜る」は「もらう」の謙譲語で、「いただく」よりさらに改まった言い方。式典で社長から挨拶をいただきたい、という司会の言葉に合う。", "opts": ["", "傾聴したい：「傾聴」は熱心に耳を傾けて聞くこと。「挨拶を傾聴したい」は不自然", "差し上げたい：「あげる」の謙譲語。社長に挨拶をあげることになり、方向が逆", "お受けしたい：「受ける」の謙譲語で、依頼や注文を引き受けるときに使う"], "ex": "本日は多くの方々からご支援を<b>賜り</b>、心より感謝申し上げます。"},
"181": {"point": "「〜ときたら」は、ある物事を話題に取り上げて、話し手の強い評価や感情（多くは不満・驚き）を述べる。「目も当てられない」は「見ていられないほどひどい」。", "steps": "「その」の後に「映像から見て取れる」が来て「事故現場の悲惨さ」を修飾する。それを話題にする「ときたら」が続き、評価の「目も当てられないほど」が文末の「であった」につながる。", "ex": "うちの兄<b>ときたら</b>、休みの日は昼まで寝ている。"},
"182": {"point": "「AならまだしもB」は「Aならまだ許せるが、Bは困る・驚く」という意味。", "steps": "初対面でも聞かれて普通な「名前や職業」に「ならまだしも」を付ける。驚いた内容「家庭環境まで」を後に置き、「聞かれた」が「ので」につながる。", "ex": "一度<b>ならまだしも</b>、何度も同じミスをされては困る。"},
"183": {"point": "「〜ですら」は「〜でさえも」という意味で、極端な例を挙げて「ほかはなおさらだ」と示す。「稀代（きたい）」は「世にもまれな」という意味。", "steps": "「その道に優れた」は「稀代の名人」を修飾し、「ですら」が続く。その後に「時には失敗をする」「ということ」が来て、「を例えた」につながる。", "ex": "専門家<b>ですら</b>、この問題には答えられなかった。"},
"184": {"point": "「〜とでもいうべき」は「〜と呼んでもいいような」という意味で、物事をたとえて評価するときに使う。", "steps": "「システム設計の」の後に名詞「落とし穴」が来る。「とでも」「いうべき」と続け、名詞「もの」が文末の「だった」につながる。", "ex": "この発見は、医学の革命<b>とでもいうべき</b>出来事だ。"},
"185": {"point": "「AたるものB」は「Aという立場にある者は、当然Bするべきだ」という意味の書き言葉。", "steps": "「国家の」の後に「最高責任者」が来て、「たるもの」が続く。何をすべきかは後に述べ、「国民」「のこと」が「を第一に考えた」の目的語になる。", "ex": "教師<b>たるもの</b>、生徒の手本とならなければならない。"},
"186": {"point": "「〜とはいうものの」は「〜とは言っても（実際は予想と違う）」という逆接。昇進したと言っても給料はあまり変わらない、という意味。", "opts": ["からには＝「〜した以上は（当然…すべきだ）」。後に義務や決意が来る", "とあれば＝「〜という理由なら」。後に「どんなことでもする」などが来る", "だけあって＝「〜にふさわしく、さすがに」。後にプラスの評価が来る", ""], "ex": "春<b>とはいうものの</b>、まだ寒い日が続いている。"},
"187": {"point": "「お気に召す」は「気に入る」の尊敬語。送ったお菓子を相手が気に入ってくれたらうれしい、という意味になる。", "opts": ["お気になさって：「気にする」の尊敬語で「心配する」の意。意味が合わない", "", "頂戴して：「もらう」の謙譲語で、相手の行為には使えない", "お目にかかって：「会う」の謙譲語。意味が合わない"], "ex": "このデザインは<b>お気に召しました</b>か。"},
"188": {"point": "「名詞＋なりに」は「その立場にふさわしい程度に・それ相応に」という意味。学生には学生なりの大変さがある、という意味になる。", "opts": ["にして：「〜にして（〜であって同時に・〜になってやっと）」。意味が合わない", "", "に則って：「〜に従って」。規則などに使う", "ならでは：「〜だけが持つ」。後に「の＋名詞」が必要で、意味も合わない"], "ex": "子どもは子ども<b>なりに</b>、家族のことを心配している。"},
"189": {"point": "「〜をよそに」は「〜を気にせず・無視して」という意味。周囲の反対を無視して危険な地域に向かった、という意味になる。", "opts": ["", "めぐって：「〜をめぐって」は「〜について（争う・議論する）」。後の行動と合わない", "もとに：「〜をもとに」は「〜を材料・根拠にして」。意味が合わない", "機に：「〜を機に」は「〜をきっかけに」。反対をきっかけに出発するのは不自然"], "ex": "親の心配<b>をよそに</b>、息子は一人で旅に出た。"},
"190": {"point": "「AかれBかれ」は、い形容詞の語幹に「かれ」を付けて「AでもBでも、いずれにしても」を表す古い形（遅かれ早かれ・多かれ少なかれ・良かれ悪しかれ）。語幹「遅・早」が入る。", "opts": ["遅い/早い：「遅いかれ」という形はない", "遅く/早く：「遅くかれ」という形はない", "遅くな/早くな：こういう形はない", ""], "ex": "<b>遅かれ早かれ</b>、本当のことはわかるだろう。"},
"191": {"point": "「名詞＋かたがた」は「〜を兼ねて」という意味で、手紙や訪問のあいさつに使う改まった言い方。名詞の「報告」に直接付く。", "opts": ["報告する：辞書形は「かたがた」に接続しない", "報告し：ます形の語幹は「かたがた」に接続しない", "", "報告の：「の」は入れず、名詞に直接付ける"], "ex": "先日のお礼<b>かたがた</b>、ご挨拶に伺いました。"},
"192": {"point": "「〜だにしない」は「〜さえしない」という意味の書き言葉（想像だにしない・微動だにしない）。有名な女優と結婚するなど想像さえしなかった、という意味。", "opts": ["するべからず：「〜べからず」は「〜してはならない」という禁止", "しないではすまなかった：「〜しないではすまない」は「〜しなければならない」", "してはかなわない：「〜てはかなわない」は「〜ては困る・たまらない」", ""], "ex": "こんな結果になるとは、夢に<b>だに</b>思わなかった。"},
"193": {"point": "「〜に由来する」は、名前や物事の起こりが〜にあるという意味。市の名前がトヨタの本社があることから来ている、という文に合う。", "opts": ["まつわる：「〜にまつわる」は「〜に関係する（〜にまつわる伝説）」。後に名詞が必要", "ともなう：「〜にともなう」は「〜と一緒に起こる」。名前の起こりは表さない", "", "起因する：「〜に起因する」は、事故や問題の原因が〜にあること。悪い出来事に使う"], "ex": "この地名は、昔ここにあった大きな池に<b>由来する</b>。"},
"194": {"point": "「〜か否か」は「〜かどうか」の書き言葉。合格できるかどうかはっきりとは言えない、という意味になる。", "opts": ["", "できるや否や：「〜や否や」は「〜するとすぐに」。意味が合わない", "しようがしまいが：「してもしなくても（関係ない）」。後の「はっきりとは言えない」と合わない", "しようかしまいか：「しようかやめようか（迷う）」。合格は自分の意志で決められない"], "ex": "計画を実行する<b>か否か</b>は、来週の会議で決める。"},
"195": {"point": "「〜に越したことはない」は「〜のほうがいい（それより良いことはない）」という意味。家族のために入っているほうがいいが、という前半と、後の「が」の逆接が合う。", "opts": ["", "入るといったらない：「〜といったらない」は「非常に〜だ（悔しいといったらない）」という感情の表現", "入っていることはない：「〜ことはない」は「〜する必要はない」。前の「家族のためにも」と合わない", "入るおそれがある：「〜おそれがある」は悪いことが起こる可能性。意味が合わない"], "ex": "安全のためには、用心する<b>に越したことはない</b>。"},
"196": {"point": "「AともあろうB」は「Aという立派な立場にある人が（そんなことをするとは）」という意味で、驚きや非難を表す。", "steps": "「政治家」に「ともあろう」が付き、「人が言ってはいけない」が続いて「差別的な発言」を修飾する。「差別的な発言」が文末の「をした」につながる。", "ex": "警察官<b>ともあろう</b>者が、交通違反をするとは。"},
"197": {"point": "「動詞の辞書形＋べく」は「〜するために」という目的を表す書き言葉（「するべく」は「すべく」とも言う）。", "steps": "「歌手になる」「という」が「幼少期からの夢を」の内容を説明する。その後に目的を表す「実現するべく」が来て、後の「歌やダンスのレッスンを受ける」につながる。", "ex": "留学の資金を貯める<b>べく</b>、アルバイトを始めた。"},
"198": {"point": "「Aをおいてほかにいない（ない）」は「A以外に適当な人（もの）はいない」という意味。", "steps": "「私の」は「大事な顧客を」を修飾し、「任せられるのは」が続く。そのあとに候補の「森山さんを」が来て、「おいてほかにいない」が「と考えていた」につながる。", "ex": "この役を演じられるのは、彼<b>をおいてほかにいない</b>。"},
"199": {"point": "「〜たところで」は「〜しても（むだだ・結果は変わらない）」、「AもののB」は「AけれどもB」という意味。", "steps": "「今さら」の後には「悔やんだところで」が来て、その結果「結果が変わることはない」が続く。逆接の「ものの」の後に前向きな内容「失敗から学べる」が来て、「こと」を修飾する。", "ex": "今から急いだ<b>ところで</b>、もう間に合わない。"},
"200": {"point": "「言うまでもなく」は「当然のことだが・わざわざ言う必要もないが」という意味。", "steps": "文中の「言う」に「までもなく」が付く。そのあと「裸で」「街を歩く」「こと」がひとまとまりになり、「は犯罪である」の主語になる。", "ex": "<b>言うまでもなく</b>、健康は何よりも大切だ。"},
"201_0": {"point": "直後の文「あるいは、〜と考えているのではないだろうか」と並ぶ形で、筆者は孤独を不幸と思う人の無意識の考え方を推測している。同じ推測の「〜ているのではないだろうか」が入る。", "opts": ["前提にさせないのである：使役の否定で「（他人に）前提にさせない」という意味になり、孤独を不幸だと思い込んでいる人の説明と合わない。また断定の形で、次の文の推測とも並ばない", "", "前提にしないようにしているのだ：意識して避けている意味になり、「無意識のうちに」と矛盾する", "前提にせざるを得ないと思っている：本人が自覚していることになり、「無意識のうちに」と矛盾する"], "ex": "彼が来ないのは、何か理由がある<b>のではないだろうか</b>。"},
"201_1": {"point": "孤独は不幸だという常識に対して、わざと疑問を投げかけている。「困難や反対があるのを承知で、わざわざ」という意味の「あえて」が入る。", "opts": ["あらかじめ＝前もって。問いかける時期の話ではない", "いっそ＝思い切って（極端な方を選ぶ）。問いかけの様子に合わない", "おそるおそる＝怖がりながら。筆者の態度に合わない", ""], "ex": "反対されるとわかっていたが、<b>あえて</b>自分の意見を言った。"},
"201_2": {"point": "孤独の負の感情を並べている部分。「誰も（自分を）理解してくれない」と、孤独な人の側から見た不満を表す「〜てくれない」が入る。", "opts": ["理解させない：使役で「他人に理解することを許さない」意味になり、孤独な人の気持ちと合わない", "理解させられない：「理解させることができない」の意で、自分の説明不足の話になる", "", "理解してやらない：自分が他人を理解しない意味になり、方向が逆"], "ex": "誰も私の気持ちをわかって<b>くれない</b>。"},
"201_3": {"point": "「すると、」で始まる文なので、距離を置いて考えた結果として予想されることが来る。肯定の推量「気づくだろう」が入り、次の「決して『孤独であること＝不幸』ではないのだ」につながる。", "opts": ["気づかない：否定で、ポジティブな側面があるという後の主張と矛盾する", "", "気づくのか：疑問の形で、「すると」の結果を述べる文にならない", "気づくまい：「気づかないだろう」という否定の推量で、後の主張と矛盾する"], "ex": "落ち着いて考えれば、彼も自分の間違いに<b>気づくだろう</b>。"},
"201_4": {"point": "「そう思えた時」、つまり孤独を成熟の時間と受け止められた時点で、すでに心豊かな人生へ向かい始めている、と筆者は評価している。「一歩踏み出したと言えるだろう」が入る。", "opts": ["", "一歩踏み出そうとするのだろう：これから踏み出すという推測で、「そう思えた時」の評価として弱い", "一歩踏み出す必要がなくなるのだろう：「心豊かな人生に向けて」と意味がつながらない", "一歩踏み出せなくなっていくのだろう：孤独を肯定する文章の結論と反対になる"], "ex": "自分の弱さを認められた時、人は成長への一歩を踏み出した<b>と言えるだろう</b>。"},
"202_0": {"point": "「名詞＋いかんで」は「〜次第で・〜によって（結果が変わる）」という意味。前の「どのような姿勢で臨むかによって、…大きく変わってきます」を「つまり」で言い換えている。", "opts": ["", "にかぎり＝「〜だけは（特別に）」。条件によって変わる意味は出ない", "のみならず＝「〜だけでなく」。後の文とつながらない", "にかかわらず＝「〜に関係なく」。つき合い方で変わるという前の内容と反対になる"], "ex": "交渉の結果<b>いかんで</b>、計画を見直すことになる。"},
"202_1": {"point": "前の段落は「失敗を怖れて何もしない慎重な人」、この段落は「失敗をまったく考えずに突き進む人」で、反対のタイプを対比している。「これとは正反対に」が入る。", "opts": ["これと同様に：同じタイプを続ける言い方で、反対の人物の説明と合わない", "これに比例して：数量が一緒に増減する関係を表す", "", "これとは別に：別の話題を加える言い方で、対比の関係が表せない"], "ex": "兄はおとなしい。<b>これとは正反対に</b>、弟はとても活発だ。"},
"202_2": {"point": "後に「まわりをごまかすための言い訳に終始する」とあるので、原因の究明を「しようとしないで」という意味の「行おうとせず」が入る。", "opts": ["行うべく：「〜べく」は「〜するために」。言い訳に終始する人の説明と合わない", "行わんがために：「〜んがため」も目的を表す。①と同じ理由で合わない", "行おうか否か：「行うかどうか（迷う）」。後の文とつながらない", ""], "ex": "彼は人の意見を聞こう<b>とせず</b>、自分の考えを押し通した。"},
"202_3": {"point": "「失敗は避けられない。しかし、それが致命的になってはいけない」という逆接の関係なので、「〜とはいえ（〜けれども）」が入る。", "opts": ["避けられるともすれば：「ともすれば」は「ややもすると」という副詞で、この形では使わない", "", "避けられるとばかりに：「〜とばかりに」は「今にも〜と言いそうな様子で」。意味が通らない", "避けられないとあって：「〜とあって」は理由を表し、後の内容と逆接の関係が表せない"], "ex": "仕事<b>とはいえ</b>、毎晩遅くまで働くのはつらい。"},
"202_4": {"point": "予想される失敗の知識を念頭に置いて行動すれば、致命的な失敗やむだな失敗を前もって防げる。「不必要な失敗を避ける」が入る。", "opts": ["必要な失敗を繰り返す：同じ失敗を何度も繰り返す人を批判した前の段落と矛盾する", "必要な挑戦を選ぶ：失敗の知識を生かすという話から外れる", "不必要な挑戦はしない：挑戦を控える意味になり、「行動しなければ何も起こらない」という筆者の主張と合わない", ""], "ex": "事前に道を調べておけば、むだな遠回りを<b>避ける</b>ことができる。"},
"203_0": {"point": "「好むと好まざるとにかかわらず」は「好きでも嫌いでも、本人の気持ちに関係なく」という意味の決まった言い方。近代以前の不自由さを表している。", "opts": ["まつわり：「〜にまつわる」は「〜に関係する」。この決まった言い方には使わない", "", "かこつけて：「〜にかこつけて」は「〜を口実にして」。意味が通らない", "よっては：「〜によっては」は「〜の場合には」。この言い方には使わない"], "ex": "好むと好まざると<b>にかかわらず</b>、新しい制度に従わなければならない。"},
"203_1": {"point": "近代以前の不自由な時代を経て、ついに「どのような価値観を持とうが自由」という合意を手に入れた、という歴史の到達点を述べている。「ついに〜するまでになった」という意味の「〜にいたりました」が入る。", "opts": ["獲得するばかりなのです：「〜ばかりだ」は「その方向にどんどん進む（悪化するばかり）」。合意の成立を表せない", "獲得するにかたくありません：「〜にかたくない」は「想像にかたくない」のように使い、意味が通らない", "獲得するきらいがあるのです：「〜きらいがある」はよくない傾向。筆者が評価する内容と合わない", ""], "ex": "長い話し合いの末、両国は合意する<b>にいたった</b>。"},
"203_2": {"point": "「皮肉なことに」は「期待とは逆の結果になって」という意味の決まった言い方。自由のための価値観の多様化が、新たな問題を生んだことを表す。", "opts": ["もの：「皮肉なものだ」とは言うが、「皮肉なものに」とは言わない", "", "ところ：「皮肉なところに」とは言わない", "よう：「皮肉なように」とは言わない"], "ex": "<b>皮肉なことに</b>、便利になればなるほど人は忙しくなった。"},
"203_3": {"point": "明確な価値の拠り所を失った結果、私たちは空気を読み合う人間関係を送るしかない状況になっている、という今日の問題を述べている。「〜なければならなくなっている」が入る。", "opts": ["", "送ったことになっているのです：「〜ことになっている」は「事実でなくてもそう扱われる・決まりだ」の意。問題の説明にならない", "送るに越したことはないのです：「そうするほうがよい」という勧めになり、問題を述べる文と合わない", "送るまでもないのです：「その必要はない」の意で、前の内容と矛盾する"], "ex": "人手が足りず、毎日残業をし<b>なければならなくなって</b>いる。"},
"203_4": {"point": "「〜などというわけにはいかない」で否定されているのは、「多様な価値観を再び一つにまとめるべきだ」という考え。「統合しなければならない」が入る。筆者は多様性の承認こそが自由の条件だと考えている。", "opts": ["統合すべきではない：これは筆者自身の考えで、「〜というわけにはいかない」で否定する内容にならない", "統合するまでもない：「その必要がない」の意で、後の「わけにはいかない」とつながらない", "", "統合しようもない：「統合する方法がない」の意で、筆者の理由（多様性の承認）と合わない"], "ex": "一度決めたことだから、今さらやめる<b>というわけにはいかない</b>。"},
"204_0": {"point": "直前の「見直しの動きは鈍い」を裏付けるので、時短に踏み切った店が少ないことを表す「〜に過ぎない（ただ〜だけだ）」が入る。", "opts": ["約4%に限らない：「〜に限らない」は「〜だけではない」。少なさを表せない", "", "約4%にとどまらない：「〜にとどまらない」は「〜を超えて広がる」。「鈍い」と矛盾する", "約4%に相違ない：「〜に相違ない」は「きっと〜だ」という確信。少なさを強調できない"], "ex": "会議に出席したのは、わずか10人<b>に過ぎなかった</b>。"},
"204_1": {"point": "「〜ほど」は、一方の程度が変わるにつれて、もう一方も変わる（比例）ことを表す。売上高が伸びれば伸びるだけ本部の収益も増える仕組み。", "opts": ["", "くらい：程度の目安を表し、比例の関係は表せない", "さえ：「〜さえ〜ば」の形で条件を表すが、ここでは「ば」がなく形が合わない", "より：比較を表し、比例の関係は表せない"], "ex": "年をとる<b>ほど</b>、時間が早く過ぎるように感じる。"},
"204_2": {"point": "前の段落は本部の立場（営業時間を長くして売上を増やしたい）、この段落は加盟店の立場（深夜営業はデメリットが大きい）で、二つを対比している。「これに対し」が入る。", "opts": ["これにしては：「〜にしては」は「〜から予想されるのとは違って」。対比にならない", "これにつけて：「〜につけ」は「〜するたびに（何かにつけて）」。意味が通らない", "", "これに向けて：「〜に向けて」は目標に向かうこと。意味が通らない"], "ex": "兄は文系に進んだ。<b>これに対し</b>、弟は理系を選んだ。"},
"204_3": {"point": "近くに同じチェーンの店が集まると客を奪い合うので、収益が悪くなるおそれがある。「〜かねない（〜するおそれがある）」が入る。", "opts": ["悪化するというものではない：「必ずしも悪化するわけではない」の意で、加盟店の不利を述べる流れと合わない", "悪化しないとでもいうべきだ：「悪化しない」では、加盟店どうしが客を奪い合うという前の内容と矛盾する", "悪化しない次第である：「〜次第だ」は事情の説明で、意味が反対になる", ""], "ex": "このまま放っておくと、大きな事故につながり<b>かねない</b>。"},
"204_4": {"point": "公取が改革を迫る理由を、前の段落の「社会インフラとしての機能」から筆者が推測している。「〜したためだろう」が入る。", "opts": ["考慮するというのだ：「〜というのだ」は言い換えや伝聞で、理由の推測にならない", "", "考慮するのだそうだ：伝聞で、筆者が推測する文脈と合わない", "考慮したまでのことだ：「ただそれだけのことだ」の意で、意味が合わない"], "ex": "道が混んでいるのは、近くで祭りがある<b>ためだろう</b>。"},
"205_0": {"point": "お母さんがしてくれることを次々に挙げている。前の内容に加えて、さらに付け加えるので「それだけではなく」が入る。", "opts": ["そうとはいえ：「そうは言っても」という逆接。後に同じ方向の例が続くので合わない", "それにせよ：「いずれにせよ（どちらにしても）」に近い意味で、例を付け加える接続にはならない", "それにしては：「それから予想されるのとは違って」の意で、意味が通らない", ""], "ex": "この店は安い。<b>それだけではなく</b>、味もいい。"},
"205_1": {"point": "結婚するとどうなるかを一般的に説明している部分なので、「〜のです」で事情を説明する「見始めるのです」が入る。", "opts": ["見始めてきたのです：「〜てきた」はこれまでの変化の経過を表し、結婚後に起こることを一般的に説明するこの文には合わない", "", "見始めてはいられません：「〜てはいられない」は「〜している余裕がない」。意味が通らない", "見始めるまでのことです：「ただそれだけのことだ」の意で、説明の流れと合わない"], "ex": "一緒に暮らし始めると、相手の細かい習慣が気になり始める<b>のです</b>。"},
"205_2": {"point": "「果ては（最後には）」と呼応して、普通なら気にならないような小さなこと「さえ」気になり始める、という極端さを表す「まで」が入る。", "opts": ["", "より：比較を表し、意味が通らない", "は：取り立ての「は」では、「果ては」が表す極端さが出ない", "ぐらい：「せめて〜ぐらい」のように最低限を表し、極端な例の強調にならない"], "ex": "緊張して、自分の名前<b>まで</b>忘れてしまった。"},
"205_3": {"point": "前の文「社会に出たら、絶対に1人暮らしをするべきです」に続き、そうして家事の面倒さを体で知るべきだ、と勧めている。「身をもって知るべきです」が入る。", "opts": ["身をもって知ったのです：過去の事実を述べる形で、読者への勧めになっていない", "身をもって知る限りです：「〜限りだ」は「うれしい限りだ」のように感情を強めるときに使い、不自然", "", "身をもって知ったわけです：過去の結論を述べる形で、勧めの文脈と合わない"], "ex": "親のありがたさは、一人暮らしをして<b>身をもって知るべきだ</b>。"},
"205_4": {"point": "自分で家事の面倒さを知れば、相手のやり方が多少違っても「自分がやるよりはいい」と思えるので、愚痴を言わなくてよい。「〜ずに済む」が入る。", "opts": ["こぼしてやみません：「〜てやまない」は「心から〜し続ける（願ってやまない）」で、愚痴には使わない", "", "こぼすにかたくありません：「〜にかたくない」は「想像にかたくない」のように使い、意味が通らない", "こぼすのだそうです：伝聞で、筆者の主張の結論にならない"], "ex": "早めに準備しておけば、当日慌て<b>ずに済む</b>。"},
"20026": {"point": "「〜とあって」は「〜という特別な事情なので」という意味で、後には人が集まる・喜ぶなど、その事情から当然起こる様子が来る。講演会が無料という特別な事情でファンが詰めかけた。", "opts": ["にして：「〜にして」は「〜であって同時に（医者にして作家）」や「〜になってやっと（40歳にして）」の意。理由は表さない", "にあって：「〜にあって」は「〜という状況・立場で（非常時にあって）」。理由と結果の関係が表せない", "として：「〜として」は立場や資格（代表として）。「無料として」では意味が通らない", ""], "ex": "連休初日<b>とあって</b>、高速道路はどこも渋滞している。"},
"20027": {"point": "「〜につけ」は「〜するたびに、いつも」という意味で、「聞くにつけ・見るにつけ」の形で、ある気持ちが自然に起こることを表す。後の「つくづく感じる」と合う。", "opts": ["", "なり：「〜なり」は「〜するとすぐに（帰るなり寝た）」。毎回自然に感じる気持ちは表せない", "とは：「〜とは」は定義や驚き（〜とは知らなかった）。意味が通らない", "にしてみると：「〜にしてみると」は「〜の立場から考えると（親にしてみると）」で、人を表す名詞に付く"], "ex": "故郷の写真を見る<b>につけ</b>、子どもの頃を思い出す。"},
"20028": {"point": "「〜に〜にと」は、例を並べて「〜にも〜にも、いろいろと」という意味を表す。後の「何にでも使えて」とつながる。", "opts": ["は：「揚げ物には」では、いろいろな例を並べる意味にならない", "", "や：「〜や」は名詞を並べるときに使い、「〜に〜にや」という形は不自然", "か：「〜か」は選択を表し、「何にでも」と合わない"], "ex": "週末は掃除に洗濯に<b>と</b>、休む暇がない。"},
"20029": {"point": "「〜させられたあげく」は、嫌なのに〜させられて、その末によくない結果になった、という意味。主語は「私」で、担当者に質問に答えさせられた（使役受身）。「あげく」は過去の出来事なので、た形が入る。", "opts": ["させた：使役で、私が担当者に答えさせたことになり、意味が逆", "させられる：使役受身だが、「あげく」には過去のた形が付く", "させる：使役で意味が逆。また「あげく」にはた形が付く", ""], "ex": "さんざん待たされた<b>あげく</b>、今日は診察できないと言われた。"},
"20030": {"point": "「〜ではないか」は、驚いて思いがけないことに気づいたときの言い方（「なんと〜た」）。動詞のた形に直接付く。電車が反対方向に走り始めたことに驚いている。", "opts": ["ではない：否定になり、後の「後悔した」と矛盾する", "", "のではない：「〜のではない」は否定の説明で、驚きを表さない", "のではないか：推量（〜だろう）を表し、目の前の事実に驚く表現にならない"], "ex": "箱を開けてみると、中は空っぽ<b>ではないか</b>。"},
"20031": {"point": "「お客様に食事を出す」のは店側（自分）の行為なので、謙譲語の「お出しする」を使う。「〜以上」は「〜するからには、当然…」という意味で、後の「何よりも注意しております」と合う。", "opts": ["お出しになる以上：「お〜になる」は尊敬語で、自分の行為には使わない", "お出しになるうえ：尊敬語で誤り。また「〜うえ（に）」は「その上さらに」の意", "", "お出しするうえ：謙譲語は正しいが、「〜うえ」は追加を表し、「当然〜する」という意味にならない"], "ex": "引き受けた<b>以上</b>、最後まで責任を持ってやります。"},
"20032": {"point": "「〜でしかない」は「〜にすぎない」という意味。「気付いていなかった」の対象を表す「〜ことに」が付いて、「世界のほんの小さな一部分でしかないことに気付いていなかった」となる。", "opts": ["でないことにしか：「〜にしか気付いていなかった」となり、意味が逆になる", "", "にないことでしか：「一部分にない」は意味が通らない", "にしかないことで：「一部分にしかない」は意味が通らず、「ことで」も「気付く」と合わない"], "ex": "それがうわさ<b>でしかない</b>ことに、彼は最後まで気付かなかった。"},
"20033": {"point": "「〜くらい」は程度を表し、「今までの苦労がばかばかしく思えるほど簡単に計算できた」となる。「思える」は自然にそう感じられること。", "opts": ["ばかばかしい思いをするもので：「〜もので」は理由の説明になり、「簡単に計算できた」の程度を表せない", "ばかばかしく思えるもので：①と同じく理由の形で、程度を表せない", "ばかばかしい思いをするくらい：「〜思いをする」は人が実際にそういう体験をすることで、「今まであんなに時間をかけてたのが」を受けられない。「〜のがばかばかしく思える」なら自然", ""], "ex": "それまでの悩みがうそに思える<b>くらい</b>、気分がすっきりした。"},
"20034": {"point": "原稿ができていない木村先生が、あと3日待ってほしいと出版社の人に頼んでいる。「〜ていただくわけにはいきませんか」は、相手に丁寧に頼む言い方。", "opts": ["待っておいでになります：尊敬語で、相手が待っていることを述べるだけになり、頼む文にならない", "お待ち申し上げております：謙譲語で、自分が待っている意味になる", "待たせていただくことにしましょうか：自分が待つ意味になり、立場が逆", ""], "ex": "申し訳ありませんが、締め切りを延ばしていただく<b>わけにはいきませんか</b>。"},
"20035": {"point": "「〜かっていうと」は「〜かというと（そうではない）」という話し言葉。後の「そうじゃないんです」と呼応し、初めから宇宙飛行士になるつもりだったわけではない、という意味になる。", "opts": ["", "つもりなのかっていわれたら：今のつもりを聞かれたことになり、「医者になろうと思っていましたから」という過去の話と合わない", "つもりじゃなかったのかっていわれたら：否定の形で、「そうじゃないんです」と組み合わせると意味が逆になる", "つもりがなかったかっていうと：否定の形で、「そうじゃない」と言うと「つもりがあった」ことになり、後の話と矛盾する"], "ex": "毎日料理をする<b>かっていうと</b>、そうでもないんです。"},
"20036": {"point": "「〜ということのないように」は「〜ということが起こらないように」という意味で、望ましくない事態を防ぐために前もって何かをするときに使う。", "steps": "「迷ってしまった」の後に「という」が来て、名詞「こと」を説明する。「ことの」の「の」は「が」と同じ働きで、「ことのない（＝ことがない）」となる。最後の「ように」が目的を表して「事前に見学しておくとよい」につながる。", "ex": "忘れ物をする<b>ということのないように</b>、前の晩に準備しておこう。"},
"20037": {"point": "「〜てまで」は「そこまで極端なことをして」、「〜となると」は「そういう場合になると」という意味。極端な手段を取ることへの批判を表す。", "steps": "「犠牲」には「にして」が付いて「犠牲にして」、極端さを表す「まで」が続く。そのあと「となる」「と」で「となると」となり、「それはちょっと問題です」につながる。", "ex": "借金をし<b>てまで</b>ブランド品を買う必要はない。"},
"20038": {"point": "「たとえ〜ても」は「仮に〜でも」、「〜だとして」は「〜だと考えて・〜だということにして」という意味。", "steps": "「たとえ」は「〜ても」と呼応するので、「自分には責任」「がなくても」が続く。そのあと「自分の責任」「だとして」で、部下の失敗を自分のこととみなす意味になり、「部下の失敗も引き受ける」につながる。", "ex": "たとえ失敗し<b>ても</b>、挑戦したことに意味がある。"},
"20039": {"point": "「今でこそ〜が」は「今は〜だが、以前はそうではなかった」という意味。過去と現在を対比するときに使う。", "steps": "「今でこそ」で始め、現在の様子「一流企業と言われる」が「我が社だが」を修飾する。逆接の「が」の後に、以前の様子を表す「もともとは」が来て、「小さな町工場だった」につながる。", "ex": "<b>今でこそ</b>人気の店だが、開店当初は客がほとんど来なかった。"},
"20040": {"point": "「〜かと思いきや」は「〜と思ったが、意外にもそうではなかった」という意味。予想と違う結果を述べるときに使う。", "steps": "「役作りに悩んでいる」に疑問の「のか」が付き、「と」「思いきや」が続く。予想とは違う結果「そうでもない」が、伝聞の「という」につながる。", "ex": "簡単に勝てる<b>かと思いきや</b>、試合は延長戦になった。"},
"20041_0": {"point": "後に「が、モンダイはその入り方のタイミングだ」と逆接が続くので、まずＣＭが入ること自体は認めている。「入るのはいい（入ること自体はかまわない）」が入る。", "opts": ["入るのにいい：「〜のにいい」は「〜するのに適している」の意で、意味が通らない", "入るのがいいのか：疑問の形で、後の「が、モンダイは〜」とつながらない", "", "入るのでいいのか：疑問の形で、ＣＭが入ること自体を疑うことになり、後の流れと合わない"], "ex": "安いの<b>はいい</b>が、品質が心配だ。"},
"20041_1": {"point": "筆者は広告主に「お願いをしたい」と書いている。せこいＣＭの入れ方をやめてもらいたいという、相手への要望の「やめてほしいのだ」が入る。", "opts": ["やめようと思う：自分がやめる意味になる。ＣＭを入れているのは筆者ではない", "", "やめるのだろうか：疑問・推量で、お願いの文にならない", "やめられるものではない：「やめることはできない」の意で、筆者の主張と逆"], "ex": "夜遅くに大きな音で音楽を聴くのは、<b>やめてほしい</b>。"},
"20041_2": {"point": "「たしかに〜ことは間違いない。が、〜」は、相手の言い分をいったん認めてから反論する形。身を乗り出している瞬間にＣＭを入れれば見られることは確かだが、そのやり方はさもしい、という流れになる。", "opts": ["やはり／ところだった：「〜ところだった」は「もう少しで〜しそうだった」の意で、意味が通らない", "いったい／のか：疑問の形で、後の「が、〜」という反論の流れにならない", "といっても／わけでもない：「見られるわけでもない」と否定すると、後の反論とつながらない", ""], "ex": "<b>たしかに</b>便利になった<b>ことは間違いない</b>。が、失ったものも多い。"},
"20041_3": {"point": "企業が視聴者に、いやでもＣＭを見させる、という意味。主語は企業（ＣＭの出し方）で、視聴者に見させるので使役の「見させてしまう」が入る。", "opts": ["", "身を乗り出させる：身を乗り出すのは番組の盛り上がりによるもので、ＣＭの出し方が強制していることではない", "見られてしまう：受身で、企業の側が見られる意味になり、主語と合わない", "身を乗り出される：受身で、意味が通らない"], "ex": "子どもに嫌いな野菜を無理に食べ<b>させる</b>のはよくない。"},
"20041_4": {"point": "「ぼくだけじゃない、みんな（も）だいぶ前から怒ってるよ」となる。筆者自身（ぼく）が不満を述べてきた文章なので、筆者だけでなく視聴者みんなが怒っている、と結んでいる。", "opts": ["", "広告主／みんな：怒っているのは視聴者側で、広告主ではない", "広告主／ぼくも：②と同じく、広告主が怒っていることになり不自然", "ぼく／広告主も：広告主は筆者がお願いしている相手で、「品がねえぞ」と怒る側ではない"], "ex": "<b>ぼく</b>だけじゃない、<b>みんな</b>そう思っているよ。"},
"21026": {"point": "「〜をよそに」は「〜を気にしないで・関係ないという態度で」という意味。混雑を気にせずパソコンを広げている様子を表す。", "opts": ["含めて：「〜を含めて」は「〜も入れて」。意味が通らない", "もとに：「〜をもとに」は「〜を材料・根拠にして」。意味が通らない", "除いて：「〜を除いて」は「〜以外」。混雑を除くことはできない", ""], "ex": "家族の心配<b>をよそに</b>、彼は一人で山に登った。"},
"21027": {"point": "「ます形の語幹＋もしないで」は「当然すべき〜さえしないで」と強く非難する言い方。漫画を読みさえしないで批判する父への不満を表す。", "opts": ["読まない：「読まないもしないで」という形はない", "", "読もう：意向形は「もしないで」に接続しない", "読んで：て形は「もしないで」に接続しない"], "ex": "彼はろくに調べ<b>もしないで</b>、無理だと決めつけた。"},
"21028": {"point": "「もっとも」は、前に述べたことに補足や少し反対の内容を付け加えるときに使う（ただし）。チームワークの大切さを痛感したが、実は気づいたのは去年だった、と付け加えている。", "opts": ["要するに：前の内容をまとめる言い方。後の内容はまとめになっていない", "あるいは：「または」の意。二つのうちのどちらかを表す", "", "ついては：「そのことに関連して（お願いがあります）」と、依頼や案内を続けるときに使う"], "ex": "この店の料理はおいしい。<b>もっとも</b>、値段は少し高いが。"},
"21029": {"point": "主語は90歳の元村長の東山さんなので、尊敬語を使う。「〜ておいでになる」は「〜ていらっしゃる」と同じ尊敬語で、「覚えておいでになり」となる。", "opts": ["", "差し上げ：「あげる」の謙譲語。「覚えて差し上げる」では意味が通らない", "まいり：「行く・来る」の謙譲語で、相手の行為には使えない", "申し上げ：「言う」の謙譲語で、相手の行為には使えない"], "ex": "先生は、私が卒業した年のことを今も覚えて<b>おいでになる</b>。"},
"21030": {"point": "「〜に越したことはない」は「〜であるほうがいい（が、絶対に必要というわけではない）」という意味。後の「が、それよりも人柄や姿勢を重視しています」と逆接でつながる。", "opts": ["にすぎません：「〜にすぎない」は「ただ〜だけだ」。「知識はあるにすぎません」では意味が通らない", "ことは否めません：「〜ことは否めない」は「〜ことは否定できない」。応募者を安心させる回答と合わない", "", "といっても過言ではありません：「〜と言っても言いすぎではない」。後の「それよりも人柄を重視」と矛盾する"], "ex": "経験はある<b>に越したことはない</b>が、なくても応募できる。"},
"21031": {"point": "「〜次第では」は「〜によっては（その結果、ある事態になることもある）」という意味。復旧状況によっては営業再開が遅れる可能性がある、となる。", "opts": ["次第には：こういう形はない", "次第に：副詞「次第に」は「だんだん」の意で、意味が通らない", "", "次第：名詞に付く「次第」は「〜次第だ」「〜次第で」の形で使い、「次第、」だけで後の文につなげることはできない（「ます形の語幹＋次第」なら「〜したらすぐ」の意）"], "ex": "天候<b>次第では</b>、試合が中止になることもある。"},
"21032": {"point": "クレジットカードの番号は、他人に知られると困る情報。受身の「知られる」に「〜ては困る」が付いて、「知られては困る」となる。", "opts": ["知っていても：他人が知っていても、の意で、「困る」とつながらない", "知っていなくても：意味が通らない", "知らなくては：「知らなくては困る」は「知らないと困る」で、意味が逆", ""], "ex": "人に見られ<b>ては困る</b>書類は、引き出しにしまっておこう。"},
"21033": {"point": "「〜ばいいというものではない」は「〜すればそれで十分だとは言えない」という意味。前の「いかに成果を上げるかが大切」と合わせ、時間をかけてがんばるだけでは不十分だ、という意見になる。", "opts": ["がんばることだといってもおかしくない：「がんばることだと言える」の意で、前の内容と矛盾する", "", "がんばることでしかない：「がんばることにすぎない」の意で、意味が通らない", "がんばりようがない：「がんばる方法がない」の意で、意味が通らない"], "ex": "安けれ<b>ばいいというものではない</b>。品質も大切だ。"},
"21034": {"point": "「〜ものと思われる」は「〜だろうと考えられる」と客観的に推量する書き言葉。主語の「地質構造が」に合わせて自動詞「なる」を使い、「明らかになるものと思われる」となる。", "opts": ["", "するという思いがある：「明らかにする」は他動詞で主語と合わない。「思いがある」も個人的な気持ちを表す", "なったかに思える：「すでに明らかになったように見える」の意で、「いずれ近いうちに」と合わない", "するだろうと思う：他動詞「する」が主語と合わない。「〜と思う」も個人的な言い方で、論文調の文に合わない"], "ex": "新しい薬は、来年には販売される<b>ものと思われる</b>。"},
"21035": {"point": "「〜させてもらおうかと思って」は、自分がしたいことを、相手の許しを得る形で控えめに伝える言い方。後に西村先輩が「辞める？」と聞き返しているので、山下さんが辞めたいと伝えている。", "opts": ["辞めてしまわれたのでしょうか：尊敬語で、相手が辞めたかを尋ねる形になる", "辞めてしまったのかと思って：すでに辞めたと思ったという意味で、これから辞める話と合わない", "辞めさせたらどうでしょうか：誰かを辞めさせることを提案する意味になる", ""], "ex": "今日は体調が悪いので、早めに帰ら<b>せてもらおうかと思って</b>。"},
"21036": {"point": "「〜に由来する」は「〜がもとになっている・〜から来ている」という意味。名前や言葉の起こりを説明するときに使う。", "steps": "「アセビには」の後に「有毒成分があり」が来る。続いて「馬が食べると酔ったような」が「状態になることに」を修飾し、「由来する」が文末の「そうです」につながる。", "ex": "この町の名前は、昔ここにあった大きな寺に<b>由来する</b>。"},
"21037": {"point": "「人に〜を気づかせる」は、使役の形で「その人が〜に気づくようにする」という意味。「〜てくれる」で、それがありがたいという気持ちを表す。", "steps": "「つい」は「仕事に夢中になりすぎる」を修飾し、それが「私に」を説明する。気づかせる内容「本当に大切なものは何なのか」の後に「気づかせてくれる」が来て、「ありがたい存在です」を修飾する。", "ex": "この本は、私に読書の楽しさを<b>気づかせてくれた</b>。"},
"21038": {"point": "「〜ことに対し」は「〜ことについて」という意味で、相手の行為に反論・抗議するときによく使う。「など」は内容をぼかして引用する言い方。", "steps": "「脱税を行った」は「疑いがあるなどと」につながり、「報じられた」が続く。そのあと「ことに対し」が来て、反論の内容「事実とは全く」が文の「異なり」につながる。", "ex": "住民の要望<b>に対し</b>、市は早急に対応すると答えた。"},
"21039": {"point": "「〜てのことだ」は「〜したうえでのことだ・〜したからだ」という意味で、ある行動の理由を説明する。文末の「という」は伝聞。", "steps": "「判断」に「して」が付き、「の」「ことだ」が続いて「判断してのことだ」となる。最後に伝聞の「という」が来る。", "ex": "彼が厳しいことを言うのも、君のためを思っ<b>てのことだ</b>。"},
"21040": {"point": "「〜ほど…ない」は「〜と言えるほど…ではない」という意味。「資格を取っただけで希望の職につける」と言えるほど、世間は甘くない。", "steps": "「資格を取った」に「だけ」「で」が付いて「取っただけで」となる。そのあと「希望の職につける」が来て、程度を表す「ほど」が文末の「世間は甘くない」につながる。", "ex": "一晩勉強しただけで合格できる<b>ほど</b>、試験は簡単ではない。"},
"21041_0": {"point": "マニュアル通りに動く機械と違って、生き物には個性がある。「あちらに通用したことが、こちらに通用するとは限らない」という意味の「こちらにいえるとは限らない」が入る。", "opts": ["こちらにはいえないこともない：「言えなくはない（少しは言える）」の意で、生き物の違いを強調する前の文と合わない", "", "こちらにもいえるとは思わなかった：「同じだと思わなかった」の意で、前の文とつながらない", "こちらにはいえないと思うのか：反問の形で、文章の流れと合わない"], "ex": "高ければよいもの<b>とは限らない</b>。"},
"21041_1": {"point": "前の段落の「ねこを飼い始めた当座は、何も分からなかった」時期を受けて、「そういう時に」と指している。", "opts": ["", "する：「する時に」では、何をする時か分からない", "あの：「あの時」は話し手と聞き手が共通に知っている過去を指す。直前の内容を受けるには「そういう」が自然", "やろうという：「やろうという時に」では何をやろうとするのか分からない"], "ex": "引っ越したばかりで何もわからなかった。<b>そういう</b>時に助けてくれたのが隣の人だった。"},
"21041_2": {"point": "「中でも納得したのが、〜」と、マニュアルの中で特に納得した内容を、名詞で取り上げている。次の段落でトイレの説明が引用されるので「トイレのことだ」が入る。", "opts": ["", "トイレのことであるに違いない：自分が納得した内容を推量するのは不自然", "トイレだからである：理由を述べる形で、「納得したのが」と合わない", "トイレだと聞いている：伝聞で、自分で読んで納得した話と合わない"], "ex": "この本で一番印象に残ったのは、最後の場面<b>のことだ</b>。"},
"21041_3": {"point": "マニュアル通りに遠慮していたのに、実際のゆずは人のいるトイレにわざわざ入ってくる。予想と違う展開を導く「ところがである」が入る。", "opts": ["もっともである：前の内容に賛成する言い方で、後の意外な展開と合わない", "当然である：①と同じく、後の意外な内容と合わない", "", "例えばである：例を挙げる言い方で、前と反対の展開を導けない"], "ex": "準備は完璧だと思っていた。<b>ところがである</b>、当日になって大雪が降った。"},
"21041_4": {"point": "ゆずのトイレの出来事は、生き物には個性があることを改めて感じさせられる出来事だった、と文章をまとめている。「認識させられる出来事だった」が入る。", "opts": ["認識させられたことがある：経験の有無を言う形で、この出来事のまとめにならない", "認識させられたおかげだ：「〜おかげだ」は恩恵の理由を表し、意味が通らない", "認識させられる話があった：他人から聞いた話のようになり、自分の体験のまとめにならない", ""], "ex": "健康の大切さを改めて考えさせられる<b>出来事だった</b>。"},
"22026": {"point": "「〜ねばならない」は「〜なければならない」の書き言葉。火山灰が降っている間、住民は屋内で過ごす必要がある、という意味になる。", "opts": ["", "過ごすほどのことではない：「そこまでする必要はない」の意で、火山灰が降る状況と合わない", "過ごすにあたらない：「〜にあたらない」は「〜する必要はない」。状況と合わない", "過ごしてもさしつかえない：「〜してもかまわない」という許可で、必要性を表さない"], "ex": "約束は守ら<b>ねばならない</b>。"},
"22027": {"point": "「ます形の語幹＋もしないで」は「当然すべき〜さえしないで」と強く非難する言い方。企画書を読みさえしないで放っておいた上司への不満を表す。", "opts": ["読もう：意向形は「もしないで」に接続しない", "読め：命令形は「もしないで」に接続しない", "読まない：「読まないもしないで」という形はない", ""], "ex": "彼はろくに調べ<b>もしないで</b>、無理だと決めつけた。"},
"22028": {"point": "「〜といったところだ」は「だいたい〜ぐらいだ」と、程度や範囲をおおよそ示す言い方。航空券の値段の目安を述べている。", "opts": ["ときたら：「〜ときたら」は話題を取り上げて不満などを述べる。値段の目安を表さない", "としたところ：「〜としたところ」は「〜したら（結果）」の意で、意味が通らない", "というわけ：「〜というわけだ」は結論や理由の説明で、おおよその範囲を表さない", ""], "ex": "通勤時間は、片道30分<b>といったところ</b>です。"},
"22029": {"point": "インタビューで相手に気持ちを話してもらうよう頼んでいる。「お聞かせ願えますか」は「聞かせてもらえますか」の丁寧な依頼表現。", "opts": ["ご説明なさいますか：尊敬語で相手に説明するかどうかを尋ねる形になり、依頼にならない", "申し上げてください：「申し上げる」は謙譲語で、相手の行為には使えない", "お聞きください：自分の話を相手に聞いてもらう依頼になり、立場が逆", ""], "ex": "今後の目標を<b>お聞かせ願えますか</b>。"},
"22030": {"point": "「〜ゆえに」は「〜ので・〜から」という意味の硬い書き言葉。乾燥が火事の原因の一つであるから、注意が必要だ、という理由と結果の関係。", "opts": ["べく：「〜べく」は「〜するために」という目的。「あるべく」では意味が通らない", "", "や否や：「〜や否や」は「〜するとすぐに」。意味が通らない", "ごとく：「〜ごとく」は「〜のように」。理由を表さない"], "ex": "若さ<b>ゆえに</b>、失敗することもある。"},
"22031": {"point": "電車が止まっているので、これから時間に間に合わないだろうと推測して、先に始めていいと伝えている。「間に合わなさそうだ」は「間に合わないようだ」という様子からの推量。", "opts": ["間に合いそうだから：間に合うなら先に始める必要がなく、意味が矛盾する", "間に合いそうになかったから：過去の形で、これからのことを伝える文に合わない", "", "間に合わなかったから：送別会はまだ始まっておらず、過去の形は合わない"], "ex": "雨はしばらく止ま<b>なさそう</b>だから、タクシーで帰ろう。"},
"22032": {"point": "「〜ようがない」は「〜する方法がない・〜しようとしてもできない」という意味。連絡が取れないので、伝えたくても伝える方法がない。", "opts": ["", "伝えたって仕方がありません：「伝えても意味がない」の意で、「伝えたくても」と合わない", "伝わないではおかないです：「伝う（つたう）」の形になってしまい（「伝える」なら「伝えないではおかない」）、意味も通らない", "伝えばいいというものではないです：「伝う（つたう）」の形になってしまい（「伝える」なら「伝えればいい」）、意味も通らない"], "ex": "住所がわからないので、手紙の送り<b>ようがない</b>。"},
"22033": {"point": "「ます形の語幹＋次第」は「〜したらすぐに」という意味で、お知らせなどの改まった文で使う。点検が終わったらすぐに営業を再開する。", "opts": ["", "次第には：こういう形はない", "次第に：副詞の「次第に」は「だんだん」の意。「終わり次第に」とは言わない", "次第では：「名詞＋次第では」は「〜によっては」の意で、ます形には付かない"], "ex": "詳しいことがわかり<b>次第</b>、ご連絡いたします。"},
"22034": {"point": "「〜たところで」は「〜しても（期待する結果にはならない・むだだ）」という意味。後の「時間の無駄だよ」と合う。", "opts": ["後悔しただけに：「〜だけに」は「〜なのでなおさら」の意で、後の内容とつながらない", "", "後悔したところを：「〜ところを」は「〜している場面を（見られた）」などの意で、意味が通らない", "後悔はさておき：「〜はさておき」は「〜は後回しにして」の意で、意味が通らない"], "ex": "今から急いだ<b>ところで</b>、もう間に合わない。"},
"22035": {"point": "「AあってのB」は「Aがあるからこそ、Bが成り立つ」という意味。体調を崩して何もかもうまくいかなくなったので、すべては健康があってこそだ、と実感している。", "opts": ["", "からある：「数量＋からある」は数量の多さを強調する（20キロからある荷物）。名詞「健康」には合わない", "ながらの：「〜ながらの」は「〜のままの（昔ながらの）」の意で、意味が通らない", "ならではの：「〜ならではの」は「〜だけが持つ」。健康の大切さを表せない"], "ex": "お客様<b>あっての</b>商売だということを忘れてはいけない。"},
"22036": {"point": "「動詞の辞書形＋べく」は「〜するために」という目的を表す書き言葉。", "steps": "「歯止めをかける」に「べく」が付いて目的を表す。そのあと「様々な」が「取り組みが」を修飾し、「行われている」で文が終わる。", "ex": "夢を実現する<b>べく</b>、毎日努力を続けている。"},
"22037": {"point": "「AもさることながらB（も）」は「Aはもちろん、Bも」という意味で、AもBもよいと評価するときに使う。", "steps": "「性能も」の後に「さることながら」が来て、もう一つの長所「値段もリーズナブルで」が続く。その結果の「売り上げが」「ますます伸びている」で文が終わる。", "ex": "この店は料理の味<b>もさることながら</b>、店員の対応も素晴らしい。"},
"22038": {"point": "「〜つつある」は「〜している途中だ」と、変化が少しずつ進んでいることを表す書き言葉。", "steps": "「経済低迷が続く中」の後に主語の「失業者は」が来て、「増えつつあり」が続く。そのあと「経済的に」が「苦しんでいる」を修飾し、「人々」を説明する。", "ex": "この町の人口は、年々減り<b>つつある</b>。"},
"22039": {"point": "「〜と言わんばかりの」は「今にも〜と言いそうな」という意味で、後に名詞が来る。「〜でさえ」は「〜でも（ほかはなおさら）」。", "steps": "「辞任の表明をする」は「記者会見でさえ」を修飾する。そのあと「自分には」「責任がないと」が続き、「言わんばかりの」が文末の「態度だった」を修飾する。", "ex": "彼は「早く帰れ」と<b>言わんばかりの</b>顔で私を見た。"},
"22040": {"point": "「〜を契機に」は「〜をきっかけにして」という意味。", "steps": "「遠隔医療」に「を契機に」が付く。そのあと「通信インフラが」「整備され」が続き、「医療費増加問題」が文中の「の解決」につながる。", "ex": "留学<b>を契機に</b>、海外の文化に関心を持つようになった。"},
"22041_0": {"point": "「半端ではない」は「程度が普通ではない・ものすごい」という意味の話し言葉。夏の暑さが非常に厳しかったことを表す。", "opts": ["", "半端になった：「中途半端になった」の意で、暑さの厳しさを表さない", "半端ならざるを得なかった：こういう言い方はしない", "中途半端だった：「どっちつかずだった」の意で、続く「風が完全に熱風だった」と合わない"], "ex": "この店のラーメンは、量が<b>半端ではない</b>。"},
"22041_1": {"point": "「〜わけにもいかない」は「事情があって〜することもできない」という意味。夜は氷まくらでしのげたが、日中は氷をぶらさげておくこともできず、つらかった。", "opts": ["", "ぶらさげておくわけがなく：「〜わけがない」は「〜はずがない」の意で、意味が通らない", "ぶらさげておくわけで：「〜わけで」は理由や結論の説明。「つらかった」とつながらない", "ぶらさげておくわけではなく：「〜わけではない」は部分否定で、意味が通らない"], "ex": "熱があったが、大事な会議なので休む<b>わけにもいかず</b>、出社した。"},
"22041_2": {"point": "前の「動くクロをほとんど見ることなく、この夏が過ぎました」が原因で、後の「体重増加」が結果。順接の「なので」が入る。", "opts": ["むしろ：「どちらかといえば」の意で、比較を表す", "ところが：逆接で、因果関係が表せない", "", "一方で：対比を表し、因果関係が表せない"], "ex": "雨が降っていた。<b>なので</b>、出かけるのをやめた。"},
"22041_3": {"point": "暑くても夏バテしない理由を、筆者が推測している。「よく食べ、よく寝ているからでしょうか」と理由を控えめに述べる形が入る。", "opts": ["よく寝ているぐらいでしょう：「ぐらい」は程度を表し、理由にならない", "よく寝ているせいです：「〜せい」は悪い結果の原因に使い、夏バテしないというよい結果には合わない", "よく寝ているからだとは限らないです：理由を否定することになり、前の内容と合わない", ""], "ex": "最近元気なのは、毎朝散歩している<b>からでしょうか</b>。"},
"22041_4": {"point": "今日の煮豚の作り方について、筆者が自分で決めたことを述べている。「〜ことにしました」が入る。", "opts": ["仕上げずにはおかないです：「必ず〜する」の硬い表現で、料理の話に合わない", "", "仕上げるのをお勧めします：読者への勧めになり、「今日は」という自分の話と合わない", "仕上げればよかったです：後悔を表し、これから作る話と合わない"], "ex": "健康のため、毎朝30分歩く<b>ことにしました</b>。"},
"23026": {"point": "先生に論文について質問したいので、「聞く・尋ねる」の謙譲語「伺う」を使う。", "opts": ["拝見したい：「見る」の謙譲語。「先生に拝見したい」は意味が通らない", "", "お目にかかりたい：「会う」の謙譲語。「先生にお目にかかりたいことがある」とは言わない", "お聞きになりたい：尊敬語で、自分の行為には使えない"], "ex": "来週のご予定について、少し<b>伺いたい</b>のですが。"},
"23027": {"point": "「〜を余儀なくされる」は「望まないが、〜しなければならなくなる」という意味。輸出額の減少で、給料の削減をせざるを得なくなった。", "opts": ["しようにもできない：「したくてもできない」の意で、削減したいわけではない文脈と合わない", "せずにはおかない：「必ず〜する・自然に〜させてしまう」という強い意志や作用を表し、望まないのにやむを得ずする、という意味にならない", "", "するまでもない：「する必要がない」の意で、前の状況と矛盾する"], "ex": "台風のため、イベントは中止<b>を余儀なくされた</b>。"},
"23028": {"point": "「〜とあって」は「〜という特別な事情なので」という意味。ベストセラー作家の新作という特別な事情なので、予約が殺到している。", "opts": ["ごとき：「〜ごとき」は「〜のような（私ごとき）」。理由を表さない", "", "あっての：「〜あっての」は「〜があるからこそ成り立つ」。後に名詞が必要で、意味も合わない", "とはいえ：「〜とはいえ」は逆接で、予約が殺到する結果と合わない"], "ex": "人気の歌手が出演する<b>とあって</b>、チケットはすぐに売り切れた。"},
"23029": {"point": "パワハラが辛いという話の後なので、会社を辞めたいほどだ、と気持ちの強さを表している。「辞めさせてもらいたい」は「（許しを得て）辞めたい」、「ぐらい」は程度の大きさを表す。", "opts": ["", "辞めてしまえばいいもんなんだから：「辞めればいい」と突き放す言い方で、自分の辛さを訴える文と合わない", "辞めさせられても仕方がないんだから：自分に責任があって辞めさせられる意味になり、パワハラの被害の話と合わない", "辞めてみせるんだから：「〜てみせる」は強い決意で、辛さを訴える文と合わない"], "ex": "毎日残業ばかりで、もう逃げ出したい<b>ぐらい</b>なんだ。"},
"23030": {"point": "「〜といったらありゃしない」は「とても〜だ」という意味の話し言葉（「〜といったらない」のくだけた形）。安全性を証明したのに副作用を訴える人が出て、非常に困っている気持ちを表す。", "opts": ["", "ほどのことではない：「それほどではない」の意で、困っている状況と合わない", "きらいがある：「よくない傾向がある」の意で、「困っている」には付かない", "とは限らない：「必ずしも〜ではない」の意で、意味が通らない"], "ex": "夜中に隣の犬がほえて、うるさい<b>といったらありゃしない</b>。"},
"23031": {"point": "「見るに見かねて」は「黙って見ていられなくなって」という意味。誰も席を譲らない様子を見ていられず、僕が譲った。", "opts": ["うってかわって：「がらりと変わって」の意で、意味が通らない", "", "といっても：前の内容を少し否定・修正する言い方で、つながらない", "とはいえ：逆接で、前の内容とつながらない"], "ex": "後輩が困っているのを<b>見るに見かねて</b>、手伝ってあげた。"},
"23032": {"point": "「〜するだに」は「〜するだけでも」という意味で、「想像するだに・考えるだに」の形で後に「恐ろしい」などの感情が来る。", "opts": ["", "の極み：「〜の極み」は最高の程度（光栄の極み）。「想像の極み」では意味が通らない", "のあまり：「〜のあまり」は「〜しすぎて」の意で、「心配のあまり」のように感情の名詞に付く", "にひきかえ：「〜にひきかえ」は「〜と比べて反対に」。意味が通らない"], "ex": "あの事故のことは、思い出す<b>だに</b>胸が痛む。"},
"23033": {"point": "「〜にて」は「〜で」の硬い言い方で、手段や場所を表す。お知らせや案内文でよく使う。", "opts": ["", "とて：「〜とて」は「〜であっても（私とて）」の意で、手段を表さない", "にして：「〜にして」は「〜であって同時に・〜になってやっと」の意", "たりとて：「一円たりとも」のように「〜でさえも（ない）」と最小を強調する言い方"], "ex": "ご質問は、受付窓口<b>にて</b>承ります。"},
"23034": {"point": "「〜に即して（則して）」は「〜に従って・〜に合わせて」という意味。ガイドラインに従って適切に対処する、となる。", "opts": ["にまつわって：「〜にまつわる」は「〜に関係する（〜にまつわる話）」で、動詞を修飾する形は普通使わない", "にいたって：「〜にいたって」は「〜という段階になって（やっと）」。意味が通らない", "にして：「〜にして」は「〜であって同時に・〜になってやっと」。意味が通らない", ""], "ex": "実情<b>に即して</b>、計画を見直す必要がある。"},
"23035": {"point": "「〜にかこつけて」は「〜を口実にして（本当の目的は別）」という意味。行政視察を口実に接待を受けていた疑い、となる。", "opts": ["", "とあって：「〜という特別な事情なので」。疑いの内容を表せない", "を踏まえて：「〜を前提にして」。意味が通らない", "を皮切りに：「〜を最初にして（次々に）」。意味が通らない"], "ex": "彼は出張<b>にかこつけて</b>、観光を楽しんでいた。"},
"23036": {"point": "「〜に転じる」は「（状態や方向が）〜に変わる」という意味。「〜見込みだ」は「〜と予想される」。", "steps": "「男性喫煙者数が」の後に、時を表す「今年」「初めて」が来る。続いて「減少に転じる」が「見込みだ」につながり、「という報告」となる。", "ex": "売り上げは、三年ぶりに増加<b>に転じた</b>。"},
"23037": {"point": "「動詞の辞書形＋べく」は「〜するために」という目的を表す書き言葉。", "steps": "「大掃除をして」の後に「年越しそばを食べる」が来て「風習があり」を修飾する。そのあと時を表す「新年になると」が続き、目的の「初詣にいくべく」が「神社やお寺を訪れる」につながる。", "ex": "新しい技術を学ぶ<b>べく</b>、海外の研修に参加した。"},
"23038": {"point": "「AはおろかBさえ（〜ない）」は「Aは言うまでもなく、もっと簡単なBさえ〜ない」という意味。", "steps": "「あまりにも」は「悲惨な事故に」を修飾する。そのあと「声を出すことは」「おろか」が続き、より簡単な「目をそむけること」が文中の「さえできなかった」につながる。", "ex": "熱が高くて、起き上がること<b>はおろか</b>、話すこと<b>さえ</b>できなかった。"},
"23039": {"point": "「〜にしても」は「〜としても」という意味の逆接で、「〜には及ばない」は「〜ほどではない」。「Aには及ばないにしても、それなりに〜」で、完全ではないがある程度はよい、と評価する。", "steps": "「大手」の後に「には及ばない」が来て、「にしても」が続く。そのあと「それなりに」が「整っている」を修飾し、「と思う」につながる。", "ex": "プロ<b>には及ばないにしても</b>、彼の料理の腕はなかなかのものだ。"},
"23040": {"point": "「名詞＋ならではの」は「〜だけにある特別な」という意味。", "steps": "「地元」に「ならではの」が付き、「こだわりの食材や」を修飾する。そのあと「職人の手によって」「作り上げられた」が文中の「品々」を修飾する。", "ex": "この祭りでは、京都<b>ならではの</b>伝統芸能が見られる。"},
"23041_0": {"point": "部族が大きくなると、遠くの人とのコミュニケーションだけでなく、決まりや言い伝えを次の世代に伝える必要も生まれる。「伝える必要が出てきます」が入る。", "opts": ["", "伝えるまでもないです：「その必要がない」の意で、前の「〜なくてはなりません」と矛盾する", "伝えることは難しいです：問題点の指摘は次の段落で述べられる。ここでは必要性を述べている", "伝えかねます：「伝えることはできない」の丁寧な断りで、意味が通らない"], "ex": "会社が大きくなると、ルールを文書にする<b>必要が出てきます</b>。"},
"23041_1": {"point": "音声は耳で受け取るだけのものなので、話したとたんに消えてしまう。「〜た途端に」は「〜するとすぐに」という意味。", "opts": ["語っただけあって：「〜だけあって」は「さすが〜にふさわしく」の意で、意味が通らない", "", "語ったところで：「〜たところで」は「〜しても（むだだ）」の意で、「消えてしまう」とつながらない", "語ったからには：「〜からには」は「〜した以上は当然」の意で、意味が通らない"], "ex": "家を出た<b>途端に</b>、雨が降り出した。"},
"23041_2": {"point": "「とくに困るのは、〜ことです」の形で、困ることの内容を述べている。優れた語り手が亡くなると伝承が途切れてしまうことが困る。", "opts": ["途切れてもかまわないことです：困ることの説明と矛盾する", "", "途切れるとは思わなかったことです：意外だったという意味で、「とくに困るのは」と合わない", "途切れてしかるべきです：「途切れるのが当然だ」の意で、意味が反対"], "ex": "一番困るのは、急に予定が変わって<b>しまうことです</b>。"},
"23041_3": {"point": "絵は「ある瞬間をとらえて表現するもの」、話し言葉は「時間の流れに沿って展開するもの」で、二つの性質を対比している。「それに対して」が入る。", "opts": ["", "それにもかかわらず：逆接だが、「前の事実から予想されることと違う」場合に使い、対比には合わない", "それと同時に：同時に成り立つことを加える言い方で、対比にならない", "それに基づいて：前の内容を根拠にする言い方で、意味が通らない"], "ex": "兄は外で遊ぶのが好きだ。<b>それに対して</b>、弟は家で本を読むのが好きだ。"},
"23041_4": {"point": "話し言葉と同じく時間的に展開する「文字」に写すのが、最もよい方法だと結論づけている。「最も賢明な方法です」が入る。", "opts": ["", "最も賢明な方法だとは限らないです：結論を否定することになり、文章の流れと合わない", "最も賢明な方法であるがゆえのことです：理由を述べる形で、意味が通らない", "最も賢明な方法になりかねます：「〜かねる」は「〜できない」、「〜かねない」は悪い可能性を表し、どちらも意味が通らない"], "ex": "わからないことは専門家に聞くのが、最も<b>賢明な方法</b>だ。"},
"24026": {"point": "「〜を控えて」は「〜が近くに迫っている時に」という意味。首相の記者会見が迫っていて、会場の緊張が高まっている。", "opts": ["あたって：「〜にあたって」の形で使い、「を」とは結びつかない", "", "あって：「〜あって」では意味が通らない", "あいまって：「〜と相まって」の形で使い、「を」とは結びつかない"], "ex": "試験<b>を控えて</b>、学生たちは図書館で勉強している。"},
"24027": {"point": "「〜ないものか」は「何とかして〜できないだろうか」という強い願望を表す。前の「なんとかして」と呼応する。", "opts": ["ものの：「〜ものの」は「〜けれども」という逆接で、後に文が続く", "ものだ：「〜ないものだ」は「〜しないのが普通だ」という一般論で、願望を表さない", "", "ものを：「〜ものを」は「〜のに」という不満・残念な気持ち"], "ex": "もっと楽に英語が覚えられ<b>ないものか</b>。"},
"24028": {"point": "「〜をよそに」は「〜に関係なく・〜を気にせず」という意味。当初の予想（売れないだろう）に反して、新製品が売れている。", "opts": ["含めて：「〜を含めて」は「〜も入れて」。意味が通らない", "除いて：「〜を除いて」は「〜以外」。意味が通らない", "", "もとに：「〜をもとに」は「〜を材料にして」。予想に基づいて売り上げが伸びるのは不自然"], "ex": "周囲の心配<b>をよそに</b>、彼女は手術から一週間で仕事に戻った。"},
"24029": {"point": "「〜においてさえ」は「〜でも」という意味で、極端な例を挙げて「ほかの場合はなおさらだ」と示す。研究が進んだ現代でも、地震の予知は難しい。", "opts": ["", "においてこそ：「〜でこそ」は「まさに〜で」と強調し、後の「難しい」と逆接の関係にならない", "に対してさえ：「〜に対して」は相手・対象を表し、時代には使わない", "に対してこそ：②③と同じ理由で合わない"], "ex": "医学が進んだ今日<b>においてさえ</b>、治せない病気は多い。"},
"24030": {"point": "「〜を余儀なくされる」は「仕方なく〜しなければならなくなる」という意味。不景気のため、工場を止めざるを得なくなった。", "opts": ["", "の至り：「〜の至り」は「光栄の至り」のように、感情が最高の程度であることを表す", "にかたくない：「想像にかたくない」の形で使い、意味が通らない", "にたえない：「感謝にたえない・聞くにたえない」のように使い、意味が通らない"], "ex": "大雪のため、列車は運休<b>を余儀なくされた</b>。"},
"24031": {"point": "「〜ゆえに」は「〜が原因で・〜ので」という硬い言い方。論文が独創的だったため、当初は理解できる人がいなかった、という理由と結果の関係。", "opts": ["としても：「〜としても」は仮定の逆接。意味が通らない", "からには：「〜からには」は「〜した以上は（当然…）」の意で、名詞に直接は付かない", "といえば：「〜といえば」は話題の提示。理由を表さない", ""], "ex": "その美しさ<b>ゆえに</b>、この花は多くの人に愛されている。"},
"24032": {"point": "「〜べきところを」は「本当は〜するべきなのに（そうしないで）」という意味。素直に謝るべきなのに反抗して、退学処分になった。", "opts": ["謝るべく：「〜べく」は「〜するために」という目的。反抗したことと合わない", "", "謝るべきところに：「ところに」は「ちょうどその時に」の意で、逆接の意味にならない", "謝るまじき：「〜まじき」は「〜してはならない（教師にあるまじき行為）」の意で、後に名詞が必要"], "ex": "本来なら私が伺う<b>べきところを</b>、わざわざお越しいただき恐縮です。"},
"24033": {"point": "主語は90歳の元村長なので、尊敬語を使う。「〜ておいでになる」は「〜ていらっしゃる」と同じ尊敬語で、「覚えておいでになり」となる。", "opts": ["差し上げ：「あげる」の謙譲語。「覚えて差し上げる」では意味が通らない", "まいり：「行く・来る」の謙譲語で、相手の行為には使えない", "", "申し上げ：「言う」の謙譲語で、相手の行為には使えない"], "ex": "先生は、私が卒業した年のことを今も覚えて<b>おいでになる</b>。"},
"24034": {"point": "「どうやら〜ようだ」は「はっきりとは言えないが、どうも〜らしい」という推量。快晴で気温も上がったことから、台風が過ぎ去ったと推測している。文末の「ようだ」と呼応する。", "opts": ["仮に：「仮に〜としたら」のように仮定を表し、「ようだ」と呼応しない", "必ずしも：「必ずしも〜ない」のように後に否定が必要", "くれぐれも：「くれぐれも気をつけて」のように依頼・注意に使う", ""], "ex": "<b>どうやら</b>明日は雨になるようだ。"},
"24035": {"point": "「〜ないとも限らない」は「〜する可能性もある」という意味。今はお説教としか思っていなくても、いつか役に立つかもしれない、と伝えている。", "opts": ["", "立つまでだ：「〜までだ」は「〜するだけだ・〜するしかない」の意で、意味が通らない", "立ってやまない：「〜てやまない」は「願ってやまない」のように心から思い続ける気持ちを表す", "立たないではすまない：「〜ないではすまない」は「〜しなければ許されない」の意で、意味が通らない"], "ex": "油断していると、思わぬ事故が起き<b>ないとも限らない</b>。"},
"24036": {"point": "「〜はともかく」は「〜は別として（今は問題にしない）」、「〜すら」は「〜さえ」という意味。", "steps": "「原因は」に「ともかく」が付く。そのあと「上司への」が「報告すら」を修飾し、「しなかった」が文中の「ことを咎められた」につながる。", "ex": "結果<b>はともかく</b>、最後まであきらめなかったことが大切だ。"},
"24037": {"point": "「AなくしてB（ない）」は「AがなければBはできない」という意味の書き言葉。", "steps": "「労働条件」の後に「の」「改善」が来て、「なくして」が続く。そのあと「あり得ない」が文中の「ことだ」につながる。", "ex": "努力<b>なくして</b>成功はあり得ない。"},
"24038": {"point": "「何かしら（の）」は「はっきりとはわからないが、何か（の）」という意味。", "steps": "「何かしらの」は名詞を修飾するので、「譲れない」「こだわりを」が続く。そのあと「持っていて」が文中の「最高の物を作る」につながる。", "ex": "誰にでも、<b>何かしらの</b>悩みはあるものだ。"},
"24039": {"point": "「〜ともなると」は「〜という段階・立場になると、当然…」、「〜かねない」は「〜するおそれがある」という意味。", "steps": "「海外移住」に「ともなると」が付く。そのあと「国によっては」が続き、「後悔する」「ことにもなりかねない」が文中の「ので」につながる。", "ex": "このまま放っておくと、大きな事故につながり<b>かねない</b>。"},
"24040": {"point": "「〜からには」は「〜のだから、当然…」という意味で、後に義務・決意などが来る。「〜としては」は「〜の立場から言うと」。", "steps": "「特に」は「日本酒に興味のある」を修飾し、「私としては」が続く。そのあと「それを知ったからには」が来て、「それを味わわずに」が文末の「帰ることはできない」につながる。", "ex": "引き受けた<b>からには</b>、最後まで責任を持ってやり遂げる。"},
"24041_0": {"point": "「AはもとよりB」は「Aはもちろん、Bも」という意味。ニュース番組はもちろん、コマーシャルもインタビュー番組も、じかに語りかけてくる、と例を並べている。", "opts": ["をよそに：「〜を無視して」の意で、例を並べる文に合わない", "", "にひきかえ：「〜とは反対に」の意で、同じ特徴を持つものを並べる文に合わない", "といい：「AといいBといい」と二つ以上並べて使う形で、ここでは形が合わない"], "ex": "この映画は子ども<b>はもとより</b>、大人も楽しめる。"},
"24041_1": {"point": "日本とアメリカのニュースで、なぜ「これほど大きく」違う印象を与えるのか、と疑問を投げかけている。程度を強める「これほどまでにも」が入る。", "opts": ["これ見よがしに：「わざと見せびらかすように」の意で、意味が通らない", "こともなげに：「何でもないことのように平気で」の意で、意味が通らない", "", "こともあろうに：「よりによって（ほかに方法もあるのに）」の意で、意味が通らない"], "ex": "どうして彼は、<b>これほどまでにも</b>努力できるのだろう。"},
"24041_2": {"point": "「次の事実に思い当たった」を受けて、その「事実」の内容を「日本人は〜という事実に」と言い換えている。言い換えの「すなわち」が入る。", "opts": ["", "しかしながら：逆接で、前の内容を言い換える文にならない", "もしくは：「または」の意で、どちらか一方を選ぶときに使う", "とはいえ：「そうは言っても」の逆接で、意味が通らない"], "ex": "日本の首都、<b>すなわち</b>東京には多くの人が集まる。"},
"24041_3": {"point": "直前で「カメラのレンズを直視することにためらいを覚えるのも、同じ理由にもとづいている」と述べている。目をどこに向けるかという「視線」もまた日本語（相手との関係で言葉を変える習慣）に支配されている、という意味。「もまた」は、言葉だけでなく〜も、ということ。", "opts": ["言葉：日本語の支配下にあるのは当然で、「もまた」と付け加える意味がない", "上下関係：上下関係は日本語の使い分けの原因で、日本語に支配されるものではない", "礼儀：直前の「レンズを直視することのためらい」と直接つながらない", ""], "ex": "人の<b>視線</b>が気になって、うまく話せなかった。"},
"24041_4": {"point": "「むろん、アメリカ人も〜。だが、それは二義的なことにすぎない」という流れで、相手によって言葉を変えることもないわけではない、と部分的に認めている。「〜ないわけではない」が入る。", "opts": ["変えないものでもない：「〜ないものでもない」は「条件によっては〜してもいい」という話し手の消極的な意志を表す。アメリカ人の一般的な事実を部分的に認めるこの文には合わない", "", "変えるにあたらない：「変える必要はない」の意で、後の「だが、それは二義的」とつながらない", "変えるきらいがある：「変えるというよくない傾向がある」の意で、意味が通らない"], "ex": "辛い料理が食べられ<b>ないわけではない</b>が、あまり好きではない。"},
"25026": {"point": "インタビューで相手に話をしてもらうよう丁寧に頼む場面。「お聞かせください」は「聞かせてください」の尊敬・丁寧な形で、「（あなたの話を）私に聞かせてください」という依頼になる。", "opts": ["", "お聞きになってもよろしいですか：「お聞きになる」は相手が聞く動作の尊敬語。聞くのは自分なので主語が合わない", "聞かざるをえません：「聞かないわけにはいかない」という意味で、相手への丁寧な依頼にならない", "お聞きになりたい：聞きたいのは自分なので、相手の動作を高める「お聞きになる」は使えない"], "ex": "今後の目標について、ぜひ<b>お聞かせください</b>。"},
"25027": {"point": "「AさえB」は極端な例Aを挙げて「Aでも〜なのだから、ほかはなおさらだ」と示す。母語話者でも紛らわしいのだから、外国人学習者に分かるはずがない、という文。", "opts": ["はおろか：「Aはおろか Bも」の形で、より程度の軽いAを先に挙げる。ここでは後に「も・さえ」がなく、意味も逆になる", "", "のかたわら：「〜する一方で別のこともする」という意味で、名詞「母語話者」には付かない", "にもまして：「〜以上に」という意味で、文の内容に合わない"], "ex": "専門家<b>さえ</b>解けない問題を、私が解けるはずがない。"},
"25028": {"point": "「〜をよそに」は「〜を気にしないで、無視して」という意味。同僚のアドバイスを聞かずに転職して、結局苦労している。後の「あげく」とも合う。", "opts": ["かわきりに：「〜を皮切りに」は「〜を始まりとして次々に」という意味で、文脈に合わない", "へて：「〜を経て」は「〜を通過して・経験して」という意味で、アドバイスを無視した結果の苦労につながらない", "ふまえて：「〜を踏まえて」は「〜を判断の根拠にして」という意味で、「さんざん苦労している」と合わない", ""], "ex": "家族の心配<b>をよそに</b>、彼は一人で海外へ旅立った。"},
"25029": {"point": "客の頼みを店側が丁寧に断る場面。「〜かねます」は「〜できません」を丁寧・婉曲に言う表現で、接客でよく使われる。", "opts": ["", "遠慮してもらいます：客に対して失礼な言い方で、断りの表現としても不自然", "了解いたしました：引き受ける表現で、「申し訳ございませんが」と合わない", "辞めらせていただきます：「辞める」は仕事などをやめる意味で、形も誤り（正しくは「辞めさせて」）"], "ex": "申し訳ございませんが、そのご質問にはお答えし<b>かねます</b>。"},
"25030": {"point": "「〜きらいがある」は「〜しがちだ、〜する傾向がある」という意味で、よくない傾向に使う。趣味の絵なのに芸術家ぶる傾向がある、という批判。", "opts": ["にかたくない：「想像にかたくない」のように「簡単に〜できる」という意味で、動詞の辞書形には付かない", "べからず：「〜してはいけない」という禁止で、掲示などに使う。文脈に合わない", "", "までのことだ：「〜すればいいだけだ」という意味で、文脈に合わない"], "ex": "彼は何でも一人で決めてしまう<b>きらいがある</b>。"},
"25031": {"point": "「数量＋からある」は「〜もある」と、大きさ・長さ・重さが大きいことを強調する。身長が2メートルもある男。", "opts": ["からなる：「〜から成る」は「〜で構成される」という意味で、数量の強調にならない", "", "からする：「〜からする」は値段に使う（「100万円からする時計」）。身長には使わない", "からの：「〜からの」は「〜以上の」の意で使うことがあるが、身長を強調する決まった形ではない"], "ex": "10キロ<b>からある</b>荷物を一人で運んだ。"},
"25032": {"point": "「AはおろかBも（さえ・すら）」は「Aはもちろん、もっと簡単なBも」という意味。後の「すら」と呼応する。作文はもちろん、簡単な日常会話すらできない。", "opts": ["", "とあれば：「〜という事情なら」という意味で、後の「すら」と合わない", "とはいえ：「〜とは言っても」という逆接で、意味が通らない", "ときたら：「〜は（困ったことに）」と人や物を話題にする言い方で、意味が通らない"], "ex": "漢字<b>はおろか</b>、ひらがな<b>も</b>読めない。"},
"25033": {"point": "「〜とあって」は「〜という特別な状況なので」という意味で、後に当然の結果が続く。世界的なアーティストの展覧会なので、多くの人が詰めかけた。", "opts": ["にあって：「〜という状況の中で」という硬い言い方で、「展覧会にあって多くの人が詰めかけた」は不自然", "にひきかえ：「〜とは反対に」と二つを比べる言い方で、文脈に合わない", "", "といえども：「〜であっても」という逆接で、意味が通らない"], "ex": "連休<b>とあって</b>、観光地はどこも混雑していた。"},
"25034": {"point": "「〜たところで」は「〜しても（無駄だ）」という意味で、後に否定的な結果が続く。今から急いで行っても、もう間に合わない。", "opts": ["ところを：「お忙しいところを」のように「〜の時に（迷惑をかけて）」という意味で、文脈に合わない", "ところへ：「ちょうど〜している時に（何かが来る）」という意味で、合わない", "ところに：「ところへ」と同じく、ある場面に別のことが起こる言い方で、合わない", ""], "ex": "今さら謝っ<b>たところで</b>、許してはもらえないだろう。"},
"25035": {"point": "上司に許可を求める丁寧な言い方。「〜ても差し支えないでしょうか」は「〜てもいいでしょうか」をさらに丁寧にした表現。", "opts": ["", "お手数ではないでしょうか：「お手数」は相手に手間をかけさせることで、「〜ても」の後に続けて許可を求める形にならない", "ご迷惑をおかけしたのでしょうか：過去の迷惑を尋ねる言い方で、これからの許可を求める文に合わない", "恐縮ではないでしょうか：「恐縮」は自分が恐れ入る気持ちで、相手に尋ねる形にならない"], "ex": "こちらの資料をお借りしても<b>差し支えないでしょうか</b>。"},
"25036": {"point": "「〜んがために」は「〜しようとして、〜するために」という硬い言い方。動詞の未然形に付く（緩和せ＋んがために）。", "steps": "「打撃を」の後に「緩和せんがために」が続き、目的を表す。次に「消費税を」「引き上げる」で「方針を」を修飾し、文末の「打ち出した」につながる。", "ex": "勝た<b>んがために</b>、どんな手段も使った。"},
"25037": {"point": "「AやBを把握する」の形。主語の「取り組むべきことは」と、述語の「〜を素早く把握することである」を正しく対応させる。", "steps": "「災害が起きた時に」の後に「真っ先に」が「取り組むべきことは」を修飾して主語になる。続く「住民の安否確認や」「被害状況を」が文末の「素早く把握することである」につながる。", "ex": "朝起きて<b>真っ先に</b>することは、天気予報の確認だ。"},
"25038": {"point": "「〜ようがない」は「〜する方法がない」という意味（取り締まる→取締りようがない）。", "steps": "「世界遺産に」の後に「落書きをする」が「問題が相次いで」を修飾し、「発生しているが」と逆接で続く。最後に「取締りようがなく」が文末の「当局は頭を悩ませている」につながる。", "ex": "連絡先が分からないので、知らせ<b>ようがない</b>。"},
"25039": {"point": "名詞を修飾するつながりを見つける。「子供の登下校時」「交通事故にあうリスク」がそれぞれひとまとまりになる。", "steps": "「子供の」に「登下校時に」が付き、次に「交通事故にあう」が「リスクを減らすため」を修飾する。最後に「スクールゾーンが」が文末の「設置されています」の主語になる。", "ex": "通学路の事故の<b>リスクを減らすため</b>、横断歩道が新しく作られた。"},
"25040": {"point": "「〜たるもの」は「〜という立場にある者は（当然）」という意味で、後に「べきだ」が続くことが多い。", "steps": "「教育者」に「たるもの」が付いて主題になる。「子供たちが」が「発揮できる」の主語になり、「それぞれ持っている」が「潜在力を」を修飾して、文末の「発揮できるよう指導するべきである」につながる。", "ex": "教師<b>たるもの</b>、生徒の手本となる<b>べきだ</b>。"},
"25041_0": {"point": "酸素がなくなっても、嫌気性のバクテリアは酸素に触れると死んでしまう生物なので、むしろ生き残れる。次の文の「生き残る生物はいる」とも合う。", "opts": ["", "生き残るわけがない：生き残る可能性を否定する言い方で、後の「生き残る生物はいる」と矛盾する", "生き残るしかない：「ほかに方法がない」という意味で、生物の性質を述べる文に合わない", "生き残らざるを得ない：「仕方なく生き残る」という意味になり、文脈に合わない"], "ex": "この植物は水が少なくても<b>生き残ることができる</b>。"},
"25041_1": {"point": "環境が悪くなっても生き残る生物がいるし、むしろその方が好ましいという生物もいる、という流れ。後の段落の「都合がいい」ともつながる。", "opts": ["都合がつかない：予定などを調整できないという意味で、文脈に合わない", "都合がある：用事や事情があるという意味で、意味が通らない", "", "都合が悪い：環境の悪化で困るという意味になり、「生き残る生物はいる」から続く流れに合わない"], "ex": "暗い場所の<b>方が都合がいい</b>という生き物もいる。"},
"25041_2": {"point": "人間がほかの全生物を代表して環境を守っているという考えは、筆者から見れば思い上がった勘違いである。直後で「地球のためでもないし、ほかの生物のためでもない」と否定している。", "opts": ["怠惰な生活をしやすい：「怠惰」はなまけることで、環境問題への取り組みについての考えと関係がない", "", "善意を施しやすい：筆者は人間の取り組みを善意とは見ておらず、否定する流れに合わない", "愚かな行いをしやすい：行いではなく「〜というような」考え方を述べているので合わない"], "ex": "自分だけが正しいと考えるのは、<b>傲慢な思い違い</b>だ。"},
"25041_3": {"point": "「自分に都合がいい環境を守ろうとしている」に、「そもそも環境を悪くしたのも人類だ」と、同じ方向の事実を付け加えている。添加の「しかも」が入る。", "opts": ["しかし：逆接。前後は対立していないので合わない", "したがって：結果を導く順接。人類が環境を悪化させたことは前の文の結果ではない", "一方：別の面と対比する言い方で、前後は対比になっていない", ""], "ex": "この店は安い。<b>しかも</b>、味もいい。"},
"25041_4": {"point": "「地球環境を守るのは合理的なことだ」に続き、高度成長期に壊された自然は直さなければならないと述べている。", "opts": ["", "修復しても仕方がない：「直しても意味がない」となり、「守るのは合理的なことだ」と矛盾する", "修復にあたらない：「〜にあたらない」は「〜する必要はない」という意味で、文脈に合わない", "修復にきりがない：「いくらやっても終わらない」という意味で、筆者の主張に合わない"], "ex": "地震で壊れた橋を早く<b>修復しなければならない</b>。"},
"26026": {"point": "「AにはBないまでも」は「Aという段階まではいかないが（それに近い程度に）」という意味。守備のプレーは直接得点にはならないが、攻撃に大きな影響を与えている、という文。「～には至らないまでも」が決まった形。", "opts": ["及ばないまでも：「及ばない」は「必要がない」「かなわない」の意で、「得点には及ばない」は意味が通らない", "", "あたらないまでも：「～にはあたらない」は「～する必要はない」の意で、「得点には」と合わない", "さておき：「～はさておき」の形で使い、「得点にはさておき」とは言わない"], "ex": "優勝には<b>至らないまでも</b>、決勝までは進みたい。"},
"26027": {"point": "先輩に相談した結果、話がややこしくなったことを悔やんでいる。「～んじゃなかった」は「～しなければよかった」という後悔を表す話し言葉。", "opts": ["", "するには及ばなかった：「する必要はなかった」という意味で、後悔の気持ちが弱く、会話の流れに合わない", "するべきではない：一般的な判断を述べる言い方で、自分のしたことへの後悔にならない", "するというものではない：「～すればいいというものではない」の形で使い、ここでは意味が通らない"], "ex": "こんなに高いなら、買う<b>んじゃなかった</b>。"},
"26028": {"point": "「～てやまない」は「心から強く～し続けている」という意味で、尊敬・期待・願望などの気持ちを表す。ずっと心から尊敬していた恩人が亡くなった、という文。", "opts": ["ならない：「～てならない」は「自然に～してしまう」という意味で、「尊敬してならない」とは言わない", "いられない：「～ずにはいられない」の形で使う。「尊敬していられない」は意味が通らない", "", "きれない：「～きれない」は動詞の連用形に付き、「尊敬してきれない」とは言わない"], "ex": "皆様のご健康を願って<b>やみません</b>。"},
"26029": {"point": "「～きわまる」は「この上なく～だ」という意味で、な形容詞の語幹に付く（大胆きわまる・失礼きわまる）。後の名詞「活躍」を修飾する。", "opts": ["あっての：「AあってのB」は「Aがあるから成り立つB」という意味で、「大胆あっての」とは言わない", "かぎりの：「力のかぎり」のように「できるだけ全部」の意で、な形容詞の語幹には付かない", "きっての：「町きっての秀才」のように集団や場所を表す名詞に付き、「その中でいちばんの」という意味", ""], "ex": "彼の態度は失礼<b>きわまる</b>ものだった。"},
"26030": {"point": "「～とあっては」は「～という（特別な）状況なら、当然…」という意味で、後に当然の結果や判断が続く。処刑されるリスクが高まっている状況なら、国から逃げようと思うのも当然だ。", "opts": ["ともなく：「見るともなく」のように「特に～しようとするつもりもなく」の意で、文脈に合わない", "ものなら：「～ようものなら（大変だ）」「できるものなら」の形で使い、ここでは意味が通らない", "", "にかこつけて：「～を口実にして」の意。前の内容は口実ではなく実際の状況なので合わない"], "ex": "社長の頼み<b>とあっては</b>、断るわけにはいかない。"},
"26031": {"point": "「～としてあるまじき」は「～という立場の者として、あってはならない」という意味。患者を見捨てるのは医者という立場の者がしてはならない行為だ、という文。", "opts": ["", "をおいて：「Aをおいてほかにない」の形で「A以外に」の意。「あるまじき」とは結びつかない", "はもとより：「AはもとよりBも」の形で使い、後に「も」がないので合わない", "たりとも：「一円たりとも」のように最小の数量に付いて「～も（～ない）」の意で、「医者」には付かない"], "ex": "教師<b>としてあるまじき</b>発言だ。"},
"26032": {"point": "「～てならない」は「自然に強く～してしまう、～でたまらない」という意味。「懸念されてならない」は「心配に思われてしかたがない」となる。", "opts": ["", "されるきらいがある：「～きらいがある」は人や物の好ましくない傾向を言う表現で、話し手の強い気持ちを表さない", "しないともかぎらない：「～かもしれない」の意で、「懸念しないともかぎらない」では意味がずれる", "とされている：「一般にそう考えられている」という意味で、話し手自身の強い気持ちにならない"], "ex": "彼のことが心配に思われて<b>ならない</b>。"},
"26033": {"point": "「～（こと）といったらない」は「言葉で言い表せないほど～だ」という意味で、話し手の強い感情（驚き・あきれ・怒りなど）を表す。言い逃れや責任転嫁をする政治家への、話し手のあきれた気持ちを表している。", "opts": ["このうえない：「～ことこのうえない」は「この上なく～だ」と程度を述べる書き言葉で、話し手の気持ちを直接ぶつける言い方ではない。話し手のあきれた気持ちを表すこの文では、「といったらない」が正解", "", "を禁じ得ない：「怒りを禁じ得ない」のように感情を表す名詞に付き、「見苦しいこと」には付かない", "にしのびない：「見るにしのびない」のように動詞に付いて「つらくて～できない」の意で、合わない"], "ex": "合格の知らせを聞いたときのうれしさ<b>といったらなかった</b>。"},
"26034": {"point": "「～（よう）にも～ない」は「～しようとしても、できない」という意味。同じ動詞を繰り返して使う（引き受けようにも引き受けられない）。仕事で手一杯なので、引き受けたくても無理だ。", "opts": ["引き受けるといえども：「～といえども」は「～ではあっても」の意で、後の「引き受けられない」と合わない", "引き受けるものなら：「～ようものなら」の形で「もし～したら（大変なことになる）」の意で、意味が通らない", "引き受けるだに：「～だに」は「考えるだに恐ろしい」のように「～するだけでも」の意で、合わない", ""], "ex": "財布を忘れたので、買お<b>うにも</b>買え<b>ない</b>。"},
"26035": {"point": "「～にして（ようやく）」は「～という段階になって、やっと」という意味で、時間がかかったことを表す。被災から約３か月たって、やっと医療チームが入った。", "opts": ["を皮切りに：「～を始まりとして次々に」の意で、「ようやく」と合わない", "をもって：「本日をもって終了します」のように区切りや手段を表し、「ようやく」と合わない", "にあって：「～という状況の中で」の意で、時間の経過を表さない", ""], "ex": "結婚して十年目<b>にして</b>、ようやく家を買った。"},
"26036": {"point": "「AはもとよりBまで」は「Aはもちろん、Bも」という意味。「もとより」の前には名詞や「～こと」が来る。", "steps": "「相手に」の後に「送る」「ことは」が続いて「送ることは」となり、「もとより」でつなぐ。最後に「支払いまで」が文末の「済ませることができます」につながる。", "ex": "この店は和食<b>はもとより</b>、洋食<b>まで</b>何でもある。"},
"26037": {"point": "「AとBとがあいまって」は「AとBが一緒に作用して（よい結果になる）」という意味。「～わりには」は「～から予想されるのと違って」という意味。", "steps": "「車格の」の後に「わりには」が付き、「手頃な」が「価格とが」を修飾する。「デザイン、…完備と…価格とが」を受けて「あいまって」が続き、文末の「大ヒットを記録した」につながる。", "ex": "才能と努力<b>とがあいまって</b>、彼は大成功を収めた。"},
"26038": {"point": "「ふとした拍子に」は「ちょっとしたきっかけで」という意味。「～可能性があるため」で理由を表し、後の「行動をとるよう努力」につながる。", "steps": "「誰もが」の後に「ふとした拍子に」「健康や安全を脅かされる」が続き、「可能性があるため」で理由を示す。最後に「常識的で節度ある」が文末の「行動」を修飾する。", "ex": "<b>ふとした拍子に</b>、昔のことを思い出した。"},
"26039": {"point": "「～うえで」は「～するにあたって、～する場合に」、「～ことから」は理由を表す。", "steps": "「推し進める」に「うえで」が付く。次に「テレワークは」が主語になり、「欠かせないものである」に「ことから」が付いて理由を示し、文の後半「以前にもまして…尽力していく」につながる。", "ex": "留学する<b>うえで</b>、語学力は欠かせない。"},
"26040": {"point": "「～べく」は「～するために」、「～にまつわる」は「～に関係する」という意味。主人公と警察官の二者が協力する、という文の形をつかむ。", "steps": "「謎の組織への」の後に「復讐を誓う主人公と」が続く。次に「パワーにまつわる」が「犯罪を一掃すべく立ち上がる」の「犯罪」を修飾し、それが「地元警察官が協力し」の「地元警察官」を修飾する。", "ex": "夢を実現する<b>べく</b>、毎日練習している。"},
"26041_0": {"point": "直前で、機能的なデザインは近代以前にもあり、近代以降にも機能性を考えないデザインがあると述べている。だから「機能的であること」と「近代の産物であること」は同じではない、という結論になる。", "opts": ["", "間違いないと言える：「一致する」とする言い方になり、前の二つの例と矛盾する", "似ているが、違うものではないだろうか：「似ている」とは述べておらず、前の内容から導けない", "人によってとらえ方が違うものである：人による違いの話はしていないので合わない"], "ex": "値段が高いことと品質がいいことは、<b>必ずしも一致しない</b>。"},
"26041_1": {"point": "前の段落で機能主義と近代は一致しないと述べた後、「近代の一時期に機能主義が標榜されたことはあった」といったん相手の考えを認め、「だが」で反論に移る。「確かに～。だが…」の形。", "opts": ["すなわち：前の内容を言い換える接続詞で、反対の事実を認める流れに合わない", "", "その結果：前の内容から生じた結果を述べる言い方で、合わない", "そのうえ：前の内容に付け加える言い方で、後の「だが」と合わない"], "ex": "<b>確かに</b>この案は安い。だが、時間がかかりすぎる。"},
"26041_2": {"point": "機能主義が支持されたのは近代の中のほんの一時期にすぎない「のに」、近代建築という言葉は機能主義を指す語として定着している。予想に反する事実を続ける逆接が入る。", "opts": ["したがって：前の内容の当然の結果を述べる順接で、前後が反対の関係なので合わない", "", "もしくは：「または」の意で、二つのうちどちらかを選ぶ言い方なので合わない", "それに：付け加える言い方で、前後の逆接の関係を表せない"], "ex": "何度も注意された。<b>にもかかわらず</b>、彼は同じ失敗を繰り返した。"},
"26041_3": {"point": "筆者は、機能主義は近代と結びつくものではない（近代だけのものではない）と繰り返し述べている。だから機能主義を乗り越えても「脱近代」とは言えない、と後の文につながる。", "opts": ["いいものとは言いがたい：機能主義のよし悪しは論じておらず、後の「だから…脱近代主義とは言えない」とつながらない", "現代的であると言える：筆者の主張と反対になる", "重要であるわけではない：重要かどうかは論じていないので合わない", ""], "ex": "古い建物だからといって、価値がある<b>わけではない</b>。"},
"26041_4": {"point": "「近代建築」が本来は言葉の誤用だと述べたのと同じように、「ポスト・モダニズム」という言葉も用語として筋が通らない、と批判している。「これもまた」が前の批判と並べていることを示す。", "opts": ["共感できる：筆者は用語のあり方を批判しているので合わない", "使い分けできる：用語の使い分けの話はしていないので合わない", "", "あり得る：「あり得るところをもっている」では批判にならず、文脈に合わない"], "ex": "彼の説明には、どうも<b>納得しがたい</b>ところがある。"},
"27026": {"point": "「AはAで」は「Aにも（ほかと同じように）それなりの事情や立場がある」という意味。子供から見ればうらやましい大人にも、大人なりの大変さがある、という文。", "opts": ["", "大人が大人に：「大人が大人に大変なことがある」では意味が通らない", "大人より大人で：比べる対象がなく、意味が通らない", "大人から大人に：受け渡しを表す言い方になり、意味が通らない"], "ex": "学生は気楽だと言われるが、学生<b>は</b>学生<b>で</b>悩みがある。"},
"27027": {"point": "「～だけあって」は「～なので、それにふさわしく」という意味で、評価する気持ちを表す。幼稚園の先生をしていたので、昔話や童話をたくさん知っているのも当然だ。", "opts": ["していたからには：「～からには」の後には「～べきだ・～つもりだ」など話し手の判断・決意が続き、事実を述べる文に合わない", "していたとは：「～とは」は驚きを表し、後に「知らなかった」などが続く形で、この文に合わない", "していたところ：「～したところ」は「～したら（その結果）」の意で、理由を表さない", ""], "ex": "さすがプロ<b>だけあって</b>、料理の盛り付けが美しい。"},
"27028": {"point": "「いっさい～ない」は「まったく～ない」という意味で、例外なく全部否定する。どんな理由があってもデータの持ち出しは一切認められていない。", "opts": ["", "むしろ：二つを比べて「どちらかといえば」の意で、否定を強める副詞ではない", "かならず：「必ず～する」と肯定に使うのが普通で、「必ず認められていない」は不自然", "どうしても：「どうしても～ない」は「努力しても～できない」の意で、規則の否定には合わない"], "ex": "この部屋での飲食は<b>いっさい</b>禁止されている。"},
"27029": {"point": "「～にしてみれば」は「～の立場から考えると」という意味。旅行者が感動したきれいな海も、地元の人の立場から見れば毎日見ている風景だ。", "opts": ["からして：「～からして」は「～を代表例として（ほかも）」「～から判断して」の意で、立場を表さない", "といっても：「～とはいっても」の意の逆接で、意味が通らない", "", "はともかくとして：「～は別として」の意で、地元の人を話題から外すことになり、意味が通らない"], "ex": "親<b>にしてみれば</b>、子供はいつまでも子供だ。"},
"27030": {"point": "相手の会社の社長（田中さん）について、自分が「知っている」ことを謙譲語で言う場面。「存じ上げる」は人を「知っている」の謙譲語。", "opts": ["知っていただけです：「だけ」で軽く扱う言い方になり、お世話になった人について言うには失礼", "", "お目にかかれます：「会える」の謙譲語で、「よく」と合わず、知っていることを表さない", "お会いになっています：「お会いになる」は相手の動作を高める尊敬語で、自分の動作には使えない"], "ex": "お名前はかねがね<b>存じ上げて</b>おります。"},
"27031": {"point": "「～ものなら」は「もし～できるなら（実際には難しいが）」という意味で、実現が難しい願望を表す。抜かないで済むならそうしたいが、ほかに方法がない。", "opts": ["抜かずにいると：「～と」は条件・結果を表し、後の「そうしたい」と合わない", "抜かずにいることで：手段を表す言い方で、願望の条件にならない", "抜かずに済むのだから：「済む」と決まっている言い方になり、後の「ほかに方法がない」と矛盾する", ""], "ex": "できる<b>ものなら</b>、もう一度学生時代に戻りたい。"},
"27032": {"point": "「～に決まっている」は「きっと～だ」という強い確信を表す。忙しい彼に頼んでも、無理だと言われるのはほぼ確実だが、それでも頼んでみる。", "opts": ["言わせる始末だ：「～始末だ」は悪い結果に至ったことを言い、まだ頼んでいない状況に合わない。「言わせる」も意味が通らない", "言わせるということだ：伝聞や結論を表す言い方で、「言わせる」も意味が通らない", "", "言われるまでになる：「～までになる」は程度が高まることを表し、意味が通らない"], "ex": "こんなに練習したのだから、合格する<b>に決まっている</b>。"},
"27033": {"point": "「～でいいから」は「～で構わないので」という意味で、相手に負担をかけないように頼む言い方。忙しくないときで構わないから、作り方を教えてほしい。", "opts": ["がいいし：「～がいい」は勧める言い方で、「時間があるときがいいし」では頼みにならない", "", "ならいいのに：「～ならいいのに」は実現していないことへの残念な気持ちを表し、頼む言い方にならない", "でもいいけど：「～でもいいけど」は譲歩を表し、後に別の条件が続く言い方で、頼みとして不自然"], "ex": "少し<b>でいいから</b>、手伝ってくれない？"},
"27034": {"point": "「～といえるだろうか」は反語で「～とはいえない」という意味。直後の「私はそうは思わない」と合う。", "opts": ["", "といえないではないか：「～ではないか」で「いえない」と強く主張する言い方になり、後の「私はそうは思わない」と内容が重なって不自然", "べきではないだろうか：「～するべきだ」という提案になり、「教育の質が向上している」と合わない", "べきであるか否か：「～かどうか」を問う言い方で、文の終わりとして成り立たない"], "ex": "これで本当に問題が解決したと<b>いえるだろうか</b>。"},
"27035": {"point": "「～ても始まらない」は「～しても何にもならない、意味がない」という意味。落ち込んでばかりいても仕方がないと思い直し、練習を再開した。", "opts": ["落ち込みもしない：実際に落ち込んでいたので、前の文と矛盾する", "落ち込むわけではない：前の文で落ち込んでいたと述べているので矛盾する", "落ち込んでいたことは否めない：落ち込んでいたことを認める言い方で、「また練習をやることにした」につながらない", ""], "ex": "今さら後悔し<b>ても始まらない</b>。次のことを考えよう。"},
"27036": {"point": "「～との」は「～という」という意味で、報告や連絡の内容を表す（～との報告／～との連絡）。「～には」は目的を表す。", "steps": "「原因を特定する」に「には」が付いて目的を表す。次に「詳細な調査をする」「必要がある」が続き、最後に「との」が文末の「報告」につながる。", "ex": "明日の会議は中止する<b>との</b>連絡があった。"},
"27037": {"point": "「～からにほかならない」は「まさに～からだ（それ以外の理由はない）」という意味。", "steps": "「困難に遭っても」の後に「それに負けることなく」が続き、「サッカーを続けてこられたのは」が主語になる。最後に「信頼できる」が「仲間がいたから」を修飾し、文末の「にほかならない」につながる。", "ex": "彼が成功したのは、努力を続けた<b>からにほかならない</b>。"},
"27038": {"point": "「～かのような」は「実際は違うのに、まるで～のような」という意味。「～しか知らない私にとっては」で、筆者の立場を示す。", "steps": "「昔の」に「町の様子しか知らない」が付き、「私にとっては」が続く。次に「どこか知らない」が「町に来たかのような」を修飾し、文末の「不思議な感覚だった」につながる。", "ex": "まるで夢を見ている<b>かのような</b>気分だった。"},
"27039": {"point": "「～もんか（ものか）」は「絶対に～ない」という強い否定・拒否を表す話し言葉。「なんて」は気持ちの内容を軽く示す。", "steps": "「謝ってきても」の後に「許して」「やる」「もんか」と続いて「許してやるもんか」となる。最後に「なんて」が文末の「気持ちもあった」につながる。", "ex": "あんな店、二度と行く<b>もんか</b>。"},
"27040": {"point": "「～にたえる」は「～するだけの価値がある」という意味。「～をと考えて」は「～を作ろうと考えて」の「作ろう」を省いた言い方。", "steps": "「大人の」の後に「観賞にたえるような」が続き、「アニメ映画を」を修飾する。次に「と考えて」で監督の意図を示し、最後に「作った作品だ」が文末の「と語った」につながる。", "ex": "この作品は大人の鑑賞<b>にたえる</b>本格的な内容だ。"},
"27041_0": {"point": "前の段落で紹介した友人（ハハ友）の話を続けている。「そんな彼女の息子」で、前の段落の「彼女」を受けて、友人の息子だと分かるようにする。", "opts": ["私の：一人暮らしを始めたのは筆者の息子ではなく友人の息子なので合わない", "", "クラスメートだった：誰の息子かがはっきりせず、前の段落とつながらない", "その友人だった：「友人だった息子」となり、意味が通らない"], "ex": "<b>そんな彼女の</b>夢は、いつか自分の店を持つことだ。"},
"27041_1": {"point": "母親が一生懸命世話をしたのに、息子は「じゃあね」の一言だけだった。「それはないだろう（ひどい）」という母親の不満が入る。「ありがとうと言えないのだ」に続く気持ち。", "opts": ["", "「じゃあね」も言えないのか：息子は実際に「じゃあね」と言っているので合わない", "「じゃあね」とは言っただろう：言ったことを確認する言い方で、不満を表さない", "「じゃあね」じゃなかったのか：息子は「じゃあね」と言っており、意味が通らない"], "ex": "せっかく作ったのに、「まずい」<b>はないだろう</b>。"},
"27041_2": {"point": "筆者が7歳だったころの話に移っている。「その頃」という意味の「当時」で、過去の場面を導く。", "opts": ["また：前の内容に付け加える言い方で、過去の場面に移る流れに合わない", "例えば：例を挙げる言い方で、ここでは前の内容の例になっていない", "", "今度は：これから先のことや順番を表し、過去の話に合わない"], "ex": "<b>当時</b>はまだ携帯電話がなかった。"},
"27041_3": {"point": "母は何も言わずに話を聞いていただけだったが、翌日にはお菓子を用意してくれていた。「黙って」と合い、後の行動の意外さが伝わる。", "opts": ["", "聞きたそうだった：筆者がすでに話しているので、「聞きたそう」は合わない", "聞くようになった：変化を表す言い方で、その晩一度の出来事に合わない", "聞くかと思った：話し手の予想を表し、「母は黙って」と合わない"], "ex": "先生は何も言わずに、黙って<b>聞くだけだった</b>。"},
"27041_4": {"point": "筆者は自分の体験から「愛情は生き続けるものだ」と述べた。だから友人の息子への愛も彼の心で育ち続けるはずだ、と強く確信している。", "opts": ["育ち続けるのだそうだ：伝聞の言い方で、筆者自身の確信を表せない", "育ち続けるというのだ：人の言葉を引く言い方で、筆者の結論にならない", "育ち続けるからかもしれない：理由の推測になり、文の結論として合わない", ""], "ex": "努力はいつか報われる<b>に違いない</b>。"},
"27126": {"point": "「果たして～だろうか」は「結果はいったいどうなるのだろうか」と疑問を強める言い方。優勝候補同士の対決で、どちらが勝つか分からない。", "opts": ["ついに：「とうとう」の意で、結果がすでに出たときに使い、疑問の文に合わない", "まさか：「まさか～ないだろう」と打ち消しの推量に使い、この疑問には合わない", "どうやら：「どうやら～らしい」と推量に使い、疑問の文に合わない", ""], "ex": "<b>果たして</b>彼の予想は当たるのだろうか。"},
"27127": {"point": "「どんな～（よ）うと」は「どんなに～ても（関係なく）」という意味。どんな反論をしても自由だが、押し付けはよくない。", "opts": ["する以上：「～以上」は「～のだから当然」の意で、「自由だ」と合わない", "しつつも：「～つつも」は「～ながらも」の逆接で、「どんな」と合わない", "", "している限りは：「～限りは」は条件の範囲を表し、「どんな」と合わない"], "ex": "誰が何を言<b>おうと</b>、私の考えは変わらない。"},
"27128": {"point": "「～ともなれば」は「～という（特別な）状況になると、当然」という意味。週末になると、当然家族連れで混雑する。", "opts": ["につき：「～につき」は「～なので」（掲示などの硬い言い方）や「～ごとに」の意で、ここでは合わない", "を機に：「～をきっかけに」の意で、毎週の繰り返しに合わない", "をもって：「～で（区切り・手段）」の意で、意味が通らない", ""], "ex": "年末<b>ともなれば</b>、どの店も混み合う。"},
"27129": {"point": "「～も～ないも」は「～するかどうかは（～次第だ）」という意味で、後に「～にかかっている」「～次第だ」が続く。", "opts": ["", "するやらしないやら：「～やら～やら」は「～かどうか分からない」という不明を表し、「君にかかっている」と合わない", "するなりしないなり：「～なり～なり」は選択肢を示して勧める言い方で、合わない", "するというかしないというか：言い換えに迷う言い方で、意味が通らない"], "ex": "合格する<b>もしないも</b>、これからの努力次第だ。"},
"27130": {"point": "「～てみせる」は「必ず～する」という強い決意を表す。前回おいしくないと言われたので、今度こそおいしく作ると決意している。", "opts": ["作るものか：「絶対に作らない」という意味になり、文脈と反対になる", "作る始末だ：悪い結果になったことを表し、決意を表さない", "", "作りつつある：進行中であることを表し、「今度は」「絶対」と合わない"], "ex": "次の試合では、必ず勝って<b>みせる</b>。"},
"27131": {"point": "「～といったところだ」は「だいたい～程度だ（それほど多くない）」という意味。中古なら高くても4、5万円程度だ。", "opts": ["に上る：「～に上る」は数量が多いことを表し、「高くても」と合わない", "", "でもあるまい：「～でもないだろう」の意で、意味が通らない", "どころではない：「～する余裕はない」の意で、値段の話に合わない"], "ex": "ここから駅までは、歩いて10分<b>といったところだ</b>。"},
"27132": {"point": "「～がゆえの」は「～であるために生じる」という意味で、後に名詞が続く。天才であるために生じる悩みもあった。", "opts": ["とし得る：「～とすることができる」の意で、「苦悩」と結びつかない", "であるがごとき：「～であるかのような」の意で、本当に天才である人には合わない", "とせざるを得ない：「～としないわけにはいかない」の意で、後の「苦悩」と結びつかない", ""], "ex": "若さ<b>ゆえの</b>失敗も、今ではいい思い出だ。"},
"27133": {"point": "「～ものの」は「～けれども」という意味で、後に期待どおりにならなかった結果が続く。市民の心をつかもうとしたが、支持が得られなかった。", "opts": ["", "つかみきれなかったものの：心をつかめなかったことと「支持が得られず」は同じ方向の内容で、逆接の「ものの」でつなぐと不自然", "つかもうとしたからといって：後に「～とは限らない」などが続く形で、この文に合わない", "つかみきれなかったからといって：同じく後に「～わけではない」などが続く形で、合わない"], "ex": "免許は取った<b>ものの</b>、まだ運転には自信がない。"},
"27134": {"point": "「～しかない」は「ほかに方法がない」という意味。自分が代わることはできないので、弟本人に頑張ってもらうほかない。", "opts": ["頑張れるに決まっている：強い確信を表し、「代わることもできないので」とつながらない", "", "頑張れないこともない：「頑張ろうと思えば頑張れる」の意で、文脈に合わない", "頑張ってしまうところがある：性格の傾向を表し、意味が通らない"], "ex": "電車が止まったので、歩いて帰る<b>しかない</b>。"},
"27135": {"point": "「～ますように」は「～ことを願っています」という祈りや願いを表す。相手が早く回復することを願っている。「回復される」は「回復する」の尊敬の形。", "opts": ["", "願ってはどうですか：相手に勧める言い方で、自分の願いを表さない", "いたしたく思います：「いたす」は謙譲語で、相手の回復に使うと失礼", "していらっしゃるでしょうか：今の状態を尋ねる言い方で、「一日も早く」と合わない"], "ex": "試験に合格でき<b>ますように</b>。"},
"27136": {"point": "「誰かしら」は「（誰かは分からないが）必ず誰か」という意味。一人で行っても必ず誰か友達に会うから、約束する必要がない。", "steps": "「一人で」の後に「行っても」が続く。次に「誰かしら」「友達に会うので」で理由を示し、最後に「誰かと」が文末の「約束して」につながる。", "ex": "あの店に行けば、<b>誰かしら</b>知り合いに会う。"},
"27137": {"point": "「～とか」は発言の内容を例として示す言い方（～とか言う）。「どうだって」は「どうでも」の話し言葉。", "steps": "「そんなこと」の後に「どうだって」「かまわない」と続き、「とか」で発言の内容を示す。最後に「本心とは違うことを」が文末の「言ってしまう」につながる。", "ex": "彼は忙しい<b>とか</b>言って、手伝ってくれない。"},
"27138": {"point": "「～か否か」は「～かどうか」という意味。「AだけでなくBも重要だ」の形をつかむ。", "steps": "「情報が正しい」に「か否か」が付き、「だけでなく」で次に続ける。次に「いつのデータかを」「確認すること」が続き、文末の「も重要である」につながる。", "ex": "参加する<b>か否か</b>は、明日までに決めてください。"},
"27139": {"point": "「～ようがない」は「～する方法がない」という意味。「これ以上きれいにしようがないくらい」で、精一杯きれいにしたことを表す。", "steps": "「部屋が汚いことを」の後に「親に注意されて」が続く。次に「これ以上」「きれいにしようがないくらい」が「きれいにしたつもりだったが」を修飾し、文末の「まだ汚いと言われた」につながる。", "ex": "これ以上は説明し<b>ようがない</b>。"},
"27140": {"point": "「～までに至らない」は「～という段階まで達しない」という意味。「～というのが現状である」で、全体をまとめる。", "steps": "「回復してきている」に「と実感できる」が付き、「までに至らない」が「企業もまだ多い」を修飾する。最後に「というのが」が文末の「現状である」につながる。", "ex": "交渉は合意<b>に至らない</b>まま終わった。"},
"27141_0": {"point": "若者は、店を覗いていた筆者たちに気づいて、とっさに飛び出してきたのだろう、と筆者が推測している。「反射的に」と合う。", "opts": ["飛び出してくることもあった：何度もあったことを表し、一回の出来事に合わない", "飛び出してくるかもしれなかった：実際に飛び出してきたので合わない", "飛び出してきたほどだ：程度を強調する言い方で、前の文とつながらない", ""], "ex": "彼は慌てていたから、きっと忘れて<b>いったのだろう</b>。"},
"27141_1": {"point": "理屈ばかりで動かない若者が多いとぼやく友人が、あんな若者が部下にいればいいのに、と願っている。「～たらなあ」は実現していない願望を表す。", "opts": ["いたとしてもね：仮定の逆接で、願望を表さない", "", "いたとはなあ：実際にいたことへの驚きを表し、合わない", "いたんだけどね：過去に実際にいたことを表し、文脈に合わない"], "ex": "もっと時間があっ<b>たらなあ</b>。"},
"27141_2": {"point": "続く文で「駆け出しの編集者時代」と筆者自身の若いころの話をしている。「私だって若いころは」となる。", "opts": ["彼女：「駆け出しの編集者時代」は筆者自身のことなので合わない", "部下：部下の話ではないので合わない", "", "あの子：あの若者の話ではなく、筆者の過去の話なので合わない"], "ex": "<b>私だって</b>、昔は泣き虫だった。"},
"27141_3": {"point": "筆者はあの若者と同じ立場なのに、いつの間にか腰が重くなっている。前後が反対の関係なので、逆接の「なのに」が入る。", "opts": ["すると：前の行動の結果として次のことが起こる言い方で、合わない", "", "こうして：前の内容をまとめて結果を導く言い方で、合わない", "それどころか：前の内容よりさらに程度が進むことを表し、逆接の関係を表せない"], "ex": "毎日練習している。<b>なのに</b>、少しも上手にならない。"},
"27141_4": {"point": "明日から臨戦態勢でいこうと決め、見習うべき相手としてあの若者を挙げている。決意をきっぱりと述べる「あの若者だ」が入る。", "opts": ["", "あの若者だからか：理由の推測になり、決意を述べる文にならない", "あの若者だそうだ：伝聞になり、筆者自身の決意を表せない", "あの若者だと思っていた：過去の考えを述べる言い方になり、「明日からは」と合わない"], "ex": "目標にすべきは、<b>あの先輩だ</b>。"},
"27226": {"point": "「～をよそに」は「～を気にしないで、～に関係なく」という意味。車内が混んでいるのも気にせず、男は平然とパソコンを広げていた。", "opts": ["含めて：「～を含めて」は「～も入れて」の意で、意味が通らない", "もとに：「～をもとに」は「～を基礎・材料にして」の意で、意味が通らない", "除いて：「～を除いて」は「～以外は」の意で、意味が通らない", ""], "ex": "周囲の心配<b>をよそに</b>、彼は一人で山に登った。"},
"27227": {"point": "「（動詞ます形）もしないで」は「～さえしないで」という意味で、当然するべきことをしない人を非難する気持ちを表す。漫画を読みさえしないで批判する父への不満。", "opts": ["読まない：「読まないもしないで」という形はない", "", "読もう：「読もうともしないで」なら言えるが、「読ももしないで」は誤り", "読んで：「読んでもしないで」という形はない"], "ex": "彼は話を聞き<b>もしないで</b>反対した。"},
"27228": {"point": "「もっとも」は「ただし」の意で、前に述べたことに補足や修正を加える。チームワークの大切さを知った、ただしそれに気づいたのは去年だ、と付け加えている。", "opts": ["要するに：前の内容をまとめる言い方で、後の補足と合わない", "あるいは：「または」の意で、二つから選ぶ言い方なので合わない", "", "ついては：「そこで（それに関して）」の意で、依頼や案内を続ける言い方なので合わない"], "ex": "この店の料理はおいしい。<b>もっとも</b>、値段は少し高いが。"},
"27229": {"point": "「～ておいでになる」は「～ている」の尊敬語。目上の元村長の様子を、話し手が敬って述べている。", "opts": ["", "差し上げ：「～て差し上げる」は相手のために何かをする謙譲の言い方で、「覚えて」と合わない", "まいり：「～てまいる」は自分の動作をへりくだる謙譲語で、元村長の動作には使えない", "申し上げ：「申し上げる」は「言う」の謙譲語で、意味が通らない"], "ex": "先生は今も、昔の教え子の名前を覚えて<b>おいでになる</b>。"},
"27230": {"point": "「～に越したことはない」は「～のほうがいい、～が一番だ」という意味。知識はあるほうがいいが、それより人柄を重視している。", "opts": ["にすぎません：「ただ～だけだ」の意で、意味が通らない", "ことは否めません：「～ことは否定できない」の意で、後の「が、それよりも」とつながりにくい", "", "といっても過言ではありません：「～と言っても言いすぎではない」の意で、知識の大切さを強調しすぎて文脈に合わない"], "ex": "体のためには、早く寝る<b>に越したことはない</b>。"},
"27231": {"point": "「～次第では」は「～によっては」という意味で、後に「～可能性がある」などが続く。復旧の状況によっては、営業再開が遅れるかもしれない。", "opts": ["次第には：この形では使わない", "次第に：「だんだん」という意味の副詞で、意味が通らない", "", "次第：「～次第」は「～したらすぐ」の意（動詞ます形＋次第）や「～によって決まる」の意で、ここでは可能性を表せない"], "ex": "天候<b>次第では</b>、試合が中止になることもある。"},
"27232": {"point": "「～ては困る」は「～されると困る」という意味。カード番号などは他人に知られると困る情報なので、受身の「知られては」が入る。", "opts": ["知っていても：主語が他人になり、「困る」とつながらない", "知っていなくても：意味が通らない", "知らなくては：「知らなければならない」の意になり、意味が通らない", ""], "ex": "大事な書類なので、なくされ<b>ては困る</b>。"},
"27233": {"point": "「～ばいいというものではない」は「～すれば十分というわけではない」という意味。大切なのは成果で、ただ時間をかけて頑張ればいいわけではない。", "opts": ["がんばることだといってもおかしくない：意味が通らず、前の「大切であり」と合わない", "", "がんばることでしかない：「頑張ることにすぎない」の意で、文脈と合わない", "がんばりようがない：「頑張る方法がない」の意で、文脈と合わない"], "ex": "安けれ<b>ばいいというものではない</b>。品質も大事だ。"},
"27234": {"point": "「～ものと思われる」は「～だろうと考えられる」という客観的な推量の言い方で、報告や論文などで使う。「明らかになる」が自動詞なので「なる」が入る。", "opts": ["", "するという思いがある：「明らかにする」になり、主語の「地質構造が」と合わない", "なったかに思える：「なったかのように思える」の意で、「いずれ近いうちに」と合わない", "するだろうと思う：「明らかにする」になり、主語と合わない"], "ex": "この傾向は今後も続く<b>ものと思われる</b>。"},
"27235": {"point": "「～させてもらおうかと思って」は「～しようと思っている」ことを、相手に配慮して控えめに伝える言い方。先輩にサークルを辞めたいと切り出している。", "opts": ["辞めてしまわれたのでしょうか：自分のことに尊敬語を使っており、誤り", "辞めてしまったのかと思って：すでに辞めたことになり、「今日で」と合わない", "辞めさせたらどうでしょうか：他人を辞めさせることを提案する言い方で、意味が通らない", ""], "ex": "来月で仕事を休ま<b>せてもらおうかと思って</b>いるんです。"},
"27236": {"point": "「～に由来する」は「～がもとになっている」という意味。「馬酔木」という書き方の由来を説明している。", "steps": "「アセビには」の後に「有毒成分があり」が続く。次に「馬が食べると酔ったような」が「状態になることに」を修飾し、最後に「由来する」が文末の「そうです」につながる。", "ex": "この町の名前は、川の名前<b>に由来する</b>。"},
"27237": {"point": "「AにBを気づかせる」の形。「つい～しすぎる私に」で、気づかせる相手を示す。", "steps": "「つい」の後に「仕事に夢中になりすぎる」が「私に」を修飾する。次に「本当に大切なものは何なのか」が続き、「気づかせてくれる」が文末の「ありがたい存在です」を修飾する。", "ex": "友人の一言が、自分の間違いに<b>気づかせてくれた</b>。"},
"27238": {"point": "「～などと報じられた」は報道の内容を示す。「～ことに対し」で、訴訟を起こした理由を表す。", "steps": "「脱税を行った」の後に「疑いがあるなどと」「報じられた」が続き、「ことに対し」で受ける。最後に「事実とは全く」が文末の「異なり」につながる。", "ex": "首相の発言<b>に対し</b>、批判が相次いだ。"},
"27239": {"point": "「～てのことだ」は「～したうえでのことだ」という意味で、行動の理由を説明する。文末の「という」は伝聞を表す。", "steps": "「判断」に「して」が付き、「の」「ことだ」と続いて「判断してのことだ」となる。最後に「という」で伝聞を表して文を終える。", "ex": "彼が会社を辞めたのは、よく考え<b>てのことだ</b>。"},
"27240": {"point": "「AほどBない」は「Aというほどには B ではない」という意味。資格を取っただけで希望の職につけるほど、世間は甘くない。", "steps": "「資格を取った」に「だけ」「で」が付いて「取っただけで」となる。次に「希望の職につける」に「ほど」が付き、文末の「世間は甘くない」につながる。", "ex": "一度話した<b>だけで</b>分かり合える<b>ほど</b>、人間は単純ではない。"},
"27241_0": {"point": "機械はマニュアル通りに動くが、生き物はそうはいかない、という流れ。ある所で通用したことが別の所でも通用するとは限らない、という意味の文が入る。", "opts": ["こちらにはいえないこともない：「いえる場合もある」の意で、「そうはいかない」と合わない", "", "こちらにもいえるとは思わなかった：筆者の過去の驚きを述べる言い方で、一般論として合わない", "こちらにはいえないと思うのか：相手に問いかける言い方で、文脈に合わない"], "ex": "高い薬がよく効く<b>とは限らない</b>。"},
"27241_1": {"point": "前の段落の、ねこを飼い始めて何も分からなかった時のことを「そういう時」と指している。", "opts": ["", "する：「する時に」では何をする時か分からず、意味が通らない", "あの：話し手と聞き手が共に知っている過去を指す言い方で、文章で直前の内容を受けるには「そういう」が自然", "やろうという：意味が通らない"], "ex": "困っている<b>そういう</b>時こそ、友達の助けがありがたい。"},
"27241_2": {"point": "直後に引用されている内容は、ねこのトイレの時の注意である。「中でも納得したのが、トイレのことだ」と、話題を示す。", "opts": ["", "トイレのことであるに違いない：筆者自身が納得したことなので、推量の言い方は合わない", "トイレだからである：理由を表す言い方で、「納得したのが」とつながらない", "トイレだと聞いている：伝聞になり、筆者自身が本で読んだ内容と合わない"], "ex": "旅行で一番困ったのは、言葉<b>のことだ</b>。"},
"27241_3": {"point": "マニュアル通りに遠慮していたが、実際のゆずはまったく違う行動をとった。予想と反対の展開を導く「ところがである」が入る。", "opts": ["もっともである：前の内容を認める言い方で、後の意外な展開と合わない", "当然である：前の内容を当然とする言い方で、後の展開と合わない", "", "例えばである：例を挙げる言い方で、前の内容の例にはなっていない"], "ex": "準備は完璧だった。<b>ところがである</b>。当日になって雨が降り出した。"},
"27241_4": {"point": "ゆずの行動というひとつの出来事を通して、生き物には個性があると改めて思い知らされた、と結んでいる。", "opts": ["認識させられたことがある：経験の有無を言う言い方で、この出来事の結びにならない", "認識させられたおかげだ：何かのおかげという理由の言い方で、意味が通らない", "認識させられる話があった：人から聞いた話になり、筆者自身の体験と合わない", ""], "ex": "家族の大切さを改めて感じ<b>させられる出来事だった</b>。"},
"27326": {"point": "「～限り」は「～している間はずっと」という意味。応援してくれるファンが一人でもいる間は歌い続ける、という決意を表している。", "opts": ["いた上：「～た上で」は「～してから」の意で、意味が通らない", "", "いながら：「～ながら」は「～のに」「～と同時に」の意で、意味が通らない", "いるだけあって：「～だけあって」は「～にふさわしく」の意で、意味が通らない"], "ex": "体が動く<b>限り</b>、仕事を続けたい。"},
"27327": {"point": "「～とすれば」は「～と仮定すれば」という意味。リーダーが石川さんでないと考えた場合、ほかに誰なのかと推測している。", "opts": ["", "とあって：「～とあって」は「～という特別な状況なので」の意で、後ろに疑問の文は続かない", "というより：「AというよりB」は比べてBの方が適当だと言う表現で、意味が通らない", "と思っても：「～と思っても」は逆接で、意味が通らない"], "ex": "この話が本当だ<b>とすれば</b>、大変なことになる。"},
"27328": {"point": "「なんら～ない」は「少しも～ない」という意味。品質には少しも問題がないと強く否定している。", "opts": ["かりに：「かりに～ても」は仮定を表し、後ろに「ない」を伴う強い否定にはならない", "", "なかなか：「なかなか～ない」は「簡単には～ない」の意で、問題の有無には使わない", "あまりにも：程度が大きすぎることを表し、意味が通らない"], "ex": "私はこの事件とは<b>なんら</b>関係がない。"},
"27329": {"point": "「～ことは否めない」は「～ということは否定できない」という意味。体力が落ちてきたことは認めつつ、「が」で技術力への期待を述べている。", "opts": ["はずだった：予定や予想と違う結果を表し、意味が通らない", "とおりだった：「～とおり」は予想と同じだったという意で、文脈に合わない", "", "に越したことはない：「～が一番いい」の意で、「体力が落ちてきた」と合わない"], "ex": "準備不足だった<b>ことは否めない</b>。"},
"27330": {"point": "「ご～なさる」は「～する」の尊敬語。社内の上司である鈴木課長の動作なので、尊敬語を使っている。", "opts": ["申します：「申す」は「言う」の謙譲語で、課長の動作には使えない", "いただきます：「ご～いただく」は話し手が相手にしてもらう言い方で、主語が「課長が」の文には合わない", "願います：「ご～願う」は相手に頼む言い方で、意味が通らない", ""], "ex": "社長が新しい方針をご説明<b>なさいます</b>。"},
"27331": {"point": "「～においてさえ」は「～の時でも」という意味。研究が進んだ現代でさえ解明できていない部分が多い、と極端な例を挙げている。", "opts": ["", "においてこそ：「～においてこそ」は「～だからこそ」と強調する言い方で、後ろの「解明できていない」と合わない", "に対してさえ：「～に対して」は動作や感情の向かう相手を表し、時代には使わない", "に対してこそ：「～に対して」は相手を表し、また「こそ」も文脈に合わない"], "ex": "医学が進歩した今日<b>においてさえ</b>、治せない病気は多い。"},
"27332": {"point": "「～ぬく」は「最後まで～する」、「～た末に」は「いろいろあった結果」という意味。相手の厳しい攻撃に最後まで耐えた結果、勝利を収めた。", "opts": ["耐えかねたほど：「～かねる」は「～できない」の意で、勝利と合わない", "耐えかねた末に：「耐えかねる」は「我慢できない」の意で、勝利と合わない", "耐えぬいたほど：「～ほど」は程度を表し、後ろの「勝利を収めた」と意味がつながらない", ""], "ex": "厳しい練習に<b>耐えぬいた末に</b>、ついに代表に選ばれた。"},
"27333": {"point": "「～たつもりが」は「～したと思っていたのに、実際は違った」という意味。話しやすいようにしたと思っていたのに、逆に緊張させてしまった。", "opts": ["ようにしたあげく：「～たあげく」は「さんざん～した結果、悪い結果になった」の意で、「逆に」と合わない", "", "ようになったものを：「～ものを」は不満や残念な気持ちを表し、文脈に合わない", "ようになったばかりか：「～ばかりか」は「～だけでなく」の意で、「逆に」と合わない"], "ex": "冗談を言った<b>つもりが</b>、相手を怒らせてしまった。"},
"27334": {"point": "「～ばかりとなる」は「あとは～するだけの状態になる」という意味。手続きが全部終わり、あとは出発を待つだけになった。", "opts": ["", "待つこともあるはずだ：意味が通らない", "待てなくなってしまった：「あとは」と合わない", "待てそうにないみたいだ：「待てそうにない」は自分の気持ちなのに「みたいだ」で推量していて不自然"], "ex": "料理の準備もでき、あとは客の到着を待つ<b>ばかりとなった</b>。"},
"27335": {"point": "「～っこない」は「絶対に～ない」という意味の話し言葉。2週間で10冊は絶対に読みきれないと思ったが、全部読んで返した。", "opts": ["読みかけなのか：「～かけ」は途中までの意で、借りたばかりの本には合わない", "読みっぱなしだろう：「～っぱなし」は「～したままにしておく」の意で、意味が通らない", "", "読んでもいないくせに：「～くせに」は非難を表し、意味が通らない"], "ex": "こんな難しい問題、私に解け<b>っこない</b>。"},
"27336": {"point": "「～こともあって」は「～という理由もあって」という意味。ペンギンの赤ちゃんが生まれたことも理由になって、いつも以上ににぎわっている。", "steps": "「生まれた」の後に「こともあって」が続く。次に「赤ちゃんを一目見よう」が「という」につながって「多くの人で」を修飾し、「いつも以上ににぎわっている」へ続く。", "ex": "連休という<b>こともあって</b>、道路はひどく混んでいた。"},
"27337": {"point": "「～なくして」は「～がなければ」、「何が～だ」は「～とは言えない」という強い反論。労働条件を改善しなければ業績向上はありえない、と述べている。", "steps": "「労働条件」の後に「の」「改善」が続いて「労働条件の改善」となる。次に「なくして」が続き、最後に「何」が文末の「が業績向上だ」につながる。", "ex": "努力<b>なくして</b>成功はありえない。"},
"27338": {"point": "「～にかけては」は「～については（ほかの人に負けない）」という意味。世界観に合わせて音楽を作る才能では、彼女より優れた作曲家はいない。", "steps": "「合わせて」の後に「音楽を作る」が続き、「才能にかけては」を修飾する。次に「彼女以上に優れている」が「作曲家はまずいない」を修飾し、文末の「だろう」につながる。", "ex": "料理の腕<b>にかけては</b>、彼の右に出る者はいない。"},
"27339": {"point": "「～にしろ」は「～としても」という意味。A社のものには遠く及ばないとしても、それなりに効率よく走れるものができた。", "steps": "「されている」の後に「A社が開発した」が続き、「ものには」を修飾する。次に「遠く及ばないにしろ」が続き、最後に「それなりに」が「効率よく走れる」につながる。", "ex": "どんな理由がある<b>にしろ</b>、暴力は許されない。"},
"27340": {"point": "「～こと＋数量」は「～を（その回数・期間）して」という意味。描いては直すことを数十回繰り返して、やっと納得のいくものができた。", "steps": "「描いては」の後に「直す」が続いて「描いては直す」となる。次に「を」「繰り返すこと」が続き、最後に「数十回」が来て「、やっと納得のいくものができた」につながる。", "ex": "待つ<b>こと</b>3時間、ようやく順番が回ってきた。"},
"27341_0": {"point": "父が子犬を連れてきた時の、筆者の状況を述べている。大学に通いながら仕事をしていた時期だった、という意味で「ころでした」が入る。", "opts": ["していたはずでした：予定や予想と違ったことを表す言い方で、文脈に合わない", "していたからでした：理由を表すが、前に理由を求める内容がなく、意味が通らない", "", "していたぐらいでした：程度を強調する言い方で、文脈に合わない"], "ex": "その知らせを聞いたのは、ちょうど家を出ようとしていた<b>ころでした</b>。"},
"27341_1": {"point": "前の文「『直司』と名付けました」の理由を後から補っている。「日本人の名前なら祖父も覚えられると思って（名付けた）」という意味で「思って」が入る。", "opts": ["思います：今の考えを述べる言い方で、名付けた理由にならない", "思うようです：他人の様子を推量する言い方で、自分のことには使わない", "思うのに：逆接を表し、意味が通らない", ""], "ex": "雨が降るかもしれないと<b>思って</b>、傘を持ってきた。"},
"27341_2": {"point": "「自分がもう1人いる」の「自分」は「いる」の主語。「ような感じ」の中の節なので、主語には「が」を使う。末っ子の自分のような存在がもう1人いる感じだ、という意味。", "opts": ["は：節の中の主語を表すには「が」が自然で、「は」では不自然になる", "", "も：「自分も」では、ほかにもう1人いる人がいることになり、意味が通らない", "だけ：限定を表し、意味が通らない"], "ex": "まるで子どもの頃の自分<b>が</b>そこにいるようだった。"},
"27341_3": {"point": "家を出てから、電話するたびに父や母に直司の様子を尋ねている。筆者の習慣的な動作なので「聞いています」が入る。", "opts": ["", "聞いてきます：「～てくる」は相手から自分に向かう動作などを表し、筆者が尋ねる文脈に合わない", "聞いてくれます：父や母が筆者のために聞く意味になり、合わない", "聞かれています：筆者が尋ねられる意味になり、合わない"], "ex": "毎週、母に電話して家族の様子を<b>聞いています</b>。"},
"27341_4": {"point": "最後に、直司の残りの人生もできるだけ近くにいたい、という筆者自身の希望を述べている。話し手の希望なので「いたいです」が入る。", "opts": ["", "いたがっています：「～たがる」は第三者の希望を表し、筆者自身には使わない", "いたのです：過去の説明になり、「残りの人生」と合わない", "いたことです：意味が通らない"], "ex": "これからも家族のそばに<b>いたいです</b>。"},
"27426": {"point": "「～に先立ち」は「～の前に、～を始める前に」という意味。美術館の閉館の前に、記念式典を行ったという内容。", "opts": ["", "次ぎ：「～に次ぎ」は「～の次に（順位・程度）」の意で、意味が通らない", "つけ：「～につけ」は「～するたびにいつも」の意で、意味が通らない", "つれ：「～につれ」は一方の変化に伴って他方も変化する意で、意味が通らない"], "ex": "開会<b>に先立ち</b>、主催者があいさつをした。"},
"27427": {"point": "「～がゆえに」は「～ため、～という理由で」という硬い表現。父親が有名な選手であるために、大きなプレッシャーに苦しんできた。", "opts": ["かというと：「～かというと」は「～かと言えば（実はそうではない）」の意で、意味が通らない", "", "といえば：「～といえば」は話題を取り上げる言い方で、後の文と合わない", "ように：「～ように」は様子や目的を表し、理由にならない"], "ex": "責任ある立場である<b>がゆえに</b>、発言には注意が必要だ。"},
"27428": {"point": "「～んなら（のなら）」は相手の話を受けて「～するのであれば」と条件にする言い方。妹が新宿に行くと聞いて、それを前提に買い物を頼んでいる。", "opts": ["行くと：「～と」は自然な結果や習慣を表し、後に依頼の文は来にくい", "行けば：「～ば」は一般的な仮定の条件で、相手の話を受けて頼む言い方にならない", "行ってたら：「行っていたら」はすでに行った状態を仮定する言い方で、これから出かける場面に合わない", ""], "ex": "駅に<b>行くんなら</b>、この手紙を出してきてくれる？"},
"27429": {"point": "「花を」があるので他動詞の「咲かせる」を使う。「木が花を咲かせる」は決まった言い方。", "opts": ["咲いた：「咲く」は自動詞で、「花を」と一緒に使えない", "咲いている：自動詞で「花を」と合わず、「今年初めて」とも合わない", "", "咲くだろう：自動詞で「花を」と合わず、推量も意味が通らない"], "ex": "庭のバラが美しい花を<b>咲かせた</b>。"},
"27430": {"point": "「お～願います」は相手に丁寧に依頼する表現。社内メールで、参加希望者に連絡を頼んでいる。", "opts": ["いたします：「お～いたす」は自分の動作をへりくだる謙譲語で、依頼にならない", "なさいます：「お～なさる」は相手の動作を高める尊敬語で、依頼の意味にならない", "", "申し上げます：「お～申し上げる」は自分の動作の謙譲語で、依頼にならない"], "ex": "会場内では携帯電話の電源をお切り<b>願います</b>。"},
"27431": {"point": "「～ないまでも」は「～とまではいかなくても」という意味。解決までは至らなくても、少なくとも気持ちは楽になる、という流れ。", "opts": ["ほどでは：「ないほどでは」という言い方はなく、意味が通らない", "ほどを：文法的につながらない", "", "までもが：「までもが」は「～さえも」の意で、「ないまでも」の形にならない"], "ex": "毎日とは言わ<b>ないまでも</b>、週に一度は運動したい。"},
"27432": {"point": "「～たつもりでも」は「自分では～したと思っていても（実際はそうではない）」という意味。きちんと洗ったと思っていても、汚れが残っているという流れ。", "opts": ["洗えるとは：「～とは」は驚きなどを表し、後の文と合わない", "洗えるとのことで：「～とのことで」は伝聞を表し、意味が通らない", "洗ったつもりだし：「～し」は理由を並べる言い方で、後の「汚れが残っている」と逆接にならない", ""], "ex": "説明した<b>つもりでも</b>、相手に伝わっていないことがある。"},
"27433": {"point": "「～（る）んじゃなかった」は「～しなければよかった」という後悔の表現。胃の調子が悪いので、夜中にラーメンを食べたことを悔やんでいる。", "opts": ["", "食べられるんじゃなかった：可能・受身の形で、自分の行動への後悔を表せない", "食べたんじゃなかった：「食べたのではなかった」は事実の否定になり、後悔の意味にならない", "食べられたんじゃなかった：可能・受身の過去で、意味が通らない"], "ex": "あんな映画、見に<b>行くんじゃなかった</b>。"},
"27434": {"point": "「～つつある」は変化が進んでいる途中であることを表す。主語が「関心が」なので、自動詞の「高まる」を使う。", "opts": ["", "高める見込みだ：「高める」は他動詞で、「関心が」と合わない", "高まるケースだ：「ケースだ」は事例を表し、変化の様子を述べる文に合わない", "高めることを余儀なくさせた：他動詞で「関心が」と合わず、意味も通らない"], "ex": "景気は少しずつ回復し<b>つつある</b>。"},
"27435": {"point": "「～としている」は組織などが「～と判断している、～と発表している」という報道の言い方。電力会社が停電の原因を発表している。", "opts": ["になっている：「～になっている」は状態や決まりを表し、会社の見解を示せない", "", "にある：「原因にある」は意味が通らない", "とある：「～とある」は書かれている内容を示す言い方で、会社の見解を伝える文に合わない"], "ex": "気象庁は、今後も強い雨が続くおそれがある<b>としている</b>。"},
"27436": {"point": "「～以上（は）」は「～したからには」という意味。「物事を始めてしまった以上、途中でやめるわけにはいかない」となる。", "steps": "「降りることができない」の後に「ことから」が続き、ことわざの由来を示す。次に「物事を始めてしまった」＋「以上」で「始めたからには」となり、「途中でやめるわけにはいかない」が文末の「ことのたとえである」につながる。", "ex": "約束した<b>以上</b>、必ず守ります。"},
"27437": {"point": "「～ていたら～はずだ」は、実際とは違うことを仮定して結果を想像する言い方。その内容を「と後悔する」で受け、「～ような生き方はしたくない」とまとめる。", "steps": "「振り返った時に」の後に、後悔の内容「あの時ああしていたら」「もっと素晴らしい人生を送れていたはずと」が続く。それを「後悔するような」が受けて「生き方は」を修飾し、文末の「したくない」につながる。", "ex": "もっと早く出発し<b>ていたら</b>、間に合った<b>はずだ</b>。"},
"27438": {"point": "「～ことによって」は手段、「～ことを目的に」は「～ために」という意味。", "steps": "「展開していくことに」の後に「よって」が続き、手段を表す。次に「豊かな社会の実現に寄与する」＋「ことを」＋「目的に」となり、文末の「活動をしています」につながる。", "ex": "地域の活性化<b>を目的に</b>、祭りが開かれた。"},
"27439": {"point": "「～のではという」は「～のではないかという」の省略で、心配や推測の内容を示し、後ろの名詞を説明する。", "steps": "「小学校だが」の後に、昔の状況を表す「かつては少子化で」が続く。次に「存続は難しい」＋「のでは」＋「という」で危機感の内容を示し、文末の「危機感があった」につながる。", "ex": "失敗する<b>のではという</b>不安が消えない。"},
"27440": {"point": "「～として（ある）まじき」は「～の立場の者として、決してしてはいけない」という意味。", "steps": "「教育関係者からは」の後に「教育現場の長」＋「として」が続き、立場を示す。次に「あるまじき」が「行為」を修飾し、それが「怒りの声が挙がった」につながる。", "ex": "人の命を預かる医師<b>としてあるまじき</b>行為だ。"},
"27441_0": {"point": "筆者も思春期に母親を疎ましく思っていた。それを受けて、主人公の鈴子にとっても母親は天敵のような存在だったと、筆者と同じであることを「も」で示している。", "opts": ["ではないが：「鈴子ではないが」は意味が通らない", "と同じく：「鈴子と同じく母親は」では、母親が鈴子と同じだという意味になり、文が成り立たない", "とは違って：筆者と同じく母親を疎ましく思っていたのだから、「違って」は合わない", ""], "ex": "この写真は、私<b>にとっても</b>大切な思い出だ。"},
"27441_1": {"point": "穏やかな日々を過ごしていた鈴子に、母親の体調が悪いという知らせが届く場面。物語の新しい展開で、日を特定しない「ある日」が入る。", "opts": ["", "あの日に：すでに話題に出た特定の日を指す言い方で、初めて出てくる出来事に合わない", "こうして：前の内容の結果を述べる言い方で、新しい出来事の始まりに合わない", "そうやって：前に述べた方法を受ける言い方で、意味が通らない"], "ex": "<b>ある日</b>、一通の手紙が届いた。"},
"27441_2": {"point": "筆者自身の気持ちを述べた部分。後の「居たたまれないような気持ちになることがある」からも、筆者がふだんからそう思っていることが分かる。", "opts": ["", "よく思うらしい：「らしい」は他人についての推量で、筆者自身の気持ちに合わない", "思った場合だ：意味が通らない", "思っただけだ：「だけだ」は限定を表し、後の文脈と合わない"], "ex": "もっと時間があればと<b>よく思う</b>。"},
"27441_3": {"point": "前で記憶は塗り変えられず胸を締め付けると述べ、後で新しい記憶を育むことは出来ると補っている。前の内容に条件や別の見方を付け加える「ただ」が入る。", "opts": ["それに：同じ方向の内容を付け加える言い方で、前後の内容が反対なので合わない", "", "だって：理由を述べる話し言葉で、意味が通らない", "まして：「なおさら」の意で、前後の関係に合わない"], "ex": "この店はおいしい。<b>ただ</b>、少し値段が高い。"},
"27441_4": {"point": "本を読み終えた筆者自身の行動。主語は筆者なので「鈴子は」は入らず、筆者が自分の母親に会いたくなって実家へ車を走らせたという意味になる。", "opts": ["鈴子は会いたくなって：本を閉じたのは筆者で、鈴子の行動ではない", "鈴子は母親に会いたくなって：主語が鈴子になり、「本を閉じた後」と合わない", "", "母親は鈴子に会いたくなって：主語が母親になり、「車を実家に走らせた」と合わない"], "ex": "久しぶりに母の声を聞いて、<b>会いたくなって</b>しまった。"},
"27526": {"point": "「～と引きかえに」は「～を得る代わりに」という意味。便利さを手に入れた代わりに、失ったものも少なくない、と述べている。", "opts": ["なくしては：「～なくしては」は「～がなければ（～できない）」の意で、「失った」と合わない", "と相まって：「～と相まって」は「～と一緒に作用して」の意で、意味が通らない", "のみならず：「～のみならず」は「～だけでなく」の意で、意味が通らない", ""], "ex": "彼は健康<b>と引きかえに</b>、莫大な財産を手に入れた。"},
"27527": {"point": "「～べく」は「～するために」という意味の硬い表現。地球環境を守るために、廃棄物の減量などに取り組んでいる。", "opts": ["守ろうとも：「～ようとも」は「たとえ～ても」という逆接で、意味が通らない", "守ればこそ：「～ばこそ」は「～からこそ」と理由を強調する言い方で、目的を表せない", "", "守るにせよ：「～にせよ」は「たとえ～としても」の意で、意味が通らない"], "ex": "夢を実現す<b>べく</b>、毎日練習を重ねている。"},
"27528": {"point": "「なにも～なくても」は「そこまで～する必要はない」と、相手の言動が大げさだと非難する言い方。少し遅れただけで、そんなに怒る必要はない。", "opts": ["まるで：「まるで～ようだ」のように比喩に使う言葉で、意味が通らない", "ちっとも：「ちっとも～ない」と否定を強める言葉で、「～なくてもいい」と合わない", "", "いっさい：「いっさい～ない」は「全く～ない」の意で、意味が通らない"], "ex": "<b>なにも</b>そこまで言わ<b>なくても</b>いいじゃないか。"},
"27529": {"point": "「～ったって」は「～と言っても」の話し言葉。「探して」と言われても、こんな広い場所では探しようがない、と反論している。", "opts": ["", "探すのかどうか：探すかどうかを問題にする言い方で、後の「どうやって探すの？」と合わない", "探すわりには：「～わりには」は「～から予想されるのとは違って」の意で、意味が通らない", "探すっていうより：「～というより」は別の言い方の方が適切だと述べる言い方で、意味が通らない"], "ex": "急げ<b>ったって</b>、もう間に合わないよ。"},
"27530": {"point": "「なんと～ことか」は「非常に～だ」と強い感動を表す言い方。富士山頂からの景色がとても美しかったことを述べている。", "opts": ["のか：疑問や問いかけを表し、感嘆の「なんと～」と合わない", "", "わけだ：「～わけだ」は当然の結果や納得を表す言い方で、意味が通らない", "ものだ：「～ものだ」は一般的な性質や過去の回想を表し、「なんと～」とは結びつかない"], "ex": "合格の知らせを聞いて、<b>なんと</b>うれしかった<b>ことか</b>。"},
"27531": {"point": "「～かと思えば」は「～と思うと、すぐに反対のことが起こる」という意味。甘えてきたと思うと、今度は呼んでも無視していなくなる、という気まぐれな様子を表している。", "opts": ["そうだと思って：「そう判断して」の意になり、反対の行動が続く文に合わない", "", "こうだと見て：「こうだと判断して」の意で、意味が通らない", "こうかと見れば：このような言い方はしない"], "ex": "弟は泣いていた<b>かと思えば</b>、もう笑っている。"},
"27532": {"point": "「～のをいいことに」は「～という状況を都合よく利用して（よくないことをする）」という意味。誰にも何も言われないのを利用して、だらしない生活をするようになった。", "opts": ["", "のがよければ：条件を表す言い方で、意味が通らない", "といいものだから：このような言い方はしない", "とよさそうなのに：逆接を表し、意味が通らない"], "ex": "先生がいない<b>のをいいことに</b>、生徒たちは騒ぎ始めた。"},
"27533": {"point": "「聞かせていただく」は、自分が聞くことをへりくだって言う謙譲表現。「～中で」は「～している過程で」という意味。取材で被害者の話を聞くうちに、苦労を知った。", "opts": ["聞いてくださる一方で：「～てくださる」は相手の動作に使う言い方で、話を聞いたのは話し手自身なので合わない。「一方で」も意味が通らない", "聞かせてくださる一方で：「一方で」は対比を表し、話を聞いて苦労を知ったという流れに合わない", "聞いていただく中で：「聞いていただく」は相手に聞いてもらう意味になり、話を聞いたのが話し手である文と合わない", ""], "ex": "多くの方のお話を<b>聞かせていただく中で</b>、この仕事の大切さに気づきました。"},
"27534": {"point": "「～しかあるまい」は「～するしかないだろう」という意味。すぐに契約を結ぶのは難しいので、根気よく交渉を重ねていくほかない、と判断している。", "opts": ["どころではなかろう：「～どころではない」は「～する余裕がない」の意で、意味が通らない", "", "などあるものか：「～などあるものか」は強い否定を表し、意味が通らない", "ことすらない：「～ことすらない」は「～さえしない」の意で、意味が通らない"], "ex": "誰も手伝ってくれないなら、自分でやる<b>しかあるまい</b>。"},
"27535": {"point": "「～てくれればよかったのに」は、相手がしてくれなかったことへの不満や残念な気持ちを表す。見かけたのに声をかけてくれなかったことを残念がっている。", "opts": ["くれたと思ったんだね：実際には声をかけてもらっていないので、意味が通らない", "もらったと思ったのに：自分の思い違いを表す言い方になり、意味が通らない", "", "もらえばよかったんだね：自分が頼めばよかったという意味になり、相手への不満を表せない"], "ex": "来るなら連絡して<b>くれればよかったのに</b>。"},
"27536": {"point": "「～を機に」は「～をきっかけに」、「～つつ」は「～ながら（も）」という意味。引越しをきっかけに、欲しかったソファを買うことにした。", "steps": "「引越しするのを機に」の後に「今まで欲しいと思いつつ」が続き、「買えずにいた」が「ソファを買うことにした」のソファを修飾する。最後に文末の「そうだ」につながる。", "ex": "就職<b>を機に</b>、一人暮らしを始めた。"},
"27537": {"point": "「～と言えば聞こえはいいが」は「よく言えば～だが、実際は」という意味。後の「要するに」で実際の姿を言い直している。", "steps": "「のどかな所」に「である」が付き、「と言えば」「聞こえはいいが」と続く。最後に「要するに」が「周りに田んぼしかない」につながる。", "ex": "自由業<b>と言えば聞こえはいいが</b>、実際は収入が不安定なだけだ。"},
"27538": {"point": "「～ごとき」は「～のような（取るに足りない）」という意味で、「私ごとき」は自分をへりくだって言う表現。", "steps": "「こんな大役が」の後に「私ごとき」が来て「新人に務まるのかと」を修飾し、「不安でいっぱいでしたが」で逆接となって、後の「先輩方の…おかげで」につながる。", "ex": "<b>私ごとき</b>がこのような賞をいただいてよいのでしょうか。"},
"27539": {"point": "「～ことなしに」は「～しないで」という意味。「～として」はここでは訴えの理由を示す。", "steps": "「同意を得る」に「こと」「なしに」が続いて「同意を得ないで」の意になり、「進めた」の後に「として」が来て、住民が市長を訴えた理由を表す。", "ex": "努力する<b>ことなしに</b>成功はありえない。"},
"27540": {"point": "「～現在」は「～の時点で」、「～における」は「～での」という意味。統計の基準となる日付を示している。", "steps": "「昨年4月1日」に「現在」が付き、「における」が「15歳未満の人口」を修飾する。最後に「は」で主題を示し、「一昨年と比べて」につながる。", "ex": "5月1日<b>現在</b>の会員数は300人だ。"},
"27541_0": {"point": "同時にいろいろなことをすると達成率が下がると分かっているので、自分への注意としてメモに書いた。「～ように」は、メモなどで指示や注意を表す。", "opts": ["消してもかまわない：許可を表し、自分を戒めるメモとして合わない", "消せなくて：理由や困った気持ちを表し、注意書きにならない", "", "消さないのではないか：推量を表し、自分への注意にならない"], "ex": "廊下は走らない<b>ように</b>。"},
"27541_1": {"point": "一日のうちに出てくるいろいろな自分の中には、ひどい者もいる、という意味。「ひどい」が直接かかり、後で「こいつは扱いにくい」と一人の小説係を取り上げる流れにもつながる。", "opts": ["", "そいつら：前に出た特定の人々を指す言葉で、「ひどい」の修飾を受けられない", "そんなやつ：「そんな」が指す内容が前になく、意味が通らない", "そんなやつら：「そんな」が指す内容が前になく、後で一人の小説係を取り上げる流れとも合わない"], "ex": "あいつは本当にいい<b>やつ</b>だ。"},
"27541_2": {"point": "前の文は他の係が時間帯や備品のコンディションを問わないことを述べ、後の文は小説係のわがままさを述べている。両者を対比しているので、逆接の「が」が入る。", "opts": ["ゆえに：「だから」の意で、前後に因果関係がないので合わない", "", "とはいえ：前のことを認めつつ、それと食い違う内容を述べる言い方で、別の係同士を対比する文脈に合わない", "また：並列や追加を表し、対比にならない"], "ex": "兄は背が高い。<b>が</b>、弟は小柄だ。"},
"27541_3": {"point": "文筆課はこの小説係を中心に作られたので、今更組織図から外すことはできない。「～わけにもいかない」は「事情があって～することもできない」という意味で、前の「しかし」の流れに合う。", "opts": ["外すべきではなかった：すでに外したことを後悔する言い方で、今も小説係の世話をしている状況と合わない", "外していないはずだ：推量を表し、意味が通らない", "外したとは思えない：過去の行為を推測する言い方で、意味が通らない", ""], "ex": "約束したので、今更断る<b>わけにもいかない</b>。"},
"27541_4": {"point": "「今日もわたしは、お茶を作り、お菓子を調達し」と、毎日くり返している行動を現在形で述べている。同じく現在形の「励ます」で文を結ぶ。", "opts": ["", "励ましたいのに：逆接で文が完結せず、意味が通らない", "励ますからだ：理由を述べる言い方で、前に理由を説明すべき内容がない", "励ましただろうか：過去への疑問を表し、「今日も」と合わない"], "ex": "試合に負けた後輩を<b>励ます</b>。"},
"27626": {"point": "「AにB」はAとBの組み合わせを表す。「Tシャツにジーンズ」で、その二つを合わせた服装を示している。", "opts": ["を：名詞同士を並べる助詞ではなく、組み合わせを表せない", "", "など：「Tシャツなどジーンズ」となり、意味が通らない", "ほど：程度を表す言い方で、組み合わせを表せない"], "ex": "ご飯<b>に</b>みそ汁という和風の朝食。"},
"27627": {"point": "「～ならではの」は「～だけにある、～でなければない特別な」という意味。海の町だからこそ楽しめる新鮮な魚料理を述べている。", "opts": ["なり：「～なり～なり」は例を挙げる言い方で、意味が通らない", "なくして：「～なくして」は「～がなければ」の意で、意味が通らない", "ながらに：「～ながらに」は「～のままで」の意で、意味が通らない", ""], "ex": "京都<b>ならではの</b>風景を楽しんだ。"},
"27628": {"point": "「なかなか」は肯定文で「予想以上に、かなり」の意。日本有数の水量を誇るだけあって、かなり見事な滝だったと評価している。", "opts": ["あえて：「わざわざ、無理に」の意で、意味が通らない", "まさか：後ろに否定や驚きの表現が来る言い方で、合わない", "", "かえって：「逆に、反対に」の意で、前の内容と合わない"], "ex": "初めて作ったにしては<b>なかなか</b>おいしい。"},
"27629": {"point": "「辞書形＋ところだった」は「もう少しで～しそうだった（が、実際はしなかった）」という意味。教えてもらえなかったら映画を見逃すところだった、という感謝の気持ち。", "opts": ["", "見逃さなかった：「見逃さなかったところだった」とは言わない", "見逃せる：可能形では「もう少しで～しそうだった」の意にならない", "見逃せなかった：意味が逆になり、文脈に合わない"], "ex": "寝坊して、もう少しで電車に乗り遅れる<b>ところだった</b>。"},
"27630": {"point": "「～かねない」は「～という悪い結果になるおそれがある」という意味。職人の高齢化が進むと、伝統技術が失われる心配があると述べている。", "opts": ["失われたようだ：すでに失われたという推量で、「このままでは」と合わない", "失われかけている：今まさに失われつつある状態で、「このままでは」の後の予測として合わない", "", "失われてはならない：義務・禁止の言い方で、予測を述べる文脈に合わない"], "ex": "このまま無理を続けると、体を壊し<b>かねない</b>。"},
"27631": {"point": "「～（よ）うにも～ない」は「～しようと思っても、できない」という意味。先輩が席にいないので、聞こうとしても聞けない。", "opts": ["聞いては：「～ては」は好ましくない結果を導く条件で、意味が通らない", "聞くには：「～には」は目的を表し、「聞けない」と合わない", "", "聞かずとも：「聞かなくても」の意で、意味が通らない"], "ex": "財布を忘れたので、買おう<b>にも</b>買えない。"},
"27632": {"point": "「～までになる」は「努力の結果、そこまで到達する」という意味。支店長を任されるほど出世したが、夢のために退職した、という流れ。", "opts": ["任されたまでは：後ろの「夢であった和菓子職人を目指し」とうまくつながらない", "任されたくらいでは：「その程度では不十分」の意で、文脈に合わない", "", "任されるくらいになれば：仮定の言い方で、過去の経歴を述べる文に合わない"], "ex": "彼は練習を重ね、全国大会に出場する<b>までになった</b>。"},
"27633": {"point": "「～てみなきゃわからない」は「実際にやってみなければわからない」という意味。「なきゃ」は「なければ」の話し言葉。", "opts": ["やってるって：「やっているそうだ」の意で、意味が通らない", "", "やっちゃうのが：意味が通らない", "やっちゃおうと：意味が通らない"], "ex": "おいしいかどうかは食べて<b>みなきゃ</b>わからない。"},
"27634": {"point": "「～ておけばいい」は「とりあえず～すれば十分だ」という意味。本当のことを言わず、適当に答えれば十分だと助言している。", "opts": ["答えてくれそうだよ：相手の行動を推量する言い方で、助言にならない", "答えられたせいだよ：原因を述べる言い方で、文脈に合わない", "答えただけのことだ：「それだけの話だ」の意で、助言にならない", ""], "ex": "細かいことは気にせず、「はい」と<b>言っておけばいい</b>よ。"},
"27635": {"point": "「～おそれがある」は「～という悪いことが起こる可能性がある」という意味。目標が高すぎると、やる気を失わせてしまう可能性がある、と理由を述べている。", "opts": ["失わせてしまってはならない：禁止の言い方で、「～からだ」と理由を述べる文に合わない", "失わせてしまいつつある：今まさに進行中の変化を表し、一般論に合わない", "失わせてしまうところだ：「もう少しで～する」の意で、一般論に合わない", ""], "ex": "台風が上陸する<b>おそれがある</b>。"},
"27636": {"point": "「～ところを助けられる」は「～している時に助けられる」という意味。わなで苦しんでいた時におじいさんに助けられた鶴の話。", "steps": "「苦しんでいる」の後に「ところを」が続き、「助けられた」で「鶴が」を修飾する。最後に「助けてくれた」が「おじいさんに」を修飾する。", "ex": "道に迷っている<b>ところを</b>親切な人に<b>助けられた</b>。"},
"27637": {"point": "「～わけにもいかない」は「事情があって～できない」という意味。見なかったことにして放っておくこともできず、起こして注意した。", "steps": "「見なかった」の後に「ことにして」が続き、「ほうっておく」が「わけにもいかず」につながる。最後に「起こして」が「注意することにした」に続く。", "ex": "頼まれたので、断る<b>わけにもいかず</b>引き受けた。"},
"27638": {"point": "「～にあって」は「～という状況で」という意味。短期的な成果が重視されがちな時代の中で、着実に成長している会社を紹介している。", "steps": "「重視されがちな」の後に「時代にあって」が続く。次に「目先の利益だけでなく」「日本の将来を見据えながら」と並び、「着実に成長を続けている」が「工作機械メーカー」を修飾する。", "ex": "厳しい経済状況<b>にあって</b>、売り上げを伸ばしている。"},
"27639": {"point": "「～にして初めて」は「～だからこそできる、～でなければできない」という意味。犯罪心理学に精通した専門家だからこそ書ける心理描写だと述べている。", "steps": "「精通した」の後に「専門家」が続き、「にして」「初めて」で「専門家でなければ」の意となる。最後に「書ける」が「ものである」に続く。", "ex": "長年の経験を積んだ職人<b>にして初めて</b>できる技だ。"},
"27640": {"point": "「それはそれで」は「それなりに、それとして」という意味。失敗しても、自分で決めたことならそれなりに一つの経験として受け入れられる。", "steps": "「自分が」の後に「決めたことなら」が続く。次に「それは」「それで」で「それはそれで」となり、最後に「ひとつの」が「経験として」を修飾する。", "ex": "雨の日の旅行も、<b>それはそれで</b>楽しかった。"},
"27641_0": {"point": "自然を観察した結果、「たしかに」直線と呼べるものはなかった、と確かめた内容が入る。可能形の否定「見つけられなかった」が自然。", "opts": ["", "見つけられなくなった：以前は見つけられたという変化を表し、文脈に合わない", "見つけないようにした：意図的に避けた意になり、観察の結果と合わない", "見つけようとしなかった：探す気がなかった意になり、「確かめるために観察」と合わない"], "ex": "いくら探しても、鍵は<b>見つけられなかった</b>。"},
"27641_1": {"point": "前の段落の「自然や身体には直線がない」ことと、「身の回りには直線が溢れていた」ことを対比している。対照的な事柄を並べる「一方で」が入る。", "opts": ["むしろ：「どちらかと言えば～のほうが」の意で、二つの事実を対比する文脈に合わない", "", "しかも：前の内容に同じ方向の内容を付け加える言い方で、対比に合わない", "それどころか：前の内容を否定し、さらに程度の高いことを述べる言い方で、合わない"], "ex": "兄は勉強が得意だ。<b>一方で</b>、弟はスポーツが得意だ。"},
"27641_2": {"point": "自然の造形と人工の造形の違いを理解したのは、身の回りの直線に気づいた子どもの頃だった、と時期を述べている。「その時のことである」が入る。", "opts": ["その時ぐらいである：「その時だけ」と程度を限定する言い方で、文脈に合わない", "その時だからである：理由を述べる言い方で、「理解したのは」と合わない", "その時のためである：目的を表す言い方で、意味が通らない", ""], "ex": "日本の文化に興味を持ったのは、高校生の<b>時のことである</b>。"},
"27641_3": {"point": "直前の「紀元前に作られた土器の模様」を受けて、そうした古い装飾を「こうした最古の装飾」と指している。", "opts": ["その他の：土器の模様以外のものを指すことになり、文脈に合わない", "例の：話し手と聞き手が共に知っている事柄を指す言い方で、文章の流れに合わない", "", "以下のような：後に述べる内容を指す言い方で、前の内容を受けられない"], "ex": "<b>こうした</b>問題は、どの国にも見られる。"},
"27641_4": {"point": "文章のまとめとして、装飾が人工と自然をつなぐ重要な役割を持っていると、筆者が断定的に結論を述べている。「持っているのだ」が入る。", "opts": ["", "持っているべきだ：当為を表す言い方で、事実を述べる結論に合わない", "持っていてほしい：願望の言い方で、「実のところ」と合わない", "持っていてもかまわない：許容の言い方で、「至要な役割」と合わない"], "ex": "音楽は人の心を癒やす力を<b>持っているのだ</b>。"},
"27726": {"point": "「Ｘこそ～が」は「Ｘは（できなかった）が、別の点では」という意味。優勝はできなかったが、自己ベスト更新という好成績を収めた、と対比している。", "opts": ["さえ：「優勝さえ逃した」は「優勝までも逃した」という意味になり、後の「好成績を収めた」と合わない", "", "ほど：程度を表す語で、「優勝ほど逃した」は意味が通らない", "ばかり：「～ばかり」は限定を表し、意味が通らない"], "ex": "賞<b>こそ</b>取れなかったが、多くの人に作品を見てもらえた。"},
"27727": {"point": "「～ことだから」は「～という事情なので」と、後の判断の理由を表す。息子も帰ってくるので、家族旅行に行こうと考えている。", "opts": ["ことだが：逆接になり、「家族旅行に行こう」と合わない", "ことでも：「帰ってくることでも」は意味が通らない", "", "こととはいえ：「～こととはいえ」は「～ではあるが」という逆接で、意味が通らない"], "ex": "せっかくの休みの<b>ことだから</b>、少し遠出しよう。"},
"27728": {"point": "「どうやら～ようだ」は「はっきりとは分からないが、どうも～らしい」という推測。兄の明るい表情から、面接がうまくいったと推測している。", "opts": ["仮に：「仮に～ても／たら」と仮定を表し、推測の「ようだ」と合わない", "まさか：「まさか～ないだろう」と否定の推量に使い、意味が通らない", "必ずしも：「必ずしも～ない」と部分否定に使い、意味が通らない", ""], "ex": "空が暗くなってきた。<b>どうやら</b>雨が降るようだ。"},
"27729": {"point": "「～ないものか」は「何とか～できないだろうか」と強く願う気持ちを表す。皿をもう少し良いものにしてほしいと願っている。", "opts": ["", "ものの：「～ものの」は「～けれども」という逆接で、文末の「と思う」と合わない", "ものだ：「使えないものだ」は「使えないのが当然だ」という意味になり、改善を願う文脈と合わない", "ものを：「～ものを」は「～のに」と不満を表し、後に続く文がなく意味が通らない"], "ex": "この渋滞、何とかならない<b>ものか</b>。"},
"27730": {"point": "「～じゃない」（上昇調）は「～ではないか」と、相手に確認しながら評価を伝える話し言葉。木村くんの心配に対し、先生がよく書けていると褒めている。", "opts": ["書けてなきゃ：「書けていなければ」という条件になり、褒める文脈と合わない", "書けてたらいいね：まだ結果が分からない場合の言い方で、既に読んだ先生の言葉として合わない", "", "書けてるかどうかだね：評価が決まっていない言い方で、木村くんの「ありがとうございます」と合わない"], "ex": "なんだ、ちゃんとできてる<b>じゃない</b>。"},
"27731": {"point": "「～とかで」は「～ということで」と、人から聞いた理由をあいまいに述べる言い方。テレビで紹介されたと聞いた、それが行列の理由になっている。", "opts": ["", "とかなら：仮定になり、すでに起きている行列の理由として合わない", "というのが：主語になる形で、後の文とつながらない", "というのも：「というのも～からだ」と前の文の理由を後で説明する形で、ここでは使えない"], "ex": "田中さんは風邪を引いた<b>とかで</b>、今日は休みだそうだ。"},
"27732": {"point": "「何の～にもなっていない」は「少しも～になっていない」と強く否定する言い方。「何の」は「も」を伴う否定と組み合わせて使う。社長の会見は少しも説明になっていなかった。", "opts": ["になっておらず：「何の」と呼応する「も」がなく、不自然", "", "になっているのではなく：「何の」と呼応せず、意味が通らない", "にもなっているのではなく：否定の形にならず、「何の」と呼応しない"], "ex": "そんな言い訳は<b>何の</b>解決<b>にもなっていない</b>。"},
"27733": {"point": "「～たり～なかったり」は「する時もしない時もある」という意味。山口さんは来ると言っても、来る日も来ない日もあるので分からない、と言っている。", "opts": ["来ても来なくても：「どちらでも関係ない」という意味で、後に続く判断がなく文が成り立たない", "来るか来ないか：「来るか来ないか分からない」のように後に述語が必要で、「だから」とつながらない", "", "来るのも来ないのも：後に述語が必要で、意味が通らない"], "ex": "彼は気分次第で、練習に来<b>たり来なかったり</b>だ。"},
"27734": {"point": "「危うく～ところだった」は「もう少しで～しそうだった（が、実際はしなかった）」という意味。強引な勧誘で、もう少しで入会させられそうになった。", "opts": ["", "されようがなかった：「～ようがない」は「方法がない」の意で、「危うく」と合わない", "させなかったのかと思った：意味が通らない", "しなかったことにした：「危うく」と呼応せず、意味が通らない"], "ex": "寝坊して、<b>危うく</b>飛行機に乗り遅れる<b>ところだった</b>。"},
"27735": {"point": "「～からって～わけじゃない」は「～からといって、必ず～というわけではない」という意味。見学しても入らなければならないわけではないので、気軽に見学を勧めている。", "opts": ["入りたがるだけじゃない：意味が通らない", "入らせないわけにはいかない：「入らせなければならない」の意で、気軽に誘う文脈と合わない", "入りたくないだけかもしれない：林さんの気持ちを推測する言い方で、見学に誘う文脈と合わない", ""], "ex": "高い<b>からって</b>、品質がいい<b>わけじゃない</b>。"},
"27736": {"point": "「～ことなく」は「～しないで」という意味。患者を待たせないで診察できるように、予約制を導入する。", "steps": "「患者を」の後に「待たせる」が続き、「ことなく」で「待たせないで」となる。次に「診察できる」が来て、「ように」で目的を表し、「近々予約制を導入する」につながる。", "ex": "彼は一度も休む<b>ことなく</b>、練習に通い続けた。"},
"27737": {"point": "「～がちな」は「～になりやすい」、「～だけに」は「～なので、なおさら」という意味。野菜不足になりやすいので、野菜ジュースがなおさらありがたい。", "steps": "「インスタント食品ばかり食べてしまって」の後に「野菜不足」「になり」が続く。「がちな」で「なりやすい」となり、「だけに」で理由を表して「ありがたい」につながる。", "ex": "期待していた<b>だけに</b>、負けたときのショックは大きかった。"},
"27738": {"point": "「～かといえばそうではない」は「必ずしも～ではない」という意味。洗剤を多く入れればきれいになるわけではない、と説明している。", "steps": "「洗濯物を」の後に「きれいに洗うには」が続き、「洗剤をたくさん入れればいいかといえば」で問いを立てる。「そうではなく」で否定し、「逆にすすぎ切れなかったりして」が「悪臭の原因にもなります」につながる。", "ex": "高い店ならおいしい<b>かといえば、そうではない</b>。"},
"27739": {"point": "「～からには」は「～以上は、当然」という意味。洋館があると知った以上、見ないで帰るわけにはいかない、という強い気持ちを表す。", "steps": "「前々から」の後に「近代建築に興味がある」が続き、「私としては」を修飾する。次に「それを知ったからには」で理由を述べ、「その洋館を見ずに」が「帰ることはできない」につながる。", "ex": "引き受けた<b>からには</b>、最後まで責任を持ってやるつもりだ。"},
"27740": {"point": "「～きっかけになれば（と思い）」は「～のきっかけになることを願って」という意味。野菜作りが農業を身近に考えるきっかけになることを願って提案した。", "steps": "「私は」の後に「育てた野菜を収穫して」が続き、「食べるということが」で主語になる。「農業を身近なものとして」が「考えるきっかけになれば」を修飾し、「と思い」につながる。", "ex": "この本が、読書を好きになる<b>きっかけになれば</b>と思う。"},
"27741_0": {"point": "冒頭の「まず一つは、『人間は謎』だということ」を受けて、知っておくべき言葉の一つ目をまとめている。次の段落が「それからもう一つは」と始まるので、「まず一つ」が入る。", "opts": ["あと：「あと一つ」は残りを表し、一つ目をまとめる文脈と合わない", "また：「また一つ」は追加を表し、最初の一つ目を述べる文脈と合わない", "", "もう：「もう一つ」は次の段落で二つ目に使われており、ここでは合わない"], "ex": "大切なことは二つある。<b>まず一つ</b>は、毎日続けることだ。"},
"27741_1": {"point": "相手に応じて見せる顔が変わる、という内容。上司の前、お得意様の前と、ほかの所に行けばまた違う顔をするので「別の」が入る。", "opts": ["同じ：相手に応じて顔が変わるという内容と反対になる", "", "そんな：直前に指す顔がなく、意味が通らない", "あのときの：特定の過去の顔を指し、文脈に合わない"], "ex": "家にいる時と会社にいる時とでは、<b>別の</b>顔を見せる人もいる。"},
"27741_2": {"point": "自分の暗い部分を最初からわかっていることが条件となり、その結果「すぐにでも心が平和になるだろう」と続く。条件を表す「いれば」が入る。", "opts": ["いて：単なるつなぎで、条件と結果の関係を表せない", "", "いるため：すでに成り立っている事実の理由を表す言い方で、「わかっていれば」という仮定の流れに合わない", "いたとしても：逆接になり、「心が平和になる」と合わない"], "ex": "早めに準備して<b>いれば</b>、慌てずに済む。"},
"27741_3": {"point": "暗い部分の存在を認識すれば、人間関係にはいろいろなことが関係しているということも自然に理解できるようになる、という筆者の推論。「わかってくるはずだ」が入る。", "opts": ["わかっていた：過去の事実を述べる形で、これから心が平和になるという流れと合わない", "わかってきたのか：疑問の形で、筆者の主張として合わない", "わかっているらしい：他人のことを伝聞・推量する言い方で、筆者の主張として合わない", ""], "ex": "経験を重ねれば、その意味も<b>わかってくるはずだ</b>。"},
"27741_4": {"point": "前の段落の「いつも光って見える」という明るい面に対し、裏側には真っ暗な部分がある、と反対の面を述べている。対比を表す「しかしその一方で」が入る。", "opts": ["", "そうしたからといって：前の内容は行為ではないので、「そうした」が指すものがない", "例えばこのように：前の内容の例を挙げるわけではなく、意味が通らない", "どちらかというとむしろ：二つを比べて一方を選ぶ言い方で、明暗の対比を表せない"], "ex": "この仕事は収入が多い。<b>しかしその一方で</b>、休みが少ない。"},
"32001": {"point": "「洪水」は「こうずい」。「洪」は音読み「こう」、「水」は連濁して「ずい」になる。「香水（こうすい）」と混同しないこと。", "meaning": "大雨などで川の水があふれ出ること。", "kr": "홍수", "opts": ["こうすい：「水」は連濁して「ずい」。「こうすい」は「香水」の読み", "", "きょうすい：「洪」は「こう」と読み、「きょう」とは読まない", "きょうずい：「洪」は「こう」"], "ex": "台風の大雨で川があふれ、<b>洪水</b>が起きた。"},
"32002": {"point": "「迅速」は「じんそく」。「迅」は濁って「じん」、「速」は「そく」。促音化はしない。", "meaning": "物事の進み方や行動が非常に速いこと。", "kr": "신속", "opts": ["", "しんそく：「迅」は濁って「じん」", "じっそく：促音化はせず「じんそく」", "しっそく：「迅」は「じん」。「しっそく」は「失速」の読み"], "ex": "事故の知らせを受け、消防は<b>迅速</b>に対応した。"},
"32003": {"point": "「合併」は「がっぺい」。「合」は「がっ」と促音化し、促音の後の「併（へい）」は半濁音化して「ぺい」になる。", "meaning": "二つ以上の会社・組織などが一つにまとまること。", "kr": "합병", "opts": ["がっへい：促音の後の「へい」は「ぺい」になる", "ごうへい：「合」は「がっ」、「併」は「ぺい」", "", "ごうぺい：「合」は「ごう」ではなく「がっ」"], "ex": "隣の町と<b>合併</b>して、新しい市が生まれた。"},
"32004": {"point": "「修行」は「しゅぎょう」。「修」は短く「しゅ」、「行」は「行列」と同じ「ぎょう」。「修」の「しゅう」と迷わせる問題。", "meaning": "学問・技芸・仏道などを身につけるため、努力して自分をきたえること。", "kr": "수행, 수련", "opts": ["", "しゅうぎょう：「修」は短く「しゅ」。「しゅうぎょう」は「就業」などの読み", "しゅこう：「行」は「ぎょう」。「しゅこう」は「趣向」の読み", "しゅうこう：「しゅう」も「こう」も誤り"], "ex": "父は若いころ、京都で料理人の<b>修行</b>を積んだ。"},
"32005": {"point": "「楽観」は「らっかん」。「楽」は「らく」で、後ろの「か」の前で促音化して「らっ」になる。「音楽」の「がく」と迷わせる問題。", "meaning": "物事がうまくいくと明るく考え、心配しないこと。", "kr": "낙관", "opts": ["がくかん：「楽観」の「楽」は「がく」ではなく「らく」", "がっかん：「楽」は「らっ」", "らくかん：「らく」は「か」の前で促音化して「らっ」", ""], "ex": "医者は、病状は<b>楽観</b>できないと言った。"},
"32006": {"point": "「圧迫」は「あっぱく」。「圧（あつ）」が促音化して「あっ」、その後の「迫（はく）」は半濁音化して「ぱく」になる。", "meaning": "強く押さえつけること。また、勢いや力で相手を苦しめること。", "kr": "압박", "opts": ["あっばく：促音の後は「ばく」ではなく「ぱく」", "あつばく：「圧」は促音化して「あっ」、「迫」は「ぱく」", "", "あつはく：促音化と半濁音化が起こって「あっぱく」"], "ex": "増え続ける医療費が国の財政を<b>圧迫</b>している。"},
"32007": {"point": "「治療」は「ちりょう」。「治」には「じ」（政治）の読みもあるが、ここは「ち」。「療」は長音で「りょう」。", "meaning": "病気やけがを治すために手当てをすること。", "kr": "치료", "opts": ["", "ちりょ：「療」は長音で「りょう」", "じりょう：「治」は「政治」の「じ」もあるが、「治療」では「ち」", "じりょ：「ち」「りょう」の両方が誤り"], "ex": "虫歯の<b>治療</b>のため、毎週歯医者に通っている。"},
"32008": {"point": "「恋愛」は「れんあい」。「恋」は「れん」、「愛」は「あい」。「反応（はんのう）」のように「ん」の後の「あ」行が「な」行に変わる語もあるが、「恋愛」は変わらない。", "meaning": "互いに恋をし、愛し合うこと。", "kr": "연애", "opts": ["れんない：「ん」の後でも「愛」は「あい」のまま", "", "れあい：「恋」は「れん」", "れない：「恋」は「れん」、「愛」は「あい」"], "ex": "姉は大学時代からの長い<b>恋愛</b>の末に結婚した。"},
"32009": {"point": "「復興」は「ふっこう」。「復（ふく）」が「こ」の前で促音化して「ふっ」になる。「興」は「こう」で、「興味」の「きょう」と迷わせる問題。", "meaning": "衰えたり壊れたりしたものが、再び盛んになること。", "kr": "부흥", "opts": ["ふっきょう：「興」は「こう」。「きょう」は「興味」の読み", "ふくきょう：「ふく」は促音化し、「興」も「こう」", "", "ふくこう：「復」は「こ」の前で促音化して「ふっ」"], "ex": "地震の後、町の<b>復興</b>には十年近くかかった。"},
"32010": {"point": "「事業」は「じぎょう」。「事」は「じ」、「業」は「ぎょう」。「企業（きぎょう）」と混同しないこと。", "meaning": "社会的・経済的な目的をもって、計画的に行う仕事。", "kr": "사업", "opts": ["きごう：「事」は「じ」、「業」は「ぎょう」。「きごう」は「記号」の読み", "じごう：「業」は「ぎょう」。「ごう」は「自業自得」などの読み", "きぎょう：「事」は「じ」。「きぎょう」は「企業」の読み", ""], "ex": "兄は会社を辞めて、小さな<b>事業</b>を始めた。"},
"32011": {"point": "「意向」は「いこう」。「向」は長音で、濁らずに「こう」と読む（方向・傾向）。", "meaning": "どうするつもりかという考え・気持ち。", "kr": "의향", "opts": ["いご：「向」は「こう」。「いご」は「以後」「囲碁」の読み", "いごう：「向」は濁らず「こう」", "いこ：「向」は長音で「こう」", ""], "ex": "会社は社員の<b>意向</b>を聞いてから計画を決めた。"},
"32012": {"point": "「内緒」は「ないしょ」。「緒」は短く「しょ」と読む。「情緒（じょうちょ）」の「ちょ」と迷わせる問題。", "meaning": "他人に知られないように隠しておくこと。秘密。", "kr": "비밀, 몰래", "opts": ["", "ないしょう：「緒」は短く「しょ」", "ないじょ：「緒」は濁らない", "ないちょ：「緒」は「情緒」の「ちょ」もあるが、「内緒」では「しょ」"], "ex": "このことはみんなには<b>内緒</b>にしておいてね。"},
"32013": {"point": "「海峡」は「かいきょう」。「峡」は音読み「きょう」（峡谷）。形の似た「狭（きょう）」と同じ音。", "meaning": "陸地にはさまれて、海が狭くなっている所。", "kr": "해협", "opts": ["かいこう：「峡」は「きょう」。「かいこう」は「海溝」「開港」の読み", "かいそう：「峡」は「きょう」。「かいそう」は「海草」「改装」の読み", "", "かいしょう：「峡」は「きょう」。「かいしょう」は「解消」の読み"], "ex": "船は夜のうちに<b>海峡</b>を渡った。"},
"32014": {"point": "「大衆」は「たいしゅう」。「大」は「だい」ではなく「たい」（大会・大切と同じ）、「衆」は長音で「しゅう」。", "meaning": "社会の大多数をしめる一般の人々。", "kr": "대중", "opts": ["だいしゅう：「大衆」の「大」は濁らず「たい」", "だいすう：「だいすう」は「代数」の読み。「衆」は「しゅう」", "", "たいすう：「衆」は「しゅう」"], "ex": "演歌は昔から<b>大衆</b>に愛されてきた。"},
"32015": {"point": "「誇張」は「こちょう」。「誇」は短く「こ」（訓は「ほこる」）、「張」は「ちょう」。促音化もしない。", "meaning": "実際よりも大げさに表すこと。", "kr": "과장", "opts": ["", "こうちょう：「誇」は短く「こ」。「こうちょう」は「校長」「好調」の読み", "こうちょ：「こう」も「ちょ」も誤り", "こっちょう：促音化はせず「こちょう」"], "ex": "彼の話はいつも少し<b>誇張</b>されている。"},
"32016": {"point": "「接触」は「せっしょく」。「接（せつ）」が「し」の前で促音化して「せっ」、「触」は「しょく」（訓は「ふれる」）。", "meaning": "近づいてふれること。また、人と関わりを持つこと。", "kr": "접촉", "opts": ["せっそく：「触」は「しょく」", "せつぞく：「せつぞく」は「接続」の読み", "", "ぜつじょく：「接」も「触」も濁らない"], "ex": "コードの<b>接触</b>が悪く、電気がついたり消えたりする。"},
"32017": {"point": "「領域」は「りょういき」。「領」は長音で「りょう」、「域」は濁らず「いき」（地域・区域）。", "meaning": "ある力や権限が及ぶ範囲。また、学問などで専門とする範囲。", "kr": "영역", "opts": ["りょいき：「領」は長音で「りょう」", "", "ろういき：「領」は「りょう」", "りょういぎ：「域」は濁らず「いき」"], "ex": "これは私の専門の<b>領域</b>ではないので、よくわからない。"},
"32018": {"point": "「訴訟」は「そしょう」。「訴」は短く「そ」（訓は「うったえる」）、「訟」は長音で「しょう」。長音の位置を迷わせる問題。", "meaning": "裁判所に訴えて、判決を求めること。", "kr": "소송", "opts": ["そうしょ：「訴」は短く「そ」、「訟」は長く「しょう」で、逆になっている", "そしょ：「訟」は長音で「しょう」", "そうしょう：「訴」は短く「そ」", ""], "ex": "住民たちは工場を相手に<b>訴訟</b>を起こした。"},
"32019": {"point": "「無念」は「むねん」。「無」には「ぶ」（無事・無難）の読みもあるが、ここは「む」。意味の近い「残念」と迷わせる問題。", "meaning": "悔しく思うこと。残念に思う気持ち。", "kr": "원통함, 분함", "opts": ["ざんねん：意味は近いが「残念」の読み。「無」は「ざん」と読まない", "なしねん：「無」を訓読みで読むのは誤り", "ぶねん：「無」には「ぶ」の読みもあるが、「無念」では「む」", ""], "ex": "決勝で一点差で負け、<b>無念</b>の涙を流した。"},
"32020": {"point": "「操縦」は「そうじゅう」。「操」は「そう」、「縦」は長音の「じゅう」（訓は「たて」）。", "meaning": "飛行機や機械などを思いどおりに動かすこと。また、人を思いどおりに動かすこと。", "kr": "조종", "opts": ["そうじゅ：「縦」は長音で「じゅう」", "", "そうじょ：「縦」は「じゅう」", "そうじょう：「縦」は「じゅう」。「そうじょう」は「相乗」などの読み"], "ex": "彼は子どものころからの夢をかなえ、旅客機を<b>操縦</b>している。"},
"32021": {"point": "「運輸」は「うんゆ」。「輸」は短く「ゆ」と読む（輸出・輸入と同じ）。", "meaning": "旅客や貨物を運ぶこと。", "kr": "운수, 운송", "opts": ["うんゆう：「輸」は短く「ゆ」", "うんしゅう：「輸」は「ゆ」と読む（輸出・輸入も「ゆ」）。「ゆ」を伸ばすのも誤り", "", "うんしゅ：「輸」は「ゆ」"], "ex": "鉄道や航空などの<b>運輸</b>業界は、燃料費の値上がりに苦しんでいる。"},
"32022": {"point": "「著名」は「ちょめい」。「著」は短く「ちょ」（著者）、「名」は「めい」。「名字（みょうじ）」の「みょう」と迷わせる問題。", "meaning": "名前が世の中に広く知られていること。", "kr": "저명", "opts": ["ちょうみょう：「著」は短く「ちょ」、「名」は「めい」", "ちょうめい：「著」は短く「ちょ」", "ちょみょう：「名」は「みょう」ではなく「めい」", ""], "ex": "その会議には<b>著名</b>な学者が大勢参加した。"},
"32023": {"point": "「衝突」は「しょうとつ」。「衝」は濁らず「しょう」（衝撃・折衝）、「突」は「とつ」。", "meaning": "ぶつかること。また、意見や利害が対立して争うこと。", "kr": "충돌", "opts": ["そうとつ：「衝」は「しょう」", "ぞうとつ：「衝」は「しょう」で、濁らない", "", "じょうとつ：「衝」は濁らず「しょう」"], "ex": "会議で二人の意見が正面から<b>衝突</b>した。"},
"32024": {"point": "「患者」は「かんじゃ」。「者」は「しゃ」だが、「ん」の後で濁って「じゃ」になる。「患」は「かん」（訓は「わずらう」）。", "meaning": "病気やけがで、医者の治療を受ける人。", "kr": "환자", "opts": ["かんしゃ：「者」は濁って「じゃ」。「かんしゃ」は「感謝」の読み", "ちゅうしゃ：「患」は「かん」。「ちゅうしゃ」は「注射」の読み", "", "ちゅうじゃ：「患」は「かん」"], "ex": "冬になると、かぜの<b>患者</b>が増える。"},
"32025": {"point": "「寿命」は「じゅみょう」。「寿」は短く「じゅ」、「命」は「めい」ではなく「みょう」と読む。", "meaning": "生物が生きている期間。また、物が使える期間。", "kr": "수명", "opts": ["じゅうみょう：「寿」は短く「じゅ」", "", "じゅうめい：「寿」は「じゅ」、「命」は「みょう」", "じゅめい：「命」は「生命」の「めい」ではなく「みょう」"], "ex": "この電池は<b>寿命</b>が長いので、取り替える手間が少ない。"},
"32026": {"point": "「赴任」は「ふにん」。「赴」は音読み「ふ」（訓は「おもむく」）、「任」は濁らず「にん」。", "meaning": "命じられた勤務地へ行くこと。", "kr": "부임", "opts": ["", "ふじん：「任」は「にん」。「ふじん」は「夫人」「婦人」の読み", "とにん：「赴」は「ふ」で、「と」とは読まない", "とじん：「ふ」「にん」の両方が誤り"], "ex": "父は来月から大阪へ単身<b>赴任</b>することになった。"},
"32027": {"point": "「優秀」は「ゆうしゅう」。「優」も「秀」も長音で、「ゆう」「しゅう」と読む。", "meaning": "他よりも特にすぐれていること。", "kr": "우수", "opts": ["", "ゆうしゅ：「秀」は長音で「しゅう」", "ゆうすう：「秀」は「しゅう」", "ゆしゅう：「優」は長音で「ゆう」"], "ex": "彼女はクラスで最も<b>優秀</b>な学生だ。"},
"32028": {"point": "「保障」は「ほしょう」。「保」は短く「ほ」、「障」は「しょう」（故障・障害）。", "meaning": "ある状態や権利が損なわれないように守ること。", "kr": "보장", "opts": ["ほうしょう：「保」は短く「ほ」", "", "ほうそう：「ほうそう」は「放送」「包装」の読み", "ほそう：「障」は「しょう」。「ほそう」は「舗装」の読み"], "ex": "憲法は国民の基本的人権を<b>保障</b>している。"},
"32029": {"point": "「妨害」は「ぼうがい」。「妨」は「方（ほう）」と違って濁って「ぼう」（訓は「さまたげる」）、「害」は「がい」。", "meaning": "他人のじゃまをすること。", "kr": "방해", "opts": ["ほうかい：「ぼう」「がい」の両方が誤り。「ほうかい」は「崩壊」の読み", "ほうがい：「妨」は濁って「ぼう」", "ぼうかい：「害」は濁って「がい」", ""], "ex": "工事の騒音で睡眠を<b>妨害</b>された。"},
"32030": {"point": "「秩序」は「ちつじょ」。「秩」は促音化せず「ちつ」、「序」は短く「じょ」（順序）。", "meaning": "社会や物事が正しい順序・決まりに従って整っている状態。", "kr": "질서", "opts": ["ちつじょう：「序」は短く「じょ」", "", "ちっじょう：「秩」は「ちつ」、「序」は「じょ」", "ちっじょ：「秩」は促音化せず「ちつ」"], "ex": "災害の後も、人々は<b>秩序</b>を守って列に並んだ。"},
"32031": {"point": "「収穫」は「しゅうかく」。「収」は長音で「しゅう」、「穫」は濁らず「かく」（「獲」と同じ音）。", "meaning": "農作物を取り入れること。また、得られた成果。", "kr": "수확", "opts": ["しゅうがく：「穫」は濁らず「かく」。「しゅうがく」は「修学」の読み", "", "しゅがく：「収」は「しゅう」、「穫」は「かく」", "しゅかく：「収」は長音で「しゅう」"], "ex": "今年はりんごの<b>収穫</b>が例年より多かった。"},
"32032": {"point": "「弁解」は「べんかい」。「解」は「かい」（解決・理解）。「解熱（げねつ）」の「げ」の読みもあるが、ここは「かい」。", "meaning": "失敗や過ちについて、言い訳をすること。", "kr": "변명", "opts": ["べんじょう：「解」は「かい」", "べんしょう：「解」は「かい」。「べんしょう」は「弁償」の読み", "べんがい：「解」は濁らず「かい」", ""], "ex": "遅刻の理由をいくら<b>弁解</b>しても、聞いてもらえなかった。"},
"32033": {"point": "「暖房」は「だんぼう」。「暖」は「だん」、「房」は長音で「ぼう」。反対語「冷房（れいぼう）」と迷わせる問題。", "meaning": "部屋などを暖めること。また、その装置。", "kr": "난방", "opts": ["れいぼう：「冷房」の読み。「暖」は「だん」", "れいぼ：「暖」は「だん」、「房」は長音で「ぼう」", "", "だんぼ：「房」は長音で「ぼう」"], "ex": "この部屋は<b>暖房</b>が効きすぎて暑い。"},
"32034": {"point": "「炭素」は「たんそ」。「炭」は濁らず「たん」（訓は「すみ」）、「素」も濁らず「そ」。", "meaning": "元素の一つ。木炭やダイヤモンドなどを形作っている。", "kr": "탄소", "opts": ["", "たんぞ：「素」は濁らず「そ」", "だんそ：「炭」は濁らず「たん」", "だんぞ：「炭」も「素」も濁らない"], "ex": "二酸化<b>炭素</b>の排出を減らす取り組みが進んでいる。"},
"32035": {"point": "「先端」は「せんたん」。「端」は音読み「たん」で濁らない。訓の「はし」と迷わせる問題。", "meaning": "細長い物の一番先の部分。また、時代や流行の一番先。", "kr": "첨단, 끝", "opts": ["せんだん：「端」は濁らず「たん」", "せんばし：「端」は訓の「はし」ではなく音の「たん」", "", "せんはし：「先」は音、「端」は訓の混ぜ読みで誤り"], "ex": "この研究所では最<b>先端</b>の医療技術を開発している。"},
"32036": {"point": "「瞬間」は「しゅんかん」。「瞬」は「しゅん」（訓は「またたく」）、「間」は「かん」。", "meaning": "きわめて短い時間。また、ある事が起こったちょうどその時。", "kr": "순간", "opts": ["すんかん：「瞬」は「しゅん」", "", "ずんかん：「瞬」は濁らず「しゅん」", "じゅんかん：「瞬」は濁らず「しゅん」。「じゅんかん」は「循環」の読み"], "ex": "ゴールが決まった<b>瞬間</b>、スタジアムは歓声に包まれた。"},
"32037": {"point": "「改革」は「かいかく」。「革」は「かく」（革命・変革）、訓は「かわ」。", "meaning": "制度や組織などを改めて、よりよく変えること。", "kr": "개혁", "opts": ["かいさん：「革」は「かく」。「かいさん」は「解散」の読み", "かいこう：「革」は「かく」。「かいこう」は「開校」などの読み", "かいてい：「革」は「かく」。「かいてい」は「改定」「改訂」の読み", ""], "ex": "新しい首相は税制の<b>改革</b>に取り組んでいる。"},
"32038": {"point": "「故障」は「こしょう」。「障」は「しょう」（障害・保障）、訓は「さわる」。", "meaning": "機械や体などの働きが悪くなること。", "kr": "고장", "opts": ["", "こせい：「障」は「しょう」。「こせい」は「個性」の読み", "こしゅう：「障」は「しょう」", "こすい：「障」は「しょう」。「こすい」は「湖水」の読み"], "ex": "エレベーターが<b>故障</b>して、階段で上がった。"},
"32039": {"point": "「探検」は「たんけん」。「探」は「たん」（訓は「さがす」）、「検」は「けん」で、どちらも濁らない。", "meaning": "危険をおかして、知られていない土地などを調べに行くこと。", "kr": "탐험", "opts": ["たんげん：「検」は濁らず「けん」", "", "だんげん：「探」も「検」も濁らない。「だんげん」は「断言」の読み", "だんけん：「探」は濁らず「たん」"], "ex": "子どもたちは裏山へ<b>探検</b>に出かけた。"},
"32040": {"point": "「外来」は「がいらい」。二字とも音読みで、「外」は「がい」、「来」は「らい」。訓読みとの混ぜ読みに注意。", "meaning": "外から来ること。また、病院に通って診察を受けること。", "kr": "외래", "opts": ["そとき：「外」も「来」も音読みで「がいらい」", "そとらい：「外」は訓の「そと」ではなく音の「がい」", "がいき：「来」は「らい」", ""], "ex": "<b>外来</b>の受付は午前十一時までです。"},
"32041": {"point": "「閉鎖」は「へいさ」。「鎖」は濁らず「さ」（訓は「くさり」）。", "meaning": "出入り口などを閉ざすこと。また、施設などの活動をやめること。", "kr": "폐쇄", "opts": ["へいさつ：「鎖」は「さ」で、「つ」は付かない", "へいざつ：「鎖」は濁らず「さ」", "", "へいざ：「鎖」は濁らず「さ」"], "ex": "大雪のため、高速道路の一部が<b>閉鎖</b>された。"},
"32042": {"point": "「基礎」は「きそ」。「礎」は短く「そ」（訓は「いしずえ」）。", "meaning": "建物の土台。また、物事が成り立つもとになるもの。", "kr": "기초", "opts": ["", "きそう：「礎」は短く「そ」", "きしょう：「礎」は「そ」。「きしょう」は「気象」「起床」の読み", "きしょ：「礎」は「そ」"], "ex": "外国語は<b>基礎</b>をしっかり身につけることが大切だ。"},
"32043": {"point": "「名簿」は「めいぼ」。「名」は「めい」、「簿」は「帳簿（ちょうぼ）」と同じく濁って「ぼ」。", "meaning": "関係者の名前や住所などを書き並べた帳面。", "kr": "명부, 명단", "opts": ["ほいほ：「名」は「めい」、「簿」は「ぼ」", "", "めいふ：「簿」は「ふ」ではなく「ぼ」", "めいぶ：「簿」は「ぶ」ではなく「ぼ」"], "ex": "参加者は受付で<b>名簿</b>に名前を書いてください。"},
"32044": {"point": "「考慮」は「こうりょ」。「考」は濁らず「こう」、「慮」は短く「りょ」（配慮・遠慮）。", "meaning": "いろいろな事情をよく考えに入れること。", "kr": "고려", "opts": ["ごうりょう：「考」は濁らず「こう」、「慮」は短く「りょ」", "ごうりょ：「考」は濁らず「こう」", "こうりょう：「慮」は短く「りょ」。「こうりょう」は「香料」などの読み", ""], "ex": "相手の立場も<b>考慮</b>して、返事をするべきだ。"},
"32045": {"point": "「抽選」は「ちゅうせん」。「抽」は長音で「ちゅう」、「選」は「せん」。", "meaning": "くじを引くこと。くじ引き。", "kr": "추첨", "opts": ["", "ちゅせん：「抽」は長音で「ちゅう」", "ちょうせん：「抽」は「ちゅう」。「ちょうせん」は「挑戦」の読み", "ちょせん：「抽」は「ちゅう」"], "ex": "商店街の<b>抽選</b>で旅行券が当たった。"},
"32046": {"point": "「宣伝」は「せんでん」。「伝」は音読み「でん」（伝言・伝統）で、「てん」とは読まない。", "meaning": "商品や考えなどを、多くの人に広く知らせること。", "kr": "선전, 광고", "opts": ["せんせん：「伝」は「でん」。「せんせん」は「宣戦」の読み", "せんぜん：「伝」は「でん」", "せんてん：「伝」は濁って「でん」", ""], "ex": "新しい映画の<b>宣伝</b>が駅のあちこちに貼られている。"},
"32047": {"point": "「汚染」は「おせん」。「汚」は音読み「お」（訓は「よごれる」「きたない」）、「染」は「せん」（訓は「そめる」）。", "meaning": "空気・水・土などが有害な物質でよごれること。", "kr": "오염", "opts": ["ごせん：「汚」は「お」", "", "ごぜん：「汚」は「お」、「染」は「せん」。「ごぜん」は「午前」の読み", "おぜん：「染」は濁らず「せん」"], "ex": "工場の排水による川の<b>汚染</b>が問題になっている。"},
"32048": {"point": "「秘密」は「ひみつ」。「秘」は「ひ」、「密」は「みつ」。意味の近い「機密（きみつ）」と迷わせる問題。", "meaning": "他人に知られないように隠していること。", "kr": "비밀", "opts": ["", "ひびつ：「密」は「みつ」", "きみつ：「秘」は「ひ」。「きみつ」は「機密」の読み", "きびつ：「秘」は「ひ」、「密」は「みつ」"], "ex": "二人が付き合っていることは、まだ<b>秘密</b>だ。"},
"32049": {"point": "「取材」は「しゅざい」。「取」は音読み「しゅ」（訓は「とる」）、「材」は「ざい」（材料）。", "meaning": "記事や作品の材料を、人に会ったり現地へ行ったりして集めること。", "kr": "취재", "opts": ["しょざい：「取」は「しゅ」。「しょざい」は「所在」の読み", "しょうざい：「取」は「しゅ」", "", "しゅうざい：「取」は短く「しゅ」"], "ex": "記者は被災地で住民に<b>取材</b>した。"},
"32050": {"point": "「安静」は「あんせい」。「静」は濁らず「せい」（静止・冷静）。「安定（あんてい）」と混同しないこと。", "meaning": "病気などのとき、体を動かさずに静かに休むこと。", "kr": "안정(安靜)", "opts": ["あんでい：「静」は「せい」", "あんてい：「静」は「せい」。「あんてい」は「安定」の読み", "あんぜい：「静」は濁らず「せい」", ""], "ex": "熱が下がるまで、家で<b>安静</b>にしていてください。"},
"32051": {"point": "「老い」は「おい」。動詞「老いる（おいる）」の連用形が名詞になった語。音読みは「ろう」（老人）。", "meaning": "年をとること。年をとって体や心が衰えること。", "kr": "늙음, 노화", "opts": ["やまい：「病（やまい）」の読み", "とい：「問い」の読み", "ふい：「不意」の読み", ""], "ex": "最近、階段を上るのがつらくなり、<b>老い</b>を感じる。"},
"32052": {"point": "「臨む」は「のぞむ」。ここでは「海に臨む」で、場所が海に面しているという意味。「望む」と同じ読みで、音読みは「りん」（臨時）。", "meaning": "（場所が）海や川などに面する。また、ある場面・事態に向かい合う。", "kr": "면하다, 임하다", "opts": ["", "はずむ：「弾む」の読み", "めぐむ：「恵む」の読み", "はげむ：「励む」の読み"], "ex": "選手たちは万全の態勢で決勝に<b>臨んだ</b>。"},
"32053": {"point": "「誤って」は「あやまって」。「誤る（あやまる）」は判断ややり方を間違えること。音読みは「ご」（誤解）。意味の近い「まちがって」と迷わせる問題。", "meaning": "判断や方法を間違える。", "kr": "그르치다, 잘못하다", "opts": ["まちがって：意味は近いが「間違って」の読み。「誤」の訓は「あやまる」", "", "しくじって：意味は近いが「誤」の読みではない", "あやつって：「操って」の読み"], "ex": "道を<b>誤って</b>、知らない村に出てしまった。"},
"32054": {"point": "「健やか」は「すこやか」。体や心が丈夫で元気な様子。音読みは「けん」（健康）。同じ「〜やか」の形容動詞と迷わせる問題。", "meaning": "体や心が丈夫で元気な様子。", "kr": "건강하다, 튼튼하다", "opts": ["なごやか：「和やか」の読み", "すみやか：「速やか」の読み", "", "さわやか：「爽やか」の読み"], "ex": "赤ちゃんは<b>健やか</b>に育っている。"},
"32055": {"point": "「大幅」は「おおはば」。「大」も「幅」も訓読みで、「おお」＋「はば」。音読みの「だい」「ふく」との混ぜ読みに注意。", "meaning": "数量や程度の変化が大きいこと。", "kr": "대폭", "opts": ["おおふく：「幅」は訓の「はば」。「ふく」は「振幅」などの音読み", "だいふく：音読みは誤り。「だいふく」は「大福」の読み", "", "だいはば：「大」も訓で「おお」"], "ex": "台風の影響で、電車のダイヤが<b>大幅</b>に乱れた。"},
"32056": {"point": "「真心」は「まごころ」。訓読みで「ま」＋「こころ」、「心」が連濁して「ごころ」になる。", "meaning": "うそや飾りのない、誠実な心。", "kr": "진심, 정성", "opts": ["まこころ：「心」は連濁して「ごころ」", "", "しんしん：音読みは誤り。「しんしん」は「心身」の読み", "しんじん：音読みは誤り。「しんじん」は「信心」などの読み"], "ex": "母の<b>真心</b>のこもった手紙に、思わず涙が出た。"},
"32057": {"point": "「人質」は「ひとじち」。「人」は訓「ひと」、「質」は「質屋（しちや）」の「しち」が連濁して「じち」になる特別な読み。", "meaning": "要求を通すために、捕らえて自由を奪っておく人。", "kr": "인질", "opts": ["にんしつ：「人」は「ひと」、「質」は「じち」", "ひとしち：「しち」は連濁して「じち」", "ひとじつ：「質」は「しつ」ではなく「しち」が濁った「じち」", ""], "ex": "犯人は<b>人質</b>を解放して、警察に投降した。"},
"32058": {"point": "「訪れた」は「おとずれた」。「訪れる（おとずれる）」は人や場所をたずねること。音読みは「ほう」（訪問）。", "meaning": "人や場所をたずねる。また、季節などがやってくる。", "kr": "방문하다, 찾아오다", "opts": ["すたれた：「廃れた」の読み", "ふくれた：「膨れた」の読み", "", "みだれた：「乱れた」の読み"], "ex": "長い冬が終わり、ようやく春が<b>訪れた</b>。"},
"32059": {"point": "「悪者」は「わるもの」。「悪（わる）」＋「者（もの）」の訓読み。音読みの「あくしゃ」とは読まない。", "meaning": "悪いことをする人。悪人。", "kr": "나쁜 사람, 악역", "opts": ["", "おもの：「悪」は「わる」。「お」は「悪寒」などの音読み", "あくしゃ：音読みは誤り。訓読みで「わるもの」", "あくじゃ：音読みは誤り。訓読みで「わるもの」"], "ex": "本当は彼のせいではないのに、いつも<b>悪者</b>にされる。"},
"32060": {"point": "「献立」は「こんだて」。「献」は普通「けん」（献血）だが、この語では特別に「こん」と読む。「立」は訓「たて」が連濁して「だて」。", "meaning": "料理の種類や組み合わせ、出す順序などの計画。メニュー。", "kr": "식단, 메뉴", "opts": ["", "こんりつ：「立」は「だて」", "けんだて：「献」は「けん」が普通だが、「献立」では「こん」", "けんりつ：「献」は「こん」、「立」は「だて」。「けんりつ」は「県立」の読み"], "ex": "今夜の<b>献立</b>は、焼き魚とみそ汁だ。"},
"32061": {"point": "「催して」は「もよおして」。「眠気を催す」は、眠気などの感覚が自然に起こること。「会を催す」（開く）の意味もある。音読みは「さい」（開催）。", "meaning": "ある気持ちや体の状態が起こる。また、会などを開く。", "kr": "(졸음 등을) 느끼다, 개최하다", "opts": ["みたして：「満たして」の読み", "", "はたして：「果たして」の読み", "ひやかして：「冷やかして」の読み"], "ex": "町内会では毎年夏に盆踊りを<b>催して</b>いる。"},
"32062": {"point": "「煩わしい」は「わずらわしい」。手間がかかってめんどうな様子。「煩う（わずらう）」と同じ読みで、音読みは「はん」（煩雑）。", "meaning": "手間がかかってめんどうだ。うっとうしい。", "kr": "번거롭다, 귀찮다", "opts": ["うるわしい：「麗しい」の読み", "いやわしい：このような語はない", "まぎらわしい：「紛らわしい」の読み", ""], "ex": "書類の手続きが多くて<b>煩わしい</b>。"},
"32063": {"point": "「素直」は「すなお」。「素」を「す」（素顔・素足の「す」）、「直」を「なお」と読む特別な読み方。意味の近い「率直（そっちょく）」と混同しないこと。", "meaning": "性格や態度にひねくれたところがなく、ありのままである様子。", "kr": "솔직하다, 순순하다", "opts": ["", "そちょく：音読みを並べた形だが、そういう読みはない", "そっちょく：「率直」の読み。意味は近いが漢字が違う", "すじき：「直」を「じき」と読むのは「正直（しょうじき）」など。この語では「なお」"], "ex": "子どもは注意されると、<b>素直</b>に謝った。"},
"32064": {"point": "「音色」は「ねいろ」。「音」を訓読みの「ね」（本音・音を上げるの「ね」）、「色」を「いろ」と読む。「おと」と読みたくなるのが落とし穴。", "meaning": "その楽器や声に特有の音の感じ。", "kr": "음색", "opts": ["おとしき：「音」は「ね」、「色」は「いろ」。「しき」は「景色」などの読み", "ねしき：「色」は訓読みで「いろ」", "おといろ：「音」はこの語では「ね」と読む", ""], "ex": "このギターは柔らかい<b>音色</b>が魅力だ。"},
"32065": {"point": "「描く」は「えがく」（「かく」とも読む）。絵や文章で様子を表すこと。音読みは「ビョウ」（描写）。", "meaning": "絵や文章などで、物事の姿や様子を表現すること。", "kr": "그리다, 묘사하다", "opts": ["", "きずいた＝築いた。「描」の読みではない", "さばいた＝裁いた・捌いた。「描」の読みではない", "もがいた＝苦しんで手足を動かした。「描」の読みではない"], "ex": "この小説は戦後の若者の姿をリアルに<b>描いて</b>いる。"},
"32066": {"point": "「傾ける」は「かたむける」。「傾く（かたむく）」の他動詞で、「心を傾ける」は一つのことに心を集中させること。音読みは「ケイ」（傾向）。", "meaning": "斜めにすること。「心・耳を傾ける」の形で、そのことに心を集中すること。", "kr": "기울이다", "opts": ["むけて＝向けて。「傾」の読みではない", "さずけて＝授けて。「傾」の読みではない", "", "もうけて＝設けて・儲けて。「傾」の読みではない"], "ex": "彼は部下の意見に熱心に耳を<b>傾けた</b>。"},
"32067": {"point": "「整える」は「ととのえる」。乱れたものをきちんとした状態にすること。「整う（ととのう）」と同じ読み。音読みは「セイ」（整理）。", "meaning": "乱れているものをきちんとした状態にすること。", "kr": "가다듬다, 정돈하다", "opts": ["そなえて＝備えて・供えて。「整」の読みではない", "ひかえて＝控えて。「整」の読みではない", "ふまえて＝踏まえて。「整」の読みではない", ""], "ex": "面接の前に、鏡の前で髪を<b>整えた</b>。"},
"32068": {"point": "「劣る」は「おとる」。能力や価値が他より低いこと。音読みは「レツ」（劣等・劣悪）。反対の意味の「勝る（まさる）」と混同しないこと。", "meaning": "能力や価値が他より低いこと。", "kr": "뒤떨어지다, 못하다", "opts": ["ほこる＝誇る。「劣」の読みではない", "", "まさる＝勝る・優る。「劣る」とは反対の意味", "はかる＝計る・測る・図る。「劣」の読みではない"], "ex": "値段は安いが、品質は他社の製品に<b>劣らない</b>。"},
"32069": {"point": "「黙る」は「だまる」。何も言わないでいること。音読みは「モク」（沈黙・黙読）。", "meaning": "何も言わないでいること。口を閉じること。", "kr": "잠자코 있다, 입을 다물다", "opts": ["かたって＝語って。「黙」の読みではない", "もぐって＝潜って。「黙」の読みではない", "", "すわって＝座って。「黙」の読みではない"], "ex": "彼は何を聞かれても<b>黙った</b>まま下を向いていた。"},
"32070": {"point": "「練り直す」は「ねりなおす」。「練る（ねる）」＋「直す（なおす）」で、計画や案をもう一度よく考え直すこと。音読みは「レン」（練習）。", "meaning": "計画や案などを、もう一度よく考えて作り直すこと。", "kr": "다시 짜다, 재검토하다", "opts": ["ひねりだした＝捻り出した。「練」の読みではない", "やりなおした＝やり直した。「練」を「や」とは読まない", "", "ぬりなおした＝塗り直した。「塗」の読みで、「練」ではない"], "ex": "予算が足りないので、企画を一から<b>練り直す</b>ことにした。"},
"32071": {"point": "「見逃す」は「みのがす」。「逃す（のがす）」は「逃げる（にげる）」と同じ漢字だが読みが違うので注意。ここでは、悪いことを知りながら許すという意味。", "meaning": "見ていながら気づかずにいること。また、悪いことを知りながらとがめずに許すこと。", "kr": "눈감아 주다, 놓치다", "opts": ["みにげして：「にげ」は「逃げる」の読み。「見逃す」は「のがす」", "", "みはがして：「はがす」は「剥がす」。「逃」の読みではない", "みなおして＝見直して。「逃」の読みではない"], "ex": "一度だけなら、この失敗は<b>見逃して</b>あげよう。"},
"32072": {"point": "「値引き」は「ねびき」。「値」を訓読みの「ね」（値段の「ね」）と読み、「引き」は連濁して「びき」になる。", "meaning": "決まっている値段から、いくらか安くすること。", "kr": "할인, 가격 인하", "opts": ["あたいびき：「値」を「あたい」と読むのは「値する」など。この語では「ね」", "あたいひき：「値」は「ね」、「引き」は連濁して「びき」", "", "ねひき：「引き」は連濁して「びき」"], "ex": "閉店前になると、弁当が半額に<b>値引き</b>される。"},
"32073": {"point": "「操る」は「あやつる」。人を陰から思いどおりに動かすこと。音読みは「ソウ」（操作・体操）。", "meaning": "人を陰から思いどおりに動かすこと。また、道具や言葉などをうまく使いこなすこと。", "kr": "조종하다, 다루다", "opts": ["まかなって＝賄って。「操」の読みではない", "とどこおって＝滞って。「操」の読みではない", "さえぎって＝遮って。「操」の読みではない", ""], "ex": "彼女は五か国語を自由に<b>操る</b>。"},
"32074": {"point": "「手薄」は訓読みで「てうす」。「手」を「て」、「薄」を「うす」（薄いの「うす」）と読む。音読みの「ハク」（薄弱）と混同しないこと。", "meaning": "人手や物の数量が少なく、不十分なこと。", "kr": "허술함, 부족함", "opts": ["てはく：「薄」は訓読みで「うす」", "", "しゅはく：両方音読みにした形。この語は訓読み", "しゅうす：「手」は「て」と読む"], "ex": "夜間は警備が<b>手薄</b>になりやすい。"},
"32075": {"point": "「間柄」は訓読みで「あいだがら」。「間」を「あいだ」、「柄」を「がら」（人柄・家柄の「がら」）と読む。人と人との関係を表す。", "meaning": "人と人との関係。親族関係や付き合いの関係。", "kr": "사이, 관계", "opts": ["まへい：「柄」の音読み「ヘイ」は「横柄」などで使う。この語は「あいだがら」", "けんへい：「間」「柄」の音読みを並べた形。この語は訓読み", "まがら：「間」はここでは「あいだ」", ""], "ex": "彼とは何でも話せる<b>間柄</b>だ。"},
"32076": {"point": "「慰める」は「なぐさめる」。悲しみや苦しみをやわらげること。音読みは「イ」（慰安・慰労）。", "meaning": "悲しみや苦しみをやわらげ、心を楽にさせること。", "kr": "위로하다, 달래다", "opts": ["ながめた＝眺めた。「慰」の読みではない", "ちぢめた＝縮めた。「慰」の読みではない", "", "めざめた＝目覚めた。「慰」の読みではない"], "ex": "試合に負けた後輩を、先輩たちが優しく<b>慰めた</b>。"},
"32077": {"point": "「地元」は「じもと」。「地」を「じ」（地面・地震の「じ」）、「元」を訓読みの「もと」と読む重箱読み。", "meaning": "その物事に直接関係のある土地。また、自分が住んでいる土地。", "kr": "그 고장, 현지", "opts": ["ちげん：両方音読みにした形。この語は「じもと」", "ちもと：「地」はこの語では「じ」", "じげん：「元」は「もと」。「じげん」は「次元」の読み", ""], "ex": "大学を卒業した後、<b>地元</b>の企業に就職した。"},
"32078": {"point": "「焦る」は「あせる」。思うようにいかず、気持ちが落ち着かないこと。同じ字の「焦げる（こげる）」と読みが違う。音読みは「ショウ」（焦点）。", "meaning": "思うようにならず、早くしようとして落ち着きを失うこと。", "kr": "초조해하다, 조급해하다", "opts": ["とどこおって＝滞って。「焦」の読みではない", "とどまって＝留まって・止まって。「焦」の読みではない", "さとって＝悟って。「焦」の読みではない", ""], "ex": "時間がないからといって<b>焦る</b>と、かえってミスが増える。"},
"32079": {"point": "「手際」は「てぎわ」。「際（きわ）」が連濁して「ぎわ」になる（「窓際（まどぎわ）」と同じ）。音読みの「サイ」（国際）と混同しないこと。", "meaning": "物事を処理するやり方や腕前。", "kr": "솜씨, 수완", "opts": ["てきわ：「際」は連濁して「ぎわ」", "", "しゅさい：音読みにした形。「主催」と同じ音で、この語の読みではない", "しゅざい：音読みにした形。「取材」と同じ音で、この語の読みではない"], "ex": "彼女は<b>手際</b>よく夕食の準備を済ませた。"},
"32080": {"point": "「目覚ましい」は「めざましい」。「目覚ます（めざます）」から来た形容詞で、「覚」は連濁して「ざ」になる。驚くほどすばらしい様子を表す。", "meaning": "驚くほどすばらしい様子。", "kr": "눈부시다, 놀랍다", "opts": ["めさましい：「覚」は連濁して「ざ」", "", "まさましい：「目」はここでは「め」。「覚」も連濁して「ざ」", "まざましい：「目」はここでは「め」"], "ex": "この国の経済は<b>目覚ましい</b>発展を遂げた。"},
"32081": {"point": "「踏む」は「ふむ」。「手続きを踏む」は、決められた順序どおりに物事を行うこと。音読みは「トウ」（踏襲）。", "meaning": "足で押さえつけること。「手続き・段階を踏む」の形で、決められた順序どおりに行うこと。", "kr": "밟다, 거치다", "opts": ["", "かむ＝噛む。「踏」の読みではない", "のむ＝飲む。「踏」の読みではない", "はげむ＝励む。「踏」の読みではない"], "ex": "正式な手順を<b>踏んで</b>、申請を行ってください。"},
"32082": {"point": "「尋ねる」は「たずねる」。わからないことを人に聞くこと。同じ音の「訪ねる（訪問する）」と使い分ける。音読みは「ジン」（尋問）。", "meaning": "わからないことを人に聞くこと。", "kr": "묻다, 질문하다", "opts": ["かさねよう＝重ねよう。「尋」の読みではない", "つらねよう＝連ねよう。「尋」の読みではない", "たばねよう＝束ねよう。「尋」の読みではない", ""], "ex": "駅員に乗り換えの方法を<b>尋ねた</b>。"},
"32083": {"point": "「懲りる」は「こりる」で、「懲りず」はひどい目にあってもやめずに、という意味。音読みは「チョウ」（懲役・懲罰）。", "meaning": "（「懲りる」）ひどい目にあって、もうしないと思うこと。「懲りず」は、それでもやめずに、の意味。", "kr": "질리지 않고, 단념하지 않고", "opts": ["かりず：「借りず」の読み。「懲」の読みではない", "", "おりず：「降りず・下りず」の読み。「懲」の読みではない", "ちょうりず：音読み「チョウ」を混ぜた形で、そういう読みはない"], "ex": "彼は何度断られても<b>懲りずに</b>誘い続けている。"},
"32084": {"point": "「隠れる」は「かくれる」。人に見えない所に身を置くこと。音読みは「イン」（隠居）。", "meaning": "人に見えない所に身を置くこと。", "kr": "숨다", "opts": ["すたれた＝廃れた。「隠」の読みではない", "のがれた＝逃れた。「隠」の読みではない", "", "たれた＝垂れた。「隠」の読みではない"], "ex": "子どもたちはカーテンの後ろに<b>隠れて</b>遊んでいる。"},
"32085": {"point": "「励ます」は「はげます」。元気づけてやる気を起こさせること。「励む（はげむ）」と同じ読み。音読みは「レイ」（激励・奨励）。", "meaning": "元気づけて、やる気を起こさせること。", "kr": "격려하다", "opts": ["れいまして：音読み「レイ」を使った形で、そういう読みはない", "", "すまして＝済まして・澄まして。「励」の読みではない", "なやまして＝悩まして。「励」の読みではない"], "ex": "友人たちに<b>励まされて</b>、もう一度挑戦する気になった。"},
"32086": {"point": "「避ける」は「さける」。好ましくないものに近づかないようにすること。音読みは「ヒ」（避難・回避）。", "meaning": "好ましくないものに近づかないようにすること。", "kr": "피하다", "opts": ["もうけて＝設けて・儲けて。「避」の読みではない", "", "かたむけて＝傾けて。「避」の読みではない", "うけて＝受けて。「避」の読みではない"], "ex": "混雑を<b>避けて</b>、朝早く出かけた。"},
"32087": {"point": "「強める」は「つよめる」。「強い（つよい）」から来た動詞で、力や程度を強くすること。意味の近い「高める（たかめる）」と混同しないこと。", "meaning": "力や程度を強くすること。", "kr": "강화하다, 세게 하다", "opts": ["かためて＝固めて。「強」の読みではない", "さだめて＝定めて。「強」の読みではない", "", "たかめて＝高めて。意味は近いが「高」の読み"], "ex": "警察は飲酒運転の取り締まりを<b>強めて</b>いる。"},
"32088": {"point": "「眺める」は「ながめる」。遠くや全体をじっと見ること。「つくづく眺める」は、しみじみと見つめること。音読みは「チョウ」（眺望）。", "meaning": "遠くや全体をじっと見ること。また、見つめながら物思いにふけること。", "kr": "바라보다", "opts": ["そめる＝染める。「眺」の読みではない", "しずめる＝沈める・静める。「眺」の読みではない", "さだめる＝定める。「眺」の読みではない", ""], "ex": "窓から夕日に染まる海を<b>眺めた</b>。"},
"32089": {"point": "割合を表す「割」は訓読みで「わり」。「1割」は10パーセント。音読みの「カツ」は「分割・割愛」などの熟語で使う。", "meaning": "全体を十等分したうちの一つ分。10パーセント。", "kr": "할(10퍼센트)", "opts": ["", "かつ：音読み「カツ」は「分割」などの熟語の読み。割合を表すときは「わり」", "たし：「足し」の読み。「割」の読みではない", "かけ：「掛け」の読み。「割」の読みではない"], "ex": "会員になると、全商品が2<b>割</b>引きになる。"},
"32090": {"point": "「透き通る」は「すきとおる」。「透く（すく）」＋「通る（とおる）」。「通る」は「とおる」と長音を「お」で書く。音読みは「トウ」（透明）。", "meaning": "物を通して向こうがはっきり見えること。また、声などが澄んでいること。", "kr": "투명하다, 비쳐 보이다", "opts": ["", "ときとおる：「透」は訓読みで「す（く）」", "つきとおる：「突き通る」の読み。「透」は「す（く）」", "はきとおる：「透」を「は」とは読まない"], "ex": "この湖の水は底まで<b>透き通って</b>いる。"},
"32091": {"point": "「上回る」は「うわまわる」。「上」を「うわ」と読むのは「上着・上履き」などと同じ。反対語は「下回る（したまわる）」。", "meaning": "ある数量や程度を超えること。", "kr": "웃돌다, 상회하다", "opts": ["", "したたまわる：「上」を「した」とは読まない。「した」は「下」の読み", "うえまわる：この語では「上」は「うわ」", "しもまわる：「上」を「しも」とは読まない。「しも」は「下」の読み"], "ex": "今年の売り上げは、去年を大きく<b>上回った</b>。"},
"32092": {"point": "「経る」は「へる」で、「〜を経て」はある場所や段階を通って、という意味。同じ字の「経つ（たつ）」は時間が過ぎる意味で、ここには合わない。音読みは「ケイ」（経由）。", "meaning": "ある場所や段階を通って過ぎること。", "kr": "거치다", "opts": ["えて＝得て。「経」の読みではない", "そって＝沿って。「経」の読みではない", "", "たって：「経つ」は時間が過ぎる意味。「〜を経て（場所を通って）」は「へて」"], "ex": "彼は営業部を<b>経て</b>、現在は企画部で働いている。"},
"32093": {"point": "「雷」は訓読みで「かみなり」。音読みは「ライ」（落雷・雷雨）。", "meaning": "雲と雲、雲と地面の間で起こる放電。また、それによって起こる大きな音。", "kr": "천둥, 벼락", "opts": ["みなもと＝源。「雷」の読みではない", "おもむき＝趣。「雷」の読みではない", "たましい＝魂。「雷」の読みではない", ""], "ex": "遠くで<b>雷</b>が鳴り始めたので、急いで家に帰った。"},
"32094": {"point": "「取引」は「とりひき」。「取り引き」の送り仮名を省いた形で、「引」は連濁せず「ひき」と読む。", "meaning": "商売として、物やお金をやりとりすること。", "kr": "거래", "opts": ["とりびき：「引」は連濁せず「ひき」", "じゅいん：「取」の音読みは「シュ」。この語は訓読み", "", "しゅいん：音読みを並べた形。この語は訓読みで「とりひき」"], "ex": "その会社とは十年以上<b>取引</b>が続いている。"},
"32095": {"point": "「交わす」は「かわす」。「議論・言葉を交わす」のように、互いにやりとりすること。音読みは「コウ」（交換）。", "meaning": "やりとりすること。互いに〜し合うこと。", "kr": "주고받다, 나누다", "opts": ["", "がわした：語の初めは濁らず「か」", "あわした：「合わした」の読み。「交」の読みではない", "こわした＝壊した。「交」の音読み「コウ」と混同しないこと"], "ex": "二人は笑顔で握手を<b>交わした</b>。"},
"32096": {"point": "「雪崩」は熟字訓で「なだれ」。一字ずつの読み（「雪＝ゆき」「崩＝くず・ほう」）とは関係なく、二字まとめて読む。", "meaning": "山の斜面に積もった大量の雪が、一度に崩れ落ちること。", "kr": "눈사태", "opts": ["ゆくえ＝行方（熟字訓）。「雪崩」の読みではない", "", "せつほう：音読み「セツ・ホウ」を並べた形。この語は熟字訓", "ゆきだれ：一字ずつ訓読みしたような形で、誤り"], "ex": "春先は気温が上がり、<b>雪崩</b>が起きやすい。"},
"32097": {"point": "「合間」は訓読みで「あいま」。「合」を「あい」（話し合いの「あい」）、「間」を「ま」（すき間の「ま」）と読む。", "meaning": "物事と物事の間の、短い空き時間。", "kr": "짬, 틈", "opts": ["あいかん：「間」は訓読みで「ま」", "", "ごうま：「合」は訓読みで「あい」", "ごうかん：両方音読みにした形で、誤り"], "ex": "仕事の<b>合間</b>にコーヒーを飲んで一息ついた。"},
"32098": {"point": "「醜い」は「みにくい」。見た目や行いが見苦しいこと。「醜い争い」は見苦しい争い。音読みは「シュウ」（醜悪・醜態）。", "meaning": "見た目が悪い様子。また、行いや態度が見苦しく、恥ずかしい様子。", "kr": "추하다, 보기 흉하다", "opts": ["", "こころよい＝快い。「醜」の読みではない", "いちじるしい＝著しい。「醜」の読みではない", "いさぎよい＝潔い。「醜」の読みではない"], "ex": "遺産をめぐって、兄弟が<b>醜い</b>争いを続けている。"},
"32099": {"point": "「稲」は訓読みで「いね」。複合語では「いな」と読むこともある（稲作・稲妻）。音読みは「トウ」（水稲）。", "meaning": "米を実らせる植物。主に水田で育てる。", "kr": "벼", "opts": ["くき＝茎。「稲」の読みではない", "しお＝塩・潮。「稲」の読みではない", "つつ＝筒。「稲」の読みではない", ""], "ex": "秋になると、田んぼの<b>稲</b>が黄金色に実る。"},
"32100": {"point": "「競う」は「きそう」。互いに負けまいと張り合うこと。意味の近い「争う（あらそう）」と混同しないこと。音読みは「キョウ・ケイ」（競争・競馬）。", "meaning": "互いに負けまいと張り合うこと。", "kr": "겨루다, 경쟁하다", "opts": ["あらそって＝争って。意味は近いが「争」の読み", "", "ただよって＝漂って。「競」の読みではない", "たたかって＝戦って・闘って。「競」の読みではない"], "ex": "子どもたちは<b>競って</b>手を挙げた。"},
"32101": {"point": "「痛い出費」は、生活に響くほど大きなお金の支払いのこと。結婚式のご祝儀などで家計からお金が出ていったという文脈なので、支出を表す「出費」が合う。", "meaning": "費用を出すこと。また、その費用。", "kr": "지출, 비용", "opts": ["浪費＝お金や時間を無駄に使うこと。祝儀は無駄遣いではないので合わない", "経費＝事業や仕事を行うのにかかる費用。会社などで使い、家計には合わない", "実費＝実際にかかった費用（「交通費は実費で支給」）。「痛い実費」とは言わない", ""], "ex": "車の修理代が十万円もかかり、思わぬ<b>出費</b>になった。"},
"32102": {"point": "「煙たい」は、煙が目や喉にしみて苦しい様子。主語が「たばこの煙」なので「けむたかった」が合う。", "meaning": "煙が立ちこめて、息苦しく目にしみる様子。", "kr": "냅다, 매캐하다", "opts": ["まずしい＝貧しい。お金や物が少ない様子で、煙には使わない", "するどい＝鋭い。刃物の先がとがっている、感覚が優れている様子", "", "まぶしい＝光が強くて目を開けていられない様子。光について言い、煙には使わない"], "ex": "たき火の風下に立つと、<b>煙たくて</b>涙が出てきた。"},
"32103": {"point": "おぼれた子どもを危険を恐れずに助けた若者なので、恐れずに立ち向かう様子を表す「勇敢な」が合う。", "meaning": "危険や困難を恐れず、勇ましく立ち向かう様子。", "kr": "용감하다", "opts": ["愉快な＝楽しく面白い様子。人命救助の行為とは結びつかない", "膨大な＝量や規模が非常に大きい様子。人には使わない", "迅速な＝物事の処理が非常に速い様子。「迅速な若者」とは言わない", ""], "ex": "火事の現場で<b>勇敢な</b>消防士が住民を救い出した。"},
"32104": {"point": "「おのずから明らかになる」は、何もしなくても自然にはっきりする、という決まった言い方。真相が自然にわかる、という文脈なので「おのずから」。", "meaning": "自然に。ひとりでに。", "kr": "저절로, 자연히", "opts": ["", "いやいや＝気が進まないまま、しかたなく（「いやいや勉強する」）", "ぼつぼつ＝少しずつ物事を始める様子（「ぼつぼつ出かけよう」）", "ちやほや＝人をおだてて甘やかす様子（「ちやほやされる」）"], "ex": "努力を続けていれば、結果は<b>おのずから</b>ついてくるものだ。"},
"32105": {"point": "入学した新入生に対して、学校の仕組みや生活について説明する会が開かれる、という文脈なので「オリエンテーション」。「〜が開かれる」とも結びつく。", "meaning": "新しく入った人に、環境や仕事の内容などを説明し、慣れさせるための説明会。", "kr": "오리엔테이션", "opts": ["アンケート＝多くの人に同じ質問をして意見を集める調査。「開かれる」ものではない", "オートメーション＝機械による作業の自動化", "レポート＝報告書。学生が書いて出すもので、「開かれる」とは言わない", ""], "ex": "新入社員向けの<b>オリエンテーション</b>が本社の会議室で行われた。"},
"32106": {"point": "「虫がいい」は、自分の都合ばかり考えて、ずうずうしい様子を表す慣用句。人のノートで100点をとろうとするのは自分勝手な考えなので「むし」。", "meaning": "（「虫がいい」の形で）自分に都合のいいことばかり考えて、ずうずうしい様子。", "kr": "뻔뻔하다, 제멋대로다", "opts": ["ねこ＝「猫をかぶる」「猫の手も借りたい」などに使う。「ねこがいい」とは言わない", "うま＝「馬が合う」は気が合うこと。「うまがいい」とは言わない", "あじ＝「味がいい」は食べ物がおいしいことで、ずうずうしさの意味はない", ""], "ex": "何もしないで給料だけ上げてほしいなんて、<b>虫</b>がいい話だ。"},
"32107": {"point": "「核実験」は核兵器を爆発させて性能を調べる実験。影響が完全には予測できない実験、という文脈に合うのは「核」。", "meaning": "原子核。「核〜」で核兵器・核エネルギーに関わることを表す。", "kr": "핵", "opts": ["某＝名前をはっきり言わない語（「某会社」「某氏」）。「某実験」は不自然", "微＝ごく小さいこと（「微生物」「微調整」）。「微実験」とは言わない", "", "貴＝相手を敬う語（「貴社」「貴校」）。実験には付かない"], "ex": "その国の<b>核</b>実験に対して、各国が強く抗議した。"},
"32108": {"point": "「使い果たす」は、残らず全部使ってしまうこと。「貯金をすべて」とあるので、「〜果たす（すっかり〜する）」の「はたして」が合う。", "meaning": "（動詞の連用形について）すっかり〜してしまう。「使い果たす」で全部使い切ること。", "kr": "다 써 버리다, 탕진하다", "opts": ["", "使いあげる＝このような複合動詞はない", "使いぬく＝最後まで使い通すこと。「貯金を使いぬく」とは言わない", "使いとおす＝一つのものを最後まで使い続けること。貯金には合わない"], "ex": "旅行先で財布の中のお金を<b>使い果たして</b>しまった。"},
"32109": {"point": "人間が動物と違うのは、新しい文化を作り出すこと。「文化を創造する」が自然な組み合わせ。", "meaning": "それまでなかったものを新しく作り出すこと。", "kr": "창조", "opts": ["", "想像＝実際にないことを心の中に思い浮かべること。「文化を想像する」は不自然", "構想＝計画や考えの組み立てを練ること（「新事業を構想する」）", "創作＝小説・絵などの芸術作品を作ること。文化全体には使わない"], "ex": "芸術家は常に新しい価値を<b>創造</b>しようとしている。"},
"32110": {"point": "国が独立したことを国の内外に正式に発表するのは「独立を宣言する」。「独立宣言」という語もある。", "meaning": "考えや方針を外に向かって公式に表明すること。", "kr": "선언", "opts": ["明言＝はっきり言うこと。個人の発言に使い、「独立を明言する」は不自然", "断言＝自信をもってきっぱり言い切ること。正式な表明の意味はない", "公言＝人前で堂々と言うこと（「優勝すると公言する」）。国の正式な発表には使わない", ""], "ex": "議長が開会を<b>宣言</b>して、会議が始まった。"},
"32111": {"point": "暗がりから思いがけなく急に人が出てきた、という場面。「不意に」は予期しないときに突然、という意味で「現れる」と結びつく。", "meaning": "思いがけないときに突然起こる様子。", "kr": "갑자기, 불시에", "opts": ["意外＝思っていたことと違う様子。「意外に人が現れた」は不自然", "案外＝予想と違って（「テストは案外易しかった」）。突然の意味はない", "", "微妙＝簡単に言い表せない細かな様子。出現の様子には使わない"], "ex": "<b>不意に</b>名前を呼ばれて、思わず振り返った。"},
"32112": {"point": "不況で会社が人員を減らした、という文脈。人数や費用を減らすことは「削減」で、「人員削減」はよく使う組み合わせ。", "meaning": "数量・金額などを削って減らすこと。", "kr": "삭감, 감축", "opts": ["削除＝文章やデータの一部を削って取り除くこと。人員には使わない", "", "軽減＝負担や苦痛を軽くすること（「負担を軽減する」）。人員には使わない", "加減＝程度を調節すること（「力を加減する」）"], "ex": "経費<b>削減</b>のため、会議室の照明をこまめに消すことになった。"},
"32113": {"point": "「突き詰める」は、物事をとことんまで追究すること。スキルを磨いて最後まで深めていく、という文脈なので「つめて」。", "meaning": "物事を最後のところまで深く考え、追究すること。", "kr": "끝까지 파고들다, 철저히 추구하다", "opts": ["突き捨てる＝このような複合動詞はない", "突き合わせる＝二つのものを比べて確かめること（「書類を突き合わせる」）", "", "突き果たす＝このような複合動詞はない"], "ex": "問題の原因を<b>突き詰めて</b>考えると、管理体制の甘さに行き着く。"},
"32114": {"point": "「理想郷」は、理想として思い描く、すばらしい世界のこと。「理想郷を描く」で、理想の世界を思い描くという意味になる。", "meaning": "（「〜郷」の形で）その性質を持つ土地・場所。「理想郷」で理想的な世界。", "kr": "-향(이상향), 고장", "opts": ["帯＝ある範囲の地域・時間（「地震帯」「時間帯」）。「理想帯」とは言わない", "", "孔＝あな（「鼻孔」）。「理想孔」とは言わない", "臭＝におい、また「〜くさい」様子（「役人臭」）。「理想臭」とは言わない"], "ex": "その小さな島は、争いのない<b>理想郷</b>として知られていた。"},
"32115": {"point": "クラブがどのような仕組みで運営されているか尋ねる文。組織や制度の仕組みを表す「システム」が合う。", "meaning": "全体をまとめる仕組み。制度・組織。", "kr": "시스템, 체계, 구조", "opts": ["オートマチック＝自動式。機械の仕組みに使い、クラブの運営には合わない", "", "レギュラー＝正選手、また正規・定期のもの。「どういうレギュラー」は不自然", "サイクル＝周期、また自転車。仕組みの意味はない"], "ex": "この店では、ポイントがたまると割引になる<b>システム</b>を導入している。"},
"32116": {"point": "「肩を持つ」は、対立している一方の味方をすること、ひいきすること。「君のことばかり〜をもつ」なので「かた」。", "meaning": "（「肩を持つ」の形で）一方の味方をする。ひいきする。", "kr": "편을 들다", "opts": ["あたま＝「頭を持つ」という慣用句はない（「頭を抱える」「頭が固い」など）", "こし＝「腰を持つ」という慣用句はない（「腰が低い」「腰を据える」など）", "", "あし＝「足を持つ」という慣用句はない（「足を引っ張る」など）"], "ex": "母はいつも弟の<b>肩</b>を持つので、私は不満だ。"},
"32117": {"point": "「活発に活動する」は、元気よく盛んに動く様子。若いピアニストが盛んに演奏活動をしているという文脈なので「活発」。", "meaning": "元気がよく、勢いのある様子。動きが盛んな様子。", "kr": "활발하다", "opts": ["", "自在＝思いのままにできる様子（「自由自在」）。活動の盛んさは表さない", "不調＝調子が悪い様子。「不調に演奏活動をする」とは言わない", "敏感＝わずかな刺激にもすぐ反応する様子。活動の様子には使わない"], "ex": "この地域では住民によるボランティア活動が<b>活発</b>に行われている。"},
"32118": {"point": "「ちょくちょく」は、たびたび、よく、という意味の副詞。「訪ねる」という繰り返しの行動と結びつく。", "meaning": "何度も繰り返す様子。たびたび。", "kr": "자주, 종종", "opts": ["つくづく＝心の底から深く感じる様子（「つくづく嫌になる」）", "", "じっくり＝落ち着いて時間をかける様子（「じっくり考える」）", "なるたけ＝できるだけ（「なるたけ早く来て」）。頻度は表さない"], "ex": "近所に住む姉が、<b>ちょくちょく</b>野菜を持ってきてくれる。"},
"32119": {"point": "「しぶとく」は、簡単にあきらめず、ねばり強い様子。自分の意見にいつまでもこだわって譲らない様子に合う。", "meaning": "ねばり強くて、簡単にはあきらめたりくじけたりしない様子。", "kr": "끈질기다, 끈덕지다", "opts": ["そっけなく＝相手への思いやりがなく冷たい様子（「そっけなく断る」）", "", "あっけなく＝予想に反して簡単に終わってしまう様子（「あっけなく負けた」）", "ややこしく＝複雑でわかりにくい様子。こだわり方には使わない"], "ex": "最下位のチームが最後まで<b>しぶとく</b>戦い、引き分けに持ち込んだ。"},
"32120": {"point": "「微妙な違い」は、はっきりとは言えないほど細かい違いのこと。二人の考えの違いの様子を表せるのは「微妙」だけ。", "meaning": "細かい点に複雑な意味や味わいがあり、簡単には言い表せない様子。", "kr": "미묘하다", "opts": ["", "微量＝ごくわずかな量。名詞で、「微量な違い」とは言わない", "微力＝力が弱いこと。自分の力を謙遜して言う（「微力ながら」）。違いの様子には使わない", "特徴＝他と比べて目立つ点。名詞で、「特徴な違い」とは言わない"], "ex": "この二つの色には<b>微妙な</b>差があって、並べないとわからない。"},
"32121": {"point": "病院で入院患者に会うことができる時間は「面会時間」。病院の決まりとして使われる語。", "meaning": "訪ねてきた人と会うこと。", "kr": "면회", "opts": ["対面＝顔を合わせて向き合うこと（「初対面」）。「対面時間」は病院で使わない", "面接＝試験などのために直接会って話すこと", "会見＝公式に人と会うこと（「記者会見」）", ""], "ex": "祖父が入院している病院へ<b>面会</b>に行った。"},
"32122": {"point": "高い授業料を払うために家計にかかる重みを表すのは「負担」。「家計の負担が大きい」はよく使う言い方。", "meaning": "仕事・責任・費用などを引き受けること。また、その重み。", "kr": "부담", "opts": ["", "責任＝引き受けなければならない務め。「家計の責任」は意味が違う", "役割＝割り当てられた役目。費用の重さには使わない", "分担＝仕事などを分けて受け持つこと（「家事を分担する」）"], "ex": "医療費の自己<b>負担</b>が増えると、生活は苦しくなる。"},
"32123": {"point": "初めての演説なのに口調がよどみなかった、という文脈。話し方がつかえずにすらすら進む様子は「なめらかな口調」。", "meaning": "表面がすべすべしている様子。また、話などがよどみなく進む様子。", "kr": "매끄럽다, 유창하다", "opts": ["のどかな＝穏やかでのんびりしている様子（「のどかな田舎」）", "すこやかな＝体や心が健康な様子（「すこやかに育つ」）", "", "すみやかな＝行動がすばやい様子（「すみやかに退場する」）"], "ex": "彼女は英語を<b>なめらか</b>に話し、聞き手を驚かせた。"},
"32124": {"point": "単語をばらばらに覚えるのと対比して、文章を全部ひとまとめに覚える、という文脈なので「まるごと」。", "meaning": "分けずに、そのまま全部。", "kr": "통째로", "opts": ["もっぱら＝ほかのことはせず、そればかり（「休日はもっぱら寝ている」）。「ばらばらに」と対比して全部まとめて覚える意味にならない", "ひたすら＝ほかのことを考えず、一つのことに集中する様子。熱心さを表すだけで、「ばらばらに」との対比にならない", "", "なおさら＝なお一層、ますます。前の内容を受けて程度が上がることを表し、覚え方は表さない"], "ex": "リンゴを皮ごと<b>まるごと</b>かじった。"},
"32125": {"point": "インターネットは情報を伝える手段なので、新聞・テレビなどと同じ「メディア」。", "meaning": "情報を伝える手段。新聞・テレビ・インターネットなど。", "kr": "미디어, 매체", "opts": ["テレックス＝文字を送受信する昔の通信装置。新しいものではない", "トランジスタ＝電子部品の一つ。社会を変える情報手段ではない", "ワット＝電力の単位", ""], "ex": "その事件は多くの<b>メディア</b>で大きく取り上げられた。"},
"32126": {"point": "「ひどい目にあう」は、つらい経験やいやな経験をすること。急いでいたのに渋滞で1時間もかかった、という文脈に合う慣用句。", "meaning": "（「〜目にあう」の形で）そのような経験をすること。「ひどい目にあう」でつらい思いをすること。", "kr": "(혼)나다, 봉변을 당하다", "opts": ["", "あし＝「足」を使った慣用句に「ひどい足にあう」はない", "て＝「ひどい手にあう」とは言わない（「手を焼く」などはある）", "みみ＝「耳」を使った慣用句に「ひどい耳にあう」はない（「耳が痛い」などはある）"], "ex": "旅行先で財布を盗まれて、ひどい<b>目</b>にあった。"},
"32127": {"point": "「文字盤」は、時計で数字や目盛りが書かれた平らな面のこと。腕時計のデザインの話なので「盤」。", "meaning": "（「〜盤」の形で）平らな台・板状のもの。「文字盤」は時計の数字が書かれた面。", "kr": "-판(문자판)", "opts": ["欄＝紙面の区切られた部分（「記入欄」「投書欄」）。時計には使わない", "簿＝書き記す帳面（「名簿」「家計簿」）", "碑＝石に文字を刻んで立てたもの（「記念碑」）", ""], "ex": "暗い所でも見えるように、<b>文字盤</b>が光る時計を買った。"},
"32128": {"point": "「作り上げる」は、苦労して完全なものに作り終えること。父親が苦労して作った会社、という文脈なので「あげた」。", "meaning": "（動詞の連用形について）すっかり〜し終える。「作り上げる」で完成させること。", "kr": "만들어 내다, 이룩하다", "opts": ["作り入れる＝このような複合動詞はない", "", "作りかける＝作り始めて途中であること。苦労して完成させた意味にならない", "作りそびれる＝作る機会を逃すこと。会社をつぶす話とつながらない"], "ex": "チーム全員で一つの作品を<b>作り上げた</b>。"},
"32129": {"point": "高いがけから車ごと転げ落ちる、という場面。高い所から落ちることは「転落」。", "meaning": "高い所から転がり落ちること。また、地位や状態が急に悪くなること。", "kr": "추락, 전락", "opts": ["堕落＝生活や考えが悪い方へ落ちること。物理的に落ちることには使わない", "", "没落＝栄えていたものが衰えること（「名家が没落する」）", "倒産＝会社がつぶれること"], "ex": "足をすべらせて、階段から<b>転落</b>した。"},
"32130": {"point": "親しくもないのに親しいかのような態度をとる、という文脈なので「なれなれしい」。「なれなれしい口をきく」で、遠慮のない話し方をすること。", "meaning": "親しくないのに、ひどく親しそうにふるまう様子。", "kr": "버릇없이 친한 척하다, 허물없이 굴다", "opts": ["でかい＝大きい（くだけた言い方）。「でかい口をきく」は偉そうに言うことで、「親しくもないのに」と合わない", "", "いやらしい＝不快な感じ、下品な様子。親しさとは関係がない", "このましい＝好ましい。良い感じで、注意する理由にならない"], "ex": "初対面なのに<b>なれなれしく</b>肩をたたかれて、不快だった。"},
"32131": {"point": "「人生は〜だった」と、人生の状態を表すのは「孤独」。ひとりぼっちで寂しい人生、という意味になる。", "meaning": "仲間や身寄りがなく、ひとりぼっちで寂しいこと。", "kr": "고독", "opts": ["", "孤立＝周りから離れて一つだけになること（「孤立した村」）。「孤立する」と動詞で使い、人生の様子には合わない", "独立＝他から離れて自分の力でやっていくこと。寂しさの意味はない", "自立＝人に頼らず、自分の力でやっていくこと"], "ex": "都会で一人暮らしをしていると、<b>孤独</b>を感じることがある。"},
"32132": {"point": "「ミチオ」と「ミチヨ」は似ていて区別しにくい。似ていて間違えやすい様子は「まぎらわしい」。", "meaning": "よく似ていて、区別がつきにくい様子。", "kr": "헷갈리기 쉽다, 혼동하기 쉽다", "opts": ["ひとしい＝等しい。同じである様子。「困る」理由にならない", "ふさわしい＝似合っている、適している様子", "", "のぞましい＝望ましい。そうあってほしい様子"], "ex": "この二つの薬は名前が<b>紛らわしい</b>ので、取り違えないように注意しよう。"},
"32133": {"point": "「しとやかに」は、言葉づかいや動作が上品で落ち着いている様子。おじぎの仕方に使える。", "meaning": "動作や話し方が上品で落ち着いている様子。", "kr": "얌전하다, 정숙하다", "opts": ["さわやかに＝気分がすっきりして気持ちがいい様子（「さわやかな朝」）。動作の上品さではない", "こまやかに＝心配りが細かく行き届いている様子（「こまやかな配慮」）", "きよらかに＝汚れがなく美しい様子（「清らかな水」）", ""], "ex": "着物姿の女性が<b>しとやかに</b>お茶をいれてくれた。"},
"32134": {"point": "「AのみならずひいてはB」は、Aだけでなく、それが広がって最終的にBにまで及ぶ、という言い方。業界→国家へと範囲が広がっているので「ひいては」。", "meaning": "それが原因・きっかけとなって、さらに進んで。", "kr": "나아가서는", "opts": ["のきなみ＝どれもこれもみな（「のきなみ値上がりした」）", "", "ひたすら＝一つのことに集中する様子", "いまさら＝今になって（「いまさら謝っても遅い」）"], "ex": "一人一人の努力が、<b>ひいては</b>社会全体を変えることにつながる。"},
"32135": {"point": "雨で試合が途中で止まった、という文脈。続いていたものが途中で一時止まるのは「中断」。「〜が中断する」と自動詞でも使える。", "meaning": "続いていた物事が途中で一時止まること。また、止めること。", "kr": "중단", "opts": ["決断＝はっきりと心を決めること", "", "休止＝運転や活動などをしばらく休むこと（「運転休止」「活動休止」）。進行中の試合が雨で途中で止まる場合は「中断」を使う", "休憩＝疲れを取るために休むこと。人がするもので、試合が主語にならない"], "ex": "停電で工場の作業が一時<b>中断</b>した。"},
"32136": {"point": "「一括して提出する」は、いくつもの書類を一つにまとめて出すこと。", "meaning": "いくつかのものを一つにまとめること。", "kr": "일괄", "opts": ["一連＝ひと続きの関係にあるもの（「一連の事件」）", "一帯＝その辺り全体（「この地域一帯」）", "一同＝そこにいる人全員（「社員一同」）", ""], "ex": "代金は分割ではなく<b>一括</b>で支払った。"},
"32137": {"point": "SFは小説の種類の一つなので、分野・種類を表す「ジャンル」。", "meaning": "芸術作品などの種類・分野。", "kr": "장르", "opts": ["デザイン＝形・色などの意匠。小説の種類の意味はない", "モデル＝手本、型、また作品の題材になる人。小説の種類・分野の意味はない", "", "デッサン＝絵の下書き、素描。小説には使わない"], "ex": "彼はクラシックからロックまで、幅広い<b>ジャンル</b>の音楽を聞く。"},
"32138": {"point": "悪いことをしていないのに疑われて怒った、という文脈。「腹が立つ」は怒りを感じることを表す慣用句。", "meaning": "（「腹が立つ」の形で）怒る。しゃくにさわる。", "kr": "화가 나다", "opts": ["はな＝「鼻が高い」は得意な様子。「鼻が立つ」とは言わない", "みみ＝「耳が立つ」とは言わない（「耳を立てる」は聞こうとすること）", "くち＝「口が立つ」は話がうまいこと。怒りの意味はない", ""], "ex": "約束を破られて、さすがに<b>腹</b>が立った。"},
"32139": {"point": "アレルギー性の病気の名前なので「花粉症」。病名に付けて症状・病気を表す「〜症」。", "meaning": "（「〜症」の形で）病気・症状。", "kr": "-증(화분증), 증상", "opts": ["病＝「〜病」も病名を作るが（「心臓病」）、花粉には付かない", "炎＝炎症を表す（「胃炎」「皮膚炎」）。「花粉炎」とは言わない", "傷＝きず（「切り傷」「外傷」）", ""], "ex": "春になると<b>花粉症</b>で目がかゆくなる。"},
"32140": {"point": "「疲れ果てる」は、すっかり疲れてしまうこと。「心身ともに」とあるので、程度が極まる「〜果てる」が合う。", "meaning": "（動詞の連用形について）すっかり〜する。「疲れ果てる」でくたくたに疲れること。", "kr": "녹초가 되다, 몹시 지치다", "opts": ["", "疲れつける＝このような複合動詞はない", "疲れあわせる＝このような複合動詞はない", "疲れつくす＝一般には使わない。「〜尽くす」は「食べ尽くす」のように他動詞に付く"], "ex": "一日中歩き回って、<b>疲れ果てて</b>しまった。"},
"32141": {"point": "財産目当ての結婚という、品性が低くて情けない行為を非難する文。「あさましい」は、心がいやしく、見ていて情けない様子。", "meaning": "心がいやしく、見苦しくて情けない様子。", "kr": "치사하다, 비열하다, 한심하다", "opts": ["", "とぼしい＝乏しい。量が少ない様子", "いやしい＝卑しい。身分や品性が低い様子。近い意味だが、行為に対するあきれた気持ちを表すには「あさましい」が自然", "たくましい＝体や精神が強い様子。非難の意味はない"], "ex": "人の不幸を利用してもうけようとするなんて、<b>あさましい</b>考えだ。"},
"32142": {"point": "だれからも好かれる人の性格として、楽しくて面白い様子の「ゆかいな」が合う。", "meaning": "楽しくて、面白い様子。", "kr": "유쾌하다", "opts": ["", "さかんな＝勢いがよい様子（「スポーツがさかんな町」）。人の性格には使わない", "あわれな＝かわいそうな様子。好かれる理由にならない", "びみょうな＝はっきり言えない複雑な様子。人の性格には使わない"], "ex": "<b>愉快な</b>仲間と一緒に、楽しい旅行をした。"},
"32143": {"point": "服のサイズが自分の体にちょうど合う様子は「きっちりと」。すき間やずれがなく、ぴったりの様子。", "meaning": "すき間やずれがなく、ぴったりと合う様子。", "kr": "꼭, 딱 맞게", "opts": ["", "ほっと＝安心する様子（「ほっとする」）", "がっちりと＝体格ががっしりしている、また固くしっかりした様子", "げっそりと＝急にやせる、またはひどくがっかりする様子"], "ex": "ふたが<b>きっちりと</b>閉まっているか確かめた。"},
"32144": {"point": "「猫の額」は、土地などが非常に狭いことのたとえ。池も作れない狭い庭なので「ねこのひたい」。", "meaning": "（「猫の額ほど」の形で）土地や場所が非常に狭いことのたとえ。", "kr": "손바닥만 함(아주 좁음)", "opts": ["", "すずめのなみだ＝ごくわずかな量のたとえ。金額などに使い、広さには使わない", "水のあわ＝努力が無駄になること（「努力が水の泡になる」）", "上の空＝他のことに気を取られて注意が向かない様子"], "ex": "<b>猫の額</b>ほどの畑で、家族が食べる分の野菜を育てている。"},
"32145": {"point": "ひどいことをしてはいけないと感じる心は「良心」。「良心があれば〜できないはずだ」は自然な言い方。", "meaning": "善悪を判断し、正しく行動しようとする心。", "kr": "양심", "opts": ["", "誠心＝まごころ（「誠心誠意」）。単独ではあまり使わない", "感心＝りっぱだと思って心を動かされること", "肝心＝最も大切なこと（「肝心な点」）"], "ex": "うそをつくたびに、<b>良心</b>が痛んだ。"},
"32146": {"point": "長く続いた政権がだめになって終わる、という文脈。組織や体制が崩れてなくなることは「崩壊」。", "meaning": "建物や組織・体制などが崩れて壊れること。", "kr": "붕괴", "opts": ["破棄＝書類を破り捨てる、また契約などを一方的に取り消すこと（「契約を破棄する」）", "放棄＝権利や責任などを捨てて使わないこと（「権利を放棄する」）", "廃棄＝不要な物を捨てること（「廃棄処分」）", ""], "ex": "地震でビルが<b>崩壊</b>し、多くの人が閉じ込められた。"},
"32147": {"point": "旅行に行きたいという頼みを父親が聞き入れて許すこと。人の頼みや申し出を引き受けることは「承諾」で、「承諾を得る」とよく使う。", "meaning": "相手の頼みや申し出を聞き入れ、引き受けること。", "kr": "승낙", "opts": ["承認＝正式なものとして認めること。国・会社・会議など公的な場面で使うことが多い", "承合＝このような語は一般に使わない", "", "承知＝事情を知っていること、また頼みを聞き入れること。「承知を得る」とは言わない"], "ex": "写真を載せる前に、本人の<b>承諾</b>を得なければならない。"},
"32148": {"point": "経営者の行動が会社の評判を下げてしまう、という文脈なので「イメージダウン」。「〜になる」とも結びつく。", "meaning": "評判やイメージが悪くなること。", "kr": "이미지 실추, 이미지 하락", "opts": ["ブーム＝一時的な流行。会社に悪い影響を与える意味はない", "メッセージ＝伝えたい内容、伝言", "ロマンチック＝甘く夢のような様子。ナ形容詞で、「〜になるような行動」と合わない", ""], "ex": "選手の不祥事は、チームにとって大きな<b>イメージダウン</b>になった。"},
"32149": {"point": "「未決囚」は、裁判の判決がまだ出ていない、捕らえられている人のこと。「囚」は捕らえられた人を表す。", "meaning": "（「〜囚」の形で）捕らえられて牢に入れられている人。", "kr": "-수(죄수), 수감자", "opts": ["士＝資格を持つ専門家（「弁護士」「会計士」）。「未決士」とは言わない", "", "隊＝まとまった集団（「探検隊」）", "家＝その道の専門の人（「作家」「専門家」）"], "ex": "その<b>死刑囚</b>は、刑務所の中で手記を書き続けた。"},
"32150": {"point": "「泣き明かす」は、一晩中泣いて朝を迎えること。「一晩じゅう」とあるので、夜を過ごして朝になる意味の「〜明かす」。", "meaning": "（動詞の連用形について）夜通し〜して朝を迎える。「泣き明かす」で一晩中泣くこと。", "kr": "밤새 울다", "opts": ["泣き果たす＝このような複合動詞はない", "", "泣き尽くす＝ふつうは使わない。「一晩じゅう」と結びつくのは「明かす」", "泣き回す＝このような複合動詞はない"], "ex": "友人と朝まで語り<b>明かした</b>。"},
"32151": {"point": "見ようと思っていたのに忙しくて行けなかった、という文脈。「〜そびれる」は、する機会を逃してしまうこと。", "meaning": "（動詞の連用形について）〜する機会を逃す。", "kr": "~할 기회를 놓치다, ~하지 못하다", "opts": ["行きかける＝行こうとし始めること。行けなかった意味にならない", "行きつける＝何度も行って慣れていること（「行きつけの店」）", "行きつめる＝「行き詰まる」なら進めなくなること。「行きつめる」とは言わない", ""], "ex": "話が盛り上がって、お礼を言い<b>そびれて</b>しまった。"},
"32152": {"point": "「会計士」は、会計の専門資格を持つ人。国家試験で資格を取る職業に付く「〜士」が合う。", "meaning": "（「〜士」の形で）資格や専門的な技能を持つ人。", "kr": "-사(회계사)", "opts": ["陣＝集団・顔ぶれ（「報道陣」「首脳陣」）", "句＝言葉のひと区切り（「文句」「俳句」）", "人＝「〜人」は人を表すが、「会計人」は資格名ではない", ""], "ex": "兄は<b>弁護士</b>を目指して、毎日勉強している。"},
"32153": {"point": "隠しごとをしない性格なので、隠さずありのままを見せる「オープンな」が合う。", "meaning": "隠しだてがなく、開放的な様子。", "kr": "개방적이다, 솔직하다", "opts": ["ドライな＝感情に流されず割り切った様子。隠しごとをしない理由にならない", "ルーズな＝時間やお金にだらしない様子", "ユニークな＝独特な様子", ""], "ex": "彼女は何でも<b>オープンに</b>話してくれるので、付き合いやすい。"},
"32154": {"point": "人が入ってきた途端にみんなが話をすばやくやめた、という場面。動作がすばやい様子は「さっと」。", "meaning": "動作がすばやい様子。", "kr": "재빨리, 휙", "opts": ["ぐっと＝力を入れる、また程度が大きく変わる様子（「ぐっとこらえる」）", "ひょっと＝思いがけず。「ひょっとすると」の形で使う", "ちらっと＝ほんの一瞬見えたり見たりする様子", ""], "ex": "先生が入ってくると、生徒たちは<b>さっと</b>席に着いた。"},
"32155": {"point": "計画を実現させた原因は山田さんの強い気持ち。「〜の熱意で」と名詞で使えるのは「熱意」。", "meaning": "物事に対する熱心な気持ち。", "kr": "열의, 열정", "opts": ["懸念＝気にかかって心配すること。実現の理由にならない", "", "懸命＝力の限りがんばる様子。ナ形容詞で「懸命に」の形で使い、「〜の懸命で」とは言わない", "熱心＝一つのことに打ち込む様子。ナ形容詞で、「山田さんの熱心で」とは言わない"], "ex": "彼の<b>熱意</b>に負けて、とうとう協力することにした。"},
"32156": {"point": "「水を差す」は、うまくいっている物事や盛り上がった雰囲気をじゃますること。「〜ようなことを言うな」と結びつく慣用句。", "meaning": "（「水を差す」の形で）うまくいっている関係や雰囲気をじゃまする。", "kr": "찬물을 끼얹다", "opts": ["ながす＝「水に流す」は過去のことをなかったことにする意味。「水をながす」は慣用句ではない", "いれる＝「水を入れる」は文字どおりの意味しかない", "", "のむ＝「水を飲む」は文字どおりの意味しかない"], "ex": "せっかく盛り上がっているのに、<b>水を差す</b>ようなことを言わないでほしい。"},
"32157": {"point": "目標をなしとげることは「達成」。「目標を達成する」は決まった組み合わせ。", "meaning": "目標などをなしとげること。", "kr": "달성", "opts": ["到達＝ある地点や段階に行き着くこと（「頂上に到達する」）。「目標を到達する」とは言わない", "成功＝物事がうまくいくこと。「目標を成功する」とは言わない", "", "実行＝実際に行うこと。目標には「達成」を使う"], "ex": "今年の売り上げ目標を<b>達成</b>することができた。"},
"32158": {"point": "死ぬのではないかという悪いことが起こりそうな予感なので「不吉な」。「不吉な予感」はよく使う組み合わせ。", "meaning": "縁起が悪く、悪いことが起こりそうな様子。", "kr": "불길하다", "opts": ["不明な＝はっきりわからない様子", "不当な＝道理に合わない様子（「不当な扱い」）", "", "不審な＝疑わしい様子（「不審な人物」）"], "ex": "黒い猫が前を横切り、なんだか<b>不吉な</b>気がした。"},
"32159": {"point": "成績がはっきりわかるほど大きく上がった、という文脈。変化の程度が目立って大きい様子は「いちじるしく」。", "meaning": "程度がはっきりわかるほど目立つ様子。", "kr": "현저하게", "opts": ["ひさしく＝長い間（「ひさしく会っていない」）", "", "とうとく＝尊く。価値が高い様子で、変化の程度は表さない", "さびしく＝寂しく。成績の向上には合わない"], "ex": "新しい薬のおかげで、症状が<b>著しく</b>改善した。"},
"32160": {"point": "会費で費用のすべてがまかなわれる、という文脈。「一切の〜」で「すべての〜」を表す。", "meaning": "全部。すべて。", "kr": "일체, 모든", "opts": ["一層＝さらに、ますます（「一層努力する」）", "一様＝みな同じ様子（「一様に驚いた」）", "一律＝すべて同じ基準で扱うこと（「一律千円」）", ""], "ex": "引っ越しにかかる<b>一切の</b>費用は会社が負担する。"},
"32161": {"point": "「備え付ける」は、必要な物をその場所に置いておくこと。申し込み用紙がカウンターに置いてある、という意味なので「つけて」。", "meaning": "（「備え付ける」の形で）いつでも使えるように、その場所に置いておく。", "kr": "비치하다", "opts": ["そなえあわせる＝このような複合動詞はない（「兼ね備える」はある）", "そなえつくす＝このような複合動詞はない", "", "そなえこむ＝このような複合動詞はない"], "ex": "各部屋に消火器が<b>備え付けて</b>ある。"},
"32162": {"point": "時間が過ぎていくことは「経過」。「〜年が経過する」は決まった言い方。", "meaning": "時間が過ぎていくこと。また、物事の移り変わりの様子。", "kr": "경과", "opts": ["", "経緯＝物事のいきさつ、事情（「事件の経緯」）", "過程＝物事が進んでいく途中の段階（「成長の過程」）", "課程＝学校で学ぶべき内容の範囲（「博士課程」）"], "ex": "手術から一週間が<b>経過</b>し、ようやく歩けるようになった。"},
"32163": {"point": "社会の中では欲求をある程度おさえなければならない、という文脈。欲求や気持ちを無理におさえつけることは「抑圧」。", "meaning": "行動や欲求などを無理におさえつけること。", "kr": "억압", "opts": ["制定＝法律や規則を作って定めること", "", "圧迫＝強くおさえつけること。財政や胸などに使い（「財政を圧迫する」）、欲求には「抑圧」", "迫害＝弱い立場の人を苦しめること（「宗教的迫害」）"], "ex": "自由な発言が<b>抑圧</b>される社会では、創造的な考えは生まれにくい。"},
"32164": {"point": "探検のために組まれた集団は「探検隊」。集団を表す「〜隊」が合う。", "meaning": "（「〜隊」の形で）ある目的のために組織された集団。", "kr": "-대(탐험대)", "opts": ["弾＝たま（「弾丸」）、また回数（「第二弾」）", "", "師＝先生、またその技術の専門家（「美容師」）", "戦＝たたかい（「決勝戦」）"], "ex": "<b>救助隊</b>が山で遭難した人を見つけ出した。"},
"32165": {"point": "「お目が高い」は、ものを見る目があって、良い物を見分ける力があること。器をほめる人の鑑識眼を評価する言い方。", "meaning": "（「お目が高い」の形で）物の価値を見分ける力が優れている。", "kr": "보는 눈이 높다, 안목이 있다", "opts": ["おおきい＝「目が大きい」は文字どおりの意味で、鑑識眼の意味はない", "", "ひくい＝「目が低い」とは言わない", "ちいさい＝「目が小さい」は文字どおりの意味"], "ex": "それを選ぶとは、お客様はお<b>目が高い</b>ですね。"},
"32166": {"point": "外国映画の題名を訳すのはむずかしい、という文脈なので「タイトル」。", "meaning": "題名。表題。", "kr": "타이틀, 제목", "opts": ["タイピスト＝タイプライターを打つ職業の人", "", "タイマー＝時間を計る装置", "タイミング＝ちょうどよい時機"], "ex": "その映画は、日本では原作と違う<b>タイトル</b>で公開された。"},
"32167": {"point": "叱られると、反抗したい気持ちがさらに強くなる、という文脈。程度がもっと増すことを表すのは「なおさら」。", "meaning": "前よりも一層。ますます。", "kr": "더욱더, 한층", "opts": ["てんで＝（後ろに否定）まったく（「てんで話にならない」）", "なぜなら＝前の内容の理由を述べる接続詞", "", "さほど＝（後ろに否定）それほど（「さほど難しくない」）"], "ex": "だめだと言われると、<b>なおさら</b>やってみたくなる。"},
"32168": {"point": "倒産がうわさされるほど大量の赤字なので、数量が非常に大きい様子の「膨大な」。", "meaning": "数や量が非常に多く、大きい様子。", "kr": "방대하다, 막대하다", "opts": ["大胆な＝度胸があり、思い切ったことをする様子", "", "大体な＝このような言い方はしない（「大体」は副詞・名詞）", "盛大な＝集まりなどが大規模でにぎやかな様子（「盛大なパーティー」）"], "ex": "この研究には<b>膨大な</b>時間と費用がかかった。"},
"32169": {"point": "コンピューターの進歩が目を見張るほどすばらしい、という文脈。「めざましい進歩」はよく使う組み合わせ。", "meaning": "目が覚めるほどすばらしい様子。", "kr": "눈부시다, 놀랍다", "opts": ["こころよい＝気持ちがよい様子（「こころよい風」）", "あわただしい＝落ち着かず忙しい様子", "はかない＝もろくて長く続かない様子", ""], "ex": "その選手は今シーズン、<b>めざましい</b>活躍を見せた。"},
"32170": {"point": "山では一人だけで行動すると危険なので注意する、という文脈。「単独行動」は一人だけで行動すること。", "meaning": "ただ一人。また、他から離れて一つだけであること。", "kr": "단독", "opts": ["唯一＝ただ一つだけ（「唯一の方法」）。「唯一行動」とは言わない", "単一＝ただ一つで、他のものがまじらないこと（「単一民族」）。人の行動には使わず、「単一行動」とは言わない", "", "孤独＝ひとりぼっちで寂しいこと。行動の仕方には使わない"], "ex": "犯人は<b>単独</b>で犯行に及んだとみられている。"},
"32171": {"point": "新聞などで読者の投書を載せる区切られた部分は「投書欄」。紙面の区切りを表す「〜欄」。", "meaning": "（「〜欄」の形で）新聞・書類などで区切られた部分。", "kr": "-란(투고란)", "opts": ["源＝みなもと（「資源」「電源」）", "制＝制度（「会員制」）。紙面の部分を表さない", "", "帯＝ある範囲（「時間帯」「地震帯」）"], "ex": "名前と住所を所定の<b>欄</b>に記入してください。"},
"32172": {"point": "共働きで忙しく、検診を受ける機会を逃してしまう、という文脈。「〜そこねる」は、しようとしてしそこなう、機会を逃すこと。", "meaning": "（動詞の連用形について）〜しようとしてうまくできない。〜する機会を逃す。", "kr": "~할 기회를 놓치다, ~하지 못하다", "opts": ["受けこなす＝このような複合動詞はない（「こなす」は「使いこなす」など）", "受けつめる＝このような複合動詞はない", "受けあかす＝このような複合動詞はない", ""], "ex": "寝坊して、いつものバスに乗り<b>そこねた</b>。"},
"32173": {"point": "「耳を傾ける」は、注意して熱心に聞くこと。「じっと」と結びついて、相手の話を熱心に聞く様子を表す。", "meaning": "（「耳を傾ける」の形で）注意して熱心に聞く。", "kr": "귀를 기울이다", "opts": ["だす＝「耳をだす」は文字どおりの意味しかない", "むける＝「顔を向ける」などは言うが、「耳を向ける」は慣用句ではない", "いれる＝「耳に入れる」は人に知らせることで、「耳をいれる」とは言わない", ""], "ex": "社長は社員の意見にも<b>耳を傾ける</b>人だ。"},
"32174": {"point": "ある地位を争う相手なので、競争相手を表す「ライバル」。", "meaning": "競争相手。好敵手。", "kr": "라이벌, 경쟁자", "opts": ["", "チームワーク＝チームの協力関係", "ファイト＝闘志、戦う気力", "ポイント＝点数、また要点"], "ex": "二人は高校時代からの<b>ライバル</b>で、いつも成績を競っていた。"},
"32175": {"point": "「一切〜ない」は、全く〜ない、という強い否定。後ろの「責任を持ちません」と結びつくのは「一切」。", "meaning": "（後に打ち消しを伴って）全く。少しも。", "kr": "일절, 전혀", "opts": ["", "断然＝他と比べて飛び抜けて（「断然安い」）。否定を強める語ではない", "突如＝急に、突然。責任の有無には合わない", "非常＝程度がはなはだしいこと。「非常に」の形でも否定とは結びつかない"], "ex": "会議の内容は<b>一切</b>外部に漏らさないでください。"},
"32176": {"point": "「結束する」は、多くの人が同じ目的のために固くまとまること。「すべての労働者が〜して経営者に当たった」とあるので、団結の意味の「結束」。", "meaning": "同じ目的を持つ人々が、固くまとまること。", "kr": "결속, 단결", "opts": ["緊密＝関係がすきまなく密接なこと（「緊密な連携」）。「緊密する」とは言わない", "親密＝仲がよく親しいこと。「親密する」とは言わない", "収束＝混乱などがおさまること（「事態が収束する」）。人がまとまる意味はない", ""], "ex": "地域の住民が<b>結束</b>して、ごみ処理場の建設に反対した。"},
"32177": {"point": "「論議する」は、ある問題について意見を出し合って論じ合うこと。「細かいことを〜していないで」とあるので、あれこれ議論する意味の「論議」が合う。", "meaning": "互いに意見を述べて論じ合うこと。", "kr": "논의", "opts": ["", "抗議＝相手のやり方に反対の意見を申し立てること。「細かいことを抗議する」は不自然", "審議＝議案などを詳しく調べて、よいか悪いかを話し合うこと。正式な場で使う", "会議＝集まって相談する会。「〜を会議する」とは言わない"], "ex": "新しい制度の是非をめぐって、国会で活発な<b>論議</b>が交わされた。"},
"32178": {"point": "「肌が敏感」は、肌が刺激に反応しやすいこと。化粧品を避ける理由として合うのは「敏感」。", "meaning": "刺激に対してすぐに反応する様子。", "kr": "민감하다, 예민하다", "opts": ["", "頻繁＝何度も繰り返し起こること（「頻繁に連絡する」）。肌の性質ではない", "真剣＝本気で取り組む様子。肌には使わない", "切実＝身にしみて強く感じる様子（「切実な問題」）。肌の性質ではない"], "ex": "この石けんは<b>敏感</b>な肌の人でも安心して使える。"},
"32179": {"point": "「はかない恋」は、長続きせずすぐに消えてしまう恋。「おわってみれば」とあるので、むなしく短い意味の「はかない」。", "meaning": "長続きせず、むなしく消えてしまう様子。", "kr": "덧없다, 허무하다", "opts": ["すばしこい＝動作がすばやい（「すばしこい子ども」）。恋には使わない", "ひらたい＝平らで高さがない。恋には使わない", "そっけない＝相手への態度が冷たく愛想がない。「恋」そのものを表す語ではない", ""], "ex": "夏の夜空に広がる花火は美しいが<b>はかない</b>。"},
"32180": {"point": "「〜に到達する」は、努力や移動の結果、ある地点・水準に行き着くこと。「合格圏内に」とあるので「到達」。", "meaning": "目的とする地点や水準に行き着くこと。", "kr": "도달", "opts": ["上達＝技術や能力が上手になること。「〜に上達する」とは言わない", "到着＝目的地に着くこと。場所に使い、「合格圏内」のような水準には使わない", "", "達成＝目標を成し遂げること。「〜を達成する」の形で、「〜に達成する」とは言わない"], "ex": "三日目の昼、登山隊はついに山頂に<b>到達</b>した。"},
"32181": {"point": "「栄養失調」は、栄養が足りず体の調子が崩れること。「栄養」と結びついて一語になるのは「失調」。", "meaning": "調和が崩れて、体の調子が悪くなること。", "kr": "실조", "opts": ["低調＝調子が出ず盛り上がらないこと（「低調な売れ行き」）", "不調＝調子が悪いこと。「栄養不調」とは言わない", "", "変調＝調子が変わること、普通の状態でなくなること（「体に変調をきたす」）。「栄養変調」とは言わない"], "ex": "戦後の食糧難の時代には、<b>栄養失調</b>になる子どもが多かった。"},
"32182": {"point": "「最先端」は、時代や技術のいちばん先。「通信技術の〜先端」なので、接頭語「最」が付く。", "meaning": "（「最先端」で）いちばん先。最も進んだところ。", "kr": "최첨단", "opts": ["", "核＝物事の中心（「核家族」）。「核先端」という語はない", "微＝ごく小さいこと（「微生物」）。「先端」には付かない", "緒＝物事の始まり（「端緒」）。「緒先端」という語はない"], "ex": "この研究所では医療の<b>最先端</b>の技術を研究している。"},
"32183": {"point": "「海外進出」は、企業などが外国の市場に新しく出て行って活動すること。「企業の海外〜」とあるので「進出」。", "meaning": "新しい方面・地域に進んで出て行くこと。", "kr": "진출", "opts": ["進入＝ある場所に進んで入ること（「車両進入禁止」）。企業の活動には使わない", "", "進展＝物事が進んで発展すること（「交渉が進展する」）。「海外進展」とは言わない", "推進＝物事を進めること（「計画を推進する」）。「海外推進」とは言わない"], "ex": "その自動車メーカーは十年前にアジア市場へ<b>進出</b>した。"},
"32184": {"point": "「ニュアンスの違い」は、言葉の意味や感じのごく細かい差。「微妙な」「二つの文の間」とあるので「ニュアンス」。", "meaning": "言葉・表現などの微妙な意味合いや感じ。", "kr": "뉘앙스", "opts": ["キャリア＝経歴、職業上の経験。文の違いには使わない", "チャンス＝機会。文の違いには使わない", "", "タイミング＝何かをするのにちょうどよい時機"], "ex": "同じ「すみません」でも、言い方によって<b>ニュアンス</b>が変わる。"},
"32185": {"point": "「有力」は、ある地位に就く見込みが大きいこと。「新しい首相は田中さんが〜だ」とあるので、可能性が高い意味の「有力」。", "meaning": "力や勢いがあること。見込みが大きいこと。", "kr": "유력", "opts": ["勢力＝人を従わせる勢い・力、またはその集団。「田中さんが勢力だ」とは言わない", "威力＝人を圧倒する強い力（「台風の威力」）", "", "権力＝人を支配し従わせる力。人が「権力だ」とは言わない"], "ex": "次の大会では、地元チームが優勝候補として<b>有力</b>視されている。"},
"32186": {"point": "「売り尽くす」は、商品を残らず全部売ること。30分で5000万円分が売れた、という文脈に合うのは「つくした」。", "meaning": "（「〜尽くす」で）残らず全部〜する。", "kr": "다 ~하다, 다 팔다", "opts": ["", "〜あかす＝「語り明かす」のように、夜明けまで〜する。「売りあかす」とは言わない", "〜かえす＝もう一度〜する、相手にやり返す（「読み返す」）。「売り返す」は意味が合わない", "〜わたす＝相手に移す（「売り渡す」）。売れた量の多さを表さない"], "ex": "閉店セールで、店の商品を全部<b>売り尽くした</b>。"},
"32187": {"point": "「手を焼く」は、扱いに困って持て余すこと。言うことをきかない妹に母が困っている、という意味になるのは「て」。", "meaning": "（「手を焼く」で）扱い方に困る。持て余す。", "kr": "애를 먹다, 골치를 앓다", "opts": ["「足を焼く」という慣用句はない", "", "「鼻を焼く」という慣用句はない", "「首を焼く」という慣用句はない"], "ex": "このパソコンは古くて動作が遅く、毎日<b>手</b>を焼いている。"},
"32188": {"point": "「単調な生活」は、変化がなく同じことの繰り返しの生活。「そろそろ飽きてきた」とあるので「単調な」。", "meaning": "変化がなく、一本調子な様子。", "kr": "단조롭다", "opts": ["大柄な＝体が大きい、模様が大きい。生活には使わない", "困難な＝非常に難しい。「飽きる」とは結びつかない", "", "複雑な＝込み入っている。変化が多いので、「飽きる」とは結びつかない"], "ex": "毎日同じ作業の繰り返しで、<b>単調な</b>仕事に眠くなる。"},
"32189": {"point": "「どうにか」は、苦労したり努力したりして、やっとのことで、という意味。「何度も読んでみて」とあるので、やっと理解できた意味の「どうにか」。", "meaning": "努力したりして、やっとのことで。なんとか。", "kr": "간신히, 그럭저럭, 겨우", "opts": ["とかく＝ややもすると、ともすれば（「とかく人は他人を批判しがちだ」）。そうなりやすい傾向を言う文で使い、「わかった」とは合わない", "どうでも＝どのようであっても（「どうでもいい」）。「わかった」とは結びつかない", "すんなり＝つかえずに簡単に。「何度も読んでみて」と合わない", ""], "ex": "締め切りの前日に、<b>どうにか</b>レポートを書き上げた。"},
"32190": {"point": "「〜のが望ましい」は、そうであることがよい、理想的だ、という意味。需要と供給が一致するのが理想だ、という文なので「のぞましい」。", "meaning": "そうなることが願わしい。そうあってほしい。", "kr": "바람직하다", "opts": ["あらっぽい＝乱暴で雑な様子。状態の理想を表さない", "まちどおしい＝早く来てほしいと待ち遠しい様子。予定された出来事に使う", "", "わずらわしい＝面倒で気が重い様子。文意に合わない"], "ex": "試験の前日は早めに寝るのが<b>望ましい</b>。"},
"32191": {"point": "「体が不調」は、体の調子がよくないこと。「思うように仕事がはかどらなかった」の原因として合うのは「不調」。", "meaning": "調子がよくないこと。", "kr": "컨디션 난조, 상태가 나쁨", "opts": ["困難＝非常に難しいこと。体の状態には使わない", "", "自在＝思いのままにできること（「自由自在」）。仕事がはかどらない理由にならない", "気楽＝心配がなくのんびりしている様子。仕事がはかどらない理由にならない"], "ex": "エースの投手が肩の<b>不調</b>で試合を欠場した。"},
"32192": {"point": "「ぺこぺこ頭を下げる」は、何度も頭を下げて、相手にへつらう様子。お得意の客に対する店員の様子なので「ぺこぺこ」。", "meaning": "何度も頭を下げて、へつらう様子。", "kr": "굽실굽실", "opts": ["ぼつぼつ＝少しずつ物事が始まる様子（「ぼつぼつ出かけよう」）", "", "だらだら＝しまりなく長く続く様子（「だらだら話す」）", "ずるずる＝引きずる様子、けじめなく長引く様子"], "ex": "彼は上司の前ではいつも<b>ぺこぺこ</b>している。"},
"32193": {"point": "「異議がある」は、ある意見や決定に反対の考えを持っていること。「この問題に〜のある人」と出席者に問いかけているので「異議」。", "meaning": "他と違う意見。反対の意見。", "kr": "이의", "opts": ["意向＝どうしたいかという考え（「本人の意向」）。「問題に意向がある」とは言わない", "発見＝初めて見つけること。「発見のある人」は文意に合わない", "", "偏見＝かたよった見方。人に問いかける場面に合わない"], "ex": "この案に<b>異議</b>のある方は、手を挙げてください。"},
"32194": {"point": "「情けない」は、あまりにひどくて嘆かわしい、みじめだ、という気持ち。大学に入れそうにないほど悪い点数なので「なさけない」。", "meaning": "あまりにもひどくて、みじめで嘆かわしい。", "kr": "한심하다, 비참하다", "opts": ["こころぼそい＝頼るものがなく不安な様子。点数には使わない", "たやすい＝簡単だ。点数の悪さを表さない", "なにげない＝特に意図がない様子（「何気ない一言」）", ""], "ex": "こんな簡単なミスをするなんて、我ながら<b>情けない</b>。"},
"32195": {"point": "「交代で」は、順番に入れ替わって何かをすること。食堂が狭いので順番に入れ替わって食事をする、という意味になるのは「交代」。", "meaning": "役目などを入れ替わってすること。", "kr": "교대", "opts": ["交互＝二つのものが代わる代わる（「左右の足を交互に出す」）。「交互で」とは言わない", "", "交差＝線や道などが交わること", "交錯＝いくつかのものが入りまじること（「期待と不安が交錯する」）"], "ex": "夜中の運転は、二人で<b>交代</b>ですることにした。"},
"32196": {"point": "「法律を廃止する」は、それまで行われていた制度や法律をやめること。法律の場合は「廃止」を使う。", "meaning": "それまでの制度・法律・習慣などをやめること。", "kr": "폐지", "opts": ["", "廃棄＝不要な物を捨てること（「書類を廃棄する」）。法律には使わない", "禁止＝ある行為をしてはいけないと止めること。法律そのものをなくす意味ではない", "停止＝動きや活動を途中で止めること（「営業停止」）。法律をなくす意味ではない"], "ex": "その国では、数年前に死刑制度が<b>廃止</b>された。"},
"32197": {"point": "「口が軽い」は、言ってはいけないことまで簡単に話してしまうこと。雄弁家だが困った点、という文脈に合うのは「かるい」。", "meaning": "（「口が軽い」で）秘密などを軽々しく話してしまう。", "kr": "입이 가볍다", "opts": ["", "しつこい＝何度も繰り返して嫌になる様子。「口がしつこい」とは言わない", "きつい＝言い方がきびしい意味の「口がきつい」はあるが、雄弁家と対比する困った点としては「軽い」が合う", "つよい＝「口が強い」という慣用句はない"], "ex": "あの人は<b>口が軽い</b>から、大事なことは話さないほうがいい。"},
"32198": {"point": "「〜をリードする」は、他より先に立って進むこと。「ヨーロッパ諸国を〜している」とあるので、先を行く意味の「リード」。", "meaning": "先に立って導くこと。他より優位に立つこと。", "kr": "리드, 앞섬", "opts": ["ケース＝場合、事例。「〜をケースする」とは言わない", "ポーズ＝姿勢、ふり。文意に合わない", "", "レース＝競走。「〜をレースする」とは言わない"], "ex": "後半に入っても、ホームチームが2点を<b>リード</b>している。"},
"32199": {"point": "船を数える助数詞は「隻（せき）」。「軍艦が三隻」となる。", "meaning": "船を数える語。", "kr": "척(배를 세는 단위)", "opts": ["炉＝火をたく所（「原子炉」）。助数詞ではない", "欄＝紙面などの区切り（「投書欄」）。助数詞ではない", "", "艇＝小さい船（「救命艇」）。船の種類を表す語で、助数詞ではない"], "ex": "港には大型のタンカーが二<b>隻</b>停泊している。"},
"32200": {"point": "「割り込む」は、列などの間に無理に入り込むこと。順番を待っている人の列に入り、文句を言われたので「こんで」。", "meaning": "人の間や列などに、無理に入り込むこと。", "kr": "끼어들다, 새치기하다", "opts": ["「割りつける」は紙面などに配分すること。列に入る意味ではない", "", "「割りこなす」という語はない", "「割りあげる」という語はない（「割り上げ」は料理の言葉）"], "ex": "レジの列に<b>割り込んで</b>きた人に注意した。"},
"32201": {"point": "「抗病力」は、病気に抵抗する力。接頭語「抗」は、〜に逆らう・〜を防ぐの意味（「抗菌」「抗がん剤」）。", "meaning": "（接頭語）〜に逆らう。〜を防ぐ。", "kr": "항(抗)~", "opts": ["被＝〜を受ける（「被害」「被災」）。「被病力」という語はない", "", "乱＝みだれる（「乱用」）。「病力」には付かない", "微＝ごく小さい（「微生物」）。「病力」には付かない"], "ex": "このタオルは<b>抗</b>菌加工がされているので、においにくい。"},
"32202": {"point": "「使いこなす」は、道具や技術を十分に使い、思いのままに扱うこと。「かなりの技術が必要」とあるので「こなす」。", "meaning": "（「〜こなす」で）十分に〜して、思いのままに扱う。", "kr": "자유자재로 ~하다, 능숙하게 다루다", "opts": ["〜おわる＝〜し終える。技術とは関係がない", "〜はたす＝「使い果たす」は全部使ってなくすこと。技術の必要と合わない", "〜すてる＝「使い捨てる」は一度使って捨てること", ""], "ex": "祖母はスマートフォンを上手に<b>使いこなして</b>いる。"},
"32203": {"point": "「ニュースをキャッチする」は、情報をすばやくとらえること。「いちはやく」とあるので、受け止める意味の「キャッチ」。", "meaning": "とらえること。受け止めること。", "kr": "캐치, 포착", "opts": ["", "コントロール＝調節や管理をすること。ニュースには合わない", "チェンジ＝変えること、交代すること", "インテリ＝知識人。動作を表す語ではない"], "ex": "記者たちは事件の情報をいち早く<b>キャッチ</b>した。"},
"32204": {"point": "「鼻にかける」は、自慢して得意そうにすること。成績が上がったことを自慢している、という意味になるのは「はな」。", "meaning": "（「鼻にかける」で）自慢して得意がる。", "kr": "자랑하다, 뽐내다", "opts": ["「顔にかける」という慣用句はない", "", "「足にかける」という慣用句はない", "「首にかける」は物を首にぶら下げる意味で、自慢の意味はない"], "ex": "彼女は家が金持ちなのを<b>鼻</b>にかけている。"},
"32205": {"point": "「不審な人」は、様子がおかしく疑わしい人。警察（110番）に通報する対象なので「不審な」。", "meaning": "疑わしいと思われる様子。", "kr": "수상하다", "opts": ["不吉な＝悪いことが起こりそうな（「不吉な予感」）。人の様子には使わない", "不明な＝はっきりしない（「原因不明」）。通報する人の様子ではない", "", "不当な＝正当でない（「不当な扱い」）"], "ex": "夜中に家の前をうろうろする<b>不審な</b>男がいた。"},
"32206": {"point": "「ずらっと並ぶ」は、たくさんのものが一列に長く並んでいる様子。入場券を買う人々の列なので「ずらっと」。", "meaning": "多くのものが一列に並んでいる様子。", "kr": "죽, 줄줄이", "opts": ["ひょっと＝思いがけず、もしかすると（「ひょっとしたら」）", "ちらっと＝一瞬だけ見える様子（「ちらっと見る」）", "きちっと＝整っていて乱れのない様子。人数の多さを表さない", ""], "ex": "本棚には古い辞書が<b>ずらっと</b>並んでいる。"},
"32207": {"point": "「無報酬」は、働いても報酬（お礼のお金）がないこと。「無〜で働いている」とあるので「報酬」。", "meaning": "労働や仕事に対するお礼のお金や品物。", "kr": "보수", "opts": ["失礼＝礼儀に欠けること。「無失礼」という語はない", "礼儀＝社会生活での作法。「無礼儀」とは言わず「無礼」", "賃金＝労働の対価のお金。「無〜で働く」の形では「無報酬」「無給」がふつう", ""], "ex": "彼はボランティアとして、<b>報酬</b>を受け取らずに働いている。"},
"32208": {"point": "「歴史に名高い」は、歴史の上で名前がよく知られていること。織田信長が死んだ場所として有名だ、という意味なので「なだかい」。", "meaning": "名前がよく知られている。有名だ。", "kr": "유명하다, 이름 높다", "opts": ["", "みすぼらしい＝見た目が貧しくてみっともない", "だるい＝体が疲れて重い", "くわしい＝細かい所までよくわかっている。「歴史に詳しい」は人について言う"], "ex": "この地方は良質な米の産地として<b>名高い</b>。"},
"32209": {"point": "「企画書」は、新しい仕事や催しの計画を書いた書類。「次の仕事の〜書を作成する」とあるので「企画」。", "meaning": "新しい事業などの計画を立てること。", "kr": "기획", "opts": ["用意＝準備すること。「用意書」という語はない", "", "企業＝利益を目的に事業を行う組織。「企業書」とは言わない", "事業＝社会的・経済的な仕事。「事業書」はふつう言わない（「事業計画書」）"], "ex": "新商品の<b>企画</b>が会議で採用された。"},
"32210": {"point": "「処置」は、病気やけがに手当てをすること。歯医者に行って虫歯の手当てをしてもらう、という文なので「処置」。", "meaning": "状況に応じて取り扱うこと。特に、けがや病気の手当て。", "kr": "처치", "opts": ["", "処分＝不要な物を始末すること、罰を与えること。治療には使わない", "処理＝仕事や問題を片付けること（「データを処理する」）。治療には使わない", "対処＝問題に応じて対応すること。「〜してもらう」の形で治療を表さない"], "ex": "けがをした選手は、すぐに医務室で応急<b>処置</b>を受けた。"},
"32211": {"point": "「見合わせる」は、事情により実行をしばらく控えること。運転状況によって発売を一時やめる、という意味なので「あわせる」。", "meaning": "事情を考えて、実行を一時やめておく。", "kr": "보류하다, 미루다", "opts": ["「見習う」は手本にしてまねること", "「見逃す」は見落とすこと、大目に見ること", "", "「見込む」は予想すること、期待すること。「ご容赦ください」と謝る内容に合わない"], "ex": "大雨のため、本日の試合は<b>見合わせる</b>ことになった。"},
"32212": {"point": "「没趣味」は、趣味がまったくないこと。「仕事のほかは」とあるので、何の趣味もない、という意味の「没」。接頭語「没」は「〜がない」の意味。", "meaning": "（接頭語）〜がない。", "kr": "몰(沒)~, ~이 없음", "opts": ["某＝ある、名前を伏せた（「某氏」）", "密＝ひそかな、すきまがない（「密輸」）", "猛＝はげしい（「猛練習」）。「猛趣味」とは言わない", ""], "ex": "仕事一筋だった父は、自分のことを<b>没</b>趣味な人間だと言っている。"},
"32213": {"point": "「歯が立たない」は、相手が強すぎたり難しすぎたりして、まったくかなわないこと。「むずかしすぎて」とあるので「は」。", "meaning": "（「歯が立たない」で）難しすぎて、まったく手に負えない。", "kr": "감당할 수 없다, 상대가 안 되다", "opts": ["「口が立つ」は話が上手なこと。「口がたたない」は意味をなさない", "「耳が立たない」という慣用句はない", "", "「手が立たない」という慣用句はない"], "ex": "相手チームは強すぎて、私たちにはまったく<b>歯</b>が立たなかった。"},
"32214": {"point": "「分裂」は、一つにまとまっていたものがいくつかに分かれること。意見の対立でクラブが二つに分かれた、という意味なので「分裂」。", "meaning": "一つのものが、いくつかに分かれること。", "kr": "분열", "opts": ["分散＝ばらばらに散らばること。「二つに」とは結びつきにくい", "分担＝仕事などを分けて受け持つこと", "", "分離＝一つのものから別々に離すこと（「油と水が分離する」）。対立による組織の分かれ方には「分裂」"], "ex": "党内の意見が合わず、党は<b>分裂</b>した。"},
"32215": {"point": "「国外に脱出する」は、危険な場所や状況から抜け出して逃げること。犯人が逃げたので「脱出」。", "meaning": "危険な所や状態から抜け出して逃げること。", "kr": "탈출", "opts": ["外出＝用事で家などの外に出かけること", "退出＝その場から出て行くこと（「会場から退出する」）", "", "出張＝仕事で他の土地へ出かけること"], "ex": "火事に気づいた住民たちは、すぐにビルから<b>脱出</b>した。"},
"32216": {"point": "「ブーム」は、ある物事が一時的に大流行すること。若者の間でスニーカーが流行している、という意味なので「ブーム」。", "meaning": "一時的な大流行。", "kr": "붐, 유행", "opts": ["ポーズ＝姿勢、ふり", "", "ムード＝その場の雰囲気", "シート＝座席、薄く平たいもの"], "ex": "今、若い女性の間で登山が<b>ブーム</b>になっている。"},
"32217": {"point": "「やたらに」は、程度を超えて、むやみに〜する様子。食器を必要以上に買い込むくせ、という意味なので「やたらに」。", "meaning": "根拠や節度がなく、むやみに。", "kr": "마구, 함부로, 무턱대고", "opts": ["もろに＝まともに、直接に（「もろにぶつかる」）", "まことに＝本当に（「まことに申し訳ない」）", "", "とっさに＝その瞬間すぐに。くせには合わない"], "ex": "知らない人に<b>やたらに</b>個人情報を教えてはいけない。"},
"32218": {"point": "「切実な問題」は、自分の生活に直接かかわり、身にしみて感じる問題。物価の値上がりについて言うので「切実な」。", "meaning": "自分に直接かかわり、身にしみて強く感じる様子。", "kr": "절실하다", "opts": ["迅速な＝動作や対応が非常に速い", "", "温和な＝性格や気候がおだやか", "器用な＝手先や要領がよい"], "ex": "若者にとって、就職は<b>切実な</b>問題だ。"},
"32219": {"point": "「うっとうしい」は、気分が晴れず、わずらわしく感じること。面白くなさそうにしている様子から、彼にとってこの仕事が気の重いものだと推測している。", "meaning": "気分が晴れず、わずらわしい。", "kr": "귀찮다, 성가시다, 울적하다", "opts": ["ものたりない＝何かが足りず満足できない様子。仕事が簡単すぎて張り合いがないときなどに使う", "ひさしい＝長い時間がたっている", "", "おっかない＝こわい"], "ex": "梅雨の時期は毎日雨で、<b>うっとうしい</b>。"},
"32220": {"point": "「普段の認識」は、日ごろから一般に持たれている認識。日本で離婚が増えているということが日ごろの共通理解だ、という意味で「普段」を選ぶ。", "meaning": "いつも。日ごろ。", "kr": "평소", "opts": ["", "通常＝特別でなく、ふつうであること（「通常の業務」「通常料金」）。業務や料金など、決まったやり方や状態について使う", "正常＝異常がなく、正しい状態", "同様＝同じである様子。「〜と同様の」のように比べる相手が必要で、この文には合わない"], "ex": "<b>普段</b>はおとなしい彼が、珍しく大きな声を出した。"},
"32221": {"point": "「陳列する」は、人に見せるために品物を並べておくこと。指輪を棚に並べて見せた、ということなので「並べた」が最も近い。", "meaning": "人に見せるために、品物を並べておくこと。", "kr": "진열하다", "opts": ["", "覆った＝上から全体にかぶせて隠した。並べる意味はない", "束ねた＝いくつかの物を一つにまとめてしばった", "操った＝道具や人を思うように動かした"], "ex": "店頭には新しい季節の商品が<b>陳列</b>されている。"},
"32222": {"point": "「心細い」は、頼るものがなくて不安な気持ちのこと。一人暮らしで不安になる、ということなので「不安に」が最も近い。", "meaning": "頼りになるものがなく、不安な様子。", "kr": "불안하다, 허전하다", "opts": ["", "平和に＝争いがなく穏やかに。不安とは逆の意味", "頻繁に＝何度も繰り返して。回数の意味", "活発に＝元気よく盛んに"], "ex": "知らない町で道に迷い、<b>心細く</b>なった。"},
"32223": {"point": "「著しい」は、違いや変化がはっきりと目立つ様子。「著しい対照」は違いがはっきりしていることなので「顕著な」が最も近い。", "meaning": "はっきりと目立つ様子。", "kr": "현저하다, 두드러지다", "opts": ["独特な＝そのものだけが持っている。目立つという意味ではない", "孤独な＝仲間がなく一人きりの", "敏感な＝わずかなことにもすぐ反応する", ""], "ex": "この十年で町の人口は<b>著しく</b>減少した。"},
"32224": {"point": "「うんざりする」は、同じことが続いてすっかりいやになること。「まいった」は、困り果てて閉口した気持ちを表し、最も近い。", "meaning": "物事に飽きて、すっかりいやになること。", "kr": "질리다, 지긋지긋하다", "opts": ["しまった＝失敗に気づいたときに言う言葉", "しめた＝思いどおりになって喜ぶときに言う言葉。逆の気持ち", "いたした＝「した」の謙譲語。気持ちを表さない", ""], "ex": "毎日同じ話を聞かされて、<b>うんざり</b>している。"},
"32225": {"point": "「ばったり」は、続いていたことが急にすっかり止まる様子。病気以来たばこを急にすっかり止めた、ということなので「完全に」が最も近い。", "meaning": "続いていたことが急に途絶える様子。", "kr": "뚝, 딱(끊다)", "opts": ["正確に＝間違いなく正しく", "", "正直に＝うそやごまかしがなく", "率直に＝飾らず、ありのままに"], "ex": "駅ができてから、この店の客足が<b>ばったり</b>途絶えた。"},
"32226": {"point": "「シナリオ」は映画などの脚本のことで、ここでは前もって考えた計画・筋書きの意味。「脚本」が最も近い。", "meaning": "映画・劇の脚本。転じて、前もって考えた計画や筋書き。", "kr": "시나리오, 각본", "opts": ["創作＝新しく作り出すこと、またその作品", "", "仮説＝説明のために仮に立てた考え", "架空＝事実ではなく想像で作ったこと"], "ex": "交渉は、こちらの<b>シナリオ</b>どおりに進んだ。"},
"32227": {"point": "「さっぱり」は、打ち消しやよくない意味の語と結び、まったくだめな様子を表す。「さっぱりです」は「全然うまくいきません」の意味。", "meaning": "（下に否定的な意味を伴って）まったくだめな様子。", "kr": "영 아니다, 신통치 않다", "opts": ["元気です＝体の調子がよい。よい状態を表す", "上々です＝非常によい。逆の意味", "まあまあです＝まずまず、ほどほど。だめという意味ではない", ""], "ex": "今年は雨が多くて、商売は<b>さっぱり</b>だ。"},
"32228": {"point": "「コレクション」は、趣味などで物を集めること、また集めた物。切手を集めているのだから「収集」が最も近い。", "meaning": "趣味などで物を集めること。また、集めた物。", "kr": "수집, 컬렉션", "opts": ["", "結束＝同じ目的のために固くまとまること", "募集＝人や作品などを広く呼びかけて集めること。趣味で集めるのではない", "拘束＝行動の自由をしばること"], "ex": "父の趣味は古いコインの<b>コレクション</b>だ。"},
"32229": {"point": "「やむをえず」は、ほかに方法がなく、仕方なくそうする様子。空港が閉鎖されて仕方なく泊まった、ということなので「しかたなく」が最も近い。", "meaning": "ほかに方法がなく、仕方なく。", "kr": "부득이, 어쩔 수 없이", "opts": ["まもなく＝少しの時間がたって。時間の意味", "思いがけなく＝予想もしないで", "", "限りなく＝終わりがなく、どこまでも"], "ex": "体調が悪く、<b>やむをえず</b>旅行を取りやめた。"},
"32230": {"point": "「ふんだんに」は、ありあまるほどたくさんある様子。水をたっぷり使う、ということなので「大量に」が最も近い。", "meaning": "ありあまるほど豊富な様子。", "kr": "충분히, 넉넉히, 듬뿍", "opts": ["普通に＝特に変わったところがなく", "適当に＝ほどよく、またはいいかげんに", "異常に＝普通とは違って。量の多さを表す語ではない", ""], "ex": "この料理には地元の野菜が<b>ふんだんに</b>使われている。"},
"32231": {"point": "「つくづく」は、念を入れてよくよく見る様子。自分の顔をよく時間をかけてながめた、ということなので「じっくり」が最も近い。", "meaning": "念を入れて、よくよく。心の底から深く感じる様子にも使う。", "kr": "곰곰이, 찬찬히, 절실히", "opts": ["こうこうと＝明かりが明るく光る様子", "きっちり＝すき間や過不足がなく正確な様子", "", "しっとり＝適度に湿っている様子、落ち着いた様子"], "ex": "古い写真を<b>つくづく</b>見ていると、昔のことが思い出された。"},
"32232": {"point": "「思惑」は、前もって考えている見込みやねらい。「思惑どおりに」は「考えていたとおりに」の意味なので「意図」が最も近い。", "meaning": "前もって考えていた見込み・ねらい。", "kr": "생각, 의도, 예상", "opts": ["", "目的＝実現しようとして目指す事柄。見込みの意味は弱い", "めじるし＝見つけたり区別したりするためのしるし", "めど＝物事が実現・解決する見通し（「解決のめどが立つ」）。本人が前もって考えたねらいや意図の意味はない"], "ex": "値上がりを期待したが、<b>思惑</b>が外れて損をした。"},
"32233": {"point": "「気がかりだ」は、どうなるかと心に引っかかって安心できない様子。将来がたいへん心配だ、ということなので「心配だ」が最も近い。", "meaning": "どうなるかと気になって、安心できない様子。", "kr": "걱정되다, 마음에 걸리다", "opts": ["愉快だ＝楽しくて気持ちがよい", "手近だ＝手の届く近い所にある", "盛大だ＝集まりなどが大がかりで立派だ", ""], "ex": "母の病気のことが<b>気がかり</b>で、仕事に集中できない。"},
"32234": {"point": "「意外にも」は、予想と違っていたことへの驚きを表す。予想に反して田中氏が選ばれた、ということなので「驚いたことに」が最も近い。", "meaning": "思っていたことと違って。予想に反して。", "kr": "의외로, 뜻밖에도", "opts": ["困ったことに＝迷惑・不都合だという気持ち。予想外の意味はない", "弱ったことに＝どうしてよいか困ったという気持ち", "", "幸いなことに＝運よく、という気持ち"], "ex": "<b>意外にも</b>、一番静かな彼がスピーチを引き受けた。"},
"32235": {"point": "「装う」は、衣服などで身なりを整えること。派手な服を着ていた、ということなので「着て」が最も近い。", "meaning": "衣服などで身なりを整え、飾ること。", "kr": "치장하다, 차려입다", "opts": ["", "寝て＝横になって眠って", "背いて＝従わずに逆らって", "焦って＝早くしようとして落ち着かずに"], "ex": "パーティーのために、彼女は着物で美しく<b>装って</b>いた。"},
"32236": {"point": "「かたくなに」は、自分の考えや態度をどうしても変えない様子。口を閉じて何も話そうとしない、ということなので「がんこに」が最も近い。", "meaning": "意地を張って、考えや態度を変えない様子。", "kr": "완고하게, 고집스럽게", "opts": ["しっかりと＝確かで、ゆるみがない様子。よい意味で使う", "あっさりと＝しつこくなく簡単に。逆の意味", "", "正確に＝間違いなく正しく"], "ex": "彼は周りの忠告を<b>かたくなに</b>拒み続けた。"},
"32237": {"point": "「わざと」は、そうと知りながら意識的にする様子。石を意識的に置いた、ということなので「故意に」が最も近い。", "meaning": "そうと知りながら、意識して。", "kr": "일부러, 고의로", "opts": ["並びに＝「および」と同じく、物事を並べてつなぐ接続詞", "ゆえに＝だから。理由を表す接続詞", "", "いまだに＝今になってもまだ"], "ex": "弟は<b>わざと</b>負けて、妹に勝たせてあげた。"},
"32238": {"point": "「わずらわしい」は、手間がかかったり気をつかったりして面倒に感じる様子。子どもの相手が面倒だ、ということなので「面倒だ」が最も近い。", "meaning": "手間がかかったり気をつかったりして、面倒な様子。", "kr": "번거롭다, 귀찮다", "opts": ["", "奇妙だ＝普通と違っていて不思議だ", "複雑だ＝入り組んでいて分かりにくい。面倒に感じる気持ちではない", "簡潔だ＝簡単で要領よくまとまっている"], "ex": "近所付き合いが<b>わずらわしく</b>て、マンションに引っ越した。"},
"32239": {"point": "「〜きらいがある」は、「〜しがちだ」「〜の傾向がある」という意味で、多くよくない傾向に使う。「傾向」が最も近い。", "meaning": "（「〜きらいがある」の形で）好ましくない傾向があること。", "kr": "경향, ~하는 면이 있다", "opts": ["", "区別＝違いによって分けること", "好み＝好きなこと。「嫌い」と混同させるわな", "様子＝外から見たありさま"], "ex": "彼は物事を大げさに言う<b>きらい</b>がある。"},
"32240": {"point": "「まばら」は、間があいていて数が少ない様子。観客が少なかった、ということなので「少なかった」が最も近い。", "meaning": "間があいていて、数が少ない様子。", "kr": "드문드문하다, 듬성듬성하다", "opts": ["", "多かった＝逆の意味", "ふまじめだった＝誠実さがなかった。人数の意味はない", "まじめだった＝誠実だった"], "ex": "平日の昼間の電車は、乗客も<b>まばら</b>だ。"},
"32241": {"point": "「反省する」は、自分の行いをふり返って、悪かったと考えること。謝罪の場面で使われており、「すまなく思っています」が最も近い。", "meaning": "自分の行いをふり返り、悪かった点を認めること。", "kr": "반성하다", "opts": ["がっかりしています＝期待が外れて力を落としている", "だめだと思っています＝見込みがないと思っている。謝る気持ちではない", "しっかりしています＝確かで、頼りになる", ""], "ex": "彼は自分の失言を深く<b>反省して</b>いる。"},
"32242": {"point": "「並ぶ」は、ここでは「同じ程度である、肩を並べる」の意味。数学で彼と同じくらいできる者はいない、ということなので「匹敵する」が最も近い。", "meaning": "能力などが同じ程度である。肩を並べる。", "kr": "견주다, 필적하다", "opts": ["挑戦する＝強い相手や難しいことに立ち向かう", "", "同盟する＝共通の目的のために手を結ぶ", "対処する＝問題に合わせて適切に処理する"], "ex": "料理の腕で彼女に<b>並ぶ</b>人はいない。"},
"32243": {"point": "「センス」は、物事の微妙なところを感じ取る能力。国際問題に対する鋭い感じ取り方のことなので「感覚」が最も近い。", "meaning": "物事の微妙な点を感じ取る能力。感覚。", "kr": "센스, 감각", "opts": ["", "推理＝分かっていることから筋道を立てて考えること", "政策＝政府などが行う政治の方針", "使命＝与えられた重要な務め"], "ex": "彼女は服の色の組み合わせの<b>センス</b>がいい。"},
"32244": {"point": "「堅実な」は、手堅く確実で、危なげがない様子。人生に対して確かな考えを持っている、ということなので「しっかりした」が最も近い。", "meaning": "手堅く確実で、危なげがない様子。", "kr": "견실한, 착실한", "opts": ["そっくりした＝よく似た（「そっくりな」）。考え方の性質ではない", "", "ゆったりした＝ゆとりがあって落ち着いた。手堅さの意味はない", "がっかりした＝期待が外れて力を落とした"], "ex": "彼は派手な投資はせず、<b>堅実な</b>貯金を続けている。"},
"32245": {"point": "「さっぱりだ」は、まったくよくない、だめな様子。景気がまったくよくない、ということなので「低調だ」が最も近い。", "meaning": "（よくない状態について）まったくだめな様子。", "kr": "영 신통치 않다, 형편없다", "opts": ["露骨だ＝気持ちなどを隠さず、むき出しにする", "高尚だ＝程度が高く、上品だ", "極端だ＝ひどく一方にかたよっている", ""], "ex": "勉強したのに、試験の結果は<b>さっぱり</b>だった。"},
"32246": {"point": "「抱える」は、ここでは人を雇って自分のもとに置く意味。運転手を雇った、ということなので「やとった」が最も近い。", "meaning": "人を雇って自分のもとに置くこと。", "kr": "고용하다, 거느리다", "opts": ["", "ののしった＝大声で悪く言った", "とがめた＝悪い点を責めた", "のっとった＝乗っ取った。奪って自分のものにした"], "ex": "その会社は千人の社員を<b>抱えて</b>いる。"},
"32247": {"point": "「弁解」は、自分の失敗などについて事情を説明して許してもらおうとすること。「言いわけ」が最も近い。", "meaning": "失敗などの事情を説明し、許しを求めること。", "kr": "변명", "opts": ["言いまわし＝言葉の言い表し方、表現", "", "言いかた＝話し方、ものの言い方", "言いつけ＝命令、指図"], "ex": "遅刻の理由をいくら<b>弁解</b>しても、先生は聞いてくれなかった。"},
"32248": {"point": "「ぺらぺら」は、外国語などをすらすらと上手に話す様子。英語をなめらかに話せる、ということなので「りゅうちょうだ（流暢だ）」が最も近い。", "meaning": "外国語などをすらすらと上手に話す様子。", "kr": "술술, 유창하다", "opts": ["おおざっぱだ＝細かいところまで気を配らない", "かんぺきだ＝完璧だ。欠点がない。話し方のなめらかさに限らない", "めちゃくちゃだ＝筋道がなく、ひどく乱れている", ""], "ex": "彼女は三年の留学で、フランス語が<b>ぺらぺら</b>になった。"},
"32249": {"point": "「丹念に」は、細かいところまで心をこめて、ていねいにする様子。本をていねいに時間をかけて読んだ、ということなので「じっくりと」が最も近い。", "meaning": "細かいところまで、心をこめてていねいに。", "kr": "정성껏, 꼼꼼히", "opts": ["", "ちらっと＝ほんの一瞬だけ", "ぼうっと＝ぼんやりして", "ざっと＝おおまかに、簡単に。逆の意味"], "ex": "祖母は古い着物を<b>丹念に</b>手入れしている。"},
"32250": {"point": "「倣う」は、手本としてまねをすること。人の作品をまねる、ということなので「模倣する」が最も近い。「習う（学ぶ）」との違いに注意。", "meaning": "手本としてまねること。", "kr": "따르다, 모방하다", "opts": ["", "学習する＝学んで身につける。「習う」の意味でここには合わない", "始末する＝後片付けをする", "改良する＝悪い点を直してよくする"], "ex": "前例に<b>ならって</b>、今年も式を簡単に行った。"},
"32251": {"point": "「ユニーク」は、ほかに例がなく、そのものだけの特色がある様子。「独特な」が最も近い。", "meaning": "ほかに類がなく、独自の特色がある様子。", "kr": "독특한, 유니크한", "opts": ["", "有名な＝広く名前が知られている", "美しい＝きれいだ", "すぐれた＝ほかより能力や質が上の"], "ex": "あの監督の映画は発想が<b>ユニーク</b>で面白い。"},
"32252": {"point": "「こつ」は、物事をうまく行うための大事な要点。魚を料理する要点を覚えた、ということなので「要領」が最も近い。", "meaning": "物事をうまく行うための大事な要点・やり方。", "kr": "요령", "opts": ["利点＝有利な点、長所", "修行＝技術などを身につけるために努めること", "", "製法＝品物の作り方"], "ex": "自転車に乗る<b>こつ</b>をつかむまで時間がかかった。"},
"32253": {"point": "「償い」は、相手に与えた損害を埋め合わせること。借りた車を壊したら損害を埋め合わせる、ということなので「補償」が最も近い。", "meaning": "与えた損害や罪を埋め合わせること。", "kr": "보상, 속죄", "opts": ["", "弁解＝言いわけ", "返還＝借りた物などを返すこと。損害の埋め合わせではない", "修理＝壊れた物を直すこと。損害を埋め合わせる意味とは違う"], "ex": "彼は一生かけて罪の<b>償い</b>をするつもりだ。"},
"32254": {"point": "「いかに〜ても」は、程度がどれほどであってもという逆接の強調。「どんなに苦しくても」と同じ意味なので「どんなに」が最も近い。", "meaning": "どれほど。どんなに。", "kr": "아무리, 얼마나", "opts": ["どうにか＝何とか、やっと", "", "どうして＝なぜ。理由を問う", "どうぞ＝人にすすめたり頼んだりするときの言葉"], "ex": "<b>いかに</b>急いでも、もう間に合わないだろう。"},
"32255": {"point": "「見合わせる」は、ここでは予定していたことを行うのをやめること。計画を取りやめると決めた、ということなので「中止する」が最も近い。", "meaning": "事情を考えて、予定していたことを行わずにおくこと。", "kr": "보류하다, 중지하다", "opts": ["変更する＝内容を変える。やめる意味ではない", "承認する＝正しいと認めて受け入れる", "実施する＝実際に行う。逆の意味", ""], "ex": "台風のため、電車は運転を<b>見合わせて</b>いる。"},
"32256": {"point": "「交代で」は、順番に入れかわって行う様子。ハンドルを順に入れかわってにぎった、ということなので「かわるがわる」が最も近い。", "meaning": "順番に入れかわって。", "kr": "교대로, 번갈아", "opts": ["くれぐれも＝何度も念を入れて（頼む）", "", "ことごとく＝残らず全部", "ちゃくちゃくと＝物事が順調に進む様子"], "ex": "夜は家族が<b>交代で</b>祖父の看病をした。"},
"32257": {"point": "「つつましい」は、遠慮深く控えめな様子。姉は控えめな人だ、ということなので「ひかえめな」が最も近い。", "meaning": "遠慮深く、控えめな様子。また、質素な様子。", "kr": "얌전하다, 조신하다, 검소하다", "opts": ["りっぱな＝すぐれていて堂々とした", "", "まずしい＝お金がなく生活が苦しい。「つつましい暮らし（質素）」とは違う", "のぞましい＝そうあってほしい"], "ex": "二人は小さな家で<b>つつましく</b>暮らしている。"},
"32258": {"point": "「くまなく」は、行き届かない所がなく、残らずすべての所に及ぶ様子。家の中を残らず捜した、ということなので「すみずみまで」が最も近い。", "meaning": "行き届かない所がなく、すみずみまで。", "kr": "샅샅이, 구석구석", "opts": ["", "ひととおり＝最初から最後まで大体", "とりあえず＝ほかのことはおいて、まず", "ありのままに＝実際のとおりに"], "ex": "警察は現場を<b>くまなく</b>調べた。"},
"32259": {"point": "「バトル」は、戦い・争いのこと。客を集める段階から競争だ、ということなので「戦い」が最も近い。", "meaning": "戦い。争い。", "kr": "배틀, 싸움", "opts": ["狙い＝目標、ねらうところ", "装い＝身なり、よそおい", "償い＝損害を埋め合わせること", ""], "ex": "人気商品をめぐって、各社の激しい<b>バトル</b>が続いている。"},
"32260": {"point": "「かけがえのない」は、ほかに代わりになるものがないほど大切な様子。写真がとても大切なものだ、ということなので「貴重な」が最も近い。", "meaning": "代わりになるものがないほど大切な。", "kr": "둘도 없는, 소중한", "opts": ["真剣な＝本気でまじめな", "", "地味な＝目立たない、派手でない", "格別な＝ほかと比べて特に程度が違う。代わりがないという意味ではない"], "ex": "家族は私にとって<b>かけがえのない</b>存在だ。"},
"32261": {"point": "「競走」は、走って速さを競うこと。100メートル走の勝負なので「レース」が最も近い。", "meaning": "一定の距離を走って速さを競うこと。", "kr": "경주, 레이스", "opts": ["バトル＝戦い、争い。速さを競う意味はない", "スコア＝得点", "", "スピード＝速さ。競う行為ではない"], "ex": "運動会の<b>競走</b>で、弟は一等になった。"},
"32262": {"point": "「どんより」は、空が曇っていて重く暗い様子。「どんよりした天気」は曇っていて暗い天気なので「曇っていて暗い」が最も近い。", "meaning": "空が雲におおわれて、重く暗い様子。", "kr": "잔뜩 흐린, 우중충한", "opts": ["晴れていて明るい＝逆の意味", "", "風が吹いて涼しい＝風の様子で、暗さの意味はない", "雨が降って蒸し暑い＝雨と暑さの意味で、「どんより」とは違う"], "ex": "朝から空が<b>どんより</b>曇っていて、気分も重い。"},
"32263": {"point": "「こぞって」は、全員がそろって、残らずみんなで、という意味。西側諸国がみんなそろって支持した、ということなので「すべて」が最も近い。", "meaning": "全員がそろって。残らずみんなで。", "kr": "모두, 다 함께", "opts": ["おのおの＝それぞれ。一人一人別々に", "ほとんど＝大部分。全部ではない", "", "あんのじょう＝思ったとおり"], "ex": "村の人々は<b>こぞって</b>祭りの準備に参加した。"},
"32264": {"point": "「告げる」は、事柄を人に言い知らせること。チャイムが終業を知らせた、ということなので「知らせる」が最も近い。", "meaning": "言葉や合図で知らせること。", "kr": "알리다, 고하다", "opts": ["閉じる＝開いていたものを閉める", "", "伝わる＝自動詞。「終業を伝わる」とは言えない", "叫ぶ＝大きな声を出す"], "ex": "春の訪れを<b>告げる</b>梅の花が咲き始めた。"},
"32265": {"point": "「慌ただしい」は、忙しくて落ち着かない様子。彼は急いで出発した、ということなので「急いで」が最も近い。", "meaning": "することが多くて忙しく、落ち着かない様子。", "kr": "황망하다, 분주하다", "opts": ["喜んで＝うれしく思って", "いさぎよく＝未練がなく、さっぱりと", "", "こころよく＝気持ちよく、嫌がらずに"], "ex": "年末は何かと<b>慌ただしく</b>過ぎていく。"},
"32266": {"point": "「ルート」は、道筋、経路のこと。情報がどんな道筋で入ってきたか、ということなので「経路」が最も近い。", "meaning": "道筋。物や情報が伝わる経路。", "kr": "루트, 경로", "opts": ["会議＝集まって相談すること", "議論＝意見を述べ合うこと", "", "流通＝商品などが生産者から消費者に渡ること。道筋そのものではない"], "ex": "山頂までは、いくつかの<b>ルート</b>がある。"},
"32267": {"point": "「オーケー」は、承知すること、許可すること。父から許可をもらっている、ということなので「承認」が最も近い。", "meaning": "承知・許可すること。", "kr": "오케이, 승낙, 허락", "opts": ["推薦＝よいと思う人や物を人にすすめること", "誤解＝間違った理解", "紹介＝知らない人同士を引き合わせること", ""], "ex": "部長から企画の<b>オーケー</b>が出た。"},
"32268": {"point": "「軽率」は、よく考えずに軽々しく行動すること。理由も聞かずに叱ったのは注意が足りなかった、ということなので「不注意」が最も近い。", "meaning": "よく考えずに、軽々しく物事をすること。", "kr": "경솔", "opts": ["", "不機嫌＝機嫌が悪いこと", "非常識＝常識に外れていること。考えの浅さとは違う", "非合法＝法律に違反していること"], "ex": "確かめもせずに人のうわさを広めるのは<b>軽率</b>だ。"},
"32269": {"point": "「ストップ」は、止まること、止めること。エンジンが止まった、ということなので「停止」が最も近い。", "meaning": "止まること。止めること。", "kr": "정지, 스톱", "opts": ["故障＝機械などが壊れて動かなくなること。止まった原因の一つで、同じ意味ではない", "", "燃焼＝燃えること", "爆発＝急に激しく破裂すること"], "ex": "大雪で、電車の運行が<b>ストップ</b>した。"},
"32270": {"point": "「バランス」は、つり合いのこと。綱の上でつり合いを取りながら歩いた、ということなので「均衡」が最も近い。", "meaning": "つり合い。釣り合いのとれた状態。", "kr": "균형, 밸런스", "opts": ["", "屈折＝折れ曲がること", "姿勢＝体の構え", "好調＝調子がよいこと"], "ex": "栄養の<b>バランス</b>を考えて食事をする。"},
"32271": {"point": "「欺く」は、うそを言って人をだますこと。彼女をだましてお金を取り上げた、ということなので「だまして」が最も近い。", "meaning": "うそを言って、人をだますこと。", "kr": "속이다, 기만하다", "opts": ["きずつけて＝体や心に傷を負わせて", "くるしませて＝つらい思いをさせて", "", "まよわせて＝どうしてよいか分からなくさせて"], "ex": "敵を<b>欺く</b>には、まず味方からと言う。"},
"32272": {"point": "「オーバー」は、ここでは実際以上に大げさな様子。形式的なほめ言葉を大げさに並べた、ということなので「おおげさで」が最も近い。", "meaning": "実際より大げさな様子。", "kr": "과장된, 오버하는", "opts": ["はなやかで＝明るく美しく目立って", "", "なめらかで＝すべすべして、またはよどみなく", "きよらかで＝汚れがなく美しく"], "ex": "彼はいつも話が<b>オーバー</b>なので、半分に聞いておいたほうがいい。"},
"32273": {"point": "「ややこしい」は、入り組んでいて分かりにくい様子。文の構造が入り組んでいる、ということなので「複雑だ」が最も近い。", "meaning": "入り組んでいて、分かりにくい様子。", "kr": "복잡하다, 까다롭다", "opts": ["明確だ＝はっきりしていて確かだ。逆の意味", "奇妙だ＝普通と違っていて不思議だ", "簡潔だ＝簡単で要領よくまとまっている。逆の意味", ""], "ex": "この手続きは書類が多くて<b>ややこしい</b>。"},
"32274": {"point": "「円滑に」は、物事が引っかかりなく順調に進む様子。会議が滞りなく進んだ、ということなので「スムーズに」が最も近い。", "meaning": "物事が引っかかりなく、順調に進む様子。", "kr": "원활하게, 순조롭게", "opts": ["エレガントに＝上品に、優雅に", "", "オープンに＝隠さず、開放的に", "ドライに＝感情にとらわれず割り切って"], "ex": "引き継ぎは<b>円滑に</b>行われた。"},
"32275": {"point": "「とっさに」は、その瞬間に、すぐさま反応する様子。落石をその瞬間によけた、ということなので「瞬間的に」が最も近い。", "meaning": "その瞬間に。すぐさま。", "kr": "순간적으로, 엉겁결에", "opts": ["一般的に＝広く全体に当てはまって", "間接的に＝間に何かを置いて、遠回しに", "", "積極的に＝自分から進んで"], "ex": "名前を聞かれて、<b>とっさに</b>うその名前を答えてしまった。"},
"32276": {"point": "「きわめて」は、程度がこの上なく高い様子。とても親切だった、ということなので「非常に」が最も近い。", "meaning": "この上なく。非常に。", "kr": "극히, 매우", "opts": ["いっこうに＝（下に否定を伴って）少しも", "", "初めて＝それまでになく、最初に", "不意に＝突然、思いがけなく"], "ex": "この手術が成功する可能性は<b>きわめて</b>低い。"},
"32277": {"point": "「ピンチ」は、追いつめられた苦しい状況、危ない状態のこと。そのとき私は危ない状態にあった、ということなので「危機」が最も近い。", "meaning": "追いつめられた危ない状態。", "kr": "핀치, 위기", "opts": ["不況＝景気が悪いこと", "切実＝身にしみて強く感じる様子", "貧困＝貧しくて生活に困ること。お金の意味に限られる", ""], "ex": "チームは九回に最大の<b>ピンチ</b>を迎えた。"},
"32278": {"point": "「ギャグ」は、人を笑わせるための冗談やしぐさ。みんなが爆笑した、ということなので「冗談」が最も近い。", "meaning": "人を笑わせるための冗談やしぐさ。", "kr": "개그, 농담", "opts": ["", "挨拶＝会ったときや別れるときに交わす言葉", "物語＝ある話の筋を語ったもの", "説話＝昔から語り伝えられた話"], "ex": "彼の<b>ギャグ</b>はいつも少し古い。"},
"32279": {"point": "「幼い」は、ここでは考えや行動が子どもっぽく未熟な様子。中学生とは思えないほど子どもっぽい、ということなので「幼稚で」が最も近い。", "meaning": "年が小さい。考えや行動が子どもっぽく、未熟な様子。", "kr": "어리다, 유치하다", "opts": ["物騒で＝危険なことが起こりそうで", "", "膨大で＝数や量が非常に多くて", "乱暴で＝荒々しく、無理に事をして"], "ex": "大人なのに、彼の考え方は少し<b>幼い</b>。"},
"32280": {"point": "「しょっちゅう」は、いつも、始終という意味。愚痴ばかりいつもこぼしている、ということなので「いつも」が最も近い。", "meaning": "いつも。始終。", "kr": "늘, 언제나, 노상", "opts": ["たびたび＝何度も繰り返して。回数が多いことで、「始終」という意味までは表さない", "にわかに＝急に、突然", "たまたま＝偶然に、時々。逆の意味", ""], "ex": "兄は<b>しょっちゅう</b>財布をなくしている。"},
"32281": {"point": "「肝心」は、特に大切なこと。何事も努力が大切だ、ということなので「重要だ」が最も近い。", "meaning": "物事の中で特に大切な様子。", "kr": "중요하다, 가장 중요하다", "opts": ["有利だ＝都合がよく、得になる", "妥当だ＝よく当てはまっていて適切だ", "", "得意だ＝自信があってうまくできる"], "ex": "外国語は毎日続けることが<b>肝心</b>だ。"},
"32282": {"point": "「なんだか」は、はっきりした理由はないが、何となくそう感じる様子。理由もなく好きになれない、ということなので「なんとなく」が最も近い。", "meaning": "理由ははっきりしないが、何となく。", "kr": "왠지, 어쩐지", "opts": ["しみじみ＝心に深く感じる様子", "", "いまにも＝もうすぐ、今すぐにも", "つくづく＝よくよく、心の底から"], "ex": "今日は<b>なんだか</b>体がだるい。"},
"32283": {"point": "「容易ならない」は「簡単には済まない、油断できないほど深刻だ」という意味。情勢が軽く考えられない状態になった、ということなので「重大な」が最も近い。", "meaning": "簡単には片づかない。軽く考えられないほど深刻だ。", "kr": "만만치 않은, 심상치 않은", "opts": ["迅速な＝非常に速い。深刻さの意味はない", "", "明白な＝はっきりしていて疑いがない", "無茶な＝筋道が通らず、程度がひどい"], "ex": "原油価格の急騰で、経済は<b>容易ならない</b>局面を迎えている。"},
"32284": {"point": "「コマーシャル」は商品などを宣伝するための放送（CM）。番組の途中で流すものなので「宣伝」が最も近い。", "meaning": "テレビ・ラジオなどで流す商業用の宣伝・広告。", "kr": "광고, 커머셜", "opts": ["予告＝前もって知らせること（「次回予告」）", "", "沈黙＝黙っていること", "抽選＝くじ引きで選ぶこと"], "ex": "ドラマのいいところで<b>コマーシャル</b>に切り替わった。"},
"32285": {"point": "「ギャップ」は二つのものの間の食い違い・隔たり。人と人の間にある考え方の隔たりを表す「溝」が最も近い。", "meaning": "食い違い。考え方などの隔たり。", "kr": "격차, 차이, 갭", "opts": ["", "同感＝同じように感じること。隔たりとは反対", "しこり＝争いの後に残るわだかまり。隔たりそのものではない", "ふた＝容器の口をふさぐもの"], "ex": "理想と現実の<b>ギャップ</b>に悩む新入社員は多い。"},
"32286": {"point": "「手軽に」は手間や費用がかからず、簡単にできる様子。誰でも簡単に海外旅行に行ける、ということなので「簡単に」。", "meaning": "手間がかからず、簡単にできる様子。", "kr": "손쉽게, 간편하게", "opts": ["見事に＝すばらしく、立派に", "", "退屈に＝することがなく、つまらなく", "冷静に＝感情に動かされず落ち着いて"], "ex": "電子レンジで<b>手軽に</b>作れる料理を紹介します。"},
"32287": {"point": "「ばったり」は思いがけず人に出会う様子。「ばったり会う」は予定していないのに偶然会うことなので「偶然」。", "meaning": "思いがけなく出会う様子。", "kr": "딱, 우연히 (마주치다)", "opts": ["自然＝人の手を加えないそのままの状態", "突然＝前ぶれなく急に。思いがけなさより急な点に重点がある", "断然＝きっぱりと、ずば抜けて", ""], "ex": "駅前で高校時代の先生に<b>ばったり</b>出くわした。"},
"32288": {"point": "「ほっとする」は心配や緊張がなくなって安心すること。彼が無事で心配がなくなった、ということなので「安心した」。", "meaning": "心配や緊張がとけて、安心する様子。", "kr": "안도하다, 한시름 놓다", "opts": ["残念だった＝期待どおりにならず心残りだ", "不安だった＝心配で落ち着かなかった。反対の意味", "心中した＝二人以上が一緒に自殺した", ""], "ex": "試験に合格したと聞いて、<b>ほっとした</b>。"},
"32289": {"point": "「カット」は一部を切り取ること。台本の数か所が取り除かれていた、ということなので「削除」が最も近い。", "meaning": "一部分を切って取り除くこと。", "kr": "삭제, 컷", "opts": ["補強＝足りない所を補って強くすること", "", "修正＝誤りや不十分な所を直すこと。取り除くとは限らない", "添削＝他人の文章などに書き加えたり削ったりして直すこと。一部を取り除くだけの「カット」とは違う"], "ex": "放送時間の都合で、インタビューの一部が<b>カット</b>された。"},
"32290": {"point": "「どうせ」は「どのような経過をたどっても結局は」という意味。いつかは必ず死ぬ、という文なので「いずれにしても」が最も近い。", "meaning": "どのみち。結局は。", "kr": "어차피, 어쨌든", "opts": ["もしかしたら＝ひょっとすると。可能性が低いことを推量する", "きっと＝確信をもって推量する。「結局は」の意味はない", "しらずしらずのうちに＝気づかないうちに", ""], "ex": "<b>どうせ</b>間に合わないのだから、ゆっくり行こう。"},
"32291": {"point": "「はかどる」は仕事などが順調に進むこと。仕事の様子を答えているので「順調に進んでいます」。", "meaning": "仕事などが順調に進む。", "kr": "진척되다, (일이) 잘 되어 가다", "opts": ["徐々に減っています＝少しずつ減っている。進み具合ではない", "", "予想外に遅れています＝思ったより遅れている。反対の意味", "急激に増えています＝急に増えている"], "ex": "静かな図書館のほうが勉強が<b>はかどる</b>。"},
"32292": {"point": "「あさましい」は品性が卑しく、情けない様子。賄賂を受け取るという卑しい行いなので「卑劣な」が最も近い。", "meaning": "心や行いが卑しく、情けない。", "kr": "비열한, 치사한, 한심한", "opts": ["冷静な＝感情に動かされず落ち着いた", "勇敢な＝勇ましく、恐れずに立ち向かう", "極端な＝程度が普通から大きく外れた", ""], "ex": "人の不幸で金もうけをしようとは、<b>あさましい</b>考えだ。"},
"32293": {"point": "「いまだに」は「今になってもまだ」という意味。以前から今まで独身のままだ、ということなので「今でも」。", "meaning": "今になってもまだ。", "kr": "아직까지도, 여태", "opts": ["", "そこまで＝その程度・その所まで", "今さら＝今になって（もう遅い）。「今さら言っても遅い」", "これから＝今から先"], "ex": "十年前の約束を、彼は<b>いまだに</b>覚えている。"},
"32294": {"point": "「いくらか」は数量や程度が少しある様子。お茶がまだ少し残っている、ということなので「少し」。", "meaning": "少し。いくぶん。", "kr": "얼마간, 조금", "opts": ["まったく＝完全に。否定とともに使うと「全然」の意味。「まったく残っている」とは言わない", "", "たっぷり＝十分にある様子。量が多い", "全然＝（否定とともに）少しも"], "ex": "薬を飲んで、痛みが<b>いくらか</b>和らいだ。"},
"32295": {"point": "「キャリア」は職業上の経験や経歴。法律家として長い経験を積んでいる、ということなので「経歴」。", "meaning": "職業上の経験・経歴。", "kr": "경력, 커리어", "opts": ["", "運転＝車などを動かすこと", "長身＝背が高いこと", "美人＝顔や姿の美しい女性"], "ex": "彼女は通訳として二十年の<b>キャリア</b>がある。"},
"32296": {"point": "「打ち明ける」は隠していたことを包み隠さず人に話すこと。すべてを彼女に話してしまった、ということなので「告白して」。", "meaning": "隠さずに、ありのままを話す。", "kr": "털어놓다, 고백하다", "opts": ["申告して＝役所などに正式に申し出て", "通告して＝決まったことを相手に知らせて", "", "密告して＝こっそり当局などに知らせて"], "ex": "悩みを親友に<b>打ち明けたら</b>、気持ちが楽になった。"},
"32297": {"point": "「ステップ」はここでは足の運び、歩き方の意味。休みを前に軽い足どりで帰る、ということなので「歩み」。", "meaning": "足の運び。歩調。また、段階。", "kr": "스텝, 발걸음", "opts": ["", "働き＝仕事をすること、作用", "舞台＝演劇などを演じる場所", "つえ＝歩くときに体を支える棒"], "ex": "合格の知らせを聞いて、軽い<b>ステップ</b>で家に帰った。"},
"32298": {"point": "「くろうと（玄人）」はその道の専門家。「くろうと並み」は専門家と同じくらいうまいことなので「プロ」。", "meaning": "その道に熟達した人。専門家。", "kr": "전문가, 프로", "opts": ["アマチュア＝素人。「くろうと」と反対の意味", "ゼロ＝何もないこと", "", "スマート＝細身で格好がよい、気が利いている"], "ex": "彼の料理の腕は<b>玄人</b>はだしだ。"},
"32299": {"point": "「頻繁に」は同じことが何度も繰り返し起こる様子。「しきりに」も何度も繰り返す様子を表すので最も近い。", "meaning": "何度も繰り返して起こる様子。", "kr": "빈번하게, 자주", "opts": ["", "にわかに＝急に、突然", "きわめて＝この上なく、非常に", "いっこうに＝（否定とともに）少しも"], "ex": "この交差点では事故が<b>頻繁に</b>起きている。"},
"32300": {"point": "「ポイント」は物事の大切な点・要点。説明の大事なところがわからなかった、ということなので「要点」。", "meaning": "大切な点。要点。", "kr": "요점, 포인트", "opts": ["視点＝物事を見たり考えたりする立場", "対処＝状況に合わせて適切に処理すること", "", "対策＝問題に対して取る方法"], "ex": "話の<b>ポイント</b>を三つにまとめてください。"},
"32301": {"point": "「しのぎを削る」は刀の部分をすり合わせるほど激しく争うこと。顧客獲得で激しく競っている、ということなので「競争し合って」。", "meaning": "互いに激しく争う。", "kr": "치열하게 경쟁하다, 각축을 벌이다", "opts": ["譲歩し合って＝互いに相手に譲って。反対の意味", "他人より優れて＝ほかの人よりまさって。争う意味はない", "鉛筆を削って＝文字どおりの意味で、慣用句の意味ではない", ""], "ex": "優勝をめぐって、二つのチームが<b>しのぎを削って</b>いる。"},
"32302": {"point": "「惜しむ」は失ったものを残念に思うこと。「死を惜しむ」は人の死を残念がり悲しむことなので「残念がっている」。", "meaning": "失ったものなどを残念に思う。", "kr": "애석해하다, 아까워하다", "opts": ["異常に思っている＝普通ではないと思っている", "面倒がっている＝手間がかかって嫌がっている", "妥当に思っている＝適切だと思っている", ""], "ex": "多くのファンが、彼の早すぎる引退を<b>惜しんだ</b>。"},
"32303": {"point": "「腹を決める」は覚悟して心を決めること。リーダーが決心すれば、ということなので「決心すれば」。", "meaning": "覚悟を決める。決心する。", "kr": "각오하다, 마음을 굳히다", "opts": ["じっとがまんすれば＝耐え忍べば。決める意味はない", "うらみをはらせば＝仕返しをして恨みをなくせば", "おこり出せば＝「腹を立てれば」の意味。「腹を決める」とは別", ""], "ex": "反対されても、彼は会社を辞めると<b>腹を決めた</b>。"},
"32304": {"point": "「プラス」はここでは有利な点・役立つことの意味。英語が話せることが彼の有利な点になっている、ということなので「利点」。", "meaning": "有利な点。役に立つこと。", "kr": "플러스, 이점", "opts": ["視点＝物事を見たり考えたりする立場", "", "観点＝物事を見たり考えたりする立場・角度", "欠点＝足りない点、悪い点。「プラス」と反対で「マイナス」に当たる"], "ex": "海外での生活経験が、就職活動で<b>プラス</b>に働いた。"},
"32305": {"point": "「ぞんざい」は物事の扱い方がいい加減で丁寧でない様子。物を雑に扱ってはいけない、ということなので「いいかげん」。", "meaning": "扱い方が雑で丁寧でない様子。", "kr": "소홀히, 함부로, 건성으로", "opts": ["じゅうぶん＝足りないところがない様子", "だいたい＝おおよそ", "わずか＝ほんの少し", ""], "ex": "客に<b>ぞんざいな</b>口のきき方をしてはいけない。"},
"32306": {"point": "「批評」は物事のよしあしなどについて意見を述べること。番組について意見を求めているので「コメント」が最も近い。", "meaning": "物事のよしあし・価値などを判断して意見を述べること。", "kr": "비평, 논평", "opts": ["インタビュー＝人に会って話を聞くこと", "アンケート＝多くの人に同じ質問をして答えてもらう調査", "チェック＝点検・確認すること", ""], "ex": "新作映画について、専門家の<b>批評</b>が新聞に載った。"},
"32307": {"point": "「閉口する」はどうにもならなくて困ること。この問題に困らされている、ということなので「なやまされて」。", "meaning": "どうしようもなく困ること。手に負えないこと。", "kr": "질림, 손듦, 곤란함", "opts": ["けなされて＝悪く言われて", "みなされて＝そうだと判断されて", "", "まよわされて＝どうしたらよいか迷うようにされて"], "ex": "毎晩続く隣の工事の騒音には<b>閉口して</b>いる。"},
"32308": {"point": "「うりふたつ（瓜二つ）」は顔かたちがよく似ていること。双子がよく似ている、ということなので「そっくり」。", "meaning": "顔かたちなどが非常によく似ていること。", "kr": "꼭 닮음, 판박이", "opts": ["めっきり＝変化がはっきり感じられる様子（「めっきり寒くなった」）", "ぶつぶつ＝小声で文句を言う様子", "にこにこ＝うれしそうに笑う様子", ""], "ex": "彼は若いころの父親と<b>瓜二つ</b>だ。"},
"32309": {"point": "「乗り越える」はここでは困難を切り抜けること。難関に打ち勝てなかった、ということなので「克服する」。", "meaning": "困難を切り抜ける。打ち勝つ。", "kr": "극복하다, 넘어서다", "opts": ["模倣する＝まねをする", "匹敵する＝力や価値が同じくらいである", "", "指摘する＝問題点などを取り上げて示す"], "ex": "多くの困難を<b>乗り越えて</b>、ついに店を開いた。"},
"32310": {"point": "「ケース」はここでは「場合・事例」の意味。診断が難しい場合が多い、ということなので「場合」。", "meaning": "場合。事例。", "kr": "경우, 케이스", "opts": ["しかけ＝工夫して作った仕組み", "はこ＝物を入れる容器。「ケース」の別の意味だが、この文には合わない", "経路＝通ってきた道筋", ""], "ex": "子どもが薬を誤って飲む<b>ケース</b>が増えている。"},
"32311": {"point": "「いかにも」はここでは「本当に・まったく」と程度を強める意味。本当に奇妙な事件だった、ということなので「実に」。", "meaning": "本当に。まったく。", "kr": "정말로, 참으로", "opts": ["", "異常に＝普通とは違って", "実は＝本当のことを言うと。前置きの言葉", "微妙に＝わずかな違いがあって、はっきりしない"], "ex": "それは<b>いかにも</b>残念な結果だった。"},
"32312": {"point": "「ポーズ」は体の構え・格好。モデルが写真のために構えをとった、ということなので「姿勢」。", "meaning": "体の構え・格好。", "kr": "포즈, 자세", "opts": ["", "雰囲気＝その場や人が持つ感じ", "均衡＝つり合いがとれていること", "態度＝物事に対する心の持ち方が表れた様子"], "ex": "カメラに向かって、子どもたちがかわいい<b>ポーズ</b>をとった。"},
"32313": {"point": "「世間話」は世の中の出来事などについての気軽なおしゃべり。決まったテーマのない話なので「雑談」。", "meaning": "世の中の出来事などについての気楽な話。", "kr": "잡담, 세상 이야기", "opts": ["", "講演＝大勢の前である題目について話すこと", "解説＝物事をわかりやすく説明すること", "議論＝互いに意見を述べて論じ合うこと"], "ex": "近所の人と<b>世間話</b>をしているうちに、一時間も過ぎていた。"},
"32314": {"point": "「じっくり」は落ち着いて時間をかけ、念入りに物事をする様子。どの道を選ぶべきか念入りに考えた、ということなので「慎重に」。", "meaning": "落ち着いて時間をかけ、念入りにする様子。", "kr": "차분히, 곰곰이", "opts": ["上手に＝うまく、巧みに", "地味に＝目立たない様子で", "", "巨大に＝非常に大きく"], "ex": "大事なことなので、<b>じっくり</b>話し合って決めよう。"},
"32315": {"point": "「あたかも」は「まるで〜のようだ」と、たとえる言い方。「あたかも真昼のような」は「まるで真昼のような」と同じ。", "meaning": "（後に「〜ようだ」が続いて）まるで。", "kr": "마치", "opts": ["いったん＝一度、ひとまず", "", "つまり＝言いかえると", "やがて＝まもなく、そのうちに"], "ex": "彼は<b>あたかも</b>自分が見てきたかのように話した。"},
"32316": {"point": "「目下」は「ただいま・今のところ」の意味。その問題は現在検討中だ、ということなので「現在」。", "meaning": "ただいま。今のところ。", "kr": "현재, 목하", "opts": ["将来＝これから先", "過去＝過ぎ去った時", "", "最中＝物事がいちばん盛んに行われているとき。「〜の最中」と使い、「目下」の言い換えにはならない"], "ex": "新製品は<b>目下</b>開発中で、来年発売の予定だ。"},
"32317": {"point": "「うとましい」は嫌で遠ざけたい気持ちを表す。大騒ぎされて嫌な気分になる、ということなので「いやな」。", "meaning": "嫌な感じがして遠ざけたい。わずらわしい。", "kr": "싫은, 귀찮은, 꺼림칙한", "opts": ["残念な＝期待どおりにならず心残りな", "よく知らない＝なじみがない。「疎い（うとい）」と混同しやすい", "", "なつかしい＝昔のことが思い出されて心がひかれる"], "ex": "毎日しつこく連絡してくる彼が<b>うとましく</b>なってきた。"},
"32318": {"point": "「ランクする」は順位・等級をつけること。ヒットチャートの第１位に位置づけられている、ということなので「順位づけ」。", "meaning": "順位・等級（をつけること）。", "kr": "순위, 랭크", "opts": ["忘却＝忘れてしまうこと", "決定＝はっきり決めること。順位の意味はない", "差別＝不当に区別して扱うこと", ""], "ex": "そのホテルは世界のトップ10に<b>ランク</b>されている。"},
"32319": {"point": "「判断する」はここでは「（笑ったことを）そういう意味だと考えた」こと。相手の行動の意味を理解した、という点で「解釈した」が最も近い。", "meaning": "物事を考えて、そうだと決めること。", "kr": "판단하다", "opts": ["拒否した＝要求などを断った", "断絶した＝関係などを断ち切った", "", "承諾した＝頼みを引き受けた。承知したのは彼女で、「私」は彼女が笑ったことの意味を考えただけなので合わない"], "ex": "空の様子から、午後は雨になると<b>判断した</b>。"},
"32320": {"point": "「一向に」は否定とともに使い、「少しも〜ない」という意味。お金に困っていることを全く知らなかった、ということなので「少しも」。", "meaning": "（否定とともに）少しも。全然。", "kr": "전혀, 조금도", "opts": ["", "むしろ＝どちらかと言えば", "すべて＝全部。一つの事実について「少しも知らなかった」と否定を強める意味はない", "かえって＝予想とは反対に"], "ex": "薬を飲んでいるのに、熱が<b>一向に</b>下がらない。"},
"32321": {"point": "「円滑」は、物事が支障なくすらすらと進む様子。「円滑に進む」「円滑な運営」のように物事の進み方に使い、人の性格や評価には使わない。②の仕事の進み方が正しい。", "meaning": "物事が滞りなく、すらすらと運ぶ様子。", "kr": "원활함, 순조로움", "opts": ["「円滑」は物事の進み方に使い、人の性格には使わない → 慎重だ（奥手だ）", "", "人の能力や評価を表す語ではない → 有能な（老練な）政治家", "「当然・不思議だ」という判断の意味はない → 不思議ではない（当然だ）"], "ex": "会議が<b>円滑</b>に進むよう、資料を事前に配っておいた。"},
"32322": {"point": "「はかどる」は、仕事や作業が順調に進むこと。「仕事がはかどる」「勉強がはかどらない」のように作業を主語にして使う。②の名簿作成が正しい。", "meaning": "仕事や作業が順調に進む。", "kr": "진척되다, 잘 되어 가다", "opts": ["場所を通り抜ける意味はない → 中心部を横切って（貫いて）流れる", "", "他動詞ではなく、「〜をはかどる」とは言わない → バランスを保つ（取る）", "許可・容認の意味はない → 署名してもかまわない（差し支えない）"], "ex": "静かな図書館だと、勉強がよく<b>はかどる</b>。"},
"32323": {"point": "「とりわけ」は、多くのものの中で特に目立って、という意味の副詞。②は「手先が器用」な中でも特に編み物が上手、と範囲の中の一つを取り立てているので正しい。", "meaning": "多くの中で特に。ことさら。", "kr": "특히, 유달리", "opts": ["予想に反するという意味はない → かえって（意外に）良い結果を生む", "", "手間をかけて、という意味はない → わざわざ行ったのに", "願望の強さを表す語ではない → 何とか（せめて）泳げるように"], "ex": "今年の夏は暑かったが、<b>とりわけ</b>八月はひどかった。"},
"32324": {"point": "「了承」は、相手の事情や申し出を理解して承知すること。「了承を得る」「ご了承ください」の形で使う。④の委員会の了承を得る、が正しい。", "meaning": "事情や申し出を理解して、認めること。", "kr": "양해, 승낙", "opts": ["終わる意味はない → ようやく終了した（終わった）", "仕事を終える意味はない → 完了する（終える）のに", "「〜のように」と知っている事柄を示すのは「ご存じ」 → ご存じ（ご承知）のように", ""], "ex": "工事中はご不便をおかけしますが、ご<b>了承</b>ください。"},
"32325": {"point": "「キャリア」は、仕事上の経歴や経験。「キャリアを積む」「長いキャリア」のように使う。③の転職で評価される経歴が正しい。", "meaning": "職業上の経歴・経験。", "kr": "경력, 커리어", "opts": ["購入できる物ではない → 新しいパソコン（設備）を購入した", "部署の中の地位を表す語ではない → 新しい部署のポスト（ポジション）に移る", "", "習得する技術の意味はない → ひとつの技（テクニック）を習得する"], "ex": "彼女は通訳として二十年の<b>キャリア</b>がある。"},
"32331": {"point": "「けなす」は、人や物の欠点を取り上げて悪く言うこと。「褒める」の反対。①の課長を悪く言う、が正しい。", "meaning": "欠点を取り上げて悪く言う。", "kr": "헐뜯다, 깎아내리다", "opts": ["", "しつこく頼む意味はない → 買ってくれとねだった", "体に触れる動作ではない → ほおをなでた（つねった）", "苦しんで努力する意味はない → いくらもがいても（工夫しても）"], "ex": "人の作品をむやみに<b>けなす</b>のはよくない。"},
"32332": {"point": "「うつろ」は、中がからっぽな様子、また心がぼんやりして目に生気がない様子。「うつろな目」「うつろな表情」の形でよく使う。④が正しい。", "meaning": "中身がない様子。気が抜けてぼんやりしている様子。", "kr": "공허함, 멍함", "opts": ["柄や色の派手さの意味はない → しまの（派手な）シャツ", "「うつろ」にうそや話のうまさの意味はない → あの人は、うそ（口）がうまい", "でたらめの意味はない → でたらめな（いいかげんな）こと", ""], "ex": "徹夜明けの彼は、<b>うつろ</b>な目で画面を見つめていた。"},
"32333": {"point": "「ドライ」は、感情や人情に流されず割り切っている様子。「ドライな性格」「ドライな関係」のようにナ形容詞として使う。③が正しい。", "meaning": "感情に流されず、割り切っている様子。", "kr": "냉정함, 드라이함", "opts": ["「ドライした」とは言わず、意味も合わない → しっかりした（はっきりした）個性", "「ドライとした」とは言わない → しっとりとした（ほのぼのとした）雰囲気", "", "先に立つという意味はない → 諸外国をリードしている"], "ex": "彼は職場の人間関係を<b>ドライ</b>に割り切っている。"},
"32334": {"point": "「へきえき（辟易）」は、相手や状況の勢いに困りはて、うんざりすること。「暑さにへきえきする」「長話にへきえきする」の形で使う。④が正しい。", "meaning": "困りはてて、うんざりすること。", "kr": "질림, 진저리남", "opts": ["相手に合わせて無理をする意味はない → 無理をして（へつらって）機嫌をとる", "上手になる意味はない → 驚くほど絵が上達した", "がっかりして元気をなくすのは「しょげる」 → しょげて（落ち込んで）しまった", ""], "ex": "上司の自慢話には、みんな<b>へきえき</b>している。"},
"32335": {"point": "「ろくに」は後ろに打ち消し（〜ない）を伴い、「満足に〜ない・十分に〜ない」と、あるべき程度に達していないことを不満や非難を込めて言う。②の「ろくに字も書けない」が正しい。①③④はどれも後ろに打ち消しがなく、意味も合わない。", "meaning": "（打ち消しを伴って）満足に。十分に。", "kr": "제대로 (~못하다), 변변히", "opts": ["打ち消しがなく、「ひどく・異様に」と程度を強める意味もない → やけに（いやに）暑い", "", "打ち消しがなく、「とても」の意味もない → いたって（とても）元気だ", "打ち消しがなく、「すぐに・反射的に」の意味もない → とっさに子どもをかばった"], "ex": "忙しくて、昼ご飯も<b>ろくに</b>食べられなかった。"},
"32341": {"point": "「しとやか」は、女性の言葉づかいや動作が上品で落ち着いている様子。①の「しとやかな女性」が正しい。", "meaning": "（主に女性の）言動が上品で落ち着いている様子。", "kr": "얌전함, 정숙함", "opts": ["", "自然の様子には使わない → 海はおだやかで", "数字や内容の正確さの意味はない → 正確な（細かい）見積もり", "柔らかくよく曲がる様子は「しなやか」 → 指はしなやかだ"], "ex": "彼女は着物姿で<b>しとやか</b>にお茶を運んできた。"},
"32342": {"point": "「いじる」は、指先でもてあそんだり、むやみに手を加えたりすること。③の「書類をいじらないで」（勝手に触らないで）が正しい。", "meaning": "指で触ってもてあそぶ。むやみに手を加える。", "kr": "만지작거리다, 손대다", "opts": ["軽く突く動作は「つつく」 → ひじで背中をつついた", "取り去る意味はない → ボタンを取られた（ちぎられた）", "", "相手を責めるのは「なじる」 → ついなじる（責める）ような言い方"], "ex": "会議中、彼はずっとペンを<b>いじって</b>いた。"},
"32343": {"point": "「しみじみ」は、心の底から深く感じる様子。「しみじみ（と）感じる・思う」の形で使う。②の母のありがたみを感じる場面が正しい。", "meaning": "心の底から深く感じる様子。", "kr": "절실히, 곰곰이", "opts": ["好みの程度を強める語ではない → とても（大）好きだ", "", "大変さの程度を表す語ではない → なかなか（かなり）たいへんだ", "漠然とした不調を表す語ではない → どうも体の調子が悪い"], "ex": "久しぶりに故郷に帰り、家族のありがたさを<b>しみじみ</b>と感じた。"},
"32344": {"point": "「余地」は、まだ何かをする余裕や可能性。「疑う余地がない」「改善の余地がある」の形で使う。①が正しい。", "meaning": "まだ何かをする余裕・可能性。", "kr": "여지", "opts": ["", "車に乗れる空きは「余裕」「席」で尋ねる。「余地」は「疑う余地」「改善の余地」のように、考えや可能性の幅に使う → 乗せてもらう余裕（席）がありますか", "休みの時間は「余暇」 → 余暇（休日）を楽しむ", "宴会などの出し物は「余興」 → 余興に手品を"], "ex": "この計画には、まだ検討の<b>余地</b>がある。"},
"32345": {"point": "「やけに」は、理由がわからないほど程度が普通ではない様子。「やけに暑い」「やけに機嫌がいい」のように使う。①が正しい。", "meaning": "程度が普通ではない様子。妙に。", "kr": "몹시, 유난히", "opts": ["", "仮定を表す語ではない → たとえ（仮に）雨だとしても", "各自が持つ様子は「手に手に」 → 手に手に武器を持って", "打ち消しを伴う「満足に〜ない」は「ろくに」 → ろくに勉強もしないのに"], "ex": "今日は朝から<b>やけに</b>静かだね。"},
"32351": {"point": "「目下（もっか）」は、ちょうど今、現在のところ。「目下練習中」「目下検討中」のように使う。②が正しい。", "meaning": "ちょうど今。現在。", "kr": "목하, 현재", "opts": ["未来を表す語ではない → この先（将来）どんなことがあるか", "", "「〜したとたん」の意味はない → 部屋に入った途端（瞬間）に", "「〜の最中」の意味では使わない → 暑い最中でも"], "ex": "新しい店舗は<b>目下</b>建設中です。"},
"32352": {"point": "「手配」は、物事がうまく運ぶよう前もって準備や指図をすること。「車を手配する」「チケットの手配」のように使う。④が正しい。", "meaning": "必要な物や人を前もって準備・用意すること。", "kr": "수배, 준비", "opts": ["傷の処置は「手当て」 → 手当て（処置）をしてもらった", "仕事に取りかかるのは「着手」 → すぐ仕事に着手した", "人にかける労力・面倒は「手間」 → 手間（迷惑）をかけて", ""], "ex": "出張のホテルの<b>手配</b>は秘書に任せている。"},
"32353": {"point": "「やたら」は、根拠や節度がなく、むやみな様子。「やたらなことを言うものではない」は、いいかげんなことを軽々しく言うな、の意味。④が正しい。", "meaning": "節度や根拠がなく、むやみな様子。", "kr": "함부로, 마구", "opts": ["眠りの深さを表す語ではない → ぐっすり（すぐに）眠って", "自分の思いどおりにするのは「勝手に」 → 勝手に決めて", "一生懸命の意味はない → 懸命に（必死に）働いた", ""], "ex": "知らない人に<b>やたら</b>と個人情報を教えてはいけない。"},
"32354": {"point": "「オープン」は、隠し立てがなく開放的な様子。「オープンな考え方」「オープンな性格」のように使う。④が正しい。", "meaning": "隠さず開放的な様子。公開されている様子。", "kr": "개방적, 오픈", "opts": ["「オープンとして」とは言わない → 情報をオープンにして（公開して）", "決まった場所の意味はない → 決まった（決められた）所", "止まる意味はない → エンジンがストップした（止まった）", ""], "ex": "うちの会社は<b>オープン</b>な雰囲気で、若手も意見を言いやすい。"},
"32355": {"point": "「むやみに」は、結果をよく考えずに度を越して行う様子。「むやみに木を切る」が正しい（②）。", "meaning": "あと先を考えず、度を越して。", "kr": "함부로, 무턱대고", "opts": ["量が十分な意味はない → たっぷり（十分に）ある", "", "直接受ける意味はない → もろに（まともに）受けて", "余計に払う意味はない → 余分に（多く）払っていた"], "ex": "薬は<b>むやみに</b>飲むと体に悪い。"},
"32361": {"point": "「没収」は、国や公的機関などが、所有物を強制的に取り上げること。③の不正に手に入れた土地を取り上げられた場面が正しい。", "meaning": "所有物を強制的に取り上げること。", "kr": "몰수, 압수", "opts": ["使えなくなる意味は「無効」 → 切符は無効になります", "まとめて一つにするのは「統合」 → 一つに統合する", "", "自分から断るのは「辞退」 → 出場を辞退する"], "ex": "授業中に使っていた携帯電話を先生に<b>没収</b>された。"},
"32362": {"point": "「無茶」は、道理に合わない、度を越した乱暴な様子。「無茶な運転」「無茶を言う」のように使う。④が正しい。", "meaning": "筋道が立たず、度を越している様子。", "kr": "터무니없음, 무모함", "opts": ["豊かな量の意味はない → 豊富な（莫大な）天然資源", "「無茶した」で増減は表せない → 急増した（激減した）", "疑わしい様子は「不審」 → 原因不明の不審な火災", ""], "ex": "熱があるのに出勤するなんて、<b>無茶</b>だよ。"},
"32363": {"point": "「かばう」は、他から害や非難を受けないよう守ること。④の飛んできたボールから子どもを守る場面が正しい。", "meaning": "害や非難から守る。", "kr": "감싸다, 두둔하다", "opts": ["隠したりうそをついたりする意味はない → 年齢を偽って（隠して）いた", "奪われる意味は「さらう」 → 優勝をさらわれた", "注意をよそへ向けるのは「そらす」 → 注意をそらそうとした", ""], "ex": "兄はいつも、叱られる弟を<b>かばって</b>くれた。"},
"32364": {"point": "「うんざり」は、同じことが続いたり程度がひどかったりして、すっかり嫌になること。②の決まりきった毎日の仕事に飽きている場面が正しい。", "meaning": "飽きたりひどすぎたりして、すっかり嫌になる様子。", "kr": "지긋지긋함, 질림", "opts": ["期待が外れて気落ちするのは「がっかり」。「うんざり」は同じことが続いて嫌になる様子 → がっかりしている", "", "考えが確かで頼りになる様子は「しっかり」 → 考え方がしっかりしている", "完全に、の意味は「すっかり」 → すっかりよくなったら"], "ex": "毎日同じ弁当で、もう<b>うんざり</b>だ。"},
"32365": {"point": "「本音」は、表に出さない本当の気持ち。「建前」の反対。②の、かかわりたくないというのが本当の気持ちだ、が正しい。", "meaning": "表向きではない、本当の気持ち。", "kr": "본심, 속마음", "opts": ["実際の性質を表す語ではない → 本当は（実は）利口者だ", "", "「本音的」という語はない → 本格的ではない", "真剣な気持ちは「本気」 → 本気になって"], "ex": "酒の席になって、ようやく彼は<b>本音</b>を話し始めた。"},
"32371": {"point": "「キャッチ」は、捕らえること。情報や電波などをとらえる意味でも使う。①の「情報をキャッチする」が正しい。", "meaning": "捕らえること。情報などをつかむこと。", "kr": "캐치, 포착", "opts": ["", "削る意味は「カット」 → 予算をカットして（削って）", "後ろ盾の意味は「バック」 → 世論をバックにした", "初めて世に出るのは「デビュー」 → デビューして以来"], "ex": "ラジオで台風の最新情報を<b>キャッチ</b>した。"},
"32372": {"point": "「冷酷」は、思いやりがなく、むごいことを平気でする様子。①の非情な犯行が正しい。", "meaning": "思いやりがなく、むごい様子。", "kr": "냉혹함", "opts": ["", "規模が小さく地味なのは「質素」「ささやか」 → 質素な（ささやかな）もの", "強く願う様子は「切実」 → 切実な（熱烈な）願い", "人をひきつける性格とは逆の意味 → 温厚な（誠実な）人柄"], "ex": "部下を<b>冷酷</b>に切り捨てる上司に、皆が反発した。"},
"32373": {"point": "「ことごとく」は、一つ残らず全部、という意味の副詞。①の書いてあることを全部理解した、が正しい。", "meaning": "残らず全部。すべて。", "kr": "모조리, 남김없이", "opts": ["", "変化の進み方を表す語ではない → だんだん（すっかり）暗くなって", "推量を表す語ではない → おそらく（たぶん）電車は遅れる", "簡単に済ませる意味は「そこそこに」 → 朝食もそこそこに"], "ex": "反対派の意見は<b>ことごとく</b>退けられた。"},
"32374": {"point": "「がっくり」は、急に力が抜けたり、ひどく気落ちしたりする様子。②の息子に死なれて気落ちしている場面が正しい。", "meaning": "急に力が抜ける様子。ひどく気落ちする様子。", "kr": "맥이 탁 풀림, 낙심함", "opts": ["頑丈な様子は「がっしり」 → がっしりした（頑丈な）倉庫", "", "しっかり組む様子は「がっちり」 → がっちりとスクラムを組んだ", "ちょうど合う様子は「ぴったり」 → ぴったり合う"], "ex": "あと一点で負けて、選手たちは<b>がっくり</b>と肩を落とした。"},
"32375": {"point": "「心中（しんじゅう）」は、二人以上の人が一緒に自殺すること。①の生活苦から心中する事例が正しい。なお「しんちゅう」と読むと「心の中」の意味。", "meaning": "二人以上が一緒に自殺すること。", "kr": "동반 자살", "opts": ["", "心を決めるのは「決心」 → 一生をささげようと決心した", "その時の気持ちは「気分」 → さわやかな気分になった", "心の働きに関するのは「心理的」 → 心理的な（精神的な）もの"], "ex": "借金に苦しんだ一家が<b>心中</b>を図った。"},
"32381": {"point": "「いまにも」は、すぐにもある事態が起こりそうな様子で、「いまにも〜そうだ」の形で使う。④の「いまにも雨が降りだしそうだ」が正しい。", "meaning": "すぐにも。今すぐにも起こりそうな様子。", "kr": "당장이라도, 금방이라도", "opts": ["相手の気持ちを推し量る語は「さぞ」 → さぞ（どんなにか）喜んでいる", "程度がはなはだしい推量は「よほど」 → よほどくやしかった", "すぐに行動する意味は「さっそく」 → さっそく今夜作って", ""], "ex": "彼女は<b>いまにも</b>泣き出しそうな顔をしていた。"},
"32382": {"point": "「いたわる」は、弱い立場の人や苦労した人に同情して大切に扱うこと。①の病人をいたわる、が正しい。", "meaning": "弱い人や苦労した人を思いやって大切にする。", "kr": "위로하다, 돌보다", "opts": ["", "努力が成果となるのは「報われる」 → 報われる（実を結ぶ）努力", "お金を払って使うのは「借りる」 → アパートを借りている", "人を通して世話する意味はない → 紹介して（世話して）もらった"], "ex": "長旅で疲れた両親を<b>いたわって</b>、温泉に連れて行った。"},
"32383": {"point": "「折衷」は、異なる考えや様式からよいところを取り合わせて一つにまとめること。「和洋折衷」「案を折衷する」の形で使う。④が正しい。", "meaning": "異なるものの良い所を取り合わせて、一つにまとめること。", "kr": "절충", "opts": ["「折衷な」とは言わない → 融合した（併設した）事業展開", "身にしみて感じるのは「痛切」 → 痛切に感じた", "取り締まりの手段は「措置」 → 厳しい措置（態度）をとった", ""], "ex": "この旅館は、和風と洋風を<b>折衷</b>した造りになっている。"},
"32384": {"point": "「質素」は、ぜいたくをせず、つつましい様子。「質素な生活」「質素な食事」のように使う。①が正しい。", "meaning": "ぜいたくをせず、つつましい様子。", "kr": "검소함, 수수함", "opts": ["", "話し方の正直さを表す語ではない → 率直に（冷静に）話し合おう", "すなおに受け入れる意味は「素直」 → 素直に誤りを認めた", "ありのままに言うのは「率直」 → 率直に（端的に）言うと"], "ex": "祖父は年金だけで<b>質素</b>に暮らしている。"},
"32385": {"point": "「だぶだぶ」は、衣服などが体に比べて大きすぎ、ゆるくて余っている様子。④の兄の洋服が大きすぎる場面が正しい。", "meaning": "衣服などが大きすぎて、ゆるい様子。", "kr": "헐렁헐렁", "opts": ["物事にゆっくり取りかかる様子は「ぼちぼち」 → ぼちぼち（そろそろ）勉強にかかる", "目が回る様子は「くらくら」 → くらくら目まいがして", "ためらって落ち着かない様子は「もじもじ」 → もじもじ（おどおど）して", ""], "ex": "やせたので、ズボンが<b>だぶだぶ</b>になってしまった。"},
"32391": {"point": "「すみやか」は、物事を行うのが早い様子。「すみやかに行動する」「すみやかな対応」のように使う。②が正しい。", "meaning": "物事の処理や行動が早い様子。", "kr": "신속함, 조속함", "opts": ["柔らかくよく曲がる様子は「しなやか」 → しなやかな体", "", "傾きがなだらかなのは「ゆるやか」 → ゆるやかな坂", "上品で落ち着いた女性は「しとやか」 → しとやかな女性"], "ex": "地震が起きたら、<b>すみやか</b>に建物の外へ避難してください。"},
"32392": {"point": "「つくづく」は、心の底から深く感じたり、念入りに考えたりする様子。「つくづく思う・考えさせられる」の形で使う。②が正しい。", "meaning": "心の底から深く。よくよく。", "kr": "절실히, 곰곰이", "opts": ["胸の高鳴りは「どきどき」 → むねがどきどきした", "", "思いがけず、の意味は「偶然」 → 偶然（たまたま）あの店で", "液体が続いて出る様子は「ずるずる」 → 鼻水がずるずる出てきて"], "ex": "病気になって、健康のありがたさを<b>つくづく</b>感じた。"},
"32393": {"point": "「内緒」は、他人に知らせず秘密にしておくこと。「内緒にする」「内緒の話」の形で使う。②が正しい。", "meaning": "人に知らせず秘密にすること。", "kr": "비밀", "opts": ["財産を受け継ぐのは「相続」 → 全財産を相続した", "", "自分の立場を意識するのは「自覚」 → 責任を自覚している", "同じ時の意味は「同時」 → 卒業と同時に結婚した"], "ex": "これは二人だけの<b>内緒</b>の話だよ。"},
"32394": {"point": "「シック」は、あか抜けていて上品なこと。服装や色づかいについて「シックな装い」のように使う。②が正しい。", "meaning": "あか抜けていて上品な様子。", "kr": "세련됨, 시크함", "opts": ["体の過敏な反応は「アレルギー」 → アレルギー（炎症）を起こす", "", "声の調子は「トーン」 → 声のトーン（調子）", "感覚・素質は「センス」 → 音楽のセンス"], "ex": "黒でまとめた<b>シック</b>な服装で、パーティーに出かけた。"},
"32395": {"point": "「前途」は、これから先の道のり・将来。「前途を祝す」「前途有望」の形で使う。③の新婚夫婦の将来を祝う場面が正しい。", "meaning": "これから先の行く手。将来。", "kr": "전도, 앞날", "opts": ["行く途中は「途中」 → 途中で引き返した", "何かが起こる前のしるしは「前兆」 → 大地震の前兆", "", "空間的な前の方は「前方」 → 私の車の前方に"], "ex": "<b>前途</b>ある若者たちに、大きな期待が寄せられている。"},
"32401": {"point": "「ゆるやか」は、傾きや変化がなだらかで急でない様子。「ゆるやかな坂」「ゆるやかに傾斜する」のように使う。③が正しい。", "meaning": "傾きや動きが急でなく、なだらかな様子。", "kr": "완만함, 느슨함", "opts": ["連絡の取り方を表す語ではない → ひそかに（頻繁に）連絡を取り合って", "音の小ささは「かすか」 → かすかな（わずかな）物音", "", "水面の様子は「なめらか」 → 鏡のようになめらかだった（静かだった）"], "ex": "景気は<b>ゆるやか</b>に回復している。"},
"32402": {"point": "「中断」は、続いていた物事を途中で一時切ること。「試合が中断される」「演説を中断する」のように使う。②が正しい。", "meaning": "続いていた物事が途中で一時止まること。", "kr": "중단", "opts": ["「中断で」とは言わない → 中途半端で（途中で）やめては", "", "どちらにも付かない態度は「中立」 → 中立的な（あいまいな）態度", "現地から送る放送は「中継」 → 中継放送された"], "ex": "大雨のため、試合は三十分間<b>中断</b>した。"},
"32403": {"point": "「サボる」は、すべき仕事や勉強を怠けて休むこと。「授業をサボる」「当番をサボる」のように使う。②が正しい。", "meaning": "すべきことを怠ける。", "kr": "땡땡이치다, 게으름 피우다", "opts": ["見て見ないふりは「目をつぶる」 → 目をつぶった", "", "乗り損なうのは「のがす」 → この電車をのがす（乗り遅れる）と", "急ぐ意味はない → 合意を急ぐことはない"], "ex": "彼は部活を<b>サボって</b>ゲームセンターに行っていた。"},
"32404": {"point": "「同調」は、他人の意見や行動に調子を合わせること。③の仲間が少年に合わせて学校をさぼった、が正しい。", "meaning": "他人の意見や行動に調子を合わせること。", "kr": "동조", "opts": ["同じ考えだという意味は「同感」 → まったく同感だ", "調子がよいのは「好調」 → 好調を維持している", "", "身をもって感じるのは「実感」 → 生きる喜びを実感した"], "ex": "周りの意見に<b>同調</b>するだけでなく、自分の考えも言うべきだ。"},
"32405": {"point": "「じっくり」は、落ち着いて時間をかけ、念入りに物事をする様子。「じっくり考える」が正しい（①）。", "meaning": "落ち着いて、時間をかけて念入りに行う様子。", "kr": "차분히, 곰곰이", "opts": ["", "ひどく気落ちする様子は「がっくり」 → がっくりしている", "失望する様子は「がっかり」 → がっかりしている", "味が淡い様子は「あっさり」 → あっさりしている"], "ex": "この問題は、時間をかけて<b>じっくり</b>話し合おう。"},
"32411": {"point": "「追及」は、責任や原因などをどこまでも問いただすこと。「責任を追及する」「容疑者を追及する」のように使う。①が正しい。", "meaning": "責任や原因などを、どこまでも問いただすこと。", "kr": "추궁", "opts": ["", "遠くへ追い出すのは「追放」 → その島に追放され", "後から加えるのは「追加」 → あと３人まえ追加して", "足りない所を満たすのは「補う」 → 短所を補い合っている"], "ex": "記者たちは大臣の責任を厳しく<b>追及</b>した。"},
"32412": {"point": "「こっけい（滑稽）」は、言動がおもしろおかしく、人を笑わせる様子。③の「こっけいなことを言ってみんなを笑わせる」が正しい。", "meaning": "おもしろおかしく、笑いを誘う様子。", "kr": "익살스러움, 우스꽝스러움", "opts": ["住まいを褒める語ではない → すてきな（けっこうな）お住まい", "何度も繰り返す様子は「しきりに」 → しきりに水をほしがった", "", "打ち消しを伴う「満足に〜ない」は「ろくに」 → ろくに寝てない"], "ex": "ピエロの<b>こっけい</b>な動きに、子どもたちは大笑いした。"},
"32413": {"point": "「さぞ」は、他人の気持ちやその場の様子を推し量る副詞で、「さぞ〜だろう・に違いない」と推量の表現と結びつく。③が正しい。", "meaning": "（推量を伴って）きっと。どんなにか。", "kr": "필시, 얼마나", "opts": ["危ないところだった意味は「あやうく」 → あやうく（もう少しで）死ぬところだった", "比較の差の大きさは「はるかに」 → はるかに優れている", "", "全く〜ない、は「まるで」 → まるで（てんで）聞こうともしない"], "ex": "一人で子どもを三人育てるのは、<b>さぞ</b>大変だっただろう。"},
"32414": {"point": "「コントロール」は、思いどおりに調節・管理すること。「感情をコントロールする」が正しい（③）。", "meaning": "思いどおりに調節・管理すること。", "kr": "컨트롤, 조절", "opts": ["距離の意味は「間隔」 → 同じ間隔（スペース）を空けて", "前もって決めた筋書きは「シナリオ」 → シナリオ（筋書き）", "", "分類の意味は「カテゴリー」 → 製品カテゴリー（モデル）"], "ex": "体重を<b>コントロール</b>するために、毎朝走っている。"},
"32415": {"point": "「動機」は、人がある行動を起こすきっかけ・理由となる気持ち。④の「〜という動機から医者になった」が正しい。", "meaning": "人が行動を起こす直接の原因となる気持ち。", "kr": "동기", "opts": ["配慮する意味は「考慮」 → 年齢を考慮しては（配慮しては）くれなかった", "「動機した」とは言わない → いい薬になった（教訓になった）", "体の動きで示すのは「手振り」 → 手振り（身振り）で示した", ""], "ex": "犯人の<b>動機</b>はいまだにわかっていない。"},
"32501": {"point": "「瓦解」は「がかい」。「瓦」は音読みで「ガ」（訓は「かわら」）、「解」は「カイ」。一部が崩れて全体がばらばらになること。", "meaning": "組織や関係などの一部が崩れたことから、全体がばらばらに崩れること。", "kr": "와해", "opts": ["うかい：「瓦」は「が」。「うかい」は「迂回」の読み", "", "ごかい：「瓦」は「が」。「ごかい」は「誤解」の読み", "わかい：「瓦」は「が」。「わかい」は「和解」の読み"], "ex": "内部の対立によって、連立政権は<b>瓦解</b>した。"},
"32502": {"point": "「懇談会」は「こんだんかい」。「懇」は「コン」（懇親会・懇願）、「談」は「ダン」。打ち解けて話し合う会のこと。", "meaning": "打ち解けて話し合う会。", "kr": "간담회", "opts": ["", "かんだんかい：「懇」は「こん」。「かんだん」は「歓談」の読み", "ざだんかい：「座談会」の読み。「懇」は「こん」", "えだんかい：「懇」を「え」とは読まない"], "ex": "新入社員と社長の<b>懇談会</b>が開かれた。"},
"32503": {"point": "「値する」は「あたいする」。「〜に値する」で、それだけの価値があるという意味。「値」を「ね」と読む「値段・値引き」と区別すること。", "meaning": "それだけの価値があること。", "kr": "~할 만하다, 가치가 있다", "opts": ["ねする：「値」を「ね」と読むのは「値段」など。「値する」は「あたいする」", "ちする：音読み「チ」（数値）を使った形で、誤り", "", "いこいする：「憩い」の読み。「値」の読みではない"], "ex": "この映画は一見に<b>値する</b>。"},
"32504": {"point": "「督促」は「とくそく」。「督」は「トク」（監督）、「促」は「ソク」（促進）で、濁らない。意味の近い「催促（さいそく）」と混同しないこと。", "meaning": "約束の実行、特に支払いなどを早くするように促すこと。", "kr": "독촉", "opts": ["さいぞく：「催促」と混同した形。「督」は「とく」で、「促」も濁らない", "さいそく：「催促」の読み。意味は近いが漢字が違う", "とくぞく：「促」は濁らず「そく」", ""], "ex": "家賃の支払いが遅れ、大家から<b>督促</b>状が届いた。"},
"32505": {"point": "「鑑定」は「かんてい」。「鑑」は「カン」（図鑑）、「定」は「テイ」。「定」を「ジョウ」と読む「勘定（かんじょう）」と混同しないこと。", "meaning": "美術品などの真偽・価値・良し悪しを、専門的に見きわめること。", "kr": "감정", "opts": ["かんじょう：「勘定」の読み。「定」はここでは「てい」", "", "けんじょう：「献上」の読み。「鑑」は「かん」", "けんてい：「検定」の読み。「鑑」は「かん」"], "ex": "古い掛け軸を<b>鑑定</b>してもらったところ、本物だとわかった。"},
"32506": {"point": "「傑作」は「けっさく」。「傑（ケツ）」が促音化して「けっ」、「作」は「サク」。ここでは、とてもこっけいで面白いという、くだけた意味で使われている。", "meaning": "非常にすぐれた作品。また、くだけた言い方で、とてもこっけいで面白いこと。", "kr": "걸작, 아주 웃김", "opts": ["", "けっさ：「作」はこの語では「さく」", "がっさく：「傑」は「けつ」→「けっ」", "がっさ：「傑」は「けっ」、「作」は「さく」"], "ex": "この絵は画家の晩年の<b>傑作</b>として知られている。"},
"32507": {"point": "「よい教訓となる」は、その経験から今後に役立つ教えが得られること。事件が皆にとって学びになった、という意味なので「教訓」。", "meaning": "経験から得た、今後に生かすべき教え。", "kr": "교훈", "opts": ["", "教養＝学問や知識によって身についた心の豊かさ", "啓発＝気づかなかったことを教え、理解を深めさせること。「よい啓発となる」は不自然", "触発＝刺激を受けて行動や感情が起こること（「〜に触発される」）"], "ex": "今回の失敗を<b>教訓</b>にして、次は慎重に準備しよう。"},
"32508": {"point": "「合意が得られる」は、話し合いで双方の意見が一致すること。「両者間の〜」とあるので「合意」。", "meaning": "互いの意見が一致すること。", "kr": "합의", "opts": ["集結＝一か所に集まること（「部隊が集結する」）", "適用＝規則などを当てはめること", "順応＝環境や状況に合わせて変わること", ""], "ex": "労使の間で、ようやく賃金についての<b>合意</b>が成立した。"},
"32509": {"point": "「幅広い知識」は、いろいろな分野にわたる知識。知識の範囲の広さを言うときは「幅広い」を使う。", "meaning": "範囲が広く、いろいろな方面にわたっている。", "kr": "폭넓다", "opts": ["", "分厚い＝厚みがある（「分厚い本」）。知識には使わない", "広大な＝面積が広くて大きい（「広大な土地」）。知識には使わない", "重厚な＝重々しく落ち着いている（「重厚な建物」）"], "ex": "彼は<b>幅広い</b>分野に興味を持っている。"},
"32510": {"point": "「条件に該当する」は、ある条件や項目に当てはまること。「次の条件に〜する場合」とあるので「該当」。", "meaning": "ある条件・項目などに当てはまること。", "kr": "해당", "opts": ["適応＝環境などに合うように変わること（「新しい環境に適応する」）。条件に当てはまる意味はない", "相当＝ある価値や程度に見合うこと（「1万円相当の品」）。条件には「該当」", "順応＝環境や状況に慣れて合わせること。条件に当てはまる意味はない", ""], "ex": "<b>該当</b>する項目に丸をつけてください。"},
"32511": {"point": "「非を暴く」は、相手の悪い点や過ちを明らかにすること。「非」は、正しくないこと・過ち。友人の過ちを明らかにするのはつらかった、という文脈に合う。", "meaning": "正しくないこと。あやまち。", "kr": "잘못, 허물", "opts": ["悪＝よくないこと。「悪を暴く」は不自然で、「悪事を暴く」となる", "", "苦＝苦しみ。暴くものではない", "没＝しずむ、ない。単独では使わない"], "ex": "彼は自分の<b>非</b>を認めて、みんなに謝った。"},
"32512": {"point": "「心細い」は、頼るものがなく不安な気持ち。雨で空が薄暗い、という状況で感じる気持ちとして合うのは「心細い」。", "meaning": "頼りになるものがなくて不安な様子。", "kr": "불안하다, 허전하다", "opts": ["かすかな＝わずかに感じられる（「かすかな音」）。気持ちの種類を表さない", "ひそかな＝人に知られないようにする（「ひそかな楽しみ」）", "", "心無い＝思いやりがない（「心無い言葉」）"], "ex": "知らない町で道に迷い、とても<b>心細かった</b>。"},
"32513": {"point": "「落ち着きを取り戻す」は、乱れていた気持ちが元の静かな状態に戻ること。コーヒーを飲んで落ち着いた、という意味なので「取り戻した」。", "meaning": "一度失ったものを、再び自分のものにする。", "kr": "되찾다", "opts": ["受け入れた＝人や意見などを受け取って認めること", "", "呼び込んだ＝客などを声をかけて招き入れること", "引き寄せた＝近くへ引いてくること"], "ex": "休養を取って、彼はすっかり元気を<b>取り戻した</b>。"},
"32514": {"point": "「端的に」は要点をはっきりと表す様子。グラフが気象異変をはっきり示している、ということなので「明白に」。", "meaning": "要点をはっきり、手短に表す様子。", "kr": "단적으로, 명백하게", "opts": ["主に＝大部分は、中心として", "大げさに＝実際より大きく", "", "部分的に＝一部分だけ"], "ex": "この数字が不況の深刻さを<b>端的に</b>物語っている。"},
"32515": {"point": "「鼻にかける」は自分の長所などを得意になって自慢すること。美人であることを自慢している、ということなので「自慢して」。", "meaning": "得意になって自慢する。", "kr": "뽐내다, 자랑하다, 코가 높다", "opts": ["張りあって＝互いに負けまいと競って", "打ち込んで＝一つのことに熱中して", "", "誇張して＝実際より大げさに表して。自慢とは違う"], "ex": "彼は有名大学の出身であることを<b>鼻にかけて</b>いる。"},
"32516": {"point": "「かねて」は「以前から、前もって」という意味。前もって知らせたとおり、ということなので「まえもって」。", "meaning": "以前から。前もって。", "kr": "미리, 전부터", "opts": ["ふたたび＝もう一度", "", "ほとんど＝大部分", "どうしても＝どんなにしても"], "ex": "<b>かねて</b>から希望していた部署に異動が決まった。"},
"32517": {"point": "「あるいは」は二つのうちどちらか一方であることを表す。今夜か明朝のどちらか、ということなので「または」。", "meaning": "または。もしくは。", "kr": "또는, 혹은", "opts": ["もしも＝仮に（〜なら）", "そのまま＝その状態で", "", "たしか＝はっきりしないが、たぶん"], "ex": "申し込みは電話<b>あるいは</b>メールで受け付けます。"},
"32518": {"point": "「ささいな」は取り上げるほどでもない、わずかな様子。小さなことが大事件に発展する、ということなので「小さな」。", "meaning": "取るに足りない、わずかな。", "kr": "사소한", "opts": ["重要な＝大切な。反対の意味", "深刻な＝事態が重大で厳しい。反対の意味", "新たな＝新しい", ""], "ex": "<b>ささいな</b>ことで夫婦げんかになった。"},
"32519": {"point": "「淡い」はここでは気持ちが強くなくほのかな様子。「淡い恋心」はほのかな、かすかな恋心なので「わずかな」が最も近い。", "meaning": "色・味・気持ちなどが薄く、かすかな様子。", "kr": "엷은, 희미한, 어렴풋한", "opts": ["みじめな＝情けなく哀れな", "ひそかな＝人に知られないようにする様子。隠す意味で、程度の薄さではない", "", "たんする＝このような語はない"], "ex": "空が<b>淡い</b>ピンク色に染まっていた。"},
"32520": {"point": "「規制」は、規則によって行動や活動を制限すること。主に法律・行政による制限に使い、「交通規制」「輸入規制」のように使う。③が正しい。", "meaning": "規則によって行動などを制限すること。", "kr": "규제", "opts": ["個人が量を減らす意味はない → ３キロに減らした", "範囲に閉じ込める意味は「限定」 → 狭い範囲に限定されている（限られている）", "", "小さくとどめる意味は「抑える」 → 最小限に抑える（食い止める）"], "ex": "マラソン大会の当日は、周辺道路で交通<b>規制</b>が行われる。"},
"32521": {"point": "「帯びる」は、ある性質・様子・雰囲気をうっすらと持つこと。「現実味を帯びる」「赤みを帯びる」の形で使う。①が正しい。", "meaning": "ある性質や様子を含み持つ。", "kr": "띠다", "opts": ["", "拍手などを受けるのは「浴びる」 → 拍手を浴びて", "うらみを持つのは「抱く」 → うらみを抱く者", "家庭を構えるのは「持つ」 → 家庭を持っている"], "ex": "夕焼けで、空が赤みを<b>帯びて</b>きた。"},
"32522": {"point": "「没頭」は、他のことを忘れて一つのことに熱中すること。④の「すべてを忘れて没頭できるもの」が正しい。", "meaning": "他を忘れて一つのことに熱中すること。", "kr": "몰두", "opts": ["治療に集中する意味は「専念」 → 治療に専念してほしい", "生活の様子を表す語ではない → 充実した生活", "感情にひたるのは「浸る」 → 充実感に浸った", ""], "ex": "彼は研究に<b>没頭</b>して、食事も忘れることがある。"},
"32523": {"point": "「耐えがたい」は、我慢できないほどつらい様子。「耐えがたい暑さ」「耐えがたい苦痛」のように使う。①が正しい。", "meaning": "我慢できないほど、つらい。", "kr": "견디기 어렵다", "opts": ["", "声の様子を表す語ではない → ひどく苦しそうな（弱々しい）声", "驚きの程度を強める語ではない → ひどく（とても）驚いた", "程度が極端な様子は「はなはだしい」 → 不注意もはなはだしい"], "ex": "工事の騒音は、住民にとって<b>耐えがたい</b>ものだった。"},
"32524": {"point": "「退く（しりぞく）」は、後ろへ下がること、また地位や職から離れること。④の長年勤めた職場を去る、が正しい。", "meaning": "後ろへ下がる。地位や職から身を引く。", "kr": "물러나다, 은퇴하다", "opts": ["やめる・こりごりだの意味では使わない → 犠牲にするのはやめた（もうこりごりだ）", "数値を上回る意味は「超える」 → 80キロを超えていた", "毎日続ける意味は「欠かさず」 → １日も欠かさず", ""], "ex": "社長は今年度限りで経営の第一線から<b>退く</b>ことになった。"},
"32525": {"point": "「復旧」は、壊れた設備や施設などを元の状態に戻すこと。「道路を復旧する」「電気が復旧する」のように使う。①が正しい。", "meaning": "壊れたものを元の状態に戻すこと。", "kr": "복구", "opts": ["", "中断したものを再び始めるのは「再開」 → 試合が再開した", "元の地位に戻るのは「復帰」 → 現役に復帰した", "仲の回復は「仲直り」 → あっという間に仲直りする"], "ex": "地震で止まった電車は、夕方には<b>復旧</b>した。"},
"32531": {"point": "「架空」は「かくう」。「架」は「カ」（架橋）で濁らず、「空」は長音の「クウ」。想像で作り出したもののこと。", "meaning": "事実に基づかず、想像で作り出したこと。", "kr": "가공, 허구", "opts": ["", "がくう：「架」は濁らず「か」", "かこう：「空」は「くう」。「かこう」は「加工・下降」の読み", "がこう：「架」は「か」、「空」は「くう」"], "ex": "この小説に出てくる町は<b>架空</b>の場所だ。"},
"32532": {"point": "「蓄える」は「たくわえる」。お金や物を将来のためにためておくこと。音読みは「チク」（貯蓄・蓄積）。", "meaning": "お金や物を、将来のためにためておくこと。", "kr": "저축하다, 비축하다", "opts": ["たずさえて＝携えて。「蓄」の読みではない", "", "そなえて＝備えて。「蓄」の読みではない", "かかえて＝抱えて。「蓄」の読みではない"], "ex": "冬に備えて、食料を<b>蓄えて</b>おく。"},
"32533": {"point": "「随時」は「ずいじ」。「随」は「ズイ」（随筆・随分）と濁って読む。必要なときにはいつでも、という意味。", "meaning": "必要なときにはいつでも。その時々に応じて。", "kr": "수시로", "opts": ["しゅうじ：「習字」の読み。「随」は「ずい」", "じゅうじ：「従事」の読み。「随」は「ずい」", "すいじ：「随」は濁って「ずい」。「すいじ」は「炊事」の読み", ""], "ex": "入会の申し込みは<b>随時</b>受け付けています。"},
"32534": {"point": "「漂う」は「ただよう」。空中や水面にふわふわと浮かぶこと、においや雰囲気がその場に満ちていること。音読みは「ヒョウ」（漂流）。", "meaning": "空中や水面にふわふわと浮かんで動くこと。また、においや雰囲気がその場に満ちていること。", "kr": "떠돌다, 감돌다", "opts": ["うるおって＝潤って。「漂」の読みではない", "", "さまよって＝あてもなく歩き回って。「漂」の読みではない", "さからって＝逆らって。「漂」の読みではない"], "ex": "会議室には重苦しい空気が<b>漂って</b>いた。"},
"32535": {"point": "「秀逸」は「しゅういつ」。「秀」は長音の「シュウ」（優秀）、「逸」は「イツ」（逸話）。他より抜きんでて優れていること。", "meaning": "他より抜きんでて優れていること。", "kr": "빼어남, 탁월함", "opts": ["", "しゅういち：「逸」は「いつ」", "しゅいつ：「秀」は長音で「しゅう」", "しゅいち：「秀」は「しゅう」、「逸」は「いつ」"], "ex": "彼の論文は着眼点が<b>秀逸</b>だと評価された。"},
"32536": {"point": "「隆盛」は「りゅうせい」。「隆」は長音の「リュウ」（隆起）、「盛」は「セイ」（全盛）。「盛」を「ジョウ」と読む「繁盛（はんじょう）」と混同しないこと。", "meaning": "勢いが盛んで、栄えていること。", "kr": "융성", "opts": ["りゅうじょう：「盛」を「じょう」と読むのは「繁盛」など。この語は「せい」", "りゅじょう：「隆」は長音で「りゅう」、「盛」は「せい」", "", "りゅせい：「隆」は長音で「りゅう」"], "ex": "江戸時代、この港町は貿易で<b>隆盛</b>を誇った。"},
"32537": {"point": "「自白を強制される」は、無理に自白させられること。被告が、自白は警察に無理にさせられたものだ、と主張しているので「強制」。", "meaning": "力によって無理にさせること。", "kr": "강제", "opts": ["圧倒＝ずば抜けた力で相手を押さえつけること（「相手を圧倒する」）。自白には使わない", "束縛＝行動の自由を制限すること。「自白を束縛される」とは言わない", "", "固執＝自分の考えを強く守ってゆずらないこと"], "ex": "参加は自由で、誰にも<b>強制</b>はしない。"},
"32538": {"point": "「センスのよさ」は、物事の微妙な点を感じとる感覚・才能がすぐれていること。マーケティングの才能について言うので「センス」。", "meaning": "物事の微妙な感じを感じとる能力。", "kr": "센스, 감각", "opts": ["", "クレーム＝苦情。「よさ」とは結びつかない", "ステップ＝段階、足の運び", "ニュアンス＝微妙な意味合い"], "ex": "彼女は服の<b>センス</b>がいいので、いつもおしゃれだ。"},
"32539": {"point": "「稼働」は、機械や工場が動いて仕事をすること。「工場は24時間体制で〜している」とあるので「稼働」。", "meaning": "機械・工場などが動いて生産すること。", "kr": "가동", "opts": ["展開＝物事を広げること、話が進んでいくこと", "起動＝機械やコンピューターを動かし始めること。24時間続く状態には使わない", "運行＝列車やバスが決まった道筋を走ること", ""], "ex": "新しい発電所が来月から<b>稼働</b>する予定だ。"},
"32540": {"point": "「報道陣」は、取材のために集まった記者やカメラマンの集団。接尾語「陣」は、ある目的で集まった人々を表す。", "meaning": "（接尾語）ある目的のために集まった人々の集団。", "kr": "진(陣), 단", "opts": ["", "網＝網の目のように張りめぐらしたもの（「通信網」）。人の集団ではない", "隊＝組織された集団（「探検隊」）。「報道隊」とは言わない", "派＝主義などを同じくする仲間（「改革派」）"], "ex": "空港には、到着した選手を待つ報道<b>陣</b>が大勢集まっていた。"},
"32541": {"point": "「被害を最小限に食い止める」は、悪いことがそれ以上広がらないように防ぐこと。台風の被害について言うので「食い止める」。", "meaning": "悪い事態がそれ以上広がらないように防ぐ。", "kr": "막다, 저지하다", "opts": ["吸い上げる＝吸って上に上げること、利益を取り上げること", "投げ出す＝放り出すこと、途中でやめること", "", "打ち切る＝途中で終わりにすること"], "ex": "消防士の活躍で、火事の延焼を<b>食い止める</b>ことができた。"},
"32542": {"point": "「へとへとに疲れる」は、ひどく疲れて力がなくなる様子。一日じゅう立ち続けだったので「へとへとに」。", "meaning": "ひどく疲れて、力がなくなった様子。", "kr": "녹초가 되어", "opts": ["ぎっしり＝すきまなく詰まっている様子", "", "すっきり＝さわやかで気持ちがいい様子。疲れとは合わない", "からからに＝すっかり乾いている様子（「のどがからからだ」）"], "ex": "マラソンを走り終えて、<b>へとへとに</b>なった。"},
"32543": {"point": "「しいて言えば」は、無理に一つ選ぶとすれば、という言い方。みんな好きだが、あえて言うとモネ、という文脈なので「しいて」。", "meaning": "無理に。あえて。", "kr": "굳이", "opts": ["よほど＝かなり、相当に（「よほど疲れていたのだろう」）", "いっそう＝さらに程度が増す様子", "いかにも＝本当にそれらしい様子", ""], "ex": "嫌いな食べ物はないが、<b>しいて</b>言えばピーマンが苦手だ。"},
"32544": {"point": "「とりわけ」は多くの中で特に、という意味。ハイキングの中でも特に秋がよい、ということなので「格別に」。", "meaning": "多くの中で特に。", "kr": "특히, 유달리", "opts": ["無性に＝むやみに、わけもなく", "大幅に＝変化の幅が大きく", "丹念に＝細かい所まで念入りに", ""], "ex": "今年の夏は、<b>とりわけ</b>暑さが厳しかった。"},
"32545": {"point": "「照会する」は不明な点を問い合わせて確かめること。経歴について教授に問い合わせてほしい、ということなので「問い合わせて」。", "meaning": "問い合わせて確かめること。", "kr": "조회하다, 문의하다", "opts": ["知らせて＝情報を伝えて。こちらから伝える意味", "申し込んで＝参加などを申し出て", "", "訪ねて＝その人の所へ行って"], "ex": "在庫の有無をメーカーに<b>照会した</b>。"},
"32546": {"point": "「案の定」は思ったとおり、予想どおりという意味。怠けていたので予想どおり落ちた、ということなので「思ったとおりに」。", "meaning": "思ったとおり。予想どおり。", "kr": "아니나 다를까, 예상대로", "opts": ["驚いたことに＝意外なことに。予想どおりとは反対", "それと同時に＝同じときに", "あいにく＝都合の悪いことに", ""], "ex": "傘を持たずに出かけたら、<b>案の定</b>雨に降られた。"},
"32547": {"point": "「思わず」はそうするつもりがないのに、ついしてしまう様子。腹が立って、つい彼をどなった、ということなので「無意識に」。", "meaning": "そのつもりはないのに。つい。", "kr": "무심코, 나도 모르게", "opts": ["思ったとおり＝予想どおり。「案の定」に当たる", "", "わざとらしく＝わざとしているようで不自然に", "十分に＝足りないところがなく"], "ex": "あまりのおかしさに、<b>思わず</b>笑ってしまった。"},
"32548": {"point": "「もろもろ（諸々）」は多くのいろいろなもの。いろいろな事情があって、ということなので「いろいろの」。", "meaning": "いろいろなもの。数多く。", "kr": "여러 가지, 제반", "opts": ["", "いかなる＝どのような", "個人的な＝その人自身に関する", "やむをえない＝しかたがない"], "ex": "引っ越しに伴う<b>もろもろの</b>手続きを済ませた。"},
"32549": {"point": "「とまどう」はどうしたらよいかわからなくて迷う、困ること。次々と出てくる要求にどう対応すべきか困った、ということなので「困った」。", "meaning": "どうしてよいかわからず、まごつく。", "kr": "당황하다, 어리둥절하다", "opts": ["驚いた＝意外なことに心が動いた。対応に迷う意味はない", "", "怖がった＝恐ろしく思った", "悔やんだ＝後悔した"], "ex": "初めての海外で、習慣の違いに<b>とまどった</b>。"},
"32550": {"point": "「抱え込む」は、物を腕に抱く、また問題や仕事を自分一人で背負うこと。②の悩み事を一人で抱え込む、が正しい。", "meaning": "腕に抱く。問題や仕事を一人で背負い込む。", "kr": "떠안다, 혼자 끌어안다", "opts": ["体力が続く意味は「持つ」 → 体が持たない", "", "見つける意味は「発見する」 → 遺体はまだ発見されていない（収容されていない）", "要求を認める意味は「受け入れる」 → 要求を受け入れる"], "ex": "彼は仕事を一人で<b>抱え込んで</b>、体を壊してしまった。"},
"32551": {"point": "「入手」は、物や情報を手に入れること。「情報を入手する」「入手経路」のように使う。③が正しい。", "meaning": "物や情報を手に入れること。", "kr": "입수", "opts": ["人から贈られる場合は「もらう」 → プレゼントをもらった", "努力して得るのは「勝ち取る」 → 自由を勝ち取った", "", "許可は「得る」「取る」 → 許可を得なければ"], "ex": "限定版のチケットをようやく<b>入手</b>した。"},
"32552": {"point": "「見落とす」は、見ていながら気づかずに見過ごすこと。③の監督のサインに気づかなかった、が正しい。", "meaning": "見ていながら気づかずに過ごす。", "kr": "못 보고 넘기다, 간과하다", "opts": ["注意して見守るのは「見張る」 → 見張っていてください", "自分の本来の姿や目指すものがわからなくなるのは「見失う」 → 自分自身を見失った", "", "先を予測するのは「見通す」 → ５年先を見通す"], "ex": "メールの大事な一文を<b>見落として</b>いた。"},
"32553": {"point": "「一律に」は、すべてを同じ基準・同じ扱いにする様子。「一律に無料化する」「一律に値上げする」のように使う。②が正しい。", "meaning": "すべてを同じ扱いにする様子。", "kr": "일률적으로", "opts": ["一度にまとめて出る様子は「どっと」 → 疲れがどっと出て", "", "「都合が悪くなるといつも」という癖は「すぐに」「決まって」で表す。「一律に」は全部を同じに扱う意味 → すぐに人のせいにする", "広く行き渡る様子は「広く」 → 広く（一般に）普及した"], "ex": "全社員の給料が<b>一律に</b>３パーセント上がった。"},
"32554": {"point": "「はなはだしい」は、程度が非常に激しい様子。主に好ましくないことに使い、「誤解もはなはだしい」「はなはだしく傷つく」のようにいう。③が正しい。", "meaning": "（好ましくないことの）程度が非常に激しい。", "kr": "심하다, 지나치다", "opts": ["よい活躍を褒めるときには使わない → めざましい活躍", "難しさを表す語ではない → かなり難しい（大変だ）", "", "よい活躍には使わない → めざましい（すばらしい）活躍"], "ex": "それは私への誤解も<b>はなはだしい</b>。"},
"32555": {"point": "「還元」は、得たものを元の所へ返すこと。「利益を社会に還元する」のように使う。④が正しい。", "meaning": "得たものを元に返すこと。", "kr": "환원", "opts": ["料金を返すのは「払い戻し」 → 料金の払い戻し（返金）", "数量が減るのは「減少」 → 30パーセント減少した", "元の状態に戻るのは「回復」 → 景気が回復する", ""], "ex": "売り上げの一部をポイントとして客に<b>還元</b>している。"},
"32561": {"point": "「虚構」は「きょこう」。「虚」は「キョ」（虚偽）、「構」は「コウ」（構造）で、どちらも濁らない。事実でないことを作り上げること。", "meaning": "事実ではないことを、事実らしく作り上げること。フィクション。", "kr": "허구", "opts": ["きょごう：「構」は濁らず「こう」", "ぎょごう：「虚」は「きょ」、「構」は「こう」で、どちらも濁らない", "", "ぎょこう：「虚」は濁らず「きょ」。「ぎょこう」は「漁港」の読み"], "ex": "この映画は実話ではなく、すべて<b>虚構</b>の物語だ。"},
"32562": {"point": "「臨む」は「のぞむ」。「記者会見に臨む」のように、重要な場面に出ること。同じ音の「望む」と使い分ける。音読みは「リン」（臨時）。", "meaning": "重要な場面や場所に出ること。また、ある場所に面すること。", "kr": "임하다, 면하다", "opts": ["はげんだ＝励んだ。「臨」の読みではない", "いどんだ＝挑んだ。意味は近いが「挑」の読み", "からんだ＝絡んだ。「臨」の読みではない", ""], "ex": "選手たちは万全の準備で決勝戦に<b>臨んだ</b>。"},
"32563": {"point": "「陳列」は「ちんれつ」。「陳」は「チン」（陳述・陳謝）、「列」は「レツ」（行列）。品物を並べて見せること。", "meaning": "人に見せるため、品物を並べておくこと。", "kr": "진열", "opts": ["", "しんれつ：「陳」は「ちん」", "ちんれい：「列」は「れつ」。「れい」は「例」などの読み", "しんれい：「陳」は「ちん」、「列」は「れつ」"], "ex": "博物館には古代の土器が<b>陳列</b>されている。"},
"32564": {"point": "「索漠」は「さくばく」。「索」は「サク」（検索・思索）、「漠」は「バク」（砂漠）。「索漠たる」の形で、心が満たされずもの寂しい様子を表す。", "meaning": "心が満たされず、もの寂しい様子。", "kr": "삭막함", "opts": ["せきまく：「索」は「さく」、「漠」は「ばく」", "せきばく：「寂寞（せきばく）」と混同した読み。「索」は「さく」", "さくまく：「漠」は「ばく」", ""], "ex": "都会の<b>索漠</b>とした暮らしに疲れ、田舎に移り住んだ。"},
"32565": {"point": "「痛罵」は「つうば」。「痛」は「ツウ」（痛烈）、「罵」は「バ」（罵倒・罵声）。激しくののしること。", "meaning": "激しくののしること。", "kr": "통렬한 매도, 호된 욕", "opts": ["", "つうは：「罵」は濁って「ば」", "うつばい：「痛」は「つう」、「罵」は「ば」", "つうはい：「罵」は「ば」と読み、「はい」とは読まない"], "ex": "彼は会議で部下の失敗を人前で<b>痛罵</b>した。"},
"32566": {"point": "「萌芽」は「ほうが」。「萌」は音読みで「ホウ」（訓は「もえる」）、「芽」は「ガ」（発芽）。物事の始まり・きざしの意味でよく使う。", "meaning": "草木の芽が出ること。転じて、物事の始まり・きざし。", "kr": "맹아, 싹", "opts": ["ほうげ：「芽」は「が」", "", "もうげ：「萌」は「ほう」、「芽」は「が」", "もうが：「萌」は「ほう」と読み、「もう」とは読まない"], "ex": "この時代の作品には、近代文学の<b>萌芽</b>が見られる。"},
"32567": {"point": "「感情の起伏が激しい」は、気分が上がったり下がったりする変化が大きいこと。「感情の〜が激しい」と結びつくのは「起伏」。", "meaning": "高くなったり低くなったりすること。感情などの変化。", "kr": "기복", "opts": ["高低＝高さの違い（「音の高低」）。感情には使わない", "出没＝現れたり隠れたりすること（「クマが出没する」）", "", "明暗＝明るさと暗さ、幸と不幸（「明暗を分ける」）"], "ex": "彼女は感情の<b>起伏</b>が激しく、さっきまで笑っていたのに急に怒り出した。"},
"32568": {"point": "「もっぱら」は、他のことはせず、そのことばかりする様子。休日の時間をほとんどゴルフの練習に使った、という意味なので「もっぱら」。", "meaning": "そのことばかりに集中する様子。", "kr": "오로지, 주로", "opts": ["", "しきりに＝何度も繰り返して（「しきりに時計を見る」）", "ますます＝前よりいっそう", "せめて＝少なくとも（「せめて一日だけでも」）"], "ex": "最近は<b>もっぱら</b>家で映画を見て過ごしている。"},
"32569": {"point": "「問題に直面する」は、困難な問題に直接向き合うこと。「〜している問題」とあるので「直面」。", "meaning": "ある物事・事態に直接向き合うこと。", "kr": "직면", "opts": ["近接＝すぐ近くにあること", "対面＝顔と顔を合わせること（「初対面」）。問題には使わない", "", "隣接＝となり合っていること（「隣接する町」）"], "ex": "その会社は深刻な経営危機に<b>直面</b>している。"},
"32570": {"point": "「最善を尽くす」は、できる限りのことをすべて行うこと。決まった組み合わせで「尽くした」。", "meaning": "（「最善を尽くす」で）できる限りのことをする。", "kr": "다하다", "opts": ["果たした＝役目や約束をやり遂げる（「責任を果たす」）。「最善を果たす」とは言わない", "", "極めた＝最後まで究める（「頂上を極める」）。「最善を極める」とは言わない", "遂げた＝目的をなしとげる（「成長を遂げる」）。「最善を遂げる」とは言わない"], "ex": "結果はだめだったが、全力を<b>尽くした</b>ので後悔はない。"},
"32571": {"point": "「ノルマ」は、一定の期間内に果たすよう割り当てられた仕事の量。「取り締まりの〜が課されている」とあるので「ノルマ」。", "meaning": "個人や集団に割り当てられた仕事の量。", "kr": "할당량", "opts": ["チーフ＝主任、責任者", "コスト＝費用", "", "キャリア＝経歴"], "ex": "営業部員には毎月の販売<b>ノルマ</b>がある。"},
"32572": {"point": "「人込みにまぎれる」は、多くの人の中に入り込んで区別がつかなくなること。少年が見えなくなった、という意味なので「まぎれて」。", "meaning": "他のものに入りまじって、区別がつかなくなる。", "kr": "섞이다, 뒤섞이다", "opts": ["なじんで＝慣れて親しむ（「新しい環境になじむ」）", "からんで＝巻きつく、関係する", "おさまって＝中にきちんと入る、静かになる", ""], "ex": "犯人は夜の闇に<b>まぎれて</b>逃げた。"},
"32573": {"point": "「すさまじい勢い」は、恐ろしいほど激しい勢い。知らせを聞いてすぐに飛び出した様子なので「すさまじい」。", "meaning": "恐ろしいほど程度が激しい様子。", "kr": "무시무시하다, 굉장하다", "opts": ["いさましい＝勇気があって元気がいい。「勢い」の激しさを表さない", "", "やかましい＝うるさい、口うるさい", "あわただしい＝落ち着かず忙しい。「あわただしい勢い」とは言わない"], "ex": "台風が<b>すさまじい</b>勢いで町を通過していった。"},
"32574": {"point": "「往来」はここでは人や車が行き来する道の意味。道の真ん中でけんかをするな、ということなので「道路」。", "meaning": "人や車が行き来すること。また、その道。", "kr": "길거리, 한길, 왕래", "opts": ["", "広場＝人が集まれる広く開けた場所", "公園＝人々が休んだり遊んだりする場所", "跡地＝建物などがなくなった後の土地"], "ex": "子どもたちが<b>往来</b>でボール遊びをしていて危ない。"},
"32575": {"point": "「フォローする」は人の足りないところを補って助けること。社長や先輩が自分を補い助けてくれた、ということなので「助けて」。", "meaning": "足りないところを補って助けること。", "kr": "도와주다, 뒷받침하다", "opts": ["援助して＝お金や物などで助けて。補う意味が弱い", "救助して＝危険な状態から救い出して", "", "教えて＝知識や技術を伝えて"], "ex": "ミスをしたが、同僚がすぐに<b>フォローして</b>くれた。"},
"32576": {"point": "「かろうじて」はやっとのことで、何とか、という意味。法案がぎりぎり過半数を得た、ということなので「何とか」。", "meaning": "やっとのことで。ぎりぎりで。", "kr": "간신히, 겨우", "opts": ["", "なぜか＝理由はわからないが", "すぐに＝時間をおかずに", "たまたま＝偶然に"], "ex": "終電に<b>かろうじて</b>間に合った。"},
"32577": {"point": "「そわそわ」は気になることがあって落ち着かない様子。面接を前に落ち着かない、ということなので「緊張して」が最も近い。", "meaning": "気になることがあって、落ち着かない様子。", "kr": "안절부절못하다, 들썩들썩", "opts": ["感動して＝深く心を動かされて", "", "振動して＝揺れ動いて。物理的な揺れの意味", "出張している＝仕事でよそへ出かけている"], "ex": "発表を待つ間、彼は朝から<b>そわそわして</b>いる。"},
"32578": {"point": "「けげん（怪訝）な」はわけがわからず、不思議に思う様子。花束を渡されて不思議そうな顔をした、ということなので「疑わしい」が最も近い。", "meaning": "わけがわからず、不思議に思う様子。", "kr": "의아한, 이상하다는 듯한", "opts": ["面倒くさい＝手間がかかって嫌だ", "不愉快な＝嫌な気持ちがする。不思議に思う意味はない", "", "機嫌よい＝気分がよい"], "ex": "突然話しかけると、彼は<b>けげんな</b>顔でこちらを見た。"},
"32579": {"point": "「プロセス」は物事が進んでいく道筋・途中の段階。実験の途中の段階で問題点がわかった、ということなので「過程」。", "meaning": "物事が進む道筋。過程。", "kr": "과정, 프로세스", "opts": ["証明＝正しいことを明らかにすること", "結果＝最後に出た状態。過程とは反対", "装置＝ある目的のために備えつけた機械や道具", ""], "ex": "結果だけでなく、そこに至る<b>プロセス</b>も大切だ。"},
"32580": {"point": "「安静」は、病気やけがの回復のため、体を動かさず静かに休んでいること。「安静にする」の形で使う。②が正しい。", "meaning": "体を動かさず静かに休むこと。", "kr": "안정 (휴식)", "opts": ["落ち着いて判断するのは「冷静」 → 冷静な判断", "", "住む環境が静かなのは「閑静」 → 閑静で暮らしやすい", "変化がなく落ち着いているのは「安定」 → 安定した仕事"], "ex": "医者から一週間は<b>安静</b>にするように言われた。"},
"32581": {"point": "「はがす」は、表面に貼りついている物を取り去ること。「ラベルをはがす」「シールをはがす」のように使う。④が正しい。", "meaning": "貼りついている物を取り去る。", "kr": "벗기다, 떼다", "opts": ["歴史の新しい展開は「開く」「加える」 → 新たな１ページを開いた（加えた）", "めがねは「かける」 → めがねをかけないと", "果物の皮は「むく」 → りんごの皮をむいて", ""], "ex": "壁に貼ってあったポスターを<b>はがした</b>。"},
"32582": {"point": "「素早い」は、動作や反応がとても速い様子。主に人の動き・対応に使う。②の素早く対応した、が正しい。", "meaning": "動作や反応がとても速い。", "kr": "재빠르다, 날쌔다", "opts": ["時間がたたずに、の意味は「すぐに」 → すぐに（早晩）すたれる", "", "発展の速さは「急速に」 → 最も急速に発展し", "前ぶれなく、の意味は「突然」「急に」 → 音楽が突然やんで"], "ex": "彼は<b>素早く</b>ボールを拾って、味方にパスした。"},
"32583": {"point": "「今更」は、今になってから、もう時機が遅いという気持ち。「今更〜まで（も）ない」「今更言っても遅い」のように使う。④が正しい。", "meaning": "今になって。もう遅いという気持ち。", "kr": "새삼스럽게, 이제 와서", "opts": ["今もまだ続く意味は「いまだに」 → いまだに内戦の傷跡が残っている", "すぐにも起こりそうな様子は「今にも」 → 今にも倒れそうな", "現在も変わらない意味は「依然として」 → 依然として（いまだに）女性の昇進は難しい", ""], "ex": "<b>今更</b>謝られても、もう遅い。"},
"32584": {"point": "「もはや」は、事態が変化して、もう今となっては、という意味。「もはや〜ない」「もはや手遅れだ」のように使う。④が正しい。", "meaning": "今となっては、もう。", "kr": "이미, 이제는", "opts": ["過去を表す語ではない → 以前は（かつて）桜の並木があった", "過去の状態を表す語ではない → かつて（以前は）高校教師だった", "「もはや」は「今となってはもう」の意味で、今すぐ行動を求める場面には使わない → 今すぐ（ただちに）この場で", ""], "ex": "ここまで来たら、<b>もはや</b>引き返すことはできない。"},
"32585": {"point": "「統合」は、いくつかのものを一つにまとめ合わせること。「経済統合」「組織を統合する」のように使う。①が正しい。", "meaning": "複数のものを一つにまとめ合わせること。", "kr": "통합", "opts": ["", "色を揃えるのは「統一」 → 焦げ茶系の色に統一しても", "人と落ち合うのは「合流」 → 彼と１時間後に合流する", "費用を足すのは「合計」 → 費用を合計してみた"], "ex": "二つの部署を<b>統合</b>して、新しい部を作った。"},
"32591": {"point": "「啓発」は「けいはつ」。「啓」は「ケイ」（拝啓）、「発」は「ハツ」。前が「い」で終わるので半濁音にならない（「出発（しゅっぱつ）」とは違う）。", "meaning": "知識を与えて、人を新しい考えや理解に導くこと。", "kr": "계발, 깨우침", "opts": ["", "けいぱつ：「発」は半濁音にならず「はつ」", "かいはつ：「開発」の読み。「啓」は「けい」", "かいぱつ：「啓」は「けい」、「発」は「はつ」"], "ex": "友人の生き方に<b>啓発</b>されて、ボランティアを始めた。"},
"32592": {"point": "「沈潜」は「ちんせん」。「沈」は「チン」（沈黙）、「潜」は「セン」（潜水）。ここでは、一つのことに深く没頭するという意味。", "meaning": "水の底深く沈むこと。転じて、一つのことに深く没頭すること。", "kr": "침잠, 몰두", "opts": ["しんせん：「沈」は「ちん」。「しんせん」は「新鮮」の読み", "しんさん：「辛酸」の読み。「沈」は「ちん」、「潜」は「せん」", "", "ちんさん：「潜」は「せん」"], "ex": "彼は研究に<b>沈潜</b>し、何年も論文を書き続けた。"},
"32593": {"point": "「拒む」は「こばむ」。相手の要求や申し出を受け入れず、断ること。音読みは「キョ」（拒否・拒絶）。", "meaning": "相手の要求や申し出を受け入れず、断ること。", "kr": "거부하다, 거절하다", "opts": ["うらんだ＝恨んだ。「拒」の読みではない", "おがんだ＝拝んだ。「拒」の読みではない", "にくんだ＝憎んだ。「拒」の読みではない", ""], "ex": "容疑者は質問に答えることを<b>拒んだ</b>。"},
"32594": {"point": "「華やか」は「はなやか」。「華」を訓読みの「はな」と読む。明るく美しく人目を引く様子。音読みは「カ」（豪華）。", "meaning": "明るく美しく、人目を引く様子。", "kr": "화려하다", "opts": ["あざやかな＝鮮やかな。「華」の読みではない", "", "なごやかな＝和やかな。「華」の読みではない", "かろやかな＝軽やかな。「華」の読みではない"], "ex": "パーティー会場は<b>華やかな</b>ドレスの女性たちでいっぱいだった。"},
"32595": {"point": "「脈絡」は「みゃくらく」。「脈」は「ミャク」（山脈）、「絡」は「ラク」（連絡）。物事の筋道やつながりのこと。", "meaning": "物事の筋道やつながり。", "kr": "맥락", "opts": ["びゃくりゃく：「脈」は「みゃく」、「絡」は「らく」", "びゃくらく：「脈」は「みゃく」", "みゃくりゃく：「絡」は「らく」。「りゃく」は「略」の読み", ""], "ex": "彼の話は<b>脈絡</b>がなく、何を言いたいのかわからない。"},
"32596": {"point": "「淡い」は「あわい」。色や味が薄い様子、気持ちがかすかな様子。音読みは「タン」（冷淡・淡水）。形の似た「浅い（あさい）」と混同しないこと。", "meaning": "色や味などが薄い様子。また、光や気持ちなどがかすかである様子。", "kr": "옅다, 희미하다", "opts": ["", "きよい＝清い。「淡」の読みではない", "あさい＝浅い。形が似ているが別の字", "はかない＝儚い。「淡」の読みではない"], "ex": "彼女は初恋の<b>淡い</b>思い出を語った。"},
"32597": {"point": "「犯罪の抑止」は、悪いことが起こらないように抑えて止めること。罰則の強化が犯罪を防ぐ効果を持つ、という意味なので「抑止」。", "meaning": "抑えて止めること。", "kr": "억지, 억제", "opts": ["抑揚＝声や文章の調子の上がり下がり", "", "予期＝前もって予想して待つこと", "予測＝前もって推し量ること"], "ex": "防犯カメラには犯罪を<b>抑止</b>する効果がある。"},
"32598": {"point": "「おおらかな性格」は、小さなことにこだわらず、ゆったりとした性格。「明るく」「毎日楽しく」と合うのは「おおらかな」。", "meaning": "心がゆったりとしていて、小さなことにこだわらない様子。", "kr": "대범하다, 너그럽다", "opts": ["", "あざやかな＝色や形がはっきりして美しい、手際がよい", "ささやかな＝規模が小さくつつましい（「ささやかな贈り物」）", "すみやかな＝すばやい（「すみやかに対応する」）"], "ex": "彼は<b>おおらかな</b>人で、小さな失敗はまったく気にしない。"},
"32599": {"point": "「データが流出する」は、情報などが外部に漏れ出ること。顧客データについて言うので「流出」。", "meaning": "中にあるものが外部へ出ること。", "kr": "유출", "opts": ["転向＝立場や考えを変えること", "展開＝広げること、物事が進むこと", "発散＝内にこもったものを外に出すこと（「ストレスを発散する」）", ""], "ex": "会社の機密情報が外部に<b>流出</b>した。"},
"32600": {"point": "「くよくよする」は、小さなことをいつまでも気にして悩むこと。「病気になるよ」と注意しているので「くよくよ」。", "meaning": "小さなことをいつまでも気にして、思い悩む様子。", "kr": "끙끙 앓다, 연연하다", "opts": ["ふんわり＝柔らかくふくらんだ様子", "ひっそり＝静かで人の気配がない様子", "のろのろ＝動作が遅い様子", ""], "ex": "終わったことを<b>くよくよ</b>しても仕方がない。"},
"32601": {"point": "「法案が可決される」は、会議で提出された案をよいと認めて決めること。「圧倒的多数で」とあるので「可決」。", "meaning": "会議で、議案をよいと認めて決めること。", "kr": "가결", "opts": ["選出＝選び出すこと。人に使う", "", "採取＝研究などのために取ること（「指紋を採取する」）", "判別＝見分けること"], "ex": "予算案は賛成多数で<b>可決</b>された。"},
"32602": {"point": "「卓越する」は、他よりはるかにすぐれていること。雄弁家としてすぐれている、という意味なので「卓越」。", "meaning": "他よりはるかにすぐれていること。", "kr": "탁월하다", "opts": ["没頭＝一つのことに夢中になること", "露呈＝隠れていたことが表に現れること（「弱点が露呈する」）", "", "装飾＝飾ること"], "ex": "彼は<b>卓越</b>した技術を持つ職人として知られている。"},
"32603": {"point": "「話を切り出す」は、言いにくい話を始めること。別れ話をどう始めればいいかわからない、という意味なので「切り出して」。", "meaning": "話を始める。特に、言いにくい話を口に出す。", "kr": "말을 꺼내다", "opts": ["", "割り当てて＝全体をいくつかに分けて配ること", "押し込んで＝無理に中に入れること", "持ち上げて＝上にあげること、人をおだてること"], "ex": "上司に転勤の話をどう<b>切り出そう</b>か迷っている。"},
"32604": {"point": "「手本」はここでは見習うべき行いや人の意味。子どもに見習うべきよい行いを示す、ということなので「模範」。", "meaning": "見習うべき物事や人。模範。", "kr": "본보기, 모범", "opts": ["方法＝目的のためのやり方", "", "手順＝物事を行う順序", "見本＝主に商品の質などを示すための品物（サンプル）。見習うべき行いという意味では「模範」のほうが近い"], "ex": "親が<b>手本</b>を見せれば、子どもも自然とあいさつをするようになる。"},
"32605": {"point": "「いかにも」はここでは「まさにそれらしい」という意味。日本人らしさがよく表れた考え方だ、ということなので「典型的に」。", "meaning": "まさにそれらしい様子。", "kr": "정말 ~답게, 전형적으로", "opts": ["具体的に＝はっきりした形や内容を備えて", "全体的に＝全体として", "", "一般的に＝広く普通に"], "ex": "<b>いかにも</b>学者らしい慎重な答え方だった。"},
"32606": {"point": "「こらえる」は苦しさや感情を外に出さずに我慢すること。眠いのを我慢して勉強した、ということなので「辛抱して」。", "meaning": "苦しさなどを我慢する。", "kr": "참다, 견디다", "opts": ["調整して＝具合よく整えて", "", "封鎖して＝出入りできないように閉ざして", "協議して＝集まって相談して"], "ex": "涙を<b>こらえて</b>、最後まで話した。"},
"32607": {"point": "「自尊心」は自分の人格や能力に誇りを持つ心。それが傷ついた、ということなので「プライド」。", "meaning": "自分の人格や能力に誇りを持つ心。", "kr": "자존심", "opts": ["", "スタイル＝体つき、型、やり方", "イメージ＝心に浮かぶ姿、印象", "コントロール＝思いどおりに操ること"], "ex": "人前で叱られて、<b>自尊心</b>を傷つけられた。"},
"32608": {"point": "「いっこうに」は否定とともに使い、「少しも〜ない」という意味。何を言われても少しも気にしない、ということなので「全然」。", "meaning": "（否定とともに）少しも。全然。", "kr": "전혀, 조금도", "opts": ["もう一度＝さらに一回", "少しずつ＝わずかずつ", "一斉に＝みんなが同時に", ""], "ex": "いくら待っても、バスは<b>いっこうに</b>来なかった。"},
"32609": {"point": "「エスカレートする」は物事の程度や規模が段階的に大きくなること。紛争がだんだん拡大していった、ということなので「段階的に拡大して」。", "meaning": "程度や規模が段階的に大きく、激しくなること。", "kr": "확대되다, 격화되다, 에스컬레이트되다", "opts": ["段階的に縮小して＝だんだん小さくなって。反対の意味", "組織的に縮小して＝組織として小さくなって", "", "組織的に拡大して＝組織としてまとまって大きくなって。「エスカレート」は「段階的に」の意味"], "ex": "最初は小さな口論だったが、次第に<b>エスカレートして</b>いった。"},
"32610": {"point": "「人一倍」は、普通の人以上に、という意味で、人の努力や感情の程度について使う。③の「人一倍努力した」が正しい。", "meaning": "普通の人よりも程度がずっと大きいこと。", "kr": "남보다 갑절, 남달리", "opts": ["物事の程度が増す意味は「一段と」 → 一段と（いっそう）楽しくなる", "数値が倍になる意味は「倍増」 → 視聴率が倍増した", "", "人の努力や気持ち以外には使わない → いつも上位に（決勝トーナメントに）進出している"], "ex": "彼女は<b>人一倍</b>負けず嫌いだ。"},
"32611": {"point": "「携わる」は、ある仕事や事柄に関係して従事すること。「経営に携わる」「研究に携わる」のように使う。④が正しい。", "meaning": "ある仕事や事柄にかかわる。従事する。", "kr": "종사하다, 관여하다", "opts": ["結果が何かになる意味はない → 大変な業績になる", "実際に行う意味は「実行」 → 実際に実行する（実現する）のは", "最後までやり通す意味は「やり抜く」 → 最後までやり抜いた", ""], "ex": "父は四十年間、教育に<b>携わって</b>きた。"},
"32612": {"point": "「軌道」は、天体や物の通る道、また物事が進む道筋・方向。「軌道に乗る」「軌道を修正する」のように使う。③が正しい。", "meaning": "物が通る道。物事の進む道筋。", "kr": "궤도", "opts": ["作業の順序は「手順」 → インストールする手順", "政府の考えの方向は「方針」 → 明確な方針", "", "目指す対象は「目標」「手本」 → 木村先生を目標に"], "ex": "新しい事業がようやく<b>軌道</b>に乗ってきた。"},
"32613": {"point": "「経緯（いきさつ・けいい）」は、物事がそうなるまでの細かな事情・成り行き。「事件の経緯」のように使う。④が正しい。", "meaning": "物事がそうなるまでの事情や成り行き。", "kr": "경위, 자초지종", "opts": ["船の進む道は「針路」「航路」 → 針路（航路）からそれないように", "製品を作る段階は「工程」 → 生産工程でのミス", "時間の使い方は「過ごし方」 → 有意義な過ごし方", ""], "ex": "会議では、計画が中止になった<b>経緯</b>が説明された。"},
"32614": {"point": "「思い詰める」は、一つのことばかりを深く考えて悩み込むこと。①の思い詰めた表情（深刻に悩んでいる顔）が正しい。", "meaning": "一つのことばかり考えて、深く悩む。", "kr": "골똘히 생각하다, 깊이 고민하다", "opts": ["", "荷物を入れる意味は「詰める」 → スーツケースに荷物を詰めた", "やめる意味は「見送る」「あきらめる」 → 購入は見送ることにした", "記憶をよみがえらせるのは「思い出す」 → はっきりと思い出す"], "ex": "一人で<b>思い詰め</b>ないで、誰かに相談してね。"},
"32615": {"point": "「心構え」は、物事に対処するための前もっての心の準備。「日頃の心構え」「受験生としての心構え」のように使う。②が正しい。", "meaning": "物事に備える、前もっての心の準備。", "kr": "마음가짐, 각오", "opts": ["相手への気配りは「心配り」 → 全宿泊客への心配り（気配り）", "", "予定・意図は「つもり」 → 勉強するつもりだった", "隠れた意図は「魂胆」「考え」 → 何か魂胆（考え）があって"], "ex": "社会人としての<b>心構え</b>を、先輩から教わった。"},
"33001": {"point": "「潔い」は訓読みで「いさぎよい」。未練がましくなく、自分の非をきっぱり認める様子。「潔」の音読みは「ケツ」（清潔・簡潔）。", "meaning": "未練がなく、思い切りがよい様子。卑怯なところがない様子。", "kr": "깨끗하다, 미련 없다, 떳떳하다", "opts": ["", "わずらわしく：「煩わしい」の読み。面倒で気が重いという意味", "すばやく：「素早い」の読み。動作が速いという意味", "しぶとく：簡単にはあきらめない様子。「潔」の読みではない"], "ex": "負けを<b>潔く</b>認めて、相手の健闘をたたえた。"},
"33002": {"point": "「釈明」は音読みで「しゃくめい」。「釈」は「シャク」（解釈・釈放）、「明」は「メイ」。誤解や非難に対して事情を説明し、理解を求めること。", "meaning": "誤解や非難に対して、自分の立場や事情を説明して理解を求めること。", "kr": "해명, 변명", "opts": ["かいめい：「解明」の読み。「釈」は「かい」とは読まない", "", "せきめい：「釈」は「せき」ではなく「しゃく」", "しょうめい：「証明」「照明」の読み。「釈」は「しょう」とは読まない"], "ex": "社長は記者会見で、不祥事について<b>釈明</b>した。"},
"33003": {"point": "「手本」は「て」（訓）＋「ほん」（音）の湯桶読みで「てほん」。見習うべき模範のこと。「手」を音読み「シュ」にしたり、「本」を「もと」と訓読みしたりしない。", "meaning": "見習うべき物事や人。模範。また、習字や絵などで写すもとにする見本。", "kr": "본보기, 모범", "opts": ["しゅほん：「手」を音読みしない。湯桶読みで「て」", "しゅもと：「手」も「本」も誤り", "", "てもと：「手元・手許」の読み。手の届く近くという別の語"], "ex": "兄はいつも弟の<b>手本</b>になるように努力している。"},
"33004": {"point": "「兆し」は訓読みで「きざし」。何かが起こりそうな前ぶれのこと。動詞「兆す（きざす）」の名詞形。音読みは「チョウ」（前兆・兆候）。", "meaning": "物事が起ころうとする前ぶれ。兆候。", "kr": "조짐, 징조", "opts": ["あかし：「証」の読み。証拠という意味", "", "しめし：「示し」の読み（「示しがつかない」）", "しるし：「印・徴」の読み。意味は近いが「兆」の読みではない"], "ex": "長い冬が終わり、ようやく春の<b>兆し</b>が感じられるようになった。"},
"33005": {"point": "「戒める」は訓読みで「いましめる」。悪いことをしないように注意する、または叱ること。音読みは「カイ」（警戒・戒律）。罰を与える「懲らしめる（こらしめる）」と混同しないこと。", "meaning": "過ちをしないように前もって注意する。また、過ちを叱る。", "kr": "훈계하다, 타이르다, 경계하다", "opts": ["", "いやしめる：「卑しめる」の読み。見下して軽んじるという意味", "くるしめる：「苦しめる」の読み", "こらしめる：「懲らしめる」の読み。罰を与えて二度としないようにさせること"], "ex": "父は、うそをついた弟を厳しく<b>戒めた</b>。"},
"33006": {"point": "「啓蒙」は音読みで「けいもう」。「啓」は「ケイ」（啓発・拝啓）、「蒙」は「モウ」。人々に正しい知識を与えて導くこと。「蒙」を「夢」の「ム」と混同しないこと。", "meaning": "知識の乏しい人々に正しい知識を与え、物事の道理を教え導くこと。", "kr": "계몽", "opts": ["かいむ：「啓」は「けい」、「蒙」は「もう」", "かいもう：「啓」は「かい」ではなく「けい」", "けいむ：「蒙」は「む」ではなく「もう」", ""], "ex": "市は、ごみの分別についての<b>啓蒙</b>ポスターを作った。"},
"33007": {"point": "「通行止め」のような規制・禁止を取りやめて元に戻すことは「解除」。「通行止めが解除される」「警報が解除される」の形でよく使う。", "meaning": "禁止・制限・契約などの措置を取りやめて、元の状態に戻すこと。", "kr": "해제", "opts": ["解消＝問題や状態がなくなること（「渋滞が解消」「ストレス解消」）。規制を取りやめる意味では「解除」が適切", "", "解体＝建物や組織をばらばらにすること（「ビルの解体」）", "解約＝契約を取り消すこと（「保険の解約」）"], "ex": "大雨警報が<b>解除</b>され、生徒たちは下校した。"},
"33008": {"point": "「催す」は会や行事を開くこと。「パーティーが盛大に催された」は受身で、パーティーが開かれたという意味。", "meaning": "（会・行事などを）計画して開く。開催する。", "kr": "개최하다, 열다", "opts": ["うちきられた＝打ち切られた。途中で終わりにされること。「盛大に」と合わない", "おだてられた＝ほめて得意にさせられた。人に使う語で、パーティーには使わない", "", "きたされた＝来された。「支障をきたす」のように悪い結果を引き起こす意味で、合わない"], "ex": "創立五十周年を記念して、ホテルで祝賀会が<b>催された</b>。"},
"33009": {"point": "「見合わせる」は、事情を見て実行をしばらく控えること。悪天候のため運航を一時取りやめている文脈なので「見合わせて」。交通機関の「運転見合わせ」「運航見合わせ」はよく使う表現。", "meaning": "事情を考えて、実行をしばらく控える。", "kr": "보류하다, 미루다, 중지하다", "opts": ["見落として＝見落とす。見ていながら気づかずにいること", "見習って＝見習う。人のすることを手本にしてまねること", "", "見渡して＝見渡す。遠くまで広く見ること"], "ex": "大雪のため、電車は一部区間で運転を<b>見合わせて</b>いる。"},
"33010": {"point": "「平静を保つ」は、心を乱さず落ち着いた状態でいること。安全運転のために気持ちを落ち着けておく、という文脈なので「平静」。", "meaning": "心が落ち着いていて、乱れていないこと。", "kr": "평정, 침착함", "opts": ["安静＝病人などが体を動かさず静かに休むこと（「絶対安静」）。運転には使わない", "閑静＝周りが静かで落ち着いている様子（「閑静な住宅街」）。場所に使う", "動静＝人や物事の動き・様子（「敵の動静を探る」）", ""], "ex": "突然の知らせにも、彼女は<b>平静</b>を装っていた。"},
"33011": {"point": "「間柄」は人と人との関係・つながり。「先輩後輩の間柄」「親子の間柄」のように、どういう関係かを表す語の後に使う。", "meaning": "人と人との関係。つきあいのつながり。", "kr": "사이, 관계", "opts": ["間近＝時間や距離がすぐ近いこと（「試験が間近だ」）", "", "身分＝社会の中での地位・立場（「身分証明書」）。二人の関係は表さない", "身柄＝その人の体そのもの（「身柄を拘束する」）"], "ex": "彼女とは、何でも話せる<b>間柄</b>だ。"},
"33012": {"point": "「一挙に」は「一度に・一回の行動で」という意味。二つの問題を同時にまとめて解決する文脈なので「一挙」。「一挙両得」の「一挙」。", "meaning": "一回の行動。（「一挙に」の形で）一度に。いっぺんに。", "kr": "일거에, 단번에, 한꺼번에", "opts": ["一向（に）＝後に否定を伴い「少しも〜ない」（「一向に改善しない」）", "", "一概（に）＝後に否定を伴い「ひとまとめに〜できない」（「一概に言えない」）", "一方＝片方。また「〜する一方だ」で一つの方向に進み続けること。「一方に解決」とは言わない"], "ex": "新しいシステムの導入で、いくつもの課題が<b>一挙</b>に片付いた。"},
"33013": {"point": "「工面」は、お金や物を何とかやりくりして用意すること。「資金を工面する」「旅費を工面する」の形でよく使う。前の「なんとか」もヒント。", "meaning": "苦心して、必要なお金や物を用意すること。やりくり。", "kr": "(돈을) 마련함, 변통", "opts": ["割引＝決まった値段から何割か安くすること。資金には使わない", "", "利益＝もうけ。「利益する」とは言わない", "新規＝新しく始めること（「新規開店」）。「資金を新規する」とは言わない"], "ex": "留学の費用は、アルバイトでなんとか<b>工面</b>した。"},
"33014": {"point": "「まぎらわしい」は、よく似ていて区別がつきにくい、間違えやすいという意味の形容詞。二つの漢字が似ていて見分けにくいということなので「区別がつきにくい」が最も近い。", "meaning": "よく似ていて区別がつきにくい。間違えやすい。", "kr": "헷갈리다, 혼동하기 쉽다", "opts": ["非常に重要である＝とても大切だ。似ていて間違えやすいという意味はない", "", "書き方が難しい＝書くのが難しい。区別のしにくさではない", "あまり使わない＝使われることが少ない。見分けにくさとは関係ない"], "ex": "「未」と「末」は形が<b>まぎらわしい</b>ので、注意して書こう。"},
"33015": {"point": "「軒並み」は、もとは家の軒が並んで続くことで、そこから「どれもこれも、一様に」の意味の副詞として使う。閉店近くには食品がどれも値下げされるということなので「すべて」が近い。", "meaning": "どれもこれも。一様に。そろって。", "kr": "일제히, 모두, 죄다", "opts": ["しいて＝無理に、あえて（「しいて言えば」）。「全部」の意味はない", "", "つとめて＝できるだけ努力して（「つとめて明るく振る舞う」）", "かつて＝以前、昔。時を表し、範囲の意味はない"], "ex": "台風の影響で、今日の飛行機は<b>軒並み</b>欠航になった。"},
"33016": {"point": "「癒し」は「癒す」の名詞形で、心や体の疲れ・苦しみをやわらげ回復させること。英語のhealingにあたり、カタカナ語では「ヒーリング」（ヒーリング音楽）。", "meaning": "心や体の疲れ・痛みをやわらげ、回復させること。", "kr": "힐링, 치유", "opts": ["", "デジタル＝数値で表す方式（アナログの反対）。音楽の効果を表す語ではない", "レクリエーション＝疲れをとるための遊びや娯楽。活動を指し、眠る前に聴く音楽の「癒し」とは違う", "バランス＝つり合い"], "ex": "この温泉は、都会で疲れた人々の<b>癒し</b>の場になっている。"},
"33017": {"point": "「コントラスト」は、色や明暗などの差がはっきりしていること、対照。赤と黄色の違いがくっきりしているということなので「対比」が最も近い。", "meaning": "対照。対比。色・明暗などの差がはっきりしていること。", "kr": "대비, 대조", "opts": ["効果＝ある働きによって現れるよい結果。色同士の対照の意味はない", "混合＝混ぜ合わせること。違いを際立たせる「コントラスト」とは逆", "", "豊富さ＝種類や量が多いこと。二つの色の対照とは関係ない"], "ex": "白い雪と青い空の<b>コントラスト</b>が美しい。"},
"33018": {"point": "「気兼ねする」は、周りの人の気持ちを気にして、言いたいことやしたいことを控えること。他の人に気をつかって発言できなかったということなので「遠慮して」が合う。", "meaning": "他人に気をつかって、遠慮すること。", "kr": "눈치를 봄, 어려워함", "opts": ["", "気に入って＝好きになって。「気」を含むが意味はまったく違う", "貫いて＝最後までやり通して（「信念を貫く」）。遠慮とは逆の態度", "割り込んで＝人の話や列などに無理に入って。遠慮の反対"], "ex": "親戚の家では<b>気兼ね</b>して、なかなかくつろげない。"},
"33019": {"point": "「挑戦する」は、困難なことや強い相手に立ち向かってやってみること。同じ「挑」を使う「挑む（いどむ）」が同じ意味で、「挑戦してみよう」≒「いどんでみよう」。", "meaning": "困難なことや強い相手に立ち向かうこと。", "kr": "도전하다", "opts": ["", "おびえて＝怖がってびくびくして。迷わず立ち向かうのとは逆", "からかって＝冗談を言ったりして人を困らせて", "つぶやいて＝小さな声で独り言を言って"], "ex": "彼は世界記録に<b>挑戦</b>することを決めた。"},
"33020": {"point": "「採決」は、会議などで議案の賛否を決めるため、挙手や投票で決をとること。「採決をとる」「採決する」と使う。意見が一致しないので多数決で決めた②が正しい。", "meaning": "議案の可否を、出席者の賛否の数によって決めること。", "kr": "표결, 채결", "opts": ["人を選んで雇うのは「採用」 → 新卒採用を行う", "", "答案に点をつけるのは「採点」 → 答案を採点して", "収支が合って利益が出ることは「採算」 → 採算が取れないため"], "ex": "議論が尽きたところで、議長は法案の<b>採決</b>を行った。"},
"33021": {"point": "「素早い」は、人や動物の動作・判断・対応が非常に早いこと。「素早い動作」「素早く対応する」のように、意志をもって動く主体について使う。③の消防の対応が正しい。", "meaning": "動作や判断がきわめて早い。", "kr": "재빠르다, 날쌔다", "opts": ["風に飛ばされる紙など、自然の勢いには使わない → 勢いよく（あっという間に）飛んでしまった", "話すのが速いことは「早口」 → 鈴木教授は早口なので", "", "商品が売れる速さには使わない → すぐに（あっという間に）売り切れてしまう"], "ex": "猫は<b>素早く</b>身をかわして逃げていった。"},
"33022": {"point": "「リスク」は、損害や悪い結果が起こる可能性、危険性のこと。「リスクがある」「リスクを負う」と使う。④の海外進出の危険性が正しい。", "meaning": "損害や危険が起こる可能性。危険性。", "kr": "리스크, 위험(성)", "opts": ["自分の長所や能力のことではない → 自分の強み（長所）を活かして", "コスト削減や効率向上はよい点なので「リスク」ではない → メリットがある", "金融に詳しいのは長所であり危険ではない → 強み（武器）である", ""], "ex": "投資には常に元本割れの<b>リスク</b>がある。"},
"33023": {"point": "「中傷」は、根拠のない悪口を言いふらして他人の名誉を傷つけること。「誹謗中傷」「ネットでの中傷」のように使う。④の匿名のネット上の悪口が正しい。", "meaning": "根拠のないことを言いふらし、他人の名誉を傷つけること。", "kr": "중상, 비방", "opts": ["対立する利害を合わせるのは「調整」 → 利害調整がうまくいかず", "親が子のためを思って言うことで、悪口ではない → 父親の忠告（助言）", "大けがは「重傷（じゅうしょう）」で、形の似た別の語 → 重傷を負った", ""], "ex": "根拠のない<b>中傷</b>に傷つき、彼女はしばらく人前に出なかった。"},
"33024": {"point": "「慕う」は、尊敬や愛情から、その人に心ひかれ、そばにいたいと思うこと。「先生を慕う」「生徒に慕われる」の形で使う。①が正しい。", "meaning": "尊敬や愛情から、その人に心ひかれ、近づきたいと思う。", "kr": "따르다, 흠모하다, 그리워하다", "opts": ["", "指示どおりにするのは「従う」 → 指示に従って", "後を追いかけるのは「追う」 → 先頭ランナーを追っている", "人を守るために弁護する意味はない → 友人をかばった"], "ex": "彼女は面倒見がよく、多くの後輩に<b>慕われて</b>いる。"},
"33025": {"point": "「禁物」は、よくない結果を招くので避けるべきこと。「油断は禁物」「〜するのは禁物だ」と述語で使い、「禁物する」「禁物される」とは言わない。規則による禁止ではなく、してはいけないという忠告の意味で使う②が正しい。", "meaning": "害になるので避けるべき物事。してはいけないこと。", "kr": "금물", "opts": ["規則で許されないことは「禁止」 → 撮影が禁止になっていた", "", "「禁物」は動詞として使えず、規則での制限は「禁止」 → 持ち込みが禁止されている", "「禁物」は動詞として使えず、標識による制限は「禁止」 → 通行が禁止されている"], "ex": "山の天気は変わりやすいので、油断は<b>禁物</b>だ。"},
"33101": {"point": "「破棄」は音読みで「はき」。「破」は「ハ」（破壊・突破）、「棄」は「キ」。契約・約束などを取り消して無効にすること。音の近い「廃棄（はいき）」「放棄（ほうき）」と区別すること。", "meaning": "契約や約束などを取り消して無効にすること。また、書類などを破り捨てること。", "kr": "파기", "opts": ["", "はいき：「廃棄」の読み。不要な物を捨てること", "へいき：「平気」の読み。「破」は「へい」とは読まない", "ほうき：「放棄」の読み。権利などを捨てること"], "ex": "相手側が条件を守らなかったため、協定は<b>破棄</b>された。"},
"33102": {"point": "「衝撃」は音読みで「しょうげき」。「衝」は「ショウ」（衝突）、「撃」は「ゲキ」（攻撃・目撃）と濁る。強く打ち当たる力、また心を強く揺さぶられること。", "meaning": "物体に急に加わる強い力。また、心に受ける激しい動揺。", "kr": "충격", "opts": ["じゅうけき：「衝」は「じゅう」ではなく「しょう」、「撃」は「げき」", "じゅうげき：「銃撃」の読み。「衝」は「しょう」", "しょうけき：「撃」は清音ではなく「げき」", ""], "ex": "人気歌手の突然の引退は、ファンに大きな<b>衝撃</b>を与えた。"},
"33103": {"point": "「諮る」は訓読みで「はかる」。ある問題について、会議や機関などに意見を求めること。音読みは「シ」（諮問）。「はかる」には「図る・計る・測る・量る・謀る」もあるが、意見を求める意味は「諮る」。", "meaning": "ある問題について、会議や他の人に意見を求める。相談する。", "kr": "자문하다, 의견을 묻다", "opts": ["めくって：「捲って」の読み。紙などを裏返すこと", "いかって：「怒って」の読み", "", "かたって：「語って」の読み"], "ex": "新しい規則は、委員会に<b>諮って</b>から決めることになった。"},
"33104": {"point": "「繊維」は音読みで「せんい」。「繊」は「セン」（繊細）、「維」は「イ」（維持）。形の似た「細（さい）」と混同しないこと。", "meaning": "動植物の体をつくる細い糸状のもの。また、布や紙の原料となる糸状のもの。", "kr": "섬유", "opts": ["さいい：「繊」を「細」と混同した読み。「繊」は「せん」", "かんい：「簡易」の読み。「繊」は「かん」とは読まない", "", "たんい：「単位」の読み"], "ex": "野菜には食物<b>繊維</b>が多く含まれている。"},
"33105": {"point": "「大筋」は訓読み＋訓読みで「おおすじ」。物事の大体の内容・骨組みのこと。「大筋で合意する」はよく使う表現。「大」を音読み「ダイ」にしない。", "meaning": "物事のだいたいの内容。主要な部分。あらまし。", "kr": "대강, 큰 줄기, 골자", "opts": ["", "おおもと：「大元・大本」の読み。物事の根本という意味", "だいすじ：「大」を音読みしない。訓読みで「おお」", "だいきん：「代金」の読み。「筋」の音読みは「キン」（筋肉）だが、この語は訓読み"], "ex": "計画の<b>大筋</b>は決まったが、細かい点はこれから話し合う。"},
"33106": {"point": "「襲う」は訓読みで「おそう」。不意に攻めかかること。また、台風・地震などの災害がある地域に被害を与えること。音読みは「シュウ」（襲撃・空襲）。", "meaning": "不意に攻めかかる。災害などが突然ある地域に押し寄せる。", "kr": "덮치다, 습격하다", "opts": ["", "さそう：「誘う」の読み", "きそう：「競う」の読み", "あらそう：「争う」の読み"], "ex": "夜中に大きな地震が町を<b>襲った</b>。"},
"33107": {"point": "「合併」は二つ以上の組織や会社が一つになること。「会社同士の」とあるので、企業が一つになる「合併」が合う。", "meaning": "二つ以上の組織・会社・自治体などが一つにまとまること。", "kr": "합병", "opts": ["", "清掃＝きれいに掃除すること", "財政＝国や団体の経済状態・お金のやりくり", "誘導＝人や物をある場所・方向へ導くこと（「避難誘導」）"], "ex": "二つの銀行が<b>合併</b>して、新しい銀行が生まれた。"},
"33108": {"point": "「体を鍛える」は、運動などで体を強くすること。毎日泳いでいる目的なので「きたえよう」。", "meaning": "練習や運動を重ねて、体や心・技術を強くする。", "kr": "단련하다", "opts": ["こたえよう＝答える・応える。質問に返事をする、期待に沿うこと", "ふるえよう＝震える。体が小刻みに揺れ動くこと。自動詞で「体を」と合わない", "となえよう＝唱える。声に出して言う、主張すること", ""], "ex": "毎朝ジョギングをして、足腰を<b>鍛えて</b>いる。"},
"33109": {"point": "「綿密」は、細かいところまで注意が行き届いていること。「綿密な観察」「綿密な計画」の形でよく使う。「もうちょっと〜な観察を」とあるので、細かく注意深い意味の「綿密」。", "meaning": "細かいところまで注意が行き届いていて、手落ちがない様子。", "kr": "면밀함, 꼼꼼함", "opts": ["濃密＝内容や密度が濃い様子（「濃密な時間」）。観察の細かさには使わない", "些細＝取るに足りないほど小さい様子（「些細なこと」）", "", "密接＝関係が深く、強く結びついている様子（「密接な関係」）"], "ex": "旅行の前に、<b>綿密</b>な計画を立てた。"},
"33110": {"point": "「折衷案」は対立する意見の間をとった案。それを出して両者に歩み寄らせた、という流れなので「妥協」。", "meaning": "対立する者同士が互いに譲り合って、意見をまとめること。", "kr": "타협", "opts": ["対立＝互いに反対の立場で張り合うこと。折衷案を出した結果としては逆", "", "反目＝互いに仲が悪く、にらみ合うこと", "親睦＝互いに親しみ合い、仲よくすること（「親睦会」）。意見の調整ではない"], "ex": "何度も話し合った末、双方が<b>妥協</b>して契約が成立した。"},
"33111": {"point": "「慎む」は、よくない言動を控えること。「言動を慎む」「発言を慎む」の形で使う。「〜方がいい」と忠告する文脈なので「つつしんだ」。", "meaning": "過ちのないように控えめにする。度を越さないように控える。", "kr": "삼가다, 조심하다", "opts": ["くやんだ＝悔やむ。後になって残念に思うこと", "いどんだ＝挑む。困難なことに立ち向かうこと", "おしんだ＝惜しむ。大切にして手放したがらないこと、残念に思うこと", ""], "ex": "会議中の私語は<b>慎んで</b>ください。"},
"33112": {"point": "「トレンド」は流行・傾向のこと。「今年のトレンド」はファッションやデザインの流行を言うときの決まった言い方。", "meaning": "流行。時代の動向・傾向。", "kr": "트렌드, 유행", "opts": ["ニュアンス＝言葉や表現の微妙な意味合い", "キャリア＝職業上の経歴", "", "プラン＝計画"], "ex": "今年の秋は、ゆったりしたコートが<b>トレンド</b>だ。"},
"33113": {"point": "「安静」は、病気やけがの回復のために体を動かさず静かにしていること。「安静にする」の形で使う。退院後の療養の指示なので「安静」。「休養」も意味は近いが、「休養する・休養をとる」と言い、「休養にする」とは言わない。", "meaning": "病気やけがの回復のため、体を動かさず静かに休むこと。", "kr": "안정(을 취함)", "opts": ["休憩＝仕事などの途中で一時休むこと。病後の療養には使わない", "休養＝仕事などを休んで体力を回復させること。「休養をとる」とは言うが「休養にする」とは言わない", "", "安定＝変化が少なく落ち着いていること（「生活が安定する」）"], "ex": "医者に、熱が下がるまで<b>安静</b>にしているように言われた。"},
"33114": {"point": "「円滑」は、物事がとどこおりなく、スムーズに進む様子。交渉がうまく進んでいるということなので、物事が調子よく進む「順調に」が最も近い。", "meaning": "物事がとどこおりなく、すらすらと進む様子。", "kr": "원활히, 순조롭게", "opts": ["強烈に＝刺激や印象が非常に強く。進み方のなめらかさの意味はない", "巧妙に＝やり方が非常にたくみに。悪い意味でも使い、物事が滞りなく進む様子ではない", "", "頻繁に＝何度も繰り返して"], "ex": "準備が整っていたので、式典は<b>円滑に</b>進んだ。"},
"33115": {"point": "「慣れる」は、何度も経験してそれが当たり前になること。新しい環境や人になじんで違和感がなくなることを「なじむ」と言い、「一人暮らしに慣れてきた」≒「なじんできた」。", "meaning": "何度も経験して、それが普通になる。", "kr": "익숙해지다, 적응하다", "opts": ["さからって＝逆らって。相手や流れに反対して", "あきれて＝あまりのことに驚き、ばかばかしく思って", "めぐまれて＝恵まれて。よい物事や環境が与えられて", ""], "ex": "転校して三か月、娘もやっと新しいクラスに<b>慣れて</b>きた。"},
"33116": {"point": "「いやみ」は、遠回しに相手を不快にさせる言い方や態度。わざと逆のことを言ったり遠回しに相手を責めたりする「皮肉」が最も近い。", "meaning": "遠回しに相手を不快にさせるような言葉や態度。", "kr": "비꼬는 말, 빈정거림", "opts": ["冗談＝ふざけて言う話。相手を不快にさせる意図はない", "愚痴＝言っても仕方がない不平をこぼすこと。相手を当てこする意味はない", "苦情＝迷惑や不満を相手に直接訴えること。遠回しの言い方ではない", ""], "ex": "遅刻した私に、課長は「ずいぶん早いね」と<b>いやみ</b>を言った。"},
"33117": {"point": "「競争する」は、他と勝ち負けや優劣を争うこと。互いに負けまいとして争う意味の「張り合う」が最も近い。", "meaning": "互いに勝ち負けや優劣を争うこと。", "kr": "경쟁하다, 겨루다", "opts": ["", "張り切って＝やる気に満ちて元気に取り組んで。相手と争う意味はない", "押し切って＝反対を無理に退けて、自分の考えを通して", "押し付けて＝無理に相手に受け入れさせて"], "ex": "二つの会社が新製品の開発で激しく<b>競争して</b>いる。"},
"33118": {"point": "「コスト」は、物を作ったり事業を行ったりするのにかかるお金、費用のこと。広告をやめて出費を減らすということなので「費用」。", "meaning": "生産や事業にかかる費用。経費。", "kr": "비용, 코스트", "opts": ["宣伝＝商品などを広く知らせること。中止するのは広告で、削減するのは費用", "便益＝便利で利益になること。削減したいものではない", "", "圧力＝押さえつける力"], "ex": "部品を海外で生産して、<b>コスト</b>を抑えている。"},
"33119": {"point": "「しいて」は「強いて」と書き、無理に、あえての意味。「しいて言えば」は、特に不満はないが無理に挙げるとすれば、という言い方。「むりに」が最も近い。", "meaning": "無理に。あえて。", "kr": "굳이, 억지로", "opts": ["", "ひたすら＝そのことだけに集中して（「ひたすら勉強する」）", "けっして＝後に否定を伴い、絶対に〜ない", "じっくり＝時間をかけて落ち着いて"], "ex": "欠点は特にないが、<b>しいて</b>言えば値段が少し高い。"},
"33120": {"point": "「抗議」は、相手の言動や決定に対して、反対の意見や不満を強く申し立てること。「〜に抗議する」「抗議の電話」などと使う。①の差別発言への抗議が正しい。", "meaning": "不当だと思う相手の言動・決定に、反対の意見を強く申し立てること。", "kr": "항의", "opts": ["", "お金を集めることではない → 会費は会場で徴収いたします（お支払いください）", "話し合いがまとまることではない → 結局、合意には至らなかった", "作品の受け止め方・評価のことではない → 映画に対する評価（感想）は"], "ex": "住民たちは工場の建設計画に強く<b>抗議</b>した。"},
"33121": {"point": "「ひとまず」は、先のことは別として、とりあえず一区切りつける様子。「ひとまず終わりにする」「ひとまず安心だ」と使う。②の今日の作業をとりあえず終わりにする文が正しい。", "meaning": "先のことは別として、とりあえず。一応。", "kr": "일단, 우선", "opts": ["「ひとまず」に「に」は付かず、済ませた報告を言うなら「一応」が自然 → 一応報告しておきました", "", "時間の長さを表す意味はない → しばらく時間が経ってから", "「一度〜した以上は」の意味は「いったん」 → いったん約束したからには"], "ex": "熱も下がったので、<b>ひとまず</b>安心だ。"},
"33122": {"point": "「手際」は、物事を処理するやり方や腕前。「手際がいい」「手際よく〜する」の形で使う。①の手際よく料理を作る、が正しい。", "meaning": "物事を処理するやり方・腕前。", "kr": "솜씨, 일 처리 솜씨", "opts": ["", "時間や労力がかかることは「手間」 → 手間のかかる作業", "立派な働き・功績は「手柄」 → 手柄をあげた", "すぐ手が届く近くは「手元」 → 手元に置いておく"], "ex": "彼は<b>手際</b>よく書類を整理して、すぐに会議の準備を終えた。"},
"33123": {"point": "「とっさに」は、急な出来事が起きたその瞬間に、考える間もなく反射的に行動する様子。転びそうになった瞬間に腕をつかんだ④が正しい。", "meaning": "急な出来事に対して、その瞬間に。思わず、反射的に。", "kr": "순간적으로, 엉겁결에", "opts": ["天気など出来事が急に起こる様子には使わない → 急に（突然）雨が降り出した", "前から予定していた行動には使わない → すぐに（さっさと）帰りました", "用事が急に生じることには使わない → 急に（突然）用事ができてしまい", ""], "ex": "ボールが飛んできたので、<b>とっさに</b>顔をかばった。"},
"33124": {"point": "「満喫」は、十分に味わい、心ゆくまで楽しむこと。「休暇を満喫する」「自然を満喫する」のように「〜を満喫する」の形で使う。③が正しい。", "meaning": "十分に味わって、満足するまで楽しむこと。", "kr": "만끽", "opts": ["「満喫になる」とは言わず、気分を表す語でもない → ゆったりとくつろぎたい", "条件に合うことは「満たす」 → 条件を満たす人材", "", "相手の欲求を満たす意味はない → 好奇心を満たせる（満足させられる）とは"], "ex": "週末は山へ行き、秋の紅葉を<b>満喫</b>した。"},
"33125": {"point": "「とぐ（研ぐ）」は、刃物を砥石などでこすって鋭くすること。米を水の中でこすって洗うことにも使う（「米をとぐ」）。③の包丁が正しい。", "meaning": "刃物をこすって鋭くする。米を水の中でこすって洗う。", "kr": "(칼을) 갈다, (쌀을) 씻다", "opts": ["体を強くすることは「鍛える」 → 体を鍛えて", "汚れや曇りを取るのは「ふく」 → ハンカチでふいた", "", "問題の答えを出すのは「解く」（て形は「といて」） → 数学の問題を解いてから寝た"], "ex": "料理人は毎朝、包丁を<b>といで</b>から仕事を始める。"},
"33201": {"point": "「意図」は音読みで「いと」。「図」には「ズ」（地図）と「ト」（図書）の読みがあり、この語では「ト」。何かをしようとする考え・ねらいのこと。", "meaning": "何かをしようと考えていること。ねらい。", "kr": "의도", "opts": ["いし：「意思・意志」の読み", "いず：「図」を「ず」と読む誤り。この語では「と」", "", "いみ：「意味」の読み"], "ex": "作者がこの場面で何を伝えたかったのか、その<b>意図</b>を考える。"},
"33202": {"point": "「頻繁」は音読みで「ひんぱん」。「頻」は「ヒン」、「繁」は「ハン」（繁栄）だが、「ん」の後で半濁音化して「ぱん」になる。何度も繰り返し行われる様子。", "meaning": "同じことが、しばしば繰り返し起こる様子。", "kr": "빈번함, 잦음", "opts": ["とびん：「頻」は「と」ではなく「ひん」、「繁」は「ぱん」", "もはん：「模範」の読み", "", "かびん：「花瓶」の読み"], "ex": "この交差点では事故が<b>頻繁</b>に起きている。"},
"33203": {"point": "「潤う」は訓読みで「うるおう」。湿り気を帯びることから、経済的にゆとりができる意味でも使う。「生活が潤う」は暮らしが豊かになること。音読みは「ジュン」（潤滑）。", "meaning": "適度に湿り気を帯びる。また、経済的にゆとりが生まれ、豊かになる。", "kr": "촉촉해지다, 윤택해지다", "opts": ["からかって：冗談を言って人を困らせること。「潤」の読みではない", "ならって：「習って・倣って」の読み", "", "あしらって：相手を軽く扱うこと。「潤」の読みではない"], "ex": "観光客が増えて、町の経済が<b>潤って</b>いる。"},
"33204": {"point": "「若干」は音読みで「じゃっかん」。「若」は「ジャク」（若年）で、「干（カン）」の前で促音化して「じゃっ」になる。濁音の「じゃ」に注意。", "meaning": "数量がそれほど多くないこと。少し。いくらか。", "kr": "약간", "opts": ["さかん：「盛ん」の読み", "ざっかん：「雑感」の読み。「若」は「ざつ」ではない", "しゃっかん：「借款」の読み。「若」は濁って「じゃく」", ""], "ex": "予定より<b>若干</b>遅れて会議が始まった。"},
"33205": {"point": "「営む」は訓読みで「いとなむ」。商売や事業などを行って経営すること。音読みは「エイ」（営業・経営）。", "meaning": "商売や事業を行う。経営する。また、生活などを行う。", "kr": "경영하다, 영위하다", "opts": ["あゆんで：「歩んで」の読み", "", "かこんで：「囲んで」の読み", "はこんで：「運んで」の読み"], "ex": "祖父母は田舎で小さな旅館を<b>営んで</b>いる。"},
"33206": {"point": "「富豪」は音読みで「ふごう」。「富」は「フ」（貧富）、「豪」は「ゴウ」（豪華）。非常に多くの財産を持つ人のこと。「富」を「ふう」と伸ばしたり、「豪」を清音で読んだりしない。", "meaning": "非常に多くの財産を持っている人。大金持ち。", "kr": "부호, 큰 부자", "opts": ["ふくごう：「複合」の読み", "ふうご：「富」は「ふ」、「豪」は「ごう」と伸ばす", "", "ふこう：「不幸」の読み。「豪」は濁って「ごう」"], "ex": "その<b>富豪</b>は、全財産を慈善団体に寄付した。"},
"33207": {"point": "「駆け引き」は、交渉などで相手の出方を見ながら自分に有利になるようにやりとりすること。与野党が法案をめぐって争っている文脈なので「駆け引き」。", "meaning": "交渉や商売で、相手の出方に応じて自分に有利になるように振る舞うこと。", "kr": "흥정, 밀고 당기기", "opts": ["", "割り引き＝決まった値段から何割か安くすること", "差し引き＝ある数量から別の数量を引くこと。また、その残り", "くじ引き＝くじを引いて当たり外れや順番を決めること"], "ex": "恋愛に<b>駆け引き</b>は必要だと言う人もいる。"},
"33208": {"point": "「結成」は、団体や組織を新しく作ること。「バンドを結成する」「チームを結成する」の形でよく使う。", "meaning": "団体・組織などを新たにつくること。", "kr": "결성", "opts": ["進出＝新しい分野・地域に進んで出ていくこと（「海外進出」）", "", "発明＝今までなかった物や方法を新しく考え出すこと", "再生＝生き返ること。また、録音・録画を再び流すこと"], "ex": "大学の仲間と劇団を<b>結成</b>した。"},
"33209": {"point": "「派遣」は、任務を与えて人をある場所へ行かせること。「現地に調査官を」とあるので「派遣」。", "meaning": "任務を与えて、人をある場所へ送り出すこと。", "kr": "파견", "opts": ["", "介入＝当事者以外が割り込んで関わること（「政府が介入する」）", "分類＝種類ごとに分けること", "転送＝送られてきたものを、さらに別の所へ送ること（「メールを転送する」）。人には使わない"], "ex": "被災地に救助隊が<b>派遣</b>された。"},
"33210": {"point": "「フォローする」は、足りないところを補ったり、後から助けたりすること。新人の仕事を支えるのが任務、という文脈なので「フォロー」。", "meaning": "足りないところを補ったり、後から手助けしたりすること。", "kr": "보완, 뒷받침, 도움", "opts": ["アップ＝上げること・上がること（「給料アップ」）", "マッチ＝調和すること、似合うこと（「服と靴がマッチする」）", "ギャップ＝ずれ、隔たり", ""], "ex": "先輩が失敗を<b>フォロー</b>してくれたおかげで、大きな問題にならなかった。"},
"33211": {"point": "「やんわり」は、言い方や態度が穏やかで角が立たない様子。「やんわり断る」はよく使う表現。穏やかに断ったのに相手は傷ついた、という流れにも合う。", "meaning": "穏やかに、遠回しに物を言う様子。", "kr": "부드럽게, 완곡하게", "opts": ["ふんわり＝柔らかく軽くふくらんでいる様子（「ふんわりしたパン」）。言い方には使わない", "どんより＝空が曇って薄暗い様子。空気などが重く濁っている様子", "わりあい＝割合。比較的、思ったよりも", ""], "ex": "先輩の誘いを<b>やんわり</b>と断った。"},
"33212": {"point": "「よみがえる」は、消えかけていたものが再び元の状態に戻ること。「思い出がよみがえる」「記憶がよみがえる」の形でよく使う。", "meaning": "一度失われたものが、再び元の状態に戻る。生き返る。", "kr": "되살아나다, 소생하다", "opts": ["ちかづける＝近づける。他動詞で「〜を近づける」と使い、「思い出が」とは合わない", "ぶらさがる＝ぶら下がる。上から垂れ下がること", "", "たてまつる＝奉る。目上の人に差し上げること"], "ex": "その曲を聞くと、幼いころの記憶が<b>よみがえる</b>。"},
"33213": {"point": "「かろうじて」は、やっとのことで、ぎりぎり何かができた様子。遅刻しそうだったが、バスに乗り換えてぎりぎり間に合った、という文脈なので「かろうじて」。", "meaning": "やっとのことで。ぎりぎりのところで。", "kr": "간신히, 겨우", "opts": ["", "ことごとく＝残らず全部", "やむをえず＝仕方なく。乗り換えた理由には合うが、「間に合った」の様子には合わない", "おのずから＝自然に、ひとりでに"], "ex": "試験には<b>かろうじて</b>合格することができた。"},
"33214": {"point": "「まごつく」は、どうしたらよいか分からず、うろたえて迷うこと。予想外の結果にどうしてよいか分からなかったということなので「とまどった」が最も近い。", "meaning": "どうしたらよいか分からず、うろたえる。まごまごする。", "kr": "당황하다, 허둥대다", "opts": ["", "よろこんだ＝うれしく思った。迷う意味はない", "気がゆるんだ＝緊張がとけて油断した", "うぬぼれた＝自分を実際以上に優れていると思い込んだ"], "ex": "初めての海外旅行で、空港の案内が分からず<b>まごついた</b>。"},
"33215": {"point": "「面倒くさい」は、手間がかかって嫌だ、やる気が起きないという気持ち。手間がかかって気が重いという意味の「煩わしい」が最も近い。", "meaning": "手間がかかって、やる気が起きない。わずらわしい。", "kr": "귀찮다, 성가시다", "opts": ["地味だ＝目立たず、華やかさがない", "紛らわしい＝似ていて区別しにくい。「煩わしい」と形が似ているので注意", "", "退屈だ＝することがなく、つまらない。手間がかかって嫌だという意味ではない"], "ex": "雨の日は外に出るのが<b>面倒くさい</b>。"},
"33216": {"point": "「微妙」は、細かい点に複雑な違いや意味があって、簡単には言い表せない様子。細やかで繊細なという意味のカタカナ語「デリケート」が最も近い（「デリケートな違い」「デリケートな問題」）。", "meaning": "細かい部分に複雑な意味や違いがあって、簡単に言い表せない様子。", "kr": "미묘하다", "opts": ["タイムリーな＝時機がちょうどよい", "", "エレガントな＝上品で優雅な", "ナンセンスな＝意味がなく、ばかげた"], "ex": "日本語の敬語には<b>微妙な</b>使い分けがある。"},
"33217": {"point": "「つのる（募る）」は、気持ちや傾向がますます激しくなること（「不安が募る」「思いが募る」）。試験直前で不安が強くなるということなので「つよくなる」。「参加者を募る」のように、広く呼びかけて集める意味もある。", "meaning": "気持ちや様子がますます激しくなる。また、広く呼びかけて集める。", "kr": "(감정이) 더해지다, 심해지다", "opts": ["よわくなる＝程度が小さくなる。「つのる」とは逆", "なくなる＝消えてしまう。逆の意味", "でなくなる＝表に出なくなる。強まる意味はない", ""], "ex": "連絡がないまま夜になり、家族の心配は<b>つのる</b>一方だった。"},
"33218": {"point": "「とぼける」は、知っているのに知らないふりをすること。質問にわざと知らないふりをしていたということなので「知らんぷりして」が最も近い。", "meaning": "知っているのに、わざと知らないふりをする。", "kr": "시치미 떼다", "opts": ["いやいや答えて＝しかたなく答えて。答えているので知らないふりではない", "", "興味を示して＝関心を見せて", "かなり怒っていた＝強く腹を立てていた。知らないふりの意味はない"], "ex": "弟は私のケーキを食べたのに、「何のこと？」と<b>とぼけて</b>いる。"},
"33219": {"point": "「了承する」は、相手の事情や申し出を理解し、それでよいと受け入れること。父が留学の話を理解して認めてくれたということなので、選択肢の中では、よく分かって受け入れる意味の「納得して」が最も近い。", "meaning": "事情や申し出を理解し、受け入れること。承知。", "kr": "승낙, 양해", "opts": ["案内して＝道や場所を教えながら連れて行って", "報告して＝結果や状況を知らせて", "", "誘導して＝目的の場所や方向へ導いて"], "ex": "部長は私の休暇の申請を<b>了承して</b>くれた。"},
"33220": {"point": "「丹念」は、細かいところまで心をこめて、丁寧に念入りにする様子。「丹念に調べる」「丹念に作る」のように「丹念に」の形でよく使う。①の職人が心をこめて作る和菓子が正しい。", "meaning": "細かいところまで心をこめて、丁寧にする様子。", "kr": "공들임, 정성스러움", "opts": ["", "あきらめてやめることは「断念」（だんねん） → 登山を断念せざるをえない", "よくないことを心配することは「懸念」 → 財政の悪化が懸念される", "仕事への強い気持ちは「情熱」 → やる気と情熱を持って"], "ex": "彼女は古い資料を一枚一枚<b>丹念に</b>調べた。"},
"33221": {"point": "「交付」は、国や役所などが書類やお金を正式に渡すこと。「補助金が交付される」「免許証を交付する」と使う。②が正しい。", "meaning": "国・役所などが書類や金銭を正式に渡すこと。", "kr": "교부", "opts": ["国民が税金を納めるのは「納付」 → 税金を納める（納付する）義務", "", "会社が給料を払うのは「支給」 → 給料が支給されたら（出たら）", "個人が土産を渡す場面には使わない → お土産を配った（渡した）"], "ex": "申請から一週間ほどで、パスポートが<b>交付</b>される。"},
"33222": {"point": "「ずらっと」（ずらりと）は、多くの人や物が長く一列に並んでいる様子。「ずらっと並ぶ」の形でよく使う。④の店の前に人が並ぶ様子が正しい。", "meaning": "多くのものが長く一列に並んでいる様子。ずらりと。", "kr": "죽, 줄지어", "opts": ["全体を大まかに見るのは「ざっと」 → 見出しにざっと目を通した", "ある状態が長く続くのは「ずっと」 → 明日はずっと晴れる", "安心するのは「ほっと」 → 聞いてほっとした", ""], "ex": "本棚には古い辞書が<b>ずらっと</b>並んでいる。"},
"33223": {"point": "「拠点」は、活動のよりどころとなる重要な場所。「〜を拠点に活動する」の形でよく使う。③の東京を中心にビジネスを展開する文が正しい。", "meaning": "活動のよりどころとなる重要な場所。", "kr": "거점", "opts": ["予定より遠くまで行くのは「足をのばす」 → 京都まで足をのばした", "社会的な位置や役割は「立場」 → 利益を守る立場にある", "", "説を支える理由や証拠は「根拠」 → 裏付けられるような根拠"], "ex": "その登山隊は、ふもとの村を<b>拠点</b>に山頂を目指した。"},
"33224": {"point": "「ののしる」は、大声でひどい悪口を言って相手を責めること。③の大きなミスをして部長に大声で責められた文が正しい。", "meaning": "大声でひどい悪口を言う。", "kr": "욕하다, 매도하다", "opts": ["人を集めるのは「募る」「募集する」 → 人材を募集している", "よいことをした子には「ほめる」（意味が逆） → ほめてあげる", "", "勝利を願う意味はない → 優勝を祈りながら（願いながら）"], "ex": "試合に負けた選手を<b>ののしる</b>観客の声が会場に響いた。"},
"33225": {"point": "「ジャンル」は、芸術作品などを内容や形式によって分けた種類・部門（音楽・文学・映画など）。②の音楽の種類が正しい。", "meaning": "芸術作品などの種類・部門。", "kr": "장르", "opts": ["試験に出る内容の広がりは「範囲」 → 出題範囲を超える", "", "建物の様式や雰囲気は「〜風」 → ヨーロッパ風の建物", "交渉の対象となる領域は「分野」 → 貿易分野で合意に達した"], "ex": "彼はクラシックからジャズまで、幅広い<b>ジャンル</b>の曲を演奏する。"},
// JLPT 급소공략 N1 문법 (模擬テスト・練習問題・総まとめ問題): 文法形式・文の組み立て・文章の文法 (each blank keyed "<id>_<blank index>")
"35001": {"point": "「〜ゆえに」は「〜が理由で」という意味の硬い表現で、名詞に直接付くこともできる。「内気な性格」が原因となって、なかなか友達を作れなかったという因果関係を表している。", "opts": ["", "くせに：「〜くせに」は不満や非難を表し、名詞には「性格のくせに」と「の」が必要。また内気だから友達ができないという理由の文に合わない", "ことに：「〜ことに」は「残念なことに」のように感情を表す語に付いて話し手の気持ちを前置きする形で、名詞「性格」には付かない", "ように：名詞には「性格のように」と「の」が必要。また「〜のように」は比喩・例示を表し、理由を表さない"], "ex": "彼は若さ<b>ゆえに</b>、失敗を恐れずに挑戦することができた。"},
"35002": {"point": "「〜ともなれば」は「〜という段階・立場になれば、当然」という意味で、後には当然の結果が続く。古い家の屋根を本格的に修理するという段階になれば、当然相当な金額がかかるだろうという文脈に合う。", "opts": ["ともすれば＝ややもすれば、どうかすると。「ともすれば〜しがちだ」と傾向を表す副詞で、名詞「修理」に付けて使えない", "", "ともあれ：「〜はともあれ」の形で「〜はともかく」の意。「修理ともあれ」とは言えず、意味も合わない", "とはいえ＝〜けれども。逆接なので、「本格的な修理には当然お金がかかる」という順当な流れに合わない"], "ex": "社長<b>ともなれば</b>、会社全体のことを常に考えなければならない。"},
"35003": {"point": "「〜ならではの」は「〜だけが持つ特別な」という意味で、それにしかない良さをほめる表現。300年の歴史を誇る老舗旅館だからこそ味わえる特別なおもてなし、という意味になる。", "opts": ["ごときの：「ごとき」は名詞に直接付くと「私ごとき」のように「〜程度の」と軽く見る意味になり、歴史を誇る旅館をほめる文に合わない", "からある：「〜からある」は「50キロからある荷物」のように数量に付いて「〜以上もある」を表す。名詞「旅館」には付かない", "にもまして＝〜以上に。「去年にもまして」のように比較の対象が必要で、後の名詞「おもてなし」を修飾する形にもならない", ""], "ex": "地元の人<b>ならではの</b>情報のおかげで、楽しい旅行になった。"},
"35004": {"point": "「〜にいたっては」は「〜という極端な事態になっては」という意味で、後には「もう〜するしかない」という判断が続く。目撃証言に加えて指紋まで発見されるという決定的な事態になっては、否認を続けられず自白するしかない。", "opts": ["にもまして＝〜以上に。「以前にもまして」のように比較に使う表現で、指紋が発見されたという事態を受ける文に合わない", "", "にひきかえ＝〜とは反対に。二つのものを対比する表現で、ここには対比されるものがない", "にむけては＝〜を目標にしては。目標や方向を表し、指紋の発見という事態を受けて判断を述べる文に合わない"], "ex": "事態がここ<b>にいたっては</b>、計画を中止するしかないだろう。"},
"35005": {"point": "「〜てまで」は「そこまでして（極端なことをして）」という意味で、後に「〜したくない・〜する気はない」などが続くことが多い。今の生活を犠牲にするという極端なことをしてまで結婚する気はない、という意味になる。", "opts": ["せずとも＝しなくても（書き言葉）。「犠牲にしなくても」の意になり、「そんなことをしてまでは〜しない」という気持ちが表せない", "しないまでも＝〜ほどではなくても、せめて。後には「せめて〜」という最低限の程度が続き、この文と合わない", "までなら：「〜までなら」は「三時までなら待てる」のように範囲の限度を表す。「犠牲にまでなら」という形は不自然で、意味もつながらない", ""], "ex": "借金をし<b>てまで</b>、ブランド品を買いたいとは思わない。"},
"35006": {"point": "「〜次第」は動詞のます形に付いて「〜したらすぐに」という意味を表し、後には「連絡します」など話し手の意志的な行為が続く。参加者のリストが出来上がったらすぐに連絡するという意味になる。", "opts": ["出来上がっては：「〜ては」は「そうなっては困る」のように好ましくない条件や繰り返しを表し、「ご連絡します」につながらない", "出来上がったかと思うと：「〜たかと思うと」は「〜したと思ったらすぐに（意外な変化が起こった）」の意で、過去の出来事に使う。これからの予定を伝える文に合わない", "", "出来上がって結果：「結果」は「出来上がった結果」のようにた形に付く。また「〜た結果」は結果の説明で、意味も合わない"], "ex": "詳しいことが分かり<b>次第</b>、お知らせいたします。"},
"35007": {"point": "「〜たところで」は「〜しても（結果は変わらない）」という意味で、「いくら〜たところで」の形で後に否定的な予測が続く。野党がどんなに反対しても、結局法案は通ってしまうだろうという文脈に合う。", "opts": ["が最後：「〜たが最後」は「一度〜したら、もう（大変なことになる）」の意。反対しても結果は変わらないという文に合わず、「いくら」とも呼応しない", "がゆえに＝〜が理由で。反対したことが理由で法案が通るという意味になり、「いくら」とも呼応しない", "どころか＝〜はもちろん、それ以上に／〜とは反対に。「いくら」と呼応せず、意味もつながらない", ""], "ex": "今さら謝った<b>ところで</b>、彼女は許してくれないだろう。"},
"35008": {"point": "「〜んがため」は「〜するために」という意味の硬い表現で、強い目的を表す。「事業を」を受けるのは使役の「成功させる」で、そのない形「させ」に「んがため」が付いて「成功させんがため」となる。", "opts": ["", "されんがため：受身の「される」から作った形で、「事業を成功される」という意味の通らない文になる。「事業を」には使役の「させる」が必要", "するがため：「成功する」は自動詞なので「事業を成功する」とは言えない。「事業を」を受けるには使役の「成功させる」が必要", "しようがため：意志形に「がため」が付く形はない。また「成功しよう」では「事業を」も受けられない"], "ex": "夢をかなえ<b>んがため</b>、彼は毎日遅くまで練習を続けた。"},
"35009": {"point": "「〜とあっては」は「〜という特別な状況なら」という意味で、後に「〜ないわけにはいかない」など、その状況ならそうせざるを得ないという判断が続く。亡くなった監督の遺作が発売されるという特別な状況なので、大ファンとして買わないわけにはいかない。", "opts": ["にあってか：「〜にあって」は「困難な時代にあって」のように名詞に付いて「〜という状況で」を表す。動詞「発売される」には付かない", "", "になっては：「〜になっては」は名詞に付く形で、動詞の辞書形「発売される」には付かない", "となっては：「今となっては」のように、すでにそうなってしまった状況を受けて「もう〜ない」と述べることが多く、発売という特別な機会を表す文に合わない"], "ex": "憧れの先輩に頼まれた<b>とあっては</b>、断るわけにはいかない。"},
"35010": {"point": "「おっしゃってくださいませんか」は「言ってくれませんか」の尊敬表現。木村さんは店長に、清水さんへ一言注意してほしいと頼んでいるので、目上の店長の動作「言う」を尊敬語「おっしゃる」で表し、依頼の形にする。", "opts": ["伺いたいのですが：「伺う」は「聞く」の謙譲語で、木村さんが店長から話を聞きたいという意味になり、注意を頼む文脈に合わない", "お聞きになるでしょうか：「お聞きになる」は「聞く」の尊敬語で、店長が聞くかどうかを推量する意味になり、依頼にならない", "申し上げてもよろしいですか：「申し上げる」は「言う」の謙譲語で、木村さんが自分で言う許可を求める意味になる。「店長から」と合わない", ""], "ex": "先生、私の作文の悪いところをはっきり<b>おっしゃってくださいませんか</b>。"},
"35101": {"point": "「〜すら」は「〜さえ」と同じく、極端な例を挙げて「ほかはなおさらだ」という意味を表す。毎日の交通費のような最低限のお金さえ足りないのだから、ましてお金のかかる旅行は無理だという流れになる。", "opts": ["", "こそ：「こそ」は「これこそ」のように強調する語で、極端な例を挙げて「ほかはなおさら」と導く意味がない", "のみ＝〜だけ（硬い表現）。「交通費のみ足りない」では交通費以外は足りていることになり、旅行は無理という結論とつながらない", "だけ：「交通費だけ足りない」では交通費以外のお金はあることになり、旅行は無理という結論とつながらない"], "ex": "忙しくて、休日<b>すら</b>ゆっくり休めない。"},
"35102": {"point": "「〜るんじゃなかった」は「〜しなければよかった」という後悔を表す話し言葉。朝からお腹の調子が悪いのは夜中にラーメンを食べたせいなので、食べたことを後悔している。", "opts": ["", "食べてみるに越したことはない：「〜に越したことはない」は「〜するのがいちばんいい」の意で、お腹をこわした後悔の気持ちと合わない", "食べて正解だった：食べてよかったという意味になり、お腹の調子が良くないという前の文と合わない", "食べるべきだった：「〜べきだった」はしなかったことを後悔する表現で、実際に食べて調子をくずした状況と逆になる"], "ex": "こんなにつまらない映画なら、見に来る<b>んじゃなかった</b>。"},
"35103": {"point": "「〜といえども」は「〜であっても」という意味の硬い表現で、後に「〜べきだ」などの判断が続く。新入社員であっても会社の一員なのだから、自分の仕事に責任を持つべきだという意味になる。", "opts": ["", "こととて＝〜なので（硬い表現。「慣れぬこととて」など）。理由を表すため、「新入社員なので責任を持つべきだ」となり意味が合わない", "にひきかえ＝〜とは反対に。二つのものを比べる表現で、比べる相手がないこの文に合わない", "かたがた＝〜を兼ねて。「お礼かたがた」のように動作を表す名詞に付く表現で、意味が合わない"], "ex": "子ども<b>といえども</b>、ルールは守らなければならない。"},
"35104": {"point": "「〜た（か）と思いきや」は「〜したと思ったが、意外にも」という意味で、動詞のた形に付く。やっと梅雨が明けたと思ったが、意外にも今度は大型台風が近づいている、という予想外の展開を表している。", "opts": ["明け：ます形の「明け」には「と思いきや」は付かない。「と思いきや」の前には普通形が必要", "明けて：て形の「明けて」には「と思いきや」は付かない。「と思いきや」の前には普通形が必要", "", "明けない：「明けないと思いきや」では梅雨が明けないと思っていたことになり、「やっと」と合わない。後の台風の話ともつながらない"], "ex": "仕事が終わった<b>と思いきや</b>、また新しい仕事を頼まれた。"},
"35105": {"point": "「ひとり〜のみならず」は「〜だけでなく」という意味の硬い表現で、後に「〜も」が続く。財政赤字は日本だけの問題ではなく、海外の多くの国々も抱えている問題だという意味になる。", "opts": ["だけで：「日本だけで」では「〜だけでなく、〜も」という意味にならず、後の「海外の多くの国々も」とつながらない", "のみで：「のみで」は「〜だけで」の意で、「〜だけでなく」の意味にならない。後の「〜も」ともつながらない", "", "かかわらず：「〜にかかわらず」の形で「〜に関係なく」の意。「日本かかわらず」とは言えず、意味も合わない"], "ex": "この問題は、<b>ひとり</b>若者<b>のみならず</b>、社会全体で考えるべきことだ。"},
"35106": {"point": "「〜とばかりに」は「いかにも〜と言いたそうな様子で」という意味で、口には出さないが態度に表れていることを表す。打ち合わせの途中なのに、「自分には関係ない」と言わんばかりの態度で部屋を出たという意味になる。", "opts": ["はずがなく：「関係ないはずがなく」では「関係がないわけがない」の意になり、部屋を出た態度の説明にならない", "", "かと思うと：「〜かと思うと」は「〜したと思ったらすぐに」の意で動作に付く。「関係ない」という状態には合わない", "ながらも＝〜けれども。「関係ないけれども部屋を出た」となり、意味がつながらない"], "ex": "彼女は「待ってました」<b>とばかりに</b>、手を挙げて発言した。"},
"35107": {"point": "「〜やいなや」は動詞の辞書形に付いて「〜するとすぐに」という意味を表す硬い表現。夕食が済むとすぐに、息子がさっさと自分の部屋にひきこもってしまった様子を表している。", "opts": ["ことなしに＝〜しないで。夕食が済まないまま部屋に行ったという意味になり、「さっさと」の流れに合わず不自然な文になる", "におよんで＝〜という段階になって。「この期に及んで」のように重大な事態に使い、食事が済むという日常の出来事に合わない", "ともなしに＝特に〜しようとは思わずに。「見るともなしに見る」のように意図のない動作に使い、意味が合わない", ""], "ex": "彼はベルが鳴る<b>やいなや</b>、教室を飛び出していった。"},
"35108": {"point": "「〜ばよいというものではない」は「〜するだけでは十分ではない」という意味で、ある考え方を否定する。自分の意見を通すだけではだめで、相手の立場も尊重するべきだという後の文と合う。", "opts": ["通すよりほかにはしかたがない：「〜よりほかにしかたがない」は「〜するしかない」の意で、後の「相手の立場も尊重して」と矛盾する", "", "通さないとも限らない：「〜ないとも限らない」は「〜する可能性もある」の意で、筆者の主張を述べる流れに合わない", "通さないではいられない：「〜ないではいられない」は「どうしても〜してしまう」の意で、相手を尊重するべきだという主張と合わない"], "ex": "安けれ<b>ばよいというものではない</b>。品質も大切だ。"},
"35109": {"point": "「〜といったところだ」は「だいたい〜ぐらいだ」という意味で、数量や程度がそれほど大きくないことを表す。中古品はどんなに高くても10万円ぐらいだ、という値段の目安を述べている。", "opts": ["にほかならない＝まさに〜だ、〜以外のものではない。強い断定の表現で、「高くても」という幅のある値段の目安に合わない", "に上る＝（数量が）〜に達する。数が大きいことを強調する表現で、「高くても10万円」という上限の目安と合わない", "", "でもあるまい＝〜でもないだろう。否定の推量になり、値段を述べる文として意味が通らない"], "ex": "毎日の勉強時間は、多くても2時間<b>といったところだ</b>。"},
"35110": {"point": "「〜をおいて他にない」は「〜以外にない」という意味で、その人やものを高く評価するときに使う。この危機を乗り切れるのは君以外にいないと、社長が山田君を強く信頼している気持ちを表している。", "opts": ["にして：「〜にして」は「40歳にして」のように「〜の段階で」などを表し、「他にはいない」と呼応しない", "にかぎって＝〜だけは特に。「うちの子にかぎって」のように特定のものについて述べる表現で、「他にはいない」と呼応しない", "", "ともなると＝〜という立場になると。後には当然の結果が続き、「君ともなると他にはいない」では意味が通らない"], "ex": "このプロジェクトのリーダーは、彼<b>をおいて</b>他にいない。"},
"36011": {"point": "「〜だけあって」は「さすが〜なので（それにふさわしく）」という意味で、評価する気持ちを表す。「さすが」と呼応し、学生時代にテニスをやっていたのだから今でも上手なのは当然だと評価している。", "opts": ["ばかりか＝〜だけでなく。「やっていたばかりか」の後には付け加える内容が必要で、「今でも上手だ」とつながらない", "", "にしては＝〜のわりには。予想と違う結果に使うので、学生時代にやっていたから上手だという文と合わず、「さすが」とも呼応しない", "きっかけで：「きっかけ」は「〜たのがきっかけで」の形で何かを始めた理由を表す語で、「今でも上手だ」という評価と合わない"], "ex": "さすが元料理人<b>だけあって</b>、彼の作る料理はおいしい。"},
"36012": {"point": "「〜とあって」は「〜という特別な事情なので」という意味で、後にその事情による結果が続く。洋食と和食の両方が楽しめるという特別な事情があるので、お得意さんが多いという意味になる。", "opts": ["", "からして＝〜をはじめとして、〜から判断して。「名前からして怪しい」のように名詞に付き、理由を表さない", "にあって＝〜という状況で。「困難な時代にあって」のように名詞に付き、動詞「楽しめる」には付かない", "にしては＝〜のわりには。予想と違う結果に使うので、「お得意さんが多い」という当然の結果と合わない"], "ex": "夏休み最初の週末<b>とあって</b>、高速道路はひどく渋滞していた。"},
"36013": {"point": "「〜のいかんでは」は「〜によっては」という意味で、後には「〜こともある」などの可能性が続く。学業成績の内容によっては、奨学金の支給を打ち切ることもあるという意味になる。", "opts": ["のきわみで：「〜のきわみ」は「感激のきわみ」のように「この上なく〜だ」という意味で、成績と奨学金の関係を表せない", "といえども＝〜であっても。「学業成績であっても」となり、何に対して譲歩しているのか分からず意味が通らない", "", "ときたら：「〜ときたら」は「うちの息子ときたら」のように人や物への不満を言うときに使い、意味が合わない"], "ex": "検査の結果<b>のいかんでは</b>、手術が必要になるかもしれない。"},
"36014": {"point": "「〜たが最後」は「一度〜したら、もう（止まらない・戻れない）」という意味で、後によくない結果が続く。「一度」と呼応し、彼女は一度話しはじめたら止まらなくなるという意味になる。", "opts": ["が早いか＝〜するとすぐに。一回の出来事について直後の動作を述べる表現で、「一度〜したら止まらなくなる」という意味にならない", "いかんでは＝〜によっては。名詞に付く表現で、動詞「話しはじめた」には付かない", "次第では＝〜によっては。名詞に付く表現で、動詞「話しはじめた」には付かない", ""], "ex": "このお菓子は、一度食べ始めた<b>が最後</b>、やめられなくなる。"},
"36015": {"point": "「〜極まりない」はな形容詞の語幹に付いて「この上なく〜だ」という意味を表す。人にぶつかっておいて謝りもしないのは、この上なく失礼だと強く非難している。", "opts": ["", "に越したことはない：「〜に越したことはない」は「〜のほうがいい」の意で、失礼な態度を非難する文に合わない", "でならない：「〜てならない」は「心配でならない」のように感情を表す語に付く。「失礼」は感情ではないので使えない", "ではいられない：「〜ではいられない」は「〜の状態のままではいられない」の意で、相手を非難する文に合わない"], "ex": "夜中に大声で騒ぐなんて、迷惑<b>極まりない</b>。"},
"36016": {"point": "「〜きらいがある」は「〜という（よくない）傾向がある」という意味で、動詞の辞書形などに付く。あの人は昔から他人の考えを無視しがちだという、よくない傾向を述べている。", "opts": ["きらいになる：この意味の「きらい」は「〜きらいがある」の形で使い、「きらいになる」では「嫌いになる」と別の意味になってしまう", "", "きらいである：決まった形は「きらいがある」で、「きらいである」とは言わない。「嫌いだ」の意味にとられてしまう", "きらいとなる：この意味の「きらい」は「〜きらいがある」の形でしか使わず、「きらいとなる」という形はない"], "ex": "彼は物事を悪いほうに考える<b>きらいがある</b>。"},
"36017": {"point": "「〜たところで」は「〜しても（無駄だ）」という意味で、後に否定的な予測が続く。今から出発しても開演には間に合わないだろうという、行動しても結果は変わらないという判断を表している。", "opts": ["出発したからか：「〜からか」は「〜のせいか」と理由を推測する表現で、まだ出発していない「今から」と合わない", "出発したところ：「〜たところ」は「〜したら（その結果）」の意で、過去の出来事の結果を述べる。後の推量「〜でしょう」と合わない", "出発したのに：「〜のに」は「出発したのに間に合わなかった」のように、すでに起きた事実への不満を表す。「今から」する行動には使えない", ""], "ex": "どんなに急いだ<b>ところで</b>、最終電車にはもう間に合わない。"},
"36018": {"point": "「〜のいかんを問わず」は「〜に関係なく」という意味の硬い表現。社内のメールは内容がどうであっても、外部へ転送してはいけないという規則を述べている。", "opts": ["", "よらず：「よる」は「〜によらず」と助詞「に」を取る動詞で、「いかんをよらず」という形にならない", "よそに：「〜をよそに」は「親の心配をよそに」のように「〜を気にかけずに」の意で、規則を述べる文に合わない", "よって：「よる」は「〜によって」と助詞「に」を取るので、「いかんをよって」とは言えない"], "ex": "経験の<b>いかんを問わず</b>、やる気のある人を募集しています。"},
"36019": {"point": "「〜かねる」は動詞のます形に付いて「〜することができない」という意味を表し、気持ちの上でできないという場合に使う。「どうも」と合わせ、先方から説明を受けても納得できないという気持ちを表している。", "opts": ["しうる＝することができる。「納得しうる」では納得できる意味になり、「どうも」や「説明を受けたが」の逆接と合わない", "", "しきれる：「〜きれる」は「完全に〜できる」の意で、「納得しきれる」では肯定の可能になり、「どうも」と合わない", "したがる：「〜たがる」は第三者の希望を表す。「私は」を主語にして使えず、意味も合わない"], "ex": "その意見には、どうしても賛成し<b>かねる</b>。"},
"36020": {"point": "「〜てからというもの」は「〜してからずっと」という意味で、ある出来事をきっかけに状態が大きく変わったことを表す。話題のドラマを見てからずっと、主演女優のファンになっているという変化を述べている。", "opts": ["というほど：「〜というほど」は「嫌というほど」のように程度を表し、「見てから」に続かない", "", "とばかりに＝いかにも〜と言いたそうな様子で。「見てから」に付く形はなく、意味も合わない", "ともなると＝〜という立場・段階になると。「見てから」に続かず、意味も合わない"], "ex": "子どもが生まれ<b>てからというもの</b>、毎日が忙しくなった。"},
"36021": {"point": "「〜かねる」は「〜することができない」という意味で、判断などをする立場にありながら、それができないことを表す。まだ結果が出ていない現時点では、今回の決定が正しいかどうか判断できないという意味になる。", "opts": ["判断したがる：「〜たがる」は第三者の希望を表し、「結果が出ていない現時点では」という状況と合わない", "", "判断しきれる：「〜きれる」は「完全に〜できる」の意で、結果が出ていない状況と矛盾する", "判断しすぎない：「〜すぎない」は「度を越さない」の意で、判断できないという意味にならない"], "ex": "本人に会ったこともないので、その人の性格については何とも言い<b>かねる</b>。"},
"36022": {"point": "「いくら〜たところで」は「どんなに〜しても（結果は変わらない）」という意味で、後に否定的な予測が続く。周辺の住民がどんなに反対しても、すでに動きだした開発計画は止まらないだろうという意味になる。", "opts": ["かぎりで：「〜かぎりで」は「今月かぎりで」のように期限や範囲を表し、「いくら」と呼応しない", "", "もので：「〜もので」は「〜なので」と理由を言い訳のように述べる表現で、「いくら」と呼応しない", "ようで：「〜ようで」は「〜みたいで」という推量・様子を表し、「いくら」と呼応しない"], "ex": "いくら頼んだ<b>ところで</b>、あの頑固な父が許してくれるはずがない。"},
"36023": {"point": "「〜だけに」は「〜なので、なおさら」という意味で、その事情から予想される気持ちや結果がいっそう強まることを表す。頑張れば勝てる相手だっただけに、負けた悔しさがいっそう大きいという意味になる。", "opts": ["", "ばかりでなく＝〜だけでなく。後に付け加える内容が必要で、「悔しい気持ち」の理由を表せない", "ほどで：「〜ほど」は程度を表し、「勝てる相手だったほどで」は不自然で意味が通らない", "わけではなく：部分的な否定で、勝てる相手だったことを否定する意味になり、悔しさの理由にならない"], "ex": "期待していた<b>だけに</b>、不合格の知らせはショックだった。"},
"36024": {"point": "「〜てからというもの」は「〜してからずっと」という意味で、ある出来事をきっかけに起きた変化が続いていることを表す。手巻き時計を買ってからずっと、時計を眺めるのが好きになったという変化を述べている。", "opts": ["購入しないにせよ：「〜にせよ」は「〜としても」という譲歩を表し、購入したことによる変化を述べる文に合わない", "購入したかと思うと：「〜たかと思うと」は直後に別の出来事が起こることを表し、その後ずっと続く変化を表せない", "購入してからでないと：「〜てからでないと」の後には「〜できない」などの否定が続き、「好きになった」と合わない", ""], "ex": "スマートフォンを持つようになっ<b>てからというもの</b>、本を読む時間が減った。"},
"36025": {"point": "「〜極まりない」はな形容詞の語幹に付いて「この上なく〜だ」という意味を表す。人がおおぜい通る道に信号がないのは、この上なく危険だという強い評価を述べている。", "opts": ["極める：「極める」は「困難を極める」のように「〜を」をとる他動詞で、「危険極める」とは言わない", "極めない：「極める」の否定で、「この上なく〜だ」という意味にならない", "", "極まっている：「この上なく〜だ」は「危険極まりない」「危険極まる」の形で表し、「極まっている」という形では使わない"], "ex": "雪道をスピードを出して走るなんて、無謀<b>極まりない</b>。"},
"36026": {"point": "「〜たが最後」は「一度〜したら、もう（元には戻らない）」という意味で、後によくない結果が続く。一度退職したら、かつての仕事仲間は誰も訪ねてこなくなるという寂しい結果を表している。", "opts": ["ものなら：「〜ものなら」は「できるものなら」のように可能形に付いて「もし〜できるなら」の意。「退職したものなら」とは言わない", "わけだと：「〜わけだ」は「当然そうなる」という結論を表す文末表現で、「わけだと」の形で後の文にはつながらない", "", "まもなく：「まもなく」は「退職してまもなく」とて形に続く。「退職したまもなく」とは言わない"], "ex": "あの人にお金を貸した<b>が最後</b>、二度と返ってこない。"},
"36027": {"point": "「〜とあって」は「〜という特別な事情なので」という意味で、後にその事情による結果が続く。3人の人気女優がそろうという特別な事情があったので、会場に100人以上の報道陣が詰めかけたという意味になる。", "opts": ["とすると：「〜とすると」は「〜と仮定すると」の意で、すでに起きた出来事の理由を述べる文に合わない", "とされても：「〜とされる」は「〜と考えられる」の意で、「とされても」では「〜と言われても」という逆接になり、意味が通らない", "", "とあっても：「〜とあっても」は「〜という事情であっても」という逆接で、報道陣が詰めかけたという順当な結果と合わない"], "ex": "有名な歌手が来る<b>とあって</b>、会場は朝から大勢の人で混雑していた。"},
"36028": {"point": "「〜きらいがある」は「〜という（よくない）傾向がある」という意味で、動詞の辞書形などに付く。自分には一人で勉強すると怠ける傾向があるので、大勢で勉強したいという意味になる。", "opts": ["きざしがある：「きざし」は「回復のきざし」のように、これから起こる変化の前ぶれを表し、性格的な傾向には使わない", "", "つもりである：「つもり」は意志・予定を表し、「怠けるつもりである」では自分から怠けようとする意味になり、文脈に合わない", "べきである：「〜べきだ」は当然の義務を表し、「怠けるべきである」では意味が通らない"], "ex": "私は忙しくなると、食事をおろそかにする<b>きらいがある</b>。"},
"36029": {"point": "「〜のいかんによっては」は「〜次第では」という意味で、後には「〜こともある・〜かねない」などの悪い可能性が続くことが多い。山登りは体にいいが、本人の健康状態によっては危険な事故に遭うおそれもあるという意味になる。", "opts": ["というより：「〜というより」は「AというよりB」と比べて言い直す表現で、「いかん」には付かない", "ともなると＝〜という段階・立場になると。「いかん」には付かず、意味も合わない", "", "をよそに＝〜を気にかけずに。「いかんをよそに」とは言わず、注意を促す文の意味とも合わない"], "ex": "天候<b>のいかんによっては</b>、試合が中止になる場合もあります。"},
"36030": {"point": "「〜のいかんによらず」は「〜に関係なく」という意味の硬い表現で、規則や通知などによく使われる。商品到着から8日間を過ぎた返品・交換には、理由がどうであっても応じられないという店の規則を述べている。", "opts": ["というより：「〜というより」は「AというよりB」と比べて言い直す表現で、「理由というより応じられない」では意味が通らない", "のしだいで：「次第」は「理由次第で」と名詞に直接付き、「の」は入らない。また「理由によっては」の意になり、一律に断る文と合わない", "にしたがって：「〜にしたがって」は「〜に従って・〜につれて」の意で、「理由に従って応じられない」では意味が通らない", ""], "ex": "年齢や国籍<b>のいかんによらず</b>、どなたでも参加できます。"},
"36031": {"point": "「〜かねます」は「（丁寧に）〜できません」という意味で、謙譲語「お答えする」と合わせて、客の要望を丁寧に断るときに使う。「大変申し訳ありませんが」と謝った後なので、断りの表現が入る。", "opts": ["お答えしきれます：「〜きれます」は「完全に〜できる」という肯定の可能で、「申し訳ありませんが」という断りの流れに合わない", "", "お答えしえます：「〜しえる」は「〜することができる」の意で、謝ってから断る文に合わない", "お答えされます：謙譲語「お〜する」に尊敬の「れる」を付けた誤った敬語で、断りの意味もない"], "ex": "恐れ入りますが、こちらの商品の返品はお受けし<b>かねます</b>。"},
"36032": {"point": "「〜のいかんを問わず」は「〜に関係なく」という意味の硬い表現。「いかん」は「どうであるか」という意味の名詞で、事情がどうであっても、期限に遅れた卒業論文は受け付けないという厳しい規則を述べている。", "opts": ["", "しまつ：「〜しまつだ」は「（悪い結果）になってしまう」の意の文末表現で、「事情のしまつを問わず」とは言わない", "ゆえ：「ゆえ」は「〜ゆえに」と理由を表す語で、「事情のゆえを問わず」とは言わない", "すききらい：「好き嫌い」は好みを表す名詞で、「事情の好き嫌いを問わず」では意味が通らない"], "ex": "結果の<b>いかんを問わず</b>、参加者全員に記念品が贈られる。"},
"36033": {"point": "「〜てからというもの」は「〜してからずっと」という意味で、ある出来事をきっかけに状態が変わり、それが続いていることを表す。不景気になってからずっと、ブランド品の売り上げが大幅に落ち込んでいるという意味になる。", "opts": ["なったところで：「〜たところで」は「〜しても（無駄だ）」の意で、後に否定的な予測が続く。売り上げが落ちている事実を述べる文に合わない", "なったかと思うと：「〜たかと思うと」は直後に別のことが起こる意で、続いている状態を表せない", "なってからでなければ：「〜てからでなければ」の後には「〜できない」などの否定が続き、この文と合わない", ""], "ex": "一人暮らしを始め<b>てからというもの</b>、親のありがたさがよく分かるようになった。"},
"36034": {"point": "「〜きらいがある」は「〜という（よくない）傾向がある」という意味で、人の性格や行動の悪い傾向を批判的に述べる。彼には他人を見かけだけで判断する悪い傾向があるという意味になる。", "opts": ["かぎり：「時間にはかぎりがある」のように「限度」を表す名詞で、「判断するかぎりがある」では意味が通らない", "しまつ：「〜しまつだ」は悪い結果に至ることを表す文末表現で、「しまつがある」という形はない", "", "しだい：「〜次第」は「〜したらすぐに」「〜によって決まる」の意で、「しだいがある」という形はない"], "ex": "彼は何でも一人で抱え込む<b>きらいがある</b>。"},
"36035": {"point": "「〜たところで」は「〜しても（無駄だ）」という意味で、後に否定的な予測が続く。疑問詞と合わせた「何を言ったところで」は「何を言っても」の意となり、彼は耳を貸さないだろうという意味になる。", "opts": ["", "ところでも：「〜たところで」がすでに「〜ても」の意を含むため、「も」を付けた「ところでも」という形は使わない", "とは：「〜とは」は驚きや定義を表し、「何を言ったとは」では意味が通らない", "もので：「〜もので」は「〜なので」と言い訳のように理由を述べる表現で、「何を」と呼応せず意味が通らない"], "ex": "今さら何をした<b>ところで</b>、もう手遅れだ。"},
"36036": {"point": "「〜いかんで」は名詞に付いて「〜によって（決まる）」という意味を表す硬い表現。今年度の業績がどうなるかによっては、この会社は倒産するおそれもあるという意味になる。", "opts": ["", "いかに：「いかに」は「いかに〜ても」のように「どんなに」の意の副詞で、名詞「業績」の後には置けない", "のしだいで：「次第」は「業績次第で」と名詞に直接付き、「の」は入らない", "しだいに：「次第に」は「だんだん」の意の副詞で、「〜によって」の意味にならない"], "ex": "本人の努力<b>いかんで</b>、結果は大きく変わるだろう。"},
"36037": {"point": "「〜たが最後」は「一度〜したら、もう（〜ない）」という意味で、後によくない結果が続く。「〜ときたら」で息子への不満を述べ、一度遊びに出たら暗くなるまで戻ってこないという意味になる。", "opts": ["しまつ：「〜しまつだ」は「（悪い結果）になってしまう」の意の文末表現で、「〜たがしまつ」という形はない", "しまい：「しまい」は「終わり」の意の名詞で、「〜たがしまい」という形はない", "", "終わり：「〜たが終わり」という形はなく、「一度〜したら、もう」という意味を表せない"], "ex": "彼は一度寝た<b>が最後</b>、何をしても起きない。"},
"36038": {"point": "「〜とあって」は「〜という特別な事情なので」という意味で、後にその事情による結果が続く。イギリスの人気サッカーチームが来日するという特別な事情なので、空港にファンが殺到したという意味になる。", "opts": ["して：「〜として」は「〜という立場で」や「〜と仮定して」の意で、ファンが殺到した理由を表せない", "いっては：「〜といっては」は「何かといっては文句を言う」のように、そのたびに同じことをする意で、意味が合わない", "すると：「〜とすると」は「〜と仮定すると」の意で、すでに起きた出来事の理由を述べる文に合わない", ""], "ex": "久しぶりに晴れた休日<b>とあって</b>、公園は家族連れでいっぱいだった。"},
"36039": {"point": "「〜極まる」はな形容詞の語幹に付いて「この上なく〜だ」という意味を表し、「退屈極まる話」のように名詞を修飾することもできる。女の人にはおもしろくても、自分にはこの上なく退屈な話だという意味になる。", "opts": ["極めて＝非常に。副詞なので「極めて退屈な話」のように前に置く。「退屈極めて話」とは言えない", "極める：「極める」は「困難を極める」のように「〜を」をとる他動詞で、「退屈極める話」とは言わない", "極まって：て形では名詞「話」を修飾できず、「退屈極まって話」は文として成り立たない", ""], "ex": "彼の態度は無礼<b>極まる</b>ものだった。"},
"36040": {"point": "「〜だけあって」は「さすが〜なので（それにふさわしく）」という意味で、評価する気持ちを表す。有機栽培の農家から野菜を直接送ってもらっているので、それにふさわしく料理の評判がよく、店がにぎわっている。", "opts": ["もらっているにすぎず：「〜にすぎない」は「ただ〜だけだ」と価値を低く言う表現で、店がにぎわっているという評価と合わない", "もらったからには：「〜からには」の後には「〜べきだ」など話し手の判断・決意が続き、店がにぎわっている事実を述べる文に合わない", "", "もらっていたところ：「〜ていたところ（に）」は「〜しているちょうどその時」の意で、店がにぎわう理由を表せない"], "ex": "さすが長年続いている店<b>だけあって</b>、どの料理もおいしい。"},
"36041": {"point": "「〜とはいえ」は「〜けれども」という意味の逆接で、前のことから予想されることとは違う事実を述べる。梅雨が明けて暑くなったけれども、朝夕はまだ涼しくて少し寒いくらいだという意味になる。", "opts": ["からには：「〜からには」の後には「〜べきだ・〜つもりだ」など話し手の判断・決意が続き、気温の事実を述べる文に合わない", "としたら：「〜としたら」は仮定を表し、すでに梅雨が明けた事実を述べる文に合わない。逆接にもならない", "", "こともあって：「〜こともあって」は理由を表し、「暑くなったので涼しい」という矛盾した文になる"], "ex": "春<b>とはいえ</b>、まだ朝晩は冷え込む。"},
"36042": {"point": "「〜ともなれば」は「〜という時・立場になると（当然）」という意味で、後にはその場合に当然起こることが続く。普段から人気のある広場なので、週末になれば当然大勢の利用客で賑わうという意味になる。", "opts": ["につき＝〜なので（掲示などに使う硬い表現）。「工事中につき」のように使い、週末に賑わうという一般的な傾向に合わない", "", "をもって＝〜で、〜によって。「本日をもって」のように手段や区切りを表し、意味が合わない", "を限りに＝〜を最後に。「今日を限りに」のように終わりを表し、意味が合わない"], "ex": "年末<b>ともなれば</b>、デパートは買い物客で混雑する。"},
"36043": {"point": "「〜ながらも」は動詞のます形などに付いて「〜けれども」という意味の逆接を表す。さまざまな苦難にあったけれども、諦めることなく最初の志を貫いたという意味になる。", "opts": ["", "あったとたんに：「〜たとたんに」は「〜したらすぐに」の意で、逆接の意味にならず、「諦めることなく」とつながらない", "あうともなると：「〜ともなると」は「〜という段階・立場になると当然」の意で、逆接の意味にならず、「諦めることなく」とつながらない", "あったうえに：「〜うえに」は「〜に加えて」と同じ方向のことを重ねる表現で、逆接にならない"], "ex": "彼は体が小さい<b>ながらも</b>、チームの誰よりも力強いプレーを見せた。"},
"36044": {"point": "「〜なくしては」は名詞に付いて「〜がなければ」という意味を表し、後に「〜ない・〜できない」などの否定が続く。相手を理解しようとする思いやりがなければ、人間関係は成り立たないという意味になる。", "opts": ["があってこそ：「〜てこそ」の後には「成り立つ」など肯定の結果が続き、文末の「成り立たない」と合わない", "にあるとはいえ：「〜とはいえ」は逆接で、「思いやりにある」という形も不自然。意味が通らない", "", "こそないまでも：「〜ないまでも」は「〜ほどではなくても、せめて」の意で、後の「成り立たない」と意味がつながらない"], "ex": "皆さんのご協力<b>なくしては</b>、この計画は実現できませんでした。"},
"36045": {"point": "「〜といったらない」は「とても〜だ（言葉で言い表せないほどだ）」という意味で、感情の程度が非常に大きいことを表す。受験は大変だったが、合格したときのうれしさは言葉にできないほど大きかったという意味になる。", "opts": ["はありえなかった：「ありえない」は「起こるはずがない」の意で、実際に感じたうれしさを否定することになり矛盾する", "にすぎなかった：「〜にすぎない」は「ただ〜だけだ」と程度を低く言う表現で、合格の喜びを表す文に合わない", "", "ほどのことではなかった：「大したことではなかった」の意で、うれしさが小さかったことになり、文脈に合わない"], "ex": "初めて富士山の頂上に立ったときの感動<b>といったらなかった</b>。"},
"36046": {"point": "「〜とはかぎらない」は「必ずしも〜ではない」という意味で、「必ずしも」「〜からといって」と呼応する。医者であっても、必ずしも自分の健康に気をつけているわけではないという意味になる。", "opts": ["はずである：「〜はずだ」は当然そうだという確信を表し、「〜からといって」「必ずしも」と呼応しない", "に違いない：「〜に違いない」は強い確信を表し、「必ずしも」と呼応しない", "といえなくもない：「〜といえないこともない」と控えめに肯定する表現で、「必ずしも」と呼応しない", ""], "ex": "高い料理が、必ずしもおいしい<b>とはかぎらない</b>。"},
"36047": {"point": "「〜なしには」は名詞に付いて「〜がなければ」という意味を表し、後に否定の表現が続く。コーヒーが大好きなので、コーヒーがなければ一日が始まらないという意味になる。", "opts": ["なくても：「コーヒー（が）なくても」は「ない場合でも」の意で、後の「一日が始まらない」と意味がつながらない", "ないから：「コーヒー（が）ないから」は理由を表す形で、「〜がなければ…ない」という条件を表せない", "ないのに：「〜のに」は逆接で、「コーヒーがないのに一日が始まらない」では意味が通らない", ""], "ex": "家族の支え<b>なしには</b>、ここまで来ることはできなかった。"},
"36048": {"point": "「〜と思いきや」は「〜と思ったが、意外にも」という意味で、予想と違う結果が後に続く。5年もアメリカに住んでいたので英語がうまいだろうと思ったが、意外にも大したことはなかったという意味になる。", "opts": ["思えばこそ：「〜ばこそ」は「〜からこそ」と理由を強調する表現で、予想が外れたという文脈に合わない", "", "思うなら：「〜なら」は仮定や条件を表し、予想と違う結果を表せない", "思ったとあって：「〜とあって」は「〜という特別な事情なので」の意で、逆接にならず、予想が外れたという文脈に合わない"], "ex": "簡単に勝てる<b>と思いきや</b>、相手チームは予想以上に強かった。"},
"36049": {"point": "「〜にいたる」は「（ある結果・段階に）なる」という意味で、さまざまな経過の末に重大な結果になったことを表す。路線の一部廃止という結果になった経緯について、住民に説明したという意味になる。", "opts": ["にもまして＝〜以上に。比較を表す表現で、名詞「経緯」を修飾できず意味も通らない", "", "にかぎった：「〜にかぎったことではない」の形で使い、「廃止にかぎった経緯」では意味が通らない", "にわたった：「〜にわたる」は「3日間にわたる」のように期間や範囲に付く表現で、「廃止」には付かない"], "ex": "長い話し合いの末、両社は合併する<b>にいたった</b>。"},
"36050": {"point": "「〜ないまでも」は「〜はできなくても、せめて」という意味で、後に「せめて〜・〜ぐらいは」など最低限のことが続く。忙しくて見舞いに行けなくても、せめて電話ぐらいはしておこうという意味になる。", "opts": ["うちに：「〜ないうちに」は「〜しないうちに（その前に）」の意で、「見舞いに行けないうちに電話ぐらいは」では意味が通らない", "かぎり：「〜ないかぎり」は「〜しなければ（〜ない）」という条件を表し、後の「電話ぐらいは」と呼応しない", "ことには：「〜ないことには」の後には「〜できない」など否定の結果が続き、「電話ぐらいはしておこう」と合わない", ""], "ex": "毎日とは言わ<b>ないまでも</b>、週に一度は連絡してほしい。"},
"36051": {"point": "「〜ともなれば」は「〜という時になると（当然）」という意味で、後にはその時に当然起こることが続く。連休や夏休みという時期になると、当然空港は旅行に出かける人々でごった返すという意味になる。", "opts": ["からすると＝〜から判断すると。判断の根拠を表し、時期を表す「連休や夏休み」とは合わない", "と思いきや＝〜と思ったが、意外にも。予想外の結果が続く表現だが、空港が混むのは当然のことで合わない", "", "にせよ＝〜にしても。譲歩を表し、空港が混雑するという当然の結果と合わない"], "ex": "12月<b>ともなれば</b>、街はクリスマスの飾りで華やかになる。"},
"36052": {"point": "「〜ないまでも」は「〜とまではいかなくても」という意味で、後に「少なくとも〜は」という程度の低いことが続く。試験中の不正行為で、退学にまではならなくても停学処分は受けるだろうという意味になる。", "opts": ["なるまでもなく：「〜までもなく」は「〜する必要もなく」の意で、「退学になる必要もなく」となり意味が通らない", "", "なるに及ばず：「〜に及ばず」は「〜する必要はない」の意で、処分の程度を比べる文に合わない", "ならないことではなく：決まった言い方ではなく、「退学とまではいかなくても」という意味を表せない"], "ex": "優勝はでき<b>ないまでも</b>、せめて決勝には進みたい。"},
"36053": {"point": "「〜なくして」は名詞に付いて「〜がなければ」という意味を表し、後に「〜ありえない」など否定の表現が続く。魅力的な新商品の開発がなければ、会社の成長はありえないという意味になる。", "opts": ["どおりに＝〜のとおりに。「計画どおりに」のように使い、後の「ありえない」と意味がつながらない", "ならでは＝〜だけが持つ特別な。「〜ならではの」の形で名詞を修飾する表現で、ここでは意味がつながらない", "に限らず＝〜だけでなく。「開発に限らず会社の成長はありえない」では意味が通らない", ""], "ex": "努力<b>なくして</b>成功はありえない。"},
"36054": {"point": "「〜かと思いきや」は「〜と思ったが、意外にも」という意味で、予想と違う結果が後に続く。店の前に大勢並んでいたので長く待たされると思ったが、意外にもすぐに席に案内されたという意味になる。", "opts": ["待たされたことと思うが：「〜ことと思う」は「さぞお疲れのことと思う」のように相手の状況を推し量る表現で、この文に合わない", "", "待たされたかと思えば：「〜たかと思えば」は「〜したと思ったらすぐに」と変化が続く意で、実際には待たされていない事実と矛盾する", "待たされることと思い：「待たされるだろうと思って」の意で、後にはその考えに基づく行動が続く。「意外にも」とつながらない"], "ex": "会議はすぐに終わる<b>かと思いきや</b>、3時間も続いた。"},
"36055": {"point": "「〜とはいえ」は「〜ではあっても」という意味の逆接で、前のことを認めながら、それと食い違う気持ちや判断を後に述べる。仕事だから仕方がないことではあっても、3カ月も海外出張するのは大変だろうという意味になる。", "opts": ["", "にそって＝〜に従って。「方針にそって」のように基準を表し、意味が合わない", "とばかりに＝いかにも〜と言いたそうな様子で。人の態度を表す表現で、この文に合わない", "にそくして＝〜に合わせて、〜を基準にして。「事実にそくして」のように使い、意味が合わない"], "ex": "安い<b>とはいえ</b>、毎日外食をしていたらお金がかかる。"},
"36056": {"point": "「〜から〜にいたるまで」は「〜から〜まで全部」という意味で、範囲の広さを強調する。この百円ショップでは皿からタオルまで、さまざまな物が何でも買えるという意味になる。", "opts": ["いたりで：「いたり」は「光栄のいたり」のように「この上ない〜」の意の名詞で、「〜から」と呼応して範囲を表せない", "", "いたっては：「〜にいたっては」は極端な例を挙げる表現で、「〜から」と呼応しない", "いたっても：「〜にいたっても」は「〜という段階になっても」の意で、範囲を表せない"], "ex": "その事件は、子ども<b>から</b>老人<b>にいたるまで</b>、誰もが知っている。"},
"36057": {"point": "「〜とは限らない」は「必ずしも〜ではない」という意味で、例外がありうることを表す。実力のあるチームがいつも勝つわけではないので、自分たちも勝てるようにがんばりたいという流れになる。", "opts": ["のではないか：「〜のではないか」は推測を表し、「強いチームが勝つのではないか」では、後の「勝てるようにがんばりたい」と合わない", "", "ということだ：伝聞や結論を表し、「いつも勝つということだ」では、強いチームに勝とうとする後の文と合わない", "に決まっている：「必ず〜だ」という強い断定で、「勝てるようにがんばりたい」と矛盾する"], "ex": "有名な大学を出た人が、仕事ができる<b>とは限らない</b>。"},
"36058": {"point": "「〜といったらありはしない」は「とても〜だ（言葉で言い表せないほどだ）」という意味で、「〜といったらない」と同じく不満などの強い気持ちを表す。雨に降られ、財布を落とし、遅刻もしたひどい一日だったという気持ちを強調している。", "opts": ["ほかない：「〜ほかない」は「〜するしかない」の意で動詞に付く。「といったらほかない」という形はない", "ならない：「〜てならない」は「心配でならない」の形で使い、「といったらならない」という形はない", "ちがいない：「〜にちがいない」は確信を表し、「といったら」の後に続く形はない", ""], "ex": "満員電車に一時間も立ちっぱなしで、疲れる<b>といったらありはしない</b>。"},
"36059": {"point": "「〜なしには〜ない」は「〜がなければ〜できない」という意味で、「なしには」の後には否定の表現が続く。優れた技術開発がなければ、この会社の発展はありえなかっただろうという意味になる。", "opts": ["あったにちがいない：肯定の表現で、「なしには」の後に否定が来ないため、「技術開発がなくても発展があった」という意味になってしまう", "ありうるのではないだろうか：「なしには」の後に肯定の推量が来て、技術開発がなくても発展できるという意味になる", "", "あるわけではない：部分否定で、「なしには」と組み合わせても「〜がなければ〜できない」という意味にならない"], "ex": "地域の人々の協力<b>なしには</b>、この祭りは続けられ<b>ない</b>。"},
"36060": {"point": "「〜ながらも」は「〜けれども」という意味の逆接で、前と後で予想に反する事柄を結ぶ。多くのすばらしい作品を残したけれども、生きている間は絵がほとんど売れず貧しい生活を送ったという意味になる。", "opts": ["残さんがため＝残すために（硬い表現）。目的を表し、作品を残したのに貧しかったという逆接の文に合わない", "", "残すともなれば：「〜ともなれば」は「〜という段階になれば当然」の意で、逆接の意味にならない", "残そうものなら：「〜ようものなら」は「もし〜したら大変なことになる」という仮定を表し、事実を述べる文に合わない"], "ex": "狭い<b>ながらも</b>、日当たりのいい部屋で気に入っている。"},
"36061": {"point": "「〜からといって〜とは限らない」は「〜だからといって、必ず〜というわけではない」という意味。学校の成績がよかったとしても、社会に出て必ず成功するわけではないという意味になる。", "opts": ["成功するに相違ない：「〜に相違ない」は「〜に違いない」という確信を表し、「〜からといって」と呼応しない", "", "成功するにほかならない：「〜にほかならない」は「まさに〜だ」と断定する表現で、「〜からといって」と呼応しない", "成功するかもしれない：可能性を表し、「〜からといって」の後に続く否定の内容にならない"], "ex": "日本人だ<b>からといって</b>、敬語が正しく使える<b>とは限らない</b>。"},
"36062": {"point": "「〜にいたって」は「〜という段階になって（やっと）」という意味で、事態が深刻になって初めて行動することを表す。「ようやく」と呼応し、副作用が社会問題になるところまで来て、政府がやっと実態調査を始めたという意味になる。", "opts": ["", "ひきかえ：「〜にひきかえ」は「〜とは反対に」と二つを対比する表現で、「ようやく」と呼応せず、意味が合わない", "わたって：「〜にわたって」は「10年にわたって」のように期間や範囲に付く表現で、動詞の辞書形には付かない", "かぎって：「〜にかぎって」は「〜のときに限って（悪いことが起こる）」の意で、「ようやく」と呼応せず、意味が合わない"], "ex": "死者が出る<b>にいたって</b>、ようやく安全対策が見直された。"},
"36063": {"point": "「～といったらない」は「とても～だ、言葉で言い表せないほど～だ」という意味で、程度が極端であることを感情を込めて表す。あのレストランの料理がひどくまずいことを強調している。", "opts": ["おそれがある：「～おそれがある」は「（悪いことが）起こる可能性がある」という意味で、料理の味についての評価を述べるこの文に合わない", "かぎりだ：「～かぎりだ」は「うれしい・寂しい」など話し手自身の感情を表す語に付いて「とても～と感じる」を表す。料理の性質を述べる「まずい」には使わない", "", "きわまりない：「～きわまりない」は「失礼きわまりない」のように主にナ形容詞の語幹に付き、イ形容詞「まずい」には付かない"], "ex": "夜中に一人で山道を歩く怖さ<b>といったらない</b>。"},
"36064": {"point": "「～ながらも」はます形などに付いて「～けれども、～のに」という逆接を表す。休暇を存分に楽しむと言っているのに、実際には仕事のことが頭から離れないという、言葉と実際の食い違いを表している。", "opts": ["にあたり：「～にあたり」は「～する時に、～に際して」という意味で、辞書形や名詞に付く。ます形「言い」には付かず、逆接の意味もない", "とおして：「～をとおして」は「～を通じて」という意味で、名詞に「を」を付けて使う。ます形には付かず、意味も合わない", "", "ながらに：「～ながらに」は「涙ながらに・生まれながらに」のように限られた語に付いて「～のまま」という状態を表す。逆接の意味はない"], "ex": "彼は文句を言い<b>ながらも</b>、最後まで仕事を手伝ってくれた。"},
"36065": {"point": "「～なくしては」は名詞に付き「～がなければ（…できない）」という意味で、後に否定や困難を表す表現が続く。映画が非常に感動的なので、涙を流さずには見られないという文意に合う。", "opts": ["なくとも：「なくても」の書き言葉。「涙がなくても見られない」という意味になり、感動して涙が出るという文意に合わない", "", "ないまでも：「～ないまでも」は「～とまではいかなくても」という意味で、動詞のない形に付く。名詞「涙」には直接付かず、意味も合わない", "なかろうと：「～なかろうと」は「～なくても（関係なく）」という意味で、後の「見られない」とつながらず、意味が通らない"], "ex": "地域の人々の協力<b>なくしては</b>、この祭りを続けることはできない。"},
"36066": {"point": "「～なしには」は名詞に付き「～がなければ（…できない）」という意味で、後に否定的な表現が続く。信頼関係がなければ仕事はうまくいかないという条件を表し、文末の「うまくいくはずがない」と呼応する。", "opts": ["", "ともなると：「～ともなると」は「～という時期・立場になると」という意味で、「信頼関係ともなると」では意味が通らない", "ともなく：「～ともなく」は「見るともなく」のように動詞の辞書形に付き、「特に～しようという意識もなく」を表す。名詞には付かず、意味も合わない", "なくて：名詞に直接「なくて」を付けた不自然な形で、「～がなくて」としても原因を表すだけで、「～がなければ」という条件の意味にならない"], "ex": "家族の支え<b>なしには</b>、ここまで来ることはできなかった。"},
"36067": {"point": "「～とはいえ」は「～けれども、～とは言っても」という逆接で、前の事実から予想されることとは違う内容が後に続く。資格を取ったという事実はあっても、不景気のためいい仕事を見つけるのは大変だという文意に合う。", "opts": ["", "からこそ：「～からこそ」は理由を強調する表現で、「資格を取ったからこそ大変だ」となり、逆接の文意に合わない", "ともなると：「～ともなると」は「～という時期・立場になると」という意味で、資格を取ったのに仕事が見つからないという逆接の関係を表せない", "にひきかえ：「～にひきかえ」は「～とは反対に」と二つのものを対比する表現で、この文には比べる対象がなく合わない"], "ex": "春になった<b>とはいえ</b>、朝晩はまだ寒い日が続いている。"},
"36068": {"point": "「～ないまでも」は「～とまではいかなくても」という意味で、程度の高いことはしなくても、それより低い程度のことはする、と続く。徹夜まではしなくても、睡眠時間を削るくらいはしなければならないという文意に合う。", "opts": ["しないほどで：「徹夜はしないほどで」という言い方はなく、意味が通らない", "するに及ばず：「～に及ばず」は「～する必要はない」という意味で、締め切りが迫って睡眠時間を削らなければならない状況と合わない", "", "しながら：「～ながら」は同時進行か逆接を表し、「徹夜はしながら睡眠時間を削る」では意味が通らない"], "ex": "優勝はでき<b>ないまでも</b>、せめて決勝には進みたい。"},
"36069": {"point": "「～ともなると」は「～という時期・立場・段階になると」という意味で、その状況になると普段とは違う様子になることを表す。紅葉の季節になると、ふだんは静かな町が観光客でにぎやかになるという文意に合う。", "opts": ["ともすると：「ともすると」は「ともすると怠けがちだ」のように「どうかすると～しがちだ」という意味の副詞で、名詞の後に付いて時期を表すことはない", "", "とはいえ：「～とはいえ」は「～けれども」という逆接で、「紅葉の季節とはいえ、にぎやかになる」では逆接の関係が成り立たない", "といっても：「～といっても」は「～と言っても実際は（大したことはない）」と前の内容を一部打ち消す表現で、文意に合わない"], "ex": "毎日忙しい父も、正月<b>ともなると</b>家でのんびり過ごしている。"},
"36070": {"point": "「～と思いきや」は「～と思ったが、意外にも（そうではなかった）」という意味で、後には予想と反対の結果が続く。写真を見ていいレストランだと思ったが、実際はそれほどでもなかったという意外な結果を述べる文が入る。", "opts": ["思ったとおりに本当によかった：予想どおりの結果を述べており、予想が外れたことを表す「～と思いきや」と合わない", "行ってみてもよさそうだ：これからのことについての推測で、「～と思いきや」の後に必要な、予想に反した実際の結果になっていない", "行ってみたらどうだ：相手への提案であり、「～と思いきや」の後に提案や意志の表現は続かない", ""], "ex": "今日は晴れると<b>思いきや</b>、午後から急に雨が降り出した。"},
"36071": {"point": "「～をおいて（他に）ない」は「～以外にはいない・ない」という意味で、その人や物を最も高く評価する表現。この仕事ができるのは君しかいないと、相手の能力を高く評価している。", "opts": ["といったらありゃしない：「～といったらありゃしない」は「とても～だ」という意味の話し言葉で、「君といったらありゃしない」では意味が通らない", "にかたくない：「～にかたくない」は「想像にかたくない」のように「簡単に～できる」という意味で、「君にかたくない」では意味が通らない", "", "でなくてなんだろう：「これが運命でなくてなんだろう」のように「まさに～だ」と事柄を強く評価する表現で、「君以外にいない」と人を限定する意味にならない"], "ex": "次期社長にふさわしいのは、田中さん<b>をおいて他にいない</b>。"},
"36072": {"point": "「～ものなら」は可能形に付いて「もし～できるなら」という意味で、実現が難しいことを強く望む気持ちを表し、後に「～たい」などが続く。スケジュールがつまっていて難しいが、姉の結婚のためにできれば帰りたいという気持ちに合う。", "opts": ["帰るにとどまらず：「～にとどまらず」は「～だけでなく（範囲が広がる）」という意味で、「帰るにとどまらず帰りたい」では意味が通らない", "", "帰るにしても：「～にしても」は「仮に～するとしても」という意味で、後に条件や判断が続く。「帰るにしても帰りたい」では意味が通らない", "帰るのにひきかえ：「～にひきかえ」は「～とは反対に」と二つのものを対比する表現で、この文には比べる対象がなく合わない"], "ex": "子どものころに戻れる<b>ものなら</b>、もう一度やり直したい。"},
"36073": {"point": "「～ばこそ」は「～からこそ」という意味で、理由を強調する。仮定形「いれば」に「こそ」が付き、親があれこれ言うのはあなたの将来を心配しているからだ、という理由を強く述べている。", "opts": ["", "いたら：「こそ」と結び付いて理由を強調するのは「ば」の形で、「たら」の後に「こそ」を付けて「～からこそ」の意味にはならない", "いるなら：「なら」は仮定や話題を表し、後に「こそ」を付けて理由を強調する形にはならない", "いたなら：過去の仮定を表す形で、「こそ」とともに理由を強調する「～ばこそ」の形にならない"], "ex": "厳しく注意するのも、君に期待してい<b>ればこそ</b>だ。"},
"36074": {"point": "「～がゆえに」は「～が理由で」という意味の硬い表現で、原因・理由を表す。母親が有名な歌手であることが理由で、彼女が大きなプレッシャーに苦しんできたという因果関係に合う。", "opts": ["かというと：「～かというと」は「～かと言えば（そうではない）」などと問いを示して説明する表現で、理由を表さない", "といえば：「～といえば」は話題を取り上げて、そこから連想することを述べる表現で、因果関係を表さない", "", "ように：「～ように」は目的や様子・例示を表し、「歌手であるように」では理由の意味にならない"], "ex": "正直である<b>がゆえに</b>、彼は損をすることも多い。"},
"36075": {"point": "「AはおろかB（も・さえ・すら）」は「Aはもちろん、Bも」という意味で、程度の高いAは当然として、程度の低いBさえできないことを表す。運動はもちろん、歩くことさえ大変だという文意で、後の「すら」と呼応している。", "opts": ["にかまけて：「～にかまけて」は「～に気を取られて（他のことをおろそかにする）」という意味で、「運動にかまけて」では文意が通らない", "といえども：「～といえども」は「～であっても」という逆接で、「運動といえども歩くことすら大変だ」では意味が通らない", "", "をふまえて：「～をふまえて」は「～を根拠・前提として」という意味で、文意に合わない"], "ex": "忙しくて、旅行<b>はおろか</b>、近所を散歩する時間さえない。"},
"36076": {"point": "「～までもない」は辞書形に付き「わざわざ～する必要はない（当然のことだ）」という意味。学生にとって勉学が最優先なのは当然なので、今さら言う必要もないという文意に合い、「今さら」とも呼応している。", "opts": ["きらいがある：「～きらいがある」は「（よくない）傾向がある」という意味で、「今さら言うきらいがあることだ」では意味が通らない", "", "よりほかない：「～よりほかない」は「～するしか方法がない」という意味で、当然のことだから言う必要はないという文意と合わない", "必要がある：「言う必要がある」では、当然のことだから今さら言わなくていいという文意と反対になり、「今さら」「～などと」とも合わない"], "ex": "健康のために睡眠が大切なのは、言う<b>までもない</b>。"},
"36077": {"point": "「～をよそに」は「～を気にしないで、無視して」という意味で、周囲の心配や反対を顧みずに物事が進む様子を表す。住民の不安が広がっているのに、それを気にせず建設工事が進められているという文意に合う。", "opts": ["はもとより：「～はもとより」は「～はもちろん」という意味で、「不安が広がるのはもとより工事は進められている」では意味が通らない", "はやはり：「やはり」は「予想どおり」という意味の副詞で、前後をつなぐ働きがなく文が成り立たない", "", "をかぎりに：「～をかぎりに」は「今日をかぎりに」のように時を表す語に付き、「～を最後に」という意味。文意に合わない"], "ex": "親の心配<b>をよそに</b>、息子は一人で海外へ旅立った。"},
"36078": {"point": "「～ようにも～ない」は意向形に付き、同じ動詞の可能形の否定と組み合わせて「～しようとしても、（事情があって）できない」という意味を表す。来客の相手をしなければならず、出かけたくても出かけられなかったという文意に合う。", "opts": ["", "出かけなかった：自分の意志で出かけなかったという意味になり、「～ようにも」の後に必要な可能形の否定になっていない", "出かけて行った：実際に出かけたことになり、出かけようとしてもできなかったという文意と矛盾する", "出かけずにいた：「～ずにいた」は「～しないでいた」という状態を表し、可能の否定ではないので「～ようにも」と呼応しない"], "ex": "足をけがして、歩こう<b>にも歩けない</b>。"},
"36079": {"point": "「～にひきかえ」は「～とは反対に、～と比べて」という意味で、二つのものを対比し、後のほうを否定的に述べることが多い。日本の女性ががんばったのと対照的に、男性はいい成績を残せなかったという対比に合う。", "opts": ["", "をぬきには：「～をぬきには」は「～を除いては（～できない）」という意味で、後に否定や困難を表す表現が続く。男女を対比するこの文に合わない", "はもとより：「～はもとより」は「～はもちろん（…も）」と同じ方向のことを付け加える表現で、反対の内容を対比するこの文に合わない", "をものともせずに：「～をものともせずに」は「困難などを問題にしないで」という意味で、「がんばったのをものともせずに」では意味が通らない"], "ex": "都会の便利な生活<b>にひきかえ</b>、田舎の暮らしは不便なことも多い。"},
"36080": {"point": "「～んばかりに」は動詞のない形に付き、「今にも～しそうなほど」という意味。受身「飛ばされる」のない形「飛ばされ」に「ん」が付いた形で、激しい風に今にも飛ばされそうになりながら家路を急ぐ様子を表している。", "opts": ["飛ばさなかったばかりに：「～たばかりに」は「～したことが原因で（悪い結果になった）」という意味で、「飛ばさなかった」では意味が通らず、後の「なりながら」にもつながらない", "", "飛ばしたばかりに：「～たばかりに」は「～したせいで」という原因を表す。能動形なので人々が何かを飛ばしたことになり、文意に合わない", "飛ばされたとばかりに：「～とばかりに」は「いかにも～と言うような様子で」という意味で、言葉や気持ちを表す内容に付く。「飛ばされた」では意味が通らない"], "ex": "試合に勝った選手たちは、泣き出さ<b>んばかりに</b>喜んでいた。"},
"36081": {"point": "「～（よ）うものなら」は動詞の意向形に付き、「もし～したら（大変なことになる）」という意味で、後に悪い結果が続く。手術がもう少しでも遅れたら大変なことになるという文意で、意向形「遅れよう」が入る。", "opts": ["遅れる：辞書形に「ものなら」が付くのは「できるものなら」のような可能の場合で、「遅れるものなら」では悪い結果を仮定する意味にならない", "遅れた：「ものなら」はた形には付かず、「遅れたものなら」という形はない", "", "遅れん：「遅れん」は「～んばかり」「～んがため」などに使う文語的な形で、「ものなら」の前には意向形が必要"], "ex": "この道路は狭いので、雪でも降ろう<b>ものなら</b>、すぐに渋滞してしまう。"},
"36082": {"point": "「～がゆえに」は「～が理由で」という意味の硬い表現で、イ形容詞の普通形などにも付く。貧しいことが理由で、多くの子供たちが教育を受けられないでいるという因果関係に合う。", "opts": ["となれば：「～となれば」は「～という状況になれば」という仮定を表し、子供たちが実際に教育を受けられないでいるという事実の理由を表さない", "のみで：「～のみで」は「～だけで」という限定を表し、「貧しいのみで」では理由の意味にならない", "", "ながらも：「～ながらも」は「～けれども」という逆接で、「貧しいながらも教育を受けられない」では逆接の関係が成り立たない"], "ex": "責任ある立場にある<b>がゆえに</b>、彼の発言は常に注目される。"},
"36083": {"point": "「AはおろかBさえ～ない」は「Aはもちろん、（より簡単な）Bさえ～ない」という意味で、程度を比べて強調する。家の手伝いはもちろん、自分の部屋の掃除さえしないという文意で、後の「さえ」と呼応する。", "opts": ["", "までも：「～までも」は「～さえも」と極端な例を挙げる表現で、「家の手伝いまでも自分の部屋の掃除さえしない」では二つの例の関係が成り立たない", "をとわず：「～をとわず」は「年齢を問わず」のように「～に関係なく」という意味で、文意に合わない", "をおいて：「～をおいて（他にない）」は「～以外に（ない）」とその人や物を高く評価する表現で、文意に合わない"], "ex": "彼は漢字<b>はおろか</b>、ひらがなさえ読めない。"},
"36084": {"point": "「～ばこそ」は「～からこそ」という意味で、理由を強調する。「あれば」に「こそ」が付き、皆様の協力があるからこそ計画は成功する、と感謝の気持ちを込めて理由を強調している。", "opts": ["あったら：「たら」には「こそ」を付けて理由を強調する用法がなく、「～ばこそ」の形にならない", "", "なければ：「協力がなければこそ成功する」となり、協力があるからこそという文意と反対になる", "なしで：「ご協力がなしで」は不自然な形で、「こそ」と結び付いて理由を表すこともできない"], "ex": "仲間がい<b>ればこそ</b>、つらい練習にも耐えられた。"},
"36085": {"point": "「～ようにも～ない」は意向形に付き、同じ動詞の可能形の否定と組み合わせて「～しようとしても、できない」という意味を表す。両手に荷物を持っているので、傘をさそうとしてもさせないという文意に合う。", "opts": ["", "さしたとて：「～たとて」は「たとえ～しても」という逆接の仮定で、「傘をさしたとてさせない」では意味が矛盾する", "さしつつも：「～つつも」は「～しながらも」という逆接で、実際に傘をさしていることになり、「させない」と矛盾する", "さそうものなら：「～ようものなら」は「もし～したら（大変なことになる）」という意味で、後に悪い結果が続く。「させない」とは呼応しない"], "ex": "周りがうるさくて、眠ろう<b>にも眠れない</b>。"},
"36086": {"point": "「～をよそに」は「～を気にしないで、無視して」という意味。親が心配しているのを気にかけず、悪い仲間との付き合いをやめようとしないという文意に合う。", "opts": ["ほかに：「～をほかに」という言い方はなく、意味が通らない。「～をおいてほかに」なら「～以外に」という意味になる", "そとに：「～をそとに」という表現はなく、意味をなさない", "もとに：「～をもとに」は「～を材料・根拠にして」という意味で、「親の心配をもとに」では文意に合わない", ""], "ex": "周囲の反対<b>をよそに</b>、彼は会社を辞めて起業した。"},
"36087": {"point": "「～んばかり」は動詞のない形に付き、「今にも～しそうなほど」という意味で、「～んばかりの＋名詞」の形で名詞を修飾する。ドアを今にも壊しそうなほど激しい勢いでたたいた様子を表している。", "opts": ["壊せばこそ：「～ばこそ」は「～からこそ」と理由を強調する表現で、後に「の勢い」は続かない", "壊すべく：「～べく」は「～するために」という目的を表し、「の」を付けて名詞を修飾することはできない", "", "壊さんがため：「～んがため」は「～するために」という目的を表し、ドアを壊すことが目的になってしまう。程度の激しさを表す文意に合わない"], "ex": "演奏が終わると、割れ<b>んばかり</b>の拍手が会場に響いた。"},
"36088": {"point": "「～をおいて他に（ない）」は「～以外に（ない）」という意味で、その人を最も高く評価する表現。ここでは「他にいるだろうか（いや、いない）」という反語と組み合わせ、この曲を歌えるのはあの歌手だけだと強調している。", "opts": ["いわず：「あの歌手をいわず」では意味が通らない。「AといわずBといわず」の形なら「AもBも区別なく」という意味になる", "", "とわず：「～をとわず」は「～に関係なく」という意味で、「あの歌手をとわず」では意味が通らない", "よそに：「～をよそに」は「～を気にしないで」という意味で、文意に合わない"], "ex": "日本でいちばん美しい紅葉が見られる場所といえば、京都<b>をおいて他に</b>ないだろう。"},
"36089": {"point": "「～までもない」は辞書形に付き「わざわざ～する必要はない」という意味。電話で注文すればすぐ届くので、時間をかけて買いに行く必要はないという文意に合い、「わざわざ」とも呼応する。", "opts": ["行かざるをえない：「～ざるをえない」は「どうしても～しなければならない」という意味で、電話で注文すればすぐ届くという後の理由と合わない", "", "行くより仕方がない：「～より仕方がない」は「～するしか方法がない」という意味で、電話で注文できるという後の文と矛盾する", "行くしかない：「～しかない」は「それ以外に方法がない」という意味で、電話で注文すればいいという後の文と矛盾する"], "ex": "この程度の傷なら、病院に行く<b>までもない</b>。"},
"36090": {"point": "「～にひきかえ」は「～とは反対に」という意味で、二つの事柄を対比する。「それにひきかえ」の形で前の文を受け、若いころは山登りをしても平気だったのと対照的に、最近は少し登っただけで疲れるという対比を表している。", "opts": ["", "はもとより：「～はもとより」は「～はもちろん」と同じ方向のことを付け加える表現で、反対の内容を対比するこの文に合わない", "をふまえて：「～をふまえて」は「～を前提・根拠にして」という意味で、前後の対比の関係を表せない", "をよそに：「～をよそに」は「～を気にしないで」という意味で、文意に合わない"], "ex": "去年の夏は涼しかった。それ<b>にひきかえ</b>、今年は毎日猛暑が続いている。"},
"36091": {"point": "「～ばこそ」は「～からこそ」と理由を強調する表現で、「～のも、～ばこそだ」の形でよく使われる。日本で勉強を続けられるのは、両親の理解があるからだという理由を強調している。", "opts": ["なければ：「理解がなければこそ」では、理解がないから勉強が続けられるという意味になり、文意と反対になる", "なかったら：「たら」は「こそ」と結び付いて理由を強調できず、意味も文意と反対になる", "あったら：「たら」には「こそ」を付けて理由を強調する用法がなく、「～ばこそ」の形にならない", ""], "ex": "子どもを厳しく叱るのも、愛してい<b>ればこそ</b>だ。"},
"36092": {"point": "「～までもない」は辞書形に付き「わざわざ～する必要はない」という意味。そんなことは常識なので、わざわざ説明してもらう必要はないという文意に合い、「わざわざ」とも呼応する。", "opts": ["しかない：「～しかない」は「それ以外に方法がない」という意味で、常識だから説明は不要だという文意と反対になる", "はずがない：「～はずがない」は「～という可能性はない」という話し手の確信を表し、「必要がない」という意味を表せない", "ほどもない：動詞に「ほどもない」を付けて「～する必要がない」という意味を表すことはなく、不自然な表現", ""], "ex": "駅は近いので、車で送ってもらう<b>までもない</b>。"},
"36093": {"point": "「～にひきかえ」は名詞に付き「～とは反対に」という意味で、二つのものを対比し、後のほうを否定的に述べることが多い。もうすぐ結婚する弟と比べて、自分はガールフレンドもいないという対比に合う。", "opts": ["とあいまって：「～とあいまって」は「～と一緒になって（よい・強い効果を生む）」という意味で、対比を表すこの文に合わない", "にこたえて：「～にこたえて」は「期待にこたえて」のように「～に応じて」という意味で、文意に合わない", "", "をひかえて：「～をひかえて」は「試験をひかえて」のように近く予定されている事柄に付いて「～が近づいている時に」という意味。人を表す「弟」には付かず、対比の意味もない"], "ex": "明るい姉<b>にひきかえ</b>、妹はおとなしくて人見知りだ。"},
"36094": {"point": "「AはおろかB（も・さえ）」は「Aはもちろん、Bも」という意味で、程度の高いAは当然として、程度の低いBでも同じだと強調する。強いウイスキーはもちろん、ビールを一口飲んだだけでも顔が真っ赤になるという文意に合う。", "opts": ["からして：「～からして」は「話し方からして失礼だ」のように、一つの例を挙げて全体を判断する表現で、より程度の低いものへ話を広げるこの文に合わない", "といえども：「～といえども」は「～であっても」という逆接で、「ウイスキーといえども」では意味が通らない", "", "をとわず：「～をとわず」は「～に関係なく」という意味で、「ウイスキーをとわず」では意味が通らない"], "ex": "祖父は、スマートフォン<b>はおろか</b>、携帯電話も使ったことがない。"},
"36095": {"point": "「～をよそに」は「～を気にしないで、無視して」という意味。健康問題が心配されているのに、それを気にしないかのように若者の喫煙が一向に減らないという文意に合う。", "opts": ["をもとに：「～をもとに」は「～を材料・根拠にして」という意味で、「懸念をもとに喫煙が減らない」では意味が通らない", "", "におうじて：「～におうじて」は「～に合わせて」という意味で、「懸念におうじて」なら喫煙は減るはずで、「一向に減らない」と合わない", "はもとより：「～はもとより」は「～はもちろん」と付け加える表現で、文意に合わない"], "ex": "周りの心配<b>をよそに</b>、本人はいたってのんきだ。"},
"36096": {"point": "「～と言わんばかりに」は「実際には言わないが、今にも～と言いそうな様子で」という意味。彼は口には出さないが、「責任はお前にある」と言いたげな態度で私をにらみつけたという文意に合う。", "opts": ["言うべからざる：「～べからざる」は「～してはならない」という意味の硬い表現で、名詞を修飾する形。動詞「にらみつけた」にはつながらない", "言いがてら：「～がてら」は「散歩がてら」のように「～のついでに」という意味で、文意に合わない", "", "言うまじき：「～まじき」は「教師にあるまじき行為」のように「～してはならない」という意味で名詞を修飾する形。動詞「にらみつけた」にはつながらない"], "ex": "彼女は早く帰れと言わ<b>んばかりに</b>、何度も時計を見た。"},
"36097": {"point": "「～ようにも～ない」は同じ動詞の意向形と可能形の否定を組み合わせ、「～しようとしても、（事情があって）できない」という意味を表す。上司がまだ働いているので、帰ろうとしても帰れないという文意に合う。", "opts": ["", "帰ろうが帰れない：「～ようが」は「雨が降ろうが行く」のように「～ても関係なく」という意味で、「帰ろうが帰れない」という言い方はしない", "帰ろうと帰れない：「～ようと」も「～ても関係なく」という意味で、「帰ろうと帰れない」という言い方はしない", "帰りたくて帰れない：「～たくて」は理由を表すので「帰りたいから帰れない」という矛盾した意味になり、文が成り立たない"], "ex": "電車が止まってしまい、会社に行こう<b>にも行けない</b>。"},
"36098": {"point": "「～（よ）うものなら」は意向形に付き、「もし～したら（大変なことになる）」という意味で、後に悪い結果が続く。部下が少しでもミスをしたら、すぐに激しく怒り出すという文意に合う。", "opts": ["ものを：「～ものを」は「～のに」と不満や残念な気持ちを表す表現で、意向形には付かない", "", "もので：「～もので」は「～ので」と言い訳の理由を表す表現で、意向形には付かない", "ものだから：「～ものだから」は理由を表す話し言葉で、意向形には付かず、仮定の意味もない"], "ex": "祖母の前で食べ物を残そう<b>ものなら</b>、ひどく叱られる。"},
"36099": {"point": "「～がゆえに」は「～が理由で」という意味の硬い表現。「新人であるが」の「が」に続いて「新人であるがゆえに」となり、入社した年は新人であることが理由で緊張していたという文意を表す。", "opts": ["", "ために：理由を表す「ために」は普通「新人であるために」のように「が」を挟まずに付く。「であるが」に続けて理由を表す形として問われているのは「がゆえに」である", "ばかりに：「～ばかりに」は「～せいで（悪い結果になった）」という意味で、「新人であるばかりに」のように直接付き、「が」の後には続かない", "ごとく：「～がごとく」は「～のように」という比喩を表し、実際に新人だった事実の理由を表せない"], "ex": "彼は優しすぎる<b>がゆえに</b>、人の頼みを断れない。"},
"36100": {"point": "「～をおいてほかに（ない）」は「～以外に（ない）」という意味で、その人を最も高く評価する表現。わずか5年足らずでこれだけの作品を残した作家は、文学史の中でも彼女以外にはいないと高く評価している。", "opts": ["を限りに：「～を限りに」は「今日を限りに」のように時を表す語に付き、「～を最後に」という意味。文意に合わない", "", "を問わず：「～を問わず」は「～に関係なく」という意味で、「彼女を問わず」では意味が通らない", "をかわきりに：「～をかわきりに」は「～を始まりとして（次々に）」という意味で、後に「ほかにはいない」は続かない"], "ex": "このチームをまとめられるのは、キャプテンの山田さん<b>をおいてほかにはいない</b>。"},
"36101": {"point": "「AとBがあいまって」は「AとBが一緒になって、互いに作用し合ってある結果を生む」という意味。休日であることと久しぶりの晴天という二つの要因が重なって、遊園地がどこも人でいっぱいになったという文意に合う。", "opts": ["", "ともに：「休日と晴天がともに」の後には動詞が必要で、このままでは後の文につながらない", "きっかけに：「～をきっかけに」は「～を機会に」という意味で「を」に付く。「晴天がきっかけに」とは言わず、二つの要因が重なる意味も表せない", "かわきりに：「～をかわきりに」は「～を始まりとして（次々に）」という意味で「を」に付く。「晴天がかわきりに」とは言わず、意味も合わない"], "ex": "美しい景色とおいしい料理が<b>あいまって</b>、忘れられない旅になった。"},
"36102": {"point": "「～ずくめ」は名詞に付き「～ばかり、～が続く」という意味で、身の回りがそのことで満ちている様子を表す。このところ何をやっても失敗ばかりが続いているという文意に合う。", "opts": ["かぎり：「～かぎり」は「できるかぎり」のように「～の限界まで」という意味などで使い、「失敗かぎり」という表現はない", "", "まみれ：「～まみれ」は「泥まみれ・汗まみれ」のように、主に表面に汚れなどが一面に付いた様子を表し、失敗が続くという意味には合わない", "きわみ：「～のきわみ」は「ぜいたくのきわみ」のように「この上ない～」という意味で「の」が必要。「失敗きわみ」とは言わない"], "ex": "今年は昇進に結婚と、いいこと<b>ずくめ</b>の一年だった。"},
"36103": {"point": "「～てまで」は「そこまでして、極端な手段をとって」という意味で、その行為への非難や疑問の気持ちを表すことが多い。家庭を犠牲にするほどのことをして趣味にお金を使うのは健全ではないという文意に合う。", "opts": ["せずとも：「～ずとも」は「～しなくても」という意味の書き言葉で、「家庭を犠牲にせずとも」では家庭を犠牲にしていないことになり、非難の文意と合わない", "しないまでも：「～ないまでも」は「～とまではいかなくても」という意味で、家庭を犠牲にしていないことになり、後の「健全な状態とは言えません」と合わない", "までなら：「犠牲にまでなら」という形はなく、意味が通らない", ""], "ex": "睡眠時間を削っ<b>てまで</b>ゲームをするのはやめたほうがいい。"},
"36104": {"point": "「何であれ」は「何であっても、どんなものでも」という意味。楽器ならどんな種類のものでも演奏できるという、彼の音楽の才能を表す文意に合う。", "opts": ["いかんで：「～いかんで」は「結果いかんで」のように名詞に付いて「～次第で」という意味。「何いかんで」とは言わない", "", "とあれば：「～とあれば」は「～という特別な事情なら」という意味で、「何とあれば」とは言わない", "ゆえ：「何ゆえ」は「なぜ」という意味の古い言い方で、文意に合わない"], "ex": "理由は何<b>であれ</b>、約束を破るのはよくない。"},
"36105": {"point": "「～そばから」は辞書形・た形に付き、「～するとすぐに（また）」という意味で、何度しても、すぐにまた元に戻されてしまうことの繰り返しを表す。片づけてもすぐに子供が散らかすので、部屋がきれいにならないという文意に合う。", "opts": ["", "あとでは：「～あとでは」は「～たあとでは」の形でた形に付く。辞書形「片づける」には付かず、繰り返しの意味も表せない", "よそには：「よそ」は「ほかの所」という意味で、「片づけるよそには」という表現はない", "ことまで：「～ことまで」は「～ことさえ」という意味で、「片づけることまで子供が散らかす」では意味が通らない"], "ex": "新しい単語を覚える<b>そばから</b>忘れてしまう。"},
"36106": {"point": "「～てやまない」は「願う・祈る・愛する」などの気持ちを表す動詞に付き、「心から～している、～し続けている」という意味。卒業する皆さんの健康と幸せを心から願っているという気持ちを表している。", "opts": ["", "たえない：「～にたえない」は「感謝にたえない」のように名詞などに「に」を付けて使う形で、て形には付かない", "とまらない：「願ってとまらない」という表現はない。「とまらない」は「涙がとまらない」のように動きが続く様子を表す", "すまない：「～てすまない」は「待たせてすまない」のように謝る表現で、文意に合わない"], "ex": "両国の友好関係が末永く続くことを願っ<b>てやまない</b>。"},
"36107": {"point": "「ただ～のみ」は「ただ～だけ」という意味で、それ以外のことはしない・できないという限定を強調する。何もできない母親が、神に祈ることしかできなかったという文意で、文末の「のみ」と呼応する。", "opts": ["さて：「さて」は話題を変えたり次の行動に移ったりする時に使う接続詞で、「のみ」と呼応せず文意に合わない", "なお：「なお」は「さらに・依然として」や補足を表す語で、「のみ」と呼応して限定を表すことはない", "まだ：「まだ」は「依然として」という意味で、「のみ」と呼応せず、祈ることしかできないという限定の意味を表せない", ""], "ex": "今は<b>ただ</b>、皆の無事を祈る<b>のみ</b>だ。"},
"36108": {"point": "「～じゃあるまいし」は「～ではないのだから」という意味の話し言葉で、後に「～しなくてもいい」など相手への忠告や意見が続く。一人で行くわけではないのだから、そんなに心配しなくていいという文意に合う。", "opts": ["行くわけだったんだから：「一人で行くことになっていたのだから」という意味になり、心配しなくていいという後の文と合わない", "", "行くもんだっただろうに：「～ものだっただろうに」という不自然な形で、意味が通らない", "行くもんじゃないだろうが：「～ものではない」は「～すべきではない」という忠告を表し、「一人で行くべきではないだろうが」となって、心配しなくていいという後の文と合わない"], "ex": "一生会えなくなる<b>わけじゃあるまいし</b>、そんなに泣かないで。"},
"36109": {"point": "「～始末だ」は動詞の辞書形などに付き、「（悪い状態が続いた結果）とうとう～ということになった」という意味で、好ましくない結果を表す。経済が悪化した結果、ついに閣僚が「もはや経済一流国ではない」と公言するまでになったという文意で、辞書形「公言する」が入る。", "opts": ["", "公言しよう：意向形には「始末だ」は付かない", "公言した：「始末だ」は普通、辞書形やない形に付いて悪い結果を表し、た形には付けない", "公言して：て形には「始末だ」は付かず、文が成り立たない"], "ex": "弟は遊んでばかりいて、とうとう大学を退学になる<b>始末だ</b>。"},
"36110": {"point": "「～てやまない」は感情を表す動詞に付き「心から～している、ずっと～し続けている」という意味。「いまだに」と合わせて、あのときのことをずっと後悔し続けている気持ちを表している。", "opts": ["ちがわない：「ちがわない」は「同じだ」という意味で、「後悔してちがわない」という表現はない", "", "とまらない：「後悔してとまらない」という表現はなく、意味が通らない", "すまない：「～てすまない」は謝罪の表現で、後悔し続けているという文意に合わない"], "ex": "彼の作品は、今も多くの人を魅了し<b>てやまない</b>。"},
"36111": {"point": "「～そばから」は「～するとすぐに（また次々と）」という意味で、同じことが繰り返される様子を表す。料理を食べるとすぐに、次の料理がどんどん運ばれてきたという文意に合う。", "opts": ["が最後：「～たが最後」は「一度～したら、もう（悪い結果になる）」という意味でた形に付く。辞書形には付かず、文意にも合わない", "", "のなら：「～のなら」は「～するなら」という仮定を表し、すでに起こった事実を述べるこの文に合わない", "ともなしに：「～ともなしに」は「見るともなしに」のように「特に～しようという意識もなく」という意味で、文意に合わない"], "ex": "何度注意しても、注意する<b>そばから</b>同じ間違いを繰り返す。"},
"36112": {"point": "「～ずにはおかない」は「必ず～させる、自然に～という状態を引き起こす」という意味。芸術性の高い彼の写真は、見る人を必ず感動させるだろうという文意に合う。", "opts": ["させずじまい：「～ずじまい」は「結局～しないで終わった」という意味で過去のことに使い、「感動させずじまいだろう」では意味が通らない", "", "させるわけにはいかない：「～わけにはいかない」は「（事情があって）～することはできない」という意味で、作品をほめる文意と合わない", "させればそれまでだ：「～ばそれまでだ」は「～したら、それで終わりだ」という意味で、文意に合わない"], "ex": "彼女の歌声は、聴く人の心を揺さぶら<b>ずにはおかない</b>。"},
"36113": {"point": "「～じゃあるまいし」は「～ではないのだから」という意味の話し言葉で、後に相手への不満や忠告が続く。いい年をして子供ではないのだから、朝くらい自分で起きてほしいという文意に合う。", "opts": ["にしたって：「～にしたって」は「～にしても」という意味で、「子供にしたって」では「子供であっても」となり、「いい年をして」と矛盾する", "", "とはうらはらに：「～とはうらはらに」は「期待とはうらはらに」のように「～とは反対に」という意味で、文意に合わない", "にひきかえ：「～にひきかえ」は「～とは反対に」と二つのものを比べる表現で、この文には対比する相手がなく合わない"], "ex": "新人<b>じゃあるまいし</b>、こんな簡単なミスをしないでほしい。"},
"36114": {"point": "「～しまつだ」は辞書形などに付き、「（悪い状況が進んだ結果）とうとう～ということになった」という意味。電車内が暑すぎた結果、ついに気分が悪くなって倒れる人まで出たという悪い結果に合う。", "opts": ["あげくだ：「～あげく」は「さんざん迷ったあげく」のようにた形に付き、辞書形「出る」には付かない", "あまりだ：「～あまり」は「心配のあまり」のように「～すぎて」という原因を表す形で、「出るあまりだ」とは言わない", "", "しだいだ：「～しだいだ」は「お願いする次第です」のように事情や経緯を改まって説明する表現で、悪い結果を表さない"], "ex": "彼は遅刻を繰り返し、ついには無断で会社を休む<b>しまつだ</b>。"},
"36115": {"point": "「～てまで」は「そこまでして、極端な手段をとって」という意味で、話し手のあきれや非難の気持ちを表すことが多い。借金するという極端なことをしてまで旅行に行ったことにあきれたという文意に合う。", "opts": ["するにたる：「～にたる」は「～する価値がある」という意味で、「借金するに値する旅行」と肯定的な評価になり、「あきれてしまった」と合わない", "しただけで：「～ただけで」は「少し～しただけで」という意味で、「借金しただけで旅行に行った」では意味が通らない", "すればこそ：「～ばこそ」は「～からこそ」と理由を強調する表現で、後に「旅行に行った」と続けると意味が通らない", ""], "ex": "人をだまし<b>てまで</b>お金をもうけたいとは思わない。"},
"36116": {"point": "「～でもあるまいし」は「～ではないのだから」という意味で、後に話し手の判断や忠告が続く。専門家ではないのだから、そんなにうまくできるはずがないという判断が入る。", "opts": ["それくらいなら簡単にできるだろう：専門家ではないことを理由に「簡単にできる」と続けることになり、前後の論理が合わない", "初心者を指導している：事実を述べるだけの文で、「～ではないのだから」という理由を受ける判断になっておらず、前とつながらない", "", "プロ並みの腕前だ：専門家ではないことと、プロ並みの腕前だという評価は逆接の関係になり、「～ではないのだから」という理由と合わない"], "ex": "子ども<b>でもあるまいし</b>、そんなことで泣くなよ。"},
"36117": {"point": "「何であれ」は「何であっても、どんなものでも」という意味。プレゼントは、中身がどんなものでも、もらえばうれしいものだという文意に合う。", "opts": ["であり：「であり」は「～であって」と並列や説明を続ける形で、「何であり」では「どんなものでも」という意味にならない", "", "であった：「何であった」は過去の断定で、後の「うれしいものだ」とつながらない", "である：「何である」では文が途中で切れてしまい、「どんなものでも」という意味にならない"], "ex": "職業は何<b>であれ</b>、一生懸命働くことが大切だ。"},
"36118": {"point": "「～ずにはおかない」は「必ず～する、どうしても～という結果を引き起こす」という意味。戦争というものは、必ず人々に悲劇をもたらすという文意に合う。", "opts": ["いけない：「～ずにはいけない」という形はなく、意味が通らない", "", "ならない：「～ずにはならない」という表現はない。「ならない」は「～てはならない」「～なければならない」の形で使う", "やらない：「～ずにはやらない」という表現はなく、意味が通らない"], "ex": "この事件は、社会に大きな影響を与え<b>ずにはおかない</b>だろう。"},
"36119": {"point": "「ただ～のみ」は「ただ～だけ」という意味で、それ以外のことはできないという限定を強調する。突然の死の知らせに何も語れず、茫然とすることしかできなかったという文意で、文末の「のみ」と呼応する。", "opts": ["", "たった：「たった」は「たった一人・たった三日」のように数量を表す語に付いて少なさを強調するもので、「茫然とする」という動作には使えない", "ただし：「ただし」は前の内容に条件や例外を付け加える接続詞で、文意に合わない", "いわゆる：「いわゆる」は「世間で言われている」という意味で名詞の前に付く語で、「茫然とする」には付かない"], "ex": "試験の結果が出るまで、<b>ただ</b>待つ<b>のみ</b>だ。"},
"36120": {"point": "「～とあいまって」は「～と一緒になって、互いに作用し合って（よい結果を生む）」という意味。清い水に恵まれていることと伝統の技術という二つの要素が一緒になり、すばらしい風味のお酒の産地となったという文意に合う。", "opts": ["ときたら：「～ときたら」は「うちの息子ときたら」のように、身近な人や物を話題にして不満や非難を述べる表現で、文意に合わない", "とおもいきや：「～と思いきや」は「～と思ったが、意外にも」という意味で、予想と違う結果を表す。この文には意外性がなく合わない", "にもかかわらず：「～にもかかわらず」は「～のに」という逆接で、清い水と伝統の技術がそろってよいお酒ができたという順接の文意に合わない", ""], "ex": "彼女の才能は、人一倍の努力<b>とあいまって</b>大きく開花した。"},
"36601": {"point": "「～ともなると」は「～という時期・立場になると」という意味で、その時期になると普段とは違う状況になることを表す。年末という時期になると、忘年会やパーティーの誘いが多くなるという文意に合う。", "opts": ["といえども：「～といえども」は「～であっても」という逆接で、「年末といえども誘いが多くなる」では逆接の関係が成り立たない", "ときたら：「～ときたら」は人や物を話題にして不満や非難を述べる話し言葉で、時期を表す「年末」に付けて状況の変化を述べる文に合わない", "とはいうものの：「～とはいうものの」は「～とは言っても実際は」という逆接で、文意に合わない", ""], "ex": "大学四年生<b>ともなると</b>、就職のことを真剣に考えなければならない。"},
"36602": {"point": "「～ようにも～ない」は意向形に付き、後に可能の否定が続いて「～しようとしても、（事情があって）できない」という意味を表す。財布を家に忘れてきたので、買い物をしようとしてもできないという文意に合う。", "opts": ["しようと：「～ようと」は「たとえ～しても（関係なく）」という意味で、後に話し手の意志や判断が続く。「買い物をしようとできない」とは言わない", "", "しようが：「～ようが」も「～しても（関係なく）」という意味で、「しようができない」では意味が通らない", "しつつも：「～つつも」は「～しながらも」という逆接で、実際に買い物をしていることになり、「できない」と矛盾する"], "ex": "連絡先がわからないので、連絡しよう<b>にもできない</b>。"},
"36603": {"point": "「ことここにいたっては」は「事態がこんな状態にまでなってしまっては」という意味で、後に「もうどうしようもない」などのあきらめや否定的な判断が続く。対策が遅れて事態が悪化した今では、もう手の打ちようがないという文意に合う。", "opts": ["どうにかなるだろう：楽観的な見通しを述べており、手遅れを嘆く「ことここにいたっては」の後に合わない", "どうってことはない：「大したことはない」という意味で、事態の悪化を嘆く前の文と合わない", "", "どうやら目途がついたようだ：解決の見通しが立ったという意味になり、対策が遅れて事態が悪化したという前の文と合わない"], "ex": "<b>ことここにいたっては</b>、計画を中止するしかない。"},
"36604": {"point": "「AはおろかB（も・だって）」は「Aはもちろん、（さらに程度の重い）Bも」という意味。不景気になれば、会社は賃金カットはもちろん、さらに厳しいリストラまで平気でするという文意で、後の「だって」と呼応する。", "opts": ["あげく：「～あげく」は「さんざん迷ったあげく」のようにた形や「名詞＋の」に付き、「いろいろ～した末に」という意味。「賃金カットはあげく」とは言わない", "", "かぎらず：「～にかぎらず」は「～だけでなく」という意味で「に」に付く。「は」の後には続かない", "いたり：「～のいたり」は「光栄のいたり」のように「この上ない～」という意味で、「は」の後には続かない"], "ex": "彼は英語<b>はおろか</b>、フランス語や中国語まで話せる。"},
"36605": {"point": "「～きらいがある」は「（好ましくない）傾向がある」という意味で、辞書形・ない形などに付く。人は年をとると他人の忠告に耳を貸さなくなるという、よくない傾向を述べる文意に合う。", "opts": ["", "しだいがある：「しだいがある」という表現はない。「～しだいだ」は事情や経緯を説明する表現で、傾向を表さない", "つもりがある：「～つもりがある」は主語の意志を表し、一般的な傾向を述べるこの文に合わない", "きっかけがある：「きっかけ」は物事が始まる機会のことで、「耳を貸さなくなるきっかけがある」では傾向の意味にならない"], "ex": "彼は何でも自分一人で決めてしまう<b>きらいがある</b>。"},
"36606": {"point": "「～だけあって」は「さすが～なので、それにふさわしく」という意味で、評価する気持ちを表し、後の「さすがに」とも呼応する。学生時代に京都に住んでいたので、この地域のことをよく知っているのも当然だという文意に合う。", "opts": ["からには：「～からには」の後には「～べきだ・～つもりだ」など話し手の判断や決意が続き、事実を述べるこの文に合わない", "ところ：「～たところ」は「～したら（その結果）」という意味で、理由を表さない", "", "とは：「～とは」は「京都に住んでいたとは驚いた」のように驚きを表す表現で、理由を表さない"], "ex": "毎日練習している<b>だけあって</b>、彼女のピアノはとても上手だ。"},
"36607": {"point": "「～がゆえに」は「～が理由で」という意味の硬い表現。「若いが」の「が」に続いて「若いがゆえに」となり、若いことが理由で甘く見られないようにと頑張ってきたという文意を表す。", "opts": ["くせに：「～くせに」は非難の気持ちを表す逆接で、「若いくせに」のように直接付く。「が」の後には続かない", "ように：「若いがように」という形はなく、意味が通らない", "のみに：「若いがのみに」という形はなく、意味が通らない", ""], "ex": "才能がある<b>がゆえに</b>、彼女は周囲から大きな期待をかけられている。"},
"36608": {"point": "「～なしには」は名詞に付き「～がなければ（…できない・ありえない）」という意味。トヨタをはじめとする自動車産業がなければ、経済大国としての今の日本はありえなかったという文意で、文末の「ありえなかっただろう」と呼応する。", "opts": ["ないにしろ：「～ないにしろ」は「～ないとしても」という意味で、動詞などのない形に付く。名詞に直接付かず、意味も合わない", "", "ないので：名詞に直接付いた不自然な形で、意味も理由になり、「～がなければ」という仮定の文意に合わない", "なくとも：「～なくとも」は「～なくても」という意味で、「自動車産業がなくてもありえなかった」となり文意に合わない"], "ex": "皆さんの応援<b>なしには</b>、優勝できなかったと思います。"},
"36609": {"point": "「～んばかり」は動詞のない形に付き、「今にも～しそうなほど」という意味。「降り出す」のない形「降り出さ」に「ん」が付いて「降り出さんばかり」となり、今にも雨が降り出しそうな空模様を表す。「今にも」とも呼応している。", "opts": ["降り出す：「辞書形＋ばかり」は「あとは出発するばかりだ」のように「～するだけの状態だ」という意味になり、「今にも～しそうだ」という意味を表せない", "降り出さ：ない形の「降り出さ」だけでは「ばかり」につながらず、「ん」が必要", "", "降り出した：「～たばかり」は「～して間もない」という意味になり、「今にも」と矛盾する"], "ex": "彼女はあふれ<b>んばかり</b>の笑顔で私たちを迎えてくれた。"},
"36610": {"point": "「～とはいえ」は「～けれども、～とは言っても」という逆接。土地の値段が下がったという事実はあっても、都心に家を買うのはやはり難しいという文意に合い、「やはり」とも呼応している。", "opts": ["", "とあって：「～とあって」は「～という特別な状況なので」という理由を表し、逆接の文意に合わない", "ことゆえ：「～ことゆえ」は「～ことなので」という理由を表す古い言い方で、逆接の文意に合わない", "だけあって：「～だけあって」は「さすが～なので」と評価して理由を述べる表現で、逆接の文意に合わない"], "ex": "値段が安くなった<b>とはいえ</b>、新しいパソコンを買う余裕はない。"},
"36611": {"point": "「～と思いきや」は「～と思ったが、意外にも」という意味で、後に予想と反対の結果が続く。今までの成績から優勝は間違いないと思われたのに、意外にも決勝進出に失敗したという文意に合う。", "opts": ["", "思ったが最後：「～たが最後」は「一度～したら、もう（どうしようもない）」という意味で、予想が外れたことを表せない", "思うがまま：「思うがまま」は「思うとおりに」という意味で、後の予想外の結果とつながらない", "思えばこそ：「～ばこそ」は「～からこそ」と理由を強調する表現で、「優勝は間違いないと思えばこそ失敗した」では意味が通らない"], "ex": "簡単な試験だと<b>思いきや</b>、意外に難しい問題ばかりだった。"},
"36612": {"point": "「～きわまりない」はナ形容詞の語幹などに付き、「この上なく～だ、非常に～だ」という意味。波が荒いのに釣りをするのは非常に危険だという、話し手の強い非難の気持ちを表している。", "opts": ["きわまらない：「きわまる」の否定形で、「危険きわまらない」という表現はない", "", "きわまっている：「危険きわまっている」という形は使わず、「この上なく危険だ」という意味は「危険きわまる」か「危険きわまりない」で表す", "きわめない：「きわめる」は「頂上をきわめる」のように「最後まで行き着く」という意味の動詞で、「危険きわめない」という表現はない"], "ex": "夜中に大声で騒ぐなんて、迷惑<b>きわまりない</b>。"},
"36613": {"point": "「～といったらない」は名詞（「～さ」の形など）に付き、「とても～だ、言葉で言い表せないほど～だ」という意味。食事の時間もろくにとれないほど、先週は非常に忙しかったという文意に合う。", "opts": ["忙しくては：「先週の」の後には名詞が必要で、形容詞の「忙しくては」は続かない。文末の「なかった」ともつながらない", "", "忙しいというのに：「～というのに」は「～のに」という逆接で、「先週の」の後には続かず、文末の「なかった」ともつながらない", "忙しいしか：「しか」はイ形容詞に直接付かず、「先週の」にもつながらない"], "ex": "初めて富士山の頂上から見た朝日の美しさ<b>といったらなかった</b>。"},
"36614": {"point": "「～ながらも」はナ形容詞の語幹や名詞にも付き、「～けれども」という逆接を表す。シンプルなデザインでありながら上品さもあるという、一見反する二つの性質が共存していることを表している。", "opts": ["からでも：「シンプルからでも」という形はなく、意味が通らない", "とあれば：「～とあれば」は「～という特別な事情なら」という意味で、「シンプルとあれば」では意味が通らない", "", "までも：「～までも」は「～さえも」という意味で、「シンプルまでも上品なデザイン」では意味が通らない"], "ex": "この部屋は狭い<b>ながらも</b>、日当たりがよくて快適だ。"},
"36615": {"point": "「〜ばこそ」は「〜からこそ」と同じく、理由を強く取り立てる表現。計画が順調に進んだのは、ほかでもなく坂口さんの協力があったからだという気持ちを表し、文末の「〜のだ」とも合う。", "opts": ["すら：「〜すら」は「〜さえ」の意で極端な例を挙げる助詞。「〜ば」の後に付いて理由を強調する形はない", "しか：「〜しか」は後に否定の形が必要で、「進んだのだ」という肯定の文に合わない。「あればしか」という形もない", "", "だけ：「〜ばだけ」という形はなく、理由を強く取り立てる意味も表せない"], "ex": "家族の支えがあれ<b>ばこそ</b>、つらい治療にも耐えられたのです。"},
"36616": {"point": "「〜なくしては」は「〜がなければ」という意味で、後に「ありえない」「できない」などの否定が続く。今度の試合に勝たなければ、決勝進出は不可能だということを表している。", "opts": ["ならでは：「〜ならでは」は「その土地ならではの味」のように「〜だけにある特別な」という評価を表し、「勝利がなければ」という条件の意味にならない", "", "なくとも：「なくても」の書き言葉で、逆接を表す。「勝利がなければ進出できない」という条件の意味にならない", "にかぎらず：「〜にかぎらず」は「〜だけでなく」の意で、後の「ありえない」と意味がつながらない"], "ex": "地域の皆様のご協力<b>なくしては</b>、この祭りを続けることはできません。"},
"36617": {"point": "「〜いかんによっては」は「〜次第では」という意味で、その内容によってはある結果になる可能性があることを表す。相手の対応次第では裁判を起こすことになるという内容で、文末の「かもしれない」とも合う。", "opts": ["", "ならでは：「〜ならでは」は「〜だけにある特別な」の意で、「いかん」に付く形はなく、意味も合わない", "をものともせず：「〜をものともせず」は「困難を問題にしないで」の意で、「対応いかん」と意味がつながらない", "にもまして：「〜にもまして」は「〜以上に」という比較の意で、条件を表さない"], "ex": "検査の結果<b>いかんによっては</b>、手術が必要になる場合もあります。"},
"36618": {"point": "「〜かねる」は動詞のます形に付き、「〜することができない」「〜しにくい」という意味を表す。需要の減少などで売り上げが停滞している状況から、当分は販売実績の伸びを期待できないという見方を、会議にふさわしい改まった言い方で述べている。", "opts": ["しうる：「〜うる」は「〜することができる」の意。期待できることになり、売り上げが停滞しているという前の内容と矛盾する", "しつくす：「〜つくす」は「食べつくす」のように「すべて〜する」の意で、「期待しつくす」では意味が通らない", "しきれる：「〜きれる」は「完全に〜できる」の意で、普通は「〜きれない」の形で使う。「期待しきれる」は不自然で、文脈とも合わない", ""], "ex": "申し訳ございませんが、そのご要望にはお応えし<b>かねます</b>。"},
"36619": {"point": "「〜のいかんにかかわらず」は「〜がどうであるかに関係なく」という意味の改まった表現。当選でも落選でも、結果に関係なく全員に連絡するという案内の内容に合う。", "opts": ["にひきかえ：「〜にひきかえ」は「〜とは反対に」と二つのものを対比する表現で、「関係なく」という意味にならない", "", "というもの：「〜てからというもの」の形で「〜してからずっと」の意を表す。名詞「結果」に付いても意味が通らない", "をものともせず：「〜をものともせず」は「困難を恐れずに」の意で、「結果」と意味が合わない"], "ex": "理由<b>のいかんにかかわらず</b>、一度お支払いいただいた料金はお返しできません。"},
"36620": {"point": "「〜をおいて他にはない」は「〜以外にはない」という意味で、それしかないと強く評価する表現。この分野で次代を担う製品を開発できるのは、技術力のあるM社だけだという評価を表している。", "opts": ["何社かある：「〜をおいて」は後に「他に〜ない」という否定の形が続く表現で、「ある」で終わる形とは結びつかない", "一社だけある：「〜をおいて」は「他にはない（いない）」で結ぶ決まった形で、「〜だけある」とは結びつかない", "", "競い合っている：「〜をおいて」と結びつかず、「M社以外にない」という評価の意味も表せない"], "ex": "家族で安心して泳げる海といえば、この浜辺<b>をおいて他にはない</b>。"},
"36121": {"point": "「〜しまつだ」は、悪い状態が続いた結果、最後にさらに悪い結果になったことを表す。「〜あげく」とともに、締め切りに追われて徹夜を続けた結果、ついに高熱で倒れたという悪い結末を表している。", "opts": ["きっかけだ：「きっかけ」は物事が始まる原因を表し、悪い結末を述べる文末として合わない。「倒れるきっかけだ」では意味が通らない", "かわりだ：「〜かわりに」は「〜の代わりに・その代償に」の意で、「倒れるかわりだ」という形にはならない", "きらいだ：「〜きらいがある」の形で「〜の悪い傾向がある」の意を表す。「きらいだ」で終わる形はなく、一度の結果にも合わない", ""], "ex": "弟は勉強もせずに遊んでばかりで、ついには留年する<b>しまつだ</b>。"},
"36122": {"point": "「〜と〜とがあいまって」は「二つのことが一緒になって（ある結果を生む）」という意味。外国からの穀物輸入と豊作という二つの要因が重なって、穀物の価格が暴落したことを表している。", "opts": ["", "あたいして：「〜にあたいする」は「〜する価値がある」の意で、「に」に付く。「とが」に続く形はなく、意味も合わない", "いったら：「〜といったら」は話題を取り上げる表現で、「とが」の後には付かず、原因も表さない", "するなら：仮定を表し、二つの要因が重なって暴落したという過去の結果の説明に合わない"], "ex": "美しい景色<b>と</b>おいしい料理<b>とがあいまって</b>、忘れられない旅になった。"},
"36123": {"point": "「〜ずくめ」は名詞に付いて「〜ばかり」「全部〜だ」という意味を表す。給料が高く、労働時間も短いという、よいことばかりの会社の様子に合う。「いいことずくめ」はよく使われる形。", "opts": ["一方：「〜一方だ」は動詞の辞書形に付いて「ますます〜する」の意を表す。名詞「いいこと」には付かない", "", "まみれ：「〜まみれ」は「泥まみれ・汗まみれ」のように、汚いものが一面に付いている様子を表し、「いいこと」には使わない", "かぎり：「〜かぎりだ」は「うれしいかぎりだ」のように感情を表す形容詞に付く。名詞「いいこと」には付かない"], "ex": "今年は昇進に結婚と、本当にめでたいこと<b>ずくめ</b>の一年だった。"},
"36124": {"point": "「〜そばから」は「〜するとすぐに（また）」という意味で、同じことが何度も繰り返される様子を表す。お菓子を作っても作ってもすぐに子供たちが食べてしまうので、もう一個しか残っていないという状況に合う。", "opts": ["とたん：「〜たとたん」は動詞のた形に付く。「作るとたん」という形はなく、繰り返しの意味もない", "とは：「〜とは」は驚きやあきれた気持ちを表し、「作るとすぐに食べる」という時間的な関係を表さない", "かたわら：「〜かたわら」は「本業のかたわら、副業をする」のように、本来の仕事のほかに別のことをする意を表し、文脈に合わない", ""], "ex": "片付ける<b>そばから</b>子どもがおもちゃを散らかすので、きりがない。"},
"36125": {"point": "「たとえ〜であれ」は「たとえ〜であっても」という意味で、後に話し手の判断が続く。冗談半分の発言であったとしても、後で問題になるおそれがあるという内容に合う。", "opts": ["だの：「〜だの〜だの」と例を並べる形で、「たとえ」とは呼応しない", "といって：「たとえ」と呼応せず、「冗談半分といって」では「〜であっても」という逆接の仮定にならない", "", "とか：「〜とか」は例を挙げたり不確かな伝聞を表したりする形で、「たとえ」とは呼応しない"], "ex": "<b>たとえ</b>親友<b>であれ</b>、言っていいことと悪いことがある。"},
"36126": {"point": "「〜てまで」は「そこまでして」という意味で、目的のために普通はしないような極端なことをする場合に使い、それを批判する文が多い。環境破壊という犠牲を払ってまで道路建設を進めることへの疑問を表している。", "opts": ["", "にかこつけて：「〜にかこつけて」は「〜を口実にして」の意。「環境破壊を」の「を」には続かず、意味も合わない", "ならまだしも：「〜ならまだしも」は「〜ならまだ許せるが」の意。「を」の後には続かず、文の意味もつながらない", "とあいまって：「〜とあいまって」は「〜と一緒になって」の意。「を」の後には続かず、意味も合わない"], "ex": "借金をし<b>てまで</b>、高いブランド品を買いたいとは思わない。"},
"36127": {"point": "「〜ではあるまいし」は「〜ではないのだから」という意味で、「ではない」の「ない」を「あるまい」にした形。後に話し手の判断や忠告が続く。海外旅行に行くわけではないのだから、荷物は少なくしたほうがいいという助言に合う。", "opts": ["いるまいし：「いるまい」は「いないだろう」の意で、「のでは」の後に付いて「〜ではない」の意味を表す形にならない", "おくまいし：「おくまい」は「置かないだろう」の意で、「のでは」の後に付いて「〜ではない」の意味を表す形にならない", "", "するまいし：「するまい」は「しないだろう」の意で、「のでは」の後に付いて「〜ではない」の意味を表す形にならない"], "ex": "子ども<b>ではあるまいし</b>、自分のことは自分でしなさい。"},
"36128": {"point": "「〜てやまない」は「心から〜している」という意味で、「期待する・願う・愛する」など気持ちを表す動詞に付く。就職が決まり、もうすぐ卒業する上田君の今後の活躍を心から期待する気持ちを表し、「心より」とも合う。", "opts": ["期待するわけにはいかない：「〜わけにはいかない」は「事情があって〜できない」の意で、門出を祝う「心より」と合わない", "期待しないわけだ：「〜わけだ」は当然の結論を表し、期待しないことになって文脈と矛盾する", "", "期待しないばかりだ：「〜ばかりだ」は動詞の辞書形に付いて「ますます〜する」の意を表し、「しないばかりだ」は不自然で意味も通らない"], "ex": "皆様のご健康とご多幸を願っ<b>てやみません</b>。"},
"36129": {"point": "「〜ないではおかない」は「必ず〜させる」「自然に〜という状態にする」という意味。本当にすばらしい小説なので、読む人の心を必ずひきつけるだろうという話し手の強い確信を表している。", "opts": ["ひきつけるにはいられない：「〜ずにはいられない」と混同した形で、「〜にはいられない」という表現はない", "ひきつけることはない：「ひきつけない」という意味になり、「本当にすばらしい」という評価と矛盾する", "ひきつけるとは限らない：「必ずしもひきつけない」という意味になり、小説を高く評価する前の文と合わない", ""], "ex": "彼の情熱的なスピーチは、聞く人を感動させ<b>ないではおかない</b>。"},
"36130": {"point": "「ただ〜のみならず」は「ただ〜だけでなく」という意味の書き言葉。環境問題は地球規模の問題なので、一つの国だけの問題ではなく、各国が協力して取り組むべき課題だという内容に合う。", "opts": ["までもなく：「〜までもなく」は「言うまでもなく」のように動詞の辞書形に付き、「〜する必要もなく」の意。「一国」には付かない", "", "にかかわらず：「〜にかかわらず」は「天候にかかわらず」のように「〜に関係なく」の意で、「ただ」と呼応せず、意味も合わない", "だけであれ：「〜であれ」は「〜であっても」の意で、「ただ一国だけであれ」では「〜だけでなく」の意味にならない"], "ex": "この問題は、<b>ただ</b>若者<b>のみならず</b>、社会全体で考えるべきことだ。"},
"36131": {"point": "「〜にかかわる」は「〜に関係する」という意味で、特に「命にかかわる」のように重大なことに影響する場合に使う。個人のプライバシーを守ることは、人権という重大な事柄に関係する問題だという内容に合う。", "opts": ["", "したがう：「〜にしたがう」は「規則にしたがう」のように「〜のとおりにする」の意で、「人権にしたがう大切な問題」では意味が通らない", "かわる：「〜にかわる」は「〜の代わりになる」の意で、「人権の代わりになる問題」となり、意味が合わない", "おうじる：「〜におうじる」は「要望におうじる」のように「〜に合わせる」の意で、重大な関係を表さない"], "ex": "少しの不注意が、命に<b>かかわる</b>事故につながることもある。"},
"36132": {"point": "「〜ならではの」は「〜だけにある特別な」という意味で、それにしかない良さを高く評価する表現。海辺の町だからこそ味わえる新鮮な魚を使った料理という意味になり、「有名だ」とも合う。", "opts": ["なみに：「〜並みに」は「プロ並みに上手だ」のように「〜と同じ程度に」の意。程度を比べるだけで、その土地だけの特別さを表せない", "ながらの：「〜ながらの」は「昔ながらの」「生まれながらの」など限られた語に付く表現で、「海辺の町ながらの」とは言わない", "なりとも：「〜なりとも」は「少しなりとも」のように「せめて〜だけでも」の意で、意味が合わない", ""], "ex": "京都<b>ならではの</b>落ち着いた町並みを楽しんだ。"},
"36133": {"point": "「〜といえども」は「〜であっても」という意味で、後に「〜べきではない」「〜ないでほしい」などの主張が続くことが多い。社長という立場であっても、社員の私生活にまで口を出すべきではないという話し手の要望に合う。", "opts": ["出せるだろう：「社長なら口を出せる」という意味になり、「〜であっても」という逆接の「といえども」と合わない", "出すこともある：事実を述べるだけで、「〜といえども」の後に続く話し手の主張にならない。「〜にまで」の批判的な気持ちとも合わない", "", "出したりする：事実を例として述べるだけで、「社長であっても許されない」という「〜といえども」の後の主張にならない"], "ex": "専門家<b>といえども</b>、すべての質問に答えられるわけではない。"},
"36134": {"point": "「〜なり」は動詞の辞書形に付いて「〜するとすぐに」という意味を表す。ひどく疲れていたので、部屋に入るとすぐにソファーに座りこんでしまったという様子に合う。", "opts": ["", "きり：「〜たきり」の形で「〜したまま（その後変化がない）」の意を表し、辞書形の「入る」には付かない", "から：理由や起点を表し、「部屋に入るから座りこんだ」では意味が通らない。理由はすでに「疲れていたので」で示されている", "べく：「〜べく」は「〜するために」という目的を表し、「すぐに」という意味にならない"], "ex": "娘は家に帰る<b>なり</b>、自分の部屋に閉じこもってしまった。"},
"36135": {"point": "「〜に即して」は「〜に合わせて」「〜にしたがって」という意味で、事実や状況にぴったり合うように行う場合に使う。規定を実際の状況に合わせて柔軟に適用するべきだという主張に合う。", "opts": ["とあいまって：「〜とあいまって」は「〜と一緒になって」の意で、二つの要因が重なって結果を生む場合に使い、意味が合わない", "もかまわず：「〜もかまわず」は「〜を気にしないで」の意で、実態を無視することになり、「柔軟に」と矛盾する", "のみならず：「〜のみならず」は「〜だけでなく」の意で、後に付け加える内容がなく、意味がつながらない", ""], "ex": "法律は、時代の変化<b>に即して</b>見直されるべきだ。"},
"36136": {"point": "「〜ないものでもない」は「〜できないこともない」という意味で、可能性が全くないわけではないことを控えめに表す。難しい試験だが、努力すれば合格できる可能性はあるという内容に合う。", "opts": ["ことでもない：「〜ことでもない」は「騒ぐことでもない（〜するほどのことではない）」の意で使い、可能性があるという意味にならない", "", "はずではない：「〜はず」の否定は普通「〜はずがない」で、「合格できないはずではない」は不自然な形で意味も通らない", "どころではない：「〜どころではない」は「〜できる状況ではない」の意で、「合格できない」に付いても意味が通らない"], "ex": "条件によっては、その仕事を引き受け<b>ないものでもない</b>。"},
"36137": {"point": "「AといいBといい」は「AもBも（どちらも）」という意味で、いくつかの観点を挙げて全体を評価する表現。価格の点から見ても広さの点から見ても、新婚夫婦にぴったりだという評価に合う。", "opts": ["", "とも/とも：「AともBとも」は「AともBとも言えない」のように後に「言う」などの動詞が続く形で、評価を述べるこの文に合わない", "なり/なり：「AなりBなり」は「どちらでもいいから選んで」という提案や命令に使い、評価を述べる文に合わない", "であり/であり：「〜であり」は「AはBである」という述語の形で、「このマンションは価格であり」となって意味が通らない"], "ex": "この店は、味<b>といい</b>サービス<b>といい</b>、申し分ない。"},
"36138": {"point": "「〜とは」は「〜なんて」という意味で、驚きやあきれた気持ちを表す。大学生にもなって、そんな簡単なこともできないなんて情けないという、話し手のあきれた気持ちを表し、「実に情けないことだ」につながる。", "opts": ["にすら：「〜にすら」は「〜にさえ」の意で名詞などに付く。「できないにすら」という形はない", "", "わけに：「〜わけにはいかない」の形で使い、「わけに」だけでは後の「実に情けない」につながらない", "ものの：「〜ものの」は「〜けれども」の逆接で、「できないけれど情けない」となり、意味が通らない"], "ex": "こんな簡単な問題を間違える<b>とは</b>、自分でも信じられない。"},
"36139": {"point": "「〜といったところだ」は「だいたい〜ぐらいだ」という意味で、数量や程度がそれほど多くないことを表す。休憩を入れても、頂上まではだいたい3時間ぐらいだろうという見積もりに合う。", "opts": ["こと：「〜といったこと」は「〜のようなこと」と内容を例として挙げる形で、「だいたい〜ぐらい」という見積もりにならない", "とき：「〜といったとき」は「〜と言った時」の意になり、所要時間の見積もりにならない", "", "ばかり：「〜といったばかり」という形はなく、意味が通らない"], "ex": "私の英語力は、日常会話ができる<b>といったところだ</b>。"},
"36140": {"point": "「〜にして」は「〜でさえ」という意味で、能力や程度が高い人を例に挙げる。あの慎重な山田さんでさえ失敗したのだから、私が失敗するのもしかたがないという論理になる。", "opts": ["成功したから：山田さんが成功したのなら、「私が失敗してもしかたがない」という結論につながらない", "成功しただけあって：「〜だけあって」は「〜にふさわしく」と評価する表現で、成功した話になり、後の「失敗してもしかたがない」と合わない", "", "失敗したとはいうものの：「〜とはいうものの」は「〜けれども」の逆接で、「山田さんでさえ失敗した」ことを理由に「しかたがない」と述べる流れにならない"], "ex": "このベテランの医師<b>にして</b>原因がわからないのだから、よほど珍しい病気なのだろう。"},
"36141": {"point": "「〜なり」は動詞の辞書形に付いて「〜するとすぐに」という意味を表す。友達が私の顔を見ると、その直後に急に笑い出したという場面なので、辞書形の「見る」が入る。", "opts": ["", "見た：「〜たなり」は「〜たまま（その後変化がない）」の意になり、「すぐに」という意味にならない", "見ない：「〜なり」はない形には付かず、「見ないなり」では意味が通らない", "見て：て形には「なり」は付かず、「見てなり」という形はない"], "ex": "母は手紙を読む<b>なり</b>、泣き出した。"},
"36142": {"point": "「AといいBといい」は「AもBも」という意味で、二つの点を挙げて「どちらから見ても」と評価する表現。少し高いけれど、味の点でも香りの点でも最高のりんごだという評価に合う。", "opts": ["なり/なり：「AなりBなり」は「どれでもいいから」と選択を示す形で、提案や命令に使い、評価を述べる文には合わない", "", "により/により：「〜により」は原因や手段を表し、二つ並べて評価する形はない", "にして/にして：「〜にして」は「〜でさえ」「〜で（段階）」の意で、二つ並べる形はない"], "ex": "彼女は、声<b>といい</b>表情<b>といい</b>、母親にそっくりだ。"},
"36143": {"point": "「〜にかかわる」は「〜に重大な影響がある」という意味で、「命にかかわる」「信用にかかわる」のように使う。販売した品物に欠陥があると言われると、店の信用に大きく影響するという内容に合う。", "opts": ["", "たえない：「〜にたえない」は「感謝にたえない（とても〜だ）」「見るにたえない（ひどくて〜できない）」の意で、「信用に」とは結びつかない", "かぎる：「〜にかぎる」は「夏はビールにかぎる」のように「〜が一番いい」の意で、意味が合わない", "かなわない：「〜にはかなわない」は「〜には勝てない」の意で、「店の信用にかなわない」では意味が通らない"], "ex": "社員一人の小さなミスが、会社全体の評判に<b>かかわる</b>問題に発展した。"},
"36144": {"point": "「〜にしてはじめて」は「〜だからこそ（…できる）」という意味で、その条件がそろって初めて可能になることを表す。大量で、しかも現金での取引だからこそ、これほど安い仕入れ値が可能になるという内容に合う。", "opts": ["かたがた：「〜かたがた」は「散歩かたがた」のように「〜を兼ねて」の意で、条件を表さない", "にもまして：「〜にもまして」は「〜以上に」という比較の意で、「はじめて」と結びつかない", "", "をおいて：「〜をおいて」は「〜以外に」の意で、後に「他にない」などの否定が続き、「はじめて可能になる」と合わない"], "ex": "長年の経験を積んだ職人<b>にしてはじめて</b>、この繊細な技が可能になる。"},
"36145": {"point": "「〜に即して」は「〜に合わせて」という意味で、実情や要求にぴったり合う形で物事を行うときに使う。お客様の要望に合わせて、すぐれた新商品を開発していくという企業の姿勢に合う。", "opts": ["につけて：「〜につけ（て）」は「何かにつけて」「見るにつけ」のように「〜するたびに」の意で、意味が合わない", "について：「〜について」は話題や対象を表し、「要望について新商品を開発する」では意味が通らない", "に反して：「〜に反して」は「〜とは反対に」の意で、要望と違うものを作ることになり、企業の姿勢として不自然", ""], "ex": "事実<b>に即して</b>、事故の状況を詳しく報告してください。"},
"36146": {"point": "「〜ないものでもない」は「〜できないこともない」という意味で、可能性がないわけではないことを表す。会議の開始までまだ30分ほどあるので、すぐに出れば間に合う可能性はあるという内容に合う。", "opts": ["間に合わないではいられない：「〜ないではいられない」は「どうしても〜してしまう」の意で、意志的な動作に使い、「間に合う」には合わない", "間に合わないどころではない：「〜どころではない」は「〜できる状況ではない」の意で、意味が通らない", "間に合わないまでもない：「〜までもない」は「言うまでもない」のように動詞の辞書形に付き、ない形には付かない", ""], "ex": "タクシーで行けば、最終の新幹線に間に合わ<b>ないものでもない</b>。"},
"36147": {"point": "「〜ならではの」は「〜だけにある特別な」という意味で、それにしかない良さを評価する表現。長い歴史を持つ老舗旅館だからこそ受けられる、行き届いたサービスという意味に合う。", "opts": ["かぎりの：「〜かぎりの」は「できるかぎりの努力」のように「〜できる限界までの」の意で、名詞「老舗旅館」には付かない", "", "まじきの：「〜まじき」は「許すまじき行為」のように辞書形に付いて「〜してはならない」の意を表す。名詞には付かず、「の」も付かない", "にかけての：「〜にかけての」は「春から夏にかけての」のような範囲を表し、意味が合わない"], "ex": "北海道<b>ならではの</b>雄大な景色に感動した。"},
"36148": {"point": "「〜といったところだ」は「だいたい〜ぐらいだ」という意味で、数量の大体の範囲を示す。この辺りの家賃の相場は、ワンルームでだいたい7万円から9万円ぐらいだという内容に合う。", "opts": ["としたこと：「〜としたことが」は「私としたことが」のように、自分の失敗に驚く表現で、家賃の話に合わない", "", "といったこと：「〜といったこと」は「〜のようなこと」と例を挙げる形で、金額の大体の範囲を表さない", "としたところ：「〜としたところで」は「〜としても」の意で、「としたところです」という形では意味が通らない"], "ex": "毎月の食費は、だいたい3万円<b>といったところ</b>です。"},
"36149": {"point": "「〜とは」は「〜なんて」という意味で、驚きやあきれた気持ちを表す。今朝遅刻しておきながら早退したいなんて、自分に都合が良すぎるという話し手のあきれた気持ちに合う。", "opts": ["ことか：「〜ことか」は「どんなにうれしかったことか」のように感嘆を表して文末に使い、後に「虫が良すぎる」は続かない", "ことを：「を」は目的語を示し、後の「虫が良すぎる」とつながらない", "", "ものを：「〜ものを」は「〜のに」という不満や残念な気持ちを表し、「早退したいのに虫が良すぎる」では意味が通らない"], "ex": "約束の時間に1時間も遅れて謝りもしない<b>とは</b>、あきれたものだ。"},
"36150": {"point": "「〜といえども」は「〜であっても」という意味の書き言葉で、前の内容から予想されることと違う事実を述べる。絵本であっても字が多く、低学年には難しいので、高学年に読んでもらいたいという内容に合う。", "opts": ["いわず：「AといわずBといわず」の形で「AもBも区別なく」の意を表し、ここでは意味が合わない", "いうなり：「〜と言うなり」は「〜と言ってすぐに」の意で、逆接にならない", "", "いえても：「といえても」という形はなく、意味が通らない"], "ex": "冬<b>といえども</b>、この地方は昼間はかなり暖かい。"},
"36151": {"point": "「〜にかかわる」は「〜に影響する」という意味で、重大な事柄に関係する場合に使う。株価があまりに安いと、会社の評判にも悪い影響を及ぼすかもしれないという内容に合う。", "opts": ["したがう：「〜にしたがう」は「〜のとおりにする」の意で、「評判にしたがう」では意味が通らない", "そくする：「〜に即する」は「〜に合わせる」の意で、悪い影響を及ぼすという意味を表さない", "", "もとづく：「〜にもとづく」は「〜を根拠にする」の意で、影響を表さない"], "ex": "睡眠不足は、仕事の質に<b>かかわる</b>重要な問題だ。"},
"36152": {"point": "「〜にして」は年齢や段階を表す語に付いて、「〜という段階で（やっと・初めて）」という意味を表す。彼女が40歳という年齢になって初めて出産するという内容に合う。", "opts": ["をもって：「〜をもって」は「本日をもって終了」のように手段や区切りを表し、「40歳で初めて」という段階を表せない", "", "をもとに：「〜をもとに」は「〜を基にして」と材料や根拠を表し、年齢には使わない", "にとして：「にとして」という形はなく、「として」の前に「に」は付かない"], "ex": "彼は60歳<b>にして</b>初めて海外旅行をしたそうだ。"},
"36153": {"point": "「〜なり」は動詞の辞書形に付いて「〜するとすぐに」という意味を表す。夜中に帰ってきた息子の顔を見ると、すぐに大声で怒鳴ったという父親の反応に合う。", "opts": ["", "見ないうちに：「〜ないうちに」は「〜する前に」の意で、顔を見る前に怒鳴ったことになり、不自然", "見たきり：「〜たきり」は「〜したまま（その後変化がない）」の意で、すぐに次の動作が起こる場面に合わない", "見てからというもの：「〜てからというもの」は「〜してからずっと」と、その後長く続く変化を表し、一度怒鳴った場面に合わない"], "ex": "彼は電話を切る<b>なり</b>、部屋を飛び出していった。"},
"36154": {"point": "「〜といったところだ」は「だいたい〜ぐらいのものだ」という意味で、程度が大したことはないことを表す。他の人には厳しい山登りも、中村さんにとっては軽い散歩ぐらいのものだという内容に合う。", "opts": ["といえばこそだ：「〜ばこそ」は理由を強調する形だが、「といえばこそだ」という文末の形はなく、意味が通らない", "といってこそだ：「といってこそだ」という形はなく、意味が通らない", "", "というにはあたらない：「〜にはあたらない」は「〜する必要はない」の意で、「軽い散歩と言う必要はない」となり、前の対比と合わない"], "ex": "夏休みといっても、ゆっくり休めるのは3日<b>といったところだ</b>。"},
"36155": {"point": "「〜とは」は「〜なんて」という意味で、意外なことに対する驚きを表す。普段は大人しい彼があんなに怒るなんてという驚きから、「よほどのことがあったに違いない」という推測につながる。", "opts": ["だに：「〜だに」は「想像するだに恐ろしい」のように限られた動詞に付いて「〜するだけでも」の意を表し、意味が合わない", "ものの：「〜ものの」は「〜けれども」の逆接で、怒ったことから推測する後の文とつながらない", "ときたら：「〜ときたら」は「うちの息子ときたら」のように名詞に付き、不満を込めて話題を示す。動詞「怒る」には付かない", ""], "ex": "あの真面目な彼が無断で欠勤する<b>とは</b>、何かあったのだろうか。"},
"36156": {"point": "「AといいBといい」は「AもBも」という意味で、二つの観点を挙げて「どの点から見ても」と評価する。サービスの点でも雰囲気の点でも最高だというレストランの評価に合う。", "opts": ["といえ/といえ：「AといえBといえ」という形はなく、二つの観点を挙げて評価する表現にはならない", "やら/やら：「AやらBやら」は「本やらノートやら」のように、いろいろなものを雑然と並べる形で、二つの点から高く評価する文に合わない", "", "につき/につき：「〜につき」は「〜なので」「〜ごとに」の意で、二つ並べて評価する形はない"], "ex": "この映画は、ストーリー<b>といい</b>音楽<b>といい</b>、何度見ても感動する。"},
"36157": {"point": "「〜に即して」は「〜に合わせて」という意味で、実情や要望にぴったり合うように物事を行うときに使う。教育現場の希望に合わせて指導方法を変更するという内容に合う。", "opts": ["なりに：「〜なりに」は「彼なりに」のように「〜にふさわしい程度で」の意で、意味が合わない", "ともなると：「〜ともなると」は「〜という立場・段階になると」の意で、後に当然の変化が続き、この文に合わない", "ばかりか：「〜ばかりか」は「〜だけでなく」の意で、後に付け加える内容がなく、意味がつながらない", ""], "ex": "現地の状況<b>に即して</b>、支援の内容を決めていく。"},
"36158": {"point": "「〜といえども」は「〜であっても」という意味の書き言葉で、予想に反する事実を述べる。日本全体が不景気であっても、中小企業の中にはよく頑張っているところもあるという内容に合う。", "opts": ["", "といえばこそ：「〜ばこそ」は理由を強調する形で、「不景気といえばこそ頑張っている」では意味が通らない", "にしては：「〜にしては」は「子どもにしては上手だ」のように、その主語自身を基準と比べて評価する表現で、「日本全体」と「中小企業」を対比するこの文に合わない", "にかけては：「〜にかけては」は「料理にかけては」のように「〜の分野では（優れている）」の意で、意味が合わない"], "ex": "小さな会社<b>といえども</b>、技術力では大企業に負けていない。"},
"36159": {"point": "「〜ならではの」は「〜だけにある特別な」という意味で、その人だからこそ実現できる良さを評価する。文学賞を受賞した作家だからこそ書ける、すばらしい作品だという評価に合う。", "opts": ["といえども：「〜といえども」は「〜であっても」という逆接で、「受賞作家であってもすばらしい」となり、意味が通らない", "", "にかけての：「〜にかけての」は「春から夏にかけての」のような範囲を表し、意味が合わない", "ともなれば：「〜ともなれば」は「〜という立場になれば当然」と一般的な傾向を述べる表現で、先月発表された一つの作品の評価に合わない"], "ex": "この作品には、子育てを経験した作者<b>ならではの</b>温かい視点がある。"},
"36160": {"point": "「〜ないものでもない」は「〜しないこともない」という意味で、条件次第ではそうする可能性があることを控えめに表す。君が本気で大学院で勉強したいのなら、推薦状を書いてもいいという話し手の気持ちに合う。", "opts": ["にすぎない：「〜にすぎない」は「ただ〜だけだ」の意で、「書かないにすぎない」では意味が通らない", "にかぎる：「〜にかぎる」は「〜が一番いい」の意で、「書かないのが一番いい」となり、「本気なら」という条件と矛盾する", "", "こともしない：「書かないこともしない」は不自然な形で、「書いてもいい」という可能性を表せない"], "ex": "君がそこまで頼むなら、手伝わ<b>ないものでもない</b>。"},
"36161": {"point": "「〜にたえない」は「聞く・見る」などの動詞の辞書形に付き、「ひどくて〜できない」という意味を表す。電話の相手の口調があまりにも乱暴で、とても聞いていられないほどだったという内容に合う。", "opts": ["にかたい：「想像にかたくない」のように否定の形で使うのが普通で、「聞くにかたい」とは言わず、意味も合わない", "にかたくない：「〜にかたくない」は「想像・理解」などに付いて「簡単に〜できる」の意で、「聞く」には付かず、意味も合わない", "にほかない：「〜にほかならない」「〜よりほかない」と混同した形で、「にほかない」という表現はない", ""], "ex": "最近のネット上の書き込みには、読む<b>にたえない</b>ものが多い。"},
"36162": {"point": "「〜にたえる」は動詞の辞書形や名詞に付いて「〜する価値がある」「〜するだけの内容がある」という意味を表す。今回の会議では、耳を傾ける価値のある意見がたくさん出たという内容に合う。", "opts": ["", "とばかりに：「〜とばかりに」は「いかにも〜と言わんばかりの様子で」の意で、名詞「意見」を修飾する形にならず、意味も合わない", "にかかわる：「〜にかかわる」は「〜に重大な影響がある」の意で、「耳を傾けるにかかわる意見」では意味が通らない", "ゆえの：「〜ゆえの」は「〜が原因の」の意で、「耳を傾けることが原因の意見」となり、意味が通らない"], "ex": "この作品は、大人の鑑賞<b>にたえる</b>本格的なアニメーションだ。"},
"36163": {"point": "「〜を禁じえない」は「〜という気持ちを抑えることができない」という意味の書き言葉で、怒り・同情・涙などの感情に使う。子どもをねらった犯罪に対して、強い怒りを抑えられないという気持ちを表す。", "opts": ["", "禁じざるをえない：「〜ざるをえない」は「〜しなければならない」の意で、怒りを抑えなければならないという意味になり、文脈と合わない", "禁じるにかたくない：「〜にかたくない」は「想像にかたくない」のように限られた名詞に付く表現で、「禁じるにかたくない」とは言わない", "禁じるばかりではない：「抑えるだけではない」の意になり、怒りを抑えられないという気持ちを表せない"], "ex": "戦争で家族を失った人々の話には、同情<b>を禁じえない</b>。"},
"36164": {"point": "「〜んがために」は動詞のない形に付いて「〜するために」という強い目的を表す書き言葉で、「する」は「せんがために」となる。大学に進学するという目的のために、毎日遅くまで勉強したという内容に合う。", "opts": ["するゆえ：「〜ゆえ」は「〜なので」という理由を表し、進学という目的を表せない", "せんばかりか：「〜んばかり」は「今にも〜しそうな」の意で、「せんばかりか」という形はない", "", "するにあって：「〜にあって」は「非常時にあって」のように名詞に付いて状況を表し、動詞に付く形はない"], "ex": "優勝を勝ち取ら<b>んがために</b>、選手たちは厳しい練習に耐えた。"},
"36165": {"point": "「〜や否や」は動詞の辞書形に付いて「〜するとすぐに」という意味を表す。よほど疲れていたのか、席に着くとすぐに眠ってしまったという内容に合う。", "opts": ["が最後：「〜たが最後」は「一度〜したら、必ず（悪い結果）になる」の意で、た形に付く。「着くが最後」という形にならない", "末に：「〜た末に」は「いろいろした結果」の意で、た形や「名詞＋の」に付く。「すぐに」の意味もない", "", "次第で：「〜次第で」は名詞に付いて「〜によって決まる」の意を表し、「着く次第で」では意味が通らない"], "ex": "父は家に着く<b>や否や</b>、テレビをつけて野球を見始めた。"},
"36166": {"point": "「〜ばそれまでだ」は「〜したら、それで終わりだ（すべてが無駄になる）」という意味。どれだけお金を持っていても、死んでしまえばそれで終わりで、何の意味もないという内容に合う。", "opts": ["それからだ：「〜てからだ」の形で「〜してから始まる」の意を表し、「死んでしまえば」と意味がつながらない", "それぐらいだ：程度を表すだけで、「すべてが終わり」という意味にならない", "それほどでもない：「大したことはない」の意で、「いくらお金を持っていても」という逆接の文と合わない", ""], "ex": "どんなに準備をしても、当日雨が降れ<b>ばそれまでだ</b>。"},
"36167": {"point": "「〜ものを」は「〜のに」という意味で、そうならなかったことへの残念な気持ちや後悔を表す。もう少し早く会社を出ていれば終電に間に合ったのに、今からではもう遅いという後悔の文になる。", "opts": ["まだまだ余裕がある：「〜ものを」は実現しなかったことを残念に思う表現で、終電に間に合わなかったことになるので、余裕があるという内容と矛盾する", "急ぐことはない：「急ぐ必要はない」の意で、終電に間に合わなかったという残念な気持ちと合わない", "", "急げば問題はない：まだ間に合うという意味になり、「間に合ったものを」が表す後悔と矛盾する"], "ex": "一言相談してくれれば手伝った<b>ものを</b>、どうして一人で抱え込んだのか。"},
"36168": {"point": "「〜もさることながら」は「〜もそうだが、それに加えて…も」という意味で、前のことを認めながら、後のことをより強調する。その店の料理は見た目の美しさはもちろん、素材を生かした味でも評判だという内容に合う。", "opts": ["もかまわず：「〜もかまわず」は「〜を気にしないで」の意で、「見た目の美しさを気にしないで」となり、意味が合わない", "", "ならまだしも：「〜ならまだしも」は「〜ならまだ許せるが」の意で、後に批判が続く。評判がよいという文に合わない", "をものともせずに：「〜をものともせずに」は「困難を問題にしないで」の意で、「見た目の美しさ」には使えない"], "ex": "この大学は、研究設備<b>もさることながら</b>、教授陣の質の高さで知られている。"},
"36169": {"point": "「〜にはあたらない」は「〜する必要はない」「〜するほどのことではない」という意味。彼なりに努力してきたのだから、いい結果が得られなくても非難する必要はないという内容に合う。", "opts": ["にすぎない：「〜にすぎない」は「ただ〜だけだ」の意で、「非難するにすぎない」では文脈と合わない", "", "にほかならない：「〜にほかならない」は「まさに〜だ」と断定する意で、「非難するにほかならない」では前の「努力してきたのだから」と合わない", "にかたくない：「〜にかたくない」は「想像にかたくない」のように「簡単に〜できる」の意で、「非難する」には付かない"], "ex": "子どもが少しぐらい失敗したからといって、叱る<b>にはあたらない</b>。"},
"36170": {"point": "「〜にもまして」は「〜以上に」という意味で、前のものと比べてさらに程度が高いことを表す。去年も厳しかったが、今年の新卒者の就職はそれ以上に厳しくなると予想されるという内容に合い、「さらに」とも呼応する。", "opts": ["にかこつけて：「〜にかこつけて」は「〜を口実にして」の意で、意味が合わない", "にかかわらず：「〜にかかわらず」は「〜に関係なく」の意で、去年と比べる文に合わない", "にそくして：「〜に即して」は「〜に合わせて」の意で、比較を表さない", ""], "ex": "今年の夏は、例年<b>にもまして</b>暑さが厳しい。"},
"36171": {"point": "「〜ばそれまでだ」は「〜したら、それで終わりだ」「〜しなければ意味がない」という意味。どんなにいいパソコンを買っても、使わなければ何の意味もないという内容に合う。", "opts": ["そのものだ：「〜そのものだ」は「真剣そのものだ」のように名詞に付いて「まさに〜だ」の意を表し、ここでは意味が通らない", "そのままだ：「変わらない状態だ」の意で、「意味がない」という結論を表せない", "", "それだけだ：「それで全部だ」の意で、「使わなければ意味がない」という結論を表せない"], "ex": "いくらいい計画を立てても、実行しなけれ<b>ばそれまでだ</b>。"},
"36172": {"point": "「〜にたる」は動詞の辞書形に付いて「〜する価値がある」「〜するのに十分だ」という意味を表す。野村君は学校の代表として推薦する価値のある、有望な学生だという内容に合う。", "opts": ["あたる：「〜にあたる」は「〜に相当する」の意で、「推薦するにあたる」では「推薦する価値がある」という意味にならない", "いたる：「〜にいたる」は「〜に到達する」の意で、意味が通らない", "", "なる：「なる」は「〜になる」の形で名詞などに付き、「推薦するになる」という形はない"], "ex": "彼は信頼する<b>にたる</b>人物だ。"},
"36173": {"point": "「〜んがために」は「〜するために」という強い目的を表す書き言葉。営業成績を上げるという目的のために、社員全員が一丸となって頑張っているという内容に合う。", "opts": ["上げようが上げまいが：「〜ようが〜まいが」は「〜してもしなくても関係なく」の意で、目的を持って頑張る文に合わない", "上げんばかりに：「〜んばかりに」は「今にも〜しそうな様子で」の意で、目的を表さない", "上げようにも：「〜ようにも」は後に「〜できない」が続き、「上げようにも上げられない」の形で使う", ""], "ex": "彼らは真実を明らかにせ<b>んがために</b>、長年調査を続けてきた。"},
"36174": {"point": "「〜にたえない」は「見る・聞く」などに付いて「ひどくて〜することができない」という意味を表す。残酷なシーンばかりで、とても見ていられない映画だという内容に合い、「まったく」とも呼応する。", "opts": ["", "見たことになる：「〜ことになる」は「結果として〜となる」の意で、映画のひどさを表せない", "見てやまない：「〜てやまない」は「願う・愛する」など気持ちを表す動詞に付く表現で、「見てやまない」とは言わない", "見ないものでもない：「見ないこともない」の意で、「まったく」と合わず、ひどくて見られないという意味にならない"], "ex": "事故現場は、見る<b>にたえない</b>ありさまだった。"},
"36175": {"point": "「〜やいなや」は動詞の辞書形に付いて「〜するとすぐに」という意味を表す書き言葉。彼が社長に就任すると、すぐに新しい事業を展開したという内容に合う。", "opts": ["うちに：「〜うちに」は「〜している間に」の意で、「就任するうちに」では意味が通らない", "とたんに：「〜たとたんに」は動詞のた形に付き、「就任するとたんに」という形にならない", "", "にひきかえ：「〜にひきかえ」は「〜とは反対に」と二つを対比する表現で、名詞に付き、意味も合わない"], "ex": "試験の終了を告げるベルが鳴る<b>やいなや</b>、学生たちは教室を出ていった。"},
"36176": {"point": "「〜ものを」は「〜のに」という意味で、そうしなかったことへの不満や残念な気持ちを表す。文句があるならそう言えばいいのに、どうして黙っていたのかと相手を責める文になる。", "opts": ["言ったんだ：「〜ものを」は実際にはそうしなかったことへの不満を表すので、「言った」では前の「言えばいいものを」と矛盾する", "", "文句があったんだ：「どうして文句があったのか」となり、言わなかったことを責める「〜ものを」の文と合わない", "だまらなかったんだ：「だまらなかった」は「言った」ということになり、前の「言えばいいものを」と矛盾する"], "ex": "早く病院に行けばすぐに治った<b>ものを</b>、我慢していたから悪化してしまった。"},
"36177": {"point": "「〜にもまして」は「〜以上に」という意味で、前のものよりさらに程度が高いことを表す。責任のある仕事を任されたことで、以前よりもさらに熱心に仕事に励むようになったという内容に合う。", "opts": ["にからんで：「〜にからんで」は「〜に関係して」の意で、「以前にからんで」では意味が通らない", "", "ともなしに：「〜ともなしに」は「見るともなしに」のように動詞に付いて「特に〜するつもりもなく」の意で、名詞「以前」には付かない", "のみならず：「〜のみならず」は「〜だけでなく」の意で、「以前だけでなく」では比較の意味にならない"], "ex": "病気をしてから、彼は以前<b>にもまして</b>健康に気を使うようになった。"},
"36178": {"point": "「〜もさることながら」は「〜もそうだが、それに加えて」という意味で、前のことを認めつつ後のことを強調する。被災地の人々を救ったのは、政府の取り組みもそうだが、ボランティアの人々の協力も大きかったという内容に合う。", "opts": ["としたところで：「〜としたところで」は「〜としても」という逆接の仮定で、意味が合わない", "にいたっては：「〜にいたっては」は「〜の場合は（極端な例として）」の意で、後に程度のひどい例が続き、意味が合わない", "", "をものともせず：「〜をものともせず」は「困難を問題にせずに」の意で、「政府の取り組み」には使えない"], "ex": "彼女の歌は、歌唱力<b>もさることながら</b>、歌詞の素晴らしさが多くの人の心をつかんでいる。"},
"36179": {"point": "「〜にはあたらない」は「〜する必要はない」「〜するほどのことではない」という意味。優秀な山下君なら難しい試験に合格するのも当然なので、驚く必要はないという内容に合う。", "opts": ["にかぎらない：「〜とはかぎらない」「〜にかぎらず」と混同した形で、「驚くにかぎらない」という表現はない", "", "にきまっている：「きっと驚く」という意味になり、「優秀な山下君のことだから」合格は当然だという前の内容と矛盾する", "にちがいない：「きっと驚くだろう」という推測になり、合格は当然だという前の内容と矛盾する"], "ex": "彼の実力なら、優勝したとしても驚く<b>にはあたらない</b>。"},
"36180": {"point": "「〜を禁じえない」は「〜という気持ちを抑えられない」という意味で、同情・怒り・驚きなどの感情に使う。一夜にして財産を火事で失った彼に対して、哀れみの気持ちを抑えられないという内容に合う。", "opts": ["", "禁じさせない：使役の否定で「（他人に）禁じさせない」の意になり、自分の感情を表す文に合わない", "禁じざるを得ない：「〜ざるを得ない」は「〜しなければならない」の意で、哀れみを抑えなければならないという意味になり、合わない", "禁じるほかない：「抑えるしかない」の意になり、哀れみの気持ちを抑えられないという意味と反対になる"], "ex": "彼のあまりに無責任な態度には、驚き<b>を禁じえない</b>。"},
"36181": {"point": "「〜にもまして」は「〜以上に」という意味で、前のものと比べてさらに程度が高いことを表す。今度発売した新製品は、従来品よりもさらに評判がいいという内容に合う。", "opts": ["ともなしに：「〜ともなしに」は「聞くともなしに」のように動詞に付いて「特にそのつもりもなく」の意で、名詞「従来品」には付かない", "ばかりか：「〜ばかりか」は「〜だけでなく…も」の意で、「従来品だけでなく好評だ」では主語の「新製品」と合わず、比較の意味にもならない", "", "ならまだしも：「〜ならまだしも」は「〜ならまだ許せるが」の意で、後に不満が続き、「好評だ」と合わない"], "ex": "今回の試験は、前回<b>にもまして</b>難しかった。"},
"36182": {"point": "「〜を禁じえない」は「〜を抑えられない」という意味で、感情や涙などが自然に出てしまうことを表す。最後の感動的な場面で涙を抑えることができなかったという内容で、過去のことなので「禁じえなかった」となる。", "opts": ["禁じえた：「抑えることができた」の意になり、感動的な場面に心を動かされたという流れと合わない", "禁じた：「禁じる」は「禁止する」の意で、「涙を禁止した」となり、意味が通らない", "", "禁じなかった：「禁止しなかった」の意になり、感情を抑えられないという意味にならない"], "ex": "長年離れて暮らしていた家族との再会に、涙<b>を禁じえなかった</b>。"},
"36183": {"point": "「〜んがため」は動詞のない形に付いて「〜するために」という強い目的を表す書き言葉。論文を仕上げるという目的のために、夜も眠らずに努力しているという内容に合う。", "opts": ["仕上げるともなく：「〜ともなく」は「見るともなく」のように「特に〜するつもりもなく」の意で、夜も眠らずに努力する様子と矛盾する", "", "仕上げようにも：「〜ようにも」は後に「〜できない」が続き、「仕上げようにも仕上げられない」の形で使う", "仕上げるまじく：「〜まじき」は「〜してはならない」の意で、「仕上げるまじく」は不自然な形で、意味も合わない"], "ex": "新記録を出さ<b>んがため</b>、彼は毎朝欠かさず練習している。"},
"36184": {"point": "「〜にたえない」は「感謝・遺憾・喜び」など感情を表す名詞に付いて「とても〜だ」「〜の気持ちを抑えられない」という意味を表す。「遺憾にたえません」は、事故で多くの死亡者を出したことを非常に残念に思うという改まった表現。", "opts": ["こたえません：「こたえる」は「期待にこたえる」「寒さが身にこたえる」のように使い、「遺憾にこたえません」では意味が通らない", "", "そえません：「〜にそう」は「期待にそう（期待に合う）」の意で、「遺憾にそえません」では意味が通らない", "やむをえません：「やむをえない」は「しかたがない」の意で、「遺憾に」の「に」の後には続かない"], "ex": "皆様の温かいご支援には、感謝の念<b>にたえません</b>。"},
"36185": {"point": "「〜にたりない」は動詞の辞書形に付いて「〜する価値がない」「〜するほどのことではない」という意味を表す。この程度の実力なら、彼は恐れる必要もない相手だという内容になる。", "opts": ["", "おそれるにも：「〜にたりない」は辞書形に直接「に」が付く形で使い、「も」を入れた「おそれるにもたりない」とは普通言わない", "おそれ：「ます形＋たりない」は「遊びたりない（まだ十分に遊んでいない）」の意になり、「〜する価値がない」という意味にならない", "おそれて：「て形＋たりない」という形はなく、「〜にたりない」は辞書形に「に」が付く形で使う"], "ex": "そんな噂は取る<b>にたりない</b>ものだから、気にしなくていい。"},
"36186": {"point": "「〜やいなや」は動詞の辞書形に付いて「〜するとすぐに」という意味を表す。デパートのドアが開くとすぐに、客たちがバーゲン会場に一斉に押し寄せたという内容に合う。", "opts": ["が最後：「〜たが最後」は「一度〜したら必ず（悪い結果）になる」の意で、た形に付く。「開くが最後」という形にならない", "とたん：「〜たとたん」は動詞のた形に付き、「開くとたん」という形にならない", "ばかり：「辞書形＋ばかりだ」は「ますます〜する」の意で、「開くばかり」では「すぐに」の意味にならない", ""], "ex": "その歌手がステージに現れる<b>やいなや</b>、会場から大きな歓声が上がった。"},
"36187": {"point": "「〜もさることながら」は「〜もそうだが、それに加えて」という意味で、前のものを認めたうえで後のものをさらに強調する。斬新なストーリーはもちろん、それに加えて映像の美しさもすばらしいという文で、後の「映像の美しさも」の「も」と合う。", "opts": ["とはいうものの：「〜とはいうものの」は「〜とは言っても（実際は）」という逆接で、後に否定的な内容が続く。ストーリーと映像の両方をほめるこの文に合わない", "どころではなく：「〜どころではない」は「〜できる状況ではない」の意で、ストーリーを否定することになり、文意に合わない", "をぬきにして：「〜をぬきにして」は「〜を除いて・考えに入れないで」の意。ストーリーを除外する意味になり、「映像の美しさも」の「も」と合わない", ""], "ex": "この店は、料理の味<b>もさることながら</b>、店員の接客もすばらしい。"},
"36188": {"point": "「〜にはあたらない」は「〜する必要はない・〜するほどのことではない」という意味。試験に落ちても、また挑戦すればいいのだから、悲観する必要はないと励ます文になる。", "opts": ["するよりほかない：「〜よりほかない」は「〜するしか方法がない」の意。悲観するしかないという意味になり、「また挑戦すればいい」と矛盾する", "しないではおかない：「〜ないではおかない」は「必ず〜する・必ず〜させる」の意。強い意志や自然に引き起こされる結果を表し、励ましの文に合わない", "", "しないはずがない：「〜ないはずがない」は「必ず〜するはずだ」という強い推量。悲観するに決まっているという意味になり、後の文と合わない"], "ex": "一度の失敗くらいで、そんなに落ち込む<b>にはあたらない</b>。"},
"36189": {"point": "「〜ものを」は「〜のに」という意味で、そうすればよかったのにしなかったことへの不満や後悔を表す。黙っていればよかったのに、余計なことを言って相手を怒らせてしまったという残念な気持ちに合う。", "opts": ["ものの：「〜ものの」は「〜けれども」と、実際に起きた事実を認めて逆の内容を続ける表現。実現しなかった「黙っていればいい」への後悔や不満は表せない", "ものか：「〜ものか」は「絶対に〜しない」という強い否定で、文末に使う。後に文が続くこの位置には入らない", "", "ものだ：「〜ものだ」は一般的な性質や過去の回想を表す文末表現で、後の「余計なことをしゃべって」につながらない"], "ex": "早く相談してくれればよかった<b>ものを</b>、彼は一人で悩み続けていた。"},
"36190": {"point": "「〜ばそれまでだ」は「〜したら、それで終わりだ・もうどうしようもない」という意味。このチャンスを逃したら、こんな機会は二度と来ないのだから、すべて終わりだという後の文と合う。", "opts": ["それだけだ：「それだけだ」は「ただそれだけのことだ」と範囲の限定を表し、機会を逃したらもう終わりだという意味にならない", "", "そのとおりだ：「そのとおりだ」は相手の言ったことに同意する表現で、「逃せば」の後に来る結果を表せない", "それほどでもない：「それほどでもない」は「大したことはない」の意。二度とない機会を逃す深刻さと矛盾する"], "ex": "どんなに準備しても、当日寝坊してしまえ<b>ばそれまでだ</b>。"},
"36191": {"point": "「〜のかたわら」は「〜をしながら、その一方で」という意味で、主な仕事や活動のほかに、別のことも並行して続ける様子を表す。子育てをしながら、その一方で近所の子供たちにピアノを教えているという文に合う。", "opts": ["いかんで：「〜いかんで」は「〜によって（結果が変わる）」の意。子育てによってピアノを教えるかどうかが決まる意味になり、文意に合わない", "ゆえに：「〜ゆえに」は「〜が原因で」という理由を表す硬い表現。子育てがピアノを教える理由になってしまい、不自然", "そばから：「〜そばから」は動詞に付いて「〜してもすぐにまた」と繰り返しを表す。「子育ての」という名詞＋「の」には付かない", ""], "ex": "彼は会社勤めの<b>かたわら</b>、週末は小説を書いている。"},
"36192": {"point": "「〜かぎりだ」は感情を表す形容詞に付き、「とても〜だ」と話し手の強い気持ちを表す。長年の念願がやっとかなった喜びを表すので、感情形容詞の「うれしい」が入る。", "opts": ["", "楽しむ：動詞なので「〜かぎりだ」の形にならない。「かぎりだ」は「うれしい・寂しい」などの感情形容詞に付く", "うれしさ：名詞なので「〜かぎりだ」の形にならない。「かぎりだ」は「うれしい」のような感情形容詞に直接付く", "喜ぶ：動詞なので「〜かぎりだ」の形にならない。強い感情を表すには形容詞の「うれしい」が必要"], "ex": "長年の友人が近くに引っ越してきて、心強い<b>かぎりだ</b>。"},
"36193": {"point": "「〜からある」は数量を表す言葉に付き、「〜以上もある」と大きさや多さを強調する。幹周りが10メートル以上もある大木だという、木の大きさを強調する文に合う。", "opts": ["", "だけある：「〜だけ（のことは）ある」は「それにふさわしい」と評価する表現で、数量の大きさを強調する意味にならない", "からする：「〜からする」は「100万円からする時計」のように値段に使う。長さや大きさには使わない", "だけする：「だけする」という言い方は一般的ではなく、「〜以上もある」という意味を表せない"], "ex": "高さ100メートル<b>からある</b>滝が、目の前に現れた。"},
"36194": {"point": "「〜かたがた」は「〜を兼ねて」という意味で、あいさつや訪問などの改まった場面で使う。書面での案内を兼ねてあいさつするという、手紙の結びの決まった表現になる。", "opts": ["といえば：「〜といえば」は話題を取り上げて連想を述べる表現で、「案内」と「挨拶」を兼ねる意味にならない", "というより：「〜というより」は「〜と言うよりもむしろ」と比べて言い直す表現で、「案内を兼ねて」の意味にならない", "からして：「〜からして」は「〜をはじめとして・〜から判断して」の意。案内とあいさつを兼ねる意味を表せない", ""], "ex": "近くまで参りましたので、ご挨拶<b>かたがた</b>お邪魔いたしました。"},
"36195": {"point": "「〜ことなしに」は「〜しないで」という意味の硬い表現で、「〜ことなく」とも言う。どんなに失敗しても、あきらめないで挑戦し続けたという文で、辞書形の「あきらめる」に付く。", "opts": ["", "ものなしに：「もの」を使った「ものなしに」という形はない。「〜しないで」の意味は「ことなしに」で表す", "ものなければ：「ものなければ」という形はなく、「〜しないで」の意味も表せない", "ことなければ：「ことなければ」という形は使わない。「〜しないで」の意味には「ことなしに」「ことなく」を使う"], "ex": "彼女は一度も休む<b>ことなしに</b>、三年間練習に通い続けた。"},
"36196": {"point": "「〜がてら」は「〜のついでに」という意味で、ある行動をする機会を利用して、別のこともする様子を表す。散歩のついでにコンビニに行ってくるという文に合う。", "opts": ["なりに：「〜なりに」は「〜にふさわしく・〜の程度で」の意。「散歩なりに」では意味をなさない", "", "がちに：「〜がち」は「病気がち」のように、好ましくない傾向を表す。散歩のついでの意味にならない", "ながら：「ながら」は動詞のます形に付くので「散歩しながら」になる。名詞に直接付く「〜ながら」は「子供ながら」のように逆接を表し、意味が合わない"], "ex": "買い物<b>がてら</b>、駅前の新しいカフェに寄ってみた。"},
"36197": {"point": "「AあってのB」は「Aがあるからこそ、Bが成り立つ」という意味。社員がいるからこそ会社が成り立つという意味になり、社員が働きやすい環境作りが欠かせないという後の文とも合う。", "opts": ["あっては：「〜にあっては」は「〜という状況では」の意で、「に」が必要。後に「会社である」と続けても意味が通らない", "", "あってで：「あってで」という形はなく、文法的に誤り。「AがあるからこそB」の意味は「あっての」で表す", "あっても：「〜があっても」は逆接の仮定で、「社員がいても会社である」となり意味が通らない"], "ex": "お客様<b>あっての</b>商売なのだから、いつも感謝の気持ちを忘れてはいけない。"},
"36198": {"point": "「〜が早いか」は「〜するとすぐに」という意味で、辞書形に付き、前の動作の直後に後の動作が起こる様子を表す。席に着くとすぐに、当たり前のようにたばこに火をつけるという文に合う。", "opts": ["とあって：「〜とあって」は「〜という特別な状況なので」と理由を表す。席に着いた直後の動作を表す意味にならない", "", "かと思ったら：「〜たかと思ったら」は「着いたかと思ったら」のようにた形に付き、話し手が見た意外な変化を表す。辞書形の「着く」には続かない", "あげく：「〜たあげく」はた形に付き、「さんざん〜した結果（悪い結果に）」の意。直後の動作を表さない"], "ex": "息子は家に帰ってくる<b>が早いか</b>、ゲームを始めた。"},
"36199": {"point": "「〜かぎり」は「〜している間は・〜という状態が続く間は」という意味で、その状態が続く範囲を表す。応援してくれるファンがいる間は歌い続けるという、引退のうわさを否定する決意の文に合う。", "opts": ["", "ばかり：「〜ばかり」は「〜だけ」と限定を表すが、「ファンがいるばかり」では「歌い続ける」ための条件にならない", "とおり：「〜とおり」は「〜と同じように」の意で、「ファンがいるとおり」では意味が通らない", "ほど：「〜ほど」は程度を表し、「ファンがいるほど」では歌い続ける間の条件の意味にならない"], "ex": "体が元気な<b>かぎり</b>、この仕事を続けたい。"},
"36200": {"point": "「〜こととて」は「〜なので」という意味の硬い表現で、事情を説明してわびたり、許しを求めたりするときに使う。新入社員なので不十分な点もあるが、よろしくお願いしますという改まったあいさつに合う。", "opts": ["からして：「〜からして」は「〜をはじめとして・〜から判断して」の意。名詞に直接付き、「新入社員の」には付かない", "ものの：「〜ものの」は「〜けれども」という逆接で、名詞には「であるものの」の形で付く。また理由を表さない", "", "おかげで：「〜おかげで」はよい結果の原因を表す。「不十分な点もある」という好ましくない内容には合わない"], "ex": "何分にも子どものした<b>こととて</b>、どうかお許しください。"},
"36201": {"point": "「〜こととて」は「〜なので」という理由を表す硬い表現。昼間はにぎやかな繁華街も、早朝なので人影がまばらだったという文で、「早朝の」に付いて理由を表す。", "opts": ["ことからは：「〜ことから」は「〜という事実から判断して」の意で、名詞＋「の」には付かない。「ことからは」という形も不自然", "ことして：「ことして」という形はなく、理由の意味も表せない。理由は「〜こととて」で表す", "", "ことさえ：「〜さえ」は「〜も（極端な例）」の意で、「早朝のことさえ」では人影がまばらな理由にならない"], "ex": "休日の<b>こととて</b>、事務所には誰もいなかった。"},
"36202": {"point": "「〜がてら」は「〜のついでに」という意味で、一つの行動で二つの目的を果たすことを表す。動詞のます形や動作を表す名詞に付く。涼むついでに夜の街を散歩しようと誘う文に合う。", "opts": ["にたる：「〜にたる」は「信頼にたる」のように「〜する価値がある」の意で、「に」が必要。ついでの意味にならない", "ごとき：「〜のごとき」は「〜のような」の意の硬い表現で、「涼みごとき」では意味が通らない", "", "なりに：「〜なりに」は「〜にふさわしく」の意で、ます形の「涼み」に付いて「ついでに」の意味を表すことはできない"], "ex": "駅まで友人を送り<b>がてら</b>、本屋に寄ってきた。"},
"36203": {"point": "「〜が早いか」は「〜するとすぐに」という意味で、動詞の辞書形に付く。弟が晩ご飯を食べ終わるとすぐに宿題を始めたという文で、辞書形の「食べ終わる」に付く。", "opts": ["限り：「〜限り」は「〜している間は」の意で、「食べ終わる限り」では宿題をし始めたという一回の出来事と合わない", "", "とたん：「〜たとたん」はた形に付くので「食べ終わったとたん」となる。辞書形の「食べ終わる」には付かない", "なりか：「なりか」という形はない。「〜するとすぐに」の意味なら「食べ終わるなり」となる"], "ex": "彼女はベルが鳴る<b>が早いか</b>、教室を飛び出していった。"},
"36204": {"point": "「〜あってのこと」は「〜があるからこそ成り立つことだ」という意味。この地域で農業が盛んなのは、豊かな水の恵みがあるからこそだと、理由を強調して説明する文に合う。", "opts": ["", "あるからの：「からの」で「こと」に続ける言い方は一般的でない。「〜があるからこそ成り立つ」という意味は「あってのことだ」の形で表す", "あるの：辞書形に「の」を付けて「あるのことだ」とする形は文法的に誤り", "あればの：「〜ばのことだ」は「〜ならの話だ」と仮定の条件を表す。実際に農業が盛んな理由を説明する文に合わない"], "ex": "今日の成功は、仲間の協力が<b>あっての</b>ことだ。"},
"36205": {"point": "「〜かたわら」は「〜をしながら、その一方で」という意味で、本業を持ちながら別の活動も続けている様子を表す。市役所に勤める一方で、ボランティアで日本語を教えているという文に合う。", "opts": ["こととて：「〜こととて」は「〜なので」と理由を表す。市役所に勤めることがボランティアの理由になり、意味が通らない", "かたがた：「〜かたがた」は「お礼かたがた」のように名詞に付き、「〜を兼ねて」訪問などをする意。長く続ける二つの活動には使わない", "うちに：「〜うちに」は「〜している間に（変化が起こる）」の意で、二つの活動を並行して続ける意味を表せない", ""], "ex": "父は会社を経営する<b>かたわら</b>、地域の少年野球の監督も務めている。"},
"36206": {"point": "「〜ないかぎり」は「〜しなければ（ずっと〜だ）」という意味で、その条件が満たされない間は状況が変わらないことを表す。彼が素直に謝らなければ決して許さないという強い気持ちに合う。", "opts": ["いたり：「〜のいたり」は「光栄のいたり」のように名詞に付いて「この上なく〜だ」の意。動詞の否定形には付かない", "ごとき：「〜ごとき」は「〜のような」の意で、「謝らないごとき」という形は不自然。許さないための条件も表せない", "しまつ：「〜しまつだ」は悪い結果を表す文末表現で、後に「私は決して許すつもりはない」と続けられない", ""], "ex": "本人がやる気にならない<b>かぎり</b>、いくら周りが言っても無駄だ。"},
"36207": {"point": "「〜かぎりだ」は感情を表す形容詞に付き、「とても〜だ」と話し手の強い気持ちを表す。楽しみにしていた家族旅行をあきらめなければならない、とても残念な気持ちを表す文に合う。", "opts": ["極みだ：「〜の極み」は「感激の極み」のように名詞＋「の」に付く。「残念な極み」という形にはならない", "", "あげくだ：「〜たあげく」は「さんざん〜した結果」の意で、動詞のた形に付く。感情を表す「残念な」には付かない", "末だ：「〜た末」は「いろいろ〜した結果」の意で、動詞のた形や名詞＋「の」に付く。「残念な末」という形はない"], "ex": "卒業してみんなと会えなくなるのは、寂しい<b>限りだ</b>。"},
"36208": {"point": "「〜かたがた」は「〜を兼ねて」という意味で、訪問などで二つの目的を同時に果たすことを表す改まった表現。先日のお礼を兼ねて伺ったという、かしこまったあいさつの文に合う。", "opts": ["次第：名詞に付く「〜次第」は「〜によって決まる」の意。「お礼次第で伺う」という意味になり、文意に合わない", "にかぎって：「〜にかぎって」は「〜の場合だけ特に（悪いことが起こる）」の意で、訪問の目的を表せない", "", "と思いきや：「〜と思いきや」は「〜と思ったが、意外にも」の意で、お礼に伺ったという文脈と合わない"], "ex": "就職のご報告<b>かたがた</b>、恩師のお宅を訪ねた。"},
"36209": {"point": "「〜ことなしに」は「〜しないで」という意味の硬い表現。銀行からお金を借りないで、自分の力で家を建てたという文で、辞書形の「借りる」に付く。", "opts": ["ことなければ：「ことなければ」という形はなく、「借りないで」の意味を表せない", "ことないまでも：「〜ないまでも」は「借りないまでも」のように動詞の否定形に付き、「ことないまでも」という形はない", "", "ことしないで：「〜しないで」は「借りないで」のように動詞に直接付く。「借りることしないで」は文法的に誤り"], "ex": "彼は誰にも相談する<b>ことなしに</b>、会社を辞めてしまった。"},
"36210": {"point": "「〜からある」は数量を表す言葉に付き、「〜以上もある」と多さを強調する。2000冊以上もある絵本を自由に読めるという、絵本の数の多さを強調する文に合う。", "opts": ["", "どころか：「〜どころか」は「〜は言うまでもなく・〜とは反対に」の意で、後に対比する内容が必要。「2000冊どころか絵本を」では意味が通らない", "さえ：「〜さえ」は「〜も（極端な例）」の意で、「2000冊さえ絵本を」では意味が通らない", "ずくめの：「〜ずくめ」は「黒ずくめ」「いいことずくめ」のように「〜ばかり」の意で、数量には付かない"], "ex": "この湖には、体長1メートル<b>からある</b>魚がいるそうだ。"},
"36211": {"point": "「〜かぎりだ」は感情を表す形容詞に付き、「とても〜だ」と話し手の強い気持ちを表す。仕事も家庭も順調な相手を見て、とてもうらやましいと感じる気持ちを表す文に合う。", "opts": ["あげくだ：「〜たあげく」は「さんざん〜した結果」の意で、動詞のた形に付く。形容詞の「うらやましい」には付かない", "あまりだ：「〜あまり」は「〜すぎて（ある結果になる）」の意で、後に結果が続く形で使う。「うらやましいあまりだ」で文を終えて強い感情を表すことはできない", "", "ごとくだ：「〜ごとくだ」は「〜のごとくだ」の形で「〜のようだ」の意。形容詞に直接付かず、気持ちの強さも表せない"], "ex": "大切な試合に負けてしまい、悔しい<b>かぎりだ</b>。"},
"36212": {"point": "「〜ないかぎり」は「〜しなければ（ずっと〜だ）」という意味で、その条件が満たされなければ状況は変わらないことを表す。先方が譲歩しなければ、この条件では契約できないという文に合う。", "opts": ["すら：「〜すら」は「〜さえ」と同じく極端な例を表し、「譲歩しないすら」では条件の意味にならない", "うえに：「〜うえに」は「〜だけでなく、さらに」と付け加える表現で、契約できないための条件を表せない", "", "かたわら：「〜かたわら」は「〜をしながら、その一方で」と二つの活動を並行して行う意で、文意に合わない"], "ex": "手術を受けない<b>かぎり</b>、この病気は治らないそうだ。"},
"36213": {"point": "「〜ことなしに」は「〜しないで」という意味で、後に「〜できない・不可能だ」などの否定的な内容が続くと「〜しなければ〜できない」という条件を表す。みんなが協力しなければ難問は解決できないという文に合う。", "opts": ["ないでは：「〜ないでは」は動詞の否定形に付き「取り組まないでは」となる。辞書形の「取り組む」には付かない", "ところで：「〜たところで」はた形に付き「〜しても無駄だ」の意。辞書形の「取り組む」には付かず、意味も合わない", "ものの：「〜ものの」は「〜けれども」と事実を認める逆接で、まだ起きていない仮定の話には合わない", ""], "ex": "努力する<b>ことなしに</b>、成功を手に入れることはできない。"},
"36214": {"point": "「〜かたわら」は「〜をしながら、その一方で」という意味で、主な仕事のほかに別の活動も続けている様子を表す。作家が小説を書く一方で、絵も描いているという文に合う。", "opts": ["がてら：「〜がてら」は「散歩がてら」のように「〜のついでに」の意で、一時的な行動に使う。長く続ける二つの活動には合わない", "", "ところを：「〜ところを」は「お忙しいところを」のように相手に迷惑をかける場面などで使い、並行する活動を表さない", "にたる：「〜にたる」は「〜する価値がある」の意で、「小説を書くにたる」では後の「絵も描いている」と合わない"], "ex": "兄は大学で研究する<b>かたわら</b>、高校生に数学を教えている。"},
"36215": {"point": "「〜あってのこと」は「〜があるからこそ成り立つことだ」という意味。仕事を続けてこられたのは家族の支援があったからこそだと、感謝の気持ちを込めて理由を強調する文に合う。", "opts": ["", "いかんでは：「〜いかんでは」は「〜によっては」の意で、結果が変わる可能性を表す。すでに実現したことの理由を表せない", "かたがた：「〜かたがた」は「〜を兼ねて」の意で、後に訪問などの動作が続く。「ことだ」とは結びつかない", "あげくの：「〜たあげく」は「さんざん〜した結果（悪い結果）」の意で、動詞のた形に付く。感謝の内容にも合わない"], "ex": "優勝できたのは、チーム全員の努力<b>あっての</b>ことだ。"},
"36216": {"point": "「〜がてら」は「〜のついでに」という意味で、ある行動の機会を利用して別のこともする様子を表す。出張のついでに、友人の彫刻の展示会を観に行ったという文に合う。", "opts": ["かたわら：「〜かたわら」は本業のほかに別の活動を長く続ける意で、「昨日は」という一回の出来事には合わない", "につれて：「〜につれて」は「一方が変化すると、もう一方も変化する」の意で、変化を表さない「出張」には合わない", "", "にともなって：「〜にともなって」は「〜と一緒に変化が起こる」の意で、ついでに何かをするという意味を表せない"], "ex": "図書館に本を返し<b>がてら</b>、近くの公園を散歩した。"},
"36217": {"point": "「〜かたがた」は「〜を兼ねて」という意味で、手紙や改まった会話で使う。入院した先生に、お見舞いを兼ねてあいさつに伺うという丁寧な内容で、敬語を使った文体とも合う。", "opts": ["", "しながら：「〜しながら」は二つの動作を同時に行う意で、「お見舞いを兼ねて訪ねる」という目的の意味を表せない", "一方で：「〜一方で」は二つのことを対比させる表現で、お見舞いとあいさつを兼ねる意味にならない", "ともに：「〜とともに」と「と」が必要。また「一緒に・同時に」の意で、訪問の目的を兼ねる意味を表せない"], "ex": "新年のご挨拶<b>かたがた</b>、近況をお知らせいたします。"},
"36218": {"point": "「〜こととて」は「〜なので」という理由を表す硬い表現。部屋を見に行った日はあいにく雨の日だったので、日当たりがどうか分からなかったという文に合う。", "opts": ["ことさえ：「〜さえ」は「〜も（極端な例）」の意で、「雨の日のことさえ」では日当たりが分からなかった理由にならない", "ことには：「〜ないことには」は「〜しなければ」の意で、動詞の否定形に付く。「雨の日のことには」では意味が通らない", "ことでは：「ことでは」は理由を表さず、「雨の日のことでは」では後の内容につながらない", ""], "ex": "慣れない土地の<b>こととて</b>、道に迷ってしまった。"},
"36219": {"point": "「〜が早いか」は「〜するとすぐに」という意味で、動詞の辞書形に付く。受験生たちは答案を書き終わるとすぐに提出して教室を出たという文で、辞書形の「書き終わる」が入る。", "opts": ["書き終わり：ます形には「が早いか」は付かない。「〜が早いか」は辞書形の「書き終わる」に付く", "書き終わって：て形には「が早いか」は付かない。「〜が早いか」は辞書形に付く", "", "書き終わろう：意向形には「が早いか」は付かない。「〜ようが」は「〜しても」の意味になり、文意も合わない"], "ex": "父は布団に入る<b>が早いか</b>、いびきをかき始めた。"},
"36220": {"point": "「〜からある」は数量を表す言葉に付き、「〜以上もある」と大きさを強調する。身長が2メートル以上もある大男が突然現れて驚いたという、男の大きさを強調する文に合う。", "opts": ["でもない：「〜でもない」は「〜というわけでもない」と否定する表現で、「大男」を修飾して大きさを強調できない", "", "ほかない：「〜ほかない」は「〜するしかない」の意で、動詞に付く。数量の「2メートル」には付かない", "までなる：「〜までになる」のように「に」が必要。また変化を表し、「〜以上もある」の意味にならない"], "ex": "重さ50キロ<b>からある</b>石を、彼は軽々と持ち上げた。"},
"36221": {"point": "「〜てかなわない」は「とても〜で我慢できない」という意味で、な形容詞には「〜でかなわない」の形で付く。駅から遠くて、とても不便で我慢できないという不満を表すので、て形の「不便で」が入る。", "opts": ["不便に：「〜にかなわない」という形はなく、「かなわない」の前にはて形の「不便で」が必要", "", "不便な：「不便な」は名詞を修飾する形で、「かなわない」に直接つながらない", "不便なら：「〜なら」は仮定の条件で、実際に不便だという不満を表す「〜てかなわない」の形にならない"], "ex": "隣の部屋の工事がうるさく<b>てかなわない</b>。"},
"36222": {"point": "「〜たるもの」は「〜という立場にある者は」という意味で、後に「〜べきだ」など、その立場にふさわしいあり方が続く。政治家という立場にある者は、国民の声に耳を傾けるべきだという文に合う。", "opts": ["とするもの：「とするもの」という言い方はなく、「〜という立場にある者は」の意味を表せない", "", "まじく：「〜まじき」は「あるまじき行為」のように「〜してはならない」の意で、名詞を修飾する。「政治家まじく」という形はない", "にするところ：「にするところ」という形はなく、「〜という立場にある者は」の意味を表せない"], "ex": "教師<b>たるもの</b>、生徒の手本とならなければならない。"},
"36223": {"point": "「疑問詞＋ともなく」は「はっきりとは分からないが」という意味で、「どこからともなく」は「どこからか分からないが」を表す。パンの香りがどこから来たのか分からないまま漂ってきた様子に合う。", "opts": ["", "とはいえ：「〜とはいえ」は「〜とは言っても」という逆接で、「どこから」に付いても意味をなさない", "とあいまって：「〜とあいまって」は「〜と一緒になって（効果を高める）」の意で、名詞に付く。「どこから」には付かない", "とばかりに：「〜とばかりに」は「いかにも〜と言うように」の意で、香りが漂う様子とは結びつかない"], "ex": "夕方になると、どこから<b>ともなく</b>鐘の音が聞こえてくる。"},
"36224": {"point": "「〜でなくてなんだろう」は「これが〜でなければ何だろうか、まさに〜だ」という意味で、強く断定する表現。クラス全員で一人に嫌がらせや無視をするのは、まさにいじめだと強く主張する文に合う。", "opts": ["にすぎないだろう：「〜にすぎない」は「ただ〜だけだ」と程度が低いことを表し、いじめを強く非難する文に合わない", "ではないだろう：「〜ではないだろう」はいじめであることを否定する推量になり、文意と逆になる", "であってなんだろう：「であってなんだろう」という形はなく、強い断定の意味は「でなくてなんだろう」で表す", ""], "ex": "命をかけて子どもを守る、これが愛<b>でなくてなんだろう</b>。"},
"36225": {"point": "「〜たりとも〜ない」は「一円」「一秒」など最小の数量に付き、「少しの〜も〜ない」と強く否定する。苦労してためたお金なので、一円も無駄には使いたくないという文に合う。", "opts": ["ばかりも：「ばかりも」という形はなく、最小の数量を強調して否定する意味を表せない", "", "だけさえ：「だけさえ」という形はなく、「少しの〜も〜ない」という強い否定の意味を表せない", "とはいえ：「〜とはいえ」は「春とはいえまだ寒い」のように、前の事実から予想されることと違う内容を続ける逆接。「〜ない」と結びついて「少しも〜ない」と強く否定する働きはない"], "ex": "試験中は、一秒<b>たりとも</b>気を抜くことはできない。"},
"36226": {"point": "「〜なりに」は「〜にふさわしく・〜にはそれ相応に」という意味で、よい条件ではなくても、それに応じた良さがあることを表す。雨の日には雨の日にふさわしい趣があり、境内の景色がきれいだったという文に合う。", "opts": ["", "までに：「〜までに」は「三時までに」のように期限を表し、「雨の日までに」では意味が通らない", "にかかわり：「〜にかかわりなく」の形で「〜に関係なく」の意になる。「にかかわり」だけでは使えない", "なくして：「〜なくして（は）」は「〜がなければ」の意で、後に否定的な内容が続く。きれいな景色だったという文に合わない"], "ex": "子どもには子ども<b>なりに</b>、悩みがあるものだ。"},
"36227": {"point": "「いかなる〜にあっても」は「どんな〜であっても」という意味の硬い表現。どんな時代であっても、安全と健康の確保はすべてに優先する課題であるという、時代を問わない主張に合う。", "opts": ["つけて：「〜につけて」は「何かにつけて」「見るにつけ」のように「〜するたびに」の意で、「いかなる時代につけて」とは言わない", "とって：「〜にとって」は「〜の立場から見ると」の意で、「時代にとって」では「どんな時代でも」の意味にならない", "", "かけても：「〜にかけても」は「名誉にかけても」のように「〜を賭けて」の意で、意味が合わない"], "ex": "いかなる状況に<b>あっても</b>、冷静さを失ってはならない。"},
"36228": {"point": "「〜ところを」は「〜している時なのに」という意味で、相手の状況を思いやり、恐縮する気持ちを表す。忙しい時なのに集まってもらったことに、恐縮しながらお礼を言う文に合う。", "opts": ["うちに：「〜うちに」は「〜している間に」の意で、恐縮する気持ちを表せない。「お忙しいうちに」では意味が通らない", "に際して：「〜に際して」は「出発に際して」のように名詞や辞書形に付き、「〜するときに」の意。形容詞の「お忙しい」には付かない", "", "にあって：「〜にあって」は「非常時にあって」のように名詞に付き、「〜という状況で」の意。形容詞には付かない"], "ex": "お休みの<b>ところを</b>お邪魔して、申し訳ございません。"},
"36229": {"point": "「〜は言うにおよばず」は「〜は言うまでもなく、もちろん」という意味で、後に「〜まで」「〜も」が続くことが多い。遊園地はもちろん、博物館まで家族連れであふれていたという文に合う。", "opts": ["およべば：仮定の「〜ば」の形になり、「言うにおよべば」という言い方はしない", "およんで：「言うにおよんで」という形は使わない。「〜に及んで」は「この期に及んで」のように「〜の段階になって」の意で、意味も合わない", "", "およばなくて：「言うにおよばなくて」という形は使わない。「〜はもちろん」の意味は「言うにおよばず」で表す"], "ex": "東京は言うに<b>およばず</b>、地方の都市でも外国人観光客が増えている。"},
"36230": {"point": "「〜と言わんばかりに」は「今にも〜と言いそうな様子で」という意味で、「〜とばかりに」とも言う。にらみつける人は、言葉にはしないが「タバコを吸うな」と言いそうな様子なので、禁止の「吸うなと」が入る。", "opts": ["吸えと：命令の「吸え」になり、「タバコを吸え」と言いそうな様子になる。ヒステリックににらみつける様子と合わない", "吸うと：「吸うとばかりに」では「吸う」と言いそうな様子になり、にらみつける人の非難の気持ちを表せない", "吸おうと：「吸おう」は意志や誘いを表し、「吸おうとばかりに」ではにらみつける人の気持ちを表せない", ""], "ex": "店員は、早く出て行け<b>とばかりに</b>私たちをにらんだ。"},
"36701": {"point": "「〜とは」は「〜なんて」という意味で、意外なことへの驚きや感動を表す。あの小さかった太郎君がこんなに立派になるなんて、と驚く気持ちを表し、後の「本当にびっくりした」と合う。", "opts": ["では：「〜では」は「〜の場合は」と条件や範囲を表し、驚きの気持ちを表せない", "", "との：「〜との」は「〜という」の意で、後に「知らせ」「連絡」などの名詞が必要。後に「、」で文が続く形には合わない", "とも：「〜とも」は「たとえ〜ても」や「もちろん」の意で、驚きの気持ちを表せない"], "ex": "あんなに元気だった彼が入院する<b>とは</b>、思いもしなかった。"},
"36702": {"point": "「〜なり」は「〜するとすぐに」という意味で、辞書形に付き、前の動作の直後に思いがけない動作が起こる様子を表す。手紙を読むとすぐに彼女が泣き出したという文で、辞書形の「読む」に付く。", "opts": ["すぐ：「すぐ」は副詞で、「読むとすぐ」「読んですぐ」の形が必要。辞書形に直接付けて「読むすぐ」とは言えない", "", "が最後：「〜たが最後」はた形に付き、「一度〜したら、もう取り返しがつかない」の意。辞書形の「読む」には付かず、意味も合わない", "とたん：「〜たとたん」はた形に付くので「読んだとたん」となる。辞書形の「読む」には付かない"], "ex": "息子は部屋に入る<b>なり</b>、ベッドに倒れ込んだ。"},
"36703": {"point": "「〜にして」は「〜で（やっと）」という意味で、ある段階や時点に至ってようやく何かが実現することを表す。非常に難しい国家試験に、5回目の受験でやっと合格できたという文に合う。", "opts": ["ですら：「〜ですら」は「〜でさえ」と極端な例を表し、後に否定的な内容が続くことが多い。「やっと合格できた」と合わない", "として：「〜として」は「留学生として」のように立場や資格を表し、「5回目として」では意味が通らない", "", "にたいして：「〜にたいして」は「〜に向けて・〜と比べて」の意で、試験の回数を表す文に合わない"], "ex": "彼は四十歳<b>にして</b>、ようやく自分の進む道を見つけた。"},
"36704": {"point": "「〜ないものでもない」は「〜しないこともない・場合によっては〜する」という意味で、条件次第で可能性があることを控えめに表す。自分の非を認めて謝るなら、許してやってもよいという条件付きの気持ちに合う。", "opts": ["やるまでもない：「〜までもない」は「わざわざ〜する必要はない」の意。許す必要もないという意味になり、「謝るなら」という条件と合わない", "やるものでもない：「〜ものでもない」は「必ずしも〜ものではない」と一般論を否定する表現。「謝るなら許してもよい」という条件付きの気持ちは表せない", "やることではない：「〜ことではない」は「〜すべきことではない」という否定で、謝るなら許すという条件の文に合わない", ""], "ex": "条件次第では、その仕事を引き受け<b>ないものでもない</b>。"},
"36705": {"point": "「〜といえども」は「〜であっても」という意味の硬い表現で、前の内容から予想されることとは違う事実を後に述べる。科学が進んだ現代であっても、科学で解明できないことがまだたくさんあるという文に合う。", "opts": ["", "というと：「〜というと」は「〜と言えば（思い浮かぶのは）」と話題を出す表現で、逆接の意味がなく、後の内容とつながらない", "にとって：「〜にとって」は「〜の立場から見ると」の意で、「現代にとって」では逆接の関係を表せない", "にかけては：「〜にかけては」は「料理にかけては」のように「〜の分野では（優れている）」の意で、文意に合わない"], "ex": "子ども<b>といえども</b>、法律を破れば責任を問われる。"},
"36706": {"point": "「〜そばから」は「〜するとすぐに（また）」という意味で、同じことが何度も繰り返される不満を表す。パソコンの使い方を教わっても、教わるとすぐに忘れてしまうことが繰り返されるという文に合う。", "opts": ["あとでは：「〜あとで」はた形に付き「教わったあとで」となる。辞書形の「教わる」には付かず、すぐに忘れる意味も表せない", "", "よそには：「〜をよそに」は「〜を気にかけずに」の意で、「教わるよそには」という形はない", "ことまで：「〜ことまで」は「〜ということも」と範囲を広げる表現で、「教わることまで忘れてしまう」では繰り返しの意味にならない"], "ex": "部屋を片づける<b>そばから</b>、子どもたちが散らかしていく。"},
"36707": {"point": "「〜ないではおかない」は「必ず〜させる・自然に〜という状態を引き起こす」という意味。このすばらしい作品は、読む者の胸を必ず打つ、つまり必ず感動させるだろうという文に合う。", "opts": ["", "打たざるをえない：「〜ざるをえない」は「仕方なく〜しなければならない」の意で、事情によってやむを得ずする行為を表す。作品が読む人を感動させる意味にならない", "打ちようもない：「〜ようもない」は「〜する方法がない」の意で、胸を打つことはできないという否定になり、「すばらしい作品」と合わない", "打ってはならない：「〜てはならない」は禁止を表し、作品を高く評価する文に合わない"], "ex": "あの監督の新作は、観客を感動させ<b>ないではおかない</b>だろう。"},
"36708": {"point": "「〜始末だ」は「（悪い状態が続いて）ついに〜という悪い結果になる」という意味。練習が厳しすぎて、ついにはやめる新入生まで現れるという悪い結果に至った状況を表す文に合う。", "opts": ["次第：「〜次第だ」は「〜という事情だ」と経緯や理由を説明する改まった表現で、悪い結果に至ったことを表せない", "挙句：「〜たあげく」はた形に付き、「さんざん〜した結果」の意。辞書形の「現れる」には付かない", "", "一方：「〜一方だ」は「増える一方だ」のように、ある方向への変化が進み続けることを表し、悪い結果に至った意味にならない"], "ex": "彼は遅刻ばかりして、ついには無断で仕事を休む<b>始末だ</b>。"},
"36709": {"point": "「〜んがために」は「どうしても〜しようとして」という強い目的を表す硬い表現で、動詞のない形に付き、「する」は「せん」になる。会社を再建するという目的のために、合併の道を選んだという文に合う。", "opts": ["するがために：目的を表す「〜んがために」は動詞のない形に付く形で、「する」は「せん」となる。「するがために」ではこの文型にならない", "", "しようがために：意向形の「しよう」には「がために」は付かない。「する」の場合は「せんがために」となる", "されんがために：受身の「される」の形になり、「再建される」という意味になって、会社を再建しようとする主語の行動と合わない"], "ex": "夢をかなえ<b>んがために</b>、彼は毎日必死に努力している。"},
"36710": {"point": "「〜といったところだ」は「だいたい〜ぐらいだ」という意味で、程度や数量がそれほど高くないことを表す。レストランのアルバイトの時給は、だいたい900円から1000円ぐらいだろうという推測に合う。", "opts": ["", "としたところ：「〜としたところ」は「〜としたら（その結果）」の意で、時給のだいたいの範囲を表せない", "というわけ：「〜というわけだ」は「〜という結論・理由だ」と説明する表現で、だいたいの程度を表す意味にならない", "ときたところ：「ときたところ」という形はなく、「だいたい〜ぐらいだ」の意味を表せない"], "ex": "家から会社までは、電車で30分<b>といったところ</b>です。"},
"36711": {"point": "「〜ばそれまでだ」は「〜したら、もう終わりだ・それまでの努力は意味がない」という意味。膨大な資金をかけて開発した新薬でも、副作用があれば意味がなくなるという文に合う。", "opts": ["からだ：「それからだ」は「次の段階はそれからだ」の意で、副作用があればすべて無駄になるという内容を表せない", "のみだ：「それのみだ」は「それだけだ」と限定を表し、すべて無駄になるという意味にならない", "ほどだ：「それほどだ」は程度を表し、「副作用があれば」に続けても意味が通らない", ""], "ex": "いくらいい計画を立てても、実行しなけれ<b>ばそれまでだ</b>。"},
"36712": {"point": "「〜にたえない」は「ひどくて〜できない・〜するのが我慢できない」という意味で、「見る」「聞く」などの動詞に付く。新入生の演奏が間違いばかりで、聞いていられないほどひどかったという文に合う。", "opts": ["にすぎない：「〜にすぎない」は「ただ〜だけだ」の意で、「聞くにすぎないもの」では演奏のひどさを表せない", "", "にかたくない：「〜にかたくない」は「想像にかたくない」のように「簡単に〜できる」の意で、「聞く」には普通付かず、意味も合わない", "にかぎらない：「〜にかぎらない」は「〜だけに限らない」と範囲を表し、演奏のひどさを表せない"], "ex": "その番組は内容がひどく、とても見る<b>にたえない</b>。"},
"36713": {"point": "「AといいBといい」は「AもBも」という意味で、いくつかの例を挙げて、どの点から見ても同じ評価になることを表す。決断力も誠実さも、どの点から見てもリーダーにふさわしいという評価の文に合う。", "opts": ["だの / だの：「AだのBだの」は「〜とか〜とか」と例を挙げる話し言葉で、不満や否定的な内容に使うことが多い。人をほめる評価の文に合わない", "ならず / ならず：「ならず」を二つ並べる形はない。「〜のみならず」の形で「〜だけでなく」の意になる", "", "とあれば / とあれば：「〜とあれば」は「〜という理由なら」の意で、二つ並べて評価の例を挙げる使い方はない"], "ex": "この店は、味<b>といい</b>値段<b>といい</b>、申し分ない。"},
"36714": {"point": "「たとえ〜であれ」は「たとえ〜であっても」という意味で、どんな場合でも結果は変わらないことを表す。たとえ子供であっても、悪いことをすれば相応の処罰を受けるべきだという文に合う。", "opts": ["とあれば：「〜とあれば」は「〜という理由なら」の意で、逆接の「たとえ」とは結びつかない", "といい：「〜といい」は「AといいBといい」と例を二つ並べて評価する形で、「たとえ」とは結びつかない", "とあいまって：「〜とあいまって」は「〜と一緒になって（効果が高まる）」の意で、逆接の「たとえ」と合わない", ""], "ex": "たとえ冗談<b>であれ</b>、人を傷つけるようなことを言ってはいけない。"},
"36715": {"point": "「〜てやまない」は「心から〜している・ずっと〜し続けている」という意味で、強い気持ちが続くことを表す。休まずに練習に打ち込めるのは、みんなが心から勝利を信じているからだという文に合う。", "opts": ["たまらない：「〜てたまらない」は「うれしくてたまらない」のように感情や感覚が抑えられないことを表し、「信じる」には付かない", "", "すまない：「〜てすまない」は「待たせてすまない」のように謝る表現で、意味が合わない", "たえない：「〜にたえない」は「感謝にたえない」のように名詞に付き、「信じて」に続く形はない"], "ex": "私は、子どもたちの幸せを願っ<b>てやまない</b>。"},
"36716": {"point": "「AとBとがあいまって」は「AとBが一緒になって（よりよい効果を生む）」という意味。映像の美しさと主演俳優の演技力が一緒になって、すばらしい作品になっているという文に合う。", "opts": ["", "ひきかえ：「〜にひきかえ」は「〜とは反対に」と二つを対比する表現で、「に」が必要。二つが一緒に効果を生む意味にならない", "おもいきや：「〜と思いきや」は「〜と思ったが、意外にも」の意で、「とが」には続かず、意味も合わない", "かかわらず：「〜にかかわらず」は「〜に関係なく」の意で、「に」が必要。意味も合わない"], "ex": "豊かな自然と温かい人柄とが<b>あいまって</b>、この町は多くの観光客を引きつけている。"},
"36717": {"point": "「〜やいなや」は「〜するとすぐに」という意味で、辞書形に付き、前のことの直後に後のことが起こる様子を表す。映画が公開されるとすぐに爆発的な人気が出たという文で、辞書形の「公開される」に付く。", "opts": ["とたん：「〜たとたん」はた形に付くので「公開されたとたん」となる。辞書形の「公開される」には付かない", "しだい：「〜しだい」はます形に付き「公開され次第」となる。また「〜したらすぐに（…する）」とこれからの予定を表し、過去の出来事には使わない", "", "そばから：「〜そばから」は「〜してもすぐにまた」と同じことの繰り返しを表し、一度きりの公開と人気には合わない"], "ex": "新しいゲームが発売される<b>やいなや</b>、店の前に長い行列ができた。"},
"36718": {"point": "「〜にはあたらない」は「〜する必要はない・〜するほどのことではない」という意味。不況で先の見通しが難しい今、会社の経営方針が頻繁に変わっても驚く必要はないという文に合う。", "opts": ["わけがない：「〜わけがない」は「〜する可能性はまったくない」と強く否定する表現で、「驚く必要はない」という評価を表せない", "にほかならない：「〜にほかならない」は「まさに〜だ」と断定する表現で、名詞などに付く。「驚くにほかならない」では意味が通らない", "にかたくない：「〜にかたくない」は「想像にかたくない」のように「簡単に〜できる」の意で、「驚く」には付かない", ""], "ex": "彼の実力なら、優勝したのも驚く<b>にはあたらない</b>。"},
"36719": {"point": "「〜を禁じえない」は「〜という気持ちを抑えられない」という意味で、「同情」「怒り」「涙」などの感情を表す名詞に付く。不幸が続いた鈴木さんの家族に、同情の気持ちを抑えられないという文に合う。", "opts": ["禁じかねない：「〜かねない」は「〜するおそれがある」の意で、同情を禁じるおそれがあるという意味になり、文意に合わない", "", "禁じざるをえない：「〜ざるをえない」は「〜するしかない」の意で、同情を禁止しなければならないという逆の意味になる", "禁じないではすまない：「〜ないではすまない」は「〜しなければ済まない」の意で、同情を禁じなければならないという逆の意味になる"], "ex": "被害者の話を聞いて、怒りを<b>禁じえない</b>。"},
"36720": {"point": "「〜ずくめ」は「〜ばかり」という意味で、身の回りが同じようなものや出来事でいっぱいであることを表す。散歩もサイクリングも露天風呂も楽しめる、楽しいことばかりの場所だという文に合う。", "opts": ["きわまりない：「〜きわまりない」は「失礼きわまりない」のように、ある状態がこの上ないことを表し、主に否定的な評価に使う。楽しいことが数多くそろっている様子は表せない", "とはかぎらない：「〜とはかぎらない」は「必ずしも〜ではない」の意で、楽しいことを並べた後の「まさに」と矛盾する", "", "にあたらない：「〜にはあたらない」は「〜する必要はない」の意で、楽しいことを並べた文の結論に合わない"], "ex": "今年は昇進に結婚と、いいこと<b>ずくめ</b>の一年だった。"},
"36231": {"point": "「〜たるもの」は「〜という立場にある者は」という意味で、後に「〜べきだ」「〜なければならない」など、その立場にふさわしいあり方が続く。刑事という立場にある者は、即座に判断して行動できなければならないという文に合う。", "opts": ["あるもの：「刑事あるもの」という形はない。「〜という立場にある者は」の意味を表す決まった形は「たるもの」である", "なるもの：「〜なるもの」は「愛なるもの」のように「〜というもの」の意の書き言葉で、立場にある者の心構えを表せない", "", "さるもの：「さるもの」は「敵もさるもの」のように「なかなか手ごわい者」の意の慣用表現で、文意に合わない"], "ex": "医者<b>たるもの</b>、患者の命を第一に考えるべきだ。"},
"36232": {"point": "「〜たりとも〜ない」は「一滴」「一円」など最小の数量に付き、「少しの〜も〜ない」と強く否定する。給水制限が続いているので、水は一滴も無駄にできないという文に合う。", "opts": ["", "どころか：「〜どころか」は「〜はもちろん・〜とは反対に」の意で、後に対比する内容が必要。「一滴どころか」では意味が通らない", "のみか：「〜のみか」は「〜だけでなく」と後に付け加える表現で、最小の量を強調して否定する意味にならない", "までも：「〜までも」は「子どもまでも知っている」のように範囲が意外なところまで及ぶことを表し、最小の数量に付いて強く否定する形にならない"], "ex": "決勝戦では、一点<b>たりとも</b>相手に与えるわけにはいかない。"},
"36233": {"point": "「〜でなくてなんだろう」は「これが〜でなければ何だろうか、まさに〜だ」という意味で、強く断定する表現。つねに人々のためを考える島村氏の態度こそ、まさに指導者の姿勢だと強く評価する文に合う。", "opts": ["にあるまじきことだろう：「〜にあるまじき」は「教師にあるまじき行為」のように「〜としてあってはならない」の意。島村氏を評価する文と逆の意味になる", "だといったところだ：「〜といったところだ」は「だいたい〜ぐらいだ」と程度が高くないことを表し、強く評価する文に合わない", "", "だといったらありはしない：「〜といったらありはしない」は「暑いといったらありはしない」のように感情や程度のはなはだしさを表し、名詞「姿勢」を評価する文に合わない"], "ex": "自分の命をかけて他人を救う、これが勇気<b>でなくてなんだろう</b>。"},
"36234": {"point": "「〜てはかなわない」は「〜では我慢できない・困る」という意味で、不快な状態への不満を表す。本を読み進めようと思ったが、こんなに眠くては我慢できない、とても読めないという文に合う。", "opts": ["かまわない：「〜てはかまわない」という形は使わない。「〜てもかまわない」は「〜してもよい」という許可の意で、意味も合わない", "", "かなうだろう：「かなう」は「願いがかなう」の意で、「眠くてはかなうだろう」では意味が通らない", "かまうだろう：「かまう」は「気にする」の意で、「眠くてはかまうだろう」では意味が通らない"], "ex": "毎日こう暑く<b>てはかなわない</b>。"},
"36235": {"point": "「〜ところを」は「〜している時なのに」という意味で、相手の都合を思いやり、恐縮する気持ちを表す。相手が忙しい時に頼みごとをすることを恐縮しながら、よろしくとお願いする文に合う。", "opts": ["に際して：「〜に際して」は名詞や辞書形に付き、「〜するときに」の意。形容詞の「お忙しい」には付かない", "", "ところで：「〜ところで」は「〜したところで（〜しても無駄だ）」の意や話題を変える意で、恐縮する気持ちを表せない", "にあたって：「〜にあたって」は「開店にあたって」のように名詞や辞書形に付き、「〜する時に」の意。形容詞には付かない"], "ex": "お疲れの<b>ところを</b>、わざわざお越しいただき恐縮です。"},
"36236": {"point": "「〜とばかりに」は「今にも〜と言いそうな様子で」という意味で、言葉にはしないが態度がそれを表していることを示す。店員が「早く帰れ」と言いそうな様子で、お皿を片づけ始めたという文に合う。", "opts": ["ばかりか：「〜ばかりか」は「〜だけでなく」と後に付け加える表現で、「帰れとばかりか」では意味が通らない", "", "ばかりも：「ばかりも」という形はなく、態度から気持ちが伝わる様子を表せない", "ばかりで：「〜ばかりで」は「〜だけで」の意で、態度から気持ちが伝わる様子を表せない"], "ex": "彼女は、もう話したくない<b>とばかりに</b>背を向けた。"},
"36237": {"point": "「〜ともなく」は「特にそのつもりもなく」という意味で、「見る」「聞く」などの動詞に付き、意識せずに何かをする様子を表す。電車でとなりの女子高生たちの話を、聞くつもりもなく聞いていたという文に合う。", "opts": ["聞かないまでも：「〜ないまでも」は「〜ほどではないが」の意で、後に「せめて〜」などが続く。「話を聞いていた」とは結びつかない", "聞くこともせずに：「聞かないで」という意味になり、「話を聞いていた」と矛盾する", "", "聞かないながらも：「〜ながらも」は逆接だが、「聞かないながらも聞いていた」では意味が矛盾する"], "ex": "窓の外を見る<b>ともなく</b>見ていたら、昔の友人が通りかかった。"},
"36238": {"point": "「〜なりの」は「〜にふさわしい・〜の立場や能力に応じた」という意味で、後の名詞を修飾する。十分ではないかもしれないが、自分の立場で考えた自分なりの考えを述べるという、謙虚な文に合う。", "opts": ["しだいの：「〜しだい」は「〜によって決まる」の意で、「わたししだいの考え」では意味が通らない", "いかんの：「〜いかん」は「〜のいかんによって」の形で「〜によって」の意。「わたしいかんの」という形は使わない", "がちの：「〜がち」は「病気がち」のように好ましくない傾向を表し、「わたしがちの」という形はない", ""], "ex": "若い人には若い人<b>なりの</b>考え方がある。"},
"36239": {"point": "「〜は言うにおよばず」は「〜はもちろん（言う必要もないほど当然で）」という意味で、後に「〜も」と範囲を広げる内容が続く。テレビはもちろん、ビデオカメラやパソコンもよく売れたという文になる。", "opts": ["までもなく：「言うまでもなく」なら「もちろん」の意になるが、「言うに」の「に」の後には付かない", "", "よらず：「〜によらず」は「〜に関係なく」（年齢によらず）の意。「言うによらず」という表現はない", "のみか：「〜のみか」は「〜だけでなく」の意で、「テレビのみか」のように名詞に付く。「言うにのみか」という形はない"], "ex": "地元の人は<b>言うにおよばず</b>、海外からも多くの観光客が訪れる。"},
"36240": {"point": "「〜にあって」は「〜という特別な状況・立場で」という意味の硬い表現。「不況下にあって」で「不況という厳しい状況の中で」となり、仕事探しが難しい背景を表す。", "opts": ["あっての：「AあってのB」は「Aがあってこそ成り立つB」（お客様あっての商売）の意。不況があってこそ成り立つという意味は文に合わない", "", "にたる：「〜にたる」は「〜する価値がある」（信頼するにたる人物）の意で、動詞の辞書形に付く。「不況下にたる」とは言わない", "ならではの：「〜ならではの」は「〜だけが持つ特別な」（京都ならではの風景）の意で、後に名詞が必要。意味も合わない"], "ex": "戦時下<b>にあって</b>、人々は互いに助け合って暮らしていた。"},
"36241": {"point": "「〜ともなく」は「読むともなく読む」のように同じ動詞を繰り返し、「特にそのつもりもなく、何となく〜する」という意味を表す。何となく新聞を読んでいたら、偶然友人の記事を見つけたという状況に合う。", "opts": ["", "ことなしに：「〜ことなしに」は「〜しないで」（努力することなしに成功はない）の意。「読むことなしに読む」では矛盾する", "そばから：「〜そばから」は「〜してもすぐに」（覚えるそばから忘れる）の意で、繰り返しを嘆く表現。「読むそばから読む」では意味をなさない", "ばかりに：「〜ばかりに」は「〜したせいで（悪い結果になった）」（一言多かったばかりに）の意。原因と悪い結果の関係はなく、合わない"], "ex": "窓の外を見る<b>ともなく</b>見ていたら、虹が出ているのに気づいた。"},
"36242": {"point": "「〜なりに」は「〜にふさわしく、その人の立場や能力の範囲で」という意味。「彼なりに」で「彼は彼のやり方で」となり、成功の理由として、彼が自分なりに創意と工夫を重ねてきたことを表す。", "opts": ["", "にもまして：「〜にもまして」は「〜以上に」（以前にもまして）の意で、他と比べる表現。「彼にもまして」では比べる相手が彼自身になり、文意が通らない", "に反して：「〜に反して」は「〜とは反対に」（予想に反して）の意で、予想・期待・規則などに付く。「彼に反して」では意味が通らない", "にひきかえ：「〜にひきかえ」は「〜とは対照的に」（兄にひきかえ弟は）の意で、二つのものを比べる表現。彼自身の努力を述べる文に合わない"], "ex": "子どもは子ども<b>なりに</b>、家族のことを心配しているのだ。"},
"36243": {"point": "「〜とばかりに」は「いかにも〜と言わんばかりの様子で」という意味。「待っていたとばかりに」で、ずっと待っていたという態度をはっきり見せて、すぐにおみやげをねだった子供の様子を表す。", "opts": ["", "とあって：「〜とあって」は「〜という特別な事情なので」（連休とあって混雑している）の意で、客観的な理由を述べる表現。様子を表すこの文に合わない", "としても：「〜としても」は「仮に〜でも」という逆接の仮定。待ちかねていた様子を表せない", "かと思うと：「〜かと思うと」は「〜したらすぐに（別のことが起こる）」（泣いたかと思うと笑い出した）の意。いかにもという様子は表せない"], "ex": "彼は「もう話すことはない」<b>とばかりに</b>席を立った。"},
"36244": {"point": "「〜たるもの」は「〜という立場にある者は」という意味で、名詞に付き、後に「〜べきだ・〜なければならない」などその立場にふさわしい行動が続く。運転手という立場の者は、客の安全に注意すべきだという文になる。", "opts": ["こととて：「〜こととて」は「〜なので（許してほしい）」（慣れぬこととて）の意。名詞に直接は付かず、義務を述べる文にも合わない", "ものなら：「〜ものなら」は「もし〜できるなら」（できるものなら）の意で、動詞の可能形などに付く。名詞には付かない", "ならでは：「〜ならでは」は「〜だけが持つ特別な」（プロならではの技）の意で、後に「の＋名詞」などが続く。義務を述べる文に合わない", ""], "ex": "教師<b>たるもの</b>、生徒の手本とならなければならない。"},
"36245": {"point": "「〜たりとも〜ない」は「一瞬」「一日」「一円」など最小の数量に付いて、「少しの〜も〜ない」と全面的に否定する。「一瞬たりとも油断ができない」で、多くの命を預かる運転士の緊張感を強く表す。", "opts": ["ならでは：「〜ならでは」は「〜だけが持つ特別な」の意で、最小の数量に付いて否定を強める働きはない", "ばかりか：「〜ばかりか」は「〜だけでなく（さらに）」の意で、後に付け加える内容が必要。否定を強める働きはない", "", "だけは：「一瞬だけは」では「その一瞬に限って」という意味になり、運転中ずっと油断できないという文意と合わない"], "ex": "試験まであと一週間。一日<b>たりとも</b>無駄にはできない。"},
"36246": {"point": "「〜てはかなわない」は「〜では我慢できない、困る」という意味で、不快な状態への不満を表す。冬が好きだと言いながらも、「そうは言っても」と逆接で続け、毎日これほど寒いのは我慢できないという気持ちを述べている。", "opts": ["かまわない：「〜てもかまわない」の形で「〜でも問題ない」と許容を表す。「寒くてはかまわない」とは言わず、寒さへの不満とも合わない", "", "きりがない：「きりがない」は「終わりがない」（数え上げたらきりがない）の意で、際限なく続く行為に使う。寒さへの不満を表せない", "さしつかえない：「〜てもさしつかえない（〜しても問題ない）」の形で許可を表す。「寒くては」とつながらず、不満の文脈とも合わない"], "ex": "毎晩隣の部屋がこううるさく<b>てはかなわない</b>。"},
"36247": {"point": "「〜でなくてなんだろう」は「これが〜でなければ何だというのか」という反語で、「まさに〜だ」と強く断定する。汚職事件は有権者への裏切り行為そのものだという、話し手の強い非難を表す。", "opts": ["にすぎない：「〜にすぎない」は「ただ〜だけだ」と程度が小さいことを表す。裏切りを軽く扱うことになり、強い非難の文脈に合わない", "にかぎったことではない：「〜にかぎったことではない」は「〜だけの問題ではない」（この町にかぎったことではない）の意。この文では意味が通らない", "", "を禁じえない：「〜を禁じえない」は「（感情を）抑えられない」（同情を禁じえない）の意で、感情を表す名詞に付く。「裏切り行為」には付かない"], "ex": "命がけで子どもを守った母親の行動は、愛<b>でなくてなんだろう</b>。"},
"36248": {"point": "「〜は言うに及ばず」は「〜はもちろん」という意味で、当然のものを先に挙げ、後に「〜も」で範囲を広げる。遺族はもちろん、参列者の大半も山田氏の言葉に涙を流したという文になる。", "opts": ["言わないまでも：「〜ないまでも」は「〜ほどではないが」（全員とは言わないまでも）の意。「遺族は言わないまでも」では意味が通らない", "", "言わんがため：「〜んがため」は「〜しようという目的で」の意。「言わんがため」では目的を表すことになり、文意に合わない", "言わないことではなく：このような形の表現はなく、「〜はもちろん」という意味も表せない"], "ex": "この店は週末は<b>言うに及ばず</b>、平日も行列ができるほどの人気だ。"},
"36249": {"point": "「〜ところを」は「〜という状況なのに」という意味で、相手に負担をかけたことへの恐縮や感謝を表す。「遠いところを」で「遠くて大変なのに」となり、「おいでくださいまして」というお礼につながる。", "opts": ["が：「遠いところが」では「遠いところ」が主語になり、後の「おいでくださいまして」とつながらない", "で：「遠いところで」では場所を表すことになり、相手に負担をかけたことへの恐縮を表せない", "に：「遠いところに」では行き先を表すことになり、遠方から来てくれた相手への恐縮を表せない", ""], "ex": "お忙しい<b>ところを</b>お時間をいただき、ありがとうございます。"},
"36250": {"point": "「〜にあっても」は「〜という状況においても」という意味で、「どのような〜にあっても」で「どんな〜でも」と逆接の仮定を表す。どれほど困難な状況でも、解決策は必ずあるという確信を述べている。", "opts": ["", "つけても：「〜につけても」は「〜するたびに」（見るにつけても）の意で、「状況につけても」とは言わない", "とっても：「〜にとっても」は「〜の立場から見ても」（私にとっても）の意で、人や組織に付く。「状況にとっても」では意味が合わない", "かけても：「〜にかけても」は「名誉にかけても」のように誓いや決意を表す形で、状況を表す文に合わない"], "ex": "どんな逆境<b>にあっても</b>、彼は笑顔を忘れなかった。"},
"36251": {"point": "「〜べからず」は動詞の辞書形に付いて「〜してはいけない」という禁止を表す硬い書き言葉で、立て札や掲示によく使われる。工事中のため立ち入りを禁止する掲示文に合う。", "opts": ["べき：「べき」は「守るべき約束」のように後に名詞が続く形で、文を終えられない。意味も禁止ではない", "べきだ：「〜べきだ」は「〜するのが当然だ」の意で、「立ち入るべきだ」では入ることを勧めることになり、工事中の掲示と矛盾する", "べし：「〜べし」は「〜しなければならない」という義務・命令の書き言葉で、「立ち入るべし」では入れと命じることになる", ""], "ex": "「芝生に入る<b>べからず</b>」という立て札が立っている。"},
"36252": {"point": "「〜べからざる」は「〜べからず」の連体形で、名詞の前に置いて「〜してはならない」という意味を表す。「許すべからざる行為」で「決して許してはならない行為」となり、テロを強く非難する文に合う。", "opts": ["許すべし：「べし」は義務・命令を表す終止形で、名詞の前には置けない。また「許すべし」では許せという意味になる", "許すべき：「許すべき行為」は「許すのが当然の行為」という意味になり、「人道と正義に反する」と矛盾する", "許すべからず：「べからず」は文末に使う終止形で、後に名詞「行為」を続けられない", ""], "ex": "表現の自由は、だれも侵す<b>べからざる</b>権利である。"},
"36253": {"point": "「〜を余儀なくされる」は「（外部の事情によって）仕方なく〜することになる」という意味。主語は「計画は」で、賃貸料の値上がりという事情によって中止せざるを得なくなったので、受け身の「余儀なくされた」が合う。", "opts": ["余儀なくさせた：「〜を余儀なくさせる」は原因の側を主語にして「仕方なく〜させる」の意。主語が「計画は」なので合わない", "", "余儀なくなった：「〜を余儀なくなる」という言い方はしない。「を」を受けるのは「余儀なくされる／させる」の形", "余儀なくしてもらった：「〜てもらう」は恩恵を受ける意味で、望まない中止を表す文と合わない。このような言い方もしない"], "ex": "大雪のため、選手たちは試合の延期を<b>余儀なくされた</b>。"},
"36254": {"point": "「〜までのことだ」は動詞の辞書形に付いて「（だめなら）〜すればいいだけだ」という意味で、ほかの方法がなくても、それをすればいいと割り切る態度を表す。「やるだけはやってみよう」という前向きな気持ちにつながる。", "opts": ["", "ゆえだ：「〜ゆえだ」は「〜が理由だ」という書き言葉。「やり直すゆえだ」では理由の説明になり、文意が通らない", "かぎりだ：「〜かぎりだ」は「うれしいかぎりだ」のように感情を表す形容詞に付いて「とても〜だ」の意を表す。動詞「やり直す」には付かない", "しまつだ：「〜しまつだ」は「悪い経過の末に、とうとう〜という結果になった」（借金までするしまつだ）の意で、前向きな決意に合わない"], "ex": "終電に乗り遅れたら、タクシーで帰る<b>までのことだ</b>。"},
"36255": {"point": "「〜（よ）うと〜まいと」は同じ動詞の意向形と「まい」を並べて、「〜しても、しなくても（関係なく）」という意味を表す。「売れようと売れまいと」で、小説が売れても売れなくても著者は気にしないという文になる。", "opts": ["ないと：「売れないと」では条件の意味になり、意向形「売れようと」と対にならない", "ないか：「〜か〜ないか」は「売れるか売れないか」の形で使い、意向形「売れようと」とは組み合わせない", "まいか：「〜（よ）うか〜まいか」は「行こうか行くまいか迷う」のように迷いを表す形。前半が「売れようと」なので対にならない", ""], "ex": "雨が<b>降ろうと降るまいと</b>、試合は予定どおり行われる。"},
"36256": {"point": "「〜をものともせず」は「困難や障害を問題にしないで、負けずに」という意味。「過酷な経営環境をものともせず」で、厳しい環境に負けずに善戦している会社の様子を表す。", "opts": ["ものとして：「〜ものとして」は「〜とみなして」（出席するものとして準備する）の意で、普通形に付く。「を」の後には付かない", "ものならず：このような表現はなく、意味をなさない。困難に負けないという意味も表せない", "", "ものだから：「〜ものだから」は「〜ので」と理由や言い訳を表し、普通形に付く。「を」の後には付かない"], "ex": "彼女はけがを<b>ものともせず</b>、最後まで走り抜いた。"},
"36257": {"point": "「〜（よ）うと」は「たとえ〜しても」という逆接の仮定で、後に話し手の意志や判断が続く。「両親に」とあり、話し手は反対される側なので受け身の意向形「されよう」が入り、たとえ両親に反対されても家を出るという決意を表す。", "opts": ["させる：「反対させると」は使役＋条件の「と」になり、「たとえ〜ても」という逆接の意味にならない", "", "しよう：「反対しようと」では反対するのが話し手になり、「両親に」とつながらず文意に合わない", "する：「反対すると」では「私が両親に反対したら」という条件になり、「たとえ反対されても」という意味にならない"], "ex": "だれに笑われ<b>ようと</b>、私は自分の夢をあきらめない。"},
"36258": {"point": "「〜をかわきりに」は「〜を始めとして、それをきっかけに次々と」という意味。コンサートツアーが東京から始まり、続いて全国の主要都市を回るという流れを表す。", "opts": ["はじまりに：「〜をはじまりに」という言い方はしない。始まりを表すには「〜を始めとして」などの形を使う", "", "あいついで：「あいついで」は「次々に続いて」という副詞で、「東京をあいついで」のように「を」を受ける形にはならない", "さいごに：「〜を最後に」は「〜を最後として（それ以降はない）」（この試合を最後に引退する）の意。ツアーの出発点を述べる文に合わない"], "ex": "この会社は新宿店を<b>かわきりに</b>、都内に次々と店舗を広げた。"},
"36259": {"point": "「〜をもって」は「〜で」という方法・手段を表す硬い表現。「賞品の発送をもって発表に替えさせていただきます」で、当選者の発表を賞品の発送で代えるという、懸賞などでよく使われる言い方になる。", "opts": ["", "なりに：「〜なりに」は「〜にふさわしく、それなりに」（子供なりに）の意で、方法・手段は表さない", "にとって：「〜にとって」は「〜の立場から見て」（私にとって）の意で、人や組織に付く。方法・手段は表さない", "にひきかえ：「〜にひきかえ」は「〜とは対照的に」の意で、二つのものを比べる表現。この文に合わない"], "ex": "合否の結果は、書面<b>をもって</b>お知らせいたします。"},
"36260": {"point": "「〜としてあるまじき」は「〜として、あってはならない」という意味で、後に名詞が続き、その立場の人の行為を強く非難する。依頼人のプライバシーを漏らすのは、弁護士としてあってはならないことだという文になる。", "opts": ["あるまい：「あるまい」は「ないだろう」という否定の推量で、普通は文末に使う。後に名詞「こと」を続けて非難を表すことはできない", "", "あるらしい：推量・伝聞を表し、「弁護士としてあるらしいこと」では意味が通らない。強い非難も表せない", "あるべき：「〜としてあるべき」は「〜として当然そうあるはずの」（教師としてあるべき姿）の意で、非難の文意と正反対になる"], "ex": "患者の秘密を他人に話すなんて、医者として<b>あるまじき</b>行為だ。"},
"36261": {"point": "「〜（よ）うと〜まいと」は「〜しても、しなくても」という意味で、する・しないにかかわらず結果は同じだということを表す。「やめようとやめまいと」で、彼が会社をやめてもやめなくても私には関係ないという文になる。", "opts": ["", "やめない：「やめようとやめないと」とは言わない。意向形「やめよう」と対になるのは「まい」の形の「やめまい」", "やめるつもり：「やめるつもりと」では「やめようと」と対にならず、文が成り立たない", "やめたい：「やめたいと」では希望を表すことになり、「やめようと」と対にならない"], "ex": "君が<b>行こうと行くまいと</b>、私は一人で行く。"},
"36262": {"point": "「どんなに〜（よ）うが」は「どんなに〜しても」という逆接の仮定で、後に「変わらない」など結果が変わらないことが続く。本は批判される側なので受け身の意向形「されようが」が入り、どれほど批判されても価値は変わらないという文になる。", "opts": ["", "されると思うと：「〜と思うと」は「〜と考えると（気持ちが〜）」の意で、「どんなに」と呼応せず、逆接の意味も表せない", "されると：「〜と」は条件を表し、「どんなに」と組み合わせて「たとえ〜ても」という逆接の意味を表せない", "されながら：「〜ながら」は同時進行や「〜のに」（知っていながら）の意で、「どんなに」とは呼応しない"], "ex": "どんなに反対され<b>ようが</b>、私はこの計画を続けるつもりだ。"},
"36263": {"point": "「〜をもって」は日付や時間に付いて「〜で（区切りとして）」と期限や終わりを表す硬い表現。「30日をもって閉店いたします」で、30日で営業を終えることを丁寧に知らせている。", "opts": ["にもとづいて：「〜にもとづいて」は「〜を根拠・基準にして」（データにもとづいて）の意で、日付には付かない", "とあって：「〜とあって」は「〜という特別な事情なので」の意で、「30日とあって閉店する」では意味が通らない", "をして：「AをしてBさせる」は「AにBさせる」（彼をして言わしめた）という使役の書き言葉で、日付には使わない", ""], "ex": "本日<b>をもって</b>、受付を終了させていただきます。"},
"36264": {"point": "「〜べからず」は「〜してはいけない」という禁止を表す書き言葉で、看板や掲示によく使われる。「私有地につき（私有地なので）」という理由とともに、立ち入りを禁止する文になる。", "opts": ["入りほうだい：「〜ほうだい」は「好きなだけ〜する」（食べほうだい）の意で、私有地への立ち入りを禁じる看板の内容と反対になる", "", "入ること：「〜こと」は「廊下を走らないこと」のように指示を表すが、「入ること」では入るよう指示することになり、私有地の看板と合わない", "入らんか：「〜んか」は「〜ないか」の意の話し言葉で、勧誘などを表す。禁止を示す看板の文に合わない"], "ex": "「危険につき、ここで泳ぐ<b>べからず</b>」と書かれた看板があった。"},
"36265": {"point": "「〜たまでだ」は「ただ〜しただけだ（それ以上の意図はない）」という意味。ここでは「〜したまでで」と文を続ける形になり、客観的なアドバイスをしただけで、判断は相手に任せるという文になる。", "opts": ["かわり：「〜かわり（に）」は代償や交換（手伝ってもらったかわりに）を表す。「アドバイスをしたかわりで」とは言わず、文意も合わない", "", "しまつ：「〜しまつだ」は悪い経過の末の結果を嘆く表現で、自分のアドバイスについて述べる文に合わない", "ほど：「〜ほど」は程度を表し、「アドバイスをしたほどで」では意味が通らない"], "ex": "私は事実を言った<b>まで</b>で、彼を責めるつもりはなかった。"},
"36266": {"point": "「〜にあるまじき」は「〜として、あってはならない」という意味で、後に「行為・発言」などの名詞が続く。生徒をなぐって怪我をさせるのは、教師としてあってはならない行為だと強く非難している。", "opts": ["あるまいし：「〜ではあるまいし」は「〜ではないのだから」（子供ではあるまいし）の意で、後に名詞は続かない", "あらんがための：「〜んがため」は「〜しようという目的で」の意。「教師にあらんがための行為」では意味が通らない", "", "あるべく：「〜べく」は「〜するために」という目的を表し、後に名詞は続かない"], "ex": "審判に暴言を吐くなど、スポーツ選手に<b>あるまじき</b>態度だ。"},
"36267": {"point": "「〜をものともせず」は「〜に負けないで、問題にしないで」という意味。「多くの困難をものともせず」で、困難に負けずに政治改革を進めた首相の姿勢を表す。", "opts": ["かわきりに：「〜をかわきりに」は「〜を始めとして」の意で、困難を始めとして改革を進めることになり、文意に合わない", "こめて：「〜をこめて」は「（気持ちなどを）入れて」（心をこめて）の意で、「困難をこめて」とは言わない", "", "おいて：「〜をおいて」は「〜以外に」（彼をおいて適任者はいない）の意で、後に否定が続く。この文に合わない"], "ex": "彼らは激しい嵐を<b>ものともせず</b>、山頂を目指して進んだ。"},
"36268": {"point": "「〜を余儀なくされる」は「（外部の事情で）仕方なく〜することになる」という意味。台風で飛行機が飛べなくなったという事情によって、旅行を中止せざるを得なくなったので、受け身の「余儀なくされた」が合う。", "opts": ["余儀ないまでだ：このような言い方はない。「余儀ない」は「〜を余儀なくされる／させる」の形で使う", "", "余儀なくさせた：「〜を余儀なくさせる」は原因の側を主語にして「仕方なく〜させる」の意。旅行を中止した人の立場で述べるこの文に合わない", "余儀なくなった：「〜を余儀なくなる」という言い方はしない"], "ex": "経営不振により、その工場は閉鎖を<b>余儀なくされた</b>。"},
"36269": {"point": "「欠くべからざる」は「欠くことのできない、どうしても必要な」という意味で、「べからず」の連体形「べからざる」が名詞「活動」を修飾する。環境にやさしい暮らしのために、リサイクルやゴミの減量は不可欠だという文になる。", "opts": ["欠くべく：「〜べく」は「〜するために」という目的を表し、後に名詞は続かない。「欠くために」という意味も文意に合わない", "欠くべき：「欠くべき活動」は「欠くのが当然の活動」という意味になり、文意と反対になる", "欠くべからず：「べからず」は文末に使う形で、後に名詞「活動」を続けられない", ""], "ex": "水は、人間が生きていくうえで<b>欠くべからざる</b>ものだ。"},
"36270": {"point": "「〜をかわきりに」は「〜を始めとして、それをきっかけに」という意味で、後に「次々と」など同類のことが続く様子が来る。最初の高層アパートの建設をきっかけに、次々と同様のアパートが建てられたという文になる。", "opts": ["かえりみず：「〜をかえりみず」は「〜を気にかけないで」（危険をかえりみず）の意で、危険や迷惑などに付く。建設が始まるきっかけを表せない", "前にして：「〜を前にして」は「〜を目の前にして」（試験を前にして）の意。すでに起きたことを起点に次々と続く流れは表せない", "", "禁じえず：「〜を禁じえず」は「（感情を）抑えられず」の意で、怒りや涙など感情を表す名詞に付く。この文に合わない"], "ex": "一人の選手の告白を<b>かわきりに</b>、同様の被害を訴える声が次々と上がった。"},
"36271": {"point": "「AはBに〜を余儀なくさせる」は「Aが原因となって、Bに仕方なく〜させる」という意味。主語が原因である「道路工事は」で、「住民たちに」とあるので、使役の「余儀なくさせた」が合う。", "opts": ["せずにはおかなかった：「〜ずにはおかない」は「必ず〜する」（罰せずにはおかない）の意。工事が生活をすることになり、「住民たちに」ともつながらない", "禁じえなかった：「〜を禁じえない」は「（怒り・涙などの感情を）抑えられない」の意で、感情を表す名詞に付く。「生活」には付かない", "極まりなかった：「〜極まりない」は「この上なく〜だ」（失礼極まりない）の意で、ナ形容詞などに付く。「生活を極まりなかった」とは言わない", ""], "ex": "急激な円高は、多くの企業に方針の転換を<b>余儀なくさせた</b>。"},
"36272": {"point": "「〜まじき」は動詞の辞書形に付いて（「する」は「すまじき」の形にもなる）、「〜してはならない」という意味で名詞を修飾する。「社会人がすまじき行為」で、飲酒運転は社会人が決してしてはならない行為だという文になる。", "opts": ["するかぎりの：「〜かぎりの」は「できるかぎりの努力」のように「〜の範囲のすべての」の意で、「社会人がするかぎりの行為」では意味が通らない", "", "するような：「社会人がするような行為」では「社会人が普通にする行為」という意味になり、飲酒運転を非難する文意と合わない", "すべき：「すべき行為」は「するのが当然の行為」という意味になり、飲酒運転を非難する文意と反対になる"], "ex": "弱い者いじめは、断じて許す<b>まじき</b>行為だ。"},
"36273": {"point": "「〜べからざる」は「〜べからず」の連体形で、名詞の前に置いて「〜してはならない」という意味を表す。「言うべからざる発言」で、記者会見という公の場で言ってはならない発言をしたという文になる。", "opts": ["", "べし：「べし」は義務を表す終止形で、名詞の前には置けない。名詞の前では「べき」の形になる", "べきの：「べき」は直接名詞に付くので、「べきの発言」のように「の」は入らない。意味も「言うのが当然の発言」になり合わない", "べからず：「べからず」は文末に使う終止形で、後に名詞「発言」を続けられない"], "ex": "この事故は、私たちにとって忘れる<b>べからざる</b>教訓となった。"},
"36274": {"point": "「〜までだ」は動詞の辞書形に付いて「（ほかに方法がなければ）〜すればいいだけだ」という意味で、話し手の覚悟や割り切りを表す。だれも手伝ってくれないなら、自分でやればいいだけだという決意の文になる。", "opts": ["にはあたらない：「〜にはあたらない」は「〜するほどのことではない」（驚くにはあたらない）の意で、驚きや称賛などに使う。決意を表せない", "までもない：「〜までもない」は「〜する必要はない」（言うまでもない）の意で、自分でやる必要がないことになり、文意と反対になる", "", "にほかならない：「〜にほかならない」は「まさに〜だ」（努力の結果にほかならない）と断定的に説明する表現。決意を表す文に合わない"], "ex": "大学に落ちたら、もう一年勉強する<b>までだ</b>。"},
"36275": {"point": "「〜をものともせずに」は「〜に負けないで、問題にしないで」という意味。体の障害という困難に負けることなく、事業を成功させた彼の強さを表す。", "opts": ["おいて：「〜をおいて」は「〜以外に」（彼をおいて適任者はいない）の意で、後に否定などが続く。この文に合わない", "せんがため：「〜んがため」は「〜しようという目的で」の意で、動詞のない形に付く（勝たんがため）。「障害をせんがため」では意味が通らない", "", "わけもなく：「わけもなく」は「理由もなく」の意の副詞で、「障害を」の「を」を受けられない"], "ex": "祖父は高齢を<b>ものともせずに</b>、毎朝山に登っている。"},
"36276": {"point": "「何と〜（よ）うと」は「何と〜しても」という逆接の仮定で、後に「気にしない・変わらない」などが続く。人が私のことを何と言っても気にしないという、話し手の動じない態度を表す。", "opts": ["", "言うまいが：「〜まいが」は「〜（よ）うが〜まいが」と対で使うのが普通で、「何と」と呼応して「何と言っても」の意味を表すことはできない", "言おうものなら：「〜（よ）うものなら」は「もし〜したら（大変なことになる）」の意で、後に悪い結果が続く。「気にしない」と合わない", "言ったが最後：「〜たが最後」は「一度〜したら、必ず（悪い結果に）なる」の意。「何と」と呼応せず、「気にしない」とも合わない"], "ex": "人に<b>何と</b>思われ<b>ようと</b>、自分が正しいと思う道を進む。"},
"36277": {"point": "「〜べからず」は「〜してはいけない」という禁止を表す書き言葉で、注意書きや掲示に使われる。「1年間は絶対保存」とあるので、会議の議事録を捨ててはいけないという禁止の文になる。", "opts": ["", "捨てたまえ：「〜たまえ」は「〜しなさい」という、目上の男性が目下に使う命令で、「絶対保存」と矛盾する", "捨ててやまない：「〜てやまない」は「心から〜し続ける」（願ってやまない）の意で、気持ちを表す動詞に付く。「捨てる」には付かない", "捨てざるをえない：「〜ざるをえない」は「仕方なく〜しなければならない」の意で、「絶対保存」と矛盾する"], "ex": "「働かざる者、食う<b>べからず</b>」ということわざがある。"},
"36278": {"point": "「〜をかわきりに」は「〜を始めとして、それをきっかけに」という意味。秋の運動会が開会式から始まり、それに続いて各種目の競技が開始されたという流れを表す。", "opts": ["おいて：「〜をおいて」は「〜以外に（〜ない）」（彼をおいて適任者はいない）の意で、後に否定が必要。この文に合わない", "もって：「〜をもって」は「本日をもって終了する」のように時点を区切ったり手段を表したりする表現で、開会式を始めとして競技が続く流れは表せない", "かぎりに：「〜をかぎりに」は「〜を最後に」（今日をかぎりに禁煙する）の意で、物事の終わりを表す。競技が始まる流れと合わない", ""], "ex": "歌手デビューを<b>かわきりに</b>、彼女は女優やモデルとしても活躍するようになった。"},
"36279": {"point": "「〜をもって」は「〜で」という方法・手段を表す硬い表現で、規約などの公式な文書でよく使われる。会員への通知やその他の連絡は、電子メールという手段で行うという意味になる。", "opts": ["とあって：「〜とあって」は「〜という特別な事情なので」の意で、手段を表さない。「電子メールとあって」では意味が通らない", "", "にして：「〜にして」は「40歳にして初めて」「一瞬にして」のように時点や段階を表し、方法・手段は表さない", "を限りに：「〜を限りに」は「〜を最後に」（今日を限りに）の意で、時を表す語に付く。手段は表さない"], "ex": "本人確認は、運転免許証などの身分証明書<b>をもって</b>行います。"},
"36280": {"point": "「〜（よ）うが〜まいが」は同じ動詞の意向形と「まい」を並べて、「〜しても、しなくても（関係なく）」という意味を表す。「とるまいが」と対になるのは意向形の「とろう」で、賞をとってもとらなくても映画の力は変わらないという文になる。", "opts": ["", "とって：「とってが」という形はなく、「とるまいが」と対にならない", "とる：「とるがとるまいが」とは言わない。「〜まいが」と対になるのは意向形の「とろう」", "とれる：可能形「とれる」に「が」を付けても「とるまいが」と対にならず、文が成り立たない"], "ex": "人が<b>見ていようがいまいが</b>、ルールは守るべきだ。"},
"36281": {"point": "「〜ただろうに」は、事実と反対のことを仮定して「（もし〜なら）〜したのに、実際はそうならなかった」という残念な気持ちを表す。彼は協力を求めなかったので、何もしてあげられなかったことを残念に思う文になる。", "opts": ["", "はずなのか：疑問の形で、事実に反する仮定を受けて残念な気持ちを表すことができない", "まいか：「〜まいか」は「〜ではあるまいか」のような推量や「〜（よ）うか〜まいか」の迷いを表し、た形には付かない", "ものか：「〜ものか」は「行くものか」のような強い否定や「どうしたものか」のような迷いを表す。実現しなかったことへの残念な気持ちは表せない"], "ex": "もう少し早く家を出ていれば、電車に間に合った<b>だろうに</b>。"},
"36282": {"point": "「〜次第では」は名詞に付いて「〜によっては」という意味を表し、その内容によってはある結果もありうることを示す。社長の都合によっては、来週の会議が延期になる可能性があるという文になる。", "opts": ["からには：「〜からには」は「〜のだから当然」（約束したからには守る）の意で、動詞などの普通形に付く。名詞「ご都合」には付かない", "", "ほどで：「〜ほどで」は「一時間ほどで」のように数量のおおよその程度を表し、条件の意味にならない", "ばかりに：「〜ばかりに」は「〜したせいで（悪い結果に）」の意で、普通形に付く。名詞に直接は付かず、可能性を述べる文にも合わない"], "ex": "天候<b>次第では</b>、明日の試合は中止になるかもしれない。"},
"36283": {"point": "「〜だにしない」は「想像・予想」などの語に付いて「少しも〜しない」と強く否定する書き言葉。子どものころは、自分がオリンピックに参加できるとは少しも想像しなかったという文になる。", "opts": ["してみた：「だに」は後に否定を伴って「少しも〜ない」となるので、肯定の「してみた」とは結びつかない", "", "しないではいられなかった：「〜ないではいられない」は「どうしても〜してしまう」の意で、結果的に肯定の意味になる。「だに」の強い否定と合わない", "できたそうだ：伝聞の肯定文で、「だに」の否定と呼応しない。自分の子どものころの気持ちを述べる文にも合わない"], "ex": "十年前には、こんな便利な時代が来るとは夢想<b>だにしなかった</b>。"},
"36284": {"point": "「〜ずじまい」は「（しようと思っていたのに）結局〜しないで終わる」という意味で、残念な気持ちを表す。抗議するつもりだったのに、結局できないまま終わったという文になる。", "opts": ["出来まい：「〜まい」は「〜ないだろう」という否定の推量や意志を表し、後に「に終わった」を続けられない", "出来ほうだい：「〜ほうだい」は「好きなだけ〜する」（食べほうだい）の意で、「できなかった」という意味にならない", "", "出来っぱなし：「〜っぱなし」は「〜したまま（放っておく）」（開けっぱなし）の意で、「できなかった」という意味にならない"], "ex": "旅行先で買ったお土産を、友達に渡せ<b>ずじまい</b>になってしまった。"},
"36285": {"point": "「〜ないではすまない」は「（周りの状況や社会的な常識から）〜しないままでは済まされない、〜しなければならない」という意味。事業拡大に伴い、効率よく業務を進めるには会社を移転しなければならないという文になる。", "opts": ["して：「してはすまない」という形はなく、否定の「しないで」でなければ「しなければならない」という意味にならない", "", "せず：「せず」を使う場合は「せずにはすまない」と「に」が必要で、「せずはすまない」とは言わない", "する：辞書形に「はすまない」を続ける形はなく、文が成り立たない"], "ex": "人の物を壊したのだから、弁償し<b>ないではすまない</b>。"},
"36286": {"point": "「〜すら」は「〜さえ」と同じ意味で、極端な例を挙げて「それさえ〜ないのだから、ほかはなおさらだ」という気持ちを表す。最低限必要な給料を払う金さえないほど、資金繰りが厳しいことを強調している。", "opts": ["こそ：「〜こそ」はほかと区別して特に取り立てる表現で、「金こそない」では「（ほかのものはあるが）金はない」という意味になり、厳しさを強調できない", "でも：「でも」は「子どもでもわかる」のように極端な例を挙げるが、「金でもない」では「金というわけでもない」の意味になり、文意に合わない", "のみ：「のみ」は「〜だけ」の意で、「金のみない」では「金だけがない」という意味になり、文意に合わない", ""], "ex": "忙しくて、昼ごはんを食べる時間<b>すら</b>ない。"},
"36287": {"point": "「〜ことだし」は「〜ので」という理由を表す話し言葉で、いくつかある理由の一つを軽く挙げ、後に「〜よう・〜ましょう」などの意志や勧誘が続く。シャワーも浴びたので、そろそろ寝ようという文になる。", "opts": ["", "ものの：「〜ものの」は「〜けれども」という逆接（買ったものの、使っていない）。シャワーを浴びたことと寝ることは逆接の関係にない", "ものとして：「〜ものとして」は「〜とみなして」（了承したものとして進める）の意で、理由を表さない", "ことに：「〜ことに」は「驚いたことに」「残念なことに」のように感情を表す語に付いて話し手の気持ちを表す。理由は表さない"], "ex": "雨もやんだ<b>ことだし</b>、散歩にでも出かけようか。"},
"36288": {"point": "「〜からなる」は「〜で構成されている」という意味で、全体を作っている要素や人数を示して後の名詞を修飾する。「100人からなる学生たち」で、100人で構成された学生の一団が、毎年語学研修に出かけることを表す。", "opts": ["からいる：数量の多さを強調する言い方は「〜からある」「〜からの」が普通で、「からいる」は一般的ではない。「〜で構成された」という意味も表せない", "までする：「100人までする」という言い方はなく、構成の意味も表せない", "", "まである：「〜まである」は範囲の上限を表し、「〜で構成された」という意味にならない。「100人まである学生たち」とは言わない"], "ex": "日本の国会は、衆議院と参議院<b>からなる</b>。"},
"36289": {"point": "「〜だけましだ」は「（悪い状況の中でも）〜だけでも、まだいい」という意味。昇給は望めないほどの不況だが、会社が倒産しないだけでもまだいいと、悪い状況の中のよい点を挙げる文になる。", "opts": ["", "しかない：「〜しかない」は「〜するほかに方法がない」（待つしかない）の意で、動詞の辞書形に付く。「倒産しないしかない」とは言わない", "ほどではない：「〜ほどではない」は「そこまでの程度ではない」の意。「倒産しないほどではない」では意味が通らない", "までもない：「〜までもない」は「〜する必要はない」の意で、動詞の辞書形に付く。「倒産しないまでもない」とは言わない"], "ex": "財布を落としたが、カードが入っていなかった<b>だけましだ</b>。"},
"36290": {"point": "「〜ごとく」は「〜ように」という意味の硬い書き言葉で、動詞に付いて後に続く文全体にかかる。「すでに述べたごとく」で「すでに述べたように」となり、前に述べた内容を確認して話を進めている。", "opts": ["", "か否か：「〜か否か」は「〜かどうか」の意で、「すでに述べたか否か」では、述べたかどうか分からないことになり文意に合わない", "ような：「ような」は後に名詞が続く形で、読点で区切って後の文全体にかけるには「ように」にする必要がある", "なりに：「〜なりに」は「彼なりに努力した」のように「その人やものにふさわしい程度で」の意。前に述べた内容を示す文に合わない"], "ex": "ご存じの<b>ごとく</b>、当社は来年創立五十周年を迎えます。"},
"36291": {"point": "「〜だに」は「聞く・考える・想像する」などの動詞の辞書形に付いて「〜するだけでも」という意味を表す書き言葉。「聞くだに哀れ」で、彼の生い立ちは聞くだけでも哀れだったという文になる。", "opts": ["ばかり：「聞くばかり」は「ただ聞いているだけ」という意味になり、「哀れなものだった」につながらない", "のみ：「聞くのみ」は「聞くだけ（ほかはしない）」の意で、「聞くだけでも」という意味にならない", "", "こと：「聞くこと哀れなものだった」という形はなく、文が成り立たない"], "ex": "あの大地震がまた来るなんて、考える<b>だに</b>恐ろしい。"},
"36292": {"point": "「〜ことすら」は動詞の辞書形に付いて「〜することさえ」という意味を表し、極端な例を挙げて「ほかのことはもちろん」という気持ちを示す。ひどい風邪で、一人では起き上がることさえできないという文になる。", "opts": ["", "にすら：「にすら」は名詞に付いて「〜にさえ」（子供にすら分かる）の意を表す。動詞の辞書形「起きあがる」には付かない", "すら：「すら」は名詞などに付き、動詞の辞書形に直接付けて「起きあがるすら」とは言わない", "ですら：「ですら」は「専門家ですら」のように名詞に付く。動詞の辞書形には付かない"], "ex": "疲れきって、口をきく<b>ことすら</b>面倒だった。"},
"36293": {"point": "「〜ずじまい」は「（〜するはずだったのに）結局〜しないで終わる」という意味。書いた記事が、スペースの都合で結局紙面に載らないまま終わったという残念な結果を表す。", "opts": ["載るまい：「〜まい」は「〜ないだろう」という否定の推量で、後に「だった」は続かない", "", "載りっぱなし：「〜っぱなし」は「〜したまま」の意で、記事が載ったままの状態を表すことになり、「スペースの関係で」と合わない", "載らないまで：「載らないまでだった」という言い方はなく、文が成り立たない"], "ex": "せっかく買った本を、忙しくて読ま<b>ずじまい</b>だった。"},
"36294": {"point": "「〜ただろうに」は、事実と反対のことを仮定して「〜したのに（実際はそうではない）」と後悔や残念な気持ちを表す。若いころにもっと勉強しなかったので、今後悔しているという気持ちを述べる文になる。", "opts": ["だけましだ：「〜だけましだ」は「〜だけでもまだいい」の意で、実際に起きたよい点を述べる表現。事実に反する仮定とは合わない", "", "ほうがましだ：「〜ほうがましだ」は「（どちらも嫌だが）〜のほうがまだいい」と比べる表現で、仮定を受けて後悔を表すことはできない", "も同然だ：「〜も同然だ」は「ほとんど〜と同じだ」（勝ったも同然だ）の意で、後悔の気持ちは表さない"], "ex": "もっと早く病院に行っていれば、こんなに悪くならなかった<b>だろうに</b>。"},
"36295": {"point": "「〜次第だ」は名詞に付いて「〜によって決まる」という意味を表す。「〜かどうかは」を受けて、ピクニックに行くかどうかは天気によって決まるという文になる。", "opts": ["限りだ：「〜限りだ」は「うれしい限りだ」のように感情を表す形容詞に付いて「とても〜だ」の意を表す。名詞「お天気」には付かない", "のみだ：「〜のみだ」は「〜だけだ」の意で、「行くかどうかはお天気のみだ」では意味が通らない", "ほどだ：「〜ほどだ」は「泣きたいほどだ」のように程度を表し、「お天気ほどだ」では意味が通らない", ""], "ex": "合格できるかどうかは、これからの努力<b>次第だ</b>。"},
"36296": {"point": "「〜ことだし」は「〜ので」と理由を表す話し言葉で、後に「〜ましょう・〜よう」などの勧誘や意志が続く。「仕事も終わった」の「も」とともに理由の一つを軽く挙げ、みんなで飲みに行こうと誘う文になる。", "opts": ["ことに：「〜ことに」は「驚いたことに」のように話し手の感情を先に述べる表現で、理由を表さない", "", "ことで：「〜ことで」は「〜することによって」と手段や原因を表し、後に勧誘の「〜ましょう」が続く文に合わない", "こととは：「〜こととは（知らず）」は「〜ということとは知らずに」の意で、後に「知らず」などが必要。この文に合わない"], "ex": "せっかく京都まで来た<b>ことだし</b>、お寺をいくつか見て帰ろう。"},
"36297": {"point": "「〜ずにはすまない」は「（社会的な常識や周りの状況から）〜しないでは済まされない、必ず〜しなければならない」という意味。不正乗車が見つかったら、それ相当の罰金を払わなければならないという文になる。", "opts": ["", "払うには及ばない：「〜には及ばない」は「〜する必要はない」の意で、罰金を払わなくてもいいことになり、文意と反対になる", "払わないことはない：「〜ないことはない」は「全く〜しないわけではない」という弱い肯定で、必ず払わなければならないという意味にならない", "払うわけにはいかない：「〜わけにはいかない」は「（事情があって）〜できない」の意で、払えないという意味になり文意と反対になる"], "ex": "これほどの事故を起こした以上、会社は責任を取ら<b>ずにはすまない</b>だろう。"},
"36298": {"point": "「〜だけましだ」は「（悪い状況の中で）〜だけでもまだいい」という意味で、前には悪い状況の中にあるよい点が来る。業績は悪化したが、損失が出ていないことはせめてもの救いなので「損失が出ない」が入る。", "opts": ["収益が出ない：収益が出ないのは悪いことで、「だけましだ」の前に置くよい点にならない", "", "黒字にならない：黒字にならないのは悪いことなので、「まだいい」という評価と合わない", "売り上げが伸びる：「業績が悪化した」という状況と食い違い、悪い状況の中でせめてもの救いを挙げる「だけましだ」の文に合わない"], "ex": "試合には負けたが、けが人が出なかった<b>だけましだ</b>。"},
"36299": {"point": "「〜のごとき」は「〜のような」という意味の硬い書き言葉で、名詞の前に置いて例を示す。「日本のごとき島国」で「日本のような島国」となり、日本を島国の例として挙げている。", "opts": ["かたわら：「〜のかたわら」は「〜をする一方で」（仕事のかたわら）などの意で、後の名詞「島国」を修飾する形にならない", "からの：「日本からの島国」では「日本から来た島国」のような意味になり、文意が通らない", "", "らしく：「らしく」は後の名詞を修飾できる形ではなく、「日本のらしく」という形もない"], "ex": "富士山の<b>ごとき</b>美しい山は、世界でも珍しい。"},
"36300": {"point": "「〜からなる」は「〜で構成される」という意味で、後の名詞を修飾する。「国や大学の専門家からなる調査隊」で、国や大学の専門家で構成された調査隊が活動を始めたという文になる。", "opts": ["とはいうものの：「〜とはいうものの」は「〜とはいっても（実際は）」という逆接で、後の名詞を修飾する働きはない", "にしたって：「〜にしたって」は「〜にしても」の話し言葉で、「専門家にしたって」は「専門家でも」の意になり、「調査隊」を修飾できない", "", "をふまえて：「〜をふまえて」は「〜を前提・根拠にして」（結果をふまえて）の意で、構成は表さない"], "ex": "市民と専門家<b>からなる</b>委員会が、計画の見直しを提案した。"},
"36301": {"point": "「〜ことだし」は「〜ので」と理由を表し、後に「〜ましょう」などの意志や勧誘が続く。お客さんが帰ったので、そろそろ店を片づけようという、軽い理由を挙げて誘う文になる。", "opts": ["", "こととて：「〜こととて」は「〜なので（許してほしい）」（不慣れなこととて）の意で、謝罪や許しを求める硬い表現。片づけを誘う文に合わない", "ことに：「〜ことに」は「残念なことに」のように感情を述べる表現で、理由を表さない", "ことで：「〜ことで」は手段や原因を表し、後に勧誘の「〜ましょう」が続く文に合わない"], "ex": "天気もいい<b>ことだし</b>、窓を開けて掃除をしましょう。"},
"36302": {"point": "「〜だけましだ」は「（悪い状況の中で）〜だけでもまだいい」という意味。家が燃えてしまったという悲しい出来事の中でも、命が助かったことはせめてもの救いだという文になる。", "opts": ["ことしかない：「〜ことしかない」は「〜すること以外にない」の意で、「助かったことしかない」では意味が通らない", "", "ことばかりだ：「〜ことばかりだ」は「〜ことが多い」（悲しいことばかりだ）の意で、「命が助かったことばかりだ」では意味が通らない", "のみである：「〜のみである」は「〜だけだ」の書き言葉で、「助かっただけだ」という意味になり、「まだいい」という評価を表せない"], "ex": "雨で旅行は中止になったが、旅費が全額戻ってきた<b>だけましだ</b>。"},
"36303": {"point": "「〜だにしない」は「予想・想像」などの名詞に付いて「少しも〜しない」と強く否定する書き言葉。あんな遠くまで津波が来るとは少しも予想しなかったという驚きを表す。", "opts": ["だの：「〜だの〜だの」は例を並べる話し言葉（服だの靴だの）で、否定を強める働きはない", "でも：「予想でもしなかった」とは言わず、「少しも〜ない」という強い否定の意味にならない", "", "では：「では」は「予想では〜だった」のように判断の根拠などを示す使い方で、後の「しなかった」とつながらない"], "ex": "兵士たちは雨の中、微動<b>だにしなかった</b>。"},
"36304": {"point": "「〜かのごとき」は「まるで〜のような」という意味の硬い書き言葉で、後の名詞を修飾する。「真夏に戻ったかのごとき猛暑」で、もう10月なのに、まるで真夏に戻ったような暑さが続いているという文になる。", "opts": ["", "ゆえの：「〜ゆえの」は「〜が理由の」（若さゆえの失敗）の意で、「かの」の後には付かない。比喩も表せない", "だけの：「〜だけの」は限定や程度（できるだけの努力）を表し、「かの」の後には付かない", "いかん：「〜いかん」は「〜次第」（結果いかんでは）の意。「かのいかん」とは言わず、後の名詞「猛暑」も修飾できない"], "ex": "彼は何も知らない<b>かのごとき</b>顔をしていた。"},
"36305": {"point": "「〜ていただろうに」は、事実と反対のことを仮定して「〜していたのに」と残念な気持ちを表す。あの子は亡くなってしまったが、もし生きていたらもう15歳になっていたのにと悲しむ文になる。", "opts": ["からに：「からに」は「見るからに」のような決まった形で使い、文末に置いて残念な気持ちを表すことはできない", "までだ：「〜たまでだ」は「ただ〜しただけだ」の意で、事実に反する仮定を受けて残念な気持ちを表せない", "", "ように：「〜ように」は比喩や目的を表し、「なっていたように」では文が完結せず、残念な気持ちも表せない"], "ex": "あと一点取れていれば、優勝できた<b>だろうに</b>。"},
"36306": {"point": "「〜からなる」は「〜で構成される」という意味で、後の名詞を修飾する。「20人ほどの山岳人からなる救助隊」で、20人ほどの山岳人で構成された救助隊が派遣されたという文になる。", "opts": ["", "からある：「〜からある」は「10キロからある荷物」のように数量に付いて「〜以上もある」と多さを強調する。「山岳人からある」とは言わない", "に達する：「〜に達する」は「ある数量・段階まで届く」（参加者は千人に達した）の意で、「山岳人に達する救助隊」では意味が通らない", "に即する：「〜に即する」は「〜にぴったり合わせる」（現実に即した対策）の意で、構成を表さない"], "ex": "この小説は、五つの短い物語<b>からなる</b>。"},
"36307": {"point": "「〜すら〜ない」は「〜さえ〜ない」という意味で、極端な例を挙げて強く否定する。前の「〜とは」は意外な事実への驚きを表し、昔は田畑だった地域がこれほど賑わうとは、想像さえしていなかったという文になる。", "opts": ["想像することができた：肯定の形で、「〜とは」が表す「思いもよらなかった」という驚きと合わない", "", "想像さえしたわけだ：肯定の形で、「〜とは」が表す驚きと合わない。「わけだ」の「当然そうなる」という意味も文脈に合わない", "想像しないではいられない：「〜ないではいられない」は「どうしても〜してしまう」の意で、すでに起きた意外な事実への驚きを表せない"], "ex": "あまりに疲れて、返事をする気力<b>すら</b>なかった。"},
"36308": {"point": "「〜次第で」は名詞に付いて「〜によって（結果が変わる）」という意味を表す。「工夫次第で」で、工夫のしかたによって様々な使い方ができるという文になる。", "opts": ["ぎみで：「〜ぎみ」は「少し〜の傾向がある」（風邪ぎみ、疲れぎみ）の意で、主に体調や状態を表す語に付く。「工夫ぎみ」とは言わない", "", "ほどで：「〜ほどで」は「一週間ほどで」のように数量のおおよその程度を表し、「工夫ほどで」とは言わない", "限りで：「〜限りで」は「今月限りで終了」のように期限を表す。「工夫限りで」とは言わない"], "ex": "練習<b>次第で</b>、だれでも上手に泳げるようになる。"},
"36309": {"point": "「〜ずじまい」は動詞のない形に付いて（行かずじまい）、「（〜するつもりだったのに）結局〜しないで終わる」という意味を表す。寒さに負けて、結局どこにも出かけないまま一日が終わったという文になる。", "opts": ["あげく：「〜たあげく」は「さんざん〜した末に」（迷ったあげく）の意で、た形や「名詞＋の」に付く。「行かずあげく」とは言わない", "しまつ：「〜しまつだ」は「悪い経過の末に〜という結果になった」の意で、辞書形などに付く。「行かずしまつ」とは言わない", "", "まい：「まい」は辞書形などに付いて「〜ないだろう・〜ないつもりだ」の意を表す。「ず」の後には付かない"], "ex": "名前を聞か<b>ずじまい</b>で、彼とは別れてしまった。"},
"36310": {"point": "「〜ずにはすまない」は動詞のない形に付いて（する→せず）、「（周りの状況や常識から考えて）〜しないでは済まされない、〜しなければならない」という意味を表す。就職は重大な問題なので、親に相談しなければならないだろうという文になる。", "opts": ["相談しない：「〜ない」の形なら「相談しないではすまない」となり、「相談しないにはすまない」とは言わない", "相談する：辞書形に「にはすまない」は付かず、「しなければならない」という意味にならない", "相談した：た形に「にはすまない」は付かず、文が成り立たない", ""], "ex": "約束を破ってしまったのだから、彼に謝ら<b>ずにはすまない</b>。"},
"36311": {"point": "「～とあれば」は「～という事情なら」という意味で、後にはその事情のために行動する・行動せざるを得ないという内容が続く。「会社の命令という事情なら、従うしかない」となり、「従わざるを得ない」と合う。", "opts": ["とはいえ＝～とは言っても（逆接）。「命令だが従わざるを得ない」となり、前後が逆接の関係にならず意味が通らない", "", "というより＝～と言うよりむしろ。より適切な言い方に言い換える表現で、この文の意味に合わない", "ときたら＝～は（不満・あきれ）。話題の人や物への不満を述べる表現で、後に「従わざるを得ない」という判断は続かない"], "ex": "子どものため<b>とあれば</b>、どんな苦労もいとわない。"},
"36312": {"point": "「～てもさしつかえない」は「～しても問題ない・かまわない」という許可・容認の丁寧な表現。来月は暇なので、休暇をとっても仕事に支障はないだろうという意味になる。", "opts": ["かぎり：「かぎりない」は「限度がない・この上ない」という意味で、「休暇をとってもかぎりない」では意味が通らない", "", "やりがい：「やりがいがない」は「する価値や手応えがない」という意味で、「～ても」の後に続けても意味が通らない", "めんぼく：「面目ない」は「恥ずかしくて顔向けできない」という意味で、「～ても」とは結びつかず文脈にも合わない"], "ex": "体調が悪い方は、途中で退席なさっ<b>てもさしつかえありません</b>。"},
"36313": {"point": "「～てしかるべきだ」は「～するのが当然だ・～であるのが適当だ」という意味。体の不自由な人のことを考えれば、もう少し配慮があるのが当然だという主張になる。", "opts": ["ことだ：「しかる（然る）」は「べき」と結びついて「しかるべき」として使う語で、「しかることだ」という形にはならない", "はずだ：「はずだ」は当然の推量を表すが、「しかる」とは結びつかず、「しかるはずだ」という表現はない", "", "わけだ：「わけだ」は結論や納得を表すが、「しかる」とは結びつかず、「しかるわけだ」という表現はない"], "ex": "この問題については、市から住民に説明があっ<b>てしかるべきだ</b>。"},
"36314": {"point": "「涙ながらに」は「涙を流しながら」という意味の慣用的な表現で、「名詞＋ながらに」でその状態のままという意味を表す。犯人が泣きながら罪を認めた様子に合う。", "opts": ["", "ばかりに：「～ばかりに」は「～が原因で（悪い結果になる）」という意味で、「涙ばかりに」とは言わない", "のままに：「～のままに」は「心のままに」のように「～の通りに」という意味で、「涙のままに」という表現はない", "かぎりに：「～をかぎりに」は「～を最後に」という意味で、「を」が必要。「涙かぎりに」では意味も通らない"], "ex": "被災者は当時の様子を涙<b>ながらに</b>語った。"},
"36315": {"point": "「AなりBなり」は「AでもBでも」と例を挙げて、その中から選ぶことを表し、後に提案・勧めなどが続く。先生でも友達でもいいから誰かに相談することを勧める文に合う。", "opts": ["といい / といい：「AといいBといい」は「AもBも（どれをとっても）」と評価を述べる表現で、後に話し手の評価が続く。勧めの文には合わない", "といえ / といえ：「AといえBといえ」という表現はない。「AといわずBといわず（区別なく、全部）」とも形が違う", "", "なら / なら：「なら」は条件や話題を表す語で、「先生なら友達なら」と二つ並べて選択を示す使い方はしない"], "ex": "休みの日くらい、映画<b>なり</b>買い物<b>なり</b>に出かけたらどうですか。"},
"36316": {"point": "「～ならいざしらず」は「～なら仕方ない（話は別だ）が」という意味で、後に「しかし～は違う」と驚きや非難が続く。新入社員ならともかく、入社5年目の社員がミスをするのは信じられないという対比を表している。", "opts": ["なるがゆえに＝～であるために（理由）。理由を表すだけで、後の「入社5年目の君が」との対比を表せない", "", "にさきがけて＝～より先に。「新入社員にさきがけて」では「新入社員より先に」となり、後の文と意味がつながらない", "のかいもなく＝～した効果もなく（努力のかいもなく）。「新入社員のかいもなく」という言い方はなく、意味も合わない"], "ex": "子ども<b>ならいざしらず</b>、大人がそんな言い訳をするのは恥ずかしい。"},
"36317": {"point": "「～てこそはじめて」は「～して初めて」という意味で、その条件があって初めて結果が得られることを強調する。顧客の信頼は地道な努力があって初めて得られるという主張になり、後の「はじめて」と合う。", "opts": ["あっての：「AあってのB」は「AがあるからこそBが成り立つ」という意味で、後に名詞が来る（努力あっての成功）。後に「はじめて」が続くこの文には合わない", "", "あるからには：「～からには」は「～以上は当然」という意味で、後に義務や決意が続く。「はじめて」とは結びつかない", "あろうとも：「～（よ）うとも」は「たとえ～ても」という逆接の仮定で、「はじめて得られる」とは意味がつながらない"], "ex": "チーム全員の協力が<b>あってこそはじめて</b>、この計画は成功する。"},
"36318": {"point": "「～といっても言い過ぎではない」は「～と言っても大げさではない、～と言えるほどだ」という意味。彼女の歌の才能を「歌うために生まれた」と強く評価しても、誇張ではないと述べている。", "opts": ["言うきらいがある：「～きらいがある」は「～という良くない傾向がある」という意味で、「といっても」とつながらず、評価の文にも合わない", "", "言うのはきりがない：「きりがない」は「終わりがない」という意味で、「といっても」の後に続けても意味が通らない", "言ってはいられない：「～てはいられない」は「～している余裕はない」という意味で、彼女を評価する文に合わない"], "ex": "この作品は彼の最高傑作だ<b>といっても言い過ぎではない</b>。"},
"36319": {"point": "「～ときたら」は話題の人や物を取り上げて、それに対する不満やあきれた気持ちを述べる表現。父の機嫌をとって要領よく小遣いをもらっている妹に、あきれている気持ちを表している。", "opts": ["", "ということは：前の内容から結論を導く表現（つまり～）で、「妹ということは」では意味が通らない", "とはいえ＝～とは言っても（逆接）。「妹とはいえ」では「妹だが」という逆接になり、後の内容とつながらない", "とおもいきや＝～と思ったが、実は（意外な結果）。「妹とおもいきや」では意味が通らない"], "ex": "うちの息子<b>ときたら</b>、毎日ゲームばかりして少しも勉強しない。"},
"36320": {"point": "「～にかぎったことではない」は「～だけではない（ほかにも当てはまる）」という意味。夏の暑さに困るのは今年だけでなく毎年のことだが、という前置きになっている。", "opts": ["かかせない：「～にかかせない」は「～に必要不可欠だ」という意味で、「今年にかかせないこと」では意味が通らない", "きわまる：「～きわまる」は「失礼きわまる」のようにナ形容詞の語幹などに付いて「この上なく～だ」を表し、「今年にきわまる」とは言わない", "そくした：「～にそくした」は「現実に即した」のように「～に合わせた・従った」という意味で、この文の意味に合わない", ""], "ex": "若者の活字離れは、日本<b>にかぎったことではない</b>。"},
"36321": {"point": "「～てしかるべきだ」は「～されるのが当然だ」という意味。信号を無視して事故を起こしたことを非難し、重い罪に処されるのが当然だという話し手の判断を表している。", "opts": ["いられない：「～てはいられない」の形で「～している余裕はない」という意味になるが、ここでは「は」がなく、意味も文脈に合わない", "かなわない：「～てはかなわない」は「～されてはたまらない」と話し手自身が困る気持ちを表し、他人の行為を非難する文に合わない", "かたくない：「～にかたくない」は「想像にかたくない」のように名詞＋「に」に付いて「容易に～できる」を表し、「て」の後には続かない", ""], "ex": "利用者の意見は、もっと計画に反映されて<b>しかるべきだ</b>。"},
"36322": {"point": "「～にかぎったことではない」は「～だけではない」という意味。東京の物価が高いのは家賃や交通費だけでなく、ほかのものも高いということを表している。", "opts": ["にかかっている＝～によって決まる。「物価の高さは家賃や交通費によって決まる」となり、文の意味が通らない", "きわまりない＝この上なく～だ。「危険きわまりない」のようにナ形容詞の語幹などに付き、名詞「交通費」には付かない", "といったらない＝とても～だ（感情の強調）。「暑さといったらない」のように程度を表す語に付き、「交通費といったらない」では意味が通らない", ""], "ex": "人手不足は、介護業界<b>にかぎったことではない</b>。"},
"36323": {"point": "「～ならいざしらず」は「～なら仕方ないが」という意味。初めて来たのなら道に迷うのも仕方ないが、何回も来ているのにまた迷うのは信じられないという対比を表している。", "opts": ["とすれば＝～と仮定すれば。「初めてとすれば」では仮定の意味になり、後の「何回も来ているのに」との対比を表せない", "ともなれば＝～という立場や段階になると当然。「社長ともなれば」のように使い、「初めてともなれば」は不自然で後の対比とも合わない", "", "なるがゆえに＝～であるために（理由）。理由を表すだけで、「初めてではないのに迷う」という対比を表せない"], "ex": "平日<b>ならいざしらず</b>、週末のこの店は予約なしではまず入れない。"},
"36324": {"point": "「AなりBなり」は「AでもBでも」と方法を例として挙げ、その中から選べることを表す。要望や意見を電話でもファックスでも、好きな方法で受け付けているという案内になる。", "opts": ["あれ / あれ：「AであれBであれ」の「で」がない形で、「電話あれファックスあれ」という言い方はない", "", "つつ / つつ：「～つつ」は動詞のます形に付いて「～しながら」を表すので、名詞「電話」「ファックス」には付かない", "だの / だの：「AだのBだの」は不満や非難を込めて例を並べる話し言葉で、客への丁寧な案内文に合わない"], "ex": "詳しいことは、メール<b>なり</b>電話<b>なり</b>でお問い合わせください。"},
"36325": {"point": "「～ながらにして」は「～したままの状態で」という意味で、本来必要な行動をしなくても、その状態のまま何かができることを表す。インターネットのおかげで、家にいたままで買い物ができるという意味になる。", "opts": ["いればこそ＝家にいるからこそ（理由の強調）。家にいることが買い物できる理由になってしまい、意味が通らない", "いるまでもなく：「～までもなく」は「～する必要もなく」という意味で、「家にいる必要もなく」となり意味が通らない", "いるのみならず＝家にいるだけでなく。後に追加の内容が続く形で、「家にいたままで」という意味を表せない", ""], "ex": "衛星中継のおかげで、日本に<b>いながらにして</b>海外のサッカーの試合が見られる。"},
"36326": {"point": "「～でもさしつかえない」は「～でも問題ない・かまわない」という意味の丁寧な許容の表現。申し込みは窓口だけでなく、郵送やファックスでしてもかまわないと案内している。", "opts": ["かないません：「～てはかなわない」は「～されてはたまらない」という不満を表す表現で、受付方法の案内には合わない", "きりがありません＝終わりがない。「郵送・ファックスでもきりがありません」では意味が通らない", "", "およびません：「～には及ばない」は「～する必要はない」という意味で「には」が必要。また許容を表す案内文の意味に合わない"], "ex": "提出書類は、コピーで<b>もさしつかえありません</b>。"},
"36327": {"point": "「～とあれば」は「～という事情なら」という意味で、その特別な事情から当然予想される判断や行動が続く。人気バンドの公演が入場無料という事情なら、大混雑は間違いないという予想につながる。", "opts": ["", "にとっては＝～の立場から見ると。「入場無料にとっては」では意味が通らない", "を問わず＝～に関係なく（年齢を問わず）。「入場無料を問わず」では意味が通らない", "をもとに＝～を基礎・材料にして。「入場無料をもとに」では意味が通らない"], "ex": "憧れの作家に会える<b>とあれば</b>、どんなに遠くても行きたい。"},
"36328": {"point": "「～ときたら」は話題の人や物を取り上げ、不満やあきれた気持ちを述べる話し言葉。すぐに故障して使い物にならないパソコンへの不満を表しており、文頭の「まったく」とも合う。", "opts": ["とあって＝～という特別な事情なので。客観的な状況の説明に使い、「まったく」で始まる不満の文には合わない", "となると＝～ということになると、その場合は。仮定や話題の転換を表し、パソコンへの不満を表せない", "", "とくるなり：「とくるなり」という表現はない。「ときたら」と混同した形である"], "ex": "隣の家の犬<b>ときたら</b>、夜中まで吠えてうるさくて眠れない。"},
"36329": {"point": "「～と言っても過言ではない」は「～と言っても大げさではない、確かにそう言える」という意味。コンピューターがなければ現代社会は成り立たないと強く言っても、誇張ではないと述べている。", "opts": ["かなわない：「～てはかなわない」は「～されてはたまらない」という意味で、「と言っても」とはつながらず意味も合わない", "やまない：「～てやまない」は「願ってやまない」のように「心から～し続ける」という意味で、「言っても」の後には続かない", "はばからない：「～てはばからない」は「公言してはばからない」のように「遠慮せず堂々と～する」という意味で、「言っても」の後には続かない", ""], "ex": "スマートフォンは現代人の生活必需品だ<b>と言っても過言ではない</b>。"},
"36330": {"point": "「～てこそはじめて」は「～して初めて」という意味で、後にはその条件によって初めて実現する肯定的な結果が続く。失敗を何回も経験することで、初めて人間として成長するという意味になる。", "opts": ["悪い結果になることもあるのだ：「～てこそはじめて」の後には、その条件で初めて実現する肯定的な結果が来るので、悪い結果の可能性を述べる内容とは合わない", "", "成功するとは限らない：「～とは限らない」は部分否定で、「その条件で初めて実現する」という「～てこそはじめて」の意味と矛盾する", "結果は関係ないのではなかろうか：結果を否定する推量で、条件によって初めて結果が得られるという「～てこそはじめて」の文と合わない"], "ex": "自分で働い<b>てこそはじめて</b>、お金のありがたさが分かる。"},
"36331": {"point": "「～てしかるべきだ」は「～するのが当然だ」という意味で、「しかる」は「べき」と結びついて使われる。隣に引っ越してきたのなら、一言挨拶があるのが当然だという主張になる。", "opts": ["さる：「～てさるべきだ」という表現はない。「べき」と結びついて当然を表すのは「しかる」である", "", "たる：「たる」は「教師たる者」のように名詞に付いて立場を表す語で、「て」の後には続かない", "かかわる：「～にかかわる」は「命にかかわる」のように「～に関係する・影響する」という意味で、「て」の後には続かない"], "ex": "子どもの安全のための対策は、もっと早くとられ<b>てしかるべきだった</b>。"},
"36332": {"point": "「～にかぎったことではない」は「～だけではない」という意味。季節の変わり目に体力が落ちるのはお年寄りだけでなく、若い人にも起こることだと述べている。", "opts": ["といっても過言ではない＝～と言っても大げさではない。「年寄りといっても過言ではない」では意味が通らない", "にすぎない＝ただ～だけだ。程度が低いと軽く見る表現で、「年寄りにすぎない」では文の意味が通らない", "にほかならない＝まさに～だ。「努力の結果にほかならない」のように原因や本質を断定する表現で、「体力が低下するのは年寄りにほかならない」は不自然", ""], "ex": "ストレスを抱えているのは、大人<b>にかぎったことではない</b>。"},
"36333": {"point": "「～てもさしつかえない」は「～しても問題ない・かまわない」という意味。駅に近いという条件を満たしていれば、部屋が多少狭くてもかまわないという希望を表している。", "opts": ["かなわない：「～てはかなわない」は「～ではたまらない」という不満を表す表現で、「ても」には続かない", "", "わりきれない：「割り切れない」は「納得できない・すっきりしない」という意味で、「狭くてもわりきれない」では意味が通らない", "かぎりない：「限りない」は「限度がない・この上ない」という意味で、「狭くてもかぎりない」では意味が通らない"], "ex": "この書類は、鉛筆で書い<b>てもさしつかえない</b>。"},
"36334": {"point": "「～ときたら」は話題の人物を取り上げ、その人への不満やあきれた気持ちを述べる表現。最近、結婚のことばかり気にしている両親に、うんざりしている気持ちを表している。", "opts": ["とあれば＝～という事情なら。後にその事情のための判断や行動が続く表現で、両親への不満を述べる文には合わない", "になると＝～という状態になると。「両親になると」では「親という立場になると」という意味になり、文に合わない", "", "にすると＝～の立場からすると。後に「～だろう」などその人の気持ちの推測が続く表現で、話し手の不満を表せない"], "ex": "父<b>ときたら</b>、休みの日は一日中テレビの前から動かない。"},
"36335": {"point": "「～とあれば」は「～という事情なら」という意味で、「ため」に付くと「～のためなら（何でもする）」という意味になる。彼は当選のためなら、実行できない公約でもするだろうという推測を表している。", "opts": ["", "として：「当選するためとして」という言い方はなく、後の「実行できない公約もする」とつながらない", "とおもいきや＝～と思ったが（意外な結果）。後に意外な事実が続く表現で、推測を表す「～だろう」と合わない", "というより＝～と言うよりむしろ。より適切な表現に言い換えるときに使い、この文の意味に合わない"], "ex": "お客様のご希望<b>とあれば</b>、すぐに対応いたします。"},
"36336": {"point": "「～といっても過言ではない」は「～と言っても大げさではない」という意味。授業参観が保護者同士の交流の場になっている現状を、「社交場」と強く言っても誇張ではないと述べている。", "opts": ["いいものを：「～てもいいものを」は「～してもいいのに（そうしない）」という不満を表す表現で、この文の意味に合わない", "はなはだおかしい：「はなはだ」は「非常に」という意味で、「社交場となるといってもはなはだおかしい」では意味が通らない", "はばからない：「～てはばからない」は「遠慮せずに堂々と～する」という意味で、「といっても」の後には続かない", ""], "ex": "彼の発見が医学の歴史を変えた<b>といっても過言ではない</b>。"},
"36337": {"point": "「～てはじめて」は「～して、そのとき初めて」という意味で、ある経験をきっかけに、それまで気づかなかったことに気づくことを表す。外国で暮らして初めて、自分の国のよさが分かるという意味になる。", "opts": ["", "暮らしてまで：「～てまで」は「そこまで極端なことをして」という意味で、後に批判などが続く。「はじめて」とは結びつかない", "暮らすだけあって：「～だけあって」は「～なので、それにふさわしく」という評価を表し、「はじめて」の前には付かない", "暮らしてさえ：「～てさえ」は「～しても（極端な例）」という意味で、「はじめて」とは結びつかない"], "ex": "病気になっ<b>てはじめて</b>、健康のありがたさに気づいた。"},
"36338": {"point": "「生まれながらに」は「生まれた時から・生まれつき」という意味の慣用的な表現で、後の動詞「抱えた」を修飾する。生まれた時から障害を抱えている子どもたちを表している。", "opts": ["ながらも：「～ながらも」は「～けれども」という逆接を表し、「生まれながらも障害を抱えた」では意味が通らない", "ながらで：「生まれながら」の後に「で」を付ける形はなく、動詞を修飾するには「に」、名詞を修飾するには「の」を使う", "", "ながらは：「ながらは」という形はなく、動詞「抱えた」を修飾することができない"], "ex": "人は生まれ<b>ながらに</b>平等な権利を持っている。"},
"36339": {"point": "「～ならいざしらず」は「～なら話は別だが」という意味。大都市なら来る人もいるかもしれないが、こんな小さい町に人形博物館を作っても誰も来ないと、二つを対比して述べている。", "opts": ["", "ともなると＝～という段階・立場になると当然。後に大都市の特徴が続く形になり、「こんな小さい町」との対比を表せない", "にもかかわらず＝～のに。「大都市にもかかわらず」では「大都市なのに」となり、後の「こんな小さい町に」と矛盾する", "でもしかたなく：「でもしかたなく」という文型はなく、「大都市でもしかたなく」では意味が通らない"], "ex": "プロ<b>ならいざしらず</b>、素人がこんな難しい技をすぐにできるはずがない。"},
"36340": {"point": "「AなりBなりする」は「AでもBでも（何か方法をとって）」という意味で、例を挙げて選ばせ、後に命令や提案が続く。自分で調べるか人に聞くかして、早くレポートを仕上げなさいという命令に合う。", "opts": ["と / と：「と」は名詞を並べる助詞で、動詞「調べる」「聞く」を並べて後の「して」につなげる形にはならない", "こと / こと：「AことBこと」という並列の形はなく、後の「して」ともつながらない", "し / し：「～し～し」は理由などを並べる表現で、後に「して」は続かず、命令の文にも合わない", ""], "ex": "分からないことがあれば、辞書を引く<b>なり</b>先輩に聞く<b>なり</b>してください。"},
"36801": {"point": "「～ともなしに」は「特にそうするつもりもなく」という意味で、「聞くともなしに聞く」「見るともなしに見る」のように同じ動詞を繰り返して使う。車内の音楽を何となく聞いていたら、という状況に合う。", "opts": ["聞かないまでも＝聞くところまではしなくても。後に「聞いていると」が続くので矛盾する", "聞くどころではなく＝聞く余裕などまったくなく。後の「聞いていると」と矛盾する", "", "聞かないのみならず＝聞かないだけでなく。後に「聞いていると」が続くので矛盾する"], "ex": "窓の外を見る<b>ともなしに</b>見ていたら、昔の友人が通り過ぎた。"},
"36802": {"point": "「AあってのB」は「AがあるからこそBが成り立つ」という意味で、Aが不可欠であることを表す。会社がここまで成長できたのは皆さんの声援があったからこそだと、感謝を述べている。後に名詞「こと」が続く。", "opts": ["あるかの：「～かのようだ」なら比喩を表すが、「ご声援あるかのこと」という形はなく、意味も通らない", "", "あるかぎりの＝あるだけ全部の。「ご声援あるかぎりのこと」では意味が通らない", "ありながらの：「～ながら」は「～のに」という逆接にもなり、「ご声援ありながらのこと」では感謝を表す文に合わない"], "ex": "お客様<b>あっての</b>商売だから、サービスを何より大切にしている。"},
"36803": {"point": "「Aは言うにおよばず」は「Aはもちろん（Bも）」という意味。パソコンや携帯電話は当然のこととして、自動車や家電など身近な道具のほとんども半導体を使っていると、範囲を広げて述べている。", "opts": ["いいながら：「～と言いながら」の形で「～と言っているのに」という意味になり、「は」の後には続かず意味も通らない", "", "いえないほど：「～とは言えないほど」という程度を表す形で、「パソコン、携帯電話はいえないほど」では文が成り立たない", "いえないまでも：「～とは言えないまでも（～ほどではないが）」という形で「と」が必要。また「～はもちろん」の意味を表せない"], "ex": "この歌手は、国内は<b>言うにおよばず</b>、海外でも人気がある。"},
"36804": {"point": "「～をものともせず」は「困難や障害を問題にせず、それに負けないで」という意味で、他人の勇敢な行動をたたえるときに使う。重圧に負けずに自己ベストを更新して優勝した選手の様子に合う。", "opts": ["もとづいて：「～にもとづいて」は「～を基準にして」という意味で「に」を取る。「重圧を」とは結びつかず、意味も合わない", "もとにして：「～をもとにして」は「～を材料・根拠にして」という意味で、「重圧をもとにして」では意味が通らない", "もちろんだが：「～はもちろんだが」の形で使い、「を」とは結びつかない", ""], "ex": "彼女は足のけが<b>をものともせず</b>、最後まで走り切った。"},
"36805": {"point": "「～（よ）うと～まいと」は「～しても、しなくても（関係なく）」という意味で、同じ動詞の意向形と「まい」を並べる。雨が降っても降らなくても、父は毎朝必ず散歩に出かけるという習慣を表している。", "opts": ["降って：「降ろうと降ってと」という形はない。意向形「降ろう」と対になるのは否定の意志・推量を表す「まい」である", "降れ：命令形の「降れ」では「降ろうと降れと」となり、文型として成り立たない", "降らない：「降ろうと降らないと」とは言わない。この文型では否定に「まい」を使う", ""], "ex": "君が行こ<b>うと</b>行く<b>まいと</b>、私は一人でも行く。"},
"36806": {"point": "「～のかたわら」は「本業の～をしながら、その一方で別のことも」という意味で、長期間並行して行う活動に使う。会社勤めという本業の一方で、ボランティア活動にも取り組んでいることを表している。", "opts": ["あまり：「～のあまり」は「心配のあまり」のように「～しすぎて（悪い結果になる）」という意味で、文の意味に合わない", "そばで：「そば」は物理的に近い場所を表し、「会社勤めのそばで」では並行して行う活動を表せない", "", "いかんで：「～いかんで」は「～次第で」という意味で、「会社勤めのいかんで」では意味が通らない"], "ex": "父は農業<b>のかたわら</b>、地元の歴史を研究している。"},
"36807": {"point": "「～をもってしても」は「～を使っても・～ほどのものでも」という意味で、後に否定的な結果が続き、それでも不可能だということを強調する。優れた彼の能力でも解決できないほど難しい問題だという意味になる。", "opts": ["におうじて＝～に合わせて。「能力におうじてしても」という形はなく、後の「しても」とつながらない", "", "とあいまって＝～と一緒になって、さらに効果を高めて。「能力とあいまってしても」とは言わず、意味も通らない", "にかぎって＝～だけは特に（ほかとは違って）。「能力にかぎってしても」という形はなく、後の「しても」とつながらない"], "ex": "最新の医療技術<b>をもってしても</b>、この病気を治すことは難しい。"},
"36808": {"point": "「～を余儀なくされる」は「（周囲の状況のために）仕方なく～することになる」という意味。主語は「会社役員」で、不正が明るみに出たために辞職せざるを得なくなったので、受身の形が入る。", "opts": ["余儀なくした：能動の「余儀なくする」は一般的な形ではなく、主語が辞職に追い込まれた「会社役員」なので受身の「余儀なくされた」にする必要がある", "", "余儀なくできた：「余儀なく」に可能の「できた」を付ける形はない", "余儀なくさせた：「～を余儀なくさせる」は「（状況が人に）仕方なく～させる」という意味で、主語は原因の側になる。「会社役員は」が主語のこの文には合わない"], "ex": "台風の影響で、多くの便が欠航<b>を余儀なくされた</b>。"},
"36809": {"point": "「～べからず」は「～してはいけない」という強い禁止を表す書き言葉で、看板や掲示などで使われる。公園内で犬を連れて散歩することを禁止する掲示の文に合う。", "opts": ["のみか＝～だけでなく。後に追加の内容が続く必要があり、文末に置くことはできない", "", "まじき：「～まじき」は「あるまじき行為」のように後に名詞が続く形で、文末には使えない", "を禁じえない＝（感情を）抑えられない。「同情を禁じえない」のように感情を表す名詞に付き、動詞の辞書形には付かない"], "ex": "ここにごみを捨てる<b>べからず</b>。"},
"36810": {"point": "「～が早いか」は「～するとすぐに」という意味で、ある動作が起きたのとほぼ同時に次のことが起きることを表す。発車のベルが鳴ったと同時にドアが閉まり、電車が動き出した様子に合う。", "opts": ["とはいえ＝～とは言っても（逆接）。「ベルが鳴るとはいえ」では、ドアが閉まったこととの関係が逆接にならず意味が通らない", "が最後＝一度～したら、もう（悪い結果になる）。「～たが最後」の形でた形に付き、後に取り返しのつかない状態が続くので合わない", "", "ときたら：話題の人や物への不満を表す表現で、「ベルが鳴るときたら」では意味が通らない"], "ex": "息子は家に帰る<b>が早いか</b>、かばんを置いて遊びに出かけた。"},
"36811": {"point": "「～でなくてなんだろう」は「これが～でなければ何だというのか、まさに～だ」という反語の強調表現。締め切り前なのに酒を飲んでいる行動を、まさに現実逃避だと強く断定している。", "opts": ["とはいえないだろう＝～とは言えないだろう。「現実逃避ではない」という逆の意味になり、文脈と合わない", "であってなんだろう：「であってなんだろう」という形はない。反語で強調するには否定の「でなくて」を使う", "", "といったらないだろう：「～といったらない」は「寒さといったらない」のように程度を強調する表現で、「だろう」とは結びつかず、「現実逃避」にも合わない"], "ex": "命がけでわが子を守った。これが愛<b>でなくてなんだろう</b>。"},
"36812": {"point": "「～を皮切りに」は「～を始めとして、次々に」という意味で、ある出来事を出発点として同じようなことが続くことを表す。アメリカでの発売を最初に、ヨーロッパ、アジアでも順に発売されるという流れに合う。", "opts": ["", "先立って：「～に先立って」は「～の前に」という意味で「に」を取る。「発売を先立って」とは言わない", "込めて：「～を込めて」は「愛を込めて」のように気持ちを入れるという意味で、「発売を込めて」では意味が通らない", "余儀なく：「～を余儀なくされる」の形で「仕方なく～する」という意味になり、「発売を余儀なく」では意味が通らない"], "ex": "東京公演<b>を皮切りに</b>、全国ツアーが始まった。"},
"36813": {"point": "「～かぎりだ」は「とても～だ、この上なく～だ」という意味で、「寂しい・うれしい・心細い」など話し手の感情を表す形容詞に付く。3年間一緒に過ごした友だちとの別れが、とても寂しいという気持ちを表している。", "opts": ["", "きわまる：「～きわまる」は「失礼きわまる」のようにナ形容詞の語幹などに付き、イ形容詞「寂しい」に直接は付かない", "きわまりない：「～きわまりない」も「危険きわまりない」のようにナ形容詞の語幹などに付き、イ形容詞「寂しい」に直接は付かない", "といったところだ＝せいぜい～程度だ。程度が大したことないことを表し、強い寂しさを述べる文に合わない"], "ex": "憧れの先生に作品をほめてもらえて、うれしい<b>かぎりだ</b>。"},
"36814": {"point": "「～たるもの」は「～という立派な立場にある者は」という意味の書き言葉で、後に「～べきだ」など、その立場にふさわしいあり方が続く。経営者という立場の者は社会貢献も考えるべきだという主張に合う。", "opts": ["ある：「経営者あるもの」という形はない。立場を表すには「たる」を使う", "さる：「さる」は「さる方（ある方）」のように名詞の前に置く語で、名詞の後には付かない", "うる：「うる（得る）」は「ありうる」のように動詞のます形に付いて可能を表す語で、名詞「経営者」には付かない", ""], "ex": "教師<b>たるもの</b>、生徒の手本とならなければならない。"},
"36815": {"point": "「～かたがた」は「～を兼ねて」という意味で、一つの行為に二つの目的があることを表す改まった表現。開店の通知と挨拶を兼ねるという意味になり、挨拶状の文に合う。", "opts": ["あっての：「AあってのB」は「AがあるからこそBが成り立つ」という意味で、「ご通知あっての」では通知と挨拶を兼ねる意味にならない", "", "いかんによらず＝～がどうであっても関係なく（理由のいかんによらず）。「ご通知いかんによらず」では意味が通らない", "のかたわら＝～をしながら、その一方で。本業と並行して長期間行う活動に使い、通知と挨拶を兼ねる意味にはならない"], "ex": "先日のお礼<b>かたがた</b>、近況をご報告いたします。"},
"36816": {"point": "「～こととて」は「～なので」という意味の古い言い方で理由を表し、後に謝罪や、仕方がない結果が続くことが多い。家事に慣れていないので、何から手をつけたらいいか分からないという文に合う。", "opts": ["ことに：「～ことに」は「うれしいことに」のように感情を表す語に付く表現で、「慣れぬことに」では意味が通らない", "ことさえ：「～ことさえ」は極端な例を挙げる表現で、理由を表すことはできない", "", "ことでは：「～ことでは」は「そんなことでは（だめだ）」のように後に否定的な評価が続く表現で、理由を表さない"], "ex": "子どものした<b>こととて</b>、どうかお許しください。"},
"36817": {"point": "「～てはかなわない」は「～されては我慢できない・たまらない」という意味で、迷惑や不満を表す。「させられちゃ」は「させられては」の話し言葉。手当もないのに残業ばかりさせられるのは我慢できないという不満に合う。", "opts": ["あたらない：「～にはあたらない」は「驚くにはあたらない」のように「～する必要はない」という意味で、「ては」の後には続かない", "", "さしつかえない：「～てもさしつかえない」は「～しても問題ない」という意味で「ても」に付く。不満を表す文にも合わない", "ちがいない：「～にちがいない」は確信を表す表現で、「ては」の後には続かない"], "ex": "毎晩こんなに騒がれ<b>てはかなわない</b>。"},
"36818": {"point": "「～とばかりに」は「いかにも～と言わんばかりの様子で」という意味で、口には出さないが態度や行動にその気持ちが表れていることを示す。今がチャンスだと言わんばかりに、多くの人が個人輸入をしている様子に合う。", "opts": ["かと思うと＝～したと思ったらすぐに。動作の直後に別のことが起きることを表し、「チャンスかと思うと」では意味が通らない", "というところが：「というところが」という文型はなく、後の文とつながらない", "", "にもまして＝～以上に。比較を表す表現で、「今がチャンスにもまして」では意味が通らない"], "ex": "ベルが鳴ると、子どもたちは待ってました<b>とばかりに</b>教室を飛び出した。"},
"36819": {"point": "「～にあるまじき」は「～として決してあってはならない」という意味で、後に「行為・態度・発言」などの名詞が続く。記者という立場の人が絶対にしてはならない取材のやり方だと非難している。", "opts": ["べからず＝～してはいけない（禁止）。文末に置いて掲示などで使い、後に名詞「行為」は続かない", "はずの：「あるはずの行為」は「当然あるはずの行為」という意味になり、非難する文の意味と合わない", "かぎりの：「あるかぎりの」は「あるだけ全部の」という意味で、「記者にあるかぎりの行為」では意味が通らない", ""], "ex": "教師<b>にあるまじき</b>発言が問題になった。"},
"36820": {"point": "「～までだ」は動詞の辞書形に付き、「（ほかに方法がないなら）～すればいいだけだ」という話し手の覚悟や割り切った気持ちを表す。電車が動かないなら、タクシーで帰ればいいだけだという意味になる。", "opts": ["まである：「辞書形＋まである」という文型はなく、話し手の覚悟や決意を表せない", "までもない＝～する必要はない。「タクシーで帰る必要はない」となり、「しかたがない」と合わない", "", "までしかない：「～しかない」と「までだ」を混同した形で、そのような表現はない"], "ex": "誰も手伝ってくれないなら、自分一人でやる<b>までだ</b>。"},
"36341": {"point": "「～を限りに」は「～を最後に（それ以降はやめる）」という意味で、続けてきたことをある時点で終わりにするときに使う。今月を最後に芸能界を引退するという意味になる。", "opts": ["先立って：「～に先立って」は「～の前に」という意味で「に」を取る。「今月を先立って」とは言わない", "際して：「～に際して」は「～するときに」という意味で「に」を取る。「今月を際して」とは言わない", "限って：「～に限って」は「～だけは特に」の意。「を限って」は「期間を限って」のように範囲を区切る意味で、「最後に」という意味は表せない", ""], "ex": "今年度<b>を限りに</b>、この路線は廃止されることになった。"},
"36342": {"point": "「～まい」は動詞の辞書形などに付き、「もう～しないぞ」という話し手の否定の意志・決意を表す。何回買っても当たらないので、もう宝くじは買わないと決心している。", "opts": ["買いたい：願望を表し、「何回買っても当たらない」「もう」と合わない", "", "買うはずだ：当然の推量を表し、話し手の決意を表せない。「もう」とも合わない", "買うしかない＝買う以外に方法がない。当たらない宝くじを「もう買うしかない」となり、文脈と矛盾する"], "ex": "あんな失礼な店には、二度と行く<b>まい</b>。"},
"36343": {"point": "「～をふまえて」は「～を前提・根拠にして」という意味で、ある事実や経験を判断の基にして次の行動をするときに使う。過去の経験を基にして、慎重に計画を練るという意味になる。", "opts": ["かわきりに：「～をかわきりに」は「～を始めとして次々に」という意味で、「過去の経験をかわきりに」では意味が通らない", "よそに：「～をよそに」は「～を気にかけないで・無視して」という意味で、「慎重に計画を練る」と合わない", "", "おいて：「～をおいて」は「彼をおいてほかにいない」のように「～以外に」という意味で、後に「ほかに～ない」が続く。この文には合わない"], "ex": "アンケートの結果<b>をふまえて</b>、サービスを改善する。"},
"36344": {"point": "「～まみれ」は「汗・泥・ほこり」など汚いものが表面いっぱいについている状態を表す。押入れの奥に長い間しまわれていた古いアルバムに、ほこりがたくさんついている様子に合う。", "opts": ["ぎみ：「～ぎみ」は「風邪ぎみ・疲れぎみ」のように「少し～の傾向がある」という意味で、「ほこりぎみ」とは言わない", "がち：「～がち」は「病気がち・遅れがち」のように「～になりやすい」という傾向を表し、「ほこりがち」とは言わない", "", "ばかり：「ほこりばかりの」は「ほこりしかない」という意味になり、表面にほこりがついたアルバムの様子を表せない"], "ex": "子どもたちは泥<b>まみれ</b>になって遊んでいた。"},
"36345": {"point": "「～にこしたことはない」は「～のほうがいい・それが最も望ましい」という意味。経験がなくてもかまわないが、もちろん経験があるほうが望ましいと、前の内容を補う言い方になっている。", "opts": ["あるともかぎらない：「～とも限らない」は「～かもしれない」という可能性を表し、「もちろん」と合わない", "", "あるに相違ない＝あるに違いない（確信）。経験の有無を推量する意味になり、文脈と合わない", "なくてはならない＝必要だ。前の「経験がなくてもかまわない」と矛盾する"], "ex": "旅行の荷物は、軽い<b>にこしたことはない</b>。"},
"36346": {"point": "「～べく」は「～するために」という目的を表す硬い表現で、動詞の辞書形に付く（「する」は「すべく」となる）。客の要望に対応するという目的のために、高品質の商品作りに努めるという意味になる。", "opts": ["", "対応しまいと：「～まいと」は「～しないように」という意味で、「要望に対応しないように」となり文の意味に合わない", "対応するはおろか：「～はおろか」は「～はもちろん（さらに程度の高いことも～ない）」という意味で後に否定が続き、目的を表せない", "対応すべからず：「～べからず」は「～してはいけない」という禁止を表して文末に使う形で、目的を表せない"], "ex": "彼は医者になる<b>べく</b>、毎日夜遅くまで勉強している。"},
"36347": {"point": "「～ねばならない」は「～しなければならない」という意味の書き言葉。地球環境問題は、未来を考える人なら誰もが真剣に取り組んでいく必要がある問題だという意味になり、「誰もが真剣に」とも合う。", "opts": ["取り組むには及ばない＝取り組む必要はない。「誰もが真剣に」と合わず、文の意味と逆になる", "取り組むに値しない＝取り組む価値がない。地球環境問題の重要性を述べる文脈と矛盾する", "取り組むわけにはいかない＝（事情があって）取り組むことができない。「誰もが真剣に」と合わない", ""], "ex": "約束した以上、最後までやり遂げ<b>ねばならない</b>。"},
"36348": {"point": "「～ますように」は、相手の幸せや物事の実現を祈ったり願ったりするときに文末で使う表現。年始のあいさつで、相手と家族にとって素晴らしい年になることを願っている。", "opts": ["ばかりに：「～ばかりに」は「～が原因で（悪い結果になる）」という意味で後に結果が続き、文末で願いを表すことはできない", "らしく：「～らしく」は推量や「～にふさわしく」を表し、「ます」には付かず、文末にも置けない", "", "そうに：「～そうに」は様子を表す形で、「ます」には付かず、願いを表すこともできない"], "ex": "明日の試合で、みんなが実力を出せます<b>ように</b>。"},
"36349": {"point": "「～の至り」は「この上なく～だ」という意味の改まった表現で、「恐縮の至り」「光栄の至り」のように決まった名詞と使う。迷惑をかけてこの上なく申し訳ないという、丁寧な謝罪の言葉になる。", "opts": ["ずくめ：「～ずくめ」は「いいことずくめ」のように「～ばかり」という意味で名詞に直接付き、「恐縮のずくめ」とは言わない", "だらけ：「～だらけ」は「間違いだらけ」のように悪いものがたくさんある様子を表し、「の」の後には付かず謝罪の表現にもならない", "", "ばかり：「恐縮のばかり」という言い方はなく、この上ない気持ちを表す改まった表現にならない"], "ex": "先生にお越しいただけるとは、光栄<b>の至り</b>でございます。"},
"36350": {"point": "「～の極み」は「それ以上はない最高の状態・極限」という意味。父親の失業によって、一家がこれ以上ないほどの貧しい状態に陥ったことを表している。", "opts": ["あげく：「～のあげく」は「さんざん～した末に（悪い結果）」という意味で、陥った状態を表す名詞にはならない", "きざし＝兆候、何かが起こりそうな気配。「貧困のきざしに陥った」とは言わない", "", "しまい＝終わり。「貧困のしまいに陥った」という言い方はない"], "ex": "一流ホテルのスイートルームに泊まるなんて、贅沢<b>の極み</b>だ。"},
"36351": {"point": "「～ますように」は願いや祈りを表す文末表現で、「どうか」「どうぞ」とよく一緒に使われる。今年の入試で第一希望に合格できることを祈る気持ちを表している。", "opts": ["ところを：「～ところを」は「お忙しいところを」のように後に動作が続く表現で、文末に置いて願いを表せない", "", "ものか：「～ものか」は「絶対に～しない」という強い否定を表し、「ます」には付かず、「どうか」とも合わない", "はずだ：当然の推量を表し、「ます」には付かない。「どうか」と一緒に願いを表すこともできない"], "ex": "母の病気が一日も早く治ります<b>ように</b>。"},
"36352": {"point": "「～に越したことはない」は「～のほうがいい・それが最も望ましい」という意味で、た形の「越した」を使う決まった形。会議は欠席してもかまわないが、出席できればそれが最も望ましいという意味になる。", "opts": ["越すことはない：「辞書形＋ことはない」は「～する必要はない」という意味になり、「それが最も望ましい」という意味を表せない", "越したことではない：決まった形は「越したことはない」で、「では」を使う形はない", "", "越すということだ：「～ということだ」は伝聞や結論を表し、「それに越すということだ」では意味が通らない"], "ex": "健康のためには、早寝早起きする<b>に越したことはない</b>。"},
"36353": {"point": "「～を踏まえた」は「～を前提・根拠にした」という意味で、後の名詞「判断」を修飾する。経営戦略を立てるときには、常に現実を前提にした判断が必要だという意味になる。", "opts": ["にわたった：「～にわたる」は「3年にわたる工事」のように期間や範囲の全体に及ぶという意味で、「現実にわたった判断」では意味が通らない", "に及ばず：「～には及ばない」は「～する必要はない・～に届かない」という意味で、名詞「判断」を修飾できない", "", "をおいて：「～をおいて」は「～以外に（ほかに～ない）」という意味で後に否定が続き、名詞「判断」を修飾できない"], "ex": "専門家の意見<b>を踏まえた</b>対策が求められている。"},
"36354": {"point": "「～べく」は「～するために」という目的を表す硬い表現で、動詞の辞書形に付く。会議に間に合わせるという目的のために、報告書の作成に取り組んでいるという意味になる。", "opts": ["だに：「～だに」は「想像するだに恐ろしい」のように「～するだけでも」という意味で、後に感情を表す語が続く。目的を表せない", "", "より：「～より」は比較や起点を表し、目的を表さない。「間に合わせるより」では意味が通らない", "とは：「～とは」は驚きや定義を表し、「間に合わせるとは」では後の文とつながらない"], "ex": "政府は景気を回復させる<b>べく</b>、新たな政策を打ち出した。"},
"36355": {"point": "「～まいとして」は「～しないようにと思って」という意味で、強い意志を表す。親に負担をかけないようにと考えて、自分でアルバイトをして生活費を稼いだという意味になる。", "opts": ["", "かけよう：「～ようとして」は「～しようと努めて」という意味で、「親に負担をかけようとして」では逆の意味になる", "かけすぎない：「かけすぎないとして」では「かけすぎないと仮定して」という意味になり、意志を表せない", "かける一方だ：「～一方だ」は「どんどん～する」という変化の傾向を表す文末表現で、後に「として」は続かない"], "ex": "彼女は涙を見せ<b>まいとして</b>、ずっと笑顔でいた。"},
"36356": {"point": "「～まみれ」は「汗・泥・油」など汚れたものが体や表面いっぱいについている状態を表す。毎日汗をびっしょりかきながら必死に働いても、生活が少しも楽にならないという意味になる。", "opts": ["がてら：「～がてら」は「散歩がてら」のように「～のついでに」という意味で、「汗がてら」とは言わない", "", "の極み：「～の極み」は「最高の状態・極限」という意味で、「汗の極み」という言い方はない", "一方：「～一方だ」は動詞の辞書形に付いて「どんどん～する」という傾向を表し、名詞「汗」には付かない"], "ex": "整備士は油<b>まみれ</b>になりながら、エンジンを修理した。"},
"36357": {"point": "「声を限りに」は「声が出る限り、出せるだけの大きな声で」という意味の慣用表現。みんなが力いっぱい大声を出して、自分のチームを応援している様子を表している。", "opts": ["にひきかえ＝～とは反対に。二つのものを対比して述べる表現で、「声にひきかえ」では意味が通らない", "にかまけて＝～に気を取られて（ほかのことがおろそかになる）。「声にかまけて」では意味が通らない", "", "をもって＝～によって・～で。手段を表す硬い表現で、「出せる限りの大声で」という意味を表せない"], "ex": "遭難者は、声<b>を限りに</b>助けを求めた。"},
"36358": {"point": "「～ねばならない」は「～しなければならない」の書き言葉で、「する」は「せねば」となる。ここでは「ならない」が中止形の「ならず」になり、論文を提出しなければならないので忙しいという意味になる。", "opts": ["しては：「～てはならない」は「～してはいけない」という禁止で、論文の提出を禁じる意味になり文脈と合わない", "するも：「～するも」は「～したが」という逆接の書き言葉で、後に「ならず」は続かない", "しても：「～てもならない」という形はなく、意味が通らない", ""], "ex": "健康のために、もっと運動<b>せねばならない</b>。"},
"36359": {"point": "「～の至り」は「この上なく～だ」という意味の改まった表現で、「感激・光栄・恐縮」などの名詞に付く。栄誉ある賞をいただいたことへの、この上ない感激を改まった場で述べている。", "opts": ["のせい：「～のせい」は悪い結果の原因を表し、「感激のせいでございます」では意味が通らない", "", "の上：「～の上」は「～に加えて」「～したうえで」などの意味で、「感激の上でございます」という言い方はない", "あまり：「～のあまり」は「～しすぎて」という意味で後に結果が続く。文末に置いて気持ちを表すことはできない"], "ex": "私の拙い発表に長時間お付き合いいただき、恐縮<b>の至り</b>です。"},
"36360": {"point": "「～の極み」は「この上ない最高の状態」という意味で、「喜びの極み」「感激の極み」のように感情を表す名詞にも付く。国際大会の開催が決まったことが、この上ない喜びだという改まったあいさつになる。", "opts": ["", "かぎり：「～かぎりだ」は「うれしいかぎりだ」のように形容詞に付く表現で、「喜びのかぎり」とは言わない", "あげく：「～のあげく」は「さんざん～した末に（悪い結果）」という意味で、「喜びのあげく」では意味が通らない", "しまつ：「～しまつだ」は「～という悪い結果になる」という意味で、喜びを表す文に合わない"], "ex": "多くの方に支えられてこの日を迎えられ、感激<b>の極み</b>です。"},
"36361": {"point": "「～まい」は「～ないだろう」という否定の推量を表す書き言葉的な表現。事件が複雑なので、そう簡単には解決しないだろうという話し手の推量になり、「そう簡単には」とも合う。", "opts": ["解決するだろう：肯定の推量で、「そう簡単には」の後には否定の表現が必要なため合わない", "解決しきれる：「～きる」の可能形で「全部解決できる」という意味。「そう簡単には」の後に肯定は続かない", "", "解決しかねない＝解決するおそれがある。「～かねない」は悪い結果に使う表現で、「簡単には」とも合わない"], "ex": "あの頑固な父のことだから、私の意見など聞く<b>まい</b>。"},
"36362": {"point": "「～を限りに」は「～を最後に」という意味で、続けてきたことをその時点で終わりにすることを表す。今村部長は今日を最後に職場を去るという意味になる。", "opts": ["", "をかわきりに＝～を始めとして次々に。始まりを表すので、「職場を去る」という終わりの意味と合わない", "を機に＝～をよい機会として。新しいことを始める契機を表し、「今日を最後に」という意味は表せない", "をきっかけに＝～が契機となって。変化の原因や始まりを表し、「最後に」という区切りの意味にはならない"], "ex": "本日<b>をかぎりに</b>、当店は閉店いたします。"},
"36363": {"point": "「〜をふまえて」は「〜を前提・根拠にして」という意味で、調査結果や経験などを判断の土台にするときに使う。市場調査の結果を土台にして製品の開発を進める、という文意に合う。", "opts": ["にあって：「〜にあって」は「非常時にあって」のように「〜という状況・立場で」の意。市場調査は状況や立場ではないので合わない", "をこめて：「〜をこめて」は「愛情をこめて」のように気持ちを入れることを表し、「市場調査」には使えない", "にそなえて：「〜にそなえて」は「〜に対して準備して」の意。調査に備えて開発するのでは、調査を土台にするという順序と合わない", ""], "ex": "前回の反省<b>をふまえて</b>、今年の計画を立て直した。"},
"36364": {"point": "「〜に越したことはない」は「〜のほうがいい・〜であればそれが一番だ」という意味。目標は合格だが、高い点数が取れればそれが一番いい、という文意になる。「越した」「ことは」の形で固定した表現である。", "opts": ["", "こすことはない：この表現は「越した」（た形）で固定しており、辞書形の「こすことはない」という形はない", "こしたこともない：「は」を「も」に変えた形は使わない。「〜に越したことはない」で一つの表現である", "こすこともない：辞書形も「も」も固定した形と違い、このような表現はない"], "ex": "健康のためには、早寝早起きをする<b>に越したことはない</b>。"},
"36365": {"point": "「〜べく」は動詞の辞書形に付いて「〜するために」という目的を表す硬い書き言葉。瓦礫の下敷きになった人々を救うという目的のために救助隊が派遣された、という報道文らしい文に合う。", "opts": ["から：「から」は理由を表し、「救うから派遣された」では救うことが目的であることを表せない", "", "ので：「ので」も理由を表す。人々を救うことは派遣の理由ではなく目的なので合わない", "ゆえ：「ゆえ（に）」は「〜ので」という理由を表す書き言葉で、目的の意味はない"], "ex": "新しい技術を学ぶ<b>べく</b>、彼は海外へ留学した。"},
"36366": {"point": "「〜ますように」は文末に置いて、願いや祈りを表す（「〜ますように（と祈る）」）。データを失った相手を気づかい、締め切りの今日こそ何も起きないようにと願っている。", "opts": ["から：「起きませんから」は「起きないので」という理由・断言になり、何も起きないことを願う気持ちが表せない", "とか：「とか」は「〜と聞いた」という不確かな伝聞を表し、相手のために願う場面に合わない", "ものを：「〜ものを」は「言ってくれればよかったものを」のように不満・残念な気持ちを表し、願いの意味にならない", ""], "ex": "家族みんなが元気で過ごせます<b>ように</b>。"},
"36367": {"point": "「〜まみれ」は、泥・汗・ほこりなどが表面一面に付いている様子を表す。子どもたちがふかふかの雪の中で遊び、全身に雪がいっぱい付いている様子に合う。", "opts": ["ずくめ：「〜ずくめ」は「黒ずくめ」「いいことずくめ」のように全部がそれであることを表し、表面に付着している様子には使わない", "", "ばかり：「雪ばかりになる」は「雪だけになる」という意味で、体に雪が付いている様子を表せない", "ぎみ：「〜ぎみ」は「風邪ぎみ」のように「少し〜の傾向がある」の意で、意味が合わない"], "ex": "父は油<b>まみれ</b>になって、車を修理していた。"},
"36368": {"point": "「〜ねばならない」は「〜なければならない」の硬い言い方。「ねば」はない形（未然形）に付き、「する」の場合は「せねば」となる。会則のような規則を述べる文なので、硬い表現が合う。", "opts": ["すねば：「ねば」の前では「する」は「せ」になる。「すねば」という形はない", "", "しねば：「ない」の前は「し」だが、「ねば」の前では「せ」になるので、「しねば」とは言わない", "するねば：「ねば」は辞書形には付かないので、「するねば」という形はない"], "ex": "明日までに、この書類を提出<b>せねばならない</b>。"},
"36369": {"point": "「〜の至り」は「この上なく〜だ」という意味で、「光栄の至り」「感激の至り」など限られた名詞に付く改まった表現。専門家に作品をほめられた喜びを丁寧に述べる場面に合う。", "opts": ["幸せな：「至り」は名詞＋「の」に付く。な形容詞の連体形「幸せな」は「至り」に付かない", "嬉しい：い形容詞は直接「至り」に付かない。「至り」は「光栄」「感激」などの名詞＋「の」に付く", "喜ぶ：動詞の辞書形は「至り」に付かず、「喜ぶ至り」という表現はない", ""], "ex": "このような立派な賞をいただき、感激<b>の至り</b>です。"},
"36370": {"point": "「〜の極み」は「これ以上ないほど〜だ」という極限の状態を表す。身内の看病で心身ともに疲れ切り、疲労が限界に達していたという文意に合う。「疲労の極みに達する」のように「に達する」とも結びつく。", "opts": ["ずくめ：「〜ずくめ」は「いいことずくめ」のように全部がそれであることを表し、「疲労ずくめ」とは言わない。「に達する」にもつながらない", "のあげく：「〜のあげく」は「長い議論のあげく」のように、さんざん〜した末の結果を表し、後に結果の文が続く。「に達する」の前には置けない", "の境：「境」は「生死の境」のように二つのものの分かれ目を表し、疲れの限界という意味にならない", ""], "ex": "一流ホテルのスイートルームに泊まるなんて、ぜいたく<b>の極み</b>だ。"},
"36371": {"point": "「〜てみせる」は「必ず〜する」という話し手の強い意志・決意を表す。勝負に勝とうとする「一念（ひたすらな強い思い）」の内容として、「絶対に勝ってみせる」が合う。", "opts": ["", "勝ってやまない：「〜てやまない」は「願ってやまない」のように気持ちを表す動詞に付いて「心から〜し続ける」を表し、「勝つ」には付かない", "勝つものと思われる：「〜ものと思われる」は客観的な推量で、本人の強い決意を表す「一念」の内容に合わない", "勝つわけにはいかない：「勝ってはいけない事情がある」という意味になり、勝利への原動力という文意と反対になる"], "ex": "次の大会では、必ず優勝し<b>てみせる</b>。"},
"36372": {"point": "「〜きれない」は動詞の連用形に付いて「完全には〜できない」を表す。「とても」は後に否定を伴い、たった1時間では機械の使い方を全部説明することはできない、という文意になる。", "opts": ["しうる：「〜うる」は「〜できる」という可能を表し、「とても」が求める否定の形にならない", "しそうだ：様子や予想を表す肯定の形で、「とても〜ない」の形にならず、意味も合わない", "したはずだ：過去の事柄についての確信を表し、時間が足りなくて説明できないという文意に合わない", ""], "ex": "この量の宿題は、一日ではとてもやり<b>きれない</b>。"},
"36373": {"point": "「AといわずBといわず」は「AもBも区別なく、どこでも全部」という意味。国内も海外も区別なく、暇があればどこへでも旅に出かけていく友人の様子を表している。", "opts": ["というか/というか：「AというかBというか」は「大胆というか無謀というか」のように、一つのものを言い表す言葉を迷いながら並べる形で、場所を並べる文に合わない", "", "といえ/といえ：「といえ」を二つ並べる形はない。「〜とはいえ」「〜といえども」は逆接の表現で、意味も合わない", "といって/といって：「AといってBといって」という並列の形はなく、意味をなさない"], "ex": "彼の部屋は、机の上<b>といわず</b>床の上<b>といわず</b>、本であふれている。"},
"36374": {"point": "「〜たところで」は動詞のた形に付き、「〜しても（無駄だ・変わらない）」という意味を表す。どちらにしても事態の深刻さは変わらない、という後の否定の内容とよく合う。", "opts": ["するところで：この意味になるのはた形の場合で、辞書形の「するところで」は「ちょうどするその場面で」という意味になる", "するもので：「〜もので」は「〜ので」という理由・言い訳を表し、「〜しても変わらない」という意味にならない", "", "したもので：「〜たもので」も「遅れたもので、すみません」のように理由を表し、「〜しても変わらない」という意味にならない"], "ex": "今さら謝っ<b>たところで</b>、許してもらえないだろう。"},
"36375": {"point": "「〜か否か（かいなか）」は「〜かどうか」という意味の硬い表現。今回の景気対策が有効かどうか、その結果が出るのはまだ先だ、という文意に合う。", "opts": ["", "あるまでで：「〜までだ」は「〜するだけだ」という意味で、有効かどうかという判断の対象を示せない", "あるのみならず：「〜のみならず」は「〜だけでなく」の意で、後に「〜も」が続く形になるため文意が合わない", "あったからか：「〜からか」は「〜からだろうか」と理由を推測する形で、まだ結果が出ていない話と合わない"], "ex": "この計画を実行する<b>か否か</b>は、来週の会議で決める。"},
"36376": {"point": "「〜つつある」は「だんだん〜している」という変化の進行を表す。宅地開発が進む中で、道路や公園が少しずつ整備されてきているという文意に合う。主語が「公共施設が」なので受身の「整備される」を使う。", "opts": ["整備させられそうになる：使役受身の形で、施設が無理に整備させられるという意味になり、意味をなさない", "", "整備させ続ける一方だ：「させる」は使役で、「公共施設が」を主語にすると意味が通らない。「〜一方だ」と組み合わせたこの形も不自然", "整備し始めたばかりだ：能動の形なので「公共施設が整備する」ことになり、主語と合わない。施設は整備される側である"], "ex": "地球の温暖化は、確実に進み<b>つつある</b>。"},
"36377": {"point": "「〜つ〜つ」は、対になる二つの動詞の連用形に付いて、二つの動作が交互に繰り返される様子を表す。「差しつ差されつ」は互いに酒をつぎ合う様子を表す慣用表現で、友人と酒をつぎ合いながら夜を明かした場面に合う。", "opts": ["", "差し差され：「つ」がないと交互の動作を表す形にならず、このような言い方はない", "差すも差されるも：「AもBも」の形で両方を並べるだけで、交互に繰り返す様子を表せない", "差すとは差されるとは：「〜とは」は定義や驚きを表し、このように二つ並べる形はない"], "ex": "店の前を行き<b>つ</b>戻り<b>つ</b>しながら、入るかどうか迷った。"},
"36378": {"point": "「〜というものではない」は「必ずしも〜とは言えない」という部分否定の意味。値段が安ければいいとは限らず、品質を第一に考えるべきだという主張に合う。後に文が続くので「〜というものではなく」の形になる。", "opts": ["としたものではなく：「〜としたものではない」という形はなく、部分否定の意味を表せない", "", "としたもので：否定の形でないため、「安ければいい」を否定して「品質を第一に」と続ける文意にならない。このような言い方も普通しない", "というもので：肯定の形なので「安ければいい」を認めることになり、「品質を第一に考えるべきだ」と矛盾する"], "ex": "練習は、ただ長くやればいい<b>というものではない</b>。"},
"36379": {"point": "「〜てはばからない」は「遠慮せずに、堂々と〜する」という意味で、「言う」「公言する」「断言する」などに付く。森田さんが、京料理は世界一だと遠慮なく言い切っている様子を表す。", "opts": ["いいかねない：「〜かねない」は「言いかねない」のように動詞の連用形に付き、「言っていいかねない」という形はない", "かたくない：「〜にかたくない」は「想像にかたくない」のように「に」に続く表現で、「言ってかたくない」とは言わない", "かなわない：「〜てかなわない」は「暑くてかなわない」のように話し手が耐えられない気持ちを表し、森田さんの主張を述べる文に合わない", ""], "ex": "彼は、自分の作るラーメンが日本一だと言っ<b>てはばからない</b>。"},
"36380": {"point": "「〜そびれる」は動詞の連用形（ます形の語幹）に付き、「〜する機会を逃す」という意味を表す。アナウンスの音が小さくて、つい聞く機会を逃してしまったという文意なので「聞き」が入る。", "opts": ["聞く：「そびれる」は動詞の連用形に付く。辞書形の「聞くそびれる」という形はない", "聞いて：「そびれる」は連用形に付き、て形には付かない。「聞いてそびれる」とは言わない", "", "聞いた：た形には「そびれる」は付かない。「聞いたそびれる」という形はない"], "ex": "忙しくて、昼ご飯を食べ<b>そびれて</b>しまった。"},
"36381": {"point": "「〜そびれる」は「〜する機会を逃して、できないままになる」という意味。ちょっとしたお礼を言うタイミングを逃して言えなかったために、相手を怒らせてしまったという文意に合う。", "opts": ["言いかけて：「〜かける」は「途中まで〜する」の意。お礼を言いかけたことが相手を怒らせる原因にはならない", "", "言ったつもりで：「〜たつもり」は実際とは違う本人の思い込みを表し、「〜たつもりでいた」などの形で使う。機会を逃して言えなかったという原因を表す形にならない", "言ったものだから：「〜ものだから」は理由を表し、「お礼を言ったので相手を怒らせた」という不自然な因果関係になる"], "ex": "彼女に本当のことを言い<b>そびれた</b>まま、今日まで来てしまった。"},
"36382": {"point": "「〜つ〜つ」は二つの動作が交互に繰り返される様子を表す。「追いつ追われつ」は「追いかけたり追いかけられたりする」の意で、両チームが交互にリードを奪い合う決勝戦の大接戦の様子を表している。", "opts": ["", "追うや追われるや：「〜や」は「〜や否や（〜するとすぐ）」の意で、交互に繰り返す動作を表す形ではない", "追うなり追われるなり：「AなりBなり」は「どちらかを選んで」という提案に使い、試合の様子の描写に合わない", "追うだに追われるだに：「〜だに」は「考えるだに恐ろしい」のように「〜するだけでも」の意で、このように並べる形はない"], "ex": "木の葉が川の流れに浮き<b>つ</b>沈み<b>つ</b>しながら流れていった。"},
"36383": {"point": "「〜きれない」は動詞の連用形に付き、「（量が多くて）全部は〜できない」という意味。作品がたくさん並んでいるので、たった2時間では全部を見終えることはできないだろう、という文意に合う。", "opts": ["", "見つけない：「見つける」の否定で「発見しない」という意味になり、全部見ることができないという意味を表せない", "見かねない：「〜かねない」は「〜するかもしれない（悪い結果）」の意で、時間が足りなくて全部見られないという文意と合わない", "見かけない：「見かける」は「たまたま目にする」の意で、「最近彼を見かけない」のように使い、文意に合わない"], "ex": "この本は難しすぎて、一週間では読み<b>きれない</b>。"},
"36384": {"point": "「〜としたところで」は「仮に〜としても（結果は変わらない）」という意味で、後に否定的な内容が来る。仮に定年まで働いたとしても、老後の生活が保障されるわけではない、という文意に合う。", "opts": ["にしては：「〜にしては」は「子どもにしては上手だ」のように予想と違う結果を表し、文意に合わない", "かと思うと：「〜かと思うと」は「〜したと思ったらすぐに」や「〜と考えると」の意で、仮定して結果を否定する文意に合わない", "", "にはかかわりなく：「〜にかかわりなく」は「年齢にかかわりなく」のように違いがあるものに付いて「〜に関係なく」を表し、「定年まで働く」に付けても文意が通らない"], "ex": "今からタクシーで行く<b>としたところで</b>、開始時間には間に合わない。"},
"36385": {"point": "「AといわずBといわず」は「AもBも区別なく、全部」という意味。手も足も、体中どこもかしこも傷だらけになって帰ってきた様子を表し、後の「全身」とよく合う。", "opts": ["", "によらず/によらず：「〜によらず」は「見かけによらず」のように「〜に関係なく」の意で、このように二つ並べて体の部分を挙げる形にはならない", "というか/というか：「AというかBというか」は一つのものを表す言葉を迷いながら並べる形で、体の部分を並べる文に合わない", "においても/においても：「〜において」は場所・分野などを表す硬い表現で、体の部分には使わない"], "ex": "子どもたちは、顔<b>といわず</b>服<b>といわず</b>泥だらけになって遊んでいた。"},
"36386": {"point": "「〜つつある」は「だんだん〜している」という変化の進行を表す。「近年」とあるので、環境への貢献が、いい企業の条件の一つに少しずつなってきている、という意味になる。主語が「環境への貢献が」なので自動詞「なる」を使う。", "opts": ["しうる：「〜とする」は「〜を〜とする」の形で使う他動詞で、「環境への貢献が」を主語にできない。また「うる」は可能性を表すだけで変化を表さない", "なりうる：「〜うる」は「〜する可能性がある」の意で、「近年」と合わせて変化が進んでいる様子を表せない", "しつつある：「する」は他動詞なので、「環境への貢献が〜としつつある」では主語と合わない", ""], "ex": "スマートフォンの普及により、人々の生活は大きく変わり<b>つつある</b>。"},
"36387": {"point": "「〜か否か（かいなか）」は「〜かどうか」という意味の硬い表現。難民を受け入れるかどうかについて、盛んに議論が交わされているという文意に合う。", "opts": ["受け入れるからには：「〜からには」は「〜する以上は」の意で、後に「〜べきだ」などの決意・義務が続き、議論の内容を表せない", "受け入れるにしては：「〜にしては」は「初めてにしては上手だ」のように予想との違いを表し、文意が通らない", "", "受け入れてはじめて：「〜てはじめて」は「〜して、その後で初めて」の意で、議論の対象を示せない"], "ex": "彼が本当のことを話している<b>か否か</b>、確かめる方法はない。"},
"36388": {"point": "「〜てみせる」は「必ず〜する」という強い意志を表す。使役の「言わせる」と合わせた「言わせてみせる」は「必ず皆に言わせる」という意味になり、店を始めたばかりの人の将来への決意に合う。", "opts": ["", "言ったまでだ：「〜たまでだ」は「〜しただけだ」と自分の行為を軽く説明する言い方で、「いずれは」という将来の決意と合わない", "言うはずもない：「〜はずもない」は「〜するわけがない」という強い否定の推量で、決意を表せない", "言いようがない：「〜ようがない」は「〜する方法がない」の意で、店の料理をほめさせるという決意と合わない"], "ex": "今度の試験では、必ず満点を取っ<b>てみせる</b>。"},
"36389": {"point": "「〜てはばからない」は動詞のて形に付いて「遠慮せずに堂々と〜する」という意味を表す。新しく就任した財務相が、消費税増税を遠慮なく公言した、という文意に合うので、て形の「公言して」が入る。", "opts": ["公言する：辞書形には「はばからない」は付かず、て形にする必要がある", "公言した：た形には「はばからない」は付かない。「公言したはばからない」という形はない", "", "公言せず：「〜せず」は「〜しないで」の意で、「遠慮せずに公言する」という意味にならない。て形が必要"], "ex": "その監督は、次の作品が最高傑作になると明言し<b>てはばからない</b>。"},
"36390": {"point": "「〜というものだ」は「まさに〜だ」と、話し手が自分の判断を強く言い切る表現。こんな遅い時間に電話をかけてくることを、それはまさに非常識だと批判している。", "opts": ["はずだ：「はずだ」は根拠のある推量・当然を表し、「という」と結んで話し手の批判を言い切る形にならない", "ことだ：「〜ということだ」は「〜だそうだ」という伝聞や「つまり〜だ」という意味になり、話し手自身の強い批判を表せない", "ようだ：「〜というようだ」という形は普通使わず、推量では批判の気持ちを言い切れない", ""], "ex": "人の話を最後まで聞かずに反論するのは、失礼<b>というものだ</b>。"},
"36391": {"point": "「〜きれない」は「（量が多すぎて）全部は〜できない」という意味。こんなにたくさんの料理は、二人では全部食べることができない、という文意に合う。", "opts": ["食べるほかない：「〜ほかない」は「〜するしかない」の意で、量が多くて食べられないという文意と反対になる", "", "食べるまい：「〜まい」は「〜しないつもりだ」「〜しないだろう」の意で、量が多くて食べられないという意味を表せない", "食べざるをえない：「〜ざるをえない」は「どうしても〜しなければならない」の意で、文意と合わない"], "ex": "一度にこんなにたくさんの単語は、とても覚え<b>きれない</b>。"},
"36392": {"point": "「〜べきか否か」は「〜すべきかどうか」という意味。デートの食事代を男性が払うべきかどうかについて、さまざまな意見があるという文意に合う。「べき」に「か」を付けた形に「否か」が続く。", "opts": ["べく：「べく」は「〜するために」という目的を表し、「否か」とつながらない", "べき：「否か」の前には「か」が必要で、「べき否か」とは言わない", "べくも：「〜べくもない」は「〜できるはずもない」の意で、「否か」とつながらない", ""], "ex": "会社を辞める<b>べきか否か</b>、ずっと悩んでいる。"},
"36393": {"point": "「〜てみせる」は「必ず〜する」という強い決意を表す。候補者が、今回の選挙に必ず当選すると強く言い切った（断言した）という文意に合う。", "opts": ["みえる：「みえる」は「〜ように見える」という見た目の意味で、「当選してみえる」では決意を表せない", "", "みさせる：「みる」の使役の形で、「当選してみさせる」という表現は意味をなさず、決意を表せない", "みられる：「みる」の受身・可能の形で、決意の意味にならない"], "ex": "来年こそ、フルマラソンを完走し<b>てみせる</b>。"},
"36394": {"point": "「AといわずBといわず」は「AもBも区別なく」という意味。師走（12月）が近づき、週末も平日も関係なく送別会や忘年会が次々と予定されている（目白押し）様子を表す。", "opts": ["", "というか/というか：一つのものを表す言葉を迷いながら並べる形で、週末と平日の区別なく続く様子を表せない", "といった/といった：「〜といった」は「AやBといった＋名詞」のように例を挙げて後の名詞を修飾し、このように二つ並べる形にはならない", "といえど/といえど：「〜といえど（も）」は「〜であっても」という逆接で、二つ並べて区別のなさを表す形ではない"], "ex": "彼は、昼<b>といわず</b>夜<b>といわず</b>、研究に打ち込んでいる。"},
"36395": {"point": "「〜としたところで」は「仮に〜としても」という意味で、後に「期待どおりにはならない」という内容が続く。その問題は解決したとしても、納得していない人は大勢いる、という文意に合う。", "opts": ["につけても：「〜につけ（ても）」は「写真を見るにつけ」のように「〜するたびに」の意で、仮定の意味はない", "", "にいたっては：「〜にいたっては」は「弟にいたっては」のように名詞に付いて極端な例を挙げる表現で、文意が通らない", "もさることながら：「AもさることながらB」は「Aもそうだが、Bはさらに」の意で、名詞に付く。仮定の逆接にならない"], "ex": "たとえ今から勉強を始めた<b>としたところで</b>、試験には間に合わないだろう。"},
"36396": {"point": "「〜つつある」は動詞の連用形に付いて「だんだん〜している」という変化の進行を表す。子供が少なくなってきていることが原因で、学校の数も次第に減ってきている、という文意に合う。", "opts": ["きらいだ：「〜きらいがある」は「〜のよくない傾向がある」の意で、辞書形に付く。「減りきらいだ」という形はない", "がちだ：「〜がちだ」は「つい〜しやすい」という繰り返し起こりやすい傾向を表し、少子化で学校が次第に減っていく変化の進行を表せない", "", "始末だ：「〜始末だ」は辞書形に付き、悪い経過の末の結果を表す。「減り始末だ」という形はない"], "ex": "古い町並みは、開発によって少しずつ失われ<b>つつある</b>。"},
"36397": {"point": "「〜そびれる」は「〜する機会を逃す」という意味で、名詞形「買いそびれ」は「買う機会を逃すこと」を表す。定期購読なら、売り切れで買えなくなる心配も買い忘れの心配もない、という文意に合う。", "opts": ["買い控え：「買い控え」は「買うのを意識して控えること」で、売り切れが原因で起こるものではない", "", "買いだめ：「買いだめ」は「たくさん買っておくこと」で、定期購読でなくなる「心配」として「買い忘れ」と並ばない", "買い放題：「買い放題」は「好きなだけ買えること」で、心配の内容にならない"], "ex": "人気の限定商品なので、買い<b>そびれ</b>のないよう早めに予約した。"},
"36398": {"point": "「〜つ〜つ」は二つの動作が交互に繰り返される様子を表す。「抜きつ抜かれつ」は「抜いたり抜かれたりして」の意で、二人の選手が互いに順位を入れ替えながらゴールまで来た様子を表す。", "opts": ["", "抜いても抜かれても：「〜ても〜ても」は「どちらの場合でも」という逆接の仮定で、交互の動作の様子を表せず、「しながら」にもつながらない", "抜くなり抜かれるなり：「AなりBなり」は「どちらかを選んで」という提案に使い、レースの様子の描写に合わない", "抜くにしろ抜かないにしろ：「〜にしろ〜にしろ」は「どちらの場合でも」の意で、交互に抜き合う様子を表せない"], "ex": "近所の人たちとは、持ち<b>つ</b>持たれ<b>つ</b>の関係で助け合っている。"},
"36399": {"point": "「〜というものだ」は「まさに〜だ」と話し手の判断を強く言い切る表現。せまい歩道に自転車を置いたままにするのは、まさに迷惑そのものだ、と批判している。", "opts": ["からなる：「〜からなる」は「水は水素と酸素からなる」のように構成を表し、意味が合わない", "", "ものがある：「〜ものがある」は「迷惑なものがある」のように連体形に付き、「〜と感じさせる何かがある」という感嘆を表すので、断定の批判にならない", "としたところだ：このような形で判断を言い切る表現はなく、「迷惑」に付けても意味が通らない"], "ex": "約束の時間に一時間も遅れてくるなんて、無責任<b>というものだ</b>。"},
"36400": {"point": "「〜てはばからない」は「遠慮せず堂々と〜する」という意味。この本の著者が、報酬こそ最大のモチベーションだと周囲に遠慮せず言い切っている様子を表す。", "opts": ["きりがない：「きりがない」は「数えたらきりがない」のように「終わりがない」の意で、断言する著者の態度を表せない", "かなわない：「〜てかなわない」は「うるさくてかなわない」のように話し手が耐えられない気持ちを表し、著者の主張を述べる文に合わない", "", "さしつかえない：「〜てさしつかえない」は「〜してもかまわない」という許可を表し、著者が実際に強く言い切っている様子を表せない"], "ex": "彼女は、失敗はすべて部下のせいだと言っ<b>てはばからない</b>。"},
"36401": {"point": "「〜にのぼる」は数量を表す語に付き、「（数量が）〜という大きな数に達する」という意味を表す。今回の火災による被害額が数億円という大きな額に達している、という文意に合う。", "opts": ["たる：「〜にたる（足る）」は「信頼するにたる」のように「〜する価値がある・十分だ」の意で、被害額が大きな数に達することを表せない", "たりる：「〜にたりる」も「〜する価値がある・十分だ」の意で、数量が大きな数に達するという意味にならない", "よる：「〜による」は原因・手段を表し、「数億円による」では被害の額を表せない", ""], "ex": "この大会の参加者は、一万人<b>にのぼる</b>見込みだ。"},
"36402": {"point": "「〜とみえて」は普通形に付き、「（様子から判断して）〜らしく」という推量を表す。よく笑い声が聞こえてくる様子から、となりのクラスの授業は楽しいらしいと推測している。い形容詞は「楽しい」の形で付く。", "opts": ["楽しく：い形容詞の連用形で、「とみえて」の前には来ない", "楽しさ：名詞「楽しさ」は「楽しい程度」を表す語で、「授業は楽しさだ」とは言えず、意味が通らない", "楽しみ：「楽しみ」は「待ち遠しく思うこと」の意で、授業中に笑い声が聞こえる様子からの推量に合わない", ""], "ex": "彼はよほど疲れていた<b>とみえて</b>、ソファーで眠ってしまった。"},
"36403": {"point": "「〜には及ばない」は「〜にはかなわない・〜の程度に達しない」という意味。新作もすばらしいが、前作の出来にはとても届かない、と比べている。「はるかに」がその差の大きさを強めている。", "opts": ["あたらない：「〜にはあたらない」は「驚くにはあたらない」のように辞書形に付いて「〜する必要はない」の意で、比較を表さない", "たまらない：「〜にはたまらない」は「ファンにはたまらない」のように「〜にとってこの上なくいい」の意になり、前作と比べる文意にならない", "はばからない：「〜てはばからない」は「遠慮せず〜する」の意で、て形に付く。比較を表さない", ""], "ex": "私の料理の腕は、まだまだ母<b>には及ばない</b>。"},
"36404": {"point": "「〜にかたくない」は「想像」「察する」などに付き、「簡単に〜できる」という意味を表す硬い表現。当初の予想に反する研究にみんなが驚いたことは、簡単に想像できる、という文意に合う。", "opts": ["", "にもおよばない：「〜には及ばない」は「〜する必要はない」「〜にかなわない」の意で、驚いたことが簡単に想像できるという文意にならない", "せずにはすまない：「〜ずにはすまない」は「（状況から）どうしても〜しなければならない」の意で、文意に合わない", "しないではおかない：「〜ないではおかない」は「必ず〜する・必ず〜させる」の意で、「驚いたことは」を主題とする文に合わない"], "ex": "彼が大会で優勝するまでにどれほど努力したかは、想像<b>にかたくない</b>。"},
"36405": {"point": "「〜にしたら」は人を表す名詞に付き、「〜の立場から考えると」という意味を表す。学生の立場からすれば、休みは長ければ長いほどいいだろう、と推測している。", "opts": ["", "に対して：「〜に対して」は動作や気持ちが向かう相手を表し、「〜の立場から」という意味にならない", "にして：「〜にして」は「40歳にして」「名人にして」のように「〜で（さえ）」を表し、意味が合わない", "によって：「学生によって」は「学生によって違う」という個人差を表し、学生全体の立場から推測する文意に合わない"], "ex": "子ども<b>にしたら</b>、親の小言はうるさいだけだろう。"},
"36406": {"point": "「〜にかかっている」は「〜次第だ・〜によって決まる」という意味。あなたが成功できるかどうかは、与えられたチャンスをどう使うかによって決まる、という文意に合う。", "opts": ["かぎって：「〜にかぎって」は「うちの子にかぎって」のように「〜だけは特に」の意で、文意に合わない", "かなって：「〜にかなう」は「目的にかなう」のように「〜に合う」の意で、「次第だ」の意味にならない", "", "さきだって：「〜にさきだって」は「〜の前に」の意で、文意に合わない"], "ex": "このプロジェクトが成功するかどうかは、チームワーク<b>にかかっている</b>。"},
"36407": {"point": "「〜によるところが大きい」は「〜が主な原因だ・〜のおかげが大きい」という意味。今の経済不況の主な原因は金融政策の失敗だ、という文意に合う。", "opts": ["たる：「〜にたる（足る）」は「〜する価値がある」の意で、原因を表さない", "", "みる：「〜にみるところが大きい」という表現はなく、原因を表せない", "くる：「〜にくるところが大きい」という表現はなく、原因を表せない"], "ex": "彼の成功は、家族の支え<b>によるところが大きい</b>。"},
"36408": {"point": "「〜にかこつけて」は「〜を口実にして」という意味で、本当の目的が別にあることを表す。父が仕事仲間との付き合いを口実にして、酒を飲んで帰宅することが多い、という文意に合う。", "opts": ["", "かけて：「〜にかけて」は「〜から〜にかけて」で範囲を、「〜にかけては」で得意な分野を表し、口実の意味はない", "かたがた：「〜かたがた」は「散歩かたがた」のように名詞に直接付いて「〜を兼ねて」を表し、「に」の後には来ない", "かぎって：「〜にかぎって」は「〜の場合だけ特に」の意で、口実の意味はない"], "ex": "彼は体調不良<b>にかこつけて</b>、面倒な会議を欠席した。"},
"36409": {"point": "「〜に言わせると」は人を表す名詞に付き、「その人の意見では」という意味を表す。彼の意見では、このパソコンは性能が低くて使い物にならない、ということだ。", "opts": ["と言っても：「〜と言っても」は「〜とは言っても実際は」の意で、彼の意見を示す形にならない", "と言えば：「〜と言えば」は「彼と言えば〜」のように話題を取り上げる表現で、彼の意見の内容を紹介する文にならない", "", "に言わせられれば：使役受身の形で、このような表現はなく、意見の主を示せない"], "ex": "母<b>に言わせると</b>、最近の若者は礼儀を知らないそうだ。"},
"36410": {"point": "「〜にとどまらず」は「〜の範囲だけで終わらず、さらに広く」という意味。この書店では本だけでなく、幅広いライフスタイルまで提案していく、という文意に合う。", "opts": ["とわず：「〜を問わず」は「を」を取る表現で、「に」の後には来ない。意味も「〜に関係なく」で合わない", "かかわらず：「〜にかかわらず」は「〜に関係なく」の意で、範囲を広げる文意に合わない", "", "のみならず：「のみならず」は「本のみならず」のように名詞に直接付き、「だけに」の後には来ない"], "ex": "彼の活躍は国内<b>にとどまらず</b>、海外にまで広がっている。"},
"36411": {"point": "「〜にしたら」は「〜の立場から考えると」という意味。言う側には軽い励ましの言葉でも、言われる本人の立場からすると負担になることもある、という立場の違いを表している。", "opts": ["にかけては：「〜にかけては」は「数学にかけては」のように得意な分野を表し、文意に合わない", "によっては：「〜によっては」は「人によっては」のように、いくつかある場合の中の一部を表す。ここは「言われる本人」という一人の立場から見た文で合わない", "にかかわらず：「〜にかかわらず」は「〜に関係なく」の意で、本人の立場から見るという文意に合わない", ""], "ex": "親<b>にしたら</b>、子どもの独立はうれしくもあり寂しくもあるものだ。"},
"36412": {"point": "「〜にかこつけて」は「〜を口実にして」という意味で、話し手の非難やあきれる気持ちを伴うことが多い。出張を口実にして大阪にいる彼女に会ってきた山下君に、話し手があきれている。", "opts": ["にかまけて：「〜にかまけて」は「仕事にかまけて家族を顧みない」のように、あることに気を取られてほかのことをおろそかにする意で、文意に合わない", "にてらして：「〜に照らして」は「規則に照らして」のように「〜を基準にして」の意で、文意に合わない", "", "にかかわりなく：「〜にかかわりなく」は「〜に関係なく」の意で、出張を口実にするという意味にならない"], "ex": "彼は友人の結婚式<b>にかこつけて</b>、一週間も休みを取った。"},
"36413": {"point": "「〜に言わせれば」は「その人の意見では」という意味で、その人ならではの考えを紹介するときに使う。登山家の山田さんの意見では、富士山などは登山のうちに入らない、と伝えている。", "opts": ["いえば：「に」の後に「いえば」は続かない。「〜と言えば」は話題を取り上げる形で、意見の紹介にならない", "", "いわれれば：受身の「〜に言われれば」は「〜に言われたら（私は）」の意になり、山田さんの意見を伝える文に合わない", "いわせられれば：使役受身の形で、このような表現はない"], "ex": "祖父<b>に言わせれば</b>、今の夏は昔よりずっと暑いそうだ。"},
"36414": {"point": "「〜には及ばない」は辞書形に付いて「〜する必要はない」という意味を表す。5年も住んでいたのだから、彼がフランス語ができるのは驚く必要はない（当然だ）、と後の文で理由を述べている。", "opts": ["限りません：「〜とは限らない」は「と」を取る表現で、「驚くには限りません」とは言わない", "", "かないません：「〜にはかなわない」は「彼にはかなわない」のように名詞に付いて「勝てない」を表し、「驚くには」とは結びつかない", "差し支えありません：「〜ても差し支えない」は「〜てもかまわない」の意で、「〜には」の形にはならない"], "ex": "その程度のけがなら、心配する<b>には及ばない</b>。"},
"36415": {"point": "「〜にかたくない」は「簡単に〜できる」という意味の硬い表現で、「想像」「察する」「理解する」などに付く。あらゆる状況から見て、彼が犯人だと判断することは簡単にできる、という文意に合う。", "opts": ["に至らない：「〜に至らない」は「大事故には至らなかった」のように「〜という段階まで行かない」の意で、状況から簡単に判断できるという文意と反対になる", "にあたらない：「〜にあたらない」は「驚くにはあたらない」のように「〜する必要はない」の意で、判断が容易だという意味にならない", "に違いない：「判断するに違いない」では「（だれかが）きっと判断するだろう」という推量になり、簡単に判断できるという意味にならない", ""], "ex": "彼が転職を決意した理由は、理解する<b>にかたくない</b>。"},
"36416": {"point": "「〜にのぼる」は数量を表す語に付き、「（数量が）〜という大きな数に達する」という意味を表す。1か月に一冊も本を読まない中学生が55％という高い割合に達している、という文意に合う。", "opts": ["わたる：「〜にわたる」は「3日間にわたる」のように時間や場所の範囲全体を表し、割合が達することには使わない", "", "もとづく：「〜にもとづく」は「〜を根拠にする」の意で、数量が達することを表せない", "たる：「〜にたる（足る）」は「信頼するにたる」のように「〜する価値がある」の意で、数量には使わない"], "ex": "この病気に悩む人は、国内で百万人<b>にのぼる</b>と言われている。"},
"36417": {"point": "「〜とみえて」は「（様子から判断して）〜らしく」という推量を表し、後にその根拠となる様子が続く。映画館の前に行列ができている様子から、その映画は人気があるらしいと推測している。", "opts": ["みて：「〜とみて」は「警察は事故とみて調べている」のように、ある人が「〜と判断して」行動する意で、判断する人が文中にいないので合わない", "", "みせて：「〜とみせて」は「〜のように見せかけて」の意で、推量を表さない", "みさせて：「みる」の使役の形で、このような表現はない"], "ex": "彼女は何かいいことがあった<b>とみえて</b>、朝からずっと機嫌がいい。"},
"36418": {"point": "「〜にかかっている」は「〜次第だ・〜によって決まる」という意味。そのコンサートが成功するかどうかは、彼が参加するかしないかによって決まる、という文意に合う。「〜か〜ないか」とよく結びつく。", "opts": ["たりる：「〜にたりる」は「〜する価値がある・十分だ」の意で、文意に合わない", "たえない：「〜にたえない」は「見るにたえない」「感謝にたえない」のように使い、「次第だ」の意味にならない", "ともなっている：「〜にともなう」は「〜と一緒に起こる」の意で、成功が何によって決まるかを表せない", ""], "ex": "試合に勝てるかどうかは、選手たちの体調<b>にかかっている</b>。"},
"36419": {"point": "「〜にとどまらず」は「〜の範囲だけで終わらず、さらに広く」という意味。海苔は日本国内だけでなく、海外でも注目されている、という文意に合い、後の「海外でも」の「も」とよく対応する。", "opts": ["におよばず：「〜に及ばず」は「言うに及ばず」のように動詞に付く形で使い、「国内におよばず」とは言わない", "", "にもまして：「〜にもまして」は「以前にもまして」のように「〜以上に」と比較を表し、「海外でも」の追加の「も」と合わない", "にかかわらず：「〜にかかわらず」は「〜に関係なく」の意で、範囲を広げる文意に合わない"], "ex": "彼の研究は学問の世界<b>にとどまらず</b>、産業界にも大きな影響を与えた。"},
"36420": {"point": "「〜によるところが大きい」は「〜が主な原因だ・〜のおかげが大きい」という意味。「AもさることながらB」は「Aもそうだが、Bのほうがさらに」の意で、映画のヒットの主な理由は俳優の演技力だ、と述べている。", "opts": ["", "にとるものがある：このような表現はなく、意味をなさない", "にはあたらない：「〜にはあたらない」は辞書形に付いて「〜する必要はない」の意で、名詞「演技力」には付かず、意味も合わない", "にかぎったことではない：「〜にかぎったことではない」は「〜だけではない」の意で、演技力が主な理由だという文意と合わない"], "ex": "この地域の発展は、新しい鉄道の開通<b>によるところが大きい</b>。"},
"36421": {"point": "「口にのぼる」は「人々の話題になる・うわさされる」という意味の慣用表現。大物政治家のスキャンダルが人々の話題になっている、という文意に合う。", "opts": ["", "のせて：「のせる」は他動詞で「〜を…にのせる」の形になり、「スキャンダルが」を主語にした文に合わない", "かけて：「かける」も他動詞で「スキャンダルが」を主語にできず、「話題になる」の意味も表さない", "かかって：「口にかかる」では「話題になる」という意味を表さない。人々に話題にされることは「口にのぼる」と言う"], "ex": "その事件は、今でも時々人々の<b>口にのぼる</b>。"},
"36422": {"point": "「〜とみえて」は「（様子から判断して）〜らしく」という推量を表す。彼が車のカタログを集めている様子から、彼は車がほしいらしいと推測している。", "opts": ["とされて：「〜とされる」は「一般に〜と考えられている」の意で、様子から推量する意味がない", "", "となって：「〜となって」は「〜という状態になって」の意で、様子から推量する意味がない", "ときて：「〜ときて」は「〜ときたら」「〜とくれば」のように話題を取り上げる形で使い、推量を表さない"], "ex": "弟はよほどお腹がすいていた<b>とみえて</b>、ご飯を三杯もおかわりした。"},
"36423": {"point": "「〜に言わせれば」は「その人の意見では」という意味。自分はおいしいと思ったが、イタリアに住む友人の意見では、これくらいの味はどこにでもある、と自分と違う意見を紹介している。", "opts": ["言うが：「友人に言うが」は「友人に言うけれども」の意で、友人の意見を紹介する形にならない", "言っても：「友人に言っても」は「友人に話しても」の意で、意見の紹介にならない", "言われては：受身の「〜に言われては」は「〜に言われたら（困る・黙っていられない）」のように後に話し手の反応が続き、友人の意見を伝える文に合わない", ""], "ex": "専門家<b>に言わせれば</b>、この程度の地震は珍しくないそうだ。"},
"36424": {"point": "「〜にかかっている」は「〜次第だ・〜によって決まる」という意味。会社の実績が伸びるかどうかは、新商品が売れるか売れないかによって決まる、という文意に合う。", "opts": ["きまっている：「〜にきまっている」は「売れるにきまっている」のように普通形に付いて「きっと〜だ」という確信を表し、「〜か〜ないか」には付かない", "かなっている：「〜にかなう」は「目的にかなう」のように「〜に合う」の意で、「次第だ」の意味にならない", "おかれている：「〜におかれている」は「厳しい状況におかれている」のように状況・立場を表し、文意に合わない", ""], "ex": "来年の売り上げは、この新製品の評判<b>にかかっている</b>。"},
"36425": {"point": "「〜にすれば」は人を表す名詞に付き、「〜の立場から考えると」という意味を表す。あなたの立場からすれば1万円は大したお金ではないだろうが、私には大金だ、と立場の違いを比べている。", "opts": ["", "よれば：「〜によれば」は「天気予報によれば」のように情報の出所を表し、後に「〜そうだ」などが続く。立場を表さない", "いえば：「〜にいえば」という形はなく、立場を表せない", "見れば：「見れば」は「〜から見れば」の形で使い、「に」の後には来ない"], "ex": "親<b>にすれば</b>、子どもの帰りが遅いと心配になるのは当然だ。"},
"36426": {"point": "「〜には及ばない」は「〜にはかなわない・〜の程度に達しない」という意味。高級レストランの料理にはかなわないが、このレストランの料理もなかなかおいしい、と比べている。「には」で比べる相手を示す。", "opts": ["とも：「とも」では比べる相手を示せず、「〜とも及ばない」とは言わない", "では：「では」は場所・場合を表し、「高級レストランでは及ばない」では比べる相手を示せない", "", "かは：名詞に「かは」を付けて比べる相手を示す形はなく、意味をなさない"], "ex": "この店のケーキは有名店のもの<b>には及ばない</b>が、値段が手ごろだ。"},
"36427": {"point": "「〜によるところが大きい」は「〜が主な原因だ・〜のおかげが大きい」という意味。かつて有名タレントだった田中氏が知事選に勝った主な理由は、人気と知名度だ、という文意に合う。", "opts": ["にされる：「にする」の受身で、「人気と知名度にされる」では原因を表せない", "にさせられる：使役受身の形で、原因を表す意味にならない", "になる：「〜になる」は変化を表し、「〜になるところが大きい」という表現はない", ""], "ex": "今回の優勝は、監督の的確な指導<b>によるところが大きい</b>。"},
"36428": {"point": "「〜にかたくない」は「察する」「想像」などに付き、「簡単に〜できる」という意味を表す。交通事故で娘をなくした彼女の悲しみがどれほど深いかは、簡単に察することができる、という文意に合う。", "opts": ["にたえない：「〜にたえない」は「見るにたえない（ひどくて見ていられない）」「感謝にたえない」のように使い、「察するにたえない」とは言わない", "にいたらない：「〜にいたらない」は「〜という段階まで行かない」の意で、悲しみが簡単に察せられるという文意と合わない", "", "にたまらない：「たまらない」は「〜てたまらない」の形で使い、「〜にたまらない」の形で「簡単に〜できる」を表すことはない"], "ex": "長年勤めた会社を去る彼の寂しさは、察する<b>にかたくない</b>。"},
"36429": {"point": "「〜にかこつけて」は「〜を口実にして」という意味で、それを理由にして本来はよくないことをする様子を表す。サッカーの応援を口実にして、若者が大声を出して騒ぎたてている、という文意に合う。", "opts": ["かまわず：「〜にかまわず」は「人目にかまわず」のように「〜を気にせず」の意で、「応援」を気にしないという文意は通らない", "", "ひきかえ：「〜にひきかえ」は「兄にひきかえ弟は」のように二つを対比する表現で、文意に合わない", "かかわらず：「〜にかかわらず」は「〜に関係なく」の意で、口実の意味にならない"], "ex": "息子は勉強<b>にかこつけて</b>、毎晩遅くまで友達の家にいる。"},
"36430": {"point": "「〜にとどまらず」は「〜の範囲だけで終わらず、さらに広く」という意味。この町は農業だけでなく、地場産業の活性化にまで支援活動の範囲を広げている、という文意に合う。", "opts": ["かこつけて：「〜にかこつけて」は「〜を口実にして」の意で、文意に合わない", "てらして：「〜に照らして」は「〜を基準にして」の意で、範囲を広げる文意に合わない", "", "ひきかえ：「〜にひきかえ」は二つを対比する表現で、農業と地場産業の両方に取り組むという文意に合わない"], "ex": "その歌手は音楽活動<b>にとどまらず</b>、映画や小説の分野でも活躍している。"},
"36431": {"point": "「〜を受けて」は「〜の影響を受けて・〜に応じて」という意味で、ある出来事をきっかけに次の行動が起こることを表す。都心部の賃貸料が高騰した影響で、多くの店舗が販売価格を値上げした、という文意に合う。", "opts": ["を限りに：「〜を限りに」は「今日を限りに」のように「〜を最後に」の意で、時を表す語に付く。文意に合わない", "をへて：「〜を経て」は「〜を通って・〜の過程を通って」の意で、影響を受けて行動するという意味にならない", "を問わず：「〜を問わず」は「〜に関係なく」の意で、原因と結果の関係を表せない", ""], "ex": "台風の接近<b>を受けて</b>、多くの学校が休校を決めた。"},
"36432": {"point": "「〜を機に」は「〜をきっかけにして」という意味で、それを境に新しいことを始めるときに使う。病気で入院したことをきっかけに、健康に注意するようになった、という文意に合う。", "opts": ["を限りに：「〜を限りに」は「〜を最後に（終わりにする）」の意で、新しく何かを始める文意に合わない", "をものともせず：「〜をものともせず」は「困難を問題にせず立ち向かう」の意で、文意に合わない", "", "をよそに：「〜をよそに」は「周囲の心配をよそに」のように「〜を気にかけずに」の意で、文意に合わない"], "ex": "結婚<b>を機に</b>、たばこをやめた。"},
"36433": {"point": "「〜を経て」は「〜を通って・〜の過程を通って」という意味。現在日本で使われている漢字は、長い年月という過程を通って、さまざまな日本式の改良が加えられたものだ、という文意に合う。", "opts": ["を問わず：「〜を問わず」は「〜に関係なく」の意で、時間の経過を表せない", "にかまけて：「〜にかまけて」は「〜に気を取られてほかをおろそかにする」の意で、文意に合わない", "", "に照らして：「〜に照らして」は「〜を基準にして」の意で、時間の経過を表せない"], "ex": "彼は営業部長<b>を経て</b>、社長に就任した。"},
"36434": {"point": "動詞の連用形に「は」を付けて「〜はしない」とすると、否定を強める言い方になる。「二度と」と結びつき、酒に酔って迷惑をかけた彼は、もう二度と酒を飲むことはしないだろう、という意味になる。", "opts": ["飲む：「〜はしない」で否定を強めるときは連用形を使う。辞書形の「飲むはしない」という形はない", "飲んだ：た形に「は」を付けて「〜はしない」とする形はなく、「飲んだはしない」とは言わない", "", "飲んで：「〜てはしない」という形はない。「〜はしない」の前は連用形になる"], "ex": "あんな怖い思いをしたのだから、二度とあの山には登り<b>はしない</b>。"},
"36435": {"point": "「AべくしてA」は同じ動詞を繰り返し、「そうなるのが当然の状況で、そのとおりに〜した」という意味を表す。監督の選手起用に問題があったので、あの試合は負けるのが当然で、実際にそのとおり負けたということ。", "opts": ["勝つべくして：「勝つべくして勝った」のように同じ動詞を繰り返す形なので、後の「負けた」と一致しない。選手起用に問題があったという前半とも合わない", "", "負けたべくして：「べく」は辞書形に付くので、た形の「負けた」には付かない", "勝てるべくして：「勝てる」では後の「負けた」と動詞が一致せず、「AべくしてA」の形にならない。選手起用に問題があったという前半とも合わない"], "ex": "準備を重ねてきた彼らは、勝つ<b>べくして</b>勝ったのだ。"},
"36436": {"point": "「辞書形＋ばかりになっている」は「準備がすべて整い、あとは〜するだけの状態だ」という意味。勉強は十分したので、残っているのは試験日を待つことだけだという状態を表し、「あとは」と呼応する。", "opts": ["待たないばかりになっている：「ばかりになっている」は肯定の辞書形に付く形で、否定形の「待たない」には付かない", "", "待たないほどになっている：「ほど」は程度を表し、否定形と合わせても「あとは〜するだけ」という準備完了の意味にならない", "待つほどになっている：「〜ほどになっている」は「〜するくらいの程度になった」という意味で、「あとは」と呼応せず、準備が整った状態を表せない"], "ex": "荷造りも済み、あとは出発する<b>ばかりになっている</b>。"},
"36437": {"point": "「辞書形＋べくもない」は「とても〜できない、〜する余地もない」という意味の書き言葉。東京で庭付きの一戸建てに住むような贅沢は、とても望めないという気持ちを表す。", "opts": ["", "にはあたらない：「〜にはあたらない」は「〜するほどのことではない（驚くにはあたらない）」という意味で、望むことが不可能だという意味にならない", "までもない：「〜までもない」は「わざわざ〜する必要もない（言うまでもない）」という意味で、望んでもかなわないという内容を表せない", "だけましだ：「〜だけましだ」は「悪い状況だが、〜だけはまだよい」という意味で、「贅沢は望む」に付けても意味が通らない"], "ex": "彼が本当は何を考えていたのか、今となっては知る<b>べくもない</b>。"},
"36438": {"point": "「〜をおして」は「病気・困難・反対などを無理に押し切って〜する」という意味。お祖母さんは体が不自由だったが、その困難を押し切って発表会に来てくれたことを表す。", "opts": ["口実に：「〜を口実に」は「〜を言い訳にして」という意味で、来ない理由になるはずの不自由な体を、来てくれたことの理由にするのは不自然", "限りに：「〜を限りに」は「〜を最後に（今日を限りに）」という意味で、時を表す語に付く。「体」には合わない", "", "おいて：「〜をおいて」は「〜以外に（彼をおいて適任者はいない）」という意味で、後に「ほかに〜ない」が続く。この文には合わない"], "ex": "父は足の痛み<b>をおして</b>、私の結婚式に出席してくれた。"},
"36439": {"point": "「名詞＋めく」は「〜らしい様子になる、〜の感じが出てくる」という意味で、「春めく」「秋めく」の形でよく使う。「春めいてまいりました」で、だんだん春らしくなってきたという改まった手紙のあいさつになる。", "opts": ["らしく：「春らしく」は連用形なので、後に「なって」がないと「まいりました」につながらない（春らしくなってまいりました）", "ぎみに：「〜ぎみ」は「少し〜の傾向がある（風邪ぎみ・遅れぎみ）」という意味で、好ましくない状態に使うことが多い。「春ぎみ」とは言わない", "っぽく：「〜っぽい」は話し言葉的で、手紙の改まったあいさつに合わない。また後に「なって」がないと「まいりました」につながらない", ""], "ex": "庭の梅がほころび始め、日差しもようやく春<b>めいて</b>きた。"},
"36440": {"point": "「〜はさておき」は「〜のことはひとまず置いておいて」という意味で、より重要な別の事柄を取り上げるときに使う。展示では製品価格の話は後回しにして、まず性能に注目してほしいという気持ちを表す。", "opts": ["", "及ばず：「〜は言うに及ばず」の形で「〜は言うまでもなく」という意味になる。「価格は及ばず」だけでは意味が通らない", "まだしも：「〜はまだしも」は「〜ならまだ許せるが（後のほうはひどい）」という意味で、後に否定的な評価が続く。性能に注目してほしいという文に合わない", "おいて：「〜をおいて」は「〜以外に（彼をおいて適任者はいない）」という意味で、後に「ほかに〜ない」が続く。ひとまず脇に置く意味は表せない"], "ex": "冗談<b>はさておき</b>、そろそろ本題に入りましょう。"},
"36441": {"point": "「連用形＋はしない」は動詞を「は」で取り立てて否定を強める形。「焦りはしなかった」は「焦ったりはしなかった」という意味で、事態を予想していたので、それほど焦らなかったことを表す。", "opts": ["", "ならなかった：「連用形＋は」の後には「する」の否定が続き、「焦りはならなかった」という言い方はない", "行かなかった：「焦りは行かなかった」は意味をなさない。「連用形＋は」の後には「しない」が必要", "やまなかった：「焦りはやまなかった」では「焦りが続いた」という意味になり、予想していたので落ち着いていたという文脈と逆になる"], "ex": "少し失敗したくらいで、彼はあきらめ<b>はしない</b>だろう。"},
"36442": {"point": "「辞書形＋べくもない」は「とても〜できない」という意味。「比べるべくもない」は「差が大きすぎて比べることなどできない」ということで、ここのりんごの香りと味わいが他産地のものよりはるかに優れていることを表す。", "opts": ["", "べからざる：「〜べからざる」は「〜してはならない（欠くべからざる人物）」という意味の書き言葉で、後に名詞が来る。文末には使えない", "べきだ：「比べるべきだ」は「比べたほうがいい」という意味になり、りんごが優れていることを強調する文に合わない", "べきことだ：「〜べきことだ」は「当然すべきことだ」という意味で、比べることが義務のようになり、文意に合わない"], "ex": "素人の私の料理など、プロの料理人の味とは比べる<b>べくもない</b>。"},
"36443": {"point": "「〜はさておき」は「〜はひとまず置いて」という意味で、別の事柄を優先して述べるときに使う。栄養のことは後回しにして、まずは味の面で気に入ったという文で、後の「まずは」とも呼応している。", "opts": ["はおろか：「〜はおろか」は「〜はもちろん（もっと程度の高い〜も）」という意味で、後に「〜も〜ない」などが続く（漢字はおろか、ひらがなも書けない）。この文に合わない", "", "からには：「〜からには」は「〜以上は（当然〜）」という意味で、活用語に付き、後に決意や義務が続く。「栄養のことからには」とは言わない", "といえども：「〜といえども」は「〜であっても」という逆接で、「栄養のことといえども」では意味が通らない"], "ex": "値段<b>はさておき</b>、このレストランの料理は見た目が美しい。"},
"36444": {"point": "「名詞＋めく」は「〜らしくなる、〜の感じが表れる」という意味。朝晩の気温が下がり、すっかり秋らしくなってきたという季節の変化を表す。「めっきり」は変化がはっきりしている様子。", "opts": ["らしく：「秋らしく」は連用形なので、後に「なって」がないと「きました」につながらない（秋らしくなってきました）", "ともなって：「〜にともなって」（〜につれて）は「に」に付く形で、「秋ともなってきました」という言い方はない", "きわまって：「〜きわまる」は「この上なく〜だ（失礼きわまる）」という意味で、季節の変化を表せない", ""], "ex": "街路樹の葉が色づき始め、街並みも秋<b>めいて</b>きた。"},
"36445": {"point": "「AべくしてA」は「そうなるのが当然の状況で、そのとおりに〜した」という意味。前からの警告を無視していたのだから、この災害は起こるのが当然で、実際に起こったのだという判断を表す。", "opts": ["べからず：「〜べからず」は「〜してはいけない（立ち入るべからず）」という禁止を表し、掲示や文末に使う。後に動詞を続けられない", "べき：「〜べき」は後に名詞が来て「すべき〜」となる形で、「起こるべき起こった」とは言えない", "", "べく：「〜べく」は「〜するために」という目的を表し、意志的な動作に使う。「災害が起こる」は意志的な行為ではないので合わない"], "ex": "毎日誰よりも練習していた彼女は、優勝する<b>べくして</b>優勝したと言える。"},
"36446": {"point": "「辞書形＋ばかりになっている」は「準備が整い、あとは〜するだけの状態だ」という意味。原稿は既に書き上げたので、残っているのは出版することだけだという状態を表す。", "opts": ["", "するほど：「〜ほどになっている」は程度を表し、「あとは〜するだけ」という準備完了の意味にならない", "しないばかり：「ばかりになっている」は肯定の辞書形に付く。「しないばかり」では意味が通らない", "しないほど：否定形に「ほど」が付いても準備完了の意味にならず、「あとは」とも合わない"], "ex": "料理はすべてテーブルに並び、あとは乾杯する<b>ばかりになっている</b>。"},
"36447": {"point": "「〜を受けて」は「〜の影響を受けて、〜に応じて」という意味で、ある出来事や状況をきっかけに次の動きが起こることを表す。景気が回復傾向にあることの影響で、ボーナスの支給額が増えると見込まれている。", "opts": ["を経て：「〜を経て」は「〜という過程・段階を通って（予選を経て）」という意味で、景気の回復傾向は通過する段階ではないので合わない", "を押して：「〜をおして」は「困難などを無理に押し切って」という意味で、景気の回復は押し切るべき障害ではない", "", "をめぐって：「〜をめぐって」は「〜について（議論・対立する）」という意味で、後に「議論が起こる」などが続く。ボーナスが増える原因を表せない"], "ex": "台風の接近<b>を受けて</b>、多くの学校が休校を決めた。"},
"36448": {"point": "「〜を経て（へて）」は「〜という過程・段階を通って」という意味。予選という段階を通って選ばれた12チームが、決勝大会に進むという流れを表す。", "opts": ["", "よそに：「〜をよそに」は「〜を気にせず、無関係に（親の心配をよそに）」という意味で、予選を通過して選ばれるという流れに合わない", "おして：「〜をおして」は「病気や反対などを無理に押し切って」という意味で、予選は押し切る困難ではないので合わない", "かまわず：「〜にかまわず」は「〜を気にしないで」という意味で、予選を通って選ばれるという流れを表せない"], "ex": "東京から名古屋<b>を経て</b>大阪へ向かう。"},
"36449": {"point": "「〜をおして」は「病気・怪我・反対などを無理に押し切って〜する」という意味。その選手は怪我をしていたが、無理をして大会に出場したことを表し、後の「結果はかんばしくなかった」にもつながる。", "opts": ["をおいて：「〜をおいて」は「〜以外に（彼をおいて適任者はいない）」という意味で、後に「ほかに〜ない」が続く。この文には合わない", "", "につけても：「〜につけても」は「〜に関連して、〜するたびに（それにつけても）」という意味で、「怪我につけても出場した」では意味が通らない", "にてらして：「〜に照らして」は「〜を基準にして（法律に照らして）」という意味で、怪我を基準にするのは文意に合わない"], "ex": "社長は病<b>をおして</b>、新工場の完成式典に出席した。"},
"36450": {"point": "「〜を機に」は「〜をきっかけ・よい機会として、新しいことを始める」という意味。開業40年を迎えることをきっかけに、最新型車両を導入するという文脈に合う。", "opts": ["を問わず：「〜を問わず」は「〜に関係なく（年齢を問わず）」という意味で、「開業40年を迎えるのを問わず」では意味が通らない", "をよそに：「〜をよそに」は「〜を気にかけず、無視して（周囲の心配をよそに）」という意味で、記念の節目をきっかけにする文脈に合わない", "を口実に：「〜を口実に」は「〜を言い訳にして」という意味で、多くはよくない行為の理由づけに使う。新車両の導入を説明する文に合わない", ""], "ex": "結婚<b>を機に</b>、長年勤めた会社を退職した。"},
"36901": {"point": "「昔ながらの」は「昔のままの、昔から変わらない」という意味で、後の名詞を修飾する。後の「そのまま残っており」と合い、昔から変わらない町並みや素朴な雰囲気が残っていることを表す。", "opts": ["かぎりの：「〜かぎりの」は「できるかぎりの努力」「その場かぎりの」のように使い、「昔かぎりの」とは言わない", "ならではの：「〜ならではの」は「〜だけが持つ、〜特有の（この店ならではの味）」という意味で、普通は人や場所などに付く。「昔のまま」という意味は表せない", "", "ならの：「昔ならの」という言い方はない。「昔なら」は「昔だったら」という仮定を表し、名詞を修飾する形にならない"], "ex": "この店では今も昔<b>ながらの</b>製法でみそを作っている。"},
"36902": {"point": "「〜ときたら」は身近な人や物事を話題にして、それに対する不満やあきれた気持ちを述べるときに使う。近頃の若者を話題にし、後の「ちっとも席を譲ろうとしない」という非難につながる。", "opts": ["というより：「〜というより」は「〜と言うよりもむしろ（暑いというより痛い）」という比較の表現で、不満の対象を話題として示せない", "とくれば：「AとくればB」は「夏とくればビールだ」のように、ある話題から当然連想されるものを挙げる表現で、不満を述べる文に合わない", "とあれば：「〜とあれば」は「〜という事情なら」という条件を表し、後に話し手の意志や判断が続く。不満の対象を示す文に合わない", ""], "ex": "うちの息子<b>ときたら</b>、毎日ゲームばかりして全然勉強しない。"},
"36903": {"point": "「名詞＋次第では」は「〜によっては」という意味で、その内容によって結果が変わることを表す。頼み方によっては、あの人も手伝ってくれる可能性があるということで、文末の「かもしれない」と合う。", "opts": ["", "次第には：「次第には」という言い方はない。「〜によっては」の意味には「次第では」を使う", "次第に：副詞の「次第に」は「だんだん（次第に暗くなる）」という意味で、名詞の後に付けて条件を表すことはできない", "次第も：「次第も」という言い方はなく、意味をなさない"], "ex": "天候<b>次第では</b>、明日の試合は中止になるかもしれない。"},
"36904": {"point": "「〜をかぎりに」は「〜を最後に、〜でそれまで続いたことを終わりにする」という意味。新しいマンションに移るので、今月を最後に、長年住み続けてきた家ともお別れになるということ。", "opts": ["をもとに：「〜をもとに」は「〜を材料・根拠にして（事実をもとに）」という意味で、時を表す「今月」には合わない", "", "をかわきりに：「〜を皮切りに」は「〜を始まりとして次々に（東京を皮切りに全国で）」という意味で、「お別れ」という終わりの意味と逆になる", "をおして：「〜をおして」は「困難などを無理に押し切って」という意味で、「今月」には付かない"], "ex": "今日<b>を限りに</b>、たばこをきっぱりやめることにした。"},
"36905": {"point": "「〜とあれば」は「〜という事情・理由なら」という意味で、後に「その理由なら〜する・〜しなければならない」という判断や意志が続く。相手が会社の大切な取引先なので、細心の注意を払う必要があるということ。", "opts": ["", "をもって：「〜をもって」は「〜で（書面をもって通知する）」「〜を最後に（本日をもって）」という意味で、条件を表せない", "といえども：「〜といえども」は「〜であっても」という逆接で、後に予想に反する内容が来る。「大切な取引先であっても注意を払う」では文意が通らない", "というより：「〜というより」は「〜と言うよりもむしろ」という比較の表現で、この文に合わない"], "ex": "子どもの将来のため<b>とあれば</b>、どんな苦労もいとわない。"},
"36906": {"point": "「〜の至り」は「この上なく〜だ」という意味の改まった表現で、「恐縮の至り」「光栄の至り」のように感情を表す漢語に付く。遠くまで来てもらったことに対する、この上ない恐縮の気持ちを表す。", "opts": ["ずくめです：「〜ずくめ」は「〜ばかり（黒ずくめ・いいことずくめ）」という意味で、名詞に直接付く。「恐縮のずくめ」とは言わない", "ほどです：「恐縮のほどです」という言い方はなく、「この上なく」という意味も表せない", "", "はずです：「〜はずだ」は「当然そうだろう」という推測を表し、自分の気持ちを述べるお礼のあいさつに合わない"], "ex": "このような賞をいただき、光栄<b>の至り</b>です。"},
"36907": {"point": "「〜からなる」は「〜で構成されている」という意味で、全体を作っている要素を示す。核家族が、父母とその未婚の子供で構成された家族であることを説明している。", "opts": ["", "となる：「〜となる」は「〜に変化する、結果として〜になる」という意味で、構成要素を表せない", "もなる：「〜にもなる」のように「に」が必要な形で、構成の意味も表せない", "でもなる：「でもなる」という言い方はなく、構成を表す意味にもならない"], "ex": "日本の国会は、衆議院と参議院<b>からなる</b>。"},
"36908": {"point": "「〜だにしない」は「少しも〜しない」という意味の書き言葉で、「予想だにしない」「想像だにしない」の形でよく使う。無名の新人選手が優勝するとは全く予想していなかったという驚きを表す。", "opts": ["のみ：「〜のみ」は「〜だけ」という限定を表し、「予想のみしなかった」では意味が通らない", "ばかり：「〜ばかり」は「〜だけ」という意味で、「予想ばかりしなかった」では意味が通らない", "", "まで：「予想までしなかった」は「予想するところまではしなかった」という意味になり、全く予想していなかったという驚きを表せない"], "ex": "衛兵は暑さの中でも微動<b>だにしない</b>。"},
"36909": {"point": "「〜ずじまい」は「結局〜しないで終わってしまう」という意味で、残念な気持ちを表す。ない形の「ない」を「ず」に変えて付ける（わからない→わからずじまい）。いろいろ調査したが、結局事故の原因はわからないまま終わったということ。", "opts": ["わかる：「じまい」は「ず」に付いて「〜ずじまい」となる。辞書形の「わかる」には付かない", "", "わからぬ：「ぬ」は「ない」の古い形だが、「〜ずじまい」は「ず」の形でしか使わない", "わからない：「ない」の形には付かず、「わからずじまい」としなければならない"], "ex": "旅行中は忙しくて、お土産を買わ<b>ずじまい</b>だった。"},
"36910": {"point": "「〜てこそ」は「〜して初めて（ある結果が得られる）」という意味で、後の「はじめて」と合わせて強調している。自然はあって当然だと思っていたが、失って初めてその大切さが分かったということ。", "opts": ["失うからには：「〜からには」は「〜する以上は（当然〜）」という意味で、後に決意や義務が続く。「はじめて〜分かる」と合わない", "失うからとて：「〜からとて」は「〜からといって（必ずしも〜ない）」という意味で、後に否定が続くことが多い。この文に合わない", "失ってまで：「〜てまで」は「そこまでの犠牲を払って」という意味で、後に「〜したくない」などが続くことが多い。「はじめて分かる」と合わない", ""], "ex": "自分が親になっ<b>てこそはじめて</b>、親の苦労が分かるものだ。"},
"36911": {"point": "「〜ことだし」は「〜ので」という意味で、理由を軽く挙げて、後に話し手の判断や提案を述べる会話的な表現。もう終わったことなので、くよくよしても仕方がないという慰めの判断につながる。", "opts": ["ことにも：「〜ことにも」は「〜ことに対しても」という意味になり、理由を表せない", "ことでも：「〜ことでも」は「〜ことであっても」という意味になり、理由を表せない", "ことから：「〜ことから」は「〜ことを根拠に（〜と判断される）」という由来・根拠を表す書き言葉的な表現で、会話で慰める文に合わない", ""], "ex": "雨も降ってきた<b>ことだし</b>、今日はもう帰りましょう。"},
"36912": {"point": "「名詞＋まみれ」は「汗・泥・血などが体や物の表面いっぱいについている」という意味。重い荷物を運んでいるうちに、体中が汗でびっしょりになった様子を表す。", "opts": ["", "ばかり：「〜ばかり」は「〜だけ」という意味で、「汗ばかりになる」では表面いっぱいについている様子を表せない", "ずくめ：「〜ずくめ」は「〜ばかり（黒ずくめ・いいことずくめ）」という意味で、汗が体についている様子には使わない", "のみ：「〜のみ」は「〜だけ」という限定の書き言葉で、「汗のみになる」では意味が通らない"], "ex": "子どもたちは泥<b>まみれ</b>になって遊んでいた。"},
"36913": {"point": "「〜ますように」は祈りや願いを表す文末の形で、「どうか」と一緒によく使われる。海外旅行中の子どもが無事に帰ってくることを心から願う気持ちを表す。", "opts": ["ものを：「〜ものを」は「〜のに（すればよかったものを）」という不満や残念な気持ちを表し、願いを表せない", "", "ことか：「〜ことか」は「どんなに〜ことか」の形で感嘆を表し、願いの「どうか」と合わない", "とは：「〜とは」は「〜なんて」という驚きを表し、願いを表せない"], "ex": "今年も家族みんなが元気で過ごせます<b>ように</b>。"},
"36914": {"point": "「〜べく」は「〜するために」という目的を表す書き言葉で、「する」は「すべく」となる。インフルエンザの感染経路を明らかにするために、調査が行われたという文に合う。", "opts": ["", "すべからざる：「〜べからざる」は「〜してはならない（欠くべからざる）」という意味で、名詞を修飾する。目的を表せない", "するはおろか：「〜はおろか」は「〜はもちろん」という意味で、後に「〜も〜ない」などが続く。目的を表せない", "しまいと：「〜まいと」は「〜しないように」という意味で、「明らかにしまいと」では明らかにしないためとなり、調査の目的と逆になる"], "ex": "夢を実現<b>すべく</b>、彼は毎日努力を続けている。"},
"36915": {"point": "「〜に越したことはない」は「〜のほうがいい、〜が一番だ」という意味。締め切りは明日の午後5時だが、早めに出せればそれが一番いいということで、「それ」は早めに出すことを指す。", "opts": ["かいがない：「〜かいがない」は「〜した効果がない（努力したかいがない）」という意味で、「それにかいがない」とは言わない", "過言ではない：「〜と言っても過言ではない」は「〜と言っても言い過ぎではない」という意味で、「に」には続かない", "", "すぎない：「〜にすぎない」は「ただ〜だけだ」という意味で、早めに出すことのよさを表せない"], "ex": "旅行先では、用心する<b>に越したことはない</b>。"},
"36916": {"point": "「〜ごとく」は「〜のように」という意味の書き言葉で、「ご承知のごとく」は「すでにご存じのように」という改まった表現。創立50周年を述べる式典などの改まった場面に合う。", "opts": ["なりに：「〜なりに」は「〜にふさわしい程度で（子どもなりに考えた）」という意味で、「ご承知のなりに」とは言わない", "きり：「〜きり」は「〜だけ（二人きり）」や「〜したまま（行ったきり）」という意味で、「ご承知のきり」とは言わない", "", "まま：「〜のまま」は「その状態が変わらない」という意味で、「ご承知のまま」では「ご存じのように」という意味にならない"], "ex": "前回の会議で述べた<b>ごとく</b>、計画は来年度から実施されます。"},
"36917": {"point": "「〜にかぎったことではない」は「〜だけではない、〜に限らない」という意味。敬語を間違えるのは子供だけではなく、大人にもよくあることだという内容を表す。", "opts": ["にあるまじきことだ：「〜にあるまじき」は「〜として決してあってはならない（教師にあるまじき行為）」という意味で、子供が敬語を間違えることを強く非難する文脈ではないので合わない", "", "というものではない：「〜というものではない」は「必ずしも〜とは言えない（高ければいいというものではない）」という意味で、「子供というものではない」では意味が通らない", "に越したことはない：「〜に越したことはない」は「〜のほうがいい」という意味で、「子供に越したことはない」では意味が通らない"], "ex": "彼が約束の時間に遅れるのは、今日<b>にかぎったことではない</b>。"},
"36918": {"point": "「〜ずにはすまない」は「〜しないでは済まされない、〜しないわけにはいかない」という意味。人のものを壊してしまったのだから、弁償しないままでは済まされないということ。", "opts": ["にも：「せずにもすまない」という言い方はない。「〜ずにはすまない」の形で「は」が必要", "とも：「〜ずとも」は「〜なくても（言わずとも分かる）」という意味で、「弁償せずともすまない」では意味が通らない", "とは：「せずとはすまない」という言い方はない。「〜ずにはすまない」と「に」と「は」の両方が必要", ""], "ex": "大切な会議を無断で欠席したのだから、上司に謝ら<b>ずにはすまない</b>だろう。"},
"36919": {"point": "「〜をふまえて」は「〜を前提・判断の根拠にして」という意味で、後に「検討する・議論する」などが続く。市をとりまく現状を前提にして、開発方針を検討していく必要があるということ。", "opts": ["をかぎりに：「〜を限りに」は「〜を最後に（今日を限りに）」という意味で、時を表す語に付く。「現状を限りに」では意味が通らない", "", "をこめて：「〜をこめて」は「〜（気持ち）を入れて（愛をこめて）」という意味で、気持ちを表す語に付く。「現状」には合わない", "をめざして：「〜をめざして」は「〜を目標にして」という意味で、現状を目標にして方針を検討するのは文意に合わない"], "ex": "前回の反省<b>をふまえて</b>、今年のイベントの計画を立てた。"},
"36920": {"point": "「AなりBなり」は「AでもBでも（何でもいいから）」と例を挙げて選ばせる表現で、後に提案・助言・命令が続く。映画でもショッピングでもいいから、何かをして気分転換を図ったほうがいいという助言に合う。", "opts": ["なら / なら：「AならBなら」と例を並べて選ばせる形はなく、後の「して」にもつながらない", "", "たら / たら：「たら」はた形に付く（見たら）ので辞書形の「見る」「する」には付かず、例を並べて選ばせることもできない", "も / も：「AもBも」は「両方とも」という意味で、動詞の辞書形に直接付けて「見るもするもして」とは言わない。選択の意味も表せない"], "ex": "分からないことがあれば、先生に聞く<b>なり</b>辞書で調べる<b>なり</b>しなさい。"},
"36451": {"point": "「辞書形＋べくもない」は「とても〜できない」という意味の書き言葉。予算がこれほど削られてしまっては、新しい事業の成功はとても期待できないという判断を表す。", "opts": ["べきだ：「期待するべきだ」は「期待したほうがいい」という意味で、予算が削られたという悪い条件と合わない", "", "べきではない：「〜べきではない」は「〜してはいけない」という義務・禁止の判断で、「こんなに予算が削られては」に続く「とても〜できない」という不可能の意味を表せない", "べからざるものだ：「〜べからざる」は「〜してはならない（欠くべからざる）」という禁止の意味で、不可能の意味を表せない"], "ex": "地方の小さな研究室では、最新の設備など望む<b>べくもない</b>。"},
"36452": {"point": "「〜はさておき」は「〜はひとまず置いて」という意味で、ある事柄を後回しにして別の事柄を述べるときに使う。ダイエット効果があるかどうかはひとまず置いて、リラックス効果はかなりあるという文に合う。", "opts": ["もとに：「〜をもとに」は「〜を材料・根拠にして」という意味で、「を」に付く。「効果はもとに」とは言わない", "よそに：「〜をよそに」は「〜を気にせず（周囲の心配をよそに）」という意味で、「を」に付く。「効果はよそに」とは言わない", "", "問わず：「〜を問わず」は「〜に関係なく（男女を問わず）」という意味で、対になる語や幅のある語に付く。ダイエット効果をひとまず置くという意味にならない"], "ex": "結果<b>はさておき</b>、最後まであきらめずに走りきったことを評価したい。"},
"36453": {"point": "「〜を経て」は「〜という時間・過程を通って」という意味。50年という長い年月がかかって、ようやく再開発ビルが完成したことを表し、「ようやく」とも合う。", "opts": ["", "を皮切りに：「〜を皮切りに」は「〜を始まりとして次々に（東京を皮切りに全国で公演する）」という意味で、年月の経過を表せない", "を控えて：「〜を控えて」は「〜が近くに迫っている（試験を控えて）」という意味で、過ぎた50年という年月には合わない", "を限りに：「〜を限りに」は「〜を最後に（今日を限りに）」という意味で、長い年月をかけて完成したという文意に合わない"], "ex": "十年に及ぶ研究<b>を経て</b>、新しい薬がついに完成した。"},
"36454": {"point": "「連用形＋はしない」は動詞の否定を「は」で取り立てて強める形で、「行きはしない」は「行ったりは決してしない」という意味。食中毒を起こした店には、さすがに誰も行かないということを強く表す。", "opts": ["", "行っては：「行ってはしない」という言い方はない。「連用形＋はしない」なので、連用形の「行き」が必要", "行っても：「行ってもしない」という言い方はなく、意味が通らない", "行こう：意向形には「〜とする」の「と」が必要で、「行こうしない」という言い方はない"], "ex": "一度裏切られた相手を、二度と信じ<b>はしない</b>。"},
"36455": {"point": "「AべくしてA」は「当然そうなる状況で、そのとおりに〜した」という意味で、同じ動詞を繰り返し、「べく」の前は辞書形になる。明らかに勉強不足だったので、試験に落ちるのは当然で、そのとおり落ちたということ。", "opts": ["落ちた：「べく」は辞書形に付くので、た形の「落ちた」には付かない", "落とされる：受身形にすると後の「落ちた」と動詞が一致しない。「AべくしてA」は同じ動詞を繰り返す", "", "落とした：他動詞「落とす」のた形で、辞書形でもなく、後の「落ちた」とも一致しない"], "ex": "安全点検を怠っていたのだから、あの事故は起きる<b>べくして</b>起きたのだ。"},
"36456": {"point": "「名詞＋めいた＋名詞」は「〜のような、〜らしい感じの」という意味。今回のことについて、弁明や言い訳のように受け取られることは一切したくないという気持ちを表す。", "opts": ["ながらの：「〜ながらの」は「昔ながらの」「生まれながらの」のように限られた語に付き、「〜のままの」という意味。「言い訳ながらの」とは言わない", "", "まみれの：「〜まみれ」は「汗・泥・借金などにすっかり覆われている」という意味で、「〜のようなもの」という意味は表せない", "きらいの：「〜きらいがある」は「〜しがちだ（よくない傾向がある）」という意味で、「きらいがある」の形で使う。「言い訳きらいの」では意味が通らない"], "ex": "彼の言葉には、どこか皮肉<b>めいた</b>響きがあった。"},
"36457": {"point": "「〜をおして」は「反対や困難を無理に押し切って〜する」という意味。周りの人が反対したが、それを押し切って今回の選挙に出馬することを決めたということ。", "opts": ["をもって：「〜をもって」は「〜で（手段）」「〜を最後に（本日をもって）」という意味で、「反対をもって」では意味が通らない", "をおいて：「〜をおいて」は「〜以外に（彼をおいて適任者はいない）」という意味で、後に「ほかに〜ない」が続く。この文に合わない", "", "をもとに：「〜をもとに」は「〜を根拠・材料にして」という意味で、反対を根拠に出馬するのは意味が通らない"], "ex": "彼女は家族の反対<b>をおして</b>、一人で海外に留学した。"},
"36458": {"point": "「辞書形＋ばかりになっている」は「準備が整い、あとは〜するだけの状態だ」という意味。新しい法案はすでに準備ができていて、残るのは議会での承認を得ることだけだという状態を表す。", "opts": ["得ないほどになっている：否定形に「ほど」が付いても準備完了の意味にならず、意味が通らない", "得ないばかりになっている：「ばかりになっている」は肯定の辞書形に付く形で、否定形の「得ない」には付かない", "得るほどになっている：「〜ほどになっている」は「〜する程度になった」という意味で、「あとは〜するだけ」という準備完了の状態を表せない", ""], "ex": "新しい店の内装も完成し、あとは開店の日を迎える<b>ばかりになっている</b>。"},
"36459": {"point": "「〜を受けて」は「〜に応じて、〜をきっかけとして」という意味で、指示・要望・結果などの後に、それに応じた行動が続く。上司の指示に応じて、来週の会議の資料を作成しているということ。", "opts": ["", "を皮切りに：「〜を皮切りに」は「〜を始まりとして次々に」という意味で、指示に応じて作業をするという意味にならない", "をピークに：「〜をピークに」は「〜を最高点として（その後減っていく）」という意味で、数量の変化を表す文に使う", "を通して：「〜を通して」は「〜を仲介・手段として（友人を通して知り合う）」という意味で、指示に応じて資料を作るという意味にならない"], "ex": "住民からの要望<b>を受けて</b>、市は公園に街灯を増やすことにした。"},
"36460": {"point": "「〜を機に」は「〜をきっかけとして、新しいことを始める」という意味。子供が小学生になったことをきっかけに、再び働き始める女性が多いという文に合う。", "opts": ["を中心に：「〜を中心に」は「〜を真ん中・主な対象として」という意味で、きっかけを表せない", "をはじめ：「〜をはじめ」は「〜を代表的な例として（東京をはじめ全国で）」という意味で、きっかけを表せない", "", "をよそに：「〜をよそに」は「〜を気にせず（親の心配をよそに）」という意味で、子供の成長をきっかけに働き始めるという文意に合わない"], "ex": "定年退職<b>を機に</b>、夫婦で田舎に移り住むことにした。"},
"37001": {"point": "「〜にしたら」は「〜の立場からすれば」という意味で、人を表す名詞に付き、その人の気持ちや考えを推し量って述べる。専門家の立場からすれば分かりやすく説明したつもりでも、素人の私には理解できなかったという対比を表す。", "opts": ["", "によれば：「〜によれば」は「〜の話では」という情報の出所を表し、後に「〜そうだ・〜らしい」などの伝聞が続く。専門家の立場を表せない", "にいったら：「にいったら」という言い方はない。立場を表すには「〜にしたら」「〜にすれば」を使う", "に見れば：「に見れば」という形はない。視点を表すには「〜から見れば」とする必要がある"], "ex": "毎日忙しく働いている母<b>にしたら</b>、休日くらいゆっくり休みたいだろう。"},
"37002": {"point": "「連用形＋きれない」は「量が多くて、完全に〜することができない」という意味。マンガをたくさん借りたので一日では全部読めないと思ったが、実際は一晩で全部読んでしまったという流れに合う。", "opts": ["読みかける：「〜かける」は「〜し始めて途中である（読みかけの本）」という意味で、「一日では〜と思った」という予想に合わない", "読みつづける：「〜つづける」は「ずっと〜する」という継続の意味で、量が多くて読み終わらないという予想を表せない", "", "読みかねない：「〜かねない」は「〜するおそれがある（事故になりかねない）」という意味で、望ましくないことの可能性に使う。文意に合わない"], "ex": "こんなにたくさんの料理は、二人では食べ<b>きれない</b>。"},
"37003": {"point": "「〜というものではない」は「必ずしも〜とは言えない」という意味で、一般的な考えを部分的に否定する。会議はただ出席していればいいわけではなく、何を言うかが大切だということで、「なく」で後の文に続く。", "opts": ["", "としたものではなく：「〜としたものではなく」という言い方はしない。「必ずしも〜ではない」という部分否定は「というものではない」で表す", "というものであり：肯定の形では「ただ出席していればいい」ことを認めることになり、後の「何を言うかが大切だ」と矛盾する", "としたものであり：「としたもの」という言い方は普通せず、肯定の形では後の「何を言うかが大切だ」とも矛盾する"], "ex": "高い薬を飲めば病気が早く治る<b>というものではない</b>。"},
"37004": {"point": "「〜か否か（かいなか）」は「〜かどうか」という意味の書き言葉。生産設備が法律の基準に適合するかどうかについて検査するという文で、後の「について」にもつながる。", "opts": ["やいなや：「〜やいなや」は「〜するとすぐに（ドアを開けるやいなや）」という意味で、後に別の動作が続く。「〜について」にはつながらない", "", "なり：「〜なり」は「〜するとすぐ（家に帰るなり寝た）」という意味で、後に動作が続く。「〜かどうか」の意味を表せない", "きり：「〜きり」は「〜したまま（出かけたきり）」や「〜だけ」という意味で、「〜かどうか」の意味を表せない"], "ex": "彼が会議に参加する<b>か否か</b>は、まだ分からない。"},
"37005": {"point": "「連用形＋つつある」は「変化がだんだん進んでいる」という意味の書き言葉。急激な経済成長と人口の増加によって、都市部の住宅事情がだんだん悪くなってきているという変化を表す。", "opts": ["なり次第だ：「連用形＋次第」は「〜したらすぐに（着き次第連絡する）」という意味で、後に行動が続く。変化が進んでいることは表せない", "なりかねる：「〜かねる」は「〜することが難しい（賛成しかねる）」という意味で、話し手の判断に使う。住宅事情の変化を表せない", "", "なりぬいた：「〜ぬく」は「最後まで〜する（走りぬく）」という意味で、「悪くなりぬいた」とは言わない"], "ex": "地球の平均気温は年々上がり<b>つつある</b>。"},
"37006": {"point": "「連用形＋そびれる」は「〜する機会を逃してしまう」という意味。せっかく京都に行ったのに、忙しくておいしい料理を食べる機会を逃したということで、「そびれる」は連用形の「食べ」に付く。", "opts": ["食べて：「そびれる」はて形には付かず、連用形に付く", "食べる：辞書形には付かない。「食べそびれる」と連用形を使う", "", "食べよう：意向形には付かず、「食べそびれる」としなければならない"], "ex": "話しかけるタイミングを逃して、彼にお礼を言い<b>そびれて</b>しまった。"},
"37007": {"point": "「〜にかたくない」は「簡単に〜できる」という意味の書き言葉で、「想像にかたくない」「察するにかたくない」の形で使う。彼女の今までの苦労を思えば、受賞したときの喜びは簡単に想像できるということ。", "opts": ["にたえない：「〜にたえない」は「ひどくて〜できない（見るにたえない）」「〜の気持ちを抑えられない（感謝にたえない）」という意味で、喜びが簡単に想像できるという意味にならない", "せずにはすまない：「〜ずにはすまない」は「〜しないでは済まされない」という義務の意味で、喜びを想像する文に合わない", "", "するほかはない：「〜ほかはない」は「〜するしか方法がない」という意味で、喜びが容易に想像できるという意味にならない"], "ex": "突然家族を失った彼の悲しみは、察する<b>にかたくない</b>。"},
"37008": {"point": "「〜を経て」は「〜という過程・段階を通って」という意味。3ヶ月間の新入社員研修という段階を終えたあとで、営業課に配属されたという流れを表す。", "opts": ["機に：「〜を機に」は「〜をきっかけに新しいことを始める」という意味で、研修は配属のきっかけではなく通過する段階なので合わない", "", "かねて：「〜をかねて」は「〜という目的も一緒に（散歩をかねて買い物に行く）」という意味で、研修の後に配属されたという流れに合わない", "ひかえて：「〜をひかえて」は「〜が近くに迫っている（入学を控えて）」という意味で、すでに終わった研修には合わない"], "ex": "厳しい審査<b>を経て</b>、彼の作品が最優秀賞に選ばれた。"},
"37009": {"point": "「〜をおして」は「病気や困難を無理に押し切って〜する」という意味。採用試験を欠席するわけにはいかないので、高熱があるのを押し切って試験を受けたということ。", "opts": ["をおいて：「〜をおいて」は「〜以外に（彼をおいて適任者はいない）」という意味で、後に「ほかに〜ない」が続く。この文に合わない", "につけても：「〜につけても」は「〜に関連して、〜するたびに」という意味で、高熱を押し切るという意味を表せない", "にてらして：「〜に照らして」は「〜を基準にして（規則に照らして）」という意味で、高熱を基準にするのは意味が通らない", ""], "ex": "監督は体調不良<b>をおして</b>、最後まで試合の指揮をとった。"},
"37010": {"point": "「話題にのぼる」は「話題になる、人々の間で話される」という意味の慣用的な表現。映画は娯楽として人気が高いので、しばしば人々の話題になることもあるということ。", "opts": ["由来する：「〜に由来する」は「〜がもとになっている（地名に由来する）」という意味で、「話題に由来する」では意味が通らない", "達する：「〜に達する」は「ある数量や段階に届く（目標に達する）」という意味で、「話題」とは結びつかない", "", "させる：「話題にさせる」は使役の形で、誰が何をさせるのかがはっきりせず、「話題になる」という意味にならない"], "ex": "新しい駅ビルのことが、近所の人たちの間でよく<b>話題にのぼる</b>。"},
"37011": {"point": "「名詞＋めく」は「〜らしくなる、〜の様子が表れてくる」という意味。昔は田舎だった町が、高層ビルが立ち並ぶようになって都市らしくなってきたという変化を表す。", "opts": ["", "まみれに：「〜まみれ」は「汗・泥などが表面いっぱいについている」という意味で、町の様子の変化を表せない", "らしく：「都市らしく」は連用形なので、後に「なって」がないと「きた」につながらない（都市らしくなってきた）", "ぶって：「〜ぶる」は「〜のふりをする、〜を気取る（学者ぶる）」という悪い意味で使い、町が自然に変化していく様子には合わない"], "ex": "新しい証言が出て、事件はますます謎<b>めいて</b>きた。"},
"37012": {"point": "「辞書形＋べくもない」は「とても〜できない」という意味で、「及ぶべくもない」は「とてもかなわない」ということ。冬の雪景色も美しいが、秋の紅葉の豪華さにはとうてい及ばないという比較を表す。", "opts": ["かいがない：「〜かいがない」は「〜した効果がない（待ったかいがない）」という意味で、「及ぶかいがない」では意味が通らない", "", "ためしがない：「〜たためしがない」は「今まで一度も〜したことがない」という意味で、た形に付く。辞書形の「及ぶ」には付かない", "よりほかはない：「〜よりほかはない」は「〜するしか方法がない」という意味で、紅葉に及ばないという比較の文意に合わない"], "ex": "初心者の私の演奏は、先生の演奏には及ぶ<b>べくもない</b>。"},
"37013": {"point": "「〜てはばからない」は「遠慮せずに堂々と〜する」という意味で、非難の気持ちを込めて使うことが多い。罪を犯したのに、社会が悪いと遠慮なく言う者もいるらしいということ。", "opts": ["いいかねない：「〜かねない」は連用形に付いて「〜するおそれがある」という意味。「言って」の後に「いいかねない」を付けても意味が通らない", "", "かたくない：「〜にかたくない」は「簡単に〜できる（想像にかたくない）」という意味で、名詞などに「に」を付けて使い、て形には続かない", "かなわない：「〜てかなわない」は「〜てたまらない（暑くてかなわない）」という意味で、話し手自身の我慢できない気持ちを表す。他人の言動を述べるこの文に合わない"], "ex": "彼は自分こそが一番優秀だと公言し<b>てはばからない</b>。"},
"37014": {"point": "「〜とみえて」は「〜らしく、〜ようで」という意味で、様子から推測したことを述べ、後にその根拠となる様子が続く。一言もしゃべらなかった様子から、彼はかなり疲れているらしいと推測している。", "opts": ["", "といったら：「〜といったら」は「〜は（程度が大変なものだ）」という話題提示・感嘆の表現で、推測の意味がない", "としては：「〜としては」は「〜の立場・資格では」という意味で、推測を表せない", "ときたら：「〜ときたら」は人や物を話題にして不満を述べる表現で、名詞に付く。「疲れているときたら」では意味が通らない"], "ex": "弟はよほどおなかがすいていた<b>とみえて</b>、ご飯を三杯もおかわりした。"},
"37015": {"point": "「〜には及ばない」は「〜する必要はない」という意味で、「ご心配には及びません」は「心配する必要はありません」という丁寧な言い方。設定部分は簡単な英語なので、心配はいらないということ。", "opts": ["にはかたくありません：「〜にかたくない」は「簡単に〜できる（想像にかたくない）」という意味で、「心配」には付かず、心配がいらないという意味にもならない", "にもほどがありません：「〜にもほどがある」は「〜の程度がひどすぎる（冗談にもほどがある）」という非難の表現で、否定形では使わない", "にもかないません：「〜にはかなわない」は「〜には勝てない、〜はたまらない」という意味で、心配する必要がないという意味にならない", ""], "ex": "簡単な手続きですので、わざわざ窓口までお越しいただく<b>には及びません</b>。"},
"37016": {"point": "「〜に言わせれば」は「〜の意見では、〜の考えによると」という意味で、その人独自の意見を紹介するときに使う。旅行好きの彼の意見によれば、小さいホテルのほうがよりよいサービスを提供できるということ。", "opts": ["いってみれば：「彼に言ってみれば」は「彼に話してみれば」という意味になり、彼の意見を紹介する形にならない", "いわれれば：「〜に言われれば」は受身で「〜から言われたら」という意味になり、彼の意見を紹介する意味にならない", "", "いわせられれば：使役受身の形で「（無理に）言わされれば」という意味になり、彼の意見を紹介する意味にならない"], "ex": "母<b>に言わせれば</b>、最近の若者は辛抱が足りないそうだ。"},
"37017": {"point": "「〜はさておき」は「〜はひとまず置いて」という意味で、より重要な事柄を先に取り上げるときに使う。責任が誰にあるかという問題は後回しにして、今は今後の対策を考えるべきだという文に合う。", "opts": ["はおろか：「〜はおろか」は「〜はもちろん（〜も）」という意味で、後に「〜も〜ない」が続く。後回しにするという意味を表せない", "にひきかえ：「〜にひきかえ」は「〜とは反対に（兄にひきかえ弟は）」と二つを対比する表現で、この文に合わない", "にかかわる：「〜にかかわる」は「〜に関係する・影響する（命にかかわる）」という意味で、後に名詞などが来る。ここでは文が続かない", ""], "ex": "誰が言い出したか<b>はさておき</b>、まずは計画を実行に移そう。"},
"37018": {"point": "「辞書形＋ばかりになっている」は「準備が整い、あとは〜するだけの状態だ」という意味。夕食の支度が終わり、あとは食べるだけの状態なのに、だれも帰ってこないという不満を表す。", "opts": ["食べ：「ばかりになっている」は連用形には付かず、辞書形に付く", "食べて：「〜てばかりいる」（〜してばかりいる）とは別の形で、準備完了の意味を表すには辞書形が必要", "", "食べよう：意向形には「ばかりになっている」は付かない。辞書形の「食べる」が必要"], "ex": "書類はすべてそろえたので、あとは提出する<b>ばかりになっている</b>。"},
"37019": {"point": "「〜てみせる」は「必ず〜する」という話し手の強い意志・決意を表し、「〜てみせよう」はその意向形。合格できなかった悔しさから、来年こそ絶対に合格するという決意を表し、「絶対に」「決意した」と合う。", "opts": ["", "しそうだ：「〜しそうだ」は様態や予想を表し、「絶対に」「決意した」という強い意志と合わない", "してみよう：「〜てみよう」は「試しに〜しよう」という意味で、「絶対に」と合わず、強い決意を表せない", "するそうだ：「〜そうだ」は伝聞を表し、自分の決意を述べる文に合わない"], "ex": "次の大会では、必ず優勝し<b>てみせる</b>。"},
"37020": {"point": "「AといわずBといわず」は「AもBも区別なく、すべて」という意味。被災地では救助の手が足りず、子供もお年寄りも区別なく、まだたくさんの人が生き埋めになっているという深刻な状況を表す。", "opts": ["とあって / とあって：「〜とあって」は「〜という特別な状況なので（連休とあって）」という理由を表し、二つ並べて「区別なく」の意味にはならない", "というか / というか：「AというかBというか」は物事をどう言い表せばよいか迷う表現で、人を並べて区別なくという意味にならない", "となら / となら：「〜となら」は「〜と一緒なら」という条件を表し、二つ並べる形はなく、意味が通らない", ""], "ex": "壁<b>といわず</b>床<b>といわず</b>、部屋中が落書きだらけだった。"},
"35011": {"point": "「〜と思いきや」は「〜と思ったが、意外にも（そうではなかった）」という意味。「彼のことだから」は「彼の性格から考えれば当然」という判断の根拠を表し、今日も遅れて来るだろうという予想が外れて10分前に来たという意外さにつながる。", "steps": "「約束の時間を守らない」は「彼」を修飾するので、まず「彼のことだから」が来る。次に予想の内容として「どうせ今日も」「時間通りには」「来ないだろうと」と続き、引用の「と」が文末の「思いきや」につながる。", "ex": "今年の冬は暖かいと<b>思いきや</b>、12月に入って急に寒くなった。"},
"35012": {"point": "「〜ずにはすまない」は「〜しないでは済まされない、必ず〜しなければならない」という意味で、社会的な事情や状況から避けられないことを表す。倒壊のおそれがある建物は、安全のために取り壊すしかないという判断になる。", "steps": "「倒壊する」に「おそれのある」が付いて名詞「建物」を修飾し、「建物では」となる。その後に「とりこわさずには」を置き、「すまない」が文末の「だろう」につながる。", "ex": "大切な書類をなくしてしまったのだから、上司に報告せ<b>ずにはすまない</b>。"},
"35013": {"point": "「〜なりに」は「〜にふさわしい程度で、〜の立場で」という意味。子どもも子どもの立場で考えて行動しているのだから、親は干渉しすぎずに見守ることが大切だという文になる。", "steps": "「子どもなりに」は動詞を修飾するので「考えて」が続き、「行動しており」で前半が区切られる。後半の主語「親は」を置き、「干渉しすぎないで」が文末の「見守る」を修飾する。", "ex": "新人は新人<b>なりに</b>、精一杯努力しているようだ。"},
"35014": {"point": "「〜かのごとき」は「まるで〜のような」という意味で、事実とは違うことにたとえる表現。後ろに名詞が来る（〜かのごとき態度）。「にもかかわらず」で、初めて会ったという事実と、昔からの知り合いのような態度との食い違いを表す。", "steps": "「初めて会った」に逆接の「にもかかわらず」が付く。次に「昔から」が「知っている」を修飾し、「知っているかのごとき」が文末の名詞「態度」を修飾する。", "ex": "彼はすべてを見てきた<b>かのごとき</b>口ぶりで事件について語った。"},
"35015": {"point": "「〜にたえる」は「〜するだけの価値がある、〜に十分応えられる」という意味（鑑賞にたえる・批判にたえる）。消費者の信頼に十分応えられる、選ばれた農家で作られた野菜だということを表す。", "steps": "「消費者の信頼に」は「たえる」と結びついて一つの修飾句になり、後ろの「選ばれた農家で生産されたもの」にかかる。「選ばれた農家で」は生産の場所を表して「生産された」につながり、「生産された」が文末の「もの」を修飾する。", "ex": "この作品は、大人の鑑賞にも<b>たえる</b>本格的なアニメ映画だ。"},
"35111": {"point": "「〜とあれば」は「〜という事情なら（何でもする・仕方がない）」という意味。以前は上司の命令という理由があれば従うしかないと考える社員が多かったが、今はそういう社員が少なくなったという文脈に合う。", "steps": "「上司の命令」に「とあれば」が付いて条件を表し、その帰結として「やらざるをえない」が続く。引用の「と考える」が文末の名詞「社員」を修飾する。", "ex": "子どものため<b>とあれば</b>、親はどんな苦労もいとわない。"},
"35112": {"point": "「〜べく」は「〜するために」という意味の書き言葉で、動詞の辞書形に付く（「する」は「すべく」）。警察が物的証拠を確保するという目的のために、捜査に力を入れていることを表す。", "steps": "「事件の」は名詞「真相」につながるので、まず「真相にかかわる」が来て「物的証拠」を修飾する。「物的証拠を」が「確保すべく」の目的語になり、目的を表す「確保すべく」の後に「捜査に」が続いて文末の「力を入れている」につながる。", "ex": "彼は医者になる<b>べく</b>、毎日遅くまで勉強している。"},
"35113": {"point": "「〜ところを」は「〜している時に、その状況を（妨げるように）」という意味で、後に「呼び出される・起こされる」など、その状況を妨げる出来事が続く。ゆっくり休んでいたのに呼び出され、休日出勤する「はめになった（よくない結果になった）」という流れになる。", "steps": "「ゆっくり」は「休んでいた」を修飾し、「休んでいたところを」で妨げられた状況を表す。その後に原因の「急用で」を置き、「呼び出され」が中止形で文末の「休日出勤するはめになった」につながる。", "ex": "気持ちよく寝ていた<b>ところを</b>起こされ、朝から掃除を手伝う<b>はめになった</b>。"},
"35114": {"point": "「〜てからでないと」は「〜した後でなければ（…できない）」という意味で、後には否定や困難を表す表現が続く。短い観光ではわからないので、実際に住んでみた後でなければその国のよさは知ることができないという主張になる。", "steps": "「住んでみてから」に「でないと」が付いて「〜てからでないと」の形になる。その後に「その国のよさを知る」を置き、「ことはできない」で否定の結論を表して、文末の「だろうと思う」につながる。", "ex": "実物を見<b>てからでないと</b>、買うかどうか決められない。"},
"35115": {"point": "「〜にひきかえ」は「〜とは反対に、〜と比べて大きく違って」という意味で、二つのものを対比させる。立派なとなりの家と比べて、わが家はとてもみすぼらしいと嘆く文。文末の「なんと〜ことか」は強い感嘆を表す。", "steps": "「立派な」は名詞「となりの家」を修飾し、そこに「にひきかえ」が付いて比べる対象を示す。後半の主語「わが家は」の後に「なんとみすぼらしい」が来て、文末の「ことか」と結びつく。", "ex": "兄が社交的なの<b>にひきかえ</b>、弟はおとなしくて無口だ。"},
"36621": {"point": "「〜をよそに」は「〜を気にかけないで、〜に関係なく」という意味。緊張して実力を出せない選手が多い中で、彼女はそんなほかの選手たちを気にせず、一人だけ独走しているという対比を表す。", "steps": "「実力を発揮できない」は名詞「選手」を修飾するので「選手も多いが」が続き、逆接の「が」で後半に移る。後半の主語「彼女は」の後に「ほかの」「選手を」を置き、文末の「よそに」につながる。", "ex": "親の心配<b>をよそに</b>、息子は毎晩遅くまで遊び歩いている。"},
"36622": {"point": "「〜たところで」は「たとえ〜しても（期待する結果にはならない）」という意味で、後には否定的な判断が続く。普段怠けていたのだから、前日に徹夜して勉強しても無駄だということを表し、文末の「〜にきまっている」と合う。", "steps": "「試験の前日に」の後に「徹夜して」「勉強した」が続き、た形に「ところで」が付いて逆接の仮定になる。その結果として「合格できない」が来て、文末の「にきまっている」につながる。", "ex": "今さら謝った<b>ところで</b>、彼女は許してくれないだろう。"},
"36623": {"point": "「〜だけに」は「〜だから、なおさら」という意味で、前の事情から当然予想される気持ちや結果が強まることを表す。コツコツ練習する姿を知っているからこそ、優勝の喜びがいっそう大きいという文。", "steps": "「コツコツと練習に」の後に「取り組んでいる」が来て、名詞「姿」を修飾する。「姿を」は「知っている」の目的語で、「知っているだけに」が理由を表して文末の「今回の優勝は本当にうれしい限りだ」につながる。", "ex": "期待していた<b>だけに</b>、不合格の知らせはショックだった。"},
"36624": {"point": "「〜にひきかえ」は「〜とは反対に」という意味で、二つのものを対比する。人が集まりすぎる都会と比べて、田舎では人口が減る一方だという対比になる。「〜ばかりで」は変化が悪い方向にだけ進むことを表す。", "steps": "「過密問題を抱えている」は名詞「都会」を修飾し、「都会にひきかえ」で比べる対象を示す。後半の場所「田舎では」の後に「人口が減る」が来て、「ばかりで」が文末の「過疎化に悩んでいる」につながる。", "ex": "去年の夏が涼しかったの<b>にひきかえ</b>、今年は猛暑が続いている。"},
"36625": {"point": "「〜ながらも」は「〜けれども」という逆接を表す。「承知しながらも」は「わかっていたけれども」の意味で、かなりのリスクがあると知りつつ、それでも支援を惜しまなかったという文になる。", "steps": "「かなりのリスクが」は「伴う」の主語で、「伴う」が形式名詞「こと」を修飾して「ことを」となる。「ことを」は「承知しながらも」の目的語で、逆接の「ながらも」が文末の「支援を惜しまなかった」につながる。", "ex": "体に悪いと知り<b>ながらも</b>、ついたばこを吸ってしまう。"},
"36626": {"point": "「〜たが最後」は「一度〜したら、もう（悪い結果になって）どうにもならない」という意味。普段は穏やかな彼でも、一度怒り出したら、だれが何と言っても聞き入れなくなるという様子を表す。", "steps": "「普段は」の後に「穏やかな彼だが」が来て、逆接の「が」で後半に移る。「一度怒り出したが」と「最後」が結びついて「〜たが最後」になり、その後に「だれが」が来て文末の「なんと言っても」と組み合わさる。", "ex": "この本は読み始めた<b>が最後</b>、最後のページまでやめられない。"},
"36627": {"point": "「〜てからというもの」は「〜して以来ずっと」という意味で、ある出来事をきっかけに状態が大きく変わり、それが続いていることを表す。手術以来、食べるものが限られていることも理由となって、人と食事をしたがらないという文。", "steps": "「手術をしてから」に「というもの」が付いて「〜てからというもの」の形になる。次に「食べるものが」「限られている」が続き、原因を表す「せい」に「も」が付いた「せいも」が、文末の「あり」と結びつく（〜せいもあり）。", "ex": "子どもが生まれ<b>てからというもの</b>、夫はたばこを一本も吸わなくなった。"},
"36628": {"point": "「〜とあって」は「〜という特別な事情なので」という意味で、その状況だから当然起こる結果が後に続く。地元でとれた果物や野菜が新鮮で安いという理由で、市場が大評判になっていることを表す。", "steps": "「地元で」は動詞「とれた」につながり、「とれた」が名詞「果物や野菜」を修飾する。「果物や野菜が」の述語が「新鮮で安い」で、引用の「と」に「あって」が付いて「〜とあって」となり、文末の「大評判である」につながる。", "ex": "人気歌手が来る<b>とあって</b>、会場には朝から長い行列ができた。"},
"36629": {"point": "「〜ようものなら」は「もし〜したら（大変なことになる）」という意味で、動詞の意向形に付く。名前のスペルを間違えでもしたら、泊まれなくなるという深刻な結果になりかねないことを表す。", "steps": "「名前のスペルを」は「間違えよう」の目的語で、意向形「間違えよう」に「ものなら」が付く。その結果として「宿泊できなくなってしまう」が来て、文末の「という大問題」につながる。", "ex": "あの先生の授業で居眠りでもし<b>ようものなら</b>、ひどく叱られる。"},
"36630": {"point": "「〜ないまでも」は「〜ほどではないが、（せめて）〜」という意味で、後には「せめて〜」など最低限の希望が続く。習ったことを全部とまでは言わないが、少なくとも前回の内容ぐらいは覚えていてほしいという気持ちを表す。", "steps": "「授業で」の後に「習ったことは」が来て話題を示す。「全部とは」が「言わないまでも」につながって「全部とは言わないまでも」となり、最低限の要求を表す「せめて」が文末の「前回習ったことぐらいは」に続く。", "ex": "毎日とは言わ<b>ないまでも</b>、週に一度は運動したほうがいい。"},
"36631": {"point": "「〜つつある」は「だんだん〜している」という変化の進行を表し、「〜とはいえ」は「〜けれども」という逆接を表す。景気は回復してきているが、それでも生活には大きな変化がないという文。", "steps": "「回復し」は動詞の連用形なので「つつある」が付いて「回復しつつある」となる。そこに逆接の「とはいえ」が続き、「依然として」が後半の「われわれの生活に大きな変化はない」を修飾する。", "ex": "新しい制度は社会に定着し<b>つつあるとはいえ</b>、まだ課題も多い。"},
"36632": {"point": "「AはおろかBすら」は「Aはもちろん、もっと簡単なBさえ」という意味で、程度の大きいAを否定したうえで、Bもできないと強調する。事故のせいで、歩くことはもちろん、起き上がることさえできないという文。", "steps": "「歩くことは」に「おろか」が付いて「〜はおろか」の形になる。次に、より程度の軽い動作として「起き上がる」が来て「ことすら」に続き、文末の「できない」につながる。", "ex": "忙しくて、旅行<b>はおろか</b>週末に休むこと<b>すら</b>できない。"},
"36633": {"point": "「〜ゆえの」は「〜が原因の、〜のための」という意味の硬い表現で、名詞に付いて後の名詞を修飾する。先進国の豊かさが原因の環境破壊と、途上国の貧困が原因の環境問題とを「とは異なり」で対比している。", "steps": "「先進国における」の後には名詞が必要なので「豊かさ」が来る。「豊かさゆえの」が「環境破壊」を修飾し、「環境破壊とは」が「異なり」と結びついて、後半の「途上国においては」につながる。", "ex": "若さ<b>ゆえの</b>失敗は、だれにでもあるものだ。"},
"36634": {"point": "「〜までもない」は「わざわざ〜する必要はない（それほど明らかだ）」という意味で、動詞の辞書形に付く。談合が競争入札の最大の阻害要因であることは明らかで、改めて強調する必要もないという文。", "steps": "「談合こそ」の述語として「最大の阻害要因である」が来て、それを「ことは」で名詞化する。次に「改めて」が「強調する」を修飾し、辞書形「強調する」が文末の「までもない」につながる。", "ex": "健康が何より大切なことは言う<b>までもない</b>。"},
"36635": {"point": "「〜をおいてほかに〜ない」は「〜以外には（〜はいない）」という意味で、その人やものが唯一の存在だと高く評価する表現。オリンピック出場が一度だけなのに、今も高く評価されている選手は彼しかいないという文。", "steps": "「今も高く」は「評価されている」を修飾し、「評価されている」が名詞「選手」を修飾して「選手は」となる。その後に「彼をおいて」「ほかには」が続き、文末の「いない」と結びつく。", "ex": "このプロジェクトのリーダーにふさわしいのは、山田さん<b>をおいてほかにいない</b>。"},
"36636": {"point": "「〜とは限らない」は「必ずしも〜ではない」という意味で、一般に成り立ちそうなことにも例外があることを表す。ある人に有益な情報でも、他の人にも有益だとは言えないという主張で、前の文の「人によっても目的によっても違う」と合う。", "steps": "「ある人に」は「有益な」につながり、「有益な」が名詞「情報」を修飾して「情報であっても」となる。逆接の後に比べる相手の「他の人にとっては」を置き、「有益とは」が文末の「限らない」につながる。", "ex": "値段が高いからといって、品質がいい<b>とは限らない</b>。"},
"36637": {"point": "「〜極まる」は「この上なく〜だ」という意味で、「非常識・失礼・危険」などナ形容詞の語幹に付き、話し手の強い非難の気持ちを表す。映画の最中に携帯電話で通話する人を、この上なく非常識だと批判している。", "steps": "「携帯電話を使って」の後に「通話する」が来て、名詞「人間」を修飾する。「非常識」に「極まる」が付いて「非常識極まる」となり、これも「人間」を修飾する。最後の「人間がいる」が文末の「とは驚きだ」につながる。", "ex": "約束を無断で破るとは、失礼<b>極まる</b>態度だ。"},
"36638": {"point": "「〜にいたって」は「〜という（極端な）段階になって」という意味で、後に「やっと・ようやく・初めて」などが続くことが多い。全財産を失うという最悪の事態になってやっと、詐欺にあったと気づいたという文。", "steps": "「全財産を失う」は辞書形なので「にいたって」が付いて「〜にいたって」の形になる。その後に「やっと」が来て「気がついた」を修飾し、「詐欺にあった」が形式名詞「こと」の内容を表して文末の「ことに気がついた」につながる。", "ex": "死者が出る<b>にいたって</b>、ようやく国は対策に乗り出した。"},
"36639": {"point": "「〜なくしては」は「〜がなければ（…できない）」という意味で、後には否定や不可能を表す表現が続く。食料自給率が下がり続け、農産物の輸入がなければ満足に食べられない状況になっていることを表す。", "steps": "「どんどん」は「さがり」を修飾し、「さがり」が「食料自給率は」の述語になる。「さがり」は連用中止形で後半につながり、「農産物の輸入」に「なくしては」が付いて条件を表し、文末の「満足に食べられなくなっている」につながる。", "ex": "家族の支え<b>なくしては</b>、この仕事を続けることはできなかった。"},
"36640": {"point": "「〜ともなれば」は「〜という（高い・特別な）立場や段階になれば、当然」という意味。一流ホテルでのパーティーという特別な場なら、服装にも気を使わないわけにはいかないという文。", "steps": "「パーティー」に「とも」「なれば」が続いて「〜ともなれば」の形になる。次に「服装にも」が「気を使わない」につながり、文末の「わけにはいかない」と結びついて「気を使わなければならない」という意味になる。", "ex": "大学生<b>ともなれば</b>、自分のことは自分で決めるべきだ。"},
"36721": {"point": "「〜てまで」は「〜という極端なことをしてでも」という意味で、目的のために普通はしないことまですることを表す。買い物の幸福感を味わいたいという目的のために、借金という極端な手段まで取るという文。", "steps": "「買い物した時の」の後には名詞が必要なので「幸福感を」が来て、「味わおうと」が目的を表す（〜ようと）。その後に手段の「借金して」と「まで」が続き、文末の「買い物をする」につながる。", "ex": "人を傷つけ<b>てまで</b>、自分の利益を守りたいとは思わない。"},
"36722": {"point": "「〜に足る」は「〜するだけの価値・資格がある」という意味で、動詞の辞書形や名詞に付く（信頼に足る人物）。次の市長という重大な役目を任せられるだけの人物は、水野さんしかいないという文。", "steps": "「次回市長」に「としての」が付いて名詞を修飾する形になり、「重大な」とともに「役目」を修飾する。「役目を担う」は辞書形なので「に足る」が付き、「に足る」が文末の名詞「人物」を修飾する。", "ex": "彼は信頼する<b>に足る</b>人物だ。"},
"36723": {"point": "「AもさることながらB」は「Aももちろん大切だが、Bもまた（それ以上に）」という意味。新製品の開発には、資金調達はもちろん重要だが、優秀な研究者も欠かせないという文。", "steps": "「新製品の開発」に「にあたっては」が付いて場面を示す。次に「資金調達」が来て「もさること」「ながら」と続き、「〜もさることながら」の形になって、文末の「優秀な研究者も欠かせない」につながる。", "ex": "この店は、料理の味<b>もさることながら</b>、サービスもすばらしい。"},
"36724": {"point": "「〜に即して」は「〜に従って、〜を基準にして」という意味で、事実や規則などに合わせて物事を行うことを表す。消費者を対象に行ったアンケートの結果を基準にして、商品開発を進めることにしたという文。", "steps": "「消費者を対象に」は動詞「行った」につながり、「行った」が名詞「アンケートの結果」を修飾する。そこに「に即して」が付いて基準を示し、「商品開発」が文末の「を進める」の目的語になる。", "ex": "実際の状況<b>に即して</b>、計画を見直す必要がある。"},
"36725": {"point": "「〜ならではの」は「〜だけにある、〜でなければ得られない」という意味で、そのものに特有のよさを表す。高原だからこそ味わえる新鮮な野菜と果物を使ったサラダ、という文。", "steps": "「高原」に「ならではの」が付いて名詞を修飾する形になり、「新鮮な野菜と果物」を修飾する。「AとB」で並んだ「新鮮な野菜と」「果物」が、文末の「を使ったサラダ」につながる。", "ex": "これは手作り<b>ならではの</b>温かみのある作品だ。"},
"36726": {"point": "「〜ではあるまいし」は「〜ではないのだから」という意味で、後には「〜できない・〜するな」などの判断や非難が続く。神様ではないのだから、だれも市場の動きを先取りして予測することなどできないという文。", "steps": "「神様では」に「あるまいし」が付いて「〜ではあるまいし」の形になる。後半の主語「だれも」の後に「市場の動きを」が来て、「先取り」が文末の「して予測する」と結びつく。", "ex": "子ども<b>ではあるまいし</b>、自分のことは自分でしなさい。"},
"36727": {"point": "「〜ばいいものを」は「〜すればいいのに（実際はそうしなかった）」という意味で、そうしなかったことへの不満や残念な気持ちを表す。知らないふりをしていればよかったのに、証言してしまったために大変なことになったという文。", "steps": "「知って」の後に「知らぬ」が来て名詞「ふり」を修飾し、「知って知らぬふり（知っているのに知らないふり）」となる。「ふりを」が「していれば」の目的語になり、「いい」が文末の「ものを」につながる。", "ex": "早く相談すれ<b>ばいいものを</b>、一人で悩んで体を壊してしまった。"},
"36728": {"point": "「ただ〜のみ」は「〜だけ」を強調する表現。「〜ところだ」は修飾を受けて「〜する内容・〜していること」を表す（多くの人の知るところだ）。関係者が亡くなった今、真相は神様だけが知っていることだという意味になる。", "steps": "「ただ」は「のみ」と呼応するので「神のみ」の前に置く。「神のみ」は「知る」の主語で、「知る」が形式名詞「ところ」を修飾し、文末の「だ」につながる。", "ex": "合格できるかどうかは、<b>ただ</b>本人の努力<b>のみ</b>にかかっている。"},
"36729": {"point": "「〜にかかわらず」は「〜に関係なく」という意味で、「有無・大小・賛否」など対立する内容を含む名詞に付く。妻が仕事をしているかどうかに関係なく、夫は育児に積極的にかかわるべきだという考えを表す。", "steps": "「妻の仕事の有無に」に「かかわらず」が付いて「〜にかかわらず」の形になる。後半の主語と対象を示す「夫は育児に」の後に「積極的にかかわる」が来て、辞書形が文末の「べきだ」につながる。", "ex": "参加の有無<b>にかかわらず</b>、メールで返事をしてください。"},
"36730": {"point": "「〜にもまして」は「〜以上に、〜よりもっと」という意味で、前のものも重要だが、後のものがそれ以上であることを表す。親にとっては、試験の結果よりも子どもの健康の方が心配だという文。", "steps": "「親に」は「とっては」と結びついて「〜にとっては」となり、立場を示す。次に比べる対象の「試験の結果」に「にもまして」が付き、より心配なものとして「子供の健康」が来て、文末の「が心配だ」につながる。", "ex": "今年の夏は、去年<b>にもまして</b>暑い日が続いている。"},
"36731": {"point": "「〜にたえない」は「（ひどくて）〜するのが我慢できない、とても〜していられない」という意味で、「聞く・見る・読む」などの辞書形に付く。高校生同士が、聞いていられないほどひどい言葉を大声で話していたという文。", "steps": "「高校生」に「同士が」が付いて主語になる。次に「聞く」に「にたえない」が付いて「聞くにたえない」となり、名詞「言葉」を修飾して文末の「言葉を大きな声で話していた」につながる。", "ex": "その事故現場は、見る<b>にたえない</b>ありさまだった。"},
"36732": {"point": "「〜にしてはじめて」は「〜だからこそ（やっと）〜できる」という意味で、その人やものでなければ実現できないことを表す。想像力豊かな子どもだからこそ描ける、無邪気で楽しい絵だという文。", "steps": "「想像力豊かな」は名詞「子ども」を修飾する。「子ども」に「にして」「はじめて」が続いて「〜にしてはじめて」の形になり、文末の「描ける絵だ」につながる。", "ex": "長年の経験を持つ職人<b>にしてはじめて</b>、この味が出せるのだ。"},
"36733": {"point": "「〜からといって」は「〜という理由だけで（必ずしも…ではない）」、「〜ないものでもない」は「まったく〜ないわけではない」という意味。性格が悪いという理由だけで経営ができないわけではないが、やはり社長の人柄は企業のイメージに表れるという文。", "steps": "「性格が悪い」に「からといって」が付き、その後に判断の内容として「経営ができない」が来る。「ものでもないが」が付いて「〜ないものでもない」の形になり、逆接の「が」の後に「やはり」を置いて、文末の「社長の人柄は〜」を導く。", "ex": "締め切りまで時間が少ない<b>からといって</b>、間に合わ<b>ないものでもない</b>。"},
"36734": {"point": "「〜といえども」は「〜であっても」という意味の硬い逆接表現で、「〜なら当然…だろう」と思われる名詞に付く。にぎやかな都心であっても、大不況のため裏通りに入ればテナント募集の張り紙だらけだという文。", "steps": "「都心」に「といえども」が付いて逆接を表す。次に「一歩裏通りに」が「入れば」につながって条件を表し、主語の「ビルは」が文末の「テナント募集の張り紙だらけである」につながる。", "ex": "子ども<b>といえども</b>、法律は守らなければならない。"},
"36735": {"point": "「〜を禁じえない」は「〜の気持ちを抑えることができない」という意味で、「涙・驚き・同情」など感情を表す名詞に付く。古代遺跡を目の前にして、古代へのつのる思いを抑えられなかったという文。", "steps": "「古代遺跡を」は「目の前にして」につながる。次に「古代への」が来て、「募る」とともに名詞「思い」を修飾する。「思いを」が文末の「禁じえなかった」の目的語になる。", "ex": "被害者の話を聞いて、同情<b>を禁じえなかった</b>。"},
"36736": {"point": "「〜にもまして」は「〜以上に」という意味で、「以前にもまして」は「以前よりいっそう」の意。父親から会社を任されたことをきっかけに、以前よりさらに仕事に励むようになったという文。", "steps": "「父親から」は「まかされて」につながるので「会社をまかされて」が来る。次に「以前にもまして」が「仕事に励む」を修飾し、辞書形「励む」に「ようになった」が付いて変化を表し、文末の「らしい」につながる。", "ex": "退院してから、父は以前<b>にもまして</b>健康に気をつけるようになった。"},
"36737": {"point": "「〜ないではおかない」は「必ず〜する」という強い意志や、自然にそういう状態を引き起こすことを表す。苦境から必ず一歩を踏み出してみせるという覚悟が、日ごとに強くなってきたという文。", "steps": "「一歩を」は「進めないでは」の目的語で、「おかない」が付いて「〜ないではおかない」の形になり、名詞「覚悟」を修飾する。「覚悟が」が主語となり、「日ごとに」が文末の「強くなってきた」を修飾する。", "ex": "今度こそ事件の真相を明らかにし<b>ないではおかない</b>。"},
"36738": {"point": "「〜とあいまって」は「〜と一緒になって、互いに作用し合って」という意味で、二つの要素が重なって大きな結果を生むことを表す。高齢化が少子化と重なって、世界に例のない速さで進んでいるという文。", "steps": "「少子化と」に「あいまって」が付いて「〜とあいまって」の形になる。次に「世界に」が「例をみない」につながり、「例をみない」が名詞「スピード」を修飾して文末の「で進んでいる」につながる。", "ex": "好天<b>とあいまって</b>、今年の祭りは大勢の人でにぎわった。"},
"36739": {"point": "「〜そばから」は「〜するとすぐに（また）」という意味で、同じことが繰り返される場面で、話し手の不満を込めて使う。注意されたすぐ後に同じミスを繰り返すので、やる気がないとしか言えないという文。", "steps": "「注意された」に「そばから」が付いて「〜たそばから」となり、直後の行動を導く。次に「同じミスを」が「繰り返す」の目的語になり、「繰り返す」が文末の「なんて」につながる。", "ex": "片づけた<b>そばから</b>、子どもがおもちゃを散らかしてしまう。"},
"36740": {"point": "「〜にかかわる」は「〜に関係する、〜に重大な影響を及ぼす」という意味で、「命・名誉・根幹」など重大な名詞に付くことが多い。人材を育てるという点で、教育は国の根幹に関係する重要な役割を担っているという文。", "steps": "「人材を育てる」に「という点で」が付いて観点を示す。次に「国の根幹」に「にかかわる」が付いて名詞「重要な役割」を修飾し、「重要な役割」が文末の「を担っており」の目的語になる。", "ex": "これは会社の信用<b>にかかわる</b>問題だから、慎重に対応してほしい。"},
"36821": {"point": "「〜からある」は数量を表す語に付いて「〜も（それ以上も）ある」という意味で、量の多さを強調する。昼夜を問わず働いて、一千万円もの大きな借金をわずか5年で全部返したという文。", "steps": "「昼夜を問わず」は動詞を修飾するので「働き」が来て、連用中止形で後半につながる。「一千万円」に「から」「ある」が続いて「〜からある」となり、文末の名詞「借金」を修飾する。", "ex": "彼は20キロ<b>からある</b>荷物を一人で運んだ。"},
"36822": {"point": "「〜ことなしに」は「〜しないで」という意味の硬い表現で、動詞の辞書形に付く。「〜ことがある」は「時に〜する場合がある」の意。マニュアルの内容は、事前に予告しないで変更する場合があるという注意書きになる。", "steps": "「将来」の後に「予告する」が来て、「ことなしに」が付いて「予告することなしに」となる。それが「変更する」を修飾し、「変更する」に「ことが」が付いて文末の「あります」につながる。", "ex": "努力する<b>ことなしに</b>、成功を手に入れることはできない。"},
"36823": {"point": "「〜たりとも」は「一＋助数詞」に付いて「たとえ〜でも（…ない）」という意味で、少しも〜しないという強い否定を表す。提出まであと2時間しかないので、1分も無駄にできない状況だという文。", "steps": "「あと」は「2時間しか」につながり、「しか」は否定の「残っておらず」と呼応する。中止形「残っておらず」の後に「一分たりとも」が来て「おろそかにできない」と呼応し、文末の名詞「状況」を修飾する。", "ex": "試験まで、一日<b>たりとも</b>休むわけにはいかない。"},
"36824": {"point": "「〜べきところを」は「本来〜するべきなのに（そうしなかった・できなかった）」という意味で、すべきことができなかった事情を述べたり、わびたりするときに使う。すぐにお見舞いに行くべきだったのに、海外出張のため行けなかったという文。", "steps": "「すぐにお見舞いに」は「行くべき」につながり、「行くべき」に「ところを」が付いて逆接を表す。その後に理由の「海外出張のため」が来て、「お見舞いに」が文末の「行けなかった」につながる。", "ex": "本来ならこちらから伺う<b>べきところを</b>、わざわざお越しいただきありがとうございます。"},
"36825": {"point": "「〜ない限り」は「〜しなければ（ずっと…だ）」という意味で、その条件が満たされない間は状況が変わらないことを表す。売り上げが減り続けている中、何か対策を立てなければ売り上げが増えることはないだろうという文。", "steps": "「何か」は「対策を立てない」につながり、「限り」が付いて「〜ない限り」の形になる。次に「増える」が来て「ことはない」で否定の結論を表し、文末の「だろう」につながる。", "ex": "本人が反省し<b>ない限り</b>、同じ失敗は繰り返されるだろう。"},
"36826": {"point": "「名詞＋がてら」は「～を兼ねて、～のついでに」という意味で、一つの行動に別の目的も持たせることを表す。駅まで歩くことに「運動」という目的を兼ねている。", "steps": "「家から駅までは」の後に、名詞「距離」を修飾する「かなりの」を置き、「かなりの距離があるが」と状況を述べる。逆接の「が」の後に、歩く目的として「運動がてら」を置き、文末の「なるべく歩くようにしている」につながる。", "ex": "散歩<b>がてら</b>、近所のパン屋まで行ってきた。"},
"36827": {"point": "「～にあっても」は「～という状況においても」という意味の書き言葉。国も地方も財政が危機的な状況であっても、高齢社会の進展によって福祉の経費は増え続けていることを述べている。", "steps": "「国と地方を通じた」と「危機的な」はどちらも名詞「財政状況」を修飾する。「財政状況」に「にあっても」が付いて状況を表し、続く「高齢社会の」が文末の名詞「進展」を修飾して「高齢社会の進展により」となる。", "ex": "どんな逆境<b>にあっても</b>、彼は決して希望を捨てなかった。"},
"36828": {"point": "「～なりに」は「～に応じて、その範囲でそれなりに」という意味。「ないなりに」で「お金がないならないで、その状態に合ったやり方で」となり、お金がなくても楽しく生きる方法があることを表す。", "steps": "「お金がなくても」を受けて「ない」に「なりに」が付き、「ないなりに」となる。その後に、動詞を修飾する「楽しく」と「生きて」が続き、「生きて」が文末の「いく方法」につながって「生きていく方法」となる。", "ex": "子どもは子ども<b>なりに</b>、家族のことを心配しているようだ。"},
"36829": {"point": "「～べからざる」は「～べからず」の連体形で、「～してはならない、～することができない」という意味の書き言葉。「許すべからざる行為」で「決して許してはならない行為」となる。", "steps": "「根幹に」の「に」は「関わる」につながり、「根幹に関わる」となる。動詞の辞書形「許す」に「べからざる」が付いて「許すべからざる」となり、名詞「行為」を修飾する。「根幹に関わる」も「行為」を修飾し、「行為」が文末の「といえよう」につながる。", "ex": "水は、人間が生きていくうえで欠く<b>べからざる</b>ものである。"},
"36830": {"point": "「～（よ）うと」は「～ても」という意味で、「何と言おうと」は「誰が何と言っても、やはり」と、ほかのことはさておき最も言いたいことを強調する。この洋食屋の最大の特徴を述べている。", "steps": "「何と」は「言おうと」につながり、「何と言おうと」で後ろ全体にかかる。その後に店の特徴として「ボリュームたっぷりで」と「安くておいしい」を並べ、「安くておいしい」が文末の名詞「こと」を修飾して「～ことだろう」で文が終わる。", "ex": "誰が<b>何と言おうと</b>、私はこの夢をあきらめない。"},
"36831": {"point": "「～こととて」は「～なので」という意味で、理由を表す古風な書き言葉。「大型連休直前のこととて」で「大型連休の直前なので」となり、今からの予約が厳しい理由を述べている。", "steps": "「大型連休」の後に「直前の」が来て「大型連休直前の」となり、「こととて」が付いて理由を表す。その後に「今からの」が名詞「予約」を修飾して「今からの予約は」となり、文末の「かなり厳しいらしい」につながる。", "ex": "何分にも初めての<b>こととて</b>、至らない点はお許しください。"},
"36832": {"point": "「～を皮切りに」は「～を始まりとして、次々に」という意味。本会議が「市長の演説」から始まり、それに続いて新年度予算案の審議に入るという流れを表す。", "steps": "「市長の演説を」の「を」は「皮切りに」につながり、「市長の演説を皮切りに」となる。次に「新年度予算案の」が名詞「審議」を修飾し、「審議に」が文末の「入ります」につながる。", "ex": "東京公演<b>を皮切りに</b>、全国20都市でコンサートが行われる。"},
"36833": {"point": "「～ともなく」は「特に～しようという意識もなく」という意味。疑問詞と使った「どちらを応援するともなく」で、どちらのチームを応援するわけでもなく、何となく試合を見ていたことを表す。", "steps": "「どちらを」の「を」は「応援する」につながり、「ともなく」が付いて「どちらを応援するともなく」となる。それが「見ていたが」を修飾し、逆接の「が」の後に「緊迫した」が来て、文末の「良い試合」を修飾する。", "ex": "電車の中で、聞く<b>ともなく</b>隣の人の話を聞いていた。"},
"36834": {"point": "「～とばかりに」は「まるで～と言うかのように」という意味で、態度や行動にその気持ちが表れていることを示す。「今がチャンスとばかりに」で、景気回復を好機と見て値上げをする企業の様子を表す。", "steps": "「今が」の後に「チャンス」が来て、「とばかりに」が付き「今がチャンスとばかりに」となる。続いて「値上げに」の「に」が「踏み切る」につながり、「踏み切る」が文末の名詞「動き」を修飾して「動きが続いている」となる。", "ex": "彼は待ってました<b>とばかりに</b>、手を挙げて発言し始めた。"},
"36835": {"point": "「～でなくてなんだろう」は「これこそまさに～だ」と強く断定する表現。自分ですら自分をよく知らないのに、他人が理解してくれると思うのは、まさに「馬鹿」だと強調している。", "steps": "「他人が」は「理解してくれる」の主語で、そこに「と思う」が続いて「他人が理解してくれると思う」となる。それを「のが」で名詞化して主語にし、「馬鹿」が文末の「でなくてなんだろう」につながる。", "ex": "命がけで子どもを守る母の姿、これが愛<b>でなくてなんだろう</b>。"},
"36836": {"point": "「～をものともせずに」は「～を問題にしないで、恐れずに」という意味で、困難に負けずに何かをする様子を表す。初舞台の不安や緊張に負けず、すばらしい演技を見せたことを評価している。", "steps": "「初舞台」に「という」が付いて名詞「不安や緊張」を修飾する。「不安や緊張を」の「を」は「ものとも」につながり、「せずに」が続いて「ものともせずに」となる。それが文末の「すばらしい演技を見せてくれた」を修飾する。", "ex": "彼は足のけが<b>をものともせずに</b>、最後まで走り抜いた。"},
"36837": {"point": "「AあってのB」は「Aがあるからこそ、Bが成り立つ」という意味。病気を克服できたのは家族の励ましがあったからこそだと、家族への感謝の気持ちを表している。", "steps": "「家族の」は名詞「励まし」を修飾する。「励まし」に「あっての」が付いて名詞「こと」を修飾し、「家族の励ましあってのこと」となる。「こと」が文末の「と感謝しています」につながる。", "ex": "お客様<b>あっての</b>商売だから、サービスには力を入れている。"},
"36838": {"point": "「身をもって」は「自分の体で、直接に」という意味で、実際に体験して知ることを表す。アルバイトを通して、働くことの厳しさを自分自身で体験したことを述べている。", "steps": "「働く」は名詞「こと」を修飾し、「ことの」が「厳しさ」につながって「働くことの厳しさを」となる。その後に「身を」「もって」が続き、「身をもって」が文末の「経験した」を修飾する。", "ex": "一人暮らしを始めて、親のありがたさを<b>身をもって</b>知った。"},
"36839": {"point": "「～かぎりだ」は感情を表す形容詞に付き、「とても～だ」と話し手の気持ちを強く表す。「～ており」は「～ていて」の書き言葉。余震が今も続いていて、非常に恐ろしいという気持ちを述べている。", "steps": "「今もなお」の後に主語「余震が」が来て、「続いて」「おり」で「余震が続いており」となる。「おり」で文をいったん中止し、その後に感情を表す「恐ろしい」が来て、文末の「かぎりだ」につながる。", "ex": "長年の夢がかなって、うれしい<b>かぎりだ</b>。"},
"36840": {"point": "「～たるもの」は「～という立場にある者は」という意味で、後にその立場にふさわしい態度が続く。「AあってのB」は「Aがあるからこそ成り立つB」。経営者なら、社員がいてこその会社だと忘れてはならないと述べている。", "steps": "「経営者」に「たるもの」が付いて主題を示す。続いて「社員」に「あっての」が付いて名詞「会社」を修飾し、「社員あっての会社」となる。「会社」は文末の「であることを忘れてはならない」につながる。", "ex": "教師<b>たるもの</b>、生徒の手本とならなければならない。"},
"36921": {"point": "「～すら」は「～さえ」という意味で、極端な例を挙げて「ほかはなおさらだ」と示す。「～ようでは」は「そんな状態では」という意味で、後に否定的な判断が続く。簡単な問題も解けない状態では大学進学は無理だと述べている。", "steps": "「こんな」は名詞「簡単な問題」を修飾し、「すら」が付いて極端な例を示す。その後に「解けない」が続き、「ようでは」で条件を表して、文末の「大学進学は無理にきまっている」につながる。", "ex": "自分の部屋の掃除<b>すら</b>できない<b>ようでは</b>、一人暮らしは無理だろう。"},
"36922": {"point": "「～のではあるまいか」は「～のではないだろうか」の書き言葉で、心配や推量を表す。小さな地震が続いていることから、近いうちに大地震が起こるのではないかと不安に思う気持ちを表している。", "steps": "「近いうちに」は「大地震が起こる」を修飾する。「大地震が起こる」に「の」が付き、「ではあるまい」「か」と続いて「大地震が起こるのではあるまいか」となる。それが文末の「と不安でたまらない」につながる。", "ex": "このままでは、地球の環境はますます悪化する<b>のではあるまいか</b>。"},
"36923": {"point": "「～ても差し支えない」は「～てもかまわない、問題ない」という意味の改まった表現。草刈の時には汚れても問題のない服を用意してほしいと、着ていく服の条件を述べている。", "steps": "「草刈の」は名詞「際」を修飾し、「際には」で時を表す。次に「汚れても」が「差し支えない」につながり、「汚れても差し支えない」と「長袖の」がどちらも文末の名詞「服」を修飾する。", "ex": "この書類は、鉛筆で書いて<b>も差し支えない</b>そうです。"},
"36924": {"point": "「～だけましだ」は「状況はよくないが、～という点ではまだよい」という意味。雪が降ってとても寒いが、風が吹かない点ではまだよいと、悪い状況の中にもよい点を見つけている。", "steps": "「こんなに」は「寒い」を修飾し、逆接の「のに」で「こんなに寒いのに」となる。その後に、よい点である「風が吹かない」が来て「だけ」が付き、文末の「ましかもしれない」につながる。", "ex": "給料は安いが、仕事がある<b>だけまし</b>だ。"},
"36925": {"point": "「～てくれてもいいだろうに」は「～してくれてもいいはずなのに（してくれない）」という意味で、相手への不満を表す。締め切り前で忙しいのだから少しは協力してほしいのに、手伝おうともしないという不満を述べている。", "steps": "「少しぐらいは」は「協力して」を修飾する。「協力して」の後に「くれても」が続き、「いいだろうに」で「協力してくれてもいいだろうに」となる。「だろうに」が逆接的に、後の「あの人は～手伝おうともしない」につながる。", "ex": "遅れるなら、電話の一本ぐらいくれ<b>てもいいだろうに</b>。"},
"36926": {"point": "「～べく」は動詞の辞書形に付いて「～するために」という意味を表す書き言葉。「お応えするべく」で、部屋にも食事にもこだわりたいという客の要望に応えるために、特別プランを用意したことを表す。", "steps": "「お部屋にも、お食事にも」は「こだわりたい」につながり、「こだわりたい」が「お客様」を修飾する。「お客様の」は名詞「ご要望」を修飾し、「ご要望に」の「に」が「お応えする」につながって、文末の「べく」に続く。", "ex": "新しい工場を建設する<b>べく</b>、用地を探している。"},
"36927": {"point": "「～てしかるべきだ」は「～するのが当然だ、～するのがふさわしい」という意味。メーカー側の対応のまずさは否定できないので、謝罪があるのが当然だという意見を述べている。", "steps": "「否定」の後に「できないので」が来て「否定できないので」と理由を表す。その後に主語「謝罪が」を置き、「あって」「しかる」と続けて「謝罪があってしかる」とし、文末の「べきだと思う」につながる。", "ex": "これだけ努力したのだから、もっと評価され<b>てしかるべきだ</b>。"},
"36928": {"point": "「～ならいざしらず」は「～ならともかく」という意味で、前の場合は別として、後の場合はそうはいかないことを表す。実際に読んだ人は別として、タイトルを見ただけでは内容がわからないと述べている。", "steps": "「実際に」は「読んだ」を修飾し、「読んだ」が「人」を修飾して「読んだ人ならいざしらず」となる。その後に「本のタイトルを」が来て「を」が「見た」につながり、「見た」が文末の「だけで」に続く。", "ex": "子ども<b>ならいざしらず</b>、大人がこんなことで泣くなんて。"},
"36929": {"point": "「～からなる」は「～で構成されている」という意味。「～さえ～ば」は「それだけで十分だ」という条件を表す。400ページもある分厚い問題集だが、やる気があれば誰でもできると述べている。", "steps": "「400ページから」の「から」は「なる」につながり、「400ページからなる」と「分厚い」がどちらも「ものだが」の「もの」を修飾する。逆接の「が」の後に「やる気さえ」が来て、文末の「あれば」につながり「やる気さえあれば」となる。", "ex": "日本の国会は、衆議院と参議院の二つ<b>からなる</b>。"},
"36930": {"point": "「～ないではすまない」は「～しないと許されない、どうしても～しなければならない」という意味で、状況や常識から見てそうするのが当然だということを表す。自分の不始末なので、責任を取らなければならないと述べている。", "steps": "「大変なことになってしまった」に「のだから」が付いて理由を表す。その後に「責任を」が来て「を」が「取らないでは」につながり、「すまない」が続いて、文末の「と思う」に続く。", "ex": "人の物を壊したのだから、弁償し<b>ないではすまない</b>だろう。"},
"36931": {"point": "「～てこそ」は「～して初めて」という意味で、そうすることで本当の価値が生まれることを強調する。困ったときに力になって初めて、本当の友達だと言えるという考えを述べている。", "steps": "「困ったとき、」の後に「力になって」が来て、「こそ」が付いて強調する。さらに「はじめて」を続けて条件を強め、「本当の友達と」の「と」が文末の「言える」につながる。", "ex": "実際に自分でやってみ<b>てこそ</b>、その難しさがわかるものだ。"},
"36932": {"point": "「～を限りに」は「～を最後として」という意味で、それまで続けてきたことをやめることを表す。夫が定年退職したので、社長にお中元を贈るのは今年を最後にしようと決めている。", "steps": "「高木社長に」の「に」は「贈る」につながり、「お中元を贈るのは」で主題を作る。その後に「今年を」が来て「を」が「限りに」につながり、文末の「しよう」に続いて「今年を限りにしよう」となる。", "ex": "彼は今シーズン<b>を限りに</b>現役を引退すると発表した。"},
"36933": {"point": "「～とは」は驚きや感動を表し、「～の極み」は「この上なく～だ」という意味。志望の大学に入れたうえに奨学金までもらえることへの驚きと、この上ない感激を表している。", "steps": "「志望の」は名詞「大学」を修飾し、「大学に入れて」の後に、追加を表す「まで」を使った「奨学金まで」が来て「もらえるとは」につながる。「とは」で驚きを示した後に「感激の」が来て、文末の「極みです」につながる。", "ex": "このような賞をいただけるとは、光栄<b>の極み</b>です。"},
"36934": {"point": "「～だろうに」は「～はずなのに（実際はそうならなかった）」という意味で、残念な気持ちや非難を表す。隠していれば見つからなかったはずなのに、机の上に置いておいたからばれたのだと述べている。", "steps": "「隠していれば」の条件を受けて「見つからない」が来て、「だろうに」で「見つからないだろうに」となる。その後に実際の行動として「机の上に」が来て「に」が「置いておく」につながり、「置いておく」が文末の「からばれたのだ」に続く。", "ex": "もう少し早く家を出れば間に合った<b>だろうに</b>、残念だ。"},
"36935": {"point": "「～といっても過言ではない」は「～と言っても言い過ぎではない」という意味で、話し手の強い主張を表す。今の農村は高齢者が支えているという現状を、「高齢者によって守られている」と強く述べている。", "steps": "「高齢者によって」は受身の「守られている」につながり、「農村は高齢者によって守られている」となる。その後に「といっても」「過言では」が続き、文末の「ありません」で「といっても過言ではありません」となる。", "ex": "彼はこの分野の第一人者だ<b>といっても過言ではない</b>。"},
"36936": {"point": "「～ねばならない」は「～なければならない」の書き言葉で、「する」は「せねばならない」となる。「～を禁じ得ない」は「～の気持ちを抑えられない」という意味。楽しみにしていた旅行を取りやめなければならなかったと聞き、同情を抑えられないと述べている。", "steps": "「予約した」は名詞「旅行」を修飾し、「旅行を」の「を」が「キャンセルせねばならなかった」につながる。その後に伝聞の「そうだ」のて形「そうで」が付いて理由を表し、文末の「まったく同情を禁じ得ない」につながる。", "ex": "市民の安全を守るために、早急に対策を講じ<b>ねばならない</b>。"},
"36937": {"point": "「～だにしない」は「少しも～しない」という意味で、「想像だにしない」「微動だにしない」など限られた語と使う。日本を代表する大企業が倒産するなど、誰も少しも想像しなかったことが起きていると述べている。", "steps": "「倒産する」に「など」が付いて想像もしなかった内容を示し、その後に主語「だれも」が来る。「想像」に「だに」が付いて「想像だに」となり、文末の「しなかった」につながって、「だれも想像だにしなかった」が名詞「こと」を修飾する。", "ex": "彼が会社を辞めるとは、想像<b>だにしなかった</b>。"},
"36938": {"point": "「～ずじまい」は「（～しようと思っていたのに）結局～しないで終わる」という意味で、残念な気持ちを表す。本をたくさん借りたのに、時間がなく結局読まないまま終わったことを述べている。", "steps": "「借りたのは」の後に「よいが」が来て「借りたのはよいが」と逆接になる。その後に理由の「時間がなく」が続き、「読まず」に「じまいに」が付いて「読まずじまいに」となり、文末の「終わった」につながる。", "ex": "旅行中は忙しくて、お土産を買わ<b>ずじまい</b>だった。"},
"36939": {"point": "「～までもなく」は「～する必要もなく」、「～ながらにして」は「～の状態のままで」という意味。情報化時代になり、わざわざ現地に行く必要もなく、自宅にいたままで世の中の動きがわかるようになったことを表す。", "steps": "「わざわざ」は「現地に行く」を修飾し、「までもなく」が付いて「現地に行くまでもなく」となる。次に「自宅に」の「に」が「居ながらに」につながり、直後の「して」が付いて「自宅に居ながらにして」となる。", "ex": "わざわざ説明する<b>までもなく</b>、彼はすべてを理解していた。"},
"36940": {"point": "「～に越したことはない」は「～するのが最もよい、～したほうがいい」という意味。治安は悪くないと聞いていても、やはり注意したほうがいいと助言している。「～そうですが」は伝聞の「そうだ」に逆接の「が」が付いた形。", "steps": "「悪くはない」に伝聞の「そうですが」が付いて逆接になる。その後に「やはり」が来て「注意する」を修飾し、「注意する」に「に越した」が付いて、文末の「ことはないでしょうね」につながる。", "ex": "健康のためには、早寝早起きをする<b>に越したことはない</b>。"},
"37021": {"point": "「～によるところが大きい」は「～が大きな原因・理由になっている」という意味。島の人々の平均寿命が長い大きな理由は、温暖な気候と多彩な食材の効能だと考えられていることを述べている。", "steps": "「温暖な気候と」の「と」で名詞を並べ、「多彩な食材の」とともに名詞「効能」につながって「温暖な気候と多彩な食材の効能」となる。「効能による」の「による」が「ところが大きい」につながり、文末の「と考えられている」に続く。", "ex": "今回の成功は、チーム全員の努力<b>によるところが大きい</b>。"},
"37022": {"point": "「AつBつ」は反対の意味の動詞を並べ、二つの動作が交互に繰り返されることを表す。「行きつ戻りつ」で、寒い日と暖かい日を繰り返しながら少しずつ春らしくなる様子を表している。「～めく」は「～らしくなる」という意味。", "steps": "「行きつ」と「戻りつ」を並べて「行きつ戻りつ」とし、その後に「しながら」を続ける。次に、「春」に「めく」が付いた「春めいて」が来て、文末の「来ました」につながり「春めいて来ました」となる。", "ex": "彼は駅の前を<b>行きつ戻りつ</b>しながら、恋人を待っていた。"},
"37023": {"point": "「～べくして～」は同じ動詞を繰り返し、「当然そうなるはずで、そのとおりそうなった」という意味を表す。大方の予想を裏切っての合格だったので、当然の結果として受かったというものではまったくないと述べている。", "steps": "動詞の辞書形「受かる」に「べくして」が付き、同じ動詞の過去形「受かった」が続いて「受かるべくして受かった」となる。その後に「という」が来て、文末の「ようなもの」につながる。", "ex": "練習量が圧倒的だったのだから、あのチームは勝つ<b>べくして</b>勝ったのだ。"},
"37024": {"point": "「～たところで」は「～しても（無駄だ、期待する結果にならない）」という意味で、後に否定的な内容が続く。「～はしない」は動詞の連用形に「は」を入れた強い否定。他国のせいにしても何の解決にもならないと述べている。", "steps": "「よその国のせいだと」の「と」は「言った」につながり、「ところで」が付いて「言ったところで」となる。次に「何の解決にも」が「なりは」につながり、文末の「しない」で「何の解決にもなりはしない」となる。", "ex": "今さら後悔した<b>ところで</b>、過去は変えられない。"},
"37025": {"point": "「～か否か」は「～かどうか」の書き言葉。「～たところ」は「～したら（その結果）」という意味で、後に結果が続く。食品の安全性に不安を感じているかどうかを尋ねた結果、98％が不安を感じていると答えたことを述べている。", "steps": "「不安を感じているか」の後に「否かに」が来て、「ついて」が続き「～か否かについて」となって「尋ねた」を修飾する。「尋ねた」に「ところ」が付いて「尋ねたところ」となり、その結果として読点の後の「全体の98％の者が～回答した」につながる。", "ex": "賛成か<b>否か</b>を尋ねた<b>ところ</b>、半数以上が賛成と答えた。"},
"37026": {"point": "「～としたところで」は「～の立場であっても、～だとしても」という意味で、後に否定的な判断が続く。専門家ではないのだから、大学の教授であってもその解決方法はわかるはずがないと述べている。", "steps": "「大学の教授」に「とした」「ところで」が続いて「大学の教授としたところで」となる。その後に「それについて」が来て、「解決方法」に文末の「など」が付き、「解決方法など分かるはずがない」となる。", "ex": "社長<b>としたところで</b>、この問題を一人で解決することはできないだろう。"},
"37027": {"point": "「～を受けて」は「～に応じて、～をきっかけとして」という意味。消費者アンケートの結果に応じて、商品を改善したり、次の商品開発に生かしたりしていく方針を述べている。", "steps": "「消費者を対象とした」は名詞「アンケート調査」を修飾し、「アンケート調査の結果を」の「を」が「受けて」につながる。次に「商品を改善」が来て、「あるいは」で「次の商品開発に」と並べ、文末の「生かしていく方針だ」につながる。", "ex": "台風の接近<b>を受けて</b>、多くの学校が休校を決めた。"},
"37028": {"point": "「～を機に」は「～をきっかけにして」という意味で、ある出来事を新しいことを始める機会とすることを表す。オフィスの拡張移転をきっかけに、オフィス家具を買い替えることになった。", "steps": "「今回のオフィスの」は名詞「拡張移転」を修飾し、「拡張移転を」の「を」が「機に」につながる。次に「オフィス家具の」が名詞「買い替え」を修飾し、「買い替えを」が文末の「行う」につながる。", "ex": "結婚<b>を機に</b>、たばこをやめた。"},
"37029": {"point": "「～にかこつけて」は「～を口実にして」という意味で、本当の理由ではないことを言い訳にする場合に使う。仕事の忙しさを口実にして、近所付き合いを妻に任せきりにしていることを表す。", "steps": "「仕事の」は名詞「忙しさ」を修飾し、「忙しさに」の「に」が「かこつけて」につながる。次に「近所の人との」が名詞「付き合い」を修飾して「付き合いは」と主題を作り、文末の「妻にまかせっきりだ」につながる。", "ex": "出張<b>にかこつけて</b>、有名な観光地を見物してきた。"},
"37030": {"point": "「～のみにとどまらず」は「～だけで終わらず、さらに範囲が広がる」という意味で、後に「～にも」が続くことが多い。彼の才能が音楽だけでなく、ほかの芸術分野にまで広がっていることを表す。", "steps": "「音楽の世界」に「のみに」が付き、「とどまらず」が続いて「音楽の世界のみにとどまらず」となる。その後に「ほかの芸術分野にも」が来て、「にも」が「及んで」につながり、文末の「いる」で「及んでいる」となる。", "ex": "環境問題は一つの国<b>のみにとどまらず</b>、世界全体の問題である。"},
"37031": {"point": "「～にかかっている」は「～によって決まる」という意味で、「いかに～か」と共に使い、何が結果を左右するかを表す。企業合併の成功はシステムをどう統合するかで決まると、「といっても過言ではない」で強く述べている。", "steps": "「いかに」の後に、「統合する」を修飾する「有機的に」が来て、「統合するかに」の「に」が「かかっている」につながる。その後に「といっても」が続き、文末の「過言ではない」で「といっても過言ではない」となる。", "ex": "試験に合格できるかどうかは、毎日の努力<b>にかかっている</b>。"},
"37032": {"point": "「～ばいいというものではない」は「～さえすれば十分だというわけではない」という意味で、一般的な考え方を部分的に否定する。仕事は成果が大切で、単に時間をかけてがんばればいいわけではないと述べている。", "steps": "「単に」の後に「時間をかけて」が来て、「がんばれば」を修飾する。「がんばれば」に「いいという」が続き、「ものではない」で「がんばればいいというものではない」となって、文末の「と思う」につながる。", "ex": "薬はたくさん飲め<b>ばいいというものではない</b>。"},
"37033": {"point": "「～そびれる」は動詞の連用形に付き、「～する機会を逃して、できなくなる」という意味。眠くて早くベッドに入ったのに、なぜか寝る機会を逃してしまい、眠ったのは11時頃だったことを表す。", "steps": "「入ったが」の逆接の後に「なぜか」が来て「寝そびれて」を修飾する。次に「眠りに」の「に」が「落ちた」につながり、「眠りに落ちた」が直後の「の」で名詞化されて、「のは11時頃であった」となる。", "ex": "忙しくて、昼ご飯を食べ<b>そびれて</b>しまった。"},
"37034": {"point": "「～ものの」は「～けれども」という意味の逆接で、前のことから予想されることと違う事実が後に続く。「～てみせる」は強い決意を表す。絶対成功させると公言したが、実はそれほど自信があるわけではないと述べている。", "steps": "「絶対成功させて」の「て」は「みせると」につながり、「と」が「公言した」に続く。「公言した」に逆接の「ものの」が付き、その後に「それほど」が来て、文末の「自信があるわけではない」につながる。", "ex": "免許は取った<b>ものの</b>、まだ一人で運転するのは怖い。"},
"37035": {"point": "「～てはばからない」は「遠慮せずに堂々と～する」という意味。インドでの滞在経験が長い山田さんが、インドを第二のふるさとだと周りに遠慮せず言っていることを表す。", "steps": "「インドを」は「言って」の目的語になり、「第二の」が名詞「ふるさと」を修飾して「第二のふるさとと」となる。「と」は「言って」につながり、文末の「はばからない」で「言ってはばからない」となる。", "ex": "彼は、自分こそが世界一の料理人だと言っ<b>てはばからない</b>。"},
"37036": {"point": "「～だけにとどまらず」は「～だけで終わらず、さらに範囲が広がる」という意味で、後に「～にも」が続くことが多い。経営破綻の影響がアメリカ国内だけでなく、世界の金融市場にまで及んだことを表す。", "steps": "「アメリカだけに」の「に」は「とどまらず」につながり、「アメリカだけにとどまらず」となる。その後に「世界の金融市場」が来て「にも」が付き、文末の「極めて大きな影響を与えた」につながる。", "ex": "その歌手の人気は国内<b>だけにとどまらず</b>、アジア各国に広がっている。"},
"37037": {"point": "「～に言わせると」は「～の意見では」という意味で、ある人の見方や意見を紹介するときに使う。多くの専門家の意見では、政府の景気対策が効果を上げ、景気は回復に向かっていると述べている。", "steps": "「多くの専門家に」の「に」は「言わせると」につながる。その後に「政府の」が名詞「景気対策」を修飾して「政府の景気対策が」と主語になり、「効果を」が文末の「あげており」につながって「効果をあげており」となる。", "ex": "母<b>に言わせると</b>、私は子どものころから頑固だったそうだ。"},
"37038": {"point": "「～なんか」は「～など」のくだけた言い方で、物事を軽く見る気持ちを表す。「～はしない」は動詞の連用形に「は」を入れた強い否定。不景気なので、人々がファミリーレストランのような所に行こうとしないことを表している。", "steps": "「不景気」に「なので」が付いて理由を表す。次に「ファミリーレストラン」に「なんかに」が付いて「ファミリーレストランなんかに」となり、「に」が「行きは」につながって、文末の「しない」で「行きはしない」となる。", "ex": "疲れているときは、料理<b>なんか</b>したくない。"},
"37039": {"point": "「～つつある」は動詞の連用形に付き、「変化が今まさに進んでいる」ことを表す書き言葉。夕日が今、海の向こうに沈んでいく途中であることを表している。", "steps": "「海の向こうに」の「に」は「沈み」につながり、「沈み」に「つつある」が付いて「沈みつつある」となる。それが名詞「夕日」を修飾し、「夕日を」が文末の「眺めながら」につながる。", "ex": "地球の温暖化は、年々進み<b>つつある</b>。"},
"37040": {"point": "「～をおして」は「（反対や困難を）無理に押し切って」という意味で、「～てでも」は犠牲を払っても実現させる強い意志を表す。理事会が反対しても工場移転の方針を通そうとする、社長の強い姿勢を表している。", "steps": "「理事会の反対を」の「を」は「おして」につながり、「でも」が付いて「理事会の反対をおしてでも」となる。それが「貫く」を修飾し、「貫く姿勢を」が文末の「見せている」につながる。", "ex": "彼は病気<b>をおして</b>、大切な会議に出席した。"},
"35016_0": {"point": "「へと」は方向を表す「へ」に「と」が付いた形で、移動や変化の向かう先を強調する。高知で育った筆者が、大学進学のために目的地の東京に向かって旅立ったことを表すので、「東京へと旅立った」となる。", "opts": ["", "にも：「東京にも旅立った」では、ほかの場所に加えて東京にも行ったという意味になり、初めて故郷を離れた話に合わない", "から：「東京から」は出発点を表すので、高知から東京へ向かったという内容と逆になる", "でと：「でと」という助詞の組み合わせはなく、日本語として成り立たない"], "ex": "列車は雪の降る北の町<b>へと</b>走り続けた。"},
"35016_1": {"point": "空欄の後で「東京という都市になじめず」「逃げるようにして高知の実家に舞い戻った」と述べている。頼るものがなく不安だという意味の「心細い」が、慣れない大都会での一人暮らしの気持ちに合う。", "opts": ["興味深い：おもしろくて関心をひかれるという肯定的な意味で、「なじめず」「逃げるように」という後の内容と合わない", "", "居心地の良い：その場所にいて気持ちが落ち着くという意味で、東京になじめなかった内容と矛盾する。本文では故郷の家庭について使われている", "期待に満ちた：前向きな気持ちを表し、逃げるように実家に戻ったという内容と合わない"], "ex": "初めての海外旅行で道に迷い、とても<b>心細い</b>思いをした。"},
"35016_2": {"point": "前では故郷の自然や家庭の良さを「何ものにも代え難い」と述べているのに、後では「もう故郷に長く帰省することもなくなった」と反対の内容が続く。逆接の「しかしながら」が入る。", "opts": ["それゆえに：「だから」という順接で理由と結果を表す。故郷が良いから帰省しなくなるという関係にはならない", "", "すなわち：「つまり」という言い換えを表すが、前後は同じ内容ではないので合わない", "しかも：「その上」と同じ方向の内容を付け加える添加で、反対の内容をつなげない"], "ex": "計画は順調に進んでいた。<b>しかしながら</b>、予算不足のため中止せざるを得なくなった。"},
"35016_3": {"point": "前の文で「故郷から離れることによって、…自立するきっかけをつかむことができた」と述べている。それを受けて、その経験がなければ親離れができなかったかもしれないと言っているので、「故郷を離れる」経験が入る。", "opts": ["大学を辞める：本文に大学を辞めた話はなく、親から自立するきっかけとしても述べられていない", "故郷の自然を味わう：故郷にいてする経験であり、故郷を離れたことで自立できたという内容と逆になる", "", "高校時代の友達にあう：帰省したときの出来事で、親からの自立のきっかけとして述べられていない"], "ex": "進学のために<b>故郷を離れる</b>若者は少なくない。"},
"35016_4": {"point": "直前で「いつの日か故郷に帰ることもできるし、ずっと故郷を離れたままでいることもできる」と述べている。帰っても離れていてもよいという自由を与えてくれるものこそ真の「故郷」だと、文章全体のテーマをまとめている。", "opts": ["人生：帰ることも離れたままでいることもできる対象は故郷であり、「人生」では前の文とつながらない", "自然：故郷の自然は心に宿っていると述べられているが、帰る・離れるという自由を与えるものとしては述べられていない", "都市：筆者が暮らした東京などの都市は、帰るか離れるかという話の対象ではない", ""], "ex": "何年たっても、生まれ育ったこの町が私の<b>故郷</b>だ。"},
"35116_0": {"point": "「男性が仕事をして女性が家事と子育てをする」は、男女がそれぞれ別の仕事を受け持つ形である。それを「という」でまとめているので、仕事を分けて受け持つという意味の「役割分担」が入る。", "opts": ["責任転嫁：自分の責任を他人に押しつけることで、家庭での仕事の分け方を表さない", "自業自得：自分の行いの報いを自分自身が受けることで、文脈と合わない", "", "共同育児：夫婦などが一緒に子育てをすることで、女性が子育てをするという前の内容と矛盾する"], "ex": "共働きの家庭では、家事の<b>役割分担</b>を決めておくことが大切だ。"},
"35116_1": {"point": "「とりわけ〜のほう」は、直前の男女の役割分担のうち、どちらの変化が大きいかを述べている。後に挙げる「既婚女性の就労」や、外で仕事をする女性が増えているという最後の段落の内容から、変化が顕著なのは「女性」のほうである。", "opts": ["男性：男性は戦前も戦後も主に仕事をしており、変化が顕著だとは述べられていない", "", "高齢者：前の文は男女の役割について述べており、高齢者はその比較の対象になっていない", "未婚者：未婚化は後で触れられるが、前の文の男女の役割の話とつながらない"], "ex": "この会社では、管理職として活躍する<b>女性</b>が年々増えている。"},
"35116_2": {"point": "少子化が進めば、生産活動に参加する働く世代の割合は減っていく。後の「そのため、高齢者の定年退職の時期がさらに遅くなる」も働き手の不足を示しているので、「減少している」が入る。", "opts": ["", "増えつつある：少子化が進んで働く人の割合が増えるという関係にはならず、定年が遅くなる理由にもならない", "減ることはない：少子化が進めば働く人の割合は減るので、前の内容と矛盾する", "急増している：「増えつつある」と同じく、少子化の結果とは逆の内容になる"], "ex": "地方では若者の人口が年々<b>減少している</b>。"},
"35116_3": {"point": "「若者の割合を増加させる」ためには、生まれる子どもの数を増やす必要がある。少子高齢化の対策として、子どもが生まれる割合を表す「出生率」を上昇させることが求められている。", "opts": ["就業率：働いている人の割合のことで、上昇しても若者の割合を増やすことにはならない", "結婚率：結婚する人の割合で、若者の割合を直接増やすものではなく、子どもの数を増やす対策を述べる文脈に合わない", "", "未婚率：結婚していない人の割合で、上昇させると少子化が進む方向になり、文脈と逆になる"], "ex": "政府は<b>出生率</b>を上げるため、子育て支援に力を入れている。"},
"35116_4": {"point": "前の文では経済的な理由で子供を産まない家庭が多いことを述べ、後では「独身の自由と気楽さを失いたくない」という別の事情を「〜ことも」と付け加えている。添加を表す「それに加えて」が入る。", "opts": ["それにもかかわらず：前の内容から予想されることと反対の結果が続く逆接で、別の事情を付け加える文に合わない", "それによって：前の内容が原因や手段になる関係を表すが、子供を産まない家庭が多いことで独身の自由を求める人が増えるわけではない", "それとは裏腹に：前と正反対の内容が続く場合に使う。後の文は前と同じ方向の事情を付け加えているので合わない", ""], "ex": "彼は英語が堪能だ。<b>それに加えて</b>、中国語も少し話せる。"},
"36641_0": {"point": "「〜んばかりに」は動詞のない形に付き（争わない→争わんばかり）、「今にも〜しそうな様子で」という意味を表す。「先を争わんばかりにして水を飲むのか」という予想が、「〜と思いきや、整然と列を作り」で裏切られる流れになる。", "opts": ["争ったばかりに：「〜たばかりに」は「〜たせいで（悪い結果になった）」という意味で、後に後悔や悪い結果が続く。予想した様子を述べる文に合わない", "", "争わんがために：「〜んがため」は「〜しようという目的で」という意味の硬い表現。先を争うことを目的に水を飲むことになり、意味が通らない", "争うべからざる：「〜べからざる」は「〜してはならない」という意味で名詞を修飾する形。後の「水を飲む」に続かず、意味も合わない"], "ex": "店員は早く帰れと言わ<b>んばかりに</b>、閉店の準備を始めた。"},
"36641_1": {"point": "後の「社会のマナーまでも」の「までも」と呼応して「AだけでなくBまでも」の形になる。スポーツの技術に加えて、社会のマナーまで自然に教えられる指導者が増えてほしいと述べている。", "opts": ["技術をおいて：「〜をおいて」は「〜以外に（ない）」という意味で、後に「ほかにない」などが続く。技術とマナーを両方教えるという内容と合わない", "技術にひきかえ：「〜にひきかえ」は「〜とは反対に」と二つを対比する表現で、技術もマナーも教えるという内容と合わない", "", "技術なくして：「〜なくして」は「〜がなければ（〜できない）」という意味で、後に否定的な内容が続く。この文の後半とつながらない"], "ex": "彼は歌<b>だけでなく</b>、ダンスまでもプロ並みにうまい。"},
"36643_0": {"point": "「〜てからというもの」は「〜して以来ずっと」という意味で、あることをきっかけに状態が変わり、それが続いていることを表す。少子化問題が取りざたされるようになって以来、こんな会話が普通にされるようになったという変化を述べている。", "opts": ["なったところで：「〜たところで」は「〜しても（無駄だ）」という逆接を表し、後の「〜ようになった」という変化の文と合わない", "なり次第：「〜次第」は「〜したらすぐに」という意味で、後に依頼や意志など未来のことが続く。過去の変化を述べる文に合わない", "なってからでなければ：「〜てからでなければ」は後に「〜できない」などの否定が続く形で、この文と合わない", ""], "ex": "子供が生まれ<b>てからというもの</b>、夫は毎日早く帰宅するようになった。"},
"36643_1": {"point": "「Aは言うまでもなく、B」は「Aはもちろん、Bも」という意味で、Aは当然として、さらにBを付け加える。経済支援は当然のこととして、仕事と育児の両立支援など様々な手立てを講じてきたと述べている。", "opts": ["とはいえ：「〜とはいえ」は「〜とはいっても」という逆接で、経済支援と両立支援を並べる文脈に合わない", "", "にいたっても：「〜に至っても」は「〜という極端な段階になっても（まだ）」という意味で、対策を並べる文に合わない", "にひきかえ：「〜にひきかえ」は二つを反対のものとして対比する表現で、同じ方向の対策を並べる文と合わない"], "ex": "彼女は英語<b>は言うまでもなく</b>、フランス語やドイツ語も話せる。"},
"36643_2": {"point": "「いくら〜たところで」は「どんなに〜しても（期待した結果にはならない）」という意味の逆接仮定を表す。支援をどれだけ充実させても、少子化や人口減少の流れはすぐには変えられないと述べている。", "opts": ["", "させたとたんに：「〜たとたん」は「〜したらすぐに（予想外のことが起きた）」と過去の事実に使う表現で、「いくら」と呼応しない", "させてみたら：「〜てみたら」は試した結果を述べる順接で、「いくら」と呼応せず、後の否定的な判断ともつながらない", "させてみたところ：「〜たところ」は実際にした結果を述べる表現で、「いくら」と呼応する仮定の逆接にならない"], "ex": "いくら説明し<b>たところで</b>、彼は納得しないだろう。"},
"36646_0": {"point": "前ではニュージーランドやドイツの質素な包装を述べ、後では「日本はどうだろうか」と過剰包装の日本を取り上げている。二つを比べて「それとは反対に」という意味を表す「それにひきかえ」が入る。", "opts": ["その代わりに：あることの代わりに別のことをするという交換を表し、海外と日本を対比する文脈に合わない", "それをぬきにしては：「それなしでは〜できない」という意味で、後に否定的な結果が続く形。「日本はどうだろうか」とつながらない", "それはもとより：「それはもちろん（〜も）」と同じ方向のことを付け加える表現で、対比の文脈に合わない", ""], "ex": "兄は社交的だ。<b>それにひきかえ</b>、弟は人見知りでおとなしい。"},
"36646_1": {"point": "「〜きらいがある」は「〜という（よくない）傾向がある」という意味で、名詞には「の」を介して付く。「再三指摘されているように」とあり、日本の過剰包装という好ましくない傾向を批判的に述べている。", "opts": ["きざしがある：「きざし」は物事が起こる前ぶれのことで、すでに再三指摘されている過剰包装の傾向を表さない", "", "つもりがある：人の意図を表す表現で、「過剰包装の」に続かず、意味も通らない", "きっかけがある：「きっかけ」は物事が始まる原因や機会のことで、過剰包装という傾向を述べる文に合わない"], "ex": "彼は物事を悲観的に考える<b>きらいがある</b>。"},
"36648_0": {"point": "「〜までもない」は辞書形に付いて「わざわざ〜する必要がない（それほど明らかだ）」という意味を表す。たばこの害は広く知られていて改めて論じる必要もないと述べ、本題の非喫煙者への害へと話を進めている。", "opts": ["ほどもない：「論じるほどもない」は普通の言い方ではなく、「わざわざ論じる必要がない」という意味は「までもない」で表す", "", "始末だ：「〜始末だ」は悪い経過の末に好ましくない結果になったことを表し、「論じる始末だ」では意味が通らない", "にたえない：「見るにたえない」のように「ひどくて〜していられない」という意味で、害が明らかだという文脈に合わない"], "ex": "こんな簡単な問題なら、先生に聞く<b>までもない</b>。"},
"36648_1": {"point": "「〜まい」は「〜ないだろう」という否定の推量を表す。前の「さほど」は後に否定を伴う副詞なので、「さほど社会問題にはなるまい（それほど社会問題にはならないだろう）」となる。", "opts": ["", "なるだろう：肯定の推量で、後に否定を伴う「さほど」と呼応しない", "なりかねない：「〜かねない」は「〜する恐れがある」という悪い可能性を表す肯定の意味で、「さほど」と呼応しない", "なろう：意志や推量を表す肯定の形で、否定と呼応する「さほど」と合わない"], "ex": "この程度の雨なら、試合は中止にはなる<b>まい</b>。"},
"36648_2": {"point": "「〜極まりない」は「この上なく〜だ」という意味で、ナ形容詞の語幹などに付き、強い非難を表すことが多い。窓から吸い殻を捨てる行為は後続の二輪車にとって非常に危険で、事故にもつながると批判している。", "opts": ["危険のみではない：「〜のみではない」は「〜だけではない」という意味で、後にほかの例が続くはずだが、次の文は危険の具体例でつながらない", "危険次第だ：「〜次第だ」は「〜によって決まる」という意味で、「危険次第だ」では意味が通らない", "", "危険にかたくない：「〜にかたくない」は「想像にかたくない」のように「容易に〜できる」という意味で、「想像」「察する」などに付き、「危険」には付かない"], "ex": "夜中に大声で電話をするなんて、迷惑<b>極まりない</b>。"},
"36741_0": {"point": "「〜とあいまって」は「〜と重なって・〜も加わって」という意味で、ある要因がほかの要因と結びついて、より大きな結果を生むことを表す。国家財政の危機的状況も加わって、学費値上げの検討が本格化したことを表している。", "opts": ["", "と言えば：「〜と言えば」はある話題から連想したことを述べる表現で、値上げを検討し始めた理由を表せない", "を皮切りに：「〜を皮切りに」は「〜を始まりとして次々に」という意味で、同じ種類のことが続いて起こる場合に使い、ここでは合わない", "をよそに：「〜をよそに」は「〜を気にせずに」という意味で、財政危機を無視して値上げを検討することになり、意味が通らない"], "ex": "美しい景色<b>とあいまって</b>、その音楽はいっそう心に響いた。"},
"36741_1": {"point": "「〜ゆえ（に）」は「〜ので・〜ために」という意味の硬い表現で、理由を表す。国からの補助がゼロになるため、国立大学の学費が私立大学と同じくらいになると予想されるという因果関係を表している。", "opts": ["かわりに：「〜かわりに」は代わりに別のことをするという代替や交換を表し、補助がなくなることが学費上昇の理由だという関係を表せない", "くせに：「〜くせに」は「〜のに」と人を非難する気持ちを表す逆接で、理由を述べる文に合わない", "にもまして：「〜にもまして」は「以前にもまして」のように「〜以上に」という意味で、「ゼロになるにもまして」では意味が通らない", ""], "ex": "経験が浅い<b>ゆえ</b>、判断を誤ることもあるだろう。"},
"36743_0": {"point": "「〜しまつだ」は、悪い状態が続いた末に、最後にはこんなひどい結果になったという意味を表す。盗難が相次ぎ、ついには倉庫の新米までごっそり盗まれるに至ったという好ましくない結末を述べている。", "opts": ["しまいだ：「〜たらおしまいだ」のように「終わりだ・もうだめだ」という意味で使い、「盗まれるしまいだ」という形はない", "かぎりだ：「〜かぎりだ」は「うれしいかぎりだ」のように感情を表す言葉に付いて「非常に〜だ」という意味を表し、この文に合わない", "", "までだ：「〜までだ」は「（ほかに方法がなければ）〜するだけだ」という覚悟などを表し、ひどい結果を述べる文に合わない"], "ex": "彼は遅刻を繰り返し、ついには無断で欠勤する<b>しまつだ</b>。"},
"36743_1": {"point": "「〜にかかわる」は「命にかかわる」のように「〜に重大な影響を及ぼす」という意味で、深刻な事柄に使う。「死活にかかわる問題」で、農家が生きていけるかどうかを左右する重大な問題であることを表す。", "opts": ["にかたくない：「〜にかたくない」は「想像にかたくない」のように「容易に〜できる」という意味で、「死活」には付かない", "", "にもとづく：「〜にもとづく」は「〜を根拠・基準にする」という意味で、「死活にもとづく問題」では意味が通らない", "に相違ない：「〜に相違ない」は「〜に違いない」という確信を表す表現で、「死活に相違ない」では意味が通らない"], "ex": "小さなミスが、人の命<b>にかかわる</b>こともある。"},
"36743_2": {"point": "「〜てやまない」は「願う・祈る・期待する」などの動詞のて形に付き、「心から強く〜し続けている」という意味を表す。「絶滅を願ってやまない」で、社会不安を助長する事件がなくなることを強く願う筆者の気持ちを表す。", "opts": ["かねない：「〜かねない」はマス形の語幹に付いて悪い結果になる可能性を表し、「願って」というて形には付かない", "きわまりない：「〜きわまりない」は「失礼きわまりない」のように形容詞の語幹などに付き、て形には付かない", "すまない：「〜てすまない」は相手に謝る気持ちを表し、事件の絶滅を願う文と合わない", ""], "ex": "子どもたちの健やかな成長を願っ<b>てやまない</b>。"},
"36746_0": {"point": "「〜なり」は辞書形に付いて「〜するとすぐに」という意味を表し、前の動作の直後に次の動作が起こることを示す。「酒かす、あります」という看板を見つけてすぐに買い求めたことを表し、後の「早速」とも合う。", "opts": ["見つけると思いきや：「〜と思いきや」は「〜と思ったが、意外にも」という意味で、予想と反対の結果が続く。看板を見てすぐ買ったという文に合わない", "見つけるこそ：「こそ」は名詞や「〜からこそ」「〜てこそ」の形で強調に使い、辞書形に直接付けて「見つけるこそ」とは言わない", "", "見つけるほど：「〜ほど」は程度や比例を表し、見つけた直後に次の行動をすることを表せない"], "ex": "息子は家に帰る<b>なり</b>、自分の部屋に閉じこもってしまった。"},
"36746_1": {"point": "「AといいBといい」は、いくつかの点を取り上げて「どの点から見ても」と評価する表現で、後に「抜群だ」などの評価が続く。手作りの甘酒が、味も香りもすばらしかったことを表している。", "opts": ["味をよそに香りをよそに：「〜をよそに」は「〜を気にせずに」という意味で、二つ重ねる形はなく、「抜群だった」という評価とも合わない", "味であり香りであり：「であり」は「である」の中止形で、重ねても「どの点から見ても」という評価の意味にならず、文が成り立たない", "味といっても香りといっても：「〜といっても」は「〜とはいうものの（実際は）」という逆接で、重ねて評価を表す形ではない", ""], "ex": "この店は、料理<b>といい</b>サービス<b>といい</b>、申し分ない。"},
"36746_2": {"point": "「〜ならではの」は名詞に付いて「〜だけが持つ・〜でなければ味わえない」という意味を表し、後の名詞を修飾する。冬にしか来ない客を覚えていてお酒のことを教えてくれる交流は、個人商店だからこそだと評価している。", "opts": ["", "めく：「〜めく」は「春めく」「冗談めいた」のように「〜らしい様子になる」という意味で、「個人商店めく触れ合い」とは言わない", "かぎりの：「今日かぎりの」「その場かぎりの」のように範囲を限定する表現で、そのものだけが持つよさという評価の意味を表せない", "まじきの：「〜まじき」は「教師にあるまじき行為」のように「あってはならない」という意味で、名詞を直接修飾し、「の」は付かない"], "ex": "地元の食材を使った、この町<b>ならではの</b>料理を味わった。"},
"36749_0": {"point": "「〜に即して」は「〜に合わせて・〜に従って」という意味で、事実や状況、規則などに合うようにすることを表す。社会生活の変化に合わせて常用漢字を増やすことになったという意味になる。", "opts": ["に至って：「〜に至って」は「〜という（極端な）段階になってやっと」という意味で、後に「ようやく〜した」などが続く。ここでは意味が合わない", "に限って：「〜に限って」は「〜の場合に限って（特に悪いことが起こる）」などの意味で、常用漢字が増えた根拠を表せない", "", "に関して：「〜に関して」は「〜について」と話題を示す表現で、変化に合わせるという意味を表せない"], "ex": "実情<b>に即して</b>、計画を見直す必要がある。"},
"36749_1": {"point": "「〜からといって」は「〜という理由だけで（必ずしも〜とは言えない）」という意味で、後に「〜わけにはいかない」「〜とは限らない」などの否定が続く。常用漢字になったという理由だけで、すぐにルビなしで使えるわけではないと述べている。", "opts": ["からいって：「〜からいって」は「立場からいって」のように名詞に付いて「〜から判断して」という意味を表し、「なったからいって」という形にはならない", "", "からこそ：「〜からこそ」は「まさに〜だから」と理由を強調する順接で、後の否定の内容と合わない", "からというもの：「〜てからというもの」は「〜して以来ずっと」という意味でて形に付き、「なったからというもの」という形はない"], "ex": "値段が高い<b>からといって</b>、品質がいいとは限らない。"},
"36841_0": {"point": "「Aは言うに及ばず、B（も）」は「Aは言うまでもなく、Bも」という意味で、Aは当然として、さらに重要なBを付け加える。引っ越しの大変さはもちろん、知り合いのいない土地への移転そのものの難しさを痛感したと述べている。", "opts": ["と言わんばかりに：「〜と言わんばかりに」は「今にも〜と言いそうな様子で」という意味で、人の態度を描写する表現。ここでは意味が通らない", "をものともせず：「〜をものともせず」は「困難を恐れずに立ち向かって」という意味で、後に困難を乗り越える行動が続く。難しさを痛感したという文と合わない", "と言ったが最後：「〜たが最後」は「一度〜したら、もう元に戻らない（悪い結果になる）」という意味で、ここでは意味が通らない", ""], "ex": "彼は国内<b>は言うに及ばず</b>、海外でも名の知られた画家だ。"},
"36841_1": {"point": "「〜こととて」は「〜なので」という意味の古風で硬い表現で、理由を表し、後に謝罪や困った気持ちが続くことが多い。「慣れぬこととて」で、田舎の生活に慣れていないので心細くてたまらなかったという理由を表している。", "opts": ["ことなしに：「〜ことなしに」は「〜しないで」という意味で、「慣れぬことなしに」では否定が重なって意味が通らない", "", "とはいえ：「〜とはいえ」は「〜とはいっても」という逆接で、慣れていないことと心細いことの因果関係に合わない", "と思いきや：「〜と思いきや」は予想と反対の結果を表す表現で、「慣れぬと思いきや心細い」では意味が通らない"], "ex": "子どものした<b>こととて</b>、どうかお許しください。"},
"36843_0": {"point": "「欠かせない」は「なくてはならない、必要不可欠な」という意味で、後の名詞を修飾する。「生きていくために」と結びつき、生命を維持するのに不可欠な水として「飲み水」を挙げる文になる。", "opts": ["あらん限りの＝ある限り全部の（あらん限りの力を出す）。「生きていくためにあらん限りの水」では意味が通らない", "あるまじき＝あってはならない。「〜にあるまじき」「〜としてあるまじき」の形で立場に合わない行為を非難する表現で、「生きていくために」には続かない", "", "欠くことはないまでも＝欠くことはないにしても。後に名詞「水」を自然に修飾できず、必要不可欠だという意味も表せない"], "ex": "十分な睡眠は、健康を保つために<b>欠かせない</b>ものだ。"},
"36843_1": {"point": "「〜に限らず」は「〜だけでなく、ほかにも」という意味。後の「文化的な生活を営むためにも」の「も」と呼応し、現代では飲み水だけでなく、文化的な生活のためにも多くの水が必要だという範囲の広がりを表す。", "opts": ["", "に反して＝〜とは反対に（予想に反して）。「飲み水に反して」は意味が通らず、後の「〜にも」とも呼応しない", "にかかわらず＝〜に関係なく（天候にかかわらず）。「晴雨」「有無」など対立を含む語に付くのが普通で、「飲み水」には合わない", "に基づいて＝〜を根拠・基準にして（データに基づいて）。飲み水を根拠にするという意味になり、文脈に合わない"], "ex": "この店は、若者<b>に限らず</b>お年寄りにも人気がある。"},
"36843_2": {"point": "「AあってのB」は「Aがあるからこそ、Bが成り立つ」という意味。直前で、朝起きてから夜寝るまであらゆる場面で水を使っていると述べており、私たちの生活は水があってこそ成り立つとまとめている。", "opts": ["ながらの＝昔のままの、〜の状態のままの（昔ながらの町並み）。「水ながらの生活」という言い方はせず、意味も通らない", "", "において＝〜で（場所・場面）。名詞を修飾するには「における」が必要で、「水において生活」は意味も通らない", "にとって＝〜の立場から見て（私にとって）。名詞を修飾するには「にとっての」が必要で、「水にとって生活」は意味が通らない"], "ex": "健康<b>あっての</b>仕事だから、無理はしないでください。"},
"36846_0": {"point": "「〜にあっては」は「〜という立場・状況においては」という意味の硬い表現。「いま多くの会社においては」と、リーダーとなる人材の不足という問題が起きている場を示している。", "opts": ["", "にもまして＝〜以上に（去年にもまして暑い）。比較の意味になり、会社の現状を述べるこの文に合わない", "に即して＝〜に従って、〜に合わせて（事実に即して）。基準を表す表現で、「多くの会社に即して悩んでいる」は意味が通らない", "につれて＝一方の変化に伴ってもう一方も変化する（時間がたつにつれて）。変化を表す語に付くもので、「会社」には付かない"], "ex": "情報化社会<b>にあっては</b>、正確な情報を見極める力が求められる。"},
"36846_1": {"point": "「〜ことなしに」は「〜しないで」という意味の硬い表現で、本来すべきことをしないまま後のことをする場合に使う。有望な社員に能力開発の機会を与えないまま「人材がいない」と嘆いている、という筆者の批判を表している。", "opts": ["ことないで：「〜ことなく」「〜ことなしに」とは言うが、「ことないで」という形はない", "", "ことなくて：「〜ないで」の意味では「ことなく」の形で使い、「ことなくて」という形はとらない", "ことないか：疑問の形になり、後の「嘆いているからです」に文がつながらない"], "ex": "努力する<b>ことなしに</b>、成功を手に入れることはできない。"},
"36846_2": {"point": "「名詞＋たる（もの）」は「〜という立場にある（者）」という意味の硬い表現で、その立場にふさわしい責任や使命を述べるときに使う。「経営者たるもの」で「経営者という立場にある者」となり、人を育てることがその使命だと述べている。", "opts": ["おる：「いる」の丁重な言い方で、名詞に直接付かない。「経営者おるもの」という言い方はない", "なりの＝〜に応じた、〜にふさわしい程度の（子どもなりの考え）。「経営者なりのものの使命」となり、意味が通らない", "", "ならではの＝〜だけが持つ、〜でなければできない（京都ならではの味）。「経営者ならではのものの使命」となり、意味が通らない"], "ex": "教師<b>たる</b>もの、生徒の手本となるよう行動すべきだ。"},
"36849_0": {"point": "「〜としてあるまじき」は「〜として、あってはならない」という意味で、その立場にふさわしくない行為を強く非難する表現。プロの運転手による飲酒運転への批判なので、「プロとしてあるまじき行為」となる。", "opts": ["あろう：推量や意志を表す形で、「プロとしてあろう行為」では批判の意味にならず、意味も通らない", "", "あるべき＝本来そうあるのが当然の（あるべき姿）。プロにふさわしい行為という肯定的な意味になり、飲酒運転への批判と逆になる", "あるような：「プロとしてあるような行為」は不自然な言い方で、非難の気持ちも表せない"], "ex": "患者を見捨てるなど、医師として<b>あるまじき</b>行為だ。"},
"36849_1": {"point": "「〜をもって」は「〜で、〜によって」という意味で、手段や方法を表す硬い表現。関係当局に対し、取り締まりとともに「罰則のさらなる強化」という手段で飲酒運転に対応してほしいという筆者の要望を表している。", "opts": ["をおして＝困難などを押し切って（病気をおして出席する）。「罰則の強化を押し切って対応する」となり、意味が合わない", "をおいて＝〜以外に（彼をおいて適任者はいない）。後に否定的な表現が続く形で、対応の手段を述べるこの文に合わない", "をもとに＝〜を材料・根拠にして（事実をもとにした小説）。何かを作り出す材料を表し、対応の手段を示すには不自然", ""], "ex": "審査の結果は、書面<b>をもって</b>お知らせいたします。"},
"36941_0": {"point": "「〜まみれ」は、汗・泥・ほこりなど汚いものが表面一面に付いている状態を表す。猛暑の中、スーツ姿のサラリーマンが汗だらけになっている様子なので、「汗まみれ」となり、後の「何か哀れだ」にもつながる。", "opts": ["ずくめ＝〜ばかり、全部〜（黒ずくめ、いいことずくめ）。色や事柄に付く表現で、「汗」には付かない", "", "いたり＝この上なく〜（感激のいたり、若気のいたり）。「感激」「光栄」などの語に付き、「汗」には付かない", "ほうだい＝好きなだけ〜する（食べ放題）、ひどくなるままにする（荒れ放題）。動詞のます形などに付き、「汗」には付かない"], "ex": "子どもたちは泥<b>まみれ</b>になって、グラウンドを走り回った。"},
"36941_1": {"point": "「感情を表す名詞＋にたえない」は「その気持ちを抑えきれないほど強く感じる」という意味の硬い表現（感謝にたえない／同情にたえない）。猛暑の中、営業で歩き回るサラリーマンを思うと、同情せずにはいられないという筆者の気持ちを表している。", "opts": ["にかぎる＝〜が一番いい（夏はビールにかぎる）。「同情するのが一番いい」という意味になり、文脈に合わない", "に値しない＝〜する価値がない（信頼に値しない）。同情する価値がないという意味になり、前の「何か哀れだ」と矛盾する", "に越したことはない＝〜のほうがいい（用心するに越したことはない）。勧めの意味になり、筆者の気持ちを表すこの文に合わない", ""], "ex": "皆様の温かいご支援には、感謝の念<b>にたえません</b>。"},
"36941_2": {"point": "「〜のごとく」は「〜のように」という意味の硬い表現。「誰もが承知のごとく」で「誰もが知っているように」となり、日本がエネルギー資源を輸入に頼っているという周知の事実を導いている。", "opts": ["", "なりに＝〜にふさわしい程度に（私なりに考えた）。「承知のなりに」という形はなく、意味も通らない", "ばかりに＝〜したせいで（悪い結果の原因）（うそをついたばかりに）。「承知の」には付かず、意味も合わない", "かたわら＝〜する一方で、別のことも並行して（仕事のかたわら）。「承知のかたわら」は意味が通らない"], "ex": "ご存じの<b>ごとく</b>、来月から料金が改定されます。"},
"36944_0": {"point": "「〜からなる」は「〜で構成されている」という意味で、全体を作っている要素を示す。自動車に搭載される電子部品が、多様な半導体チップやソフトウェアで構成されていることを表し、「〜からなる電子部品」と名詞を修飾している。", "opts": ["からある＝〜以上もある（10キロからある荷物）。数量の多さを強調する表現で、数量の後に付き、「ソフトウェア」には付かない", "だけする：構成要素を示す働きはなく、「ソフトウェアだけする電子部品」は意味が通らない", "", "だけある＝〜にふさわしい（さすがプロだけある）。評価を表す表現で、部品の構成を述べるこの文に合わない"], "ex": "日本の国会は、衆議院と参議院<b>からなる</b>。"},
"36944_1": {"point": "「〜にともなって」は「一方の変化とともに、それに応じてもう一方の変化も起こる」という意味。電子部品の役割が増大するのと同時に、部品の大規模化や複雑化も進んでいるという連動した変化を表している。", "opts": ["に対して＝〜に向けて、〜とは対照的に。動詞の辞書形には「のに対して」の形で付き、また対比の意味も文脈に合わない", "", "に反して＝〜とは反対に（予想に反して）。「予想」「期待」などに付く表現で、「増大する」には付かず意味も合わない", "について＝〜に関して（話題・対象）。動詞の辞書形には直接付かず、変化の連動も表せない"], "ex": "気温が上がる<b>にともなって</b>、電力の使用量も増えていく。"},
"36946_0": {"point": "「〜と言えばそれまでだ」は「そう言ってしまえば、それで話が終わってしまう」という意味。「時代が変わった」で片付けることもできるが、筆者はそれで済ませず、逆接の「が」の後で親が子供の生活に合わせるべきだと意見を述べている。", "opts": ["最後までだ：「〜と言えば最後までだ」という表現はなく、意味が通らない", "", "それぞれだ＝人や物によって違う（考え方は人それぞれだ）。「時代が変わったと言えばそれぞれだ」は意味が通らない", "極まりない＝この上なく〜だ（失礼極まりない）。な形容詞の語幹などに付く表現で、「と言えば」の後には続かない"], "ex": "運が悪かった<b>と言えばそれまでだ</b>が、準備不足だったことも否定できない。"},
"36946_1": {"point": "「〜と言っても過言ではない」は「〜と言っても言い過ぎではない」という意味で、自分の考えを強く主張するときに使う。早寝早起きの習慣づけこそ子供の健康を守る基本だと、筆者が強調している。", "opts": ["かなわない＝我慢できない、勝てない（暑くてかなわない）。「と言っても」に続かず、意味も合わない", "禁じえない＝（感情を）抑えられない（同情を禁じえない）。「怒り」「涙」などの名詞に「を」で付く形で、「と言っても」には続かない", "", "かかせない＝なくてはならない。「基本と言ってもかかせない」は意味が通らない"], "ex": "この作品は、彼の最高傑作<b>と言っても過言ではない</b>。"},
"36948_0": {"point": "「〜のきわみ」は「この上なく〜だ」という意味で、気持ちや状態の程度が最高であることを表す硬い表現。他の部分はそれほど傷んでいないのに捨てるしかなかったので、「残念のきわみ（非常に残念）」となる。", "opts": ["しまつ＝〜という悪い結果になる（ついには泣き出すしまつだ）。動詞などに付く表現で、「残念のしまつ」という形はない", "あげく＝いろいろ〜した末に（悩んだあげく）。経過を表す語に付く表現で、「残念」には付かない", "いかん＝〜次第（結果いかんでは）。程度の高さは表せず、「残念のいかん」は意味が通らない", ""], "ex": "このような賞をいただき、光栄<b>のきわみ</b>です。"},
"36948_1": {"point": "「〜をふまえて」は「〜を前提・根拠として考えに入れて」という意味。充電池の交換に高い費用がかかったという経験を判断の根拠にして、それ以来乾電池式のかみそりに変えたという流れになる。", "opts": ["に及ばず：「〜には及ばない（〜する必要はない）」や「〜は言うに及ばず（もちろん）」の形で使い、「経験に及ばず」は意味が通らない", "", "のかぎり＝〜の限界まで（力のかぎり）。「力」「声」などに付く表現で、「経験のかぎり」では判断の根拠を表せない", "にわたって＝〜の範囲全体に（三日間にわたって）。期間や範囲を表す語に付き、「経験」には合わない"], "ex": "前回の失敗<b>をふまえて</b>、今回は計画を慎重に立てた。"},
"36948_2": {"point": "「〜だろうに」は「〜だろうのに」という意味で、そうなるはずなのに実際はそうならないという残念な気持ちを表す。小さな部品を交換すれば生き返るはずなのに、修理代が高いために捨ててしまう、という惜しむ気持ちを表している。", "opts": ["", "だけましで＝〜だけでもまだよくて。「生き返るだけましで」では、捨ててしまうのを惜しむ後の内容とつながらない", "も同然で＝ほとんど〜と同じで（新品も同然で）。「生き返るも同然で」では、残念に思う逆接の気持ちが表せない", "までで＝〜だけで、それ以上ではない（今日はここまでで終わり）。「生き返るまでで」は意味が通らない"], "ex": "早く相談してくれれば手伝えた<b>だろうに</b>、彼は一人で抱え込んでしまった。"},
"37041_0": {"point": "「〜のだから」は、誰もが認める事実を理由として示し、後の判断を導く表現。手本となるべき大人が堂々と喫煙しているという事実があるので、未成年に「大人だってやってるだろ」と言われたら言い返せない、という理由を表している。", "opts": ["ものの＝〜けれども（逆接）（買ったものの使っていない）。逆接では、大人の喫煙が言い返せない理由になるという関係を表せない", "ところ＝〜したら（その結果）、〜している場面。「喫煙しているところ」では場面を表すだけで、理由にならない", "ままに＝〜のとおりに、〜に任せて（思うままに）。理由を表せず、意味が通らない", ""], "ex": "自分で決めた<b>のだから</b>、最後まで責任を持ちなさい。"},
"37041_1": {"point": "「〜にとどまらず」は「〜だけで終わらず、さらに範囲が広がる」という意味。あいさつだけでなく、当たり前の日常のことまでできない子が多いと、問題の範囲が広いことを表している。", "opts": ["にむかって＝〜の方向へ、〜を相手に（ゴールにむかって）。「あいさつにむかって」は意味が通らない", "にいたって＝〜という段階になって初めて（事態がここにいたって）。極端な段階を示す表現で、「あいさつ」には合わない", "", "にひきかえ＝〜とは反対に（兄にひきかえ弟は）。二つを対比する表現で、ここは範囲の広がりを述べる文脈であり、合わない"], "ex": "その歌手の人気は国内<b>にとどまらず</b>、アジア各国に広がっている。"},
"37043_0": {"point": "「〜は言うまでもない」は「わざわざ言う必要がないほど当然だ」という意味。悪事を小さいうちにつぶすことの大切さは当然だと述べたうえで、次の「問題は〜」で本当に言いたい点に話を進めている。", "opts": ["", "言うくらいだ：「〜くらいだ」は程度を示す形で、「大切なことは言うくらいだ」は意味が通らない", "言うきらいがある＝〜と言う悪い傾向がある。当然のことだと認める意味にならず、文脈に合わない", "言うはずもない＝言う可能性がない。当然だと認める意味にならず、文脈に合わない"], "ex": "健康が何より大切であることは<b>言うまでもない</b>。"},
"37043_1": {"point": "「〜かいなか（か否か）」は「〜かどうか」という意味の硬い表現。「悪を正す強い意志があるかいなか」と、後の「考えることが出来るかどうか」が並び、問題がこの二点にかかっていると述べている。", "opts": ["", "あるからには＝ある以上は。後に「〜べきだ」などの決意・義務が続く形で、「〜かどうか」と並ぶこの文に合わない", "あってはじめて＝あって、それで初めて〜が成り立つ。条件を表す形で、後の「〜かどうか」と並べられない", "あるかというと＝あるかと言えば。後に「そうではない」などの否定的な答えが続く形で、文脈に合わない"], "ex": "彼が会議に参加する<b>かいなか</b>は、まだわからない。"},
"37043_2": {"point": "「〜にかかっている」は「〜によって決まる、〜次第だ」という意味。問題の解決は、大人に悪を正す意志があるか、子どものことを社会の大人の務めと考えられるかどうか次第だ、という筆者の考えを表している。", "opts": ["あたっている＝当てはまる、的中している。「〜かどうかにあたっている」では「次第だ」という意味にならない", "", "たえない＝（感情を）抑えられない、〜する価値がない。「〜かどうかに」を受けられず、意味が通らない", "かなっている＝条件や道理に合っている（理にかなっている）。「次第だ」という意味にならず、文脈に合わない"], "ex": "試合に勝てるかどうかは、選手たちの努力<b>にかかっている</b>。"},
"37046_0": {"point": "「数量＋にのぼる」は「数や量がそこまで達する」という意味で、その多さを強調する。ゴミ処理費用が30億円という大きな額に達していることを表し、「30億円にのぼるゴミ処理費用」と名詞を修飾している。", "opts": ["かかわる＝関係する（命にかかわる）。「30億円にかかわる」では金額の多さを表せず、意味が合わない", "", "ひかえる＝「試験を明日にひかえる（迫っている）」「外出をひかえる」のように使い、金額の多さは表せない", "わたる＝範囲全体に及ぶ（多岐にわたる、三日間にわたる）。期間や範囲を表す語に付き、金額の多さには使わない"], "ex": "今回の地震による被害額は、100億円<b>にのぼる</b>という。"},
"37046_1": {"point": "「〜ねばならない」は「〜なければならない」の硬い言い方で、義務や必要を表す。ゴミ分別は各家庭の協力にかかっているので、空き缶1個の処理から意識を高く持つべきだという筆者の主張を表している。", "opts": ["", "持たんばかりだ：「〜んばかりだ」は「今にも〜しそうだ」という様子を表し（泣かんばかりの顔）、主張を述べる文に合わない", "持つには及ばない＝持つ必要はない。意識を高く持つ必要がないという意味になり、筆者の主張と逆になる", "持つすべもない＝持つ方法もない。どうしようもないという意味になり、意識を高めるよう求める文脈に合わない"], "ex": "約束した以上、最後までやり遂げ<b>ねばならない</b>。"},
"37048_0": {"point": "「〜はしない」は、動詞のます形に付いて「決して〜ない」と強く否定する表現で、「など」と呼応しやすい。お金を振り込まないと仕事が紹介されないとわかり、「世の中にうまい話など決してない」と実感した場面に合う。", "opts": ["あってやまないのだ：「〜てやまない」は「心から〜し続ける（願ってやまない）」の意で、感情を表す動詞に付き、「ある」には付かない", "あってよさそうだ＝あってもよさそうだ（あるのが当然に思える）。うまい話を否定する文脈と逆になる", "", "あるにかぎるのだ：「〜にかぎる」は「〜が一番いい」という意味で、うまい話を否定する文脈に合わない"], "ex": "一度失った信頼は、簡単には戻り<b>はしない</b>。"},
"37048_1": {"point": "「ところが」は、前の内容から予想されることとは違う結果が起きたことを表す逆接の接続詞。資料を破り捨ててそれで終わったはずなのに、実際には勧誘の電話が多くかかってくるようになったという意外な展開を示している。", "opts": ["ただし：前の内容に補足や例外の条件を付け加える接続詞で、予想外の出来事の発生を表せない", "とはいえ＝そうは言っても。前の内容を一応認めつつ反する判断を述べる表現で、予想外の出来事が起きたことを述べるこの文脈に合わない", "そういうわけで＝そのような理由で（順接）。資料を破り捨てたことが勧誘電話の理由になってしまい、文脈に合わない", ""], "ex": "天気予報では晴れだと言っていた。<b>ところが</b>、昼過ぎから激しい雨が降り出した。"},
"37048_2": {"point": "「〜べくもない」は「〜できるはずもない、とても〜できない」という意味の硬い表現で、「望むべくもない」の形でよく使う。断ると態度を一変させて電話を切る相手なので、電話のマナーなどまったく期待できないという気持ちを表している。", "opts": ["べし＝〜すべきだ（古い言い方）。「望むべし」では、マナーを期待すべきだという意味になり、文脈と逆になる", "べきである＝〜するのが当然だ。マナーを望むのが当然だという意味になり、期待できないという文脈に合わない", "", "べからざる＝〜してはならない、〜できない（欠くべからざる）。名詞を修飾する形で、文末には使えない"], "ex": "今の給料では、都心にマイホームなど望む<b>べくもない</b>。"}
};
